const CLIENT_ID       = '589308993147-rfj3kbaave6uhf3k1ojes3ph2l1pkd1m.apps.googleusercontent.com';
// KV-native: no Drive file
// Same-origin backend: the frontend always talks to whichever backend
// served it. Production (stckrm.com / app.stckrm.com) hits its own
// Caddy → Deno; staging (stckrm-staging.fly.dev) hits its own backend.
// This means staging users can't accidentally write to production data.
const WORKER_URL      = (typeof location !== 'undefined' && location.origin)
  ? location.origin
  : 'https://stckrm.fly.dev';

// ═══════════════════════════════════════════
//  STATE
// ═══════════════════════════════════════════
let items = [];
let settings = { threshold: 20, country: 'GB' };

// ─── Share Access Control (Part A of granular permissions) ────────────────
// User-defined allow / deny lists checked client-side when creating or
// editing a share. The lists live inside `settings` (so they ride the
// existing encrypted-blob sync to every device of the owner). Enforcement
// is forward-only — adding someone to the deny list after a share already
// exists does NOT auto-delete the share; instead the Household Sharing UI
// surfaces a "X is on your deny list — remove their share?" hint.
//
// Mode semantics:
//   'open'      → anyone can be added except entries on deny
//   'allowlist' → only entries on allow can be added (still minus deny)
//
// Server-side enforcement deliberately skipped: the lists protect the
// owner from themselves (accidentally sharing with an ex-partner / former
// cleaner), not from a malicious owner. The server has no security gain
// from enforcing this.
function _ensureShareAccessControl() {
  if (!settings.shareAccessControl) {
    settings.shareAccessControl = { mode: 'open', deny: [], allow: [], updatedAt: '' };
  }
  // Defensive: previous saves may have stored partial shapes
  const sac = settings.shareAccessControl;
  if (sac.mode !== 'open' && sac.mode !== 'allowlist') sac.mode = 'open';
  if (!Array.isArray(sac.deny))  sac.deny  = [];
  if (!Array.isArray(sac.allow)) sac.allow = [];
  return sac;
}

// Normalise an email for comparison — same rule both lists use. Lowercase
// + trimmed. We intentionally don't strip Gmail-style "+suffix" or dots
// because two users on the same Gmail account using different aliases is
// a legitimate use case (e.g. me+work@gmail.com vs me+personal@gmail.com).
function _normEmail(email) {
  return (email || '').trim().toLowerCase();
}

// Check whether `email` is permitted by the current shareAccessControl
// rules. Returns { ok: bool, reason: string | null }. The reason is a
// human-readable string suitable for inline display next to the share-
// create email input.
function checkShareAccessControl(email) {
  const norm = _normEmail(email);
  if (!norm) return { ok: false, reason: 'Enter an email address' };
  const sac = _ensureShareAccessControl();
  const denyHit = sac.deny.map(_normEmail).includes(norm);
  if (denyHit) return { ok: false, reason: `${email} is on your deny list — remove it from settings to share with them.` };
  if (sac.mode === 'allowlist') {
    const allowHit = sac.allow.map(_normEmail).includes(norm);
    if (!allowHit) return { ok: false, reason: `${email} is not on your allow list — add it in settings to share with them.` };
  }
  return { ok: true, reason: null };
}

// ─── Per-record granular permissions (Part B foundation) ──────────────────
// Each record (item / grocery list / reminder / transaction) may carry an
// optional `share` field that OVERRIDES the section-level perm for one or
// more specific SHARES. The field shape is one of:
//
//   undefined / null     → INHERIT — use the section-level perm as-is
//   'private'            → owner only, all shares dropped
//   { deny: [code,...] } → drop these shares; everyone else inherits
//   { allow: [code,...], readOnly: [code,...] }
//                        → only listed shares see it; readOnly forces 'r'
//                          regardless of section perm
//
// `allow` and `readOnly` may coexist on the same record. e.g.:
//   { allow: [spouseShareCode], readOnly: [cleanerShareCode] }
// means everyone on spouse's share can see+edit (if section allows),
// everyone on cleaner's share can only view, no other share sees it.
//
// ── Why share codes, not member email hashes ──
// The plan doc originally specified recipient/member email hashes, but
// that's not implementable with the current crypto: each share has ONE
// encrypted blob that ALL its members decrypt with the same shareKey. We
// can't put a different filtered view in there for each member. The unit
// of access enforceable by the crypto is the share itself — so the
// discriminator is the share code, not the member hash. If you want to
// distinguish two people (e.g. allow spouse but not adult child), put
// them on separate shares.
//
// Resolution rules (per-record ALWAYS wins over section-level):
//   1. Section perm 'none'       → record is dropped (per-record can't
//                                  promote a share that isn't in section)
//   2. record.share absent       → use section perm
//   3. record.share === 'private'→ drop
//   4. record.share.deny present → drop if this share's code is in deny,
//                                  otherwise use section perm
//   5. record.share.allow present→ drop if share code NOT in allow
//   6. record.share.readOnly present + share code in it → force 'r' even
//                                  if section perm is 'rw'
//
// Returns one of: 'rw' | 'r' | 'none'. Callers can treat 'none' as "drop
// this record from this share's payload."
//
// Malformed `share` fields fail-safe to 'none' (drop) and emit a console
// warning so the writer can be fixed. Better to hide a record than to
// accidentally expose one we shouldn't.
function resolveRecordShare(record, shareCode, sectionPerm) {
  // Rule 1: section access denied — record is unreachable regardless
  if (!sectionPerm || sectionPerm === 'none') return 'none';

  // Rule 2: no override — inherit section perm
  const share = record?.share;
  if (share == null) return sectionPerm;

  // Rule 3: explicit private
  if (share === 'private') return 'none';

  // Object form
  if (typeof share === 'object') {
    // Rule 4: deny list — short-circuit if this share is denied
    if (Array.isArray(share.deny)) {
      if (share.deny.includes(shareCode)) return 'none';
    }
    // Rule 5: allow list — only listed shares see it
    if (Array.isArray(share.allow)) {
      if (!share.allow.includes(shareCode)) return 'none';
    }
    // Rule 6: readOnly downgrade — force 'r' even if section says 'rw'
    if (Array.isArray(share.readOnly) && share.readOnly.includes(shareCode)) {
      return 'r';
    }
    // Made it through all object checks — inherit section perm
    return sectionPerm;
  }

  // Anything else (number, string other than 'private', etc.) is malformed
  console.warn('[share] malformed record.share — failing safe to none:', share, 'on record id:', record?.id);
  return 'none';
}

// Filter a section's records to those visible to a specific SHARE. Returns
// a NEW array (does not mutate the original) with each retained record
// optionally annotated with a `_shareEffectivePerm` field that downstream
// guest code can read. Records resolving to 'none' are dropped entirely.
//
// Why annotate the record? Because the guest's local view of a record
// needs to know whether they have 'r' or 'rw' on a per-record basis —
// the section-level perm alone isn't enough once readOnly is in play.
// The annotation is stripped before save on the guest side via
// _scrubGuestRecords below.
function _filterRecordsForShare(records, shareCode, sectionPerm) {
  if (!Array.isArray(records)) return records;
  if (!sectionPerm || sectionPerm === 'none') return [];
  const out = [];
  for (const rec of records) {
    const perm = resolveRecordShare(rec, shareCode, sectionPerm);
    if (perm === 'none') continue;
    // Annotate only if the per-record perm differs from the section perm —
    // saves wire bytes on the common case where it inherits.
    if (perm !== sectionPerm) {
      out.push({ ...rec, _shareEffectivePerm: perm });
    } else {
      out.push(rec);
    }
  }
  return out;
}

// Per-transaction sharing was removed in Pass 2d-rollback. The model
// changed so the unit of share is the budget CATEGORY (and its
// transactions flow with it), not the individual transaction. The
// replacement filter is built in Pass 2e-a — it walks budgetCategories
// to compute an allowed-cat-id Set and filters transactions by
// categoryId membership, not by per-tx share field.

// ── Budget filter (Pass 2e-a) ────────────────────────────────────────────
// Computes the allowed-category-id Set for a given share code and section
// perm, then returns filtered { categories, transactions } for the push
// payload. Uncategorised transactions (categoryId == null) are NEVER
// included — they have no category to share through, so they're always
// owner-private.
//
// Section perm semantics (option C, agreed): 'none' → drop everything.
// 'r' or 'rw' → use per-category share field to decide which cats flow.
// Cats without an override inherit the section perm. Per-category
// overrides ('private' / { allow } / { deny } / { readOnly }) take
// precedence — same rules as the other sections via resolveRecordShare.
//
// Returns: {
//   allowedCatIds: Set<string>,  // for downstream filtering of tombstones, debug
//   categories:    Array,         // filtered category array
//   transactions:  Object,        // {month: {txId: tx}} with non-shared cats dropped
// }
function _filterBudgetForShare(categories, txMap, shareCode, sectionPerm) {
  const empty = { allowedCatIds: new Set(), categories: [], transactions: {} };
  if (!sectionPerm || sectionPerm === 'none') return empty;
  if (!Array.isArray(categories)) return empty;

  // Build the allowed-cat-id Set by walking categories and applying
  // resolveRecordShare per cat. We collect both the id AND a possible
  // per-cat 'r' downgrade for later (so a section-rw share can still
  // see a single category as read-only).
  const allowedCatIds = new Set();
  const filteredCategories = [];
  for (const cat of categories) {
    const perm = resolveRecordShare(cat, shareCode, sectionPerm);
    if (perm === 'none') continue;
    allowedCatIds.add(cat.id);
    // Annotate with _shareEffectivePerm when different from section perm
    // (same pattern as other filtered records — guest's render code can
    // read this to know it's read-only on a per-record basis).
    if (perm !== sectionPerm) {
      filteredCategories.push({ ...cat, _shareEffectivePerm: perm });
    } else {
      filteredCategories.push(cat);
    }
  }

  // Filter transactions to those whose categoryId is in the allowed set.
  // tx.categoryId === null (uncategorised) is always dropped — those have
  // no category to share through, so they stay owner-private.
  const filteredTransactions = {};
  if (txMap && typeof txMap === 'object') {
    for (const [month, bucket] of Object.entries(txMap)) {
      if (!bucket || typeof bucket !== 'object') continue;
      const filteredBucket = {};
      for (const [txId, tx] of Object.entries(bucket)) {
        if (!tx || tx.categoryId == null) continue;        // uncategorised → owner-only
        if (!allowedCatIds.has(tx.categoryId)) continue;   // unshared cat → drop
        filteredBucket[txId] = tx;
      }
      if (Object.keys(filteredBucket).length) filteredTransactions[month] = filteredBucket;
    }
  }

  return {
    allowedCatIds,
    categories:   filteredCategories,
    transactions: filteredTransactions,
  };
}

// Strip owner-only fields (`share`, `_shareEffectivePerm`) from records
// before a GUEST pushes them back to the owner's share blob. Per-record
// perms are an owner-only concept — a guest writing them back would let
// them unilaterally rewrite the owner's sharing policy. Returns a NEW
// array of shallow-cloned records with those fields removed.
function _scrubGuestRecords(records) {
  if (!Array.isArray(records)) return records;
  return records.map(rec => {
    if (!rec || (rec.share === undefined && rec._shareEffectivePerm === undefined)) {
      return rec; // common case — nothing to strip
    }
    const clone = { ...rec };
    delete clone.share;
    delete clone._shareEffectivePerm;
    return clone;
  });
}

// _scrubGuestTransactions was removed in Pass 2d-rollback. Per-tx
// sharing fields no longer exist on transactions, so there's nothing
// to scrub. Pass 2e-a will reintroduce category-membership-based
// guest-write enforcement (a scrub that rejects categories the owner
// doesn't already have, and rejects tx writes against non-shared
// categories) — different from the field-stripping this helper did.

// ── Per-note sharing filter ─────────────────────────────────────────────
// Notes don't sit under a section perm (unlike stock/grocery/reminder/
// budget). The rule for notes is:
//   - Absent or null `share` field           → owner-only (private)
//   - share === 'private'                    → owner-only (explicit)
//   - share is an object with allow[]        → only those shares see it
//
// This is a DIFFERENT default from other record types, which inherit
// section perm when the field is absent. Notes have no section perm to
// inherit from, so absence means "private" rather than "ask the section."
//
// Excludes locked notes (locked-and-shared is incoherent — recipients
// don't have the note password) and trashed notes (deletedAt set —
// recipient should not see what the owner has thrown away).
//
// Returns a NEW array of shallow-cloned note records with the `share`
// field STRIPPED (owner-only; guests must never see who else has access).
// Body is included in full for unlocked notes — locked notes never get
// here because they're filtered out before we even try.
function _filterNotesForShare(notes, shareCode) {
  if (!Array.isArray(notes) || !shareCode) return [];
  const out = [];
  for (const n of notes) {
    if (!n || !n.id) continue;
    if (n.locked) continue;             // never share locked notes
    if (n.deletedAt) continue;          // never share trashed notes
    // Notes-specific resolve: absent → 'none', not section-inherit.
    const sh = n.share;
    let perm = 'none';
    if (sh && sh !== 'private' && typeof sh === 'object') {
      if (Array.isArray(sh.deny) && sh.deny.includes(shareCode)) {
        perm = 'none';
      } else if (Array.isArray(sh.allow) && sh.allow.includes(shareCode)) {
        perm = (Array.isArray(sh.readOnly) && sh.readOnly.includes(shareCode))
          ? 'r' : 'rw';
      }
    }
    if (perm === 'none') continue;
    // Shallow clone, strip share field, annotate effective perm for
    // recipient (same pattern as filtered categories/items).
    const { share: _drop, ...rest } = n;
    void _drop;
    rest._shareEffectivePerm = perm;
    out.push(rest);
  }
  return out;
}

// ── Round 1 debug helper ─────────────────────────────────────────────────
// No UI exists yet for setting per-record perms — Round 1 is foundation
// only. This helper lets you set, clear, and inspect the `share` field on
// any record via the browser console, then trigger a re-push to validate
// the filter end-to-end before Round 2 builds the UI.
//
// Discriminator is the SHARE CODE (not the member email hash) — see
// resolveRecordShare doc-comment for why.
//
// Usage examples:
//   shareDebug.list()                       — print every record's id + share state
//   shareDebug.shares()                     — list every share with its code
//   shareDebug.set('items', 'abc123', 'private')              — hide item from all shares
//   shareDebug.set('items', 'abc123', { allow: ['<shareCode>'] })  — only this share sees it
//   shareDebug.set('items', 'abc123', { readOnly: ['<shareCode>'] }) — share sees but can't edit
//   shareDebug.clear('items', 'abc123')                       — back to inherit
//   shareDebug.push()                       — re-push all shares so changes go live
window.shareDebug = {
  // Inspect: list all records with non-default share state across all sections
  list() {
    const sections = {
      items, groceryItems, groceryLists, reminders, budgetCategories, notes,
    };
    for (const [name, arr] of Object.entries(sections)) {
      if (!Array.isArray(arr)) continue;
      const overridden = arr.filter(r => r.share != null);
      if (!overridden.length) { console.log(`${name}: (none with overrides)`); continue; }
      console.log(`${name}: ${overridden.length} with overrides`);
      overridden.forEach(r => console.log(`  ${r.id}  ${r.name||r.title||'(unnamed)'}  →`, r.share));
    }
    // Per-tx sharing was removed in Pass 2d-rollback. Pass 2e-a adds
    // per-category sharing — set via:
    //   shareDebug.set('budgetCategories', '<catId>', { allow: ['<shareCode>'] })
    // Then shareDebug.push() to propagate.
    // Pass 3a: per-note sharing. Same shape as other sections, but
    // notes default to PRIVATE when the `share` field is absent (no
    // section perm to inherit from). Set via:
    //   shareDebug.set('notes', '<noteId>', { allow: ['<shareCode>'] })
  },

  // Set the share field on a specific record. value can be 'private',
  // null/undefined (to clear), or an object like { allow: [shareCode] }
  set(section, recordId, value) {
    const arr = this._getSectionArr(section);
    if (!arr) { console.warn('unknown section:', section); return; }
    const rec = arr.find(r => r.id === recordId);
    if (!rec) { console.warn('record not found:', recordId); return; }
    if (value == null) {
      delete rec.share;
    } else {
      rec.share = value;
    }
    rec.updatedAt = new Date().toISOString();
    console.log('set', recordId, '→', rec.share || '(cleared)');
    console.log('call shareDebug.push() to send to guests');
  },

  // Convenience clear
  clear(section, recordId) { this.set(section, recordId, null); },

  // List every share target with its share CODE. Use these codes in
  // allow / deny / readOnly arrays — NOT the member email hashes.
  shares() {
    if (!Array.isArray(_shareTargets) || !_shareTargets.length) {
      console.log('No share targets configured yet.');
      return;
    }
    _shareTargets.forEach(t => {
      const memberHashes = Object.keys(t.memberDetails || {});
      const memberCount  = memberHashes.length;
      const md = memberHashes[0] ? t.memberDetails[memberHashes[0]] : null;
      const memberSummary = memberCount === 0
        ? '(no members joined yet)'
        : memberCount === 1
          ? (md?.email || `${memberHashes[0].slice(0,12)}…`)
          : `${memberCount} members`;
      console.log(`${t.name}: code=${t.code}  →  ${memberSummary}`);
    });
  },

  // Trigger a re-push of every share so filter changes take effect
  async push() {
    if (!Array.isArray(_shareTargets) || !_shareTargets.length) {
      console.log('No share targets to push to.');
      return;
    }
    for (const t of _shareTargets) {
      try {
        await pushSharedData(t.code);
        console.log('pushed:', t.name);
      } catch(e) {
        console.warn('push failed for', t.name, e.message);
      }
    }
    console.log('all shares re-pushed');
  },

  // Internal — find the right array for a section name
  _getSectionArr(section) {
    if (section === 'items')             return items;
    if (section === 'groceries')         return groceryItems;
    if (section === 'groceryLists')      return groceryLists;
    if (section === 'reminders')         return reminders;
    if (section === 'budgetCategories')  return budgetCategories;
    if (section === 'notes')             return notes;
    // 'transactions' branch removed in Pass 2d-rollback. Per-tx sharing
    // is gone. Pass 2e uses per-category sharing via 'budgetCategories'.
    return null;
  },
};

let editingId = null;
let loggingId = null;
// ─── Sharing-panel module state ───────────────────────────────────────
// Declared early so registerSharingSection() calls scattered through the
// file (near each editor's code) don't trip the const TDZ. The actual
// module implementation (registerSharingSection, _renderSharingPanel,
// etc.) is declared further down — see "Per-record sharing panel" block.
// Per-section "is the picker expanded?" flag, keyed by section name.
let _sharingExpanded = {};
// Registry of section specs (findRecord / currentId / save / mounts).
// Populated by registerSharingSection() — see the registration calls in
// each section's editor. Pre-declared here (empty) so TDZ never throws.
let _SHARING_SECTIONS = {};
// ─── Bulk select / bulk actions module state (Pass 2a) ────────────────
// Generic multi-select infrastructure shared across Stockroom, Groceries,
// Reminders, and Spends. Each section registers a spec via
// registerBulkSelectSection — see the registration calls near each
// section's editor code. The picker UI / action bar / share-flow are
// shared; section-specific bits (find record, save path, archive
// support) live in the spec.
//
// _bulkSelectActiveSection is the key of the section currently in select
// mode (e.g. 'stock'). null when no section is in select mode. Only one
// section can be in select mode at a time — switching tabs auto-exits.
//
// _bulkSelections is keyed by section name. Each entry is a Set of
// record ids. Lazily created when a section first enters select mode.
let _bulkSelectActiveSection = null;
let _bulkSelections = {};
// Registry of section specs. Populated by registerBulkSelectSection.
let _BULK_SELECT_SECTIONS = {};
let tempStorePrices = []; // also declared in scanner.js; declared here so openAddModal works before scanner.js loads
let activeFilter = 'all';
let activeCadence = 'all';
let activeStore = 'all';
let activeRating = 0;
let currentRating = 0;
let wizardCountry = 'GB';
let compactView = false;
let activeProfile = 'default'; // household profile key

// ── Notes state ───────────────────────────────────────────
// (Notes state moved to notes.js: notes[], _notesFilter, _editingNoteId, _noteUnlocked, _noteColourPickerOpen, _noteUndoStack, _noteRedoStack, _noteBodyDirty, _noteAutoSaveTimer, _noteOtpPending, _sharedNotesIncoming)

// ═══════════════════════════════════════════
//  MODAL HELPERS (defined early — used everywhere)
// ═══════════════════════════════════════════
function openModal(id) {
  const el = document.getElementById(id);
  if (!el) { console.error('openModal: element not found:', id); return; }
  // Hide FAB and done-slide while any modal is open. Use display:none rather
  // than opacity:0 so the FAB can't intercept clicks targeted at the modal
  // (it sits at z-index 1100 vs modal 200–500). updateFab restores it on
  // tab change; closeModal restores it explicitly below.
  const fabBtn = document.getElementById('fab-btn');
  if (fabBtn) { fabBtn.dataset.modalHid = '1'; fabBtn.style.display = 'none'; }
  const fabContainer = document.getElementById('fab-container');
  if (fabContainer) fabContainer.style.display = 'none';
  document.getElementById('grocery-done-slide')?.remove();
  closeFab(true);
  try {
    if (_vtSupported() && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      el.style.viewTransitionName = 'modal-layer';
      document.startViewTransition(() => { el.classList.add('open'); });
    } else {
      el.classList.add('open');
    }
  } catch(e) {
    console.warn('openModal: view transition failed, opening directly', e.message);
    el.classList.add('open');
  }
}
function closeModal(id) {
  if (_vtSupported() && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    const el = document.getElementById(id);
    el.style.viewTransitionName = 'modal-layer';
    document.startViewTransition(() => { el.classList.remove('open'); });
  } else {
    document.getElementById(id).classList.remove('open');
  }
  // Restore FAB visibility if no other modals remain open
  setTimeout(() => {
    const anyOpen = document.querySelector('.modal-backdrop.open, .modal.open');
    if (!anyOpen) {
      const fabBtn = document.getElementById('fab-btn');
      if (fabBtn && fabBtn.dataset.modalHid === '1') {
        // Re-show only if updateFab would normally show it (i.e. we're on a
        // mobile-FAB-eligible view). Letting updateFab do the work is safer
        // than guessing here.
        delete fabBtn.dataset.modalHid;
        if (typeof updateFab === 'function') updateFab(_currentView);
      }
      // Restore done-editing slide if still in grocery edit mode
      if (_currentView === 'grocery' && groceryEditMode) _showGroceryDoneSlide();
    }
  }, 50);
}

// ── _hideFabForCustomOverlay ──────────────────────────────────────────────
// Helper for inline overlays (e.g. _openGroceryListModal) that don't go
// through openModal() but still need the FAB out of the way. Hides the FAB
// when called, then watches `overlayEl` for removal via MutationObserver and
// restores the FAB automatically — so every dismissal path (button click,
// backdrop click, programmatic remove()) is covered without each caller
// having to remember to restore the FAB.
function _hideFabForCustomOverlay(overlayEl) {
  const fabBtn = document.getElementById('fab-btn');
  const fabContainer = document.getElementById('fab-container');
  if (fabBtn) { fabBtn.dataset.overlayHid = '1'; fabBtn.style.display = 'none'; }
  if (fabContainer) fabContainer.style.display = 'none';
  if (typeof closeFab === 'function') closeFab(true);
  // Watch for the overlay element being removed from the DOM. When it goes,
  // hand the FAB back to updateFab() which knows whether the current view
  // should show one.
  if (!overlayEl || !overlayEl.parentNode) return;
  const obs = new MutationObserver(() => {
    if (!document.body.contains(overlayEl)) {
      obs.disconnect();
      const fabBtn2 = document.getElementById('fab-btn');
      if (fabBtn2 && fabBtn2.dataset.overlayHid === '1') {
        delete fabBtn2.dataset.overlayHid;
        if (typeof updateFab === 'function') updateFab(_currentView);
      }
    }
  });
  obs.observe(document.body, { childList: true, subtree: false });
}

// ═══════════════════════════════════════════
//  UTILS
// ═══════════════════════════════════════════
const uid = () => 'id_' + Date.now() + '_' + Math.random().toString(36).slice(2,7);

// ── Lucide icon helper ────────────────────────────────────────────────────
// ic('package')           → small inline icon (16px)
// ic('package','md')      → 18px
// ic('package','lg')      → 20px
// ic('package','xl')      → 24px
// ic('package','tab')     → 22px for nav tabs
function ic(name, size='') {
  const cls = size ? `icon icon-${size}` : 'icon';
  return `<svg class="${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
}
const today = () => new Date().toISOString().split('T')[0];
// ── Unified date formatter ─────────────────────────────────────
// Accepts 'YYYY-MM-DD' or full ISO timestamps. Returns '—' for falsy/invalid input.
// opts.short=true returns day+month only (no year), e.g. "5 Nov".
const fmt = (d, opts = {}) => {
  if (!d) return opts.short ? '' : '—';
  const s = String(d);
  const date = s.length <= 10 ? new Date(s + 'T12:00:00') : new Date(s);
  if (isNaN(date)) return opts.short ? '' : '—';
  const fmtOpts = opts.short
    ? { day: 'numeric', month: 'short' }
    : { day: 'numeric', month: 'short', year: 'numeric' };
  return date.toLocaleDateString('en-GB', fmtOpts);
};
// Alias kept for back-compat — many call sites use fmtDate
const fmtDate = fmt;

function timeAgo(dateStr) {
  if (!dateStr) return '—';
  const days = Math.floor((Date.now() - new Date(dateStr+'T12:00:00')) / MS_PER_DAY);
  if (days === 0) return 'today';
  if (days === 1) return 'yesterday';
  if (days < 7)  return `${days}d ago`;
  if (days < 30) return `${Math.floor(days/7)}w ago`;
  if (days < 365) return `${Math.floor(days/30)}mo ago`;
  return `${Math.floor(days/365)}y ago`;
}

// ── Stock model: daysPerUnit ─────────────────────────────────
// `daysPerUnit` is the canonical per-unit lifetime (e.g. one can of Pepsi
// lasts ~1.3 days). Total supply for N units in stock is daysPerUnit × N.
//
// Legacy items only had `months` (intended as "lifetime of one purchase")
// and `qty` (units in that purchase). The old formula multiplied them,
// producing bad numbers for multi-unit packs (24 cans × "1 month" = 24 months).
// The new model derives daysPerUnit from those legacy fields by treating
// `months` as the lifetime of the whole purchase, then dividing by qty —
// which preserves the user's original intent.
function getDaysPerUnit(item) {
  if (item && typeof item.daysPerUnit === 'number' && item.daysPerUnit > 0) {
    return item.daysPerUnit;
  }
  // Legacy migration: months was intended as "purchase supply",
  // so per-unit lifetime = months × AVG_DAYS_PER_MONTH / qty.
  const months = (item && typeof item.months === 'number') ? item.months : 1;
  const qty    = (item && typeof item.qty    === 'number' && item.qty > 0) ? item.qty : 1;
  const dpu    = (months * AVG_DAYS_PER_MONTH) / qty;
  return dpu > 0 ? dpu : AVG_DAYS_PER_MONTH;
}

// Convenience: total supply (in days) for a freshly-stocked purchase of N units.
function getTotalDaysForUnits(item, units) {
  return getDaysPerUnit(item) * Math.max(0.0001, units || 1);
}

// ── Unit types ─────────────────────────────────────────────────────
// An item is counted in a unit type: countable things (rolls, cans) or
// measured things (kg, litres). The core maths is unchanged — qty and
// months still drive daysPerUnit = (months × 30.5) / qty. unitType only
// affects (a) whether qty/stock-count inputs allow decimals, and (b) the
// labels shown to the user ("3 cans left" instead of "3 units left").
// `decimal: true` types permit fractional quantities; countable types are
// whole-number stepped. `one`/`many` are the singular/plural display words.
// Legacy items without item.unitType default to 'item' everywhere.
const UNIT_TYPES = {
  item:   { label: 'item',   one: 'item',   many: 'items',  decimal: false },
  roll:   { label: 'roll',   one: 'roll',   many: 'rolls',  decimal: false },
  can:    { label: 'can',    one: 'can',    many: 'cans',   decimal: false },
  bottle: { label: 'bottle', one: 'bottle', many: 'bottles',decimal: false },
  pack:   { label: 'pack',   one: 'pack',   many: 'packs',  decimal: false },
  kg:     { label: 'kg',     one: 'kg',     many: 'kg',     decimal: true  },
  g:      { label: 'g',      one: 'g',      many: 'g',      decimal: true  },
  litre:  { label: 'litre',  one: 'litre',  many: 'litres', decimal: true  },
  ml:     { label: 'ml',     one: 'ml',     many: 'ml',     decimal: true  },
};
const UNIT_TYPE_ORDER = ['item','roll','can','bottle','pack','kg','g','litre','ml'];

// Resolve an item's unit type key, defaulting to 'item' for legacy records.
function getUnitType(item) {
  const t = item && item.unitType;
  return (t && UNIT_TYPES[t]) ? t : 'item';
}

// Whether the item's unit type permits fractional quantities (kg, g, litre, ml).
function unitTypeAllowsDecimal(item) {
  return !!UNIT_TYPES[getUnitType(item)].decimal;
}

// Display label for a count of this item's unit. n omitted → bare label.
// unitLabel(item)          → "rolls"  (plural/base label)
// unitLabel(item, 1)       → "roll"
// unitLabel(item, 3)       → "rolls"
// Mass/volume types (kg, ml…) read the same singular and plural.
function unitLabel(item, n) {
  const u = UNIT_TYPES[getUnitType(item)];
  if (n == null) return u.many;
  return n === 1 ? u.one : u.many;
}

// Sync the qty input's stepping/min to the currently-selected unit type.
// Countable types (rolls, cans) → whole numbers; mass/volume → decimals.
// Called when the unit dropdown changes and when the item modal opens.
function applyUnitTypeToQtyInput() {
  const utSel = document.getElementById('f-unit-type');
  const qtyEl = document.getElementById('f-qty');
  if (!utSel || !qtyEl) return;
  const allowsDecimal = !!(UNIT_TYPES[utSel.value] && UNIT_TYPES[utSel.value].decimal);
  if (allowsDecimal) {
    qtyEl.step = '0.1';
    qtyEl.min  = '0.1';
  } else {
    qtyEl.step = '1';
    qtyEl.min  = '1';
    // Round any fractional leftover from a previous decimal unit to whole.
    const v = parseFloat(qtyEl.value);
    if (!isNaN(v) && v % 1 !== 0) qtyEl.value = Math.max(1, Math.round(v));
  }
}

// Same as applyUnitTypeToQtyInput, for the Add-Item wizard's fields.
function applyWizUnitTypeToQtyInput() {
  const utSel = document.getElementById('wiz-unit-type');
  const qtyEl = document.getElementById('wiz-qty');
  if (!utSel || !qtyEl) return;
  const allowsDecimal = !!(UNIT_TYPES[utSel.value] && UNIT_TYPES[utSel.value].decimal);
  if (allowsDecimal) {
    qtyEl.step = '0.1';
    qtyEl.min  = '0.1';
  } else {
    qtyEl.step = '1';
    qtyEl.min  = '1';
    const v = parseFloat(qtyEl.value);
    if (!isNaN(v) && v % 1 !== 0) qtyEl.value = Math.max(1, Math.round(v));
  }
}

function calcStock(item) {
  if (!item.logs || !item.logs.length) return null;
  // Only count delivered (non-pending) logs for stock calculation
  const deliveredLogs = item.logs.filter(l => !l.pendingDelivery);
  if (!deliveredLogs.length) return null;
  const last = deliveredLogs[deliveredLogs.length - 1];

  const dpu = getDaysPerUnit(item);

  // If a manual stock count has been recorded, project from that count
  if (item.stockCount != null && item.stockCountDate) {
    const daysSinceCount  = (Date.now() - new Date(item.stockCountDate+'T12:00:00')) / MS_PER_DAY;
    const unitsRemaining  = item.stockCount;
    const totalDays       = dpu * Math.max(1, unitsRemaining);
    let daysLeft;
    const daysSincePurchase = (Date.now() - new Date(last.date+'T12:00:00')) / MS_PER_DAY;
    const used = (last.qty || 1) - unitsRemaining;
    if (used > 0 && daysSincePurchase > 1) {
      // Learned rate: use actual measured consumption since purchase
      const ratePerDay = used / daysSincePurchase;
      daysLeft = Math.round(Math.max(0, unitsRemaining / ratePerDay));
    } else {
      // Configured rate: use daysPerUnit, decrement by time since count
      daysLeft = Math.round(Math.max(0, dpu * unitsRemaining - daysSinceCount));
    }
    const pct = Math.round(Math.max(0, Math.min(100, (daysLeft / Math.max(1, totalDays)) * 100)));
    return { pct, daysLeft, referenceDate: item.stockCountDate, fromStockCount: true };
  }

  // Default: time-based from purchase / startedUsing date
  const referenceDate = item.startedUsing || last.date;
  const daysSince  = (Date.now() - new Date(referenceDate+'T12:00:00')) / MS_PER_DAY;
  const totalDays  = dpu * (last.qty || 1);
  const daysLeft   = Math.round(Math.max(0, totalDays - daysSince));
  const pct        = totalDays > 0
    ? Math.round(Math.max(0, Math.min(100, (daysLeft / totalDays) * 100)))
    : null;
  return { pct, daysLeft, referenceDate };
}

// Format days-left for display with sanity caps to prevent absurd numbers
// like "5829 days left" appearing on cards.
function formatDaysLeft(daysLeft) {
  if (daysLeft == null || isNaN(daysLeft)) return { num: '?', unit: 'days left', suspect: false };
  if (daysLeft >= 1095) return { num: '3+', unit: 'years left', suspect: true };  // 3+ years suggests model misconfig
  if (daysLeft >= 730)  return { num: '2+', unit: 'years left', suspect: true };
  if (daysLeft >= 365)  return { num: Math.round(daysLeft / AVG_DAYS_PER_MONTH), unit: 'months left', suspect: false };
  if (daysLeft >= 60)   return { num: Math.round(daysLeft / 7), unit: 'weeks left', suspect: false };
  return { num: daysLeft, unit: daysLeft === 1 ? 'day left' : 'days left', suspect: false };
}

// Project how many units are *currently* left, given a stockCount snapshot
// and the elapsed time since that snapshot. Returns null if no count exists.
// Uses learned rate if available (stockCount is below last purchase qty and
// enough time has passed), otherwise falls back to configured daysPerUnit.
function getProjectedUnitsLeft(item) {
  if (!item || item.stockCount == null || !item.stockCountDate) return null;
  const dpu = getDaysPerUnit(item);
  if (dpu <= 0) return item.stockCount;
  const daysSinceCount = (Date.now() - new Date(item.stockCountDate + 'T12:00:00')) / MS_PER_DAY;
  if (daysSinceCount <= 0) return item.stockCount;

  // Try to compute a learned rate from the last delivered purchase
  const deliveredLogs = (item.logs || []).filter(l => !l.pendingDelivery);
  const last = deliveredLogs[deliveredLogs.length - 1];
  let ratePerDay = 1 / dpu; // default: configured rate (units consumed per day)
  if (last && last.qty != null) {
    const daysSincePurchase = (Date.now() - new Date(last.date + 'T12:00:00')) / MS_PER_DAY;
    const used = (last.qty || 1) - item.stockCount;
    if (used > 0 && daysSincePurchase > 1) {
      const learned = used / daysSincePurchase;
      if (learned > 0) ratePerDay = learned;
    }
  }
  const projected = item.stockCount - (ratePerDay * daysSinceCount);
  return Math.max(0, projected);
}

// Format projected unit count for compact card display.
// Examples: 17.3 → "~17", 0.4 → "<1", 0 → "0"
function formatProjectedUnits(projected) {
  if (projected == null || isNaN(projected)) return null;
  if (projected <= 0)    return '0';
  if (projected < 1)     return '<1';
  if (projected < 10)    return `~${projected.toFixed(1).replace(/\.0$/, '')}`;
  return `~${Math.round(projected)}`;
}

const STATUS_COLOR = { critical:'#e85050', warn:'#e8a838', ok:'#4cbb8a', nodata:'#7880a0' };
const STATUS_LABEL = { critical:`<span class='status-dot status-critical'></span> Critical`, warn:`<span class='status-dot status-low'></span> Low`, ok:`<span class='status-dot status-ok'></span> Good`, nodata:`<span class='status-dot status-none'></span> No data` };

// ═══════════════════════════════════════════
//  PERSISTENCE — IndexedDB backed
// ═══════════════════════════════════════════
// Per-user IDB note: each signed-in user has their own IndexedDB
// database (see _setActiveDbForUser). The old user-switch wipe is no
// longer needed — switching users is a name flip, and the in-memory
// state is reset via _resetInMemoryUserState() at the call sites in
// kvStoreSession / kvRestoreSession / kvStorePasskeySession /
// kvRestorePasskeySession / kvSignOut.

async function loadData() {
  // Try IndexedDB first
  let loadedItems    = await dbGet('items',    'items');
  let loadedSettings = await dbGet('settings', 'settings');

  // First-run migration from localStorage
  if (!loadedItems) {
    loadedItems = await migrateFromLocalStorage('stockroom_items', 'items', 'items', v => v);
  }
  if (!loadedSettings) {
    loadedSettings = await migrateFromLocalStorage('stockroom_settings', 'settings', 'settings', v => v);
  }

  if (Array.isArray(loadedItems)) items = loadedItems;
  if (loadedSettings && typeof loadedSettings === 'object') settings = { ...settings, ...loadedSettings };

  // Load change history (synced, capped at 50). Phase 1 of the undo
  // system — runs after items/settings so a freshly-restored history
  // entry can reference items that exist in scope.
  if (typeof loadHistory === 'function') {
    try { await loadHistory(); } catch (e) { console.warn('[boot] loadHistory failed', e); }
  }

  // Apply user's theme preference now that settings are loaded — this
  // re-runs applyTheme with the persisted choice, replacing the early
  // dark-default paint that happened before settings were ready.
  if (typeof applyTheme === 'function') applyTheme();
  // Apply text size scale (Tier 2.3) — same lifecycle as theme.
  if (typeof applyTextScale === 'function') applyTextScale();

  // Backfill localStorage from user settings so early-firing browser events (beforeinstallprompt)
  // also see the dismissed flag without waiting for a network sync
  if (settings._installDismissed) {
    try { localStorage.setItem('stockroom_install_dismissed', '1'); } catch(e) {}
    try { localStorage.setItem('stockroom_ios_banner_dismissed', '1'); } catch(e) {}
  }
  // Hide Amazon banner immediately if previously dismissed (avoid flash)
  if (settings._amazonBannerDismissed) {
    const banner = document.getElementById('amazon-banner-mobile');
    if (banner) banner.style.display = 'none';
  }
  // Apply user's mobile tab choice (defaults to Stockroom/Groceries/
  // Budget if unset). Defined further down in the file but available
  // at call time since this is run from an async boot path. Wrapped
  // defensively so a malformed setting can never block boot.
  try { if (typeof _applyMobileTabLayout === 'function') _applyMobileTabLayout(); } catch(e) { console.warn('[boot] mobile tab layout failed', e); }
}

async function saveData() {
  if (!Array.isArray(items)) { console.error('stockroom: items is not an array, aborting save'); return; }
  await dbPut('items', 'items', items);
  if (activeProfile) await saveCurrentProfile();
  registerBackgroundSync();
  bcPost({ type: 'DATA_CHANGED' });
  // Items can contain replacementReminders — recompute push schedule.
  // Debounced so a flurry of saves coalesces into one sync.
  if (typeof syncReminderPushesDebounced === 'function') syncReminderPushesDebounced();
}

async function saveSettings() {
  settings.threshold      = parseInt(document.getElementById('setting-threshold').value);
  // Country: read from Account & Security select (the canonical visible one); hidden input is a fallback mirror
  settings.country        = (document.getElementById('setting-country-sec') || document.getElementById('setting-country'))?.value || settings.country || 'GB';
  settings.email          = document.getElementById('setting-email').value.trim();
  settings.emailInterval  = parseInt(document.getElementById('setting-email-interval').value);
  settings.emailStartDate = document.getElementById('setting-email-start').value || null;
  settings.emailStartTime = document.getElementById('setting-email-start-time').value || '09:00';
  await dbPut('settings', 'settings', settings);
  updateLastSentUI();
  pushScheduleToWorker();
  scheduleRender('settings-ui', 'sns');
  // Keep Account & Security view in sync if it's visible
  renderAccountSecurity();
}

function _capitaliseFirst(str) {
  if (!str) return '';
  return str.charAt(0).toUpperCase() + str.slice(1);
}

function saveDisplayName(raw) {
  const name = _capitaliseFirst((raw || '').trim());
  settings.displayName = name;
  _saveSettings();
  updateHeaderGreeting();
}

function wizardNameInput(raw) {
  const name = _capitaliseFirst((raw || '').trim());
  settings.displayName = name || undefined;
}

function updateHeaderGreeting() {
  const el = document.getElementById('header-greeting');
  if (!el) return;
  const name = settings.displayName ? _capitaliseFirst(settings.displayName) : '';
  if (name) {
    el.style.display = 'flex';
    el.innerHTML = `Hi, <strong style="color:var(--text);margin-left:3px">${esc(name)}</strong>`;
  } else {
    el.style.display = 'flex';
    el.innerHTML = `Hi, <strong style="color:var(--text);margin-left:3px">there</strong> — <a href="#" onclick="event.preventDefault();openSettingsSection('settings-prefs-body')" style="color:var(--accent);margin-left:4px;font-size:11px">add your name</a>`;
  }
}

// renderAccountSecurity moved to Account & Security section below

function _updateSidebarProfile() {
  const el = document.getElementById('app-nav-profile');
  if (!el) return;
  const name = settings.displayName ? _capitaliseFirst(settings.displayName) : '';
  if (name) {
    el.textContent = 'Hi, ' + name;
    el.style.color = 'var(--muted)';
    el.style.cursor = 'default';
    el.onclick = null;
  } else {
    el.textContent = '';
  }
}

function saveSettingsCountry(val) {
  settings.country = val;
  // Keep both selects in sync
  const main = document.getElementById('setting-country');
  const sec  = document.getElementById('setting-country-sec');
  if (main) main.value = val;
  if (sec)  sec.value  = val;
  _saveSettings();
}

function openSettingsSection(sectionId) {
  const tab = [...document.querySelectorAll('.tab')].find(t => t.textContent.includes('Settings'));
  if (tab) showView('settings', tab);
  setTimeout(() => {
    const el = document.getElementById(sectionId);
    if (el) {
      el.classList.add('open');
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }, 150);
}

async function _saveSettings() {
  // Internal: save settings without triggering UI side effects
  await dbPut('settings', 'settings', settings);
  bcPost({ type: 'SETTINGS_CHANGED' });
}

// Stamp updatedAt on an item whenever it's modified
// ── Field-level timestamps (lightweight CRDT) ────────────
// touchField stamps individual fields in item._fieldTs so mergeItems
// can resolve conflicts at field granularity rather than whole-item LWW.
// Fields with no _fieldTs entry fall back to item-level updatedAt.
function touchField(item, ...fields) {
  const now = new Date().toISOString();
  item.updatedAt = now;
  if (!item._fieldTs) item._fieldTs = {};
  if (fields.length === 0) {
    // No specific fields — stamp the whole item (backwards compat for touchItem callers)
    return;
  }
  fields.forEach(f => { item._fieldTs[f] = now; });
}

// Keep touchItem as an alias for callers that set multiple fields at once
function touchItem(item) { touchField(item); }

// ── Logs union merge ─────────────────────────────────────
// Logs are append-only — merge by ID union, never discard an entry
function mergeLogs(localLogs = [], remoteLogs = []) {
  const byId = new Map();
  // Remote first so local can overwrite (local edits to existing logs win)
  for (const l of remoteLogs) byId.set(l.id, l);
  for (const l of localLogs)  byId.set(l.id, l);
  return Array.from(byId.values()).sort((a, b) => new Date(a.date) - new Date(b.date));
}

// ── Field-level item merge ───────────────────────────────
function mergeItemFields(local, remote) {
  // Start with a shallow copy of local
  const result = { ...local };

  // Fields we track individually — everything except id, updatedAt, _fieldTs, logs
  const SCALAR_FIELDS = [
    'name','category','cadence','qty','months','daysPerUnit','url','store','notes',
    'startedUsing','rating','imageUrl','storePrices','expiry',
    'thresholdOverride','replacementInterval','replacementUnit',
    'lastReplaced','ordered','orderedAt','quickAdded','tags',
    'subscribeAndSave','stockCount','stockCountDate',
  ];

  const localTs  = local._fieldTs  || {};
  const remoteTs = remote._fieldTs || {};
  const itemLocalTime  = local.updatedAt  ? new Date(local.updatedAt).getTime()  : 0;
  const itemRemoteTime = remote.updatedAt ? new Date(remote.updatedAt).getTime() : 0;

  for (const field of SCALAR_FIELDS) {
    if (!(field in remote)) continue; // remote doesn't have this field — keep local
    const lt = localTs[field]  ? new Date(localTs[field]).getTime()  : itemLocalTime;
    const rt = remoteTs[field] ? new Date(remoteTs[field]).getTime() : itemRemoteTime;
    if (rt > lt) result[field] = remote[field];
  }

  // Logs: union merge by ID
  result.logs = mergeLogs(local.logs, remote.logs);

  // Merge _fieldTs — keep the newest timestamp per field
  result._fieldTs = { ...remoteTs, ...localTs };
  for (const f of Object.keys(remoteTs)) {
    if (!localTs[f] || new Date(remoteTs[f]) > new Date(localTs[f])) {
      result._fieldTs[f] = remoteTs[f];
    }
  }

  // updatedAt = newest of the two
  result.updatedAt = itemLocalTime >= itemRemoteTime ? local.updatedAt : remote.updatedAt;

  return result;
}

// ── Grocery tombstones — tracks deleted grocery item IDs so they aren't re-added on sync
async function loadGroceryDeletedIds() {
  try {
    const stored = await dbGet('groceryDeletedIds', 'groceryDeletedIds');
    return new Set(Array.isArray(stored) ? stored : []);
  } catch(e) { return new Set(); }
}
async function addGroceryTombstone(id) {
  try {
    const set = await loadGroceryDeletedIds();
    set.add(id);
    // Keep max 500 tombstones; prune oldest if over limit
    const arr = [...set];
    const trimmed = arr.slice(-500);
    await dbPut('groceryDeletedIds', 'groceryDeletedIds', trimmed);
  } catch(e) {}
}

// ── Reminder tombstones — tracks deleted standalone reminder IDs so they
// aren't re-added on next sync (item-linked reminders are tracked via the
// item's own replacementReminders array and don't need this).
async function loadReminderDeletedIds() {
  try {
    const stored = await dbGet('reminderDeletedIds', 'reminderDeletedIds');
    return new Set(Array.isArray(stored) ? stored : []);
  } catch(e) { return new Set(); }
}
async function addReminderTombstone(id) {
  try {
    const set = await loadReminderDeletedIds();
    set.add(id);
    const arr = [...set];
    const trimmed = arr.slice(-500);
    await dbPut('reminderDeletedIds', 'reminderDeletedIds', trimmed);
  } catch(e) {}
}

// ── Grocery list tombstones ──────────────────────────────────────────
// Without these, deleting a list locally hard-removes it but the next
// pull restores it from the remote payload (the items get filtered by
// item-level _deletedAt, but the list itself has no tombstone).
async function loadGroceryListDeletedIds() {
  try {
    const stored = await dbGet('groceryLists', '_deletedIds');
    return new Set(Array.isArray(stored) ? stored : []);
  } catch(e) { return new Set(); }
}
async function addGroceryListTombstone(id) {
  try {
    const set = await loadGroceryListDeletedIds();
    set.add(id);
    const arr = [...set].slice(-500);
    await dbPut('groceryLists', '_deletedIds', arr);
  } catch(e) {}
}

async function loadDeletedIds() {
  const stored = await dbGet('deletedIds', 'deletedIds');
  if (stored) return new Set(stored);
  // Migration from localStorage
  try {
    const raw = localStorage.getItem('stockroom_deleted_ids');
    if (raw) {
      const set = new Set(JSON.parse(raw));
      await saveDeletedIds(set);
      localStorage.removeItem('stockroom_deleted_ids');
      return set;
    }
  } catch(e) {}
  return new Set();
}
async function saveDeletedIds(set) {
  await dbPut('deletedIds', 'deletedIds', [...set]);
}
async function addTombstone(id) {
  const set = await loadDeletedIds();
  set.add(id);
  await saveDeletedIds(set);
}
async function removeTombstone(id) {
  const set = await loadDeletedIds();
  set.delete(id);
  await saveDeletedIds(set);
}

// ═══════════════════════════════════════════
//  RECYCLE BIN — soft-delete helpers
// ═══════════════════════════════════════════
// Items, grocery items, and standalone reminders use _deletedAt as the
// soft-delete marker. After 30 days a one-time purge sweep at app start
// hard-removes them and writes a tombstone (so sync can't resurrect them).

const RECYCLE_BIN_DAYS = 30;
// ── Time constants ────────────────────────────────────────────
// MS_PER_DAY is the canonical milliseconds-in-a-day value used throughout
// the date math (item age, recycle-bin expiry, sync intervals, etc).
// AVG_DAYS_PER_MONTH is the simple AVG_DAYS_PER_MONTH approximation used to convert
// per-month rates to per-day rates (and vice versa) for stock-burn-down
// calculations. Not calendar-accurate but consistent across the app.
const MS_PER_DAY          = 86400000;
const AVG_DAYS_PER_MONTH  = 30.5;
const RECYCLE_BIN_MS   = RECYCLE_BIN_DAYS * MS_PER_DAY;

function _isInRecycleBin(obj) {
  return !!(obj && obj._deletedAt);
}

function _daysLeftInBin(obj) {
  if (!obj?._deletedAt) return null;
  const elapsed = Date.now() - new Date(obj._deletedAt).getTime();
  return Math.max(0, RECYCLE_BIN_DAYS - Math.floor(elapsed / MS_PER_DAY));
}

function _expiredFromBin(obj) {
  if (!obj?._deletedAt) return false;
  return (Date.now() - new Date(obj._deletedAt).getTime()) >= RECYCLE_BIN_MS;
}

// ── Collapsible recycle-bin header ──────────────────────────────────
// Returns the HTML for a header that toggles the bin section between
// collapsed (just the title) and expanded (subtitle + rows). State is
// persisted per-key in localStorage. Default is collapsed — the bin's
// purpose is just to advertise its existence; users open it on demand.
function _binCollapseKey(key)   { return `stockroom_bin_collapsed_${key}`; }
function _isBinCollapsed(key)   {
  // Default collapsed when no preference stored.
  const v = localStorage.getItem(_binCollapseKey(key));
  return v === null ? true : v === '1';
}
function _toggleBinCollapsed(key) {
  const next = !_isBinCollapsed(key);
  localStorage.setItem(_binCollapseKey(key), next ? '1' : '0');
  // Find the .recycle-bin-section that wraps this header and toggle its class
  const section = document.querySelector(`[data-bin-key="${CSS.escape(key)}"]`);
  if (section) section.classList.toggle('recycle-bin-collapsed', next);
}
// Builds the header markup used by every recycle bin. `titleHTML` is the
// caption (e.g. "Recently Deleted" plus a count chip). `actionHTML` is
// the right-hand action button (e.g. an Empty button) — pass '' if none.
function _renderBinHeader(key, titleHTML, actionHTML) {
  return `<div class="recycle-bin-header" onclick="_toggleBinCollapsed('${key}')">
      <div class="recycle-bin-header-left">
        <span class="recycle-bin-chevron"><svg class="icon" aria-hidden="true"><use href="#i-chevron-down"></use></svg></span>
        ${titleHTML}
      </div>
      ${actionHTML ? `<div onclick="event.stopPropagation()">${actionHTML}</div>` : ''}
    </div>`;
}

// One-time hint after first soft-delete in each section, so users know
// where deleted things go. Stored in localStorage so it persists.
function _maybeShowBinHint(section) {
  const key = `stockroom_bin_hint_${section}`;
  if (localStorage.getItem(key)) return;
  localStorage.setItem(key, '1');
  const where = {
    items: 'the bottom of the Stockroom view',
    groceries: 'the bottom of the Groceries view',
    reminders: 'the bottom of the Reminders view',
  }[section] || 'the Recently Deleted section';
  toast(`Tip: deleted things sit in ${where} for 30 days`);
}

// ═══════════════════════════════════════════════════════════════════════════
//  CHANGE HISTORY — Phase 1: Foundation + Stockroom items
//
//  Two related but distinct data structures:
//
//  1. _history[]  — SYNCED, persisted, capped at 50 entries. The audit
//     trail visible in Settings → History. Each entry has a full
//     before/after JSON snapshot of the affected record so restores
//     work even if the record was hard-deleted. Synced across devices.
//
//  2. _undoStack[] / _redoStack[] — LOCAL ONLY, in-memory. The Cmd+Z
//     stacks. Hold the same kinds of entries as _history but with
//     bound inverse functions. Reset on page reload. Per-device by
//     design — Cmd+Z reflects "what I just did on THIS device".
//
//  Phase 1 instruments only Stockroom item actions. Subsequent phases
//  add notes, reminders, groceries, budget. Each instrumented action
//  calls historyRecord() with { type, domain, recordId, summary,
//  before, after, undo, redo }. The system handles toast UI, stack
//  management, persistence, and sync.
// ═══════════════════════════════════════════════════════════════════════════

const HISTORY_CAP = 50;

let _history = [];              // synced; loaded by loadHistory()
let _undoStack = [];            // local; in-memory only
let _redoStack = [];            // local; in-memory only
let _historyDirty = false;      // mirrors _isKVDirty pattern for backup cron
let _historyLastPushTs = 0;     // for debounce (prevent storms)

// Suppress flag — set true when a restore/undo/redo is in progress so the
// re-application doesn't itself get logged as a new history entry, which
// would create a feedback loop. Stack functions all check this.
let _historyApplying = false;

// Domain → human label map used by the history page.
const HISTORY_DOMAIN_LABELS = {
  item:       'Stockroom item',
  note:       'Note',
  reminder:   'Reminder',
  groceryItem:'Grocery item',
  groceryList:'Grocery list',
  bill:       'Bill',
  budgetCategory:'Budget category',
  budgetAccount: 'Budget account',
  transaction:'Transaction',
  incomeTemplate:'Income template',
  incomeEntry:'Income entry',
};

// Action type → past-tense verb used in the summary line.
const HISTORY_VERBS = {
  create:  'created',
  edit:    'edited',
  delete:  'deleted',           // soft-delete (recycle bin)
  restore: 'restored',          // out of recycle bin
  purge:   'permanently deleted',
  archive: 'archived',
  unarchive: 'unarchived',
  order:   'marked ordered',
  unorder: 'unmarked ordered',
  rename:  'renamed',
};

// Build a summary line. Pure-functional; never throws. The summary is
// what shows on the history page row above the JSON detail toggle.
function _historySummary(entry) {
  const domain = HISTORY_DOMAIN_LABELS[entry.domain] || entry.domain;
  const verb   = HISTORY_VERBS[entry.type] || entry.type;
  const name   = entry.recordName || '(unnamed)';
  return `${domain} ${verb}: ${name}`;
}

// Push a new history entry. This is the single entry point all
// instrumented actions call. Handles:
//   - capping at HISTORY_CAP (FIFO eviction of oldest)
//   - timestamps + ids
//   - dirty flag for persistence
//   - both stacks: synced history + local undo
//   - debounce (skip if identical entry was pushed <500ms ago — e.g.
//     a double-click on the same button)
//   - suppression during undo/redo to prevent feedback loops
//
// Caller provides:
//   type:       'create' | 'edit' | 'delete' | 'restore' | 'order' | ...
//   domain:     'item' | 'note' | 'reminder' | ...
//   recordId:   id of the affected record (so duplicate detect can work)
//   recordName: human name for the summary (e.g. item.name)
//   before:     full JSON snapshot of the record pre-change (or null if create)
//   after:      full JSON snapshot of the record post-change (or null if delete)
//   undo:       function that reverses the change. Called with no args.
//               Should be idempotent if possible. May be async.
//   redo:       function that re-applies the change. May be async.
function historyRecord({ type, domain, recordId, recordName, before, after, undo, redo }) {
  if (_historyApplying) return null;  // suppress during undo/redo flow

  const now = new Date().toISOString();
  const entry = {
    id:         uid(),
    type, domain, recordId, recordName,
    before:     before ? JSON.parse(JSON.stringify(before)) : null,
    after:      after  ? JSON.parse(JSON.stringify(after))  : null,
    at:         now,
    // device identifier — helps later if we want "From iPhone" labels
    deviceId:   _deviceIdShort(),
  };

  // Debounce: drop identical recent pushes (same record + type within 500ms)
  // to swallow accidental double-fires from the UI.
  const lastEntry = _history[_history.length - 1];
  const sinceLast = Date.now() - _historyLastPushTs;
  if (lastEntry
      && lastEntry.type === type
      && lastEntry.domain === domain
      && lastEntry.recordId === recordId
      && sinceLast < 500) {
    return lastEntry; // collapse into prior entry
  }
  _historyLastPushTs = Date.now();

  // Append to synced history, FIFO-cap
  _history.push(entry);
  while (_history.length > HISTORY_CAP) _history.shift();

  // Append to local undo stack with bound inverses, also FIFO-cap.
  // Doing it in two writes keeps the synced history clean (no functions
  // in it) and the undo stack rich (closures bound to current scope).
  _undoStack.push({ ...entry, undo: undo || null, redo: redo || null });
  while (_undoStack.length > HISTORY_CAP) _undoStack.shift();
  // A fresh user action invalidates the redo branch — same behaviour as
  // browser/editor undo stacks.
  _redoStack.length = 0;

  _historyDirty = true;
  if (typeof markKVDirty === 'function') {
    try { markKVDirty(); } catch (_) {}
  }
  // Persist asynchronously — don't block the action's callsite.
  setTimeout(() => { saveHistory().catch(() => {}); }, 0);
  return entry;
}

// Persist _history to KV. Mirrors saveBudgetLocal etc.
async function saveHistory() {
  if (typeof dbPut !== 'function') return;
  try {
    await dbPut('history', 'history', _history);
    _historyDirty = false;
  } catch (e) {
    console.warn('[history] save failed', e);
  }
}

// Load _history from KV at boot. Called from the data-load path.
async function loadHistory() {
  if (typeof dbGet !== 'function') return;
  try {
    const stored = await dbGet('history', 'history');
    // Same fix as loadNotifications — clear on empty so a previous
    // session's history can't bleed into a new profile or demo.
    _history = Array.isArray(stored) ? stored.slice(-HISTORY_CAP) : [];
  } catch (e) {
    console.warn('[history] load failed', e);
    _history = [];
  }
}

// Sync merge — called from the existing sync path. Union by entry id,
// sort by `at`, then cap at HISTORY_CAP keeping the newest entries.
// Conservative: entries without an `id` (shouldn't happen) are dropped.
function mergeHistory(localList = [], remoteList = []) {
  const byId = new Map();
  for (const e of remoteList) { if (e && e.id) byId.set(e.id, e); }
  for (const e of localList)  { if (e && e.id) byId.set(e.id, e); } // local wins on tie
  const merged = [...byId.values()];
  merged.sort((a, b) => (a.at || '') < (b.at || '') ? -1 : 1);
  return merged.slice(-HISTORY_CAP);
}

// Apply undo from the top of _undoStack. Idempotent against an empty
// stack. Pops the entry onto _redoStack on success. Marks _historyApplying
// for the duration so the underlying mutation doesn't double-log.
async function undoLastAction() {
  if (!_undoStack.length) {
    if (typeof toast === 'function') toast('Nothing to undo');
    return;
  }
  const entry = _undoStack.pop();
  if (!entry.undo) {
    // No inverse bound — drop without applying. Tell the user.
    if (typeof toast === 'function') toast('Cannot undo this action');
    return;
  }
  _historyApplying = true;
  try {
    await entry.undo();
    _redoStack.push(entry);
    if (typeof toast === 'function') toast(`Undid: ${_historySummary(entry)}`);
  } catch (e) {
    console.warn('[history] undo failed', e);
    if (typeof toast === 'function') toast('Undo failed');
    // Put it back so the user can try again, or it stays available on
    // the next Cmd+Z. Don't push to redo.
    _undoStack.push(entry);
  } finally {
    _historyApplying = false;
  }
}

// Apply redo from the top of _redoStack. Symmetric with undoLastAction.
async function redoLastAction() {
  if (!_redoStack.length) {
    if (typeof toast === 'function') toast('Nothing to redo');
    return;
  }
  const entry = _redoStack.pop();
  if (!entry.redo) {
    if (typeof toast === 'function') toast('Cannot redo this action');
    return;
  }
  _historyApplying = true;
  try {
    await entry.redo();
    _undoStack.push(entry);
    if (typeof toast === 'function') toast(`Redid: ${_historySummary(entry)}`);
  } catch (e) {
    console.warn('[history] redo failed', e);
    if (typeof toast === 'function') toast('Redo failed');
    _redoStack.push(entry);
  } finally {
    _historyApplying = false;
  }
}

// Restore from a history entry (Settings → History page button). Different
// from undoLastAction because it operates on a SPECIFIC entry, not the
// stack top. Uses entry.before/after JSON to reconstruct the record
// rather than a bound function — bound functions don't survive a sync /
// reload, but the JSON snapshots do.
//
// Returns true on success, false otherwise. Toasts a message either way.
async function restoreFromHistory(entryId) {
  const idx = _history.findIndex(e => e.id === entryId);
  if (idx < 0) { if (typeof toast === 'function') toast('History entry not found'); return false; }
  const entry = _history[idx];

  _historyApplying = true;
  let ok = false;
  try {
    ok = await _applyRestoreFromSnapshot(entry);
  } catch (e) {
    console.warn('[history] restore failed', e);
  } finally {
    _historyApplying = false;
  }

  if (ok) {
    // Restoration itself is a new action — log it as such so the user
    // can undo the restore if they hit it by mistake. The new entry
    // doesn't carry bound inverses (the snapshot path lives on _history,
    // not _undoStack), but a Cmd+Z right after a restore can't help us
    // anyway because the in-memory stacks don't know about it. The
    // history page will show both rows.
    historyRecord({
      type: 'restore',
      domain: entry.domain,
      recordId: entry.recordId,
      recordName: entry.recordName,
      before: null,
      after: entry.before || entry.after || null,
      undo: null,
      redo: null,
    });
    if (typeof toast === 'function') toast(`Restored: ${_historySummary(entry)}`);
    if (typeof scheduleRender === 'function') scheduleRender('grid', 'dashboard', 'shopping', 'notes', 'reminders', 'grocery');
  } else {
    if (typeof toast === 'function') toast('Restore failed — record may already be live');
  }
  return ok;
}

// Pure data restore from a snapshot. Phase 1 implements item-domain
// only. Returns true if it applied a change, false otherwise.
async function _applyRestoreFromSnapshot(entry) {
  if (entry.domain !== 'item') return false;

  // Decide whether to restore `before` (undo a create/edit) or `after`
  // (redo a deletion's removed record). The right interpretation:
  //   - For 'delete' / 'purge': restore the BEFORE snapshot (the record
  //     as it was before deletion). Use before, fall back to after.
  //   - For 'create': the user is asking us to UNDO the create →
  //     remove the record. Set _deletedAt.
  //   - For 'edit' / 'archive' / 'order' / etc.: restore the BEFORE
  //     snapshot (the record as it was pre-change).
  //
  // We never re-apply 'after' directly because that's just "redo what
  // we already did" which makes no sense as a restore action.

  const snap = entry.before || entry.after;
  if (!snap || !snap.id) return false;

  if (entry.type === 'create') {
    // Undo a create → soft-delete the record if it still exists.
    const existing = items.find(i => i.id === snap.id);
    if (!existing) return true; // already gone — nothing to do
    existing._deletedAt = new Date().toISOString();
    if (typeof touchField === 'function') touchField(existing, '_deletedAt');
    await saveData();
    if (typeof _syncQueue !== 'undefined' && _syncQueue && _syncQueue.enqueue) _syncQueue.enqueue();
    return true;
  }

  // delete / purge / edit / archive / order / etc. → write snap back
  const existingIdx = items.findIndex(i => i.id === snap.id);

  // If the record exists (e.g. it was edited and we're rolling back),
  // overwrite it with the snapshot. Bump updatedAt so the restore beats
  // any in-flight sync deletion.
  const restored = { ...snap, updatedAt: new Date().toISOString() };
  delete restored._deletedAt; // clear any soft-delete from the snapshot
  if (existingIdx >= 0) {
    items[existingIdx] = restored;
  } else {
    items.push(restored);
  }
  // Remove from tombstones (if present) so a permanently-deleted record
  // doesn't get re-removed on the next sync. The new updatedAt will
  // beat the tombstone regardless, but cleaning up is tidier.
  if (typeof removeTombstone === 'function') {
    try { await removeTombstone(snap.id); } catch (_) {}
  }
  if (typeof touchItem === 'function') touchItem(restored);
  await saveData();
  if (typeof _syncQueue !== 'undefined' && _syncQueue && _syncQueue.enqueue) _syncQueue.enqueue();
  return true;
}

// Show a toast with an Undo button. Wraps toastAction so the rest of
// the codebase doesn't need to know about the undo machinery — call
// this from any instrumented action to give the user a one-tap undo.
// The button calls undoLastAction which pops the top of _undoStack —
// works as long as no other action has been recorded in between.
function toastWithUndo(msg) {
  if (typeof toastAction !== 'function') {
    if (typeof toast === 'function') toast(msg);
    return;
  }
  toastAction(msg, {
    label: 'Undo',
    onclick: () => { undoLastAction().catch(() => {}); },
  });
}

// ── History page rendering (Settings → Change History) ────────────────
// Renders the synced _history list into #history-page-body. Each row
// shows the summary, timestamp, device hint, and a Restore button.
// Tapping a row toggles the full before/after JSON snapshot detail.
// Renders newest-first so the user sees their most recent change at
// the top. Renders an empty-state when there's nothing to show.
function renderHistoryPage() {
  const body = document.getElementById('history-page-body');
  if (!body) return;

  if (!_history.length) {
    body.innerHTML = '<div style="padding:14px;color:var(--muted);font-size:13px;text-align:center;background:var(--surface2);border:1px solid var(--border);border-radius:8px">No changes recorded yet.</div>';
    return;
  }

  // Reverse a copy so we render newest first
  const entries = [..._history].reverse();
  body.innerHTML = entries.map(e => _historyRowHTML(e)).join('');
}

function _historyRowHTML(entry) {
  const safeId = (typeof esc === 'function') ? esc(entry.id) : entry.id;
  const summary = _historySummary(entry);
  const safeSummary = (typeof esc === 'function') ? esc(summary) : summary;
  // Friendly date — locale-aware date + time
  let when = '';
  try { when = new Date(entry.at).toLocaleString(); } catch (_) { when = entry.at || ''; }
  const device = entry.deviceId ? `<span class="history-row-device" title="Device fingerprint">on ${esc(entry.deviceId)}</span>` : '';

  // Pre-serialise the before/after JSON for the detail panel. Big snapshots
  // get scrolled. Always pretty-print so the user can read it.
  const beforeJson = entry.before ? JSON.stringify(entry.before, null, 2) : null;
  const afterJson  = entry.after  ? JSON.stringify(entry.after,  null, 2) : null;
  const detailHTML = `
    <div class="history-row-detail" style="display:none">
      ${beforeJson ? `<div class="history-detail-block">
        <div class="history-detail-label">Before</div>
        <pre class="history-detail-json">${esc(beforeJson)}</pre>
      </div>` : ''}
      ${afterJson ? `<div class="history-detail-block">
        <div class="history-detail-label">After</div>
        <pre class="history-detail-json">${esc(afterJson)}</pre>
      </div>` : ''}
      ${(!beforeJson && !afterJson) ? `<div class="history-detail-empty">No snapshot data captured.</div>` : ''}
    </div>`;

  // Restorable types: anything where a snapshot exists. Skip 'restore'
  // entries themselves (would loop).
  const restorable = (entry.type !== 'restore') && !!(entry.before || entry.after);
  const restoreBtn = restorable
    ? `<button class="btn btn-ghost btn-sm history-row-restore" onclick="event.stopPropagation();restoreFromHistory('${safeId}')">
         <svg class="icon" aria-hidden="true"><use href="#i-rotate-ccw"></use></svg> Restore
       </button>`
    : '';

  return `<div class="history-row" data-id="${safeId}" onclick="_toggleHistoryRow('${safeId}')">
    <div class="history-row-head">
      <div class="history-row-summary">${safeSummary}</div>
      ${restoreBtn}
    </div>
    <div class="history-row-meta">${esc(when)} ${device}</div>
    ${detailHTML}
  </div>`;
}

// Toggle the detail panel inside a history row. The row itself is
// clickable; the Restore button stops propagation so it doesn't toggle.
function _toggleHistoryRow(entryId) {
  const row = document.querySelector(`.history-row[data-id="${entryId}"]`);
  if (!row) return;
  const detail = row.querySelector('.history-row-detail');
  if (!detail) return;
  const open = detail.style.display !== 'none';
  detail.style.display = open ? 'none' : '';
  row.classList.toggle('is-expanded', !open);
}

// Confirmation dialog for clearing all history. Local AND synced — the
// user has to mean it. Pushes nothing to history afterwards (the clear
// would log itself otherwise, immediately re-populating it).
async function _confirmClearHistory() {
  if (!confirm(
    `Clear all change history?\n\n` +
    `This removes all ${_history.length} history entries from this device and from sync. ` +
    `Recent changes won't be restorable from the history page after this. ` +
    `Cmd+Z undo for the current session will continue to work.`
  )) return;
  _history = [];
  _historyDirty = true;
  if (typeof markKVDirty === 'function') { try { markKVDirty(); } catch (_) {} }
  try { await saveHistory(); } catch (_) {}
  if (typeof _syncQueue !== 'undefined' && _syncQueue && _syncQueue.enqueue) _syncQueue.enqueue();
  renderHistoryPage();
  if (typeof toast === 'function') toast('History cleared');
}

// Short device identifier shown alongside history entries. Uses the
// existing deviceId scheme if available; falls back to a short hash of
// userAgent for older sessions. Not a security feature — purely for
// helping the user understand "this happened on iPhone vs laptop".
function _deviceIdShort() {
  try {
    const full = (typeof window !== 'undefined' && window._deviceId) ? String(window._deviceId) : '';
    if (full) return full.slice(0, 6);
  } catch (_) {}
  try {
    const ua = (typeof navigator !== 'undefined') ? (navigator.userAgent || '') : '';
    let h = 0;
    for (let i = 0; i < ua.length; i++) h = ((h << 5) - h + ua.charCodeAt(i)) | 0;
    return Math.abs(h).toString(36).slice(0, 6);
  } catch (_) {
    return 'unknown';
  }
}

// Keyboard handler for Cmd+Z / Cmd+Shift+Z (Ctrl on Win/Linux). Skips
// when focus is in a text-editing context (input, textarea, contenteditable)
// because those want native browser undo. The Stockroom grid, Notes list,
// Budget tabs — none of those have native undo, so they get ours.
function _onHistoryKeydown(e) {
  // Ignore when modifier mismatched
  const isUndoCombo = (e.key === 'z' || e.key === 'Z') && (e.metaKey || e.ctrlKey);
  if (!isUndoCombo) return;
  // Defer to native undo when typing in a text field
  const t = e.target;
  if (t) {
    const tag = (t.tagName || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || t.isContentEditable) return;
  }
  e.preventDefault();
  if (e.shiftKey) {
    redoLastAction().catch(() => {});
  } else {
    undoLastAction().catch(() => {});
  }
}
if (typeof document !== 'undefined') {
  document.addEventListener('keydown', _onHistoryKeydown);
}

// Preserve local soft-deletes when applying a wholesale remote replacement.
// The grocery / reminders sync code paths replace the whole array with the
// remote on `remoteWins`, but the user may have just soft-deleted items
// that haven't been pushed yet. This merges the remote list with any local
// `_deletedAt` markers so freshly deleted items don't resurrect on pull.
//
// Returns a new array of items derived from `remote`, with `_deletedAt`
// (and updatedAt) carried over from any matching local item that was in
// the recycle bin.
function _preserveLocalDeletes(remote, local) {
  if (!Array.isArray(remote)) return remote;
  if (!Array.isArray(local) || !local.length) return remote;
  const localDeleted = new Map();
  for (const it of local) {
    if (it && it._deletedAt) {
      // Keep the more recent updatedAt of the two (local edit wins)
      localDeleted.set(it.id, { _deletedAt: it._deletedAt, updatedAt: it.updatedAt });
    }
  }
  if (!localDeleted.size) return remote;
  return remote.map(it => {
    const ld = localDeleted.get(it?.id);
    if (!ld) return it;
    // Preserve local soft-delete; keep the later updatedAt so subsequent
    // sync rounds don't resurrect by stale-timestamp.
    const localUpd = ld.updatedAt ? new Date(ld.updatedAt).getTime() : 0;
    const remUpd   = it.updatedAt ? new Date(it.updatedAt).getTime() : 0;
    return { ...it, _deletedAt: ld._deletedAt, updatedAt: localUpd >= remUpd ? ld.updatedAt : it.updatedAt };
  });
}

async function purgeExpiredFromBins() {
  // Purges items, grocery items, and standalone reminders whose 30-day
  // recycle bin window has expired. Writes tombstones so sync doesn't
  // resurrect them. Runs once at app start.
  let dirtyItems = false, dirtyGrocery = false, dirtyReminders = false;

  if (Array.isArray(items)) {
    const expired = items.filter(_expiredFromBin);
    if (expired.length) {
      for (const it of expired) await addTombstone(it.id);
      items = items.filter(i => !_expiredFromBin(i));
      dirtyItems = true;
    }
  }

  if (Array.isArray(groceryItems)) {
    const expired = groceryItems.filter(_expiredFromBin);
    if (expired.length) {
      for (const g of expired) await addGroceryTombstone(g.id);
      groceryItems = groceryItems.filter(i => !_expiredFromBin(i));
      dirtyGrocery = true;
    }
  }

  if (Array.isArray(reminders)) {
    const expired = reminders.filter(_expiredFromBin);
    if (expired.length) {
      for (const r of expired) await addReminderTombstone(r.id);
      reminders = reminders.filter(r => !_expiredFromBin(r));
      dirtyReminders = true;
    }
  }

  try {
    if (dirtyItems)     await saveData();
    if (dirtyGrocery)   await saveGrocery();
    if (dirtyReminders) await saveReminders();
  } catch(e) { console.warn('purgeExpiredFromBins save failed:', e); }
}

async function mergeItems(local, remote, remoteWins = false) {
  const deletedIds = await loadDeletedIds();
  const merged = new Map();
  for (const item of local) {
    if (!deletedIds.has(item.id)) merged.set(item.id, item);
  }
  for (const remoteItem of remote) {
    if (deletedIds.has(remoteItem.id)) continue;
    const localItem = merged.get(remoteItem.id);
    if (!localItem) {
      merged.set(remoteItem.id, remoteItem);
    } else {
      const localTime  = localItem.updatedAt  ? new Date(localItem.updatedAt).getTime()  : null;
      const remoteTime = remoteItem.updatedAt ? new Date(remoteItem.updatedAt).getTime() : null;
      if (localTime !== null && remoteTime !== null) {
        if (remoteTime > localTime) merged.set(remoteItem.id, remoteItem);
      } else if (remoteTime !== null && localTime === null) {
        merged.set(remoteItem.id, remoteItem);
      } else if (localTime !== null && remoteTime === null) {
        // local wins
      } else {
        if (remoteWins) merged.set(remoteItem.id, remoteItem);
      }
    }
  }
  return Array.from(merged.values());
}

// ═══════════════════════════════════════════
//  WIZARD
// ═══════════════════════════════════════════
function buildCountryGrid() {
  const grid = document.getElementById('country-grid');
  if (!grid) return;
  // Pick up any selection made before app.js loaded (via the inline stub)
  if (window._pendingCountry) wizardCountry = window._pendingCountry;
  // If buttons already exist (pre-rendered in HTML), just update selected state
  if (grid.children.length > 0) {
    selectCountry(wizardCountry);
    return;
  }
  // Fallback: build from COUNTRIES array if somehow empty
  grid.innerHTML = COUNTRIES.map(c => `
    <button class="country-btn${c.code===wizardCountry?' selected':''}" id="cbtn-${c.code}" onclick="selectCountry('${c.code}')">
      <span style="font-size:22px">${c.flag}</span>
      <span>${c.name}</span>
      <span class="check">✓</span>
    </button>`).join('');
  updateCountryConfirm();
}

function selectCountry(code) {
  wizardCountry = code;
  window._pendingCountry = null; // clear any pending stub selection
  document.querySelectorAll('.country-btn').forEach(b => b.classList.remove('selected'));
  document.getElementById('cbtn-'+code)?.classList.add('selected');
  updateCountryConfirm();
}

function updateCountryConfirm() {
  const c = COUNTRIES.find(x => x.code === wizardCountry);
  const el = document.getElementById('country-confirm');
  if (el && c) el.textContent = `✓ Using ${c.flag} ${c.name} stores`;
}

function enableItemEdit() {
  // Per-record readOnly downgrade (Part B Round 2). If the owner pushed
  // this item with _shareEffectivePerm: 'r' to this guest, the guest is
  // intentionally view-only on this specific item even when they have
  // edit perm on the rest of the stockroom section. Block the form swap
  // with a toast — defense-in-depth on top of the sync filter that
  // already keeps these items in the guest's view.
  const _editingItem = items.find(i => i.id === editingId);
  if (_editingItem?._shareEffectivePerm === 'r') {
    toast('This item is read-only — the owner shared it with view-only access');
    return;
  }
  document.getElementById('item-modal-title').textContent = 'Edit Item';
  document.getElementById('item-modal-subtitle').textContent = 'Editing: ' + (_editingItem?.name || '');
  hide('item-readonly-view');
  show('item-edit-view', 'block');
}

function wizardNext() {
  localStorage.setItem('stockroom_country_set', '1');
  document.getElementById('wizard-step-1').classList.remove('active');
  document.getElementById('wizard-step-2').classList.add('active');
  document.getElementById('dot-1').classList.remove('active');
  document.getElementById('dot-1').classList.add('done');
  document.getElementById('dot-2').classList.add('active');
  document.getElementById('dot-2').style.width = '24px';
}

function wizardBack() {
  document.getElementById('wizard-step-2').classList.remove('active');
  document.getElementById('wizard-step-1').classList.add('active');
  document.getElementById('dot-2').classList.remove('active');
  document.getElementById('dot-2').style.width = '8px';
  document.getElementById('dot-1').classList.remove('done');
  document.getElementById('dot-1').classList.add('active');
}

async function wizardFinish() {
  try {
    // Pick up country selected before app.js loaded (via inline stub)
    if (window._pendingCountry) wizardCountry = window._pendingCountry;
    settings.country = wizardCountry;
    // Capture name from wizard if entered
    const wizardName = document.getElementById('wizard-display-name')?.value?.trim();
    if (wizardName) settings.displayName = _capitaliseFirst(wizardName);
    await _saveSettings();
    await setCountrySetForDevice();
    const countrySel = document.getElementById('setting-country');
    if (countrySel) countrySel.value = settings.country;
    updateHeaderGreeting();
    // MFA already verified before we got here — go straight to Stockroom
    await _enterStockroom();
  } catch(e) {
    console.error('wizardFinish error:', e);
    // Still try to dismiss wizard even if something failed
    localStorage.setItem('stockroom_seen', '1');
    localStorage.setItem('stockroom_country_set', '1');
    document.body.classList.remove('wizard-active');
    hide('wizard');
  }
}

