// ═══════════════════════════════════════════════════════════════════════════
//  NOTIFICATION SYSTEM — in-app notification inbox
// ═══════════════════════════════════════════════════════════════════════════
//
// A persistent inbox of notifications surfaced via a bell icon in the header.
// Sources:
//   1. Reminder firing       — hooked into checkReminderNotifications()
//   2. Item alerts (low/exp) — hooked into checkLowStockNotifications()
//   3. Shared items changed  — diffed inside absorbSharedData() (owner side)
//                              and inside kvSyncNow share-pull (guest side)
//
// Each notification:
//   { id, type, title, body, sourceRef, createdAt, readAt, pinned, sharedFromCode, sharedFromName }
//
// Cap: 50 live + history total, FIFO eviction. Up to 3 pinned items stay at
// the top of the list (immune to FIFO eviction).
//
// Scope: notifications are stored in the user's OWN encrypted blob via
// kvPush/kvPull — they sync across the user's devices but NEVER cross share
// boundaries. A notification ("Sarah added milk") that lives on Pete's device
// must not appear in Sarah's notification list. Each device generates its own
// notifications from local diffs.
const NOTIFICATIONS_CAP        = 50;
const NOTIFICATIONS_PINNED_MAX = 3;

let notifications = []; // global state, mirrors dbPut('notifications','notifications', ...)

async function loadNotifications() {
  try {
    const stored = await dbGet('notifications', 'notifications');
    // Important: assign in both branches. If we only assign when stored is
    // an array, an empty IDB store leaves stale in-memory state from a
    // previous user/session — which is exactly how real-account
    // notifications leaked into demo mode (the demo IDB has nothing, the
    // load was a no-op, the previously-loaded array survived intact).
    notifications = Array.isArray(stored) ? stored : [];
  } catch(e) {
    // Fresh install — no store yet. Still reset to empty so a previous
    // tenant's data can't persist across a profile/demo switch.
    notifications = [];
  }
}

async function saveNotificationsLocal() {
  try { await dbPut('notifications', 'notifications', notifications); } catch(_) {}
}

// Add a notification. Dedupes by sourceRef+type within a 24h window so we
// don't get 30 "milk is low" entries from repeated low-stock checks.
async function addNotification({ type, title, body, sourceRef, sharedFromCode, sharedFromName, dedupeWindowMs }) {
  if (!type || !title) return null;
  const now = Date.now();
  const dwin = dedupeWindowMs ?? (24 * 60 * 60 * 1000); // 24h default
  if (sourceRef) {
    const existing = notifications.find(n =>
      n.sourceRef === sourceRef && n.type === type &&
      (now - new Date(n.createdAt).getTime()) < dwin
    );
    if (existing) {
      // Refresh body and bump createdAt so the dedupe window slides forward
      existing.body = body || existing.body;
      existing.title = title;
      existing.createdAt = new Date(now).toISOString();
      existing.readAt = null; // un-read it on re-trigger
      await saveNotificationsLocal();
      _renderNotificationBellBadge();
      return existing;
    }
  }
  const entry = {
    id: uid(),
    type,
    title,
    body: body || '',
    sourceRef: sourceRef || null,
    createdAt: new Date(now).toISOString(),
    readAt: null,
    pinned: false,
    sharedFromCode: sharedFromCode || null,
    sharedFromName: sharedFromName || null,
  };
  notifications.unshift(entry);
  _enforceNotificationCap();
  await saveNotificationsLocal();
  _renderNotificationBellBadge();
  // If the panel is open, re-render it
  if (document.getElementById('notif-panel')?.classList.contains('open')) {
    _renderNotificationPanel();
  }
  return entry;
}

// ── Pull billing/account notifications from the server queue ─────────
// Webhook handlers can't write directly into our encrypted notification
// inbox (server doesn't have the key), so they push to a plaintext
// server-side queue. This function pulls everything pending, absorbs each
// into the local inbox (via addNotification, which handles dedupe by
// sourceRef), then acks the ids so the server can delete them.
//
// Called on every billing-status refresh and on every kvSyncNow. Idempotent
// and safe to call repeatedly — addNotification dedupes by sourceRef
// inside its own 24h window, and the server-side queue dedupe protects
// against duplicate webhook deliveries.
let _pullBillingNotificationsInflight = false;
async function pullBillingNotifications() {
  if (!kvConnected || !_kvEmailHash) return;
  if (_pullBillingNotificationsInflight) return; // single-flight
  _pullBillingNotificationsInflight = true;
  try {
    const authBody = _kvSessionToken && !_kvVerifier
      ? { emailHash: _kvEmailHash, sessionToken: _kvSessionToken }
      : { emailHash: _kvEmailHash, verifier: _kvVerifier };
    const r = await fetch(`${WORKER_URL}/billing/pending-notifications`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(authBody),
    });
    if (!r.ok) {
      console.warn(`[billing-notif] pending fetch failed: ${r.status}`);
      return;
    }
    const data = await r.json();
    const items = Array.isArray(data?.items) ? data.items : [];
    if (items.length === 0) return;
    const ackIds = [];
    for (const it of items) {
      if (!it || !it.id || !it.type || !it.title) continue;
      try {
        await addNotification({
          type:      it.type,
          title:     it.title,
          body:      it.body || '',
          sourceRef: it.sourceRef || `billing:${it.id}`,
        });
        ackIds.push(it.id);
      } catch (err) {
        console.warn(`[billing-notif] failed to absorb ${it.id}:`, err?.message || err);
      }
    }
    // Ack — even partial success is worth reporting so successful absorbs
    // don't get re-delivered on the next pull.
    if (ackIds.length > 0) {
      try {
        await fetch(`${WORKER_URL}/billing/ack-notifications`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...authBody, ids: ackIds }),
        });
      } catch (err) {
        // Non-fatal — they'll re-arrive next pull and dedupe via sourceRef.
        console.warn('[billing-notif] ack failed:', err?.message || err);
      }
    }
  } catch (err) {
    console.warn('[billing-notif] pull failed:', err?.message || err);
  } finally {
    _pullBillingNotificationsInflight = false;
  }
}

// ══════════════════════════════════════════════════════════════════════
// PUSH NOTIFICATIONS (Web Push, Option A — client-prepared payloads)
// ══════════════════════════════════════════════════════════════════════
// Architecture summary (see main.ts for the server side):
//   1. User taps "Enable notifications" → Notification.requestPermission()
//   2. We call pushManager.subscribe() with the VAPID public key
//   3. POST the subscription {endpoint, p256dh, auth} to /push/subscribe
//   4. From then on, when the user wants a future notification to fire
//      on this or any of their other devices, we encrypt the body with
//      our data key and POST it to /push/schedule with a dueAt timestamp
//   5. The server's 5-minute cron dispatches due payloads to all of the
//      user's subscriptions, fan-out style
//   6. The SW receives the push, reads the data key from IDB, decrypts,
//      shows the notification
//
// E2E preservation: server sees timing + sourceRef but never content.
//
// Public API (call from anywhere):
//   isPushSupported()         — does this browser/context support push?
//   isPushSubscribed()        — async; is this device subscribed?
//   enablePush()              — async; full subscribe flow with UI feedback
//   disablePush()             — async; unsubscribe + remove on server
//   schedulePushPayload(args) — async; encrypt + post to /push/schedule
//   cancelPushPayload(sourceRef) — async; remove a pending push
//   pushSelfTest()            — async; send a test push to all our subs

const PUSH_VAPID_PUBLIC_KEY_CACHE_KEY = '_pushVapidPublicKey';

function isPushSupported() {
  return typeof navigator !== 'undefined'
    && 'serviceWorker' in navigator
    && 'PushManager' in window
    && 'Notification' in window;
}

async function isPushSubscribed() {
  if (!isPushSupported()) return false;
  try {
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    return !!sub;
  } catch (err) { return false; }
}

// base64url → Uint8Array — used to feed the VAPID public key into
// pushManager.subscribe()'s applicationServerKey option.
function _pushB64UrlToUint8Array(b64) {
  const padded = (b64 + '==='.slice((b64.length + 3) % 4))
    .replace(/-/g, '+').replace(/_/g, '/');
  const raw = atob(padded);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}

// Friendly UA label for the subscription record. Matches the device
// labelling in _checkAndNotifyNewDevice (kept in sync deliberately).
function _pushUaLabel() {
  const ua = (typeof navigator !== 'undefined' && navigator.userAgent) || '';
  if (/iPhone/i.test(ua))   return 'iPhone';
  if (/iPad/i.test(ua))     return 'iPad';
  if (/Android/i.test(ua))  return /Mobile/i.test(ua) ? 'Android phone' : 'Android tablet';
  if (/Macintosh/i.test(ua)) return 'Mac';
  if (/Windows/i.test(ua))   return 'Windows PC';
  if (/Linux/i.test(ua))     return 'Linux device';
  return 'Web';
}

// Fetch the server's VAPID public key. Cached in localStorage so we
// don't refetch on every subscribe; it changes very rarely (only if
// we rotate VAPID keys, which would require all clients to re-sub
// anyway, at which point we'd bust this cache server-side).
async function _pushGetVapidPublicKey() {
  const cached = localStorage.getItem(PUSH_VAPID_PUBLIC_KEY_CACHE_KEY);
  if (cached) return cached;
  try {
    const r = await fetch(`${WORKER_URL}/push/config`);
    if (!r.ok) return null;
    const cfg = await r.json();
    if (!cfg.configured || !cfg.publicKey) return null;
    localStorage.setItem(PUSH_VAPID_PUBLIC_KEY_CACHE_KEY, cfg.publicKey);
    return cfg.publicKey;
  } catch (err) {
    console.warn('[push] vapid key fetch failed:', err && err.message);
    return null;
  }
}

// Mirror the device id + device secret into IndexedDB so the service
// worker can read them on push receipt. localStorage is unreachable
// from the SW context, but IDB is. The secret value isn't "more secret"
// than the key itself — anything that can read IDB on this origin
// already has equivalent access — so duplicating it is not a security
// regression. This must be called after sign-in completes, when both
// values are available.
async function _saveDeviceSecretToIdb() {
  try {
    const id = getOrCreateDeviceId();
    const secret = localStorage.getItem('stockroom_device_secret');
    if (!id || !secret) return;
    // Write into the device-info DB — sw.js reads from there, independent
    // of which user is currently signed in. Previously these lived in the
    // shared `stockroom` IDB which meant either user's writes could clobber
    // the other's (the cross-account leak that prompted per-user DBs).
    await _deviceInfoSet('_pushDeviceId', id);
    await _deviceInfoSet('_pushDeviceSecret', secret);
  } catch (err) {
    console.warn('[push] mirror device secret to IDB failed:', err && err.message);
  }
}

// Called on sign-out / wipe to remove the mirrored values
async function _clearDeviceSecretFromIdb() {
  try {
    await _deviceInfoSet('_pushDeviceId', null);
    await _deviceInfoSet('_pushDeviceSecret', null);
  } catch (err) { /* non-fatal */ }
}

async function enablePush() {
  if (!isPushSupported()) {
    toast('Push notifications aren\'t supported in this browser');
    return false;
  }
  if (!kvConnected) {
    toast('Sign in first');
    return false;
  }
  // iOS PWA gate — push only works for home-screen-installed PWAs
  const isiOS = /iPhone|iPad|iPod/.test(navigator.userAgent);
  const isStandalone = window.matchMedia && window.matchMedia('(display-mode: standalone)').matches
    || window.navigator.standalone === true;
  if (isiOS && !isStandalone) {
    toast('Add Stockroom to your home screen first — iOS only allows notifications from installed apps');
    return false;
  }
  try {
    const perm = await Notification.requestPermission();
    if (perm !== 'granted') {
      toast(perm === 'denied'
        ? 'Notifications blocked — enable in browser settings to use this'
        : 'Notifications not enabled');
      return false;
    }
    const vapidKey = await _pushGetVapidPublicKey();
    if (!vapidKey) {
      toast('Push isn\'t configured on the server yet');
      return false;
    }
    const reg = await navigator.serviceWorker.ready;
    // If we already have a subscription on this device, reuse it. The
    // server-side subscribe handler is idempotent on deviceId.
    let sub = await reg.pushManager.getSubscription();
    if (!sub) {
      sub = await reg.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: _pushB64UrlToUint8Array(vapidKey),
      });
    }
    const json = sub.toJSON();
    const p256dhB64 = json.keys && json.keys.p256dh;
    const authB64   = json.keys && json.keys.auth;
    if (!json.endpoint || !p256dhB64 || !authB64) {
      toast('Subscription incomplete — could not enable');
      return false;
    }
    // Mirror device secret to IDB so the SW can decrypt on push receipt
    await _saveDeviceSecretToIdb();
    // POST to server
    const authBody = _kvSessionToken && !_kvVerifier
      ? { emailHash: _kvEmailHash, sessionToken: _kvSessionToken }
      : { emailHash: _kvEmailHash, verifier: _kvVerifier };
    const r = await fetch(`${WORKER_URL}/push/subscribe`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...authBody,
        endpoint:  json.endpoint,
        p256dhB64,
        authB64,
        deviceId:  getOrCreateDeviceId(),
        uaLabel:   _pushUaLabel(),
      }),
    });
    if (!r.ok) {
      console.warn('[push] server subscribe failed:', r.status);
      toast('Could not register with server — try again');
      // Don't unsubscribe locally — we'll retry on next enable
      return false;
    }
    settings.pushEnabled = true;
    try { await _saveSettings(); } catch(_) {}
    toast('Notifications enabled ✓');
    // Seed the server-side push queue with all of this user's future
    // reminders so this device starts receiving pushes immediately
    // (vs. having to wait for the next reminder edit to trigger sync).
    _syncReminderPushes().catch(_ => {});
    // Audit log notification
    addNotification({
      type:      'account',
      title:     'Push notifications enabled',
      body:      `You'll receive notifications on ${_pushUaLabel()}.`,
      sourceRef: `account:push-enabled:${getOrCreateDeviceId()}`,
    }).catch(_ => {});
    return true;
  } catch (err) {
    console.error('[push] enable failed:', err && err.message);
    toast('Could not enable: ' + (err && err.message ? err.message : 'unknown'));
    return false;
  }
}

async function disablePush() {
  if (!isPushSupported()) return false;
  try {
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    if (sub) await sub.unsubscribe();
    // Remove from server
    if (kvConnected) {
      const authBody = _kvSessionToken && !_kvVerifier
        ? { emailHash: _kvEmailHash, sessionToken: _kvSessionToken }
        : { emailHash: _kvEmailHash, verifier: _kvVerifier };
      await fetch(`${WORKER_URL}/push/unsubscribe`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...authBody, deviceId: getOrCreateDeviceId() }),
      }).catch(_ => {});
    }
    settings.pushEnabled = false;
    try { await _saveSettings(); } catch(_) {}
    toast('Notifications disabled');
    return true;
  } catch (err) {
    console.error('[push] disable failed:', err && err.message);
    toast('Could not disable: ' + (err && err.message ? err.message : 'unknown'));
    return false;
  }
}

// Encrypt a notification body with the user's data key and POST it as
// a scheduled push. Body shape: { title: string, body?: string, url?: string }
// The server only sees ciphertext + sourceRef + dueAt — never the title.
async function schedulePushNotification({ dueAt, sourceRef, title, body, url, fallbackTitle }) {
  if (!kvConnected || !_kvKey) return false;
  if (typeof dueAt !== 'number') return false;
  if (!sourceRef || !title) return false;
  try {
    const plaintext = JSON.stringify({ title, body: body || '', url: url || './' });
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const ciphertext = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv },
      _kvKey,
      new TextEncoder().encode(plaintext),
    );
    // Prepend iv to ciphertext, base64 the whole thing
    const combined = new Uint8Array(12 + ciphertext.byteLength);
    combined.set(iv, 0);
    combined.set(new Uint8Array(ciphertext), 12);
    const b64 = btoa(String.fromCharCode(...combined));
    const authBody = _kvSessionToken && !_kvVerifier
      ? { emailHash: _kvEmailHash, sessionToken: _kvSessionToken }
      : { emailHash: _kvEmailHash, verifier: _kvVerifier };
    const r = await fetch(`${WORKER_URL}/push/schedule`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...authBody,
        dueAt,
        sourceRef,
        ciphertextB64: b64,
        fallbackTitle: fallbackTitle || 'New Stockroom notification',
      }),
    });
    if (!r.ok) {
      console.warn('[push] schedule failed:', r.status);
      return false;
    }
    return true;
  } catch (err) {
    console.warn('[push] schedule error:', err && err.message);
    return false;
  }
}

async function cancelPushNotification(sourceRef) {
  if (!kvConnected || !sourceRef) return false;
  try {
    const authBody = _kvSessionToken && !_kvVerifier
      ? { emailHash: _kvEmailHash, sessionToken: _kvSessionToken }
      : { emailHash: _kvEmailHash, verifier: _kvVerifier };
    const r = await fetch(`${WORKER_URL}/push/cancel`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...authBody, sourceRef }),
    });
    return r.ok;
  } catch (err) {
    return false;
  }
}

async function pushSelfTest() {
  if (!kvConnected) { toast('Sign in first'); return; }
  const subbed = await isPushSubscribed();
  if (!subbed) { toast('Enable push notifications first'); return; }
  try {
    const authBody = _kvSessionToken && !_kvVerifier
      ? { emailHash: _kvEmailHash, sessionToken: _kvSessionToken }
      : { emailHash: _kvEmailHash, verifier: _kvVerifier };
    const r = await fetch(`${WORKER_URL}/push/self-test`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(authBody),
    });
    const data = await r.json();
    if (data.ok) {
      toast(`Test push sent to ${data.pushed} device${data.pushed === 1 ? '' : 's'}${data.failed ? ` (${data.failed} failed)` : ''}`);
    } else {
      toast(data.error || 'Test failed');
    }
  } catch (err) {
    toast('Test failed: ' + (err && err.message));
  }
}

// Handle the pushsubscriptionchange message from the SW — re-subscribe
if (typeof navigator !== 'undefined' && navigator.serviceWorker) {
  navigator.serviceWorker.addEventListener('message', event => {
    if (event.data && event.data.type === 'PUSH_SUBSCRIPTION_CHANGE') {
      console.log('[push] subscription rotated — re-subscribing');
      enablePush().catch(_ => {});
    }
    // Note: SW_UPDATED is handled elsewhere (look for the BG_SYNC /
    // REMINDER_REPLACED message listener) — it triggers an immediate
    // reload to swap the running page from old → new bundle. That's
    // safe in Stockroom because all state lives in IndexedDB and
    // gets autosaved on every change; no mid-edit data is in
    // volatile memory only.
  });
}

// ── Reminder push scheduling ─────────────────────────────────────────
// Walks the full reminder universe (standalone + item-embedded) and for
// each whose due date is in the future, schedules a Web Push for that
// exact moment. The server's idempotent schedulePushPayload (matched
// by sourceRef) means we can re-run this freely — duplicates collapse.
//
// sourceRef includes the due-date stamp so a "marked replaced" reminder
// gets a brand-new sourceRef when its next cycle is scheduled, while
// any stale push for the old cycle is automatically superseded.
//
// Called from:
//   - saveReminders() and the various reminder mutators (after a change)
//   - _applyReplacedLocally() (after marking a reminder replaced)
//   - kvSyncNow() (after a pull that may have brought in remote changes)
//   - enablePush() (so newly-subscribed devices immediately have their
//     future reminders queued)
let _syncReminderPushesInflight = false;
async function _syncReminderPushes() {
  if (_syncReminderPushesInflight) return;
  if (!kvConnected || !_kvKey) return;
  // Skip if push isn't enabled on this device — no server subs to feed.
  // (Server-side fan-out covers other-device subs even if THIS device
  // hasn't subscribed, but if NO device of the user is subscribed,
  // scheduling pushes is wasted work.)
  if (!isPushSupported()) return;
  _syncReminderPushesInflight = true;
  try {
    // Build the full reminder list — mirrors the construction in renderReminders().
    const allReminders = [
      ...reminders.filter(r => !r._deletedAt),
      ...items.filter(i => !i._deletedAt).flatMap(i => {
        const fallbackDate = i.startedUsing || i.logs?.filter(l => !l.pendingDelivery)[0]?.date || null;
        if (i.replacementReminders?.length) {
          return i.replacementReminders.map(r => ({
            id:           `item_${i.id}_${r.id}`,
            name:         r.name ? `${i.name} — ${r.name}` : i.name,
            itemName:     i.name,
            reminderName: r.name || '',
            interval:     r.interval,
            unit:         r.unit,
            lastReplaced: r.lastReplaced || fallbackDate || null,
          }));
        } else if (i.replacementInterval && i.replacementUnit) {
          return [{
            id:           `item_${i.id}`,
            name:         i.name,
            itemName:     i.name,
            reminderName: '',
            interval:     i.replacementInterval,
            unit:         i.replacementUnit,
            lastReplaced: i.lastReplaced || fallbackDate || null,
          }];
        }
        return [];
      }),
    ];
    const now = Date.now();
    // Look ahead up to 365 days — beyond that, the user has probably
    // changed devices/passphrase anyway and a re-sync will refresh.
    const HORIZON_MS = 365 * 24 * 60 * 60 * 1000;
    for (const r of allReminders) {
      const dueDate = getReminderDueDate(r);
      if (!dueDate) continue;
      const dueAt = dueDate.getTime();
      if (dueAt <= now) continue;                  // already due — handled by in-app loop
      if (dueAt - now > HORIZON_MS) continue;      // too far out
      const dueDateStr = dueDate.toISOString().slice(0, 10);
      const sourceRef = `reminder:${r.id}:${dueDateStr}`;
      const title = r.name;
      // Body: human-readable due description
      const days = Math.round((dueAt - now) / (24 * 60 * 60 * 1000));
      const body = days <= 0 ? 'Due today' : (days === 1 ? 'Due tomorrow' : `Due in ${days} days`);
      // Fire-and-forget; the inner function logs its own failures.
      schedulePushNotification({
        dueAt,
        sourceRef,
        title,
        body,
        url:           './',
        fallbackTitle: 'A Stockroom reminder is due',
      }).catch(_ => {});
    }
  } catch (err) {
    console.warn('[push] _syncReminderPushes failed:', err && err.message);
  } finally {
    _syncReminderPushesInflight = false;
  }
}

// Debounced wrapper — call this from event handlers (save, edit, replace).
// Multiple rapid edits collapse into a single sync after 1.5s of quiet.
let _syncReminderPushesTimer = null;
function syncReminderPushesDebounced() {
  if (_syncReminderPushesTimer) clearTimeout(_syncReminderPushesTimer);
  _syncReminderPushesTimer = setTimeout(() => {
    _syncReminderPushesTimer = null;
    _syncReminderPushesDebounce_fire();
  }, 1500);
}
function _syncReminderPushesDebounce_fire() {
  _syncReminderPushes().catch(_ => {});
}

// UI helper for the account security toggle
async function renderPushSettingsUI() {
  const labelEl = document.getElementById('push-settings-status');
  const btnEl   = document.getElementById('push-settings-toggle-btn');
  const testBtn = document.getElementById('push-settings-test-btn');
  if (!labelEl || !btnEl) return;
  if (!isPushSupported()) {
    labelEl.textContent = 'Not supported in this browser';
    btnEl.style.display = 'none';
    if (testBtn) testBtn.style.display = 'none';
    return;
  }
  const subbed = await isPushSubscribed();
  if (subbed) {
    labelEl.textContent = 'Enabled on this device';
    btnEl.textContent = 'Disable';
    btnEl.onclick = async () => {
      await disablePush();
      renderPushSettingsUI();
    };
    if (testBtn) testBtn.style.display = 'inline-flex';
  } else {
    labelEl.textContent = Notification.permission === 'denied'
      ? 'Blocked — re-enable in browser settings to use'
      : 'Off — turn on to get reminders even when the app is closed';
    btnEl.textContent = 'Enable';
    btnEl.onclick = async () => {
      await enablePush();
      renderPushSettingsUI();
    };
    if (testBtn) testBtn.style.display = 'none';
  }
}


// On every successful sync (which is the first moment `settings` is
// populated post-sign-in), check whether the current device's ID appears
// in settings.knownDevices. If not, this is a new device — emit an
// account notification and add the device to the list.
//
// The deviceId is local-only (localStorage), so a single human signing in
// on phone+tablet+desktop gets one notification per physical device on
// first sign-in. Wiping browser data on a device produces a new deviceId,
// so the next sign-in there will look "new" — that's a reasonable trade
// (a cleared device is effectively a new device from a security stance).
//
// Single-flight on `_newDeviceCheckDone` so we don't fire the same
// notification twice within a session (the helper is idempotent thanks
// to addNotification's sourceRef dedupe, but the in-memory guard saves
// the dedupe scan).
let _newDeviceCheckDone = false;
async function _checkAndNotifyNewDevice() {
  if (_newDeviceCheckDone) return;
  if (!kvConnected || !settings) return;
  try {
    const deviceId = getOrCreateDeviceId();
    if (!deviceId) return;
    const known = Array.isArray(settings.knownDevices) ? settings.knownDevices : [];
    const isKnown = known.some(d => d && d.id === deviceId);
    if (isKnown) {
      _newDeviceCheckDone = true;
      // Refresh lastSeen so we have a recent timestamp if/when we add a
      // "manage devices" view later. Best-effort, no push needed.
      const entry = known.find(d => d && d.id === deviceId);
      if (entry) entry.lastSeenAt = new Date().toISOString();
      return;
    }
    // Unknown device — record and notify.
    const ua = (typeof navigator !== 'undefined' && navigator.userAgent) || '';
    // Light UA parsing for a friendly label
    let label = 'this device';
    if (/iPhone/i.test(ua))      label = 'an iPhone';
    else if (/iPad/i.test(ua))   label = 'an iPad';
    else if (/Android/i.test(ua)) label = /Mobile/i.test(ua) ? 'an Android phone' : 'an Android tablet';
    else if (/Macintosh/i.test(ua)) label = 'a Mac';
    else if (/Windows/i.test(ua))   label = 'a Windows PC';
    else if (/Linux/i.test(ua))     label = 'a Linux device';
    known.push({
      id: deviceId,
      firstSeenAt: new Date().toISOString(),
      lastSeenAt:  new Date().toISOString(),
      uaLabel:     label,
    });
    settings.knownDevices = known;
    try { await _saveSettings(); } catch(e) {}
    addNotification({
      type:      'account',
      title:     'New sign-in on a new device',
      body:      `You signed in on ${label}. If this wasn\'t you, change your passphrase immediately.`,
      sourceRef: `account:new-device:${deviceId}`,
    }).catch(_ => {});
    _newDeviceCheckDone = true;
  } catch (err) {
    console.warn('[new-device] check failed:', err?.message || err);
  }
}


// Cap enforcement: keep all pinned (up to NOTIFICATIONS_PINNED_MAX), and
// trim the unpinned tail so total never exceeds NOTIFICATIONS_CAP. Pinned
// items beyond the max are demoted to unpinned (oldest pin first), so a
// user can never get into a state with more than 3 pins.
function _enforceNotificationCap() {
  // First: trim pins to at most NOTIFICATIONS_PINNED_MAX
  const pinned = notifications.filter(n => n.pinned);
  if (pinned.length > NOTIFICATIONS_PINNED_MAX) {
    // Sort pinned by createdAt desc; the OLDEST ones get demoted
    pinned.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    // Stamp pinnedAt on demote so the merge treats this as a fresh
    // unpin decision and propagates it across devices. Without the
    // stamp, the demote would lose to any other device that still
    // remembers the original pin (their pinnedAt would equal ours).
    const demoteTs = new Date().toISOString();
    pinned.slice(NOTIFICATIONS_PINNED_MAX).forEach(n => {
      n.pinned = false;
      n.pinnedAt = demoteTs;
    });
  }
  // Then: enforce total cap — keep all pinned plus newest unpinned
  if (notifications.length <= NOTIFICATIONS_CAP) return;
  const kept = [];
  const ordered = [...notifications].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  // Keep all pinned first
  ordered.forEach(n => { if (n.pinned) kept.push(n); });
  // Then add newest unpinned until cap
  for (const n of ordered) {
    if (kept.length >= NOTIFICATIONS_CAP) break;
    if (!n.pinned) kept.push(n);
  }
  notifications = kept;
}

function _unreadNotificationCount() {
  return notifications.filter(n => !n.readAt).length;
}

function _renderNotificationBellBadge() {
  const n = _unreadNotificationCount();
  // Header bell badge (mobile/medium screens)
  const headerBadge = document.getElementById('notif-bell-badge');
  if (headerBadge) {
    if (n > 0) {
      headerBadge.textContent = n > 99 ? '99+' : String(n);
      headerBadge.style.display = 'inline-flex';
    } else {
      headerBadge.style.display = 'none';
    }
  }
  // Sidebar bell badge (desktop). Kept in sync with the header bell so the
  // unread count appears wherever the user is most likely to look on each
  // viewport size.
  const sidebarBadge = document.getElementById('notif-sidebar-badge');
  if (sidebarBadge) {
    if (n > 0) {
      sidebarBadge.textContent = n > 99 ? '99+' : String(n);
      sidebarBadge.style.display = 'inline-flex';
    } else {
      sidebarBadge.style.display = 'none';
    }
  }
}

function openNotificationPanel() {
  const panel = document.getElementById('notif-panel');
  if (!panel) return;
  _renderNotificationPanel();
  panel.classList.add('open');
  panel.setAttribute('aria-hidden', 'false');
  // Body class drives CSS that pushes the FAB behind the panel on mobile.
  document.body.classList.add('notif-panel-open');
  setTimeout(() => {
    document.addEventListener('click', _notifPanelOutsideClick, true);
    document.addEventListener('keydown', _notifPanelKeyDown);
  }, 0);
}

function closeNotificationPanel() {
  const panel = document.getElementById('notif-panel');
  if (!panel) return;
  panel.classList.remove('open');
  panel.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('notif-panel-open');
  document.removeEventListener('click', _notifPanelOutsideClick, true);
  document.removeEventListener('keydown', _notifPanelKeyDown);
}

function toggleNotificationPanel() {
  const panel = document.getElementById('notif-panel');
  if (!panel) return;
  if (panel.classList.contains('open')) closeNotificationPanel();
  else openNotificationPanel();
}

function _notifPanelOutsideClick(e) {
  const panel    = document.getElementById('notif-panel');
  const bell     = document.getElementById('notif-bell-btn');
  const sideBell = document.getElementById('notif-sidebar-btn');
  if (!panel) return;
  // Don't close if the click landed on the panel itself or on either of the
  // bell buttons (mobile/medium header bell OR desktop sidebar bell) — those
  // toggle the panel on their own.
  if (panel.contains(e.target)) return;
  if (bell && bell.contains(e.target)) return;
  if (sideBell && sideBell.contains(e.target)) return;
  closeNotificationPanel();
}
function _notifPanelKeyDown(e) {
  if (e.key === 'Escape') closeNotificationPanel();
}

function _notifTypeIcon(type) {
  switch (type) {
    case 'reminder':  return 'i-bell';
    case 'low-stock': return 'i-alert-triangle';
    case 'expiring':  return 'i-alert-triangle';
    case 'share':     return 'i-users';
    case 'billing':   return 'i-piggy-bank';
    case 'account':   return 'i-shield';
    default:          return 'i-circle';
  }
}

function _notifRelativeTime(iso) {
  if (!iso) return '';
  const ms = Date.now() - new Date(iso).getTime();
  if (ms < 60 * 1000)        return 'just now';
  if (ms < 60 * 60 * 1000)   return Math.floor(ms / 60000) + 'm ago';
  if (ms < 24 * 3600 * 1000) return Math.floor(ms / 3600000) + 'h ago';
  if (ms < 7 * 86400 * 1000) return Math.floor(ms / 86400000) + 'd ago';
  return new Date(iso).toLocaleDateString();
}

// ── Context-aware action buttons for notification rows ────────────────────
// Returns an HTML strip of buttons appropriate to the notification type and
// current state of its underlying source object. Returns '' if no actions
// apply (e.g. share notifications, or sources that can no longer be resolved).
//
// Supported types:
//   low-stock  → Order now / Log Order / Mark Delivered (depending on url + ordered)
//   expiring   → Mark used (reuses replacement-log flow)
//   reminder   → Mark {template name} replaced  /  Mark replaced
//   pending    → Mark Delivered / Still waiting  (for future "delivery nudge" type)
//
// Each button calls a global handler via inline onclick with event.stopPropagation
// so clicking a button doesn't also trigger the row's click-to-navigate.
function _buildNotifContextButtons(n) {
  if (!n || !n.sourceRef) return '';
  try {
    if (n.type === 'low-stock' || n.type === 'expiring') {
      // sourceRef format: "lowstock:<itemId>"  (also used for expiring)
      const itemId = n.sourceRef.split(':')[1];
      const item = items.find(i => i.id === itemId);
      if (!item || item._deletedAt) return '';

      if (n.type === 'expiring') {
        return `
          <div class="notif-ctx-actions">
            <button class="notif-ctx-btn primary" onclick="event.stopPropagation();notifAction_markUsed('${n.id}','${item.id}')">
              <svg class="icon icon-sm" aria-hidden="true"><use href="#i-check-check"></use></svg> Mark used
            </button>
          </div>`;
      }

      // low-stock
      if (item.ordered) {
        return `
          <div class="notif-ctx-actions">
            <button class="notif-ctx-btn primary" onclick="event.stopPropagation();notifAction_markDelivered('${n.id}','${item.id}')">
              <svg class="icon icon-sm" aria-hidden="true"><use href="#i-truck"></use></svg> Mark Delivered
            </button>
          </div>`;
      }

      const hasUrl = !!(item.url && item.url.trim());
      const orderNowBtn = hasUrl
        ? `<button class="notif-ctx-btn primary" onclick="event.stopPropagation();notifAction_orderNow('${n.id}','${item.id}')">
             <svg class="icon icon-sm" aria-hidden="true"><use href="#i-external-link"></use></svg> Order now
           </button>`
        : '';
      const logOrderBtn = `<button class="notif-ctx-btn" onclick="event.stopPropagation();notifAction_logOrder('${n.id}','${item.id}')">
          <svg class="icon icon-sm" aria-hidden="true"><use href="#i-clipboard-check"></use></svg> Log Order
        </button>`;
      return `<div class="notif-ctx-actions">${orderNowBtn}${logOrderBtn}</div>`;
    }

    if (n.type === 'reminder') {
      // sourceRef format: "reminder:<id>" where id may be standalone or item_xxx_yyy
      const rid = n.sourceRef.slice('reminder:'.length);
      const resolved = _resolveReminderId(rid);
      if (!resolved) return '';
      const tmplName = resolved.r.reminderName || '';
      const label = tmplName ? `Mark ${tmplName} replaced` : 'Mark replaced';
      return `
        <div class="notif-ctx-actions">
          <button class="notif-ctx-btn primary" onclick="event.stopPropagation();notifAction_markReplaced('${n.id}','${rid.replace(/'/g, "\\'")}')">
            <svg class="icon icon-sm" aria-hidden="true"><use href="#i-check-check"></use></svg> ${esc(label)}
          </button>
        </div>`;
    }

    if (n.type === 'pending') {
      // Reserved for future "you ordered this N days ago, still waiting?" nudge.
      // sourceRef format: "pending:<itemId>"
      const itemId = n.sourceRef.split(':')[1];
      const item = items.find(i => i.id === itemId);
      if (!item || item._deletedAt) return '';
      return `
        <div class="notif-ctx-actions">
          <button class="notif-ctx-btn primary" onclick="event.stopPropagation();notifAction_markDelivered('${n.id}','${item.id}')">
            <svg class="icon icon-sm" aria-hidden="true"><use href="#i-truck"></use></svg> Mark Delivered
          </button>
          <button class="notif-ctx-btn" onclick="event.stopPropagation();notifAction_snoozePending('${n.id}')">
            <svg class="icon icon-sm" aria-hidden="true"><use href="#i-clock"></use></svg> Still waiting
          </button>
        </div>`;
    }
  } catch(e) { /* never let a bad source break the row */ }
  return '';
}

// ── Notification action handlers ──────────────────────────────────────────
// Each takes the notification id (so the notification can be dismissed/refreshed
// after the action) plus whatever entity id the action needs.

async function notifAction_orderNow(notifId, itemId) {
  const item = items.find(i => i.id === itemId);
  if (!item?.url) { toast('No URL on this item'); return; }
  window.open(item.url, '_blank', 'noopener');
  // Open in new tab but don't auto-mark ordered — user might just be browsing.
  // The Log Order button is right there if they do place an order.
}

async function notifAction_logOrder(notifId, itemId) {
  if (typeof markOrdered === 'function') {
    await markOrdered(itemId);
    await dismissNotification(notifId);
  }
}

async function notifAction_markDelivered(notifId, itemId) {
  if (typeof openDeliveredModal === 'function') {
    closeNotificationPanel?.();
    openDeliveredModal(itemId);
    await dismissNotification(notifId);
  }
}

async function notifAction_markReplaced(notifId, reminderId) {
  if (typeof _applyReplacedLocally === 'function') {
    await _applyReplacedLocally(reminderId, today());
    await dismissNotification(notifId);
  }
}

async function notifAction_markUsed(notifId, itemId) {
  // Treat "used" as a replacement log on the item itself
  if (typeof _applyReplacedLocally === 'function') {
    await _applyReplacedLocally(`item_${itemId}`, today());
    await dismissNotification(notifId);
  }
}

async function notifAction_snoozePending(notifId) {
  const n = notifications.find(x => x.id === notifId);
  if (!n) return;
  // Push createdAt forward 3 days so the dedupe window keeps it suppressed,
  // and mark read so the badge clears.
  const future = Date.now() + 3 * 24 * 60 * 60 * 1000;
  n.createdAt = new Date(future).toISOString();
  n.readAt = new Date().toISOString();
  await saveNotificationsLocal();
  _renderNotificationBellBadge();
  _renderNotificationPanel();
  toast('Snoozed for 3 days');
}

// ── Swipe-to-dismiss for notification rows (mobile) ──────────────────
// Horizontal drag past the threshold dismisses the row. Below the
// threshold or vertical drag releases and snaps back. Vertical-first
// gestures yield to the scroll container so the user can scroll the
// list normally.
const _NOTIF_SWIPE_THRESHOLD_PX = 80;
const _notifSwipeState = new Map(); // id → { startX, startY, dx, locked }

function onNotifRowTouchStart(event, id) {
  if (!event.touches || event.touches.length !== 1) return;
  const t = event.touches[0];
  _notifSwipeState.set(id, { startX: t.clientX, startY: t.clientY, dx: 0, locked: null });
  const row = event.currentTarget;
  if (row) {
    row.style.transition = ''; // remove any prior snap-back transition
  }
}

function onNotifRowTouchMove(event, id) {
  const st = _notifSwipeState.get(id);
  if (!st) return;
  const t = event.touches[0];
  const dx = t.clientX - st.startX;
  const dy = t.clientY - st.startY;
  // First meaningful movement decides axis: horizontal → swipe-to-dismiss;
  // vertical → release entirely so list scrolls.
  if (st.locked === null && (Math.abs(dx) > 6 || Math.abs(dy) > 6)) {
    st.locked = Math.abs(dx) > Math.abs(dy) ? 'h' : 'v';
  }
  if (st.locked !== 'h') return;
  // Prevent page scroll while horizontally dragging the row
  if (event.cancelable) event.preventDefault();
  st.dx = dx;
  const row = event.currentTarget;
  if (!row) return;
  // Fade as it drags — full opacity at rest, ~0.2 at threshold
  const progress = Math.min(Math.abs(dx) / _NOTIF_SWIPE_THRESHOLD_PX, 1);
  row.style.transform = `translateX(${dx}px)`;
  row.style.opacity = String(1 - progress * 0.8);
}

function onNotifRowTouchEnd(event, id) {
  const st = _notifSwipeState.get(id);
  if (!st) return;
  _notifSwipeState.delete(id);
  const row = event.currentTarget;
  if (!row) return;
  if (st.locked !== 'h') {
    // No horizontal commitment — clear any inline styles defensively
    row.style.transform = '';
    row.style.opacity = '';
    return;
  }
  if (Math.abs(st.dx) >= _NOTIF_SWIPE_THRESHOLD_PX) {
    // Animate off-screen in the swipe direction, then dismiss
    const dir = st.dx > 0 ? 1 : -1;
    row.style.transition = 'transform 0.18s ease-out, opacity 0.18s ease-out';
    row.style.transform = `translateX(${dir * window.innerWidth}px)`;
    row.style.opacity = '0';
    setTimeout(() => { dismissNotification(id); }, 180);
  } else {
    // Snap back
    row.style.transition = 'transform 0.18s ease-out, opacity 0.18s ease-out';
    row.style.transform = '';
    row.style.opacity = '';
  }
}

function _renderNotificationPanel() {
  const body = document.getElementById('notif-panel-body');
  if (!body) return;

  // Visible notifications = everything except dismissed. Dismissed entries
  // are kept in the underlying array so they show up in the history modal.
  const visible = notifications.filter(n => !n.dismissedAt);

  if (!visible.length) {
    body.innerHTML = `
      <div class="notif-empty">
        <div style="color:var(--muted);margin-bottom:8px"><svg aria-hidden="true" style="width:32px;height:32px"><use href="#i-bell-off"></use></svg></div>
        <div style="font-weight:600;font-size:14px;color:var(--text)">No notifications yet</div>
        <p style="font-size:12px;color:var(--muted);margin-top:6px;line-height:1.5">Updates from shared households, due reminders, and low-stock alerts will appear here.</p>
      </div>`;
    return;
  }

  // Sort: pinned (newest first) → unpinned (newest first)
  const sorted = [...visible].sort((a, b) => {
    if (!!b.pinned - !!a.pinned !== 0) return !!b.pinned - !!a.pinned;
    return new Date(b.createdAt) - new Date(a.createdAt);
  });

  const pinned   = sorted.filter(n => n.pinned).slice(0, NOTIFICATIONS_PINNED_MAX);
  const unpinned = sorted.filter(n => !n.pinned);

  // Plain JS list of pin counts so we can grey out the pin toggle when at cap
  const pinCount = pinned.length;

  const rowHTML = n => {
    const icon = _notifTypeIcon(n.type);
    const unread = !n.readAt;
    const pinTitle = n.pinned ? 'Unpin' : (pinCount >= NOTIFICATIONS_PINNED_MAX && !n.pinned ? 'Pin limit reached (3)' : 'Pin to top');
    const pinDisabled = !n.pinned && pinCount >= NOTIFICATIONS_PINNED_MAX;
    const ctxButtons = _buildNotifContextButtons(n);
    return `
      <div class="notif-row${unread ? ' unread' : ''}${n.pinned ? ' pinned' : ''}" data-id="${n.id}"
        ontouchstart="onNotifRowTouchStart(event,'${n.id}')"
        ontouchmove="onNotifRowTouchMove(event,'${n.id}')"
        ontouchend="onNotifRowTouchEnd(event,'${n.id}')"
        ontouchcancel="onNotifRowTouchEnd(event,'${n.id}')">
        <div class="notif-icon"><svg class="icon" aria-hidden="true"><use href="#${icon}"></use></svg></div>
        <div class="notif-content" onclick="onNotificationRowClick('${n.id}')">
          <div class="notif-title">${esc(n.title)}</div>
          ${n.body ? `<div class="notif-body">${esc(n.body)}</div>` : ''}
          <div class="notif-meta">
            <span>${_notifRelativeTime(n.createdAt)}</span>
            ${n.sharedFromName ? `<span class="notif-source">· ${esc(n.sharedFromName)}</span>` : ''}
          </div>
          ${ctxButtons}
        </div>
        <div class="notif-actions">
          <button class="notif-pin-btn${n.pinned ? ' active' : ''}" title="${pinTitle}"
                  onclick="event.stopPropagation();toggleNotificationPin('${n.id}')"
                  ${pinDisabled ? 'disabled' : ''}>
            <svg class="icon icon-sm" aria-hidden="true"><use href="#i-pin"></use></svg>
          </button>
          <button class="notif-dismiss-btn" title="Dismiss"
                  onclick="event.stopPropagation();dismissNotification('${n.id}')">
            <svg class="icon icon-sm" aria-hidden="true"><use href="#i-x"></use></svg>
          </button>
        </div>
      </div>`;
  };

  let html = '';
  if (pinned.length) {
    html += `<div class="notif-section-label"><svg class="icon icon-sm" aria-hidden="true"><use href="#i-pin"></use></svg> Pinned</div>`;
    html += pinned.map(rowHTML).join('');
  }
  if (unpinned.length) {
    if (pinned.length) html += `<div class="notif-section-label">Recent</div>`;
    html += unpinned.map(rowHTML).join('');
  }
  // ── "Your next reminder" footer ────────────────────────────────────
  // Surfaces the soonest upcoming reminder so the user can see at a glance
  // that nothing important is about to slip — even if it hasn't fired yet
  // (i.e. not due today/overdue, so it wouldn't be in the inbox above).
  try {
    const nr = _nextUpcomingReminder();
    if (nr) {
      html += `<div class="notif-next-reminder">
        <div class="notif-section-label" style="margin-top:18px"><svg class="icon icon-sm" aria-hidden="true"><use href="#i-bell"></use></svg> Your next reminder</div>
        <div class="notif-next-card">
          <div class="notif-next-icon"><svg class="icon" aria-hidden="true"><use href="#i-bell"></use></svg></div>
          <div class="notif-next-content">
            <div class="notif-next-title">${esc(nr.name)}</div>
            <div class="notif-next-meta">${esc(nr.label)}</div>
          </div>
        </div>
      </div>`;
    }
  } catch(e) { /* never let footer block panel render */ }
  // ── End terminator ────────────────────────────────────────────────
  html += `<div class="notif-end-terminator">— End —</div>`;
  body.innerHTML = html;
}

// Returns the soonest non-overdue reminder for the "Your next reminder"
// footer. If everything is overdue or there are no reminders, returns null.
function _nextUpcomingReminder() {
  if (typeof reminders === 'undefined' || !Array.isArray(reminders)) return null;
  if (typeof items === 'undefined' || !Array.isArray(items)) return null;
  const all = [
    ...reminders.filter(r => !r._deletedAt),
    ...items.filter(i => !i._deletedAt).flatMap(i => {
      const fallbackDate = i.startedUsing || i.logs?.filter(l => !l.pendingDelivery)[0]?.date || null;
      if (i.replacementReminders?.length) {
        return i.replacementReminders.map(r => ({
          id:           `item_${i.id}_${r.id}`,
          name:         r.name ? `${i.name} — ${r.name}` : i.name,
          interval:     r.interval,
          unit:         r.unit,
          lastReplaced: r.lastReplaced || fallbackDate || null,
        }));
      } else if (i.replacementInterval && i.replacementUnit) {
        return [{
          id:           `item_${i.id}`,
          name:         i.name,
          interval:     i.replacementInterval,
          unit:         i.replacementUnit,
          lastReplaced: i.lastReplaced || fallbackDate || null,
        }];
      }
      return [];
    }),
  ];
  let best = null, bestDays = Infinity;
  for (const r of all) {
    const days = typeof getReminderDaysUntil === 'function' ? getReminderDaysUntil(r) : null;
    if (days == null || days < 0) continue; // skip unknown + overdue
    if (days < bestDays) { bestDays = days; best = r; }
  }
  if (!best) return null;
  const label = bestDays === 0 ? 'Due today'
              : bestDays === 1 ? 'Due tomorrow'
              : `Due in ${bestDays} days`;
  return { name: best.name, label };
}

// ── Notification history modal ───────────────────────────────────────
// Shows the full notification cap-worth of entries (50), grouped by
// either date or type. The modal stays mounted; calling openNotificationHistory
// just re-renders the body.
let _notifHistorySort = 'date'; // 'date' | 'type'

function openNotificationHistory() {
  const modal = document.getElementById('notif-history-modal');
  if (!modal) return;
  modal.classList.add('active');
  _renderNotificationHistory();
}

function closeNotificationHistory() {
  const modal = document.getElementById('notif-history-modal');
  if (!modal) return;
  modal.classList.remove('active');
}

function setNotifHistorySort(sort) {
  _notifHistorySort = sort;
  document.querySelectorAll('.notif-history-sort-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-sort') === sort);
  });
  _renderNotificationHistory();
}

function _renderNotificationHistory() {
  const body = document.getElementById('notif-history-body');
  const countEl = document.getElementById('notif-history-count');
  if (!body) return;
  const total = notifications.length;
  if (countEl) countEl.textContent = `${total} / ${NOTIFICATIONS_CAP}`;
  if (!total) {
    body.innerHTML = `<div class="notif-empty" style="padding:60px 20px">
      <div style="color:var(--muted);margin-bottom:8px"><svg aria-hidden="true" style="width:32px;height:32px"><use href="#i-bell-off"></use></svg></div>
      <div style="font-weight:600;font-size:14px;color:var(--text)">No notifications</div>
      <p style="font-size:12px;color:var(--muted);margin-top:6px;line-height:1.5">Past notifications will appear here, up to ${NOTIFICATIONS_CAP} entries.</p>
    </div>`;
    return;
  }
  // Always: pinned first (regardless of sort mode)
  const pinned = notifications.filter(n => n.pinned)
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  const unpinned = notifications.filter(n => !n.pinned);

  const renderItem = n => {
    const icon = _notifTypeIcon(n.type);
    const isDismissed = !!n.dismissedAt;
    return `<div class="notif-history-row${isDismissed ? ' notif-dismissed' : ''}" data-id="${n.id}">
      <div class="notif-icon"><svg class="icon" aria-hidden="true"><use href="#${icon}"></use></svg></div>
      <div class="notif-content" onclick="onNotificationRowClick('${n.id}');closeNotificationHistory()">
        <div class="notif-title">${esc(n.title)}</div>
        ${n.body ? `<div class="notif-body">${esc(n.body)}</div>` : ''}
        <div class="notif-meta">
          <span>${esc(_notifAbsoluteTime(n.createdAt))}</span>
          ${n.sharedFromName ? `<span class="notif-source">· ${esc(n.sharedFromName)}</span>` : ''}
          ${isDismissed ? `<span class="notif-dismissed-tag">· Dismissed</span>` : ''}
        </div>
      </div>
    </div>`;
  };

  let html = '';
  // Pinned always at top
  if (pinned.length) {
    html += `<div class="notif-section-label" style="margin-top:8px"><svg class="icon icon-sm" aria-hidden="true"><use href="#i-pin"></use></svg> Pinned</div>`;
    html += pinned.map(renderItem).join('');
  }

  // General body — grouped by date or type
  if (_notifHistorySort === 'type') {
    // Group by type, defined order
    const typeOrder = ['low-stock','expiring','reminder','share','billing','account'];
    const labelOf = t => ({
      'low-stock': 'Low stock',
      'expiring':  'Expiring',
      'reminder':  'Reminders',
      'share':     'Shared household',
      'billing':   'Billing',
      'account':   'Account',
    }[t] || t);
    const byType = {};
    for (const n of unpinned) {
      const key = typeOrder.includes(n.type) ? n.type : 'other';
      (byType[key] = byType[key] || []).push(n);
    }
    const renderOrder = [...typeOrder.filter(t => byType[t]), ...Object.keys(byType).filter(k => !typeOrder.includes(k))];
    if (renderOrder.length) html += `<div class="notif-section-label" style="margin-top:14px">General</div>`;
    for (const t of renderOrder) {
      html += `<div class="notif-history-subhead">${esc(labelOf(t))}</div>`;
      // Sort within each type by date desc
      byType[t].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
      html += byType[t].map(renderItem).join('');
    }
  } else {
    // By date — group into Today / Yesterday / This week / Earlier
    const now = Date.now();
    const startOfToday = new Date(); startOfToday.setHours(0,0,0,0);
    const startOfYday  = new Date(startOfToday); startOfYday.setDate(startOfYday.getDate() - 1);
    const startOfWeek  = new Date(startOfToday); startOfWeek.setDate(startOfWeek.getDate() - 6);
    const buckets = { today: [], yesterday: [], week: [], earlier: [] };
    for (const n of unpinned) {
      const t = new Date(n.createdAt).getTime();
      if (t >= startOfToday.getTime()) buckets.today.push(n);
      else if (t >= startOfYday.getTime()) buckets.yesterday.push(n);
      else if (t >= startOfWeek.getTime()) buckets.week.push(n);
      else buckets.earlier.push(n);
    }
    if (unpinned.length) html += `<div class="notif-section-label" style="margin-top:14px">General</div>`;
    const order = [
      ['today',     'Today'],
      ['yesterday', 'Yesterday'],
      ['week',      'Earlier this week'],
      ['earlier',   'Earlier'],
    ];
    for (const [key, label] of order) {
      const list = buckets[key];
      if (!list.length) continue;
      list.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
      html += `<div class="notif-history-subhead">${label}</div>`;
      html += list.map(renderItem).join('');
    }
  }

  // "Your next reminder" footer
  try {
    const nr = _nextUpcomingReminder();
    if (nr) {
      html += `<div class="notif-next-reminder" style="margin-top:14px">
        <div class="notif-section-label"><svg class="icon icon-sm" aria-hidden="true"><use href="#i-bell"></use></svg> Your next reminder</div>
        <div class="notif-next-card">
          <div class="notif-next-icon"><svg class="icon" aria-hidden="true"><use href="#i-bell"></use></svg></div>
          <div class="notif-next-content">
            <div class="notif-next-title">${esc(nr.name)}</div>
            <div class="notif-next-meta">${esc(nr.label)}</div>
          </div>
        </div>
      </div>`;
    }
  } catch(e) {}
  html += `<div class="notif-end-terminator">— End —</div>`;
  body.innerHTML = html;
}

// Absolute timestamp formatter for the history view — date + time, locale-aware.
function _notifAbsoluteTime(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  const opts = { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' };
  return d.toLocaleString(undefined, opts);
}

async function onNotificationRowClick(id) {
  const n = notifications.find(x => x.id === id);
  if (!n) return;
  // Mark as read
  if (!n.readAt) {
    n.readAt = new Date().toISOString();
    await saveNotificationsLocal();
    _renderNotificationBellBadge();
    _renderNotificationPanel();
  }
  // Jump to source
  if (n.type === 'reminder') {
    closeNotificationPanel();
    try { navTo('reminders'); } catch(_) {}
    // sourceRef is "reminder:<rid>" — parse and scroll/flash the matching card
    if (n.sourceRef && n.sourceRef.startsWith('reminder:')) {
      const rid = n.sourceRef.slice('reminder:'.length);
      setTimeout(() => {
        const el = document.querySelector(`[data-reminder-id="${CSS.escape(rid)}"]`)
                || document.querySelector(`[data-id="${CSS.escape(rid)}"]`);
        if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        if (el) _flashElement(el);
      }, 350);
    }
  } else if (n.type === 'low-stock' || n.type === 'expiring') {
    closeNotificationPanel();
    try { navTo('stock'); } catch(_) {}
    if (n.sourceRef) {
      // sourceRef format: "lowstock:<itemId>" (or "expiring:<itemId>"). Strip
      // the prefix to get the item id we can match against .item-card[data-id].
      const colon = n.sourceRef.indexOf(':');
      const itemId = colon >= 0 ? n.sourceRef.slice(colon + 1) : n.sourceRef;
      setTimeout(() => {
        const el = document.querySelector(`.item-card[data-id="${CSS.escape(itemId)}"]`);
        if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        if (el) _flashElement(el);
      }, 350);
    }
  } else if (n.type === 'share') {
    closeNotificationPanel();
    // Navigation depends on the section that changed — default to stock view
    try { navTo('stock'); } catch(_) {}
  } else if (n.type === 'billing') {
    closeNotificationPanel();
    try { navTo('billing'); } catch(_) {}
  } else if (n.type === 'account') {
    closeNotificationPanel();
    try { navTo('account'); } catch(_) {}
  }
}

// Brief highlight flash to draw the eye after scrolling to a card or row.
// Adds the .notif-flash class for ~1.6s — the animation is in styles.css.
function _flashElement(el) {
  if (!el || !el.classList) return;
  // Restart the animation if it was already running on this element
  el.classList.remove('notif-flash');
  // Force reflow so the next add re-triggers the animation
  // eslint-disable-next-line no-unused-expressions
  void el.offsetWidth;
  el.classList.add('notif-flash');
  setTimeout(() => { el.classList.remove('notif-flash'); }, 1700);
}

// ═══════════════════════════════════════════════════════════════════
//  GLOBAL SEARCH
// ═══════════════════════════════════════════════════════════════════
// Opened by #global-search-btn (mobile header) and #global-search-nav-btn
// (desktop sidebar). The modal lives at body level in index.html as
// #global-search-modal. Per-section searchers each return a list of
// { id, title, sub, view, target } records — runGlobalSearch groups them
// by section and renders, pinning the current view's section to the top.
//
// Tapping a result calls _navigateToSearchResult, which navigates to the
// right view, waits for paint, scrolls the matching DOM node into view,
// and runs the existing _flashElement orange-border animation.
const _GLOBAL_SEARCH = {
  active: false,
  query: '',
  debounceTimer: null,
  cachedSettingsIndex: null,
  // Render order — current view first (computed at render time), then this
  // fixed order for the rest. Empty sections are omitted entirely.
  sectionOrder: ['stock', 'grocery', 'notes', 'reminders', 'budget', 'savings', 'report', 'billing', 'accessibility', 'account-security', 'settings'],
  sectionMeta: {
    stock:             { label: 'Stockroom',          icon: 'i-package',        view: 'stock' },
    grocery:           { label: 'Groceries',          icon: 'i-shopping-cart',  view: 'grocery' },
    notes:             { label: 'Notes',              icon: 'i-notebook-pen',   view: 'notes' },
    reminders:         { label: 'Reminders',          icon: 'i-bell',           view: 'reminders' },
    budget:            { label: 'Budget',             icon: 'i-banknote',       view: 'budget' },
    savings:           { label: 'Savings',            icon: 'i-piggy-bank',     view: 'savings' },
    report:            { label: 'Report',             icon: 'i-clipboard-list', view: 'report' },
    billing:           { label: 'Billing',            icon: 'i-credit-card',    view: 'billing' },
    accessibility:     { label: 'Accessibility',      icon: 'i-eye',            view: 'accessibility' },
    'account-security':{ label: 'Account & Security', icon: 'i-shield',         view: 'account-security' },
    settings:          { label: 'Settings',           icon: 'i-settings',       view: 'settings' },
  },
  // Filter toggles. Reset on each modal/omnibox open so a query that
  // previously surfaced an archived match doesn't accidentally leak into
  // an unrelated session. Searchers respect these flags; if either is
  // false (the default) they filter the corresponding records out, but
  // still count them so the filter bar can show "(N hidden)".
  includeArchived: false,
  includeDeleted:  false,
};
const _SEARCH_RESULTS_PER_SECTION = 8;

// ── Omnibox stockroom-workflow triggers ────────────────────────────────────
// Exact-match (case-insensitive, trimmed, optional trailing colon) query
// strings that hijack the results panel for stockroom bulk flows.
// Plural forms tolerated. Detection is in runGlobalSearch.
const _OMNIBOX_ORDER_TRIGGERS    = new Set(['order', 'orders', 'ordered']);
const _OMNIBOX_DELIVERY_TRIGGERS = new Set(['deliver', 'delivers', 'delivered', 'delivery', 'deliveries']);

// Ephemeral state for the order panel — which filter is active and the
// per-row selection / qty edits. Survives re-renders within a single
// open of the panel; cleared on dismiss or on omnibox collapse.
const _OMNIBOX_ORDER = {
  filter: null,            // '7' | '30' | 'critical' | 'low' | null
  // Map<itemId, { selected: bool, qty: number }> — per-row state
  rows: new Map(),
};

function openGlobalSearch() {
  const modal = document.getElementById('global-search-modal');
  const input = document.getElementById('global-search-input');
  if (!modal || !input) return;
  _GLOBAL_SEARCH.active = true;
  modal.classList.add('open');
  modal.setAttribute('aria-hidden', 'false');
  // Lock background scroll while the modal is open. CSS rule
  // `body.global-search-open { overflow: hidden; touch-action: none; }`
  // does the work — see styles.css. Mirrors the body.note-open pattern.
  document.body.classList.add('global-search-open');
  // Reset to a clean state each open. Don't preserve previous query — search
  // is fast enough that retyping is fine and a stale query feels confusing
  // when the underlying data may have changed since last open.
  input.value = '';
  _GLOBAL_SEARCH.query = '';
  // Reset filter flags too — fresh open should start with archived/deleted
  // hidden by default; the user explicitly opts in per session.
  _GLOBAL_SEARCH.includeArchived = false;
  _GLOBAL_SEARCH.includeDeleted  = false;
  // Reset workflow panel state so a fresh open of the legacy modal starts
  // at the chooser stage if the user types "order".
  if (typeof _OMNIBOX_ORDER !== 'undefined' && _OMNIBOX_ORDER) {
    _OMNIBOX_ORDER.filter = null;
    if (_OMNIBOX_ORDER.rows) _OMNIBOX_ORDER.rows.clear();
  }
  _renderGlobalSearchEmpty();
  // setTimeout so the focus call lands after the modal is visible — focusing
  // a display:none input is a no-op on some browsers.
  setTimeout(() => { try { input.focus(); } catch(_) {} }, 30);
  // Esc handler — installed on open, removed on close
  document.addEventListener('keydown', _globalSearchKeyEscape);
}

function closeGlobalSearch() {
  const modal = document.getElementById('global-search-modal');
  if (!modal) return;
  _GLOBAL_SEARCH.active = false;
  modal.classList.remove('open');
  modal.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('global-search-open');
  clearTimeout(_GLOBAL_SEARCH.debounceTimer);
  document.removeEventListener('keydown', _globalSearchKeyEscape);
}

function _globalSearchKeyEscape(e) {
  if (e.key === 'Escape' && _GLOBAL_SEARCH.active) {
    e.preventDefault();
    closeGlobalSearch();
  }
}

// Clears the search input and result list, returning focus to the input.
// Triggered by the inline X button — distinct from closeGlobalSearch which
// dismisses the entire modal. The user closes the modal by tapping the
// backdrop or pressing Esc.
function clearGlobalSearch() {
  const input = document.getElementById('global-search-input');
  if (input) { input.value = ''; input.focus(); }
  _GLOBAL_SEARCH.query = '';
  clearTimeout(_GLOBAL_SEARCH.debounceTimer);
  _renderGlobalSearchEmpty();
}

// Cmd/Ctrl+K shortcut — opens or closes. Wired in init via a single
// keydown listener on document.
function _globalSearchKeyShortcut(e) {
  // Don't trigger inside the search input itself
  if (e.target && e.target.id === 'global-search-input') return;
  const isMac = navigator.platform && /Mac|iPhone|iPad|iPod/.test(navigator.platform);
  const mod = isMac ? e.metaKey : e.ctrlKey;
  if (mod && e.key && e.key.toLowerCase() === 'k') {
    e.preventDefault();
    if (_GLOBAL_SEARCH.active) closeGlobalSearch();
    else openGlobalSearch();
  }
}

function onGlobalSearchInput() {
  const input = document.getElementById('global-search-input');
  if (!input) return;
  const q = (input.value || '').trim();
  _GLOBAL_SEARCH.query = q;
  clearTimeout(_GLOBAL_SEARCH.debounceTimer);
  if (!q) { _renderGlobalSearchEmpty(); return; }
  // 120ms debounce — keeps typing fluent without re-running searchers on
  // every keystroke. Searches are in-memory so 120ms is generous.
  _GLOBAL_SEARCH.debounceTimer = setTimeout(() => {
    try { runGlobalSearch(q); } catch (err) { console.error('Global search failed:', err); }
  }, 120);
}

function onGlobalSearchKeyDown(e) {
  // Enter without an active selection currently does nothing (Pete asked to
  // skip "jump to first result on Enter" for v1). We still capture Enter so
  // form-submit fallback doesn't trigger anything unexpected.
  if (e.key === 'Enter') { e.preventDefault(); return; }
  // Up/Down arrows could be added later for keyboard navigation through
  // results — left out of v1 to keep the surface area small.
}

function _renderGlobalSearchEmpty() {
  const container = document.getElementById('global-search-results');
  if (!container) return;
  container.innerHTML = '<div class="global-search-empty">Type to search across every section.</div>';
}

function runGlobalSearch(query) {
  const container = document.getElementById('global-search-results');
  if (!container) return;
  const q = (query || '').toLowerCase();
  if (!q) { _renderGlobalSearchEmpty(); return; }

  // ── Stockroom workflow shortcuts ────────────────────────────────────────
  // Typing "order"/"orders"/"ordered" opens a chooser → bulk-order list.
  // Typing "delivered"/"deliver"/"delivery" opens the pending-delivery list.
  // Both are render-only intercepts — they hijack the results panel and
  // leave the input alone, so the user can clear the input to dismiss.
  // The trigger is exact-match against the trimmed (lowercased) query,
  // optionally followed by a colon (`order:`) so typing flows naturally.
  // We also strip any trailing whitespace already in q via the trim.
  const qTrim = q.trim().replace(/[:\s]+$/, '');
  if (_OMNIBOX_ORDER_TRIGGERS.has(qTrim)) {
    _renderOmniboxOrderPanel(container);
    return;
  }
  if (_OMNIBOX_DELIVERY_TRIGGERS.has(qTrim)) {
    _renderOmniboxDeliveryPanel(container);
    return;
  }

  // Filter options come from _GLOBAL_SEARCH state, toggled by the user
  // via the bottom filter bar. Each searcher returns a { results, hasMore,
  // deletedCount, archivedCount } envelope; the counts let us show the
  // filter bar only when there's something to reveal.
  const opts = {
    includeArchived: _GLOBAL_SEARCH.includeArchived,
    includeDeleted:  _GLOBAL_SEARCH.includeDeleted,
  };

  // Run each section searcher. Each returns { results, hasMore } where
  // `results` is already capped at _SEARCH_RESULTS_PER_SECTION.
  const byKey = {
    stock:             _searchStockroom(q, opts),
    grocery:           _searchGroceries(q, opts),
    notes:             _searchNotes(q, opts),
    reminders:         _searchReminders(q, opts),
    budget:            _searchBudget(q, opts),
    savings:           _searchSavings(q, opts),
    report:            _searchStaticView(q, 'report'),
    billing:           _searchStaticView(q, 'billing'),
    'account-security':_searchStaticView(q, 'account-security'),
    accessibility:     _searchAccessibility(q),
    settings:          _searchStaticView(q, 'settings'),
  };

  // Pin current view's section to the top of the list. Map the current
  // view name (which may be 'shopping' inside the stock view) to the
  // matching section key.
  const currentSectionKey = _searchSectionForView(_currentView || 'stock');
  const order = [currentSectionKey, ..._GLOBAL_SEARCH.sectionOrder.filter(k => k !== currentSectionKey)];

  // Aggregate hidden counts across all sections so the filter bar can
  // show a single "Include archived (3) · Include deleted (1)" summary.
  let totalArchived = 0;
  let totalDeleted = 0;
  for (const key of order) {
    const s = byKey[key];
    if (!s) continue;
    totalArchived += s.archivedCount || 0;
    totalDeleted  += s.deletedCount  || 0;
  }

  const blocks = [];
  for (const key of order) {
    const section = byKey[key];
    if (!section || !section.results || !section.results.length) continue;
    blocks.push(_renderSearchSection(key, section, key === currentSectionKey, q));
  }

  const filterBar = _renderSearchFilterBar(totalArchived, totalDeleted);

  if (!blocks.length) {
    // No matches in the current filter set. If unfiltered counts exist,
    // tell the user explicitly so they don't think the app is broken.
    const hiddenHint = (totalArchived || totalDeleted)
      ? ` · ${totalArchived ? `${totalArchived} archived` : ''}${(totalArchived && totalDeleted) ? ', ' : ''}${totalDeleted ? `${totalDeleted} deleted` : ''} hidden`
      : '';
    container.innerHTML =
      `<div class="global-search-empty">No matches for <strong>${esc(query)}</strong>${hiddenHint}.</div>` +
      filterBar;
    return;
  }
  container.innerHTML = blocks.join('') + filterBar;
}

// Render the bottom filter bar showing toggle checkboxes for archived /
// deleted results. Hidden entirely when both counts are zero AND neither
// flag is currently on. When a flag IS on, its checkbox stays visible
// (even if count is 0 because nothing's being hidden right now) so the
// user can untick to re-hide. Each box re-runs the search via
// _toggleSearchFilter so the panel updates in place without losing
// scroll or query state.
function _renderSearchFilterBar(archivedCount, deletedCount) {
  const showArchived = archivedCount > 0 || !!_GLOBAL_SEARCH.includeArchived;
  const showDeleted  = deletedCount  > 0 || !!_GLOBAL_SEARCH.includeDeleted;
  if (!showArchived && !showDeleted) return '';
  const aChecked = _GLOBAL_SEARCH.includeArchived ? 'checked' : '';
  const dChecked = _GLOBAL_SEARCH.includeDeleted  ? 'checked' : '';
  // Show "(N hidden)" only when there are actual matches we're filtering.
  // When the flag is on the count is naturally 0, in which case we drop
  // the count entirely.
  const aCount = archivedCount > 0 ? ` <em>(${archivedCount})</em>` : '';
  const dCount = deletedCount  > 0 ? ` <em>(${deletedCount})</em>`  : '';
  const aBox = showArchived ? `
    <label class="global-search-filter-box">
      <input type="checkbox" ${aChecked} onchange="_toggleSearchFilter('archived', this.checked)">
      <span>Include archived${aCount}</span>
    </label>` : '';
  const dBox = showDeleted ? `
    <label class="global-search-filter-box">
      <input type="checkbox" ${dChecked} onchange="_toggleSearchFilter('deleted', this.checked)">
      <span>Include deleted${dCount}</span>
    </label>` : '';
  return `<div class="global-search-filter-bar">
    <div class="global-search-filter-label">Filters</div>
    ${aBox}${dBox}
  </div>`;
}

// Flip a filter flag and re-run the current search. Triggered by the
// checkbox onchange inside the filter bar. Preserves scroll position
// of the results container so toggling doesn't jump the user away from
// where they were reading. Routes through _runOmniboxSearch when the
// omnibox is the active UI (handles the ID swap so the rerender lands
// in the right container).
function _toggleSearchFilter(kind, checked) {
  if (kind === 'archived')  _GLOBAL_SEARCH.includeArchived = !!checked;
  else if (kind === 'deleted') _GLOBAL_SEARCH.includeDeleted = !!checked;

  // Determine which UI is active. The omnibox owns _OMNIBOX.active when
  // expanded; that's the signal to route via _runOmniboxSearch which
  // handles the id-swap dance. Otherwise we hit runGlobalSearch direct.
  const useOmnibox = (typeof _OMNIBOX !== 'undefined') && _OMNIBOX && _OMNIBOX.active;
  let q = '';
  if (useOmnibox) {
    const omniboxInput = document.getElementById('omnibox-input');
    q = (omniboxInput && omniboxInput.value) || '';
  } else {
    const modalInput = document.getElementById('global-search-input');
    q = (modalInput && modalInput.value) || '';
  }
  if (!q) return;

  // Preserve scroll across the re-render.
  const container = useOmnibox
    ? document.getElementById('omnibox-results')
    : document.getElementById('global-search-results');
  const prevScroll = container ? container.scrollTop : 0;

  if (useOmnibox && typeof _runOmniboxSearch === 'function') {
    _runOmniboxSearch(q);
  } else {
    runGlobalSearch(q);
  }
  if (container) container.scrollTop = prevScroll;
}

// Map a view name (which may be a sub-view like 'shopping') back to the
// section key used by the search. 'shopping' is part of Stockroom for
// purposes of search-result ordering.
function _searchSectionForView(viewName) {
  if (!viewName) return 'stock';
  if (viewName === 'shopping') return 'stock';
  if (_GLOBAL_SEARCH.sectionMeta[viewName]) return viewName;
  return 'stock';
}

function _renderSearchSection(sectionKey, section, isCurrent, query) {
  const meta = _GLOBAL_SEARCH.sectionMeta[sectionKey];
  const titleCls = isCurrent ? 'global-search-section-title current' : 'global-search-section-title';
  const titleSuffix = isCurrent ? ' · current tab' : '';
  const rows = section.results.map(r => _renderSearchRow(r, sectionKey, query)).join('');
  const moreLine = section.hasMore
    ? `<div class="global-search-section-more">+ more matches — refine your search to narrow</div>`
    : '';
  return `<div class="global-search-section">
    <div class="${titleCls}"><svg class="icon" aria-hidden="true"><use href="#${meta.icon}"></use></svg> ${esc(meta.label)}${titleSuffix}</div>
    ${rows}
    ${moreLine}
  </div>`;
}

function _renderSearchRow(r, sectionKey, query) {
  // r.id is encoded with sectionKey to keep it unique across sections so the
  // tap handler can route correctly. We pass through view + target separately.
  // Chip-style records (direct-hit Budget accounts / categories, and the
  // inline accessibility controls) get richer rendering. Plain rows fall
  // through to the standard render below.
  if (r.chip === 'account')  return _renderSearchAccountChip(r, query);
  if (r.chip === 'category') return _renderSearchCategoryChip(r, query);
  if (r.chip === 'accessibility-theme')     return _renderSearchAccessibilityThemeChip();
  if (r.chip === 'accessibility-textscale') return _renderSearchAccessibilityTextScaleChip();
  const titleHTML = _highlightMatch(r.title || '', query);
  const subHTML   = r.sub ? _highlightMatch(r.sub, query) : '';
  // State badge for archived / deleted matches — surfaced because the
  // filter bar at the bottom of the panel made them visible. Helps the
  // user see WHY a result looks unfamiliar before tapping it.
  let stateBadge = '';
  let stateCls   = '';
  if (r.state === 'archived') {
    stateBadge = '<span class="search-row-state-badge state-archived" title="Archived">archived</span>';
    stateCls   = ' is-state-archived';
  } else if (r.state === 'deleted') {
    stateBadge = '<span class="search-row-state-badge state-deleted" title="Deleted">deleted</span>';
    stateCls   = ' is-state-deleted';
  }
  // Grocery aggregation: when an item appeared in multiple lists, the
  // searcher merges them and includes `otherLists`. Render an expandable
  // pill below the sub-line. Aggregation only fires for grocery section.
  let aggregateBlock = '';
  if (sectionKey === 'grocery' && r.otherLists && r.otherLists.length) {
    const n = r.otherLists.length;
    // Stash the other-lists payload on a data attribute for the toggle
    // handler. JSON-escaping a small {id,name,deleted} array. Names can
    // contain quotes/apostrophes so we escape via JSON then HTML.
    const payloadJson = JSON.stringify(r.otherLists).replace(/"/g, '&quot;');
    aggregateBlock = `
      <button class="search-row-more-lists" data-other-lists="${payloadJson}"
              onclick="event.stopPropagation();_toggleSearchRowMoreLists(this);">
        <svg aria-hidden="true"><use href="#i-chevron-down"></use></svg>
        Also in ${n} other ${n === 1 ? 'list' : 'lists'}
      </button>`;
  }
  // Inline onclick keeps things simple — no event delegation needed because
  // result rows are re-rendered on every keystroke after debounce.
  return `<div class="global-search-row${stateCls}" onclick="_navigateToSearchResult(${JSON.stringify({s:sectionKey, v:r.view, t:r.target}).replace(/"/g,'&quot;')})">
    <svg class="global-search-row-icon" aria-hidden="true"><use href="#${esc(r.icon || _GLOBAL_SEARCH.sectionMeta[sectionKey].icon)}"></use></svg>
    <div class="global-search-row-body">
      <div class="global-search-row-title">${titleHTML}${stateBadge}</div>
      ${subHTML ? `<div class="global-search-row-sub">${subHTML}</div>` : ''}
      ${aggregateBlock}
    </div>
  </div>`;
}

// Toggle the expanded "other lists" panel below an aggregated grocery row.
// Reads the payload from the button's data attribute, builds the panel
// once on first expand, then just toggles its display on subsequent taps.
// Each list name is tappable to navigate directly to that list.
function _toggleSearchRowMoreLists(btn) {
  if (!btn) return;
  const row = btn.closest('.global-search-row');
  if (!row) return;
  let panel = row.querySelector('.search-row-other-lists');
  if (panel) {
    const isOpen = panel.style.display !== 'none';
    panel.style.display = isOpen ? 'none' : '';
    btn.classList.toggle('expanded', !isOpen);
    return;
  }
  // Build panel
  let other;
  try { other = JSON.parse(btn.getAttribute('data-other-lists') || '[]'); } catch (_) { other = []; }
  if (!other.length) return;
  const items = other.map(o => {
    const cls = o.deleted ? ' is-state-deleted' : '';
    // Navigate to the list — the grocery view supports a target id for the
    // list itself. _navigateToSearchResult routes view='grocery', target=listId.
    const navPayload = JSON.stringify({ s: 'grocery', v: 'grocery', t: o.id }).replace(/"/g, '&quot;');
    return `<div class="search-row-other-list-item${cls}" onclick="event.stopPropagation();_navigateToSearchResult(${navPayload})">
      <svg aria-hidden="true"><use href="#i-shopping-cart"></use></svg>
      <span>${esc(o.name || '(unnamed list)')}</span>
      ${o.deleted ? '<span class="search-row-state-badge state-deleted">deleted</span>' : ''}
    </div>`;
  }).join('');
  panel = document.createElement('div');
  panel.className = 'search-row-other-lists';
  panel.innerHTML = items;
  // Insert after the button
  btn.parentNode.insertBefore(panel, btn.nextSibling);
  btn.classList.add('expanded');
}

// ── Search chips: rich inline cards for direct-hit Budget entities ─────────
// Account chip — shows balance + "as of" date, plus Update Balance and Edit
// buttons that fire Budget module functions directly. Tapping the title
// area falls through to the normal navigate-to-budget-tab behaviour.
// Category chip — shows last 3 transactions (each tappable to edit), plus
// Add new / View all / Edit category actions.
//
// Buttons inside chips dismiss the omnibox via _searchChipAction so that
// when a modal opens, the omnibox backdrop blur is already gone. Tapping
// the chip's title area still navigates via _navigateToSearchResult so
// the chip respects the same "find and flash" pattern as plain rows.

function _renderSearchAccountChip(r, query) {
  const acc = (typeof budgetAccounts !== 'undefined' && Array.isArray(budgetAccounts))
    ? budgetAccounts.find(a => a.id === r.target)
    : null;
  if (!acc) {
    // Account vanished between render passes — fall back to a plain row.
    return _renderSearchRow({ ...r, chip: null }, 'budget', query);
  }
  const titleHTML = _highlightMatch(acc.name || '', query);
  const balanceStr = _money(acc.balance);
  const asOf = acc.balanceAsOf ? `as of ${esc(acc.balanceAsOf)}` : 'no update recorded';
  const idJson = JSON.stringify(acc.id).replace(/"/g, '&quot;');
  return `<div class="search-chip search-chip-account">
    <div class="search-chip-head" onclick="_navigateToSearchResult(${JSON.stringify({s:'budget', v:'budget', t:acc.id}).replace(/"/g,'&quot;')})">
      <svg class="search-chip-icon" aria-hidden="true"><use href="#i-credit-card"></use></svg>
      <div class="search-chip-head-body">
        <div class="search-chip-title">${titleHTML}</div>
        <div class="search-chip-sub">Account · ${balanceStr} · ${asOf}</div>
      </div>
    </div>
    <div class="search-chip-actions">
      <button class="search-chip-btn" onclick="_searchChipAction('openUpdateBalanceModal', ${idJson})">
        <svg aria-hidden="true"><use href="#i-refresh-cw"></use></svg>
        Update balance
      </button>
      <button class="search-chip-btn" onclick="_searchChipAction('openAccountEditor', ${idJson})">
        <svg aria-hidden="true"><use href="#i-pencil"></use></svg>
        Edit
      </button>
    </div>
  </div>`;
}

function _renderSearchCategoryChip(r, query) {
  const cat = (typeof budgetCategories !== 'undefined' && Array.isArray(budgetCategories))
    ? budgetCategories.find(c => c.id === r.target)
    : null;
  if (!cat) {
    return _renderSearchRow({ ...r, chip: null }, 'budget', query);
  }
  const titleHTML = _highlightMatch(cat.name || '', query);
  const idJson = JSON.stringify(cat.id).replace(/"/g, '&quot;');

  // Pull the 3 most recent transactions for this category across all months.
  // transactions is {yyyymm: {txId: tx}}. We flatten, filter, sort, slice.
  let recent = [];
  if (typeof transactions !== 'undefined' && transactions && typeof transactions === 'object') {
    for (const ym of Object.keys(transactions)) {
      const monthTxs = transactions[ym] || {};
      for (const txId of Object.keys(monthTxs)) {
        const tx = monthTxs[txId];
        if (tx && tx.categoryId === cat.id) recent.push(tx);
      }
    }
    // Sort by date desc, then by createdAt desc as tiebreaker.
    recent.sort((a, b) => {
      const ad = a.date || ''; const bd = b.date || '';
      if (ad !== bd) return ad < bd ? 1 : -1;
      const ac = a.createdAt || ''; const bc = b.createdAt || '';
      return ac < bc ? 1 : -1;
    });
    recent = recent.slice(0, 3);
  }

  const txRows = recent.length ? recent.map(tx => {
    const txIdJson = JSON.stringify(tx.id).replace(/"/g, '&quot;');
    const dateStr = (typeof _shortDate === 'function') ? _shortDate(tx.date) : esc(tx.date || '');
    const whereStr = esc(tx.where || '—');
    const amtStr = _money(tx.amount);
    return `<div class="search-chip-tx" onclick="_searchChipAction('openSpendTxEditor', ${txIdJson})">
      <div class="search-chip-tx-date">${dateStr}</div>
      <div class="search-chip-tx-where">${whereStr}</div>
      <div class="search-chip-tx-amount">${amtStr}</div>
    </div>`;
  }).join('') : `<div class="search-chip-empty">No transactions yet</div>`;

  // Category color dot, falling back to accent
  const dotColor = esc(cat.color || 'var(--accent)');

  return `<div class="search-chip search-chip-category">
    <div class="search-chip-head" onclick="_navigateToSearchResult(${JSON.stringify({s:'budget', v:'budget', t:cat.id}).replace(/"/g,'&quot;')})">
      <span class="search-chip-dot" style="background:${dotColor}"></span>
      <div class="search-chip-head-body">
        <div class="search-chip-title">${titleHTML}</div>
        <div class="search-chip-sub">${recent.length === 0 ? 'Spend category · no transactions yet' : `Spend category · last ${recent.length} transaction${recent.length === 1 ? '' : 's'}`}</div>
      </div>
    </div>
    <div class="search-chip-txlist">${txRows}</div>
    <div class="search-chip-actions">
      <button class="search-chip-btn" onclick="_searchChipAddSpend(${idJson})">
        <svg aria-hidden="true"><use href="#i-plus"></use></svg>
        Add new
      </button>
      <button class="search-chip-btn" onclick="_searchChipViewAllSpend(${idJson})">
        <svg aria-hidden="true"><use href="#i-list"></use></svg>
        View all
      </button>
      <button class="search-chip-btn" onclick="_searchChipAction('openBudgetCategoryEditor', ${idJson})">
        <svg aria-hidden="true"><use href="#i-pencil"></use></svg>
        Edit
      </button>
    </div>
  </div>`;
}

// Dismiss the omnibox before opening a modal-style action. Wraps the call
// in a try/catch so a missing function doesn't strand the user with a
// half-closed UI. Modal opens immediately after the omnibox collapse so
// the focus transition feels seamless on mobile.
function _searchChipAction(fnName, ...args) {
  try { closeGlobalSearch(); } catch (_) {}
  if (typeof collapseOmnibox === 'function') {
    try { collapseOmnibox(); } catch (_) {}
  }
  const fn = (typeof window !== 'undefined') ? window[fnName] : null;
  if (typeof fn !== 'function') {
    console.warn('[search-chip] action not available:', fnName);
    return;
  }
  // Defer one tick so the omnibox collapse animation has begun before the
  // modal renders on top; avoids a brief overlay+modal stacking flash.
  setTimeout(() => {
    try { fn(...args); } catch (e) { console.error('[search-chip] action failed:', fnName, e); }
  }, 30);
}

// "Add new" inside a category chip — opens the quick-add spend modal
// pre-targeted at the chip's category. openQuickAddSpend itself takes no
// args; we set a hint that quickAddInputChanged reads when the user types,
// so the parsed transaction lands in the right category by default.
function _searchChipAddSpend(catId) {
  try { closeGlobalSearch(); } catch (_) {}
  if (typeof collapseOmnibox === 'function') {
    try { collapseOmnibox(); } catch (_) {}
  }
  // Stash the target category so the quick-add modal can default to it.
  // Cleared on modal close (or next open). Lives on window so budget.js
  // can read it without a circular import.
  try { window._searchChipPrefillCategoryId = catId; } catch (_) {}
  setTimeout(() => {
    if (typeof openQuickAddSpend === 'function') {
      try { openQuickAddSpend(); } catch (e) { console.error(e); }
    }
  }, 30);
}

// "View all" inside a category chip — switches to the Budget tab's Spend
// panel with the spend list filtered to this category. Works whether or
// not the user is already on the Budget tab; navTo is a no-op when the
// current view already matches.
function _searchChipViewAllSpend(catId) {
  try { closeGlobalSearch(); } catch (_) {}
  if (typeof collapseOmnibox === 'function') {
    try { collapseOmnibox(); } catch (_) {}
  }
  try {
    // budget.js owns these globals — set them before navTo so the first
    // render lands on the right panel with the filter applied.
    if (typeof _spendCategoryFilter !== 'undefined') _spendCategoryFilter = catId;
    if (typeof _budgetActivePanel  !== 'undefined') _budgetActivePanel  = 'spend';
  } catch (_) { /* names may not exist if budget.js failed to load */ }
  try { navTo('budget'); } catch (_) {}
}

// ═══════════════════════════════════════════════════════════════════════════
//  OMNIBOX — Stockroom workflow panels (Order / Delivered)
//
//  Typing `order` (or order/ordered/orders) → chooser pills (7 days, 30
//  days, Critical, Low) → list of qualifying items with per-row checkbox
//  + editable qty + bottom-right confirm button that bulk-logs orders.
//
//  Typing `delivered` → items currently in pending-delivery state, with
//  per-row instant Delivered button. Each row mutates after the action:
//  pending → Start using → done (row disappears). Each action triggers a
//  data save + sync immediately, matching the card-button behaviour.
//
//  Both panels render directly into the results container (whichever the
//  active UI is — the id-swap dance done by _runOmniboxSearch means the
//  same #global-search-results selector works for both).
// ═══════════════════════════════════════════════════════════════════════════

// ── Helpers ────────────────────────────────────────────────────────────────

// Items eligible for ordering, classified for the four chooser pills.
// Excludes: deleted, archived, already-ordered (has any pendingDelivery
// log), and items lacking enough data to compute stock.
function _omniboxOrderClassify() {
  const out = { critical: [], low: [], in7: [], in30: [], counts: { critical: 0, low: 0, in7: 0, in30: 0 } };
  if (typeof items === 'undefined' || !Array.isArray(items)) return out;
  for (const item of items) {
    if (item._deletedAt || item._archived) continue;
    // Skip items already in the order pipeline — bulk-ordering them again
    // would create duplicate pending logs.
    const hasPending = (item.logs || []).some(l => l.pendingDelivery);
    if (hasPending) continue;
    const stock = (typeof calcStock === 'function') ? calcStock(item) : null;
    if (!stock) continue; // no logs yet → no estimate, skip
    const status = (typeof getStatus === 'function') ? getStatus(stock.pct, null, item) : null;
    if (status === 'critical') { out.critical.push({ item, stock, status }); out.counts.critical++; }
    if (status === 'warn')     { out.low.push({ item, stock, status });      out.counts.low++; }
    if (stock.daysLeft != null && stock.daysLeft <= 7)  { out.in7.push({ item, stock, status });  out.counts.in7++; }
    if (stock.daysLeft != null && stock.daysLeft <= 30) { out.in30.push({ item, stock, status }); out.counts.in30++; }
  }
  // Sort within each bucket: lowest daysLeft first (most urgent surfaced).
  const byUrgency = (a, b) => (a.stock.daysLeft ?? 0) - (b.stock.daysLeft ?? 0);
  out.critical.sort(byUrgency);
  out.low.sort(byUrgency);
  out.in7.sort(byUrgency);
  out.in30.sort(byUrgency);
  return out;
}

// Items with a pending delivery log (ordered, awaiting arrival), and
// items delivered but not yet started using (need a Start-using decision).
// Both surface in the delivery panel — the row's button reflects which
// stage it's in.
function _omniboxDeliveryClassify() {
  const out = { pending: [], readyToStart: [] };
  if (typeof items === 'undefined' || !Array.isArray(items)) return out;
  for (const item of items) {
    if (item._deletedAt || item._archived) continue;
    const logs = item.logs || [];
    const hasPending = logs.some(l => l.pendingDelivery);
    if (hasPending) {
      // Find the most recent pending log for the displayed "ordered" date
      const pendingLog = [...logs].reverse().find(l => l.pendingDelivery);
      out.pending.push({ item, pendingLog });
      continue;
    }
    // Delivered but no start date → ready to start using
    const lastDelivered = [...logs].reverse().find(l => !l.pendingDelivery && l.deliveredDate);
    if (lastDelivered && !item.startedUsing) {
      out.readyToStart.push({ item, lastDelivered });
    }
  }
  // Sort by ordered/delivered date (oldest first — they've been waiting longest)
  out.pending.sort((a, b) => {
    const ad = a.pendingLog?.date || ''; const bd = b.pendingLog?.date || '';
    return ad < bd ? -1 : ad > bd ? 1 : 0;
  });
  out.readyToStart.sort((a, b) => {
    const ad = a.lastDelivered?.deliveredDate || ''; const bd = b.lastDelivered?.deliveredDate || '';
    return ad < bd ? -1 : ad > bd ? 1 : 0;
  });
  return out;
}

// Format a days-left number using the same conventions as the cards.
function _omniboxDaysLeftLabel(daysLeft) {
  if (daysLeft == null || isNaN(daysLeft)) return '';
  if (daysLeft === 0) return 'today';
  if (daysLeft === 1) return '1 day';
  if (daysLeft < 30) return `${daysLeft} days`;
  const months = Math.round(daysLeft / 30);
  return `${months} month${months === 1 ? '' : 's'}`;
}

// ── ORDER PANEL ────────────────────────────────────────────────────────────

function _renderOmniboxOrderPanel(container) {
  const classified = _omniboxOrderClassify();
  const filter = _OMNIBOX_ORDER.filter;
  const totals = classified.counts;

  // Empty-state: no items qualify in any bucket
  const totalEligible = totals.critical + totals.low + totals.in7 + totals.in30;
  if (totalEligible === 0) {
    container.innerHTML = `
      <div class="omnibox-workflow-panel">
        <div class="omnibox-workflow-header">
          <svg class="icon icon-md" aria-hidden="true"><use href="#i-shopping-cart"></use></svg>
          <div>
            <div class="omnibox-workflow-title">Order items</div>
            <div class="omnibox-workflow-sub">Nothing needs ordering right now — everything is well-stocked.</div>
          </div>
        </div>
        <div class="omnibox-workflow-footer">
          <button class="btn btn-ghost" onclick="_omniboxOrderDismiss()">Done</button>
        </div>
      </div>`;
    return;
  }

  // Chooser stage — no filter picked yet
  if (!filter) {
    const pill = (key, label, n, icon) => {
      const disabled = n === 0 ? 'disabled' : '';
      return `<button class="omnibox-workflow-pill" ${disabled} onclick="_omniboxOrderPickFilter('${key}')">
        <svg class="icon" aria-hidden="true"><use href="#${icon}"></use></svg>
        <span class="omnibox-workflow-pill-label">${label}</span>
        <span class="omnibox-workflow-pill-count">${n}</span>
      </button>`;
    };
    container.innerHTML = `
      <div class="omnibox-workflow-panel">
        <div class="omnibox-workflow-header">
          <svg class="icon icon-md" aria-hidden="true"><use href="#i-shopping-cart"></use></svg>
          <div>
            <div class="omnibox-workflow-title">Order items</div>
            <div class="omnibox-workflow-sub">Pick what to surface. Bulk-ordering uses default qty &amp; no price — for accurate price history, use Stockroom cards.</div>
          </div>
        </div>
        <div class="omnibox-workflow-chooser">
          ${pill('critical', 'Critical', totals.critical, 'i-alert-triangle')}
          ${pill('low',      'Low stock', totals.low, 'i-alert-triangle')}
          ${pill('in7',      'Next 7 days',  totals.in7, 'i-clock')}
          ${pill('in30',     'Next 30 days', totals.in30, 'i-calendar-days')}
        </div>
        <div class="omnibox-workflow-footer">
          <button class="btn btn-ghost" onclick="_omniboxOrderDismiss()">Cancel</button>
        </div>
      </div>`;
    return;
  }

  // List stage — show items in the chosen bucket
  const bucket = filter === 'critical' ? classified.critical
              : filter === 'low'       ? classified.low
              : filter === 'in7'       ? classified.in7
              : filter === 'in30'      ? classified.in30
              : [];
  const filterLabel = filter === 'critical' ? 'Critical'
                   : filter === 'low'       ? 'Low stock'
                   : filter === 'in7'       ? 'Next 7 days'
                   : filter === 'in30'      ? 'Next 30 days'
                   : '';

  // Initialise row state for any items not yet tracked (first render or
  // newly-appearing items after a re-render). Default: selected, qty = default.
  for (const { item } of bucket) {
    if (!_OMNIBOX_ORDER.rows.has(item.id)) {
      _OMNIBOX_ORDER.rows.set(item.id, {
        selected: true,
        qty: (item.qty && item.qty > 0) ? item.qty : 1,
      });
    }
  }

  const rows = bucket.map(({ item, stock, status }) => {
    const row = _OMNIBOX_ORDER.rows.get(item.id);
    const isSel = row.selected;
    const qty = row.qty;
    const daysLabel = _omniboxDaysLeftLabel(stock.daysLeft);
    const derivedStore = (typeof urlToStoreName === 'function' ? urlToStoreName(item.url || '') : '') || '';
    const storeLabel = item.store || derivedStore || '';
    const url = (item.url && item.url.trim()) ? item.url.trim() : '';
    // Buy now link when the item has an online URL — opens in a new tab,
    // stops propagation so the link click doesn't toggle the row checkbox
    // or trigger any panel re-render side-effects. Offline-only items
    // (no url) show the store name as plain text on the sub-line below.
    const buyNow = url
      ? ` · <a class="omnibox-workflow-row-buylink" href="${esc(url)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">Buy now <svg aria-hidden="true"><use href="#i-external-link"></use></svg></a>`
      : (storeLabel ? ' · ' + esc(storeLabel) : '');
    const statusBadge = status === 'critical'
      ? '<span class="omnibox-workflow-row-badge state-critical">critical</span>'
      : status === 'warn'
        ? '<span class="omnibox-workflow-row-badge state-low">low</span>'
        : '';
    const idJson = JSON.stringify(item.id).replace(/"/g, '&quot;');
    return `<div class="omnibox-workflow-row ${isSel ? 'is-selected' : ''}">
      <label class="omnibox-workflow-row-check">
        <input type="checkbox" ${isSel ? 'checked' : ''} onchange="_omniboxOrderToggleRow(${idJson}, this.checked)">
      </label>
      <div class="omnibox-workflow-row-body">
        <div class="omnibox-workflow-row-title">${esc(item.name || '(untitled)')} ${statusBadge}</div>
        <div class="omnibox-workflow-row-sub">${daysLabel ? esc(daysLabel) + ' left' : 'low stock'}${buyNow}</div>
      </div>
      <div class="omnibox-workflow-row-qty">
        <label>Qty</label>
        <input type="number" min="0.1" step="0.1" value="${qty}" onchange="_omniboxOrderSetQty(${idJson}, this.value)" onclick="event.stopPropagation()">
      </div>
    </div>`;
  }).join('');

  // Selected count for the confirm button
  let selectedCount = 0;
  for (const { item } of bucket) {
    if (_OMNIBOX_ORDER.rows.get(item.id)?.selected) selectedCount++;
  }
  const confirmDisabled = selectedCount === 0 ? 'disabled' : '';

  container.innerHTML = `
    <div class="omnibox-workflow-panel">
      <div class="omnibox-workflow-header">
        <button class="omnibox-workflow-back" onclick="_omniboxOrderBack()" aria-label="Back">
          <svg aria-hidden="true"><use href="#i-arrow-left"></use></svg>
        </button>
        <div>
          <div class="omnibox-workflow-title">Order — ${filterLabel}</div>
          <div class="omnibox-workflow-sub">${bucket.length} item${bucket.length === 1 ? '' : 's'} · adjust qty if needed, untick to skip</div>
        </div>
      </div>
      <div class="omnibox-workflow-list">${rows}</div>
      <div class="omnibox-workflow-footer">
        <button class="btn btn-ghost" onclick="_omniboxOrderDismiss()">Cancel</button>
        <button class="btn btn-primary" id="omnibox-order-confirm-btn" ${confirmDisabled} onclick="_omniboxOrderConfirm('${filter}')">
          Order ${selectedCount} item${selectedCount === 1 ? '' : 's'}
        </button>
      </div>
    </div>`;
}

// Pick a chooser pill — switch to list stage.
function _omniboxOrderPickFilter(filter) {
  _OMNIBOX_ORDER.filter = filter;
  // Reset per-row state when entering a new bucket so previous selections
  // from a different filter don't carry over.
  _OMNIBOX_ORDER.rows.clear();
  const c = _omniboxResultsContainer();
  if (c) _renderOmniboxOrderPanel(c);
}

// Back from list stage → chooser.
function _omniboxOrderBack() {
  _OMNIBOX_ORDER.filter = null;
  _OMNIBOX_ORDER.rows.clear();
  const c = _omniboxResultsContainer();
  if (c) _renderOmniboxOrderPanel(c);
}

// Toggle a row's selected state.
function _omniboxOrderToggleRow(itemId, checked) {
  const row = _OMNIBOX_ORDER.rows.get(itemId);
  if (row) {
    row.selected = !!checked;
    // Re-render to refresh the bottom count + button label
    const c = _omniboxResultsContainer();
    if (c) _renderOmniboxOrderPanel(c);
  }
}

// Edit a row's qty.
function _omniboxOrderSetQty(itemId, val) {
  const row = _OMNIBOX_ORDER.rows.get(itemId);
  if (!row) return;
  const n = parseFloat(val);
  if (!isNaN(n) && n > 0) row.qty = n;
  // No re-render needed — qty doesn't affect any UI elsewhere in the panel
}

// Confirm — bulk-log purchases for all selected rows. Each logged purchase
// gets today's date, the user-edited qty, no price, and the item's default
// store. Matches ofSave('purchase') shape so sync/calc paths are identical.
async function _omniboxOrderConfirm(filter) {
  if (typeof canWrite === 'function' && !canWrite('stockroom')) {
    if (typeof showLockBanner === 'function') showLockBanner('stockroom');
    return;
  }
  // Re-classify to pick up any items that changed since render (paranoid)
  const classified = _omniboxOrderClassify();
  const bucket = filter === 'critical' ? classified.critical
              : filter === 'low'       ? classified.low
              : filter === 'in7'       ? classified.in7
              : filter === 'in30'      ? classified.in30
              : [];

  let ordered = 0;
  const dateToday = (typeof today === 'function') ? today() : new Date().toISOString().slice(0, 10);
  for (const { item } of bucket) {
    const row = _OMNIBOX_ORDER.rows.get(item.id);
    if (!row || !row.selected) continue;
    const qty = (row.qty && row.qty > 0) ? row.qty : 1;
    const storeVal = item.store || (typeof urlToStoreName === 'function' ? urlToStoreName(item.url || '') : '') || '';
    if (!item.logs) item.logs = [];
    item.logs.push({
      id:              (typeof uid === 'function' ? uid() : Date.now().toString(36) + Math.random().toString(36).slice(2, 7)),
      date:            dateToday,
      qty,
      price:           '', // bulk: no price (the trade-off Pete's been told about in the header copy)
      store:           storeVal,
      pendingDelivery: true,
    });
    item.logs.sort((a, b) => new Date(a.date) - new Date(b.date));
    item.ordered   = true;
    item.orderedAt = new Date().toISOString();
    if (typeof touchField === 'function') touchField(item, 'logs', 'ordered', 'orderedAt');
    ordered++;
  }
  if (ordered === 0) {
    if (typeof toast === 'function') toast('Nothing selected to order');
    return;
  }
  if (typeof saveData === 'function') await saveData();
  if (typeof scheduleRender === 'function') scheduleRender('grid', 'dashboard', 'shopping');
  if (typeof syncAll === 'function') setTimeout(syncAll, 400);
  if (typeof toast === 'function') {
    toast(`Logged ${ordered} order${ordered === 1 ? '' : 's'} — tap Delivered when they arrive`);
  }
  // Reset state and dismiss
  _OMNIBOX_ORDER.filter = null;
  _OMNIBOX_ORDER.rows.clear();
  _omniboxOrderDismiss();
}

// Dismiss the workflow panel and the omnibox.
function _omniboxOrderDismiss() {
  _OMNIBOX_ORDER.filter = null;
  _OMNIBOX_ORDER.rows.clear();
  // Clear inputs so a re-open starts clean
  const inp1 = document.getElementById('omnibox-input');
  if (inp1) inp1.value = '';
  const inp2 = document.getElementById('global-search-input');
  if (inp2) inp2.value = '';
  try { closeGlobalSearch(); } catch (_) {}
  if (typeof collapseOmnibox === 'function') {
    try { collapseOmnibox(); } catch (_) {}
  }
}

// ── DELIVERY PANEL ─────────────────────────────────────────────────────────

function _renderOmniboxDeliveryPanel(container) {
  const c = _omniboxDeliveryClassify();
  const totalRows = c.pending.length + c.readyToStart.length;

  if (totalRows === 0) {
    container.innerHTML = `
      <div class="omnibox-workflow-panel">
        <div class="omnibox-workflow-header">
          <svg class="icon icon-md" aria-hidden="true"><use href="#i-package-check"></use></svg>
          <div>
            <div class="omnibox-workflow-title">Deliveries</div>
            <div class="omnibox-workflow-sub">Nothing waiting to be delivered or started.</div>
          </div>
        </div>
        <div class="omnibox-workflow-footer">
          <button class="btn btn-ghost" onclick="_omniboxOrderDismiss()">Done</button>
        </div>
      </div>`;
    return;
  }

  const rowsPending = c.pending.map(({ item, pendingLog }) => {
    const idJson = JSON.stringify(item.id).replace(/"/g, '&quot;');
    const ordDate = pendingLog?.date ? (typeof _shortDate === 'function' ? _shortDate(pendingLog.date) : esc(pendingLog.date)) : '';
    const storeLabel = pendingLog?.store || item.store || '';
    return `<div class="omnibox-workflow-row is-delivery-pending">
      <div class="omnibox-workflow-row-icon">
        <svg aria-hidden="true"><use href="#i-truck"></use></svg>
      </div>
      <div class="omnibox-workflow-row-body">
        <div class="omnibox-workflow-row-title">${esc(item.name || '(untitled)')}</div>
        <div class="omnibox-workflow-row-sub">Ordered ${ordDate}${storeLabel ? ' · ' + esc(storeLabel) : ''}</div>
      </div>
      <button class="omnibox-workflow-row-btn" onclick="_omniboxMarkDelivered(${idJson})">
        <svg aria-hidden="true"><use href="#i-package-check"></use></svg>
        Delivered
      </button>
    </div>`;
  }).join('');

  const rowsReady = c.readyToStart.map(({ item, lastDelivered }) => {
    const idJson = JSON.stringify(item.id).replace(/"/g, '&quot;');
    const delDate = lastDelivered?.deliveredDate ? (typeof _shortDate === 'function' ? _shortDate(lastDelivered.deliveredDate) : esc(lastDelivered.deliveredDate)) : '';
    return `<div class="omnibox-workflow-row is-delivery-ready">
      <div class="omnibox-workflow-row-icon">
        <svg aria-hidden="true"><use href="#i-package-check"></use></svg>
      </div>
      <div class="omnibox-workflow-row-body">
        <div class="omnibox-workflow-row-title">${esc(item.name || '(untitled)')}</div>
        <div class="omnibox-workflow-row-sub">Delivered ${delDate} · not yet in use</div>
      </div>
      <button class="omnibox-workflow-row-btn btn-start-using" onclick="_omniboxStartUsing(${idJson})">
        <svg aria-hidden="true"><use href="#i-play"></use></svg>
        Start using
      </button>
    </div>`;
  }).join('');

  // Section labels — only show if both groups have items, for clarity
  const showLabels = c.pending.length > 0 && c.readyToStart.length > 0;
  const pendingBlock = c.pending.length > 0
    ? `${showLabels ? '<div class="omnibox-workflow-section-label">Awaiting delivery</div>' : ''}${rowsPending}`
    : '';
  const readyBlock = c.readyToStart.length > 0
    ? `${showLabels ? '<div class="omnibox-workflow-section-label">Delivered — not in use</div>' : ''}${rowsReady}`
    : '';

  container.innerHTML = `
    <div class="omnibox-workflow-panel">
      <div class="omnibox-workflow-header">
        <svg class="icon icon-md" aria-hidden="true"><use href="#i-package-check"></use></svg>
        <div>
          <div class="omnibox-workflow-title">Deliveries</div>
          <div class="omnibox-workflow-sub">${totalRows} item${totalRows === 1 ? '' : 's'} · tap to mark</div>
        </div>
      </div>
      <div class="omnibox-workflow-list">${pendingBlock}${readyBlock}</div>
      <div class="omnibox-workflow-footer">
        <button class="btn btn-ghost" onclick="_omniboxOrderDismiss()">Done</button>
      </div>
    </div>`;
}

// Mark an item as delivered from the panel. Replicates ofSave('delivered')
// with default qty and today's date, no "started now" flag — keeps the
// row alive in the ready-to-start group afterwards so the user can decide
// whether to start using it.
async function _omniboxMarkDelivered(itemId) {
  if (typeof canWrite === 'function' && !canWrite('stockroom')) {
    if (typeof showLockBanner === 'function') showLockBanner('stockroom');
    return;
  }
  const item = items.find(i => i.id === itemId);
  if (!item) return;
  if (!item.logs) item.logs = [];
  const deliveryDate = (typeof today === 'function') ? today() : new Date().toISOString().slice(0, 10);
  const pendingIdx = [...item.logs].map((l, i) => ({ l, i })).reverse().find(({ l }) => l.pendingDelivery)?.i;
  if (pendingIdx !== undefined) {
    const qty = item.logs[pendingIdx].qty || item.qty || 1;
    item.logs[pendingIdx].pendingDelivery = false;
    item.logs[pendingIdx].deliveredDate   = deliveryDate;
    // qty stays as the user-set value from the order step
  } else {
    // Defensive — shouldn't happen since we filtered by hasPending, but
    // if it does, push a fresh delivered log
    item.logs.push({
      id: (typeof uid === 'function' ? uid() : Date.now().toString(36)),
      date: deliveryDate, qty: item.qty || 1, pendingDelivery: false, deliveredDate: deliveryDate,
    });
    item.logs.sort((a, b) => new Date(a.date) - new Date(b.date));
  }
  item.ordered = false;
  item.orderedAt = null;
  // Auto-update stock count like ofSave does
  const lastLog = [...item.logs].reverse().find(l => !l.pendingDelivery);
  const dQty = lastLog?.qty || item.qty || 1;
  if (typeof getProjectedUnitsLeft === 'function') {
    const existing = getProjectedUnitsLeft(item);
    item.stockCount = (existing != null && existing > 0)
      ? Math.round((existing + dQty) * 100) / 100
      : dQty;
  } else {
    item.stockCount = dQty;
  }
  item.stockCountDate = deliveryDate;
  if (typeof touchItem === 'function') touchItem(item);
  if (typeof saveData === 'function') await saveData();
  if (typeof scheduleRender === 'function') scheduleRender('grid', 'dashboard', 'shopping');
  if (typeof syncAll === 'function') setTimeout(syncAll, 400);
  if (typeof toast === 'function') toast('Delivery confirmed ✓');
  // Re-render the panel — the row will now appear under Start-using
  const cont = _omniboxResultsContainer();
  if (cont) _renderOmniboxDeliveryPanel(cont);
}

// Mark an item as in use (sets startedUsing). Row leaves the panel.
async function _omniboxStartUsing(itemId) {
  if (typeof canWrite === 'function' && !canWrite('stockroom')) {
    if (typeof showLockBanner === 'function') showLockBanner('stockroom');
    return;
  }
  const item = items.find(i => i.id === itemId);
  if (!item) return;
  const date = (typeof today === 'function') ? today() : new Date().toISOString().slice(0, 10);
  item.startedUsing = date;
  if (typeof touchField === 'function') touchField(item, 'startedUsing');
  if (typeof saveData === 'function') await saveData();
  if (typeof scheduleRender === 'function') scheduleRender('grid', 'dashboard');
  if (typeof syncAll === 'function') setTimeout(syncAll, 400);
  if (typeof toast === 'function') toast('Start date saved ✓');
  // Re-render — row should disappear from the readyToStart group
  const cont = _omniboxResultsContainer();
  if (cont) _renderOmniboxDeliveryPanel(cont);
}

// Helper: get the active results container. The id-swap dance done by
// _runOmniboxSearch means whichever container is currently in scope
// answers to #global-search-results. If neither is found we bail.
// Helper: get the active results container. Both UIs exist in the DOM at
// the same time (#global-search-results is the legacy modal panel,
// #omnibox-results is the inline omnibox panel). _runOmniboxSearch
// temporarily renames the omnibox container to 'global-search-results'
// for the duration of runGlobalSearch — but by the time a workflow-
// panel button is clicked, the id has been restored. So we route based
// on _OMNIBOX.active: omnibox UI → omnibox-results; otherwise the
// legacy modal. Falls back to either if only one is present.
function _omniboxResultsContainer() {
  const omniboxActive = (typeof _OMNIBOX !== 'undefined') && _OMNIBOX && _OMNIBOX.active;
  if (omniboxActive) {
    return document.getElementById('omnibox-results')
        || document.getElementById('global-search-results');
  }
  return document.getElementById('global-search-results')
      || document.getElementById('omnibox-results');
}


// Wrap query matches in <mark> for visual emphasis. Case-insensitive, plain
// substring — same matcher the searchers use. Pre-escapes the text so any
// user-supplied content (item names, notes) is rendered safely.
function _highlightMatch(text, query) {
  if (!text) return '';
  const escaped = esc(text);
  if (!query) return escaped;
  // Build a case-insensitive regex from the query, with regex metachars
  // escaped so a search for "$10" doesn't error out.
  const safeQ = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  try {
    const re = new RegExp(`(${safeQ})`, 'ig');
    return escaped.replace(re, '<mark>$1</mark>');
  } catch (_) { return escaped; }
}

// Navigate to a search result. Closes the modal, calls navTo, then waits a
// tick for the view to mount before scrolling + flashing the target node.
function _navigateToSearchResult(payload) {
  if (!payload) return;
  const { s: section, v: view, t: target } = payload;
  closeGlobalSearch();
  // Also collapse the omnibox (removes body.omnibox-expanded and the
  // backdrop blur). closeGlobalSearch only handles the legacy modal's
  // own class; the omnibox needs its own cleanup. Both functions are
  // idempotent and harmless if the corresponding UI isn't active.
  if (typeof collapseOmnibox === 'function') {
    try { collapseOmnibox(); } catch (_) {}
  }
  // navTo handles the view switch — for sub-views like 'shopping' the search
  // result carries the explicit view name in v.
  try { navTo(view || section); } catch(_) {}
  // 350ms after navigation matches the timing used in the notification-tap
  // handler — gives the target view time to render its grid/rows.
  setTimeout(() => {
    const el = _findSearchResultElement(section, target);
    if (el) {
      try { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch(_) {}
      _flashElement(el);
    }
  }, 350);
}

// Locate the DOM node corresponding to a search result. Each section uses a
// different selector convention — keep them isolated here so result records
// only carry an opaque `target` id.
//
// Stockroom, Notes, Reminders, and Settings/Report/Billing/Account-Security
// flash on tap (their renders include the data-* attrs / ids we query).
// Groceries / Budget bills / Savings results currently fall through to
// "navigate only" because their renders don't yet emit data-grocery-id /
// data-bill-id / data-savings-id. Adding those attrs is a follow-up.
function _findSearchResultElement(section, target) {
  if (!target) return null;
  switch (section) {
    case 'stock':
      return document.querySelector(`.item-card[data-id="${CSS.escape(target)}"]`);
    case 'grocery':
      // Grocery rows have a data-id; lists have a data-list-id
      return document.querySelector(`[data-grocery-id="${CSS.escape(target)}"], [data-list-id="${CSS.escape(target)}"]`);
    case 'notes':
      return document.querySelector(`[data-note-id="${CSS.escape(target)}"]`);
    case 'reminders':
      return document.querySelector(`[data-reminder-id="${CSS.escape(target)}"]`);
    case 'budget':
      // Bills carry an id via inline onclick="openBillEditor('<id>')"; we
      // fall back to any element with the matching data attribute.
      return document.querySelector(`[data-bill-id="${CSS.escape(target)}"]`);
    case 'savings':
      return document.querySelector(`[data-savings-id="${CSS.escape(target)}"]`);
    default:
      // Settings / Report / Billing / Account-Security — target is an
      // element id captured at index time
      return document.getElementById(target);
  }
}

// ── Section searchers ────────────────────────────────────────────────────
// Each returns { results: [...], hasMore: bool } with results capped at
// _SEARCH_RESULTS_PER_SECTION. Records have:
//   { title, sub, view, target, icon? }

function _searchStockroom(q, opts = {}) {
  const includeArchived = !!opts.includeArchived;
  const includeDeleted  = !!opts.includeDeleted;
  const out = [];
  let archivedCount = 0;
  let deletedCount  = 0;
  for (const item of (items || [])) {
    const hay = [item.name, item.category, item.store, item.notes, (item.tags || []).join(' ')].filter(Boolean).join(' ').toLowerCase();
    if (!hay.includes(q)) continue;

    const isDeleted  = !!item._deletedAt;
    const isArchived = !isDeleted && !!item._archived;

    // Count hidden matches before filtering so the filter bar can show them
    if (isDeleted  && !includeDeleted)  { deletedCount++;  continue; }
    if (isArchived && !includeArchived) { archivedCount++; continue; }

    out.push({
      title: item.name || '(untitled)',
      sub:   [item.category, item.store].filter(Boolean).join(' · '),
      view:  'stock',
      target: item.id,
      state: isDeleted ? 'deleted' : (isArchived ? 'archived' : null),
    });
    if (out.length > _SEARCH_RESULTS_PER_SECTION) break;
  }
  return {
    results: out.slice(0, _SEARCH_RESULTS_PER_SECTION),
    hasMore: out.length > _SEARCH_RESULTS_PER_SECTION,
    archivedCount, deletedCount,
  };
}

function _searchGroceries(q, opts = {}) {
  const includeArchived = !!opts.includeArchived; // groceries don't have an archived state today, kept for symmetry
  const includeDeleted  = !!opts.includeDeleted;
  const out = [];
  let archivedCount = 0;
  let deletedCount  = 0;

  // ── Lists first ─────────────────────────────────────────────────────────
  // (so "Tesco" matches the Tesco list before its items)
  for (const list of (groceryLists || [])) {
    const hay = [list.name, list.store].filter(Boolean).join(' ').toLowerCase();
    if (!hay.includes(q)) continue;

    const isDeleted = !!list._deletedAt;
    if (isDeleted && !includeDeleted) { deletedCount++; continue; }

    out.push({
      title: list.name || '(unnamed list)',
      sub:   list.store ? `List · ${list.store}` : 'Shopping list',
      view:  'grocery',
      target: list.id,
      icon:  'i-shopping-cart',
      state: isDeleted ? 'deleted' : null,
    });
    if (out.length >= _SEARCH_RESULTS_PER_SECTION + 1) break;
  }

  // ── Items with aggregation ──────────────────────────────────────────────
  // The same item name can live across many lists (a "bread" entry in
  // Tesco, Co-op, Aldi, etc.). We group those into a single result so
  // typing "bread" doesn't produce six rows of the same name. Group key
  // is the case-insensitive trimmed name. Within a group we pick a
  // "primary" list using these rules in order:
  //   1. The currently active list (activeGroceryListId)
  //   2. The oldest list by createdAt (proxy for "main / original")
  //   3. Any list (fallback)
  // Other lists in the group are exposed via a "+N more lists" pill that
  // expands inline. Substring-only matches that don't share a canonical
  // name with anything else just render as a single result like before.
  //
  // For matching: we case-insensitively check the item name AND its dept
  // and notes; only the name participates in the aggregation key (an item
  // with "bread" in a note and one literally named Bread shouldn't merge).
  const itemGroups = new Map(); // key (lowercased name) → { items: [], canonicalName }

  for (const item of (groceryItems || [])) {
    // Field is `department` in the schema; older code referred to `dept`
    // which was always undefined. Check both for forward-compat.
    const dept = item.department || item.dept || '';
    const hay  = [item.name, dept, item.notes].filter(Boolean).join(' ').toLowerCase();
    if (!hay.includes(q)) continue;

    const isDeleted = !!item._deletedAt;
    if (isDeleted && !includeDeleted) { deletedCount++; continue; }

    // Aggregation key — only groups items that match by NAME exactly
    // (case-insensitive). If the match was solely via dept/notes, key
    // by id so it doesn't get folded into a name-based group.
    const lowerName = (item.name || '').trim().toLowerCase();
    const nameMatches = lowerName.includes(q);
    const key = nameMatches ? lowerName : ('id:' + item.id);

    if (!itemGroups.has(key)) {
      itemGroups.set(key, { items: [], canonicalName: item.name || '(unnamed item)', isDeletedSome: false });
    }
    const g = itemGroups.get(key);
    g.items.push(item);
    if (isDeleted) g.isDeletedSome = true;
  }

  // For each group, build a single result. Aggregate state: if every item
  // in the group is deleted, mark the result as deleted; if mixed, prefer
  // a non-deleted primary entry.
  const _byActiveOrOldest = (a, b) => {
    const activeId = (typeof activeGroceryListId !== 'undefined') ? activeGroceryListId : null;
    if (activeId) {
      const aActive = a.listId === activeId ? -1 : 0;
      const bActive = b.listId === activeId ? -1 : 0;
      if (aActive !== bActive) return aActive - bActive;
    }
    // Resolve list createdAt
    const listsById = (typeof groceryLists !== 'undefined' && Array.isArray(groceryLists))
      ? Object.fromEntries(groceryLists.map(l => [l.id, l]))
      : {};
    const ac = (listsById[a.listId]?.createdAt) || '';
    const bc = (listsById[b.listId]?.createdAt) || '';
    if (ac && bc) return ac < bc ? -1 : 1;
    if (ac) return -1;
    if (bc) return 1;
    return 0;
  };

  for (const [, g] of itemGroups) {
    // Pick the primary item. Prefer non-deleted items; among those, the
    // one whose list is active / oldest.
    const liveItems   = g.items.filter(i => !i._deletedAt);
    const candidates  = liveItems.length ? liveItems : g.items;
    candidates.sort(_byActiveOrOldest);
    const primary     = candidates[0];

    // Aggregate metadata
    const allDeleted    = g.items.every(i => !!i._deletedAt);
    const listIdSet     = new Set(g.items.map(i => i.listId).filter(Boolean));
    const listCount     = listIdSet.size;
    const listsById     = (typeof groceryLists !== 'undefined' && Array.isArray(groceryLists))
      ? Object.fromEntries(groceryLists.map(l => [l.id, l]))
      : {};
    const primaryList   = primary && listsById[primary.listId];
    const primaryDept   = primary?.department || primary?.dept || '';

    // Sub line: include both dept and the list count
    const subParts = [];
    if (primaryDept) subParts.push(primaryDept);
    if (primaryList?.name) subParts.push(primaryList.name);
    const sub = subParts.length ? `Item · ${subParts.join(' · ')}` : 'Grocery item';

    // Other lists for the disclosure pill. Map to {id, name, deletedFlag}.
    const otherLists = [...listIdSet]
      .filter(lid => lid !== primary?.listId)
      .map(lid => ({
        id:      lid,
        name:    listsById[lid]?.name || '(unknown list)',
        deleted: !!listsById[lid]?._deletedAt,
      }));

    out.push({
      title:  primary?.name || g.canonicalName,
      sub,
      view:   'grocery',
      target: primary?.id,
      state:  allDeleted ? 'deleted' : null,
      // Aggregation metadata for the row renderer to expand on demand
      otherLists: otherLists.length ? otherLists : null,
      groupCount: g.items.length,
    });

    if (out.length >= _SEARCH_RESULTS_PER_SECTION + 1) break;
  }

  return {
    results: out.slice(0, _SEARCH_RESULTS_PER_SECTION),
    hasMore: out.length > _SEARCH_RESULTS_PER_SECTION,
    archivedCount, deletedCount,
  };
}

function _searchNotes(q, opts = {}) {
  const includeArchived = !!opts.includeArchived;
  const includeDeleted  = !!opts.includeDeleted;
  const out = [];
  let archivedCount = 0;
  let deletedCount  = 0;
  for (const n of (notes || [])) {
    // Locked notes: title-only matching (body is encrypted and we don't
    // decrypt at index time). Show a lock indicator in the sub line.
    const title = (n.title || '').toLowerCase();
    const body  = n.locked ? '' : ((n.body || '').toLowerCase());
    const hay = (title + ' ' + body);
    if (!hay.includes(q)) continue;

    const isDeleted  = !!n.deletedAt;
    const isArchived = !isDeleted && !!n.archived;

    if (isDeleted  && !includeDeleted)  { deletedCount++;  continue; }
    if (isArchived && !includeArchived) { archivedCount++; continue; }

    out.push({
      title: n.title || '(untitled note)',
      sub:   n.locked ? '🔒 Locked note' : (n.pinned ? 'Pinned note' : 'Note'),
      view:  'notes',
      target: n.id,
      state: isDeleted ? 'deleted' : (isArchived ? 'archived' : null),
    });
    if (out.length > _SEARCH_RESULTS_PER_SECTION) break;
  }
  return {
    results: out.slice(0, _SEARCH_RESULTS_PER_SECTION),
    hasMore: out.length > _SEARCH_RESULTS_PER_SECTION,
    archivedCount, deletedCount,
  };
}

function _searchReminders(q, opts = {}) {
  const includeArchived = !!opts.includeArchived; // reminders don't have an archived state — kept for symmetry
  const includeDeleted  = !!opts.includeDeleted;
  const out = [];
  let archivedCount = 0;
  let deletedCount  = 0;
  // Reminders shown on the Reminders tab come from two sources: the
  // standalone `reminders[]` array AND the `replacementReminders` arrays
  // (and legacy single-reminder fields) on each item. The renderReminders
  // function aggregates both — search must do the same or the user will
  // type a reminder name they can see on screen and get no results.
  // Aggregation logic mirrors renderReminders() — keep in sync.
  //
  // For the filter: standalone reminders use _deletedAt. Item-derived
  // reminders inherit from the item — if the item is deleted, its
  // reminders disappear too. We don't surface deleted items as reminder
  // matches unless includeDeleted is true.
  const standaloneAll = (reminders || []);
  const itemDerivedAll = (items || []).flatMap(i => {
    if (i.replacementReminders?.length) {
      return i.replacementReminders.map(r => ({
        id:       `item_${i.id}_${r.id}`,
        name:     r.name ? `${i.name} — ${r.name}` : i.name,
        interval: r.interval, unit: r.unit,
        notes:    i.notes || '',
        _deletedAt: i._deletedAt || null, // inherit
      }));
    } else if (i.replacementInterval && i.replacementUnit) {
      return [{
        id:       `item_${i.id}`,
        name:     i.name,
        interval: i.replacementInterval, unit: i.replacementUnit,
        notes:    i.notes || '',
        _deletedAt: i._deletedAt || null,
      }];
    }
    return [];
  });
  const aggregated = [...standaloneAll, ...itemDerivedAll];

  for (const r of aggregated) {
    const hay = [r.name, r.notes].filter(Boolean).join(' ').toLowerCase();
    if (!hay.includes(q)) continue;

    const isDeleted = !!r._deletedAt;
    if (isDeleted && !includeDeleted) { deletedCount++; continue; }

    out.push({
      title: r.name || '(unnamed reminder)',
      sub:   r.interval ? `Every ${r.interval} ${r.unit || 'months'}` : 'Reminder',
      view:  'reminders',
      target: r.id,
      state: isDeleted ? 'deleted' : null,
    });
    if (out.length > _SEARCH_RESULTS_PER_SECTION) break;
  }
  return {
    results: out.slice(0, _SEARCH_RESULTS_PER_SECTION),
    hasMore: out.length > _SEARCH_RESULTS_PER_SECTION,
    archivedCount, deletedCount,
  };
}

function _searchBudget(q, opts = {}) {
  const includeArchived = !!opts.includeArchived;
  const includeDeleted  = !!opts.includeDeleted;
  const out = [];
  let archivedCount = 0;
  let deletedCount  = 0;

  // Helper: is `q` a "direct hit" against this name?
  //   - case-insensitive exact match, OR
  //   - case-insensitive whole-word token match
  // A direct hit qualifies the record for chip treatment with inline
  // actions. Non-direct (substring-only) matches fall back to a plain
  // row that just opens the editor like before.
  const _isDirectHit = (name) => {
    if (!name) return false;
    const n = name.toLowerCase();
    if (n === q) return true;
    // Build a regex with word boundaries from the (already-escaped) query.
    const safeQ = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    try { return new RegExp(`\\b${safeQ}\\b`).test(n); } catch (_) { return false; }
  };

  // ── Accounts ────────────────────────────────────────────────────────────
  // Accounts use a single `archived` flag (no separate deleted). When
  // archived and includeArchived is false, count and skip. Archived
  // accounts that ARE surfaced render as plain rows, not chips — the
  // chip's "Update balance" action makes no sense for an archived
  // account.
  for (const acc of (typeof budgetAccounts !== 'undefined' && Array.isArray(budgetAccounts) ? budgetAccounts : [])) {
    const hay = (acc.name || '').toLowerCase();
    if (!hay.includes(q)) continue;
    const isArchived = !!acc.archived;
    if (isArchived && !includeArchived) { archivedCount++; continue; }
    const direct = _isDirectHit(acc.name || '');
    out.push({
      title:  acc.name || '(unnamed account)',
      sub:    (direct && !isArchived) ? null : `Account · ${_money(acc.balance)}`,
      view:   'budget',
      target: acc.id,
      icon:   'i-credit-card',
      chip:   (direct && !isArchived) ? 'account' : null,
      payload: (direct && !isArchived) ? { id: acc.id } : null,
      state:  isArchived ? 'archived' : null,
    });
    if (out.length > _SEARCH_RESULTS_PER_SECTION) break;
  }

  // ── Categories (spend buckets) ──────────────────────────────────────────
  // Same archived-flag pattern. An archived category surfaces as a plain
  // row (no chip with "Add new" — adding spend to an archived category
  // would be surprising).
  if (out.length <= _SEARCH_RESULTS_PER_SECTION) {
    for (const cat of (typeof budgetCategories !== 'undefined' && Array.isArray(budgetCategories) ? budgetCategories : [])) {
      const hay = (cat.name || '').toLowerCase();
      if (!hay.includes(q)) continue;
      const isArchived = !!cat.archived;
      if (isArchived && !includeArchived) { archivedCount++; continue; }
      const direct = _isDirectHit(cat.name || '');
      out.push({
        title:  cat.name || '(unnamed category)',
        sub:    (direct && !isArchived) ? null : 'Spend category',
        view:   'budget',
        target: cat.id,
        icon:   'i-tag',
        chip:   (direct && !isArchived) ? 'category' : null,
        payload: (direct && !isArchived) ? { id: cat.id } : null,
        state:  isArchived ? 'archived' : null,
      });
      if (out.length > _SEARCH_RESULTS_PER_SECTION) break;
    }
  }

  // ── Bills ───────────────────────────────────────────────────────────────
  // Bills remain plain rows (no chip treatment). They have BOTH
  // `_deletedAt` (true delete) AND `archived` (soft-disabled).
  if (out.length <= _SEARCH_RESULTS_PER_SECTION) {
    for (const b of (typeof bills !== 'undefined' && Array.isArray(bills) ? bills : [])) {
      const hay = [b.name, b.notes].filter(Boolean).join(' ').toLowerCase();
      if (!hay.includes(q)) continue;

      const isDeleted  = !!b._deletedAt;
      const isArchived = !isDeleted && !!b.archived;
      if (isDeleted  && !includeDeleted)  { deletedCount++;  continue; }
      if (isArchived && !includeArchived) { archivedCount++; continue; }

      out.push({
        title: b.name || '(unnamed bill)',
        sub:   b.amount != null ? `Bill · ${_money(b.amount)}` : 'Bill',
        view:  'budget',
        target: b.id,
        state: isDeleted ? 'deleted' : (isArchived ? 'archived' : null),
      });
      if (out.length > _SEARCH_RESULTS_PER_SECTION) break;
    }
  }

  return {
    results: out.slice(0, _SEARCH_RESULTS_PER_SECTION),
    hasMore: out.length > _SEARCH_RESULTS_PER_SECTION,
    archivedCount, deletedCount,
  };
}

function _searchSavings(q, opts = {}) {
  const includeArchived = !!opts.includeArchived;
  const includeDeleted  = !!opts.includeDeleted;
  // Savings opportunities are derived from items[] (Amazon Subscribe & Save
  // tracking) — search the underlying items but route results to the savings
  // view. We deliberately don't surface every stockroom item here; only ones
  // that have any savings tracking signal (logs in the last 6 months or any
  // savings metadata).
  const out = [];
  let archivedCount = 0;
  let deletedCount  = 0;
  const ITEM_HAS_HISTORY = it => (it.logs && it.logs.length) || it.savingsSubscribed;
  for (const item of (items || [])) {
    if (!ITEM_HAS_HISTORY(item)) continue;
    const hay = [item.name, item.category].filter(Boolean).join(' ').toLowerCase();
    if (!hay.includes(q)) continue;

    const isDeleted  = !!item._deletedAt;
    const isArchived = !isDeleted && !!item._archived;
    if (isDeleted  && !includeDeleted)  { deletedCount++;  continue; }
    if (isArchived && !includeArchived) { archivedCount++; continue; }

    out.push({
      title: item.name || '(untitled)',
      sub:   item.savingsSubscribed ? 'Subscribed' : 'Tracking',
      view:  'savings',
      // No card-level DOM hook in savings yet — route to the view; we
      // still scroll to top of the view and flash nothing if no match.
      target: item.id,
      icon:  'i-piggy-bank',
      state: isDeleted ? 'deleted' : (isArchived ? 'archived' : null),
    });
    if (out.length > _SEARCH_RESULTS_PER_SECTION) break;
  }
  return {
    results: out.slice(0, _SEARCH_RESULTS_PER_SECTION),
    hasMore: out.length > _SEARCH_RESULTS_PER_SECTION,
    archivedCount, deletedCount,
  };
}

// Static-view searcher — indexes labels/headers in Report / Billing /
// Account & Security / Settings. The index is built lazily the first time
// any search runs, by walking the DOM of each view and pulling text from
// elements that look like headings/labels (h2/h3/h4, .acc-sec-h, settings
// section titles, labels). Each entry stores { title, sub, target } where
// target is an element id (added at index time if missing). Re-built on
// demand if the view markup changes.
function _searchStaticView(q, viewKey) {
  const idx = _ensureSettingsIndex();
  const entries = idx[viewKey] || [];
  const out = [];
  for (const e of entries) {
    if (e.haystack.includes(q)) {
      out.push({ title: e.title, sub: e.sub, view: viewKey, target: e.target });
      if (out.length > _SEARCH_RESULTS_PER_SECTION) break;
    }
  }
  return { results: out.slice(0, _SEARCH_RESULTS_PER_SECTION), hasMore: out.length > _SEARCH_RESULTS_PER_SECTION };
}

// ── Accessibility section search ─────────────────────────────────────────
// Returns chip-style rows that embed the actual control inline in the
// search results. Users can change theme or text size without leaving
// the omnibox / search results panel.
//
// Synonym buckets recognise the common natural-language ways someone
// might phrase the search — "dark" surfaces the Theme chip; "bigger"
// surfaces the Text size chip; "high contrast" or "low vision" surfaces
// the Theme chip with HC pre-targeted. Each chip renders the same
// segmented control as the Accessibility view itself, and the buttons
// share ids — so clicking inline updates the Accessibility view's
// segmented control in-place via _updateThemeUI / _updateTextScaleUI.
const _ACCESSIBILITY_THEME_SYNS = [
  'theme', 'themes', 'appearance', 'colour scheme', 'color scheme',
  'dark', 'dark mode', 'light', 'light mode',
  'high contrast', 'high-contrast', 'hc',
  'contrast', 'low vision', 'visual'
];
const _ACCESSIBILITY_TEXTSIZE_SYNS = [
  'text size', 'text-size', 'textsize', 'font size', 'font-size', 'fontsize',
  'text scale', 'text-scale', 'textscale',
  'larger text', 'bigger text', 'smaller text',
  'large text', 'big text', 'small text',
  'readable', 'readability', 'legibility',
  'xl', 'larger', 'bigger', 'smaller'
];

function _searchAccessibility(q) {
  // Standard DOM-harvested entries first so labels like "Display" or the
  // visible "Theme" / "Text size" headers still produce normal nav rows.
  // The user can tap one of those to land on the full Accessibility view.
  const baseline = _searchStaticView(q, 'accessibility');
  const out = [];
  const matchAny = (arr) => arr.some(syn => q.includes(syn) || syn.includes(q));
  if (matchAny(_ACCESSIBILITY_THEME_SYNS)) {
    out.push({ chip: 'accessibility-theme', view: 'accessibility', target: 'view-accessibility' });
  }
  if (matchAny(_ACCESSIBILITY_TEXTSIZE_SYNS)) {
    out.push({ chip: 'accessibility-textscale', view: 'accessibility', target: 'view-accessibility' });
  }
  // De-dupe baseline rows that would point at the same in-view targets
  // we're already showing inline (Theme / Text size headers).
  const hasChipTheme = out.some(o => o.chip === 'accessibility-theme');
  const hasChipScale = out.some(o => o.chip === 'accessibility-textscale');
  const filteredBaseline = (baseline.results || []).filter(r => {
    const t = (r.title || '').toLowerCase();
    if (hasChipTheme && t === 'theme') return false;
    if (hasChipScale && (t === 'text size' || t === 'text-size')) return false;
    return true;
  });
  // Chips first (they're the actionable controls), then any other
  // baseline rows (e.g. "Display" section header) for context.
  return {
    results: [...out, ...filteredBaseline].slice(0, _SEARCH_RESULTS_PER_SECTION),
    hasMore: false
  };
}

// Renders the Theme segmented control inline in a search-result row.
// Each button uses a distinct DOM id (suffixed with -inline) so it
// doesn't collide with the one in the Accessibility view itself. Both
// the inline buttons AND the in-view buttons update via setTheme(),
// which calls _updateThemeUI() — which finds every theme-seg-btn with
// the matching id pattern and updates them all in sync. (See the
// updated _updateThemeUI for how this works.)
function _renderSearchAccessibilityThemeChip() {
  const current = (settings && settings.theme) || 'system';
  const opts = [
    { id: 'system', label: 'System',        icon: 'i-monitor', title: 'Match system setting' },
    { id: 'light',  label: 'Light',         icon: 'i-sun',     title: 'Always light' },
    { id: 'dark',   label: 'Dark',          icon: 'i-moon',    title: 'Always dark' },
    { id: 'hc',     label: 'High contrast', icon: 'i-eye',     title: 'High contrast — maximum readability' },
  ];
  const buttons = opts.map(o => `
    <button type="button" class="theme-seg-btn ${current === o.id ? 'active' : ''}"
            id="theme-seg-${o.id}-inline"
            role="radio"
            aria-checked="${current === o.id ? 'true' : 'false'}"
            onclick="event.stopPropagation();setTheme('${o.id}')"
            title="${esc(o.title)}">
      <svg class="icon" aria-hidden="true"><use href="#${o.icon}"></use></svg>${esc(o.label)}
    </button>`).join('');
  return `<div class="global-search-row search-row-chip search-row-accessibility-chip">
    <svg class="global-search-row-icon" aria-hidden="true"><use href="#i-monitor"></use></svg>
    <div class="global-search-row-body">
      <div class="global-search-row-title">Theme</div>
      <div class="global-search-row-sub">Tap to change — applies everywhere</div>
      <div class="theme-seg search-row-inline-seg" role="radiogroup" aria-label="Theme">${buttons}</div>
    </div>
  </div>`;
}

function _renderSearchAccessibilityTextScaleChip() {
  const current = (settings && settings.textScale) || 'm';
  const opts = [
    { id: 's',  label: 'S',  fs: 11, title: 'Small text' },
    { id: 'm',  label: 'M',  fs: 13, title: 'Medium (default)' },
    { id: 'l',  label: 'L',  fs: 15, title: 'Large text' },
    { id: 'xl', label: 'XL', fs: 17, title: 'Extra large text' },
  ];
  const buttons = opts.map(o => `
    <button type="button" class="theme-seg-btn ${current === o.id ? 'active' : ''}"
            id="textscale-seg-${o.id}-inline"
            role="radio"
            aria-checked="${current === o.id ? 'true' : 'false'}"
            onclick="event.stopPropagation();setTextScale('${o.id}')"
            title="${esc(o.title)}">
      <span style="font-size:${o.fs}px;font-weight:700">${o.label}</span>
    </button>`).join('');
  return `<div class="global-search-row search-row-chip search-row-accessibility-chip">
    <svg class="global-search-row-icon" aria-hidden="true"><use href="#i-eye"></use></svg>
    <div class="global-search-row-body">
      <div class="global-search-row-title">Text size</div>
      <div class="global-search-row-sub">Tap to change — affects main content</div>
      <div class="theme-seg search-row-inline-seg" role="radiogroup" aria-label="Text size">${buttons}</div>
    </div>
  </div>`;
}

function _ensureSettingsIndex() {
  if (_GLOBAL_SEARCH.cachedSettingsIndex) return _GLOBAL_SEARCH.cachedSettingsIndex;
  const idx = {};
  const VIEW_IDS = {
    report:             'view-report',
    billing:            'view-billing',
    'account-security': 'view-account-security',
    accessibility:      'view-accessibility',
    settings:           'view-settings',
  };
  for (const [viewKey, elId] of Object.entries(VIEW_IDS)) {
    const root = document.getElementById(elId);
    if (!root) { idx[viewKey] = []; continue; }
    idx[viewKey] = _harvestSettingsEntries(root, viewKey);
  }
  _GLOBAL_SEARCH.cachedSettingsIndex = idx;
  return idx;
}

// Walk a view's DOM and pull out searchable label nodes. We grab headings
// (h2/h3/h4), `.acc-sec-h` titles, `.settings-section-header`, label-like
// `<label>` text, and section titles. Each gets an auto-id if missing so
// the search-result tap can target it. Returns an array of:
//   { title, sub, haystack, target }
function _harvestSettingsEntries(root, viewKey) {
  const out = [];
  const seenText = new Set();
  // Selectors that tend to mark a section/label inside our settings UI.
  const SELECTORS = [
    'h2', 'h3', 'h4',
    '.acc-sec-h',
    '.acc-sec-section-title',
    '.settings-section-header',
    '.settings-section-title',
    'label',
  ];
  const sel = SELECTORS.join(',');
  let counter = 0;
  root.querySelectorAll(sel).forEach(el => {
    // Skip empty or icon-only labels
    const rawText = (el.textContent || '').replace(/\s+/g, ' ').trim();
    if (!rawText || rawText.length < 2) return;
    // De-dupe identical labels (some labels appear twice in the same view)
    const dedupeKey = viewKey + '::' + rawText.toLowerCase();
    if (seenText.has(dedupeKey)) return;
    seenText.add(dedupeKey);
    // Ensure the element has an id so we can target it
    if (!el.id) { el.id = `search-tgt-${viewKey}-${++counter}`; }
    // Find the nearest section ancestor for the sub-label (gives the user
    // context like "Preferences · Currency" rather than just "Currency").
    let sub = '';
    let cur = el.parentElement;
    while (cur && cur !== root) {
      if (cur.matches('.acc-sec-section, .acc-sec-card, .settings-section, details')) {
        const head = cur.querySelector('.acc-sec-section-title, .settings-section-header, summary');
        if (head) { sub = (head.textContent || '').replace(/\s+/g, ' ').trim(); break; }
      }
      cur = cur.parentElement;
    }
    out.push({
      title: rawText,
      sub:   sub && sub.toLowerCase() !== rawText.toLowerCase() ? sub : '',
      haystack: rawText.toLowerCase() + ' ' + sub.toLowerCase(),
      target: el.id,
    });
  });
  return out;
}

// Invalidate the cached settings index — called whenever settings UI is
// rebuilt (e.g. country changes, MFA enabled, passkey added). Cheap to
// re-index next time the user searches.
function _invalidateSettingsSearchIndex() {
  _GLOBAL_SEARCH.cachedSettingsIndex = null;
}

async function toggleNotificationPin(id) {
  const n = notifications.find(x => x.id === id);
  if (!n) return;
  if (!n.pinned) {
    const currentPins = notifications.filter(x => x.pinned).length;
    if (currentPins >= NOTIFICATIONS_PINNED_MAX) {
      toast(`Max ${NOTIFICATIONS_PINNED_MAX} pinned — unpin one first`);
      return;
    }
  }
  n.pinned = !n.pinned;
  // Stamp the moment of this pin/unpin decision so the cross-device merge
  // (kvSyncNow notifications branch) can pick the latest action rather
  // than OR'ing the two sides' pinned flags. The previous OR-merge made
  // unpins bounce back after a sync round-trip: PULL → MERGE → PUSH ran
  // before the server had seen our new false, so the merge re-applied
  // remote's stale true and the pin reappeared. With pinnedAt, whichever
  // side toggled most recently wins for both pinned + pinnedAt.
  n.pinnedAt = new Date().toISOString();
  await saveNotificationsLocal();
  _syncQueue.enqueue('Syncing notifications…');
  _renderNotificationPanel();
}

async function dismissNotification(id) {
  const n = notifications.find(x => x.id === id);
  if (!n) return;
  // Mark dismissed instead of removing so the entry stays in the
  // notification history modal. The panel filters dismissed items out;
  // history filters them in (with a "dismissed" visual treatment).
  n.dismissedAt = new Date().toISOString();
  // If unread, mark read too — dismiss is a stronger acknowledgement
  if (!n.readAt) n.readAt = n.dismissedAt;
  await saveNotificationsLocal();
  // Push the dismissal up so other devices stop showing this notification.
  // The remote merge carries dismissedAt with earliest-wins semantics
  // (see kvSyncNow notifications branch), so the dismissal is sticky.
  _syncQueue.enqueue('Syncing notifications…');
  _renderNotificationBellBadge();
  _renderNotificationPanel();
}

async function markAllNotificationsRead() {
  const now = new Date().toISOString();
  let changed = false;
  notifications.forEach(n => { if (!n.readAt) { n.readAt = now; changed = true; } });
  if (changed) {
    await saveNotificationsLocal();
    _syncQueue.enqueue('Syncing notifications…');
    _renderNotificationBellBadge();
    _renderNotificationPanel();
  }
}

async function clearNotificationHistory() {
  // Keep pinned, drop everything else
  const before = notifications.length;
  notifications = notifications.filter(n => n.pinned);
  if (notifications.length !== before) {
    await saveNotificationsLocal();
    _syncQueue.enqueue('Syncing notifications…');
    _renderNotificationBellBadge();
    _renderNotificationPanel();
    toast(`Cleared ${before - notifications.length} notification${before - notifications.length !== 1 ? 's' : ''}`);
  }
}

// Lightweight snapshot used for diffing items[] across share-blob absorbs.
// Captures only what we need to detect added/removed/changed for the UI:
// id, name, and a few hot fields that signal "meaningful" change.
function _snapshotItemsForDiff(arr) {
  const map = new Map();
  if (!Array.isArray(arr)) return map;
  for (const it of arr) {
    if (!it || !it.id) continue;
    map.set(it.id, {
      id: it.id,
      name: it.name || '',
      qty: it.qty,
      ordered: !!it.ordered,
      stockCount: it.stockCount,
      lastReplaced: it.lastReplaced,
      _deletedAt: it._deletedAt,
    });
  }
  return map;
}

// Diff two item snapshots and emit notifications for the differences.
// `who` is the human label (e.g. "Sarah" or "household name") that gets
// shown in the notification body. We batch heavy diffs into a single
// summary notification rather than spamming.
async function _emitShareDiffNotifications(beforeMap, afterMap, { code, who }) {
  if (!beforeMap || !afterMap) return;
  const added   = [];
  const removed = [];
  const changed = [];
  for (const [id, after] of afterMap.entries()) {
    const before = beforeMap.get(id);
    if (!before) {
      // Truly new (not just absent because we hadn't seen it). Skip on first
      // ever sync to avoid flooding — beforeMap empty signal handled by caller.
      added.push(after);
    } else if (after._deletedAt && !before._deletedAt) {
      removed.push(after);
    } else if (
      before.name !== after.name ||
      before.qty !== after.qty ||
      before.ordered !== after.ordered ||
      before.stockCount !== after.stockCount ||
      before.lastReplaced !== after.lastReplaced
    ) {
      changed.push(after);
    }
  }
  // First-ever absorb (beforeMap empty): suppress add notifications to avoid
  // a 50-entry flood when a new device joins an existing share.
  if (beforeMap.size === 0) return;

  // Batch threshold: if more than 3 items changed in any category, summarise.
  const summarise = (added.length + removed.length + changed.length) > 5;
  const sharedFromName = who || null;
  const sharedFromCode = code || null;

  if (summarise) {
    const bits = [];
    if (added.length)   bits.push(`${added.length} added`);
    if (changed.length) bits.push(`${changed.length} updated`);
    if (removed.length) bits.push(`${removed.length} removed`);
    await addNotification({
      type: 'share',
      title: `Updates in ${who || 'shared household'}`,
      body: bits.join(', '),
      sourceRef: `share:${code}:bulk:${Date.now()}`,
      sharedFromCode, sharedFromName,
      dedupeWindowMs: 5 * 60 * 1000, // 5 min dedupe for bulk
    });
    return;
  }

  for (const it of added.slice(0, 5)) {
    await addNotification({
      type: 'share',
      title: who ? `${who} added "${it.name}"` : `Added: ${it.name}`,
      body: '',
      sourceRef: `share:${code}:add:${it.id}`,
      sharedFromCode, sharedFromName,
    });
  }
  for (const it of removed.slice(0, 5)) {
    await addNotification({
      type: 'share',
      title: who ? `${who} removed "${it.name}"` : `Removed: ${it.name}`,
      body: '',
      sourceRef: `share:${code}:remove:${it.id}`,
      sharedFromCode, sharedFromName,
    });
  }
  for (const it of changed.slice(0, 5)) {
    let body = '';
    const before = beforeMap.get(it.id);
    if (before) {
      if (before.ordered !== it.ordered) {
        body = it.ordered ? 'marked as ordered' : 'unmarked as ordered';
      } else if (before.lastReplaced !== it.lastReplaced) {
        body = 'marked as replaced';
      } else if (before.qty !== it.qty) {
        body = `qty: ${before.qty} → ${it.qty}`;
      } else if (before.stockCount !== it.stockCount) {
        body = `stock: ${before.stockCount ?? '?'} → ${it.stockCount ?? '?'}`;
      } else if (before.name !== it.name) {
        body = `renamed from "${before.name}"`;
      } else {
        body = 'updated';
      }
    }
    await addNotification({
      type: 'share',
      title: who ? `${who} updated "${it.name}"` : `Updated: ${it.name}`,
      body,
      sourceRef: `share:${code}:edit:${it.id}`,
      sharedFromCode, sharedFromName,
    });
  }
}

// ── Calculations ──────────────────────────
function getReminderIntervalDays(reminder) {
  const n = reminder.interval || 1;
  if (reminder.unit === 'days')   return n;
  if (reminder.unit === 'weeks')  return n * 7;
  if (reminder.unit === 'months') return n * AVG_DAYS_PER_MONTH;
  return n * AVG_DAYS_PER_MONTH;
}

function getReminderDueDate(reminder) {
  if (!reminder.lastReplaced) return null;
  const lastMs   = new Date(reminder.lastReplaced + 'T12:00:00').getTime();
  const intervalMs = getReminderIntervalDays(reminder) * MS_PER_DAY;
  return new Date(lastMs + intervalMs);
}

function getReminderDaysUntil(reminder) {
  const due = getReminderDueDate(reminder);
  if (!due) return null;
  return Math.round((due.getTime() - Date.now()) / MS_PER_DAY);
}

function getReminderStatus(reminder) {
  const days = getReminderDaysUntil(reminder);
  if (days === null)  return 'unknown';
  if (days < 0)       return 'overdue';
  if (days <= 30)     return 'soon';
  return 'upcoming';
}

// ── Render ────────────────────────────────
async function renderReminders() {
  await loadReminders();

  // Also collect reminders embedded in items — supports both old single and new array format
  const allReminders = [
    ...reminders.filter(r => !r._deletedAt),
    ...items.filter(i => !i._deletedAt).flatMap(i => {
      const fallbackDate = i.startedUsing || i.logs?.filter(l => !l.pendingDelivery)[0]?.date || null;
      if (i.replacementReminders?.length) {
        // New array format — one entry per named reminder
        return i.replacementReminders.map(r => ({
          id:           `item_${i.id}_${r.id}`,
          name:         r.name ? `${i.name} — ${r.name}` : i.name,
          itemName:     i.name,
          reminderName: r.name || '',
          interval:     r.interval,
          unit:         r.unit,
          lastReplaced: r.lastReplaced || fallbackDate || null,
          lastReplacedIsFallback: !r.lastReplaced && !!fallbackDate,
          notes:        i.notes || '',
          fromItem:     i.id,
          fromReminder: r.id,
        }));
      } else if (i.replacementInterval && i.replacementUnit) {
        // Legacy single-reminder format
        return [{
          id:           `item_${i.id}`,
          name:         i.name,
          itemName:     i.name,
          reminderName: '',
          interval:     i.replacementInterval,
          unit:         i.replacementUnit,
          lastReplaced: i.lastReplaced || fallbackDate || null,
          lastReplacedIsFallback: !i.lastReplaced && !!fallbackDate,
          notes:        i.notes || '',
          fromItem:     i.id,
          fromReminder: null,
        }];
      }
      return [];
    }),
  ];

  const overdue  = allReminders.filter(r => getReminderStatus(r) === 'overdue');
  const soon     = allReminders.filter(r => getReminderStatus(r) === 'soon');
  const upcoming = allReminders.filter(r => getReminderStatus(r) === 'upcoming');
  const unknown  = allReminders.filter(r => getReminderStatus(r) === 'unknown');

  const empty = document.getElementById('reminders-empty');
  if (allReminders.length === 0) {
    if (empty) empty.style.display = 'block';
    ['overdue-section','soon-section','upcoming-section'].forEach(s => {
      const el = document.getElementById('reminders-' + s);
      if (el) el.style.display = 'none';
    });
    const nudge = document.getElementById('reminders-nudge');
    if (nudge) nudge.style.display = 'none';
    renderRemindersRecycleBin();
    return;
  }
  if (empty) empty.style.display = 'none';

  // Nudge bar
  const nudge     = document.getElementById('reminders-nudge');
  const nudgeText = document.getElementById('reminders-nudge-text');
  if (nudge && overdue.length > 0) {
    nudge.style.display = 'flex';
    nudgeText.innerHTML = `<svg class="icon icon-sm" aria-hidden="true"><use href="#i-alert-triangle"></use></svg> ${overdue.length} replacement${overdue.length !== 1 ? 's' : ''} overdue`;
  } else if (nudge) {
    nudge.style.display = 'none';
  }

  // Render each section
  const renderSection = (list, containerId, sectionId, countId) => {
    const section   = document.getElementById(sectionId);
    const container = document.getElementById(containerId);
    const countEl   = document.getElementById(countId);
    if (!section || !container) return;
    if (!list.length) { section.style.display = 'none'; return; }
    section.style.display = 'block';
    if (countEl) countEl.textContent = list.length;
    container.innerHTML = list.map(r => reminderCardHTML(r)).join('');
  };

  // Sort overdue by most overdue first
  overdue.sort((a,b)  => (getReminderDaysUntil(a)||0) - (getReminderDaysUntil(b)||0));
  soon.sort((a,b)     => (getReminderDaysUntil(a)||0) - (getReminderDaysUntil(b)||0));
  upcoming.sort((a,b) => (getReminderDaysUntil(a)||0) - (getReminderDaysUntil(b)||0));

  renderSection([...overdue], 'reminders-overdue-list',    'reminders-overdue-section', 'overdue-count');
  renderSection([...soon],    'reminders-soon-list',       'reminders-soon-section',    'soon-count');
  renderSection([...upcoming, ...unknown], 'reminders-upcoming-list', 'reminders-upcoming-section', null);

  // Also update stock view badge if reminders are overdue
  updateRemindersBadge(overdue.length + soon.length);

  renderRemindersRecycleBin();
}

function renderRemindersRecycleBin() {
  const view = document.getElementById('view-reminders');
  if (!view) return;
  let bin = document.getElementById('reminders-recycle-bin');

  // Only standalone reminders are soft-deleted; item-linked reminders are
  // tied to the item's own data and follow the item's bin state.
  const trashed = reminders
    .filter(r => r._deletedAt && !_expiredFromBin(r))
    .sort((a, b) => new Date(b._deletedAt) - new Date(a._deletedAt));

  if (!trashed.length) {
    if (bin) bin.style.display = 'none';
    return;
  }

  if (!bin) {
    bin = document.createElement('div');
    bin.id = 'reminders-recycle-bin';
    bin.className = 'recycle-bin-section';
    bin.setAttribute('data-bin-key', 'reminders');
    view.appendChild(bin);
  }
  bin.style.display = 'block';
  bin.classList.toggle('recycle-bin-collapsed', _isBinCollapsed('reminders'));

  const titleHTML = `
    <div class="recycle-bin-title">
      <svg class="icon icon-md" aria-hidden="true"><use href="#i-trash-2"></use></svg>
      Recently Deleted
      <span class="recycle-bin-count">${trashed.length}</span>
    </div>`;
  const actionHTML = `<button class="btn btn-ghost btn-sm" onclick="emptyRemindersBin()">Empty</button>`;
  const headerHTML = _renderBinHeader('reminders', titleHTML, actionHTML)
    + `<div class="recycle-bin-subtitle">Reminders are permanently deleted after 30 days.</div>`;
  const rowsHTML = trashed.map(r => {
    const days = _daysLeftInBin(r);
    const interval = (r.interval && r.unit) ? `Every ${r.interval} ${r.unit}` : '';
    return `
      <div class="recycle-bin-row" data-id="${r.id}">
        <div class="recycle-bin-row-info">
          <div class="recycle-bin-row-name">${esc(r.name || 'Untitled reminder')}</div>
          <div class="recycle-bin-row-meta">${interval ? interval + ' · ' : ''}${days} day${days===1?'':'s'} left</div>
        </div>
        <div class="recycle-bin-row-actions">
          <button class="btn btn-ghost btn-sm" onclick="restoreReminder('${r.id}')">Restore</button>
          <button class="btn btn-ghost btn-sm recycle-bin-delete" onclick="purgeReminderForever('${r.id}')" title="Delete permanently">✕</button>
        </div>
      </div>`;
  }).join('');

  bin.innerHTML = headerHTML + `<div class="recycle-bin-rows">${rowsHTML}</div>`;
}

// Click handler for reminder cards. In bulk-select mode, toggles selection
// for standalone reminders (item-attached ones don't reach this handler —
// see reminderCardHTML's clickHandler branch which routes them straight
// to openReminderTimeline). Outside select mode, opens the timeline.
function onReminderCardClick(event, id) {
  if (isBulkSelectMode('reminder')) {
    if (event && event.stopPropagation) event.stopPropagation();
    toggleBulkSelection('reminder', id);
    return;
  }
  openReminderTimeline(id);
}

// Share-from-card entry for standalone reminders. Same pattern as
// stockroom and grocery: enters bulk-select mode AND pre-selects this
// reminder. Only callable on standalone reminders (the action row
// branches on !isFromItem to render the Share button).
function shareReminderFromCard(id) {
  enterBulkSelectMode('reminder');
  toggleBulkSelection('reminder', id);
}

function reminderCardHTML(r) {
  const days     = getReminderDaysUntil(r);
  const status   = getReminderStatus(r);
  const dueDate  = getReminderDueDate(r);
  const isFromItem = r.fromItem;

  const statusColor = status === 'overdue' ? 'var(--danger)' : status === 'soon' ? 'var(--warn)' : 'var(--muted)';
  const borderColor = status === 'overdue' ? 'rgba(232,80,80,0.3)' : status === 'soon' ? 'rgba(232,168,56,0.3)' : 'var(--border)';

  let timeLabel = '';
  if (days === null) {
    timeLabel = 'No replacement date recorded';
  } else if (days < 0) {
    timeLabel = `Overdue by ${Math.abs(days)} day${Math.abs(days) !== 1 ? 's' : ''}`;
  } else if (days === 0) {
    timeLabel = 'Due today';
  } else {
    timeLabel = `Due in ${days} day${days !== 1 ? 's' : ''}`;
  }

  const intervalLabel = `Every ${r.interval} ${r.unit}`;
  const lastLabel = r.lastReplaced
    ? (r.lastReplacedIsFallback ? `First used ${timeAgo(r.lastReplaced)}` : `Last replaced ${timeAgo(r.lastReplaced)}`)
    : 'Never replaced';
  const nextLabel = dueDate ? `Next: ${fmtDate(dueDate.toISOString().slice(0,10))}` : 'Set a date to track';

  // Bulk-select wiring (Pass 2c). Standalone reminders are selectable;
  // item-attached ones are marked disabled so they grey out in select
  // mode but still respond to taps normally (their click still opens
  // the timeline). The bulk-attrs and class only apply to standalone.
  const bulkAttrs = isFromItem
    ? `data-bulk-disabled="true"`
    : `class="reminder-card${bulkSelectionHas('reminder', r.id) ? ' selected' : ''}" data-bulk-id="${r.id}" data-bulk-section="reminder"`;
  const clickHandler = isFromItem
    ? `openReminderTimeline('${r.id}')`
    : `onReminderCardClick(event,'${r.id}')`;

  return `<div data-reminder-id="${r.id}" ${bulkAttrs} style="background:var(--surface);border:1px solid ${borderColor};border-radius:12px;padding:14px 16px;margin-bottom:10px;display:flex;gap:12px;align-items:flex-start;cursor:pointer;transition:border-color 0.15s,box-shadow 0.15s,outline 0.12s" onclick="${clickHandler}" title="Tap to view timeline">
    <div style="flex:1;min-width:0">
      <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:4px">
        <span style="font-size:15px;font-weight:700;color:var(--text)">${esc(r.itemName || r.name)}</span>
        ${r.reminderName ? `<span style="font-size:12px;color:var(--muted)">${esc(r.reminderName)}</span>` : ''}
        ${isFromItem ? `<span style="font-size:10px;color:var(--muted);font-family:var(--mono);padding:1px 6px;border:1px solid var(--border);border-radius:99px">linked</span>` : ''}
        ${(!isFromItem && isOwner() && r.share != null) ? (() => {
          // Sharing override indicator — only for standalone reminders.
          // Item-attached reminders (isFromItem === true) inherit from
          // their parent item and don't carry their own share field.
          const sh = r.share;
          let icon = 'i-shield', title = 'Custom sharing';
          if (sh === 'private') { icon = 'i-eye-off'; title = 'Private — owner only'; }
          else if (typeof sh === 'object') {
            if (Array.isArray(sh.allow))     title = `Visible to ${sh.allow.length} share${sh.allow.length===1?'':'s'} only`;
            else if (Array.isArray(sh.deny)) title = `Hidden from ${sh.deny.length} share${sh.deny.length===1?'':'s'}`;
            if (Array.isArray(sh.readOnly) && sh.readOnly.length) title += ` · read-only for ${sh.readOnly.length}`;
          }
          return `<svg class="icon icon-sm" aria-hidden="true" title="${esc(title)}" style="color:var(--muted)"><use href="#${icon}"></use></svg>`;
        })() : ''}
        <span style="font-size:10px;color:var(--muted);margin-left:auto;opacity:0.5"><svg class="icon" aria-hidden="true"><use href="#i-bar-chart-2"></use></svg> Timeline</span>
      </div>
      <div style="font-size:12px;font-weight:700;color:${statusColor};margin-bottom:4px">${timeLabel}</div>
      <div style="font-size:11px;color:var(--muted);font-family:var(--mono);line-height:1.8">
        ${intervalLabel} · ${lastLabel}<br>${nextLabel}
      </div>
      ${r.notes ? `<div style="font-size:12px;color:var(--muted);font-style:italic;margin-top:6px"><svg class="icon" aria-hidden="true"><use href="#i-message-square"></use></svg> ${esc(r.notes)}</div>` : ''}
      <div class="reminder-card-actions" style="display:flex;gap:6px;margin-top:10px;flex-wrap:wrap" onclick="event.stopPropagation()">
        <button class="btn btn-primary btn-sm" onclick="openLogReplacementModal('${r.id}')"><svg class="icon" aria-hidden="true"><use href="#i-check-circle-2"></use></svg> Mark replaced</button>
        ${!isFromItem
          ? `<button class="btn btn-ghost btn-sm" onclick="openEditReminderModal('${r.id}')"><svg class="icon" aria-hidden="true"><use href="#i-pencil"></use></svg> Edit</button>`
          : `<button class="btn btn-ghost btn-sm" onclick="openEditModal('${r.fromItem}')"><svg class="icon" aria-hidden="true"><use href="#i-pencil"></use></svg> Edit item</button>`
        }
        ${!isFromItem
          ? `<button class="btn btn-ghost btn-sm" onclick="shareReminderFromCard('${r.id}')" title="Share this reminder"><svg class="icon" aria-hidden="true"><use href="#i-share-2"></use></svg> Share</button>`
          : ''
        }
        <button class="btn btn-ghost btn-sm" style="color:var(--danger)" onclick="deleteReminder('${r.id}')"><svg class="icon" aria-hidden="true"><use href="#i-trash-2"></use></svg> Delete</button>
      </div>
    </div>
  </div>`;
}

// ── Resolve a reminder ID to its full data object ──────────
// Handles: standalone reminder IDs, item_${itemId} (legacy), item_${itemId}_${remId} (new)
function _resolveReminderId(id) {
  // Standalone reminder
  const standalone = reminders.find(r => r.id === id);
  if (standalone) return { r: standalone, item: null, remEntry: null };

  if (!id.startsWith('item_')) return null;

  const rest = id.slice('item_'.length); // either "itemId" or "itemId_remId"
  const underIdx = rest.indexOf('_');

  if (underIdx === -1) {
    // Legacy: item_${itemId}
    const item = items.find(i => i.id === rest);
    if (!item) return null;
    const fallbackDate = item.startedUsing || item.logs?.filter(l => !l.pendingDelivery)[0]?.date || null;
    return {
      r: {
        id, name: item.name, itemName: item.name, reminderName: '',
        interval: item.replacementInterval, unit: item.replacementUnit,
        lastReplaced: item.lastReplaced || fallbackDate || null,
        lastReplacedIsFallback: !item.lastReplaced && !!fallbackDate,
        notes: item.notes || '', fromItem: item.id, fromReminder: null,
      },
      item, remEntry: null,
    };
  } else {
    // New: item_${itemId}_${remId}
    const itemId = rest.slice(0, underIdx);
    const remId  = rest.slice(underIdx + 1);
    const item   = items.find(i => i.id === itemId);
    if (!item) return null;
    const remEntry = item.replacementReminders?.find(r => r.id === remId);
    if (!remEntry) return null;
    const fallbackDate = item.startedUsing || item.logs?.filter(l => !l.pendingDelivery)[0]?.date || null;
    return {
      r: {
        id, name: remEntry.name ? `${item.name} — ${remEntry.name}` : item.name,
        itemName: item.name, reminderName: remEntry.name || '',
        interval: remEntry.interval, unit: remEntry.unit,
        lastReplaced: remEntry.lastReplaced || fallbackDate || null,
        lastReplacedIsFallback: !remEntry.lastReplaced && !!fallbackDate,
        notes: item.notes || '', fromItem: item.id, fromReminder: remId,
      },
      item, remEntry,
    };
  }
}

// ── Reminder Timeline ──────────────────────
function openReminderTimeline(reminderId) {
  const resolved = _resolveReminderId(reminderId);
  if (!resolved) return;
  const r = resolved.r;

  const intervalDays = getReminderIntervalDays(r);
  const now          = new Date();
  const today        = now.toISOString().slice(0, 10);
  const status       = getReminderStatus(r);
  const dueDate      = getReminderDueDate(r);

  document.getElementById('rtl-title').textContent = r.name;
  document.getElementById('rtl-subtitle').textContent =
    `Every ${r.interval} ${r.unit} · ${r.lastReplaced
      ? (r.lastReplacedIsFallback ? 'Started ' : 'Last replaced ') + fmtDate(r.lastReplaced)
      : 'No start date recorded'}`;

  // Wire up the Mark replaced button
  const markBtn = document.getElementById('rtl-mark-btn');
  markBtn.onclick = () => { closeModal('reminder-timeline-modal'); openLogReplacementModal(reminderId); };

  // ── Build timeline nodes ─────────────────
  // Show 2 past cycles + current + 3 future cycles + reorder point
  const nodes = [];

  if (r.lastReplaced) {
    const startMs    = new Date(r.lastReplaced + 'T12:00:00').getTime();
    const intervalMs = intervalDays * MS_PER_DAY;

    // Past replacement events (up to 2 before the most recent)
    for (let i = 2; i >= 1; i--) {
      const d = new Date(startMs - i * intervalMs);
      if (d < new Date(startMs - 365 * MS_PER_DAY * 2)) continue; // don't go more than 2 years back
      nodes.push({ type: 'past', date: d, label: 'Replaced' });
    }
    // Most recent replacement (anchor)
    nodes.push({ type: 'anchor', date: new Date(startMs), label: r.lastReplacedIsFallback ? 'First used' : 'Last replaced' });
    // Future replacement events
    for (let i = 1; i <= 3; i++) {
      const d = new Date(startMs + i * intervalMs);
      const isPast = d < now;
      nodes.push({
        type:  isPast ? 'overdue' : (i === 1 ? 'next' : 'future'),
        date:  d,
        label: i === 1 ? 'Replace' : 'Replace',
        cycle: i,
      });
    }
    // Reorder point — 80% into the NEXT cycle (buy before you run out)
    const nextDue   = new Date(startMs + intervalMs);
    const cycleAfter = new Date(startMs + 2 * intervalMs);
    const reorderDate = new Date(nextDue.getTime() + (cycleAfter.getTime() - nextDue.getTime()) * 0.2);
    // Only show reorder if it's in the future
    if (reorderDate > now) {
      nodes.push({ type: 'reorder', date: reorderDate, label: 'Reorder by' });
    }
    // Sort all by date
    nodes.sort((a, b) => a.date - b.date);
  }

  // ── Current period progress ──────────────
  let progressPct = null;
  let progressLabel = '';
  if (dueDate && r.lastReplaced) {
    const startMs  = new Date(r.lastReplaced + 'T12:00:00').getTime();
    const endMs    = dueDate.getTime();
    const nowMs    = now.getTime();
    progressPct    = Math.min(100, Math.max(0, Math.round(((nowMs - startMs) / (endMs - startMs)) * 100)));
    const daysLeft = getReminderDaysUntil(r);
    progressLabel  = daysLeft === null ? '' : daysLeft < 0 ? `${Math.abs(daysLeft)}d overdue` : daysLeft === 0 ? 'Due today' : `${daysLeft}d remaining`;
  }

  // ── Render ───────────────────────────────
  const statusColor = status === 'overdue' ? '#e85050' : status === 'soon' ? '#e8a838' : '#4cbb8a';

  let html = '';

  if (!r.lastReplaced) {
    html = `<div style="text-align:center;padding:32px 16px;color:var(--muted)">
      <div style="margin-bottom:12px;color:var(--accent)"><svg aria-hidden="true" style="width:36px;height:36px"><use href="#i-calendar"></use></svg></div>
      <div style="font-size:14px;font-weight:600;color:var(--text);margin-bottom:6px">No start date recorded</div>
      <div style="font-size:13px;line-height:1.6">Mark this as replaced to start tracking the timeline.</div>
    </div>`;
  } else {
    // Progress bar for current period
    if (progressPct !== null) {
      const barColor = status === 'overdue' ? '#e85050' : status === 'soon' ? '#e8a838' : '#4cbb8a';
      html += `<div style="margin-bottom:20px">
        <div style="display:flex;justify-content:space-between;font-size:11px;color:var(--muted);font-family:var(--mono);margin-bottom:6px">
          <span>${r.lastReplacedIsFallback ? 'First used' : 'Last replaced'}</span>
          <span style="color:${barColor};font-weight:700">${progressLabel}</span>
          <span>Due ${dueDate ? fmtDate(dueDate.toISOString().slice(0,10)) : '—'}</span>
        </div>
        <div style="height:10px;background:var(--surface2);border-radius:99px;overflow:hidden;position:relative">
          <div style="height:100%;width:${progressPct}%;background:${barColor};border-radius:99px;transition:width 0.6s"></div>
          ${progressPct >= 100 ? '' : `<div style="position:absolute;top:0;left:${progressPct}%;transform:translateX(-50%);width:2px;height:100%;background:${barColor};opacity:0.6"></div>`}
        </div>
        <div style="font-size:11px;color:var(--muted);text-align:center;margin-top:4px;font-family:var(--mono)">${progressPct}% through current cycle</div>
      </div>`;
    }

    // Timeline nodes
    if (nodes.length) {
      html += `<div style="position:relative;padding:8px 0 8px 20px">`;

      // Vertical line
      html += `<div style="position:absolute;left:20px;top:20px;bottom:20px;width:2px;background:linear-gradient(to bottom,var(--surface2),var(--border),var(--surface2));border-radius:2px"></div>`;

      nodes.forEach((node, idx) => {
        const isPast    = node.type === 'past';
        const isAnchor  = node.type === 'anchor';
        const isOverdue = node.type === 'overdue';
        const isNext    = node.type === 'next';
        const isReorder = node.type === 'reorder';
        const isFuture  = node.type === 'future';

        const dotColor  = isOverdue ? '#e85050'
          : isNext    ? statusColor
          : isReorder ? '#e8a838'
          : isAnchor  ? '#5b8dee'
          : isPast    ? 'var(--border)'
          : 'var(--surface2)';

        const dotBorder = isNext || isReorder || isOverdue
          ? `3px solid ${dotColor}`
          : `2px solid ${dotColor}`;

        const dotSize   = isNext || isReorder ? '16px' : isAnchor ? '14px' : '10px';
        const dotBg     = isPast || isFuture ? 'var(--bg)' : isAnchor ? '#5b8dee' : isOverdue ? '#e85050' : isNext ? statusColor : '#e8a838';

        const nameColor = isOverdue ? '#e85050' : isNext ? statusColor : isReorder ? '#e8a838' : isAnchor ? '#5b8dee' : isPast ? 'var(--muted)' : 'var(--muted)';
        const fontWeight = isNext || isReorder || isAnchor ? '700' : '400';

        const isToday   = node.date.toISOString().slice(0,10) === today;
        const dateStr   = isToday ? 'Today' : fmtDate(node.date.toISOString().slice(0,10));
        const relStr    = isToday ? '' : (() => {
          const diff = Math.round((node.date - now) / MS_PER_DAY);
          if (diff < 0) return `${Math.abs(diff)}d ago`;
          if (diff === 0) return 'today';
          return `in ${diff}d`;
        })();

        const icon = isReorder ? '<svg class="icon" aria-hidden="true"><use href="#i-shopping-cart"></use></svg>' : isOverdue ? '<svg class="icon" aria-hidden="true"><use href="#i-alert-triangle"></use></svg>' : isNext ? '<svg class="icon" aria-hidden="true"><use href="#i-bell"></use></svg>' : isAnchor ? '<svg class="icon" aria-hidden="true"><use href="#i-pin"></use></svg>' : isPast ? '<svg class="icon" aria-hidden="true"><use href="#i-check"></use></svg>' : '○';
        const chip = isReorder
          ? `<span style="font-size:10px;font-weight:700;background:rgba(232,168,56,0.15);color:#e8a838;border:1px solid rgba(232,168,56,0.3);border-radius:99px;padding:1px 7px;font-family:var(--mono)">REORDER</span>`
          : isNext
          ? `<span style="font-size:10px;font-weight:700;background:rgba(76,187,138,0.15);color:${statusColor};border:1px solid rgba(76,187,138,0.3);border-radius:99px;padding:1px 7px;font-family:var(--mono)">NEXT</span>`
          : isOverdue
          ? `<span style="font-size:10px;font-weight:700;background:rgba(232,80,80,0.15);color:#e85050;border:1px solid rgba(232,80,80,0.3);border-radius:99px;padding:1px 7px;font-family:var(--mono)">OVERDUE</span>`
          : '';

        html += `<div style="display:flex;align-items:flex-start;gap:14px;margin-bottom:${idx < nodes.length-1 ? '18' : '4'}px;position:relative">
          <div style="flex-shrink:0;width:${dotSize};height:${dotSize};border-radius:50%;background:${dotBg};border:${dotBorder};margin-top:3px;position:relative;z-index:1;margin-left:calc(-${dotSize}/2 + 1px)"></div>
          <div style="flex:1;min-width:0;padding-bottom:4px">
            <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
              <span style="font-size:14px;font-weight:${fontWeight};color:${nameColor}">${icon} ${esc(node.label)}</span>
              ${chip}
            </div>
            <div style="font-size:12px;color:var(--muted);font-family:var(--mono);margin-top:2px">
              ${dateStr}${relStr ? ` <span style="opacity:0.6">· ${relStr}</span>` : ''}
            </div>
          </div>
        </div>`;
      });

      html += `</div>`;
    }

    // Summary row
    const nextReplaceDate = dueDate ? fmtDate(dueDate.toISOString().slice(0,10)) : '—';
    const reorderNode = nodes.find(n => n.type === 'reorder');
    const reorderDateStr = reorderNode ? fmtDate(reorderNode.date.toISOString().slice(0,10)) : null;
    html += `<div style="margin-top:16px;padding:12px 14px;background:var(--surface2);border-radius:10px;border:1px solid var(--border);font-size:12px;font-family:var(--mono);line-height:2;color:var(--muted)">
      <div><svg class="icon" aria-hidden="true"><use href="#i-bell"></use></svg> <span style="color:var(--text)">Next replacement:</span> ${nextReplaceDate}</div>
      ${reorderDateStr ? `<div><svg class="icon" aria-hidden="true"><use href="#i-shopping-cart"></use></svg> <span style="color:var(--text)">Reorder by:</span> <span style="color:#e8a838">${reorderDateStr}</span></div>` : ''}
      <div><svg class="icon" aria-hidden="true"><use href="#i-repeat"></use></svg> <span style="color:var(--text)">Cycle:</span> every ${r.interval} ${r.unit} (${Math.round(intervalDays)} days)</div>
    </div>`;
  }

  document.getElementById('rtl-body').innerHTML = html;
  openModal('reminder-timeline-modal');
}

function updateRemindersBadge(count) {
  // Add a badge to the Reminders tab if there are overdue/soon items
  const tab = [...document.querySelectorAll('.tab')].find(t => t.textContent.includes('Reminders'));
  if (!tab) return;
  const existing = tab.querySelector('.reminder-badge');
  if (existing) existing.remove();
  if (count > 0) {
    // Ensure the tab can host an absolutely-positioned child. The base .tab
    // rule already sets position:relative, but we set it here defensively
    // in case a future style change breaks that assumption.
    if (getComputedStyle(tab).position === 'static') tab.style.position = 'relative';
    const badge = document.createElement('span');
    badge.className = 'reminder-badge';
    badge.textContent = count;
    // Absolute positioning keeps the badge out of the normal flow, so the
    // tab's "Reminders" label stays centered on mobile (where the tab uses
    // flex-direction:column) and the badge floats in the top-right corner.
    badge.style.cssText = 'position:absolute;top:2px;right:4px;background:var(--danger);color:#fff;font-size:9px;font-weight:700;padding:1px 5px;border-radius:99px;font-family:var(--mono);line-height:1.3;pointer-events:none';
    tab.appendChild(badge);
  }
}

// ── Add / Edit ─────────────────────────────
function openAddReminderModal(prefill) {
  editingReminderId = null;
  document.getElementById('reminder-modal-title').innerHTML = '<svg class="icon icon-md" aria-hidden="true"><use href="#i-bell"></use></svg> Add Reminder';
  document.getElementById('r-name').value          = prefill?.name     || '';
  document.getElementById('r-interval').value      = prefill?.interval || 3;
  document.getElementById('r-unit').value          = prefill?.unit     || 'months';
  document.getElementById('r-last-replaced').value = '';
  document.getElementById('r-notes').value         = '';
  document.getElementById('r-item-link').value     = '';

  // Populate item link dropdown
  const sel = document.getElementById('r-item-link');
  sel.innerHTML = '<option value="">— standalone reminder —</option>'
    + items.filter(i => !i.quickAdded).map(i => `<option value="${i.id}">${esc(i.name)}</option>`).join('');

  // Render suggestion chips
  const sugg = document.getElementById('reminder-suggestions');
  sugg.innerHTML = REMINDER_SUGGESTIONS.map(s =>
    `<button onclick="applySuggestion(${JSON.stringify(s).replace(/"/g,'&quot;')})"
      style="font-size:11px;padding:4px 10px;border-radius:99px;background:var(--surface2);border:1px solid var(--border);color:var(--text);cursor:pointer;white-space:nowrap"
      onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='var(--border)'">${esc(s.name)}</button>`
  ).join('');

  openModal('reminder-modal');
  setTimeout(() => document.getElementById('r-name').focus(), 100);
  // Hide any sharing panel from a previous edit session — no record yet
  // means nothing to override. Panel re-renders on next edit-open.
  const _remSec = document.getElementById('rem-sharing-section');
  if (_remSec) _remSec.style.display = 'none';
}

function applySuggestion(s) {
  document.getElementById('r-name').value     = s.name;
  document.getElementById('r-interval').value = s.interval;
  document.getElementById('r-unit').value     = s.unit;
}

// Register the reminder section with the sharing-panel module. Save path
// is saveReminders. Only standalone reminders (in reminders[]) get
// per-record sharing — item-attached reminders inherit the item's perm
// and are scoped to Round 4+ if there's appetite.
registerSharingSection('reminder', {
  findRecord: (id) => reminders.find(r => r.id === id),
  currentId:  ()   => editingReminderId,
  save:       ()   => saveReminders(),
  mountSectionEl: () => document.getElementById('rem-sharing-section'),
  mountContentEl: () => document.getElementById('rem-sharing-content'),
  noun: 'reminder',
});

// Register the reminder section with the bulk-select module (Pass 2c).
// Scope: STANDALONE reminders ONLY (in the reminders[] array). Item-
// attached reminders (those derived from item.replacementReminders[])
// inherit their parent item's sharing — for those, the user goes to
// Stockroom and overrides the item. We mark item-attached cards as
// data-bulk-disabled in the render so they visually grey out in select
// mode and are skipped by getVisibleIds.
//
// No archive — reminders have no _archived state. Action bar shows
// [All | Share | Delete | Cancel].
registerBulkSelectSection('reminder', {
  findRecord: (id) => reminders.find(r => r.id === id),
  save:       ()   => saveReminders(),
  rerender:   ()   => renderReminders(),
  // Only standalone cards have data-bulk-id (item-attached ones get a
  // data-bulk-disabled instead — see reminderCardHTML), so this selector
  // naturally excludes them.
  getVisibleIds: () => Array.from(document.querySelectorAll('#view-reminders [data-bulk-id][data-bulk-section="reminder"]'))
                        .map(el => el.getAttribute('data-bulk-id'))
                        .filter(Boolean),
  permCheck:  ()   => {
    if (!canWrite('reminders')) { showLockBanner('reminders'); return false; }
    return true;
  },
  applyDelete: (rem) => {
    rem._deletedAt = new Date().toISOString();
    if (typeof touchField === 'function') {
      try { touchField(rem, '_deletedAt'); } catch(_) {}
    }
  },
  // No applyArchive — action bar omits Archive automatically.
  sectionPermKey: 'reminders',
  noun:           'reminder',
  pluralNoun:     'reminders',
});

function openEditReminderModal(id) {
  const r = reminders.find(r => r.id === id);
  if (!r) return;
  editingReminderId = id;
  document.getElementById('reminder-modal-title').innerHTML = '<svg class="icon icon-md" aria-hidden="true"><use href="#i-bell"></use></svg> Edit Reminder';
  document.getElementById('r-name').value          = r.name     || '';
  document.getElementById('r-interval').value      = r.interval || 3;
  document.getElementById('r-unit').value          = r.unit     || 'months';
  document.getElementById('r-last-replaced').value = r.lastReplaced || '';
  document.getElementById('r-notes').value         = r.notes    || '';
  const sel = document.getElementById('r-item-link');
  sel.innerHTML = '<option value="">— standalone reminder —</option>'
    + items.filter(i => !i.quickAdded).map(i => `<option value="${i.id}">${esc(i.name)}</option>`).join('');
  sel.value = r.linkedItemId || '';
  openModal('reminder-modal');
  // Render the sharing panel for this reminder. Hidden by openSharingPanelFor
  // when no shares exist or when not the owner.
  openSharingPanelFor('reminder');
}

async function saveReminder() {
  if (!canWrite("reminders")) { showLockBanner("reminders"); return; }
  const name = document.getElementById('r-name').value.trim();
  if (!name) { toast('Enter a name for this reminder'); return; }

  const intervalVal = parseInt(document.getElementById('r-interval').value) || 3;
  const unit        = document.getElementById('r-unit').value;
  const lastDate    = document.getElementById('r-last-replaced').value;
  const notes       = document.getElementById('r-notes').value.trim();
  const linkedItemId = document.getElementById('r-item-link').value || null;

  if (editingReminderId) {
    const r = reminders.find(r => r.id === editingReminderId);
    if (r) {
      r.name = name; r.interval = intervalVal; r.unit = unit;
      r.lastReplaced = lastDate || r.lastReplaced; r.notes = notes;
      r.linkedItemId = linkedItemId;
    }
  } else {
    reminders.push({
      id:           uid(),
      name,
      interval:     intervalVal,
      unit,
      lastReplaced: lastDate || null,
      notes,
      linkedItemId,
      createdAt:    new Date().toISOString(),
    });
  }

  // Also update linked item's replacement fields
  if (linkedItemId) {
    const item = items.find(i => i.id === linkedItemId);
    if (item) {
      item.replacementInterval = intervalVal;
      item.replacementUnit     = unit;
      item.lastReplaced        = lastDate || item.lastReplaced || null;
      touchItem(item);
      await saveData();
    }
  }

  await saveReminders();
  closeModal('reminder-modal');
  renderReminders();
  setTimeout(syncAll, 400);
  toast('Reminder saved ✓');
}

async function deleteReminder(id) {
  if (!canWrite('reminders')) { showLockBanner('reminders'); return; }

  const isItemReminder = id.startsWith('item_');

  if (isItemReminder) {
    const resolved = _resolveReminderId(id);
    if (!resolved) return;
    const { item, remEntry } = resolved;
    const name = resolved.r.reminderName ? `${item.name} — ${resolved.r.reminderName}` : item.name;
    const confirmed = confirm(
      `Delete the replacement reminder "${name}"?\n\nThe item itself will remain in your Stockroom.`
    );
    if (!confirmed) return;

    if (remEntry && item.replacementReminders) {
      // New array format — remove specific reminder
      item.replacementReminders = item.replacementReminders.filter(r => r.id !== remEntry.id);
      // Sync legacy fields to first remaining reminder
      if (item.replacementReminders?.length) {
        item.replacementInterval = item.replacementReminders[0].interval;
        item.replacementUnit     = item.replacementReminders[0].unit;
      } else {
        item.replacementInterval = null;
        item.replacementUnit     = null;
      }
    } else {
      // Legacy single reminder
      item.replacementInterval = null;
      item.replacementUnit     = null;
    }
    touchField(item, 'replacementInterval', 'replacementReminders');
    await saveData();
    await kvSyncNow(true);
    renderReminders();
    scheduleRender('grid', 'dashboard');
    toast('Reminder deleted');
  } else {
    const reminder = reminders.find(r => r.id === id);
    if (!reminder) return;
    const name = reminder.name || 'this reminder';
    const confirmed = confirm(
      `Move "${name}" to recycle bin?\n\n` +
      `You can restore it within 30 days from the bottom of the Reminders view.`
    );
    if (!confirmed) return;
    reminder._deletedAt = new Date().toISOString();
    if (typeof touchField === 'function') {
      try { touchField(reminder, '_deletedAt'); } catch(e) {}
    }
    await saveReminders();
    _syncQueue.enqueue();
    renderReminders();
    toast('Moved to recycle bin');
    _maybeShowBinHint('reminders');
  }
}

async function restoreReminder(id) {
  const reminder = reminders.find(r => r.id === id);
  if (!reminder) return;
  delete reminder._deletedAt;
  if (typeof touchField === 'function') {
    try { touchField(reminder, '_deletedAt'); } catch(e) {}
  }
  await saveReminders();
  _syncQueue.enqueue();
  renderReminders();
  toast('Reminder restored');
}

async function purgeReminderForever(id) {
  const reminder = reminders.find(r => r.id === id);
  if (!reminder) return;
  if (!confirm(`Permanently delete "${reminder.name || 'this reminder'}"? This cannot be undone.`)) return;
  reminders = reminders.filter(r => r.id !== id);
  await addReminderTombstone(id);
  await saveReminders();
  _syncQueue.enqueue();
  renderReminders();
  toast('Permanently deleted');
}

async function emptyRemindersBin() {
  const trashed = reminders.filter(_isInRecycleBin);
  if (!trashed.length) return;
  if (!confirm(
    `Permanently delete ${trashed.length} reminder${trashed.length===1?'':'s'} from the recycle bin? This cannot be undone.`
  )) return;
  for (const r of trashed) await addReminderTombstone(r.id);
  reminders = reminders.filter(r => !_isInRecycleBin(r));
  await saveReminders();
  _syncQueue.enqueue();
  renderReminders();
  toast('Recycle bin emptied');
}

// ── Log replacement ───────────────────────
function openLogReplacementModal(id) {
  loggingReminderId = id;
  const resolved = _resolveReminderId(id);
  const name     = resolved?.r.name || '';
  const interval = resolved?.r ? `${resolved.r.interval} ${resolved.r.unit}` : '';

  document.getElementById('log-replacement-title').textContent    = `Replaced: ${name}`;
  document.getElementById('log-replacement-subtitle').textContent = interval ? `Next replacement in ${interval}` : 'When did you replace it?';
  document.getElementById('log-replacement-date').value           = today();
  openModal('log-replacement-modal');
}

async function confirmLogReplacement() {
  if (!canWrite("reminders")) { showLockBanner("reminders"); return; }
  const date = document.getElementById('log-replacement-date').value || today();
  const id   = loggingReminderId;

  if (id.startsWith('item_')) {
    const resolved = _resolveReminderId(id);
    if (resolved?.remEntry) {
      // New array format — update specific reminder's lastReplaced
      resolved.remEntry.lastReplaced = date;
      touchField(resolved.item, 'replacementReminders');
      await saveData();
    } else if (resolved?.item) {
      // Legacy single-reminder format
      resolved.item.lastReplaced = date;
      touchField(resolved.item, 'lastReplaced');
      await saveData();
    }
  } else {
    const r = reminders.find(r => r.id === id);
    if (r) { r.lastReplaced = date; await saveReminders(); }
    if (r?.linkedItemId) {
      const item = items.find(i => i.id === r.linkedItemId);
      if (item) { item.lastReplaced = date; touchField(item, 'lastReplaced'); await saveData(); }
    }
  }

  closeModal('log-replacement-modal');
  renderReminders();
  setTimeout(syncAll, 400);
  toast('Replacement logged ✓');
}

// ── Smart reminder actions ──────────────────
async function applyReminderReplaced(reminderId, date, token) {
  // Verify via backend then apply locally
  try {
    const res  = await fetch(`${WORKER_URL}/reminder-pending?id=${encodeURIComponent(reminderId)}&token=${encodeURIComponent(token)}`);
    const data = await res.json();
    // Whether KV has it or not, apply locally with the provided date
    const useDate = data.date || date || today();
    _applyReplacedLocally(reminderId, useDate);
  } catch(e) {
    // Offline or error — still apply locally
    _applyReplacedLocally(reminderId, date || today());
  }
}

async function _applyReplacedLocally(reminderId, date) {
  let changed = false;
  if (reminderId.startsWith('item_')) {
    const resolved = _resolveReminderId(reminderId);
    if (resolved?.remEntry) {
      resolved.remEntry.lastReplaced = date;
      touchField(resolved.item, 'replacementReminders');
      await saveData();
      changed = true;
    } else if (resolved?.item) {
      resolved.item.lastReplaced = date;
      touchField(resolved.item, 'lastReplaced');
      await saveData();
      changed = true;
    }
  } else {
    const r = reminders.find(r => r.id === reminderId);
    if (r) {
      r.lastReplaced = date;
      await saveReminders();
      changed = true;
      if (r.linkedItemId) {
        const item = items.find(i => i.id === r.linkedItemId);
        if (item) { item.lastReplaced = date; touchField(item, 'lastReplaced'); await saveData(); }
      }
    }
  }
  if (changed) {
    renderReminders();
    setTimeout(syncAll, 400);
    showToast('✅ Marked as replaced');
    bcPost({ type: 'REMINDER_REPLACED', reminderId, date });
    // Refresh future-push schedule — the just-completed cycle's push
    // (if any was queued for the about-to-fire moment) is now stale,
    // and the next cycle needs queuing. _syncReminderPushes is
    // idempotent so cancelling the stale one isn't strictly needed —
    // it'll fire harmlessly and the SW will show a notification the
    // user may briefly find puzzling. To avoid that, explicitly
    // cancel the old sourceRef pattern (any future-dated push for
    // THIS reminder gets cancelled because its sourceRef prefix is
    // 'reminder:<reminderId>:' — server-side cancel is by exact match
    // though, so we'd need a separate "cancel by prefix" endpoint.
    // For now, accept the rare edge case; a fresh schedule catches it
    // most of the time because the SAME-day case re-uses the same
    // sourceRef (date-stamped) and dedupe replaces it.
    if (typeof syncReminderPushesDebounced === 'function') syncReminderPushesDebounced();
  }
}

// Poll backend for any reminder replacements triggered via email (runs on load + visibility change)
async function pollReminderReplacements() {
  if (!WORKER_URL) return;
  const allR = [
    ...reminders,
    ...items.flatMap(i => {
      const base = { lastReplaced: i.lastReplaced || i.startedUsing || i.logs?.filter(l=>!l.pendingDelivery)[0]?.date || null };
      if (i.replacementReminders?.length) {
        return i.replacementReminders.map(r => ({
          id: `item_${i.id}_${r.id}`, name: r.name ? `${i.name} — ${r.name}` : i.name,
          interval: r.interval, unit: r.unit,
          lastReplaced: r.lastReplaced || base.lastReplaced,
        }));
      } else if (i.replacementInterval) {
        return [{ id: 'item_' + i.id, name: i.name, interval: i.replacementInterval, unit: i.replacementUnit, lastReplaced: base.lastReplaced }];
      }
      return [];
    }),
  ].filter(r => ['overdue','soon','today'].includes(getReminderStatus(r)));

  for (const r of allR) {
    try {
      const tokenRes  = await fetch(`${WORKER_URL}/reminder-token`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ reminderId: r.id }) });
      const { token } = await tokenRes.json();
      if (!token) continue;
      const checkRes  = await fetch(`${WORKER_URL}/reminder-pending?id=${encodeURIComponent(r.id)}&token=${encodeURIComponent(token)}`);
      const check     = await checkRes.json();
      if (check.replaced) _applyReplacedLocally(r.id, check.date || today());
    } catch(e) { /* ignore network errors */ }
  }
}

// ── In-app notification check ─────────────
async function checkReminderNotifications() {
  // Compute due/overdue regardless of notifEnabled — the in-app inbox
  // should populate even when push notifications are disabled. Push is a
  // separate channel below.
  const allReminders = [
    ...reminders.filter(r => !r._deletedAt),
    ...items.filter(i => !i._deletedAt).flatMap(i => {
      const base = { lastReplaced: i.lastReplaced || i.startedUsing || i.logs?.filter(l=>!l.pendingDelivery)[0]?.date || null };
      if (i.replacementReminders?.length) {
        return i.replacementReminders.map(r => ({
          id: `item_${i.id}_${r.id}`, name: r.name ? `${i.name} — ${r.name}` : i.name,
          interval: r.interval, unit: r.unit,
          lastReplaced: r.lastReplaced || base.lastReplaced,
        }));
      } else if (i.replacementInterval) {
        return [{ id: 'item_' + i.id, name: i.name, interval: i.replacementInterval, unit: i.replacementUnit, lastReplaced: base.lastReplaced }];
      }
      return [];
    }),
  ];

  const overdue  = allReminders.filter(r => getReminderStatus(r) === 'overdue');
  const dueToday = allReminders.filter(r => getReminderDaysUntil(r) === 0);

  if (!overdue.length && !dueToday.length) return;

  // Always populate the in-app inbox — this is independent of the push
  // notification channel. Dedupe by sourceRef inside addNotification.
  for (const r of [...overdue, ...dueToday]) {
    const days = getReminderDaysUntil(r);
    const body = getReminderStatus(r) === 'overdue'
      ? `Overdue by ${Math.abs(days)} day${Math.abs(days) !== 1 ? 's' : ''}`
      : 'Due today';
    try {
      await addNotification({
        type: 'reminder',
        title: r.name,
        body,
        sourceRef: `reminder:${r.id}`,
      });
    } catch(e) { /* never let inbox errors block reminder push */ }
  }

  // Below: existing push-notification path (gated on notifEnabled)
  if (!notifEnabled || Notification.permission !== 'granted') return;

  const today2 = new Date().toISOString().slice(0,10);
  if (localStorage.getItem('stockroom_last_reminder_notif') === today2) return;

  // Send one notification per due/overdue reminder (up to 3) with a Replaced action button
  const toNotify = [...overdue, ...dueToday].slice(0, 3);
  toNotify.forEach(r => sendReminderActionNotification(r));
  localStorage.setItem('stockroom_last_reminder_notif', today2);
}

async function sendReminderActionNotification(r) {
  if (!('serviceWorker' in navigator) || !navigator.serviceWorker.controller) {
    // Fallback: plain notification
    sendLocalNotification(`🔔 ${r.name}`, 'Tap to open STOCKROOM', 'stockroom-reminder-' + r.id);
    return;
  }
  // Fetch a token for this reminder so the SW can call /reminder-done
  let token = '';
  try {
    const res = await fetch(`${WORKER_URL}/reminder-token`, {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ reminderId: r.id }),
    });
    const data = await res.json();
    token = data.token || '';
  } catch(e) { /* no token — will open app instead */ }

  const status = getReminderStatus(r);
  const body   = status === 'overdue'
    ? `Overdue by ${Math.abs(getReminderDaysUntil(r))} day${Math.abs(getReminderDaysUntil(r)) !== 1 ? 's' : ''}`
    : 'Due today';

  const reg = await navigator.serviceWorker.ready;
  reg.showNotification(`🔔 ${r.name}`, {
    body,
    tag:       'stockroom-reminder-' + r.id,
    renotify:  true,
    icon:      './icon-192.png',
    badge:     './icon-192.png',
    actions: [
      { action: 'replaced', title: '✅ Replaced' },
      { action: 'open',     title: '📦 Open app' },
    ],
    data: {
      url:        window.location.href,
      reminderId: r.id,
      reminderName: r.name,
      token,
      workerUrl:  WORKER_URL,
    },
  });
}


async function markOrdered(id) {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === id);
  if (!item) return;
  // Snapshot before so undo/restore can roll back exactly.
  const before = JSON.parse(JSON.stringify(item));
  item.ordered   = true;
  item.orderedAt = new Date().toISOString();
  touchField(item, 'ordered','orderedAt');
  await saveData();
  scheduleRender('grid', 'dashboard', 'shopping');
  setTimeout(syncAll, 400);
  // Log to history with bound inverses for Cmd+Z. Skipped silently
  // during undo/redo replay (historyRecord respects _historyApplying).
  historyRecord({
    type: 'order',
    domain: 'item',
    recordId: item.id,
    recordName: item.name,
    before,
    after: JSON.parse(JSON.stringify(item)),
    undo: async () => { await unmarkOrdered(item.id); },
    redo: async () => { await markOrdered(item.id); },
  });
  toastWithUndo(`📦 ${item.name} marked as ordered`);
}

async function unmarkOrdered(id) {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === id);
  if (!item) return;
  const before = JSON.parse(JSON.stringify(item));
  item.ordered   = false;
  item.orderedAt = null;
  touchField(item, 'ordered','orderedAt');
  await saveData();
  scheduleRender('grid', 'dashboard', 'shopping');
  setTimeout(syncAll, 400);
  historyRecord({
    type: 'unorder',
    domain: 'item',
    recordId: item.id,
    recordName: item.name,
    before,
    after: JSON.parse(JSON.stringify(item)),
    undo: async () => { await markOrdered(item.id); },
    redo: async () => { await unmarkOrdered(item.id); },
  });
  toastWithUndo(`Removed ordered status: ${item.name}`);
}

// ═══════════════════════════════════════════
//  30 — COMPACT VIEW
// ═══════════════════════════════════════════
function toggleCompactView() {
  compactView = !compactView;
  const grid = document.getElementById('items-grid');
  const btn  = document.getElementById('compact-toggle-btn');
  if (grid) grid.classList.toggle('compact-view', compactView);
  if (btn)  btn.textContent = compactView ? '⊞' : '⊟';
  try { localStorage.setItem('stockroom_compact', compactView ? '1' : ''); } catch(e){}
}

function loadCompactView() {
  compactView = !!localStorage.getItem('stockroom_compact');
  const grid = document.getElementById('items-grid');
  const btn  = document.getElementById('compact-toggle-btn');
  if (grid && compactView) grid.classList.add('compact-view');
  if (btn) btn.textContent = compactView ? '⊞' : '⊟';
}

// ═══════════════════════════════════════════
//  19 — HOUSEHOLD PROFILES
// ═══════════════════════════════════════════
async function getProfiles() {
  const stored = await dbGet('profiles', 'profiles');
  if (stored) return stored;
  // Migration from localStorage
  try {
    const raw = localStorage.getItem('stockroom_profiles');
    if (raw) {
      const profiles = JSON.parse(raw) || {};
      await dbPut('profiles', 'profiles', profiles);
      localStorage.removeItem('stockroom_profiles');
      return profiles;
    }
  } catch(e) {}
  return {};
}

async function saveProfiles(profiles) {
  await dbPut('profiles', 'profiles', profiles);
}

async function loadProfile(key) {
  activeProfile = key || 'default';
  try { localStorage.setItem('stockroom_active_profile', activeProfile); } catch(e){}
  const profiles  = await getProfiles();
  const profile   = profiles[activeProfile];
  if (profile) {
    const deletedIds = await loadDeletedIds();
    items        = (profile.items || []).filter(i => !deletedIds.has(i.id));
    settings     = { threshold: 20, country: 'GB', ...profile.settings };
    // The profile blob is a snapshot — _saveSettings() writes to IDB but not
    // to the profile, so settings flags (banner dismissals, MFA prompts, etc)
    // can be stale here. Re-read from IDB and overlay so the latest local
    // edits win. Without this, dismissed banners reappear after init.
    try {
      const liveSettings = await dbGet('settings', 'settings');
      if (liveSettings && typeof liveSettings === 'object') {
        settings = { ...settings, ...liveSettings };
      }
    } catch (e) { /* fall back to profile settings */ }
    reminders    = profile.reminders   || [];
    groceryItems = profile.groceries   || [];
    groceryDepts = profile.departments?.length ? profile.departments : DEFAULT_DEPTS.map(d => ({...d}));
  } else {
    await loadData();
    await loadReminders();
    await loadGrocery();
    await loadBudget();
    await loadBudgetSpend();
    await loadBudgetAccountsAndIncome();
    await saveCurrentProfile();
  }
  // Sweep expired items from the 30-day recycle bin
  await purgeExpiredFromBins();
  // Notifications are user-scoped (not per-profile), so we always load them
  // here too — they survive profile switches. The bell badge updates as a
  // side-effect of loadNotifications via _renderNotificationBellBadge.
  await loadNotifications();
  _renderNotificationBellBadge();
  updateProfileLabel();
  scheduleRender(...RENDER_REGIONS);
  updateSyncUI();
  applyTabPermissions();
}

async function saveCurrentProfile() {
  const deletedIds = await loadDeletedIds();
  const profiles = await getProfiles();
  const existing = profiles[activeProfile] || {};
  profiles[activeProfile] = {
    ...existing,
    items:       JSON.parse(JSON.stringify(items.filter(i => !deletedIds.has(i.id)))),
    settings,
    reminders:   JSON.parse(JSON.stringify(reminders)),
    groceries:   JSON.parse(JSON.stringify(groceryItems)),
    departments: JSON.parse(JSON.stringify(groceryDepts)),
  };
  await saveProfiles(profiles);
}

async function updateProfileLabel() {
  const profiles = await getProfiles();
  const profile  = profiles[activeProfile];
  const name     = profile?.name || (activeProfile === 'default' ? 'Home' : activeProfile);
  const colour   = profile?.colour || '#e8a838';
  const label    = document.getElementById('profile-label');
  if (label) {
    label.className = 'profile-label-subtitle';
    label.innerHTML = `/ <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${colour};margin-right:4px;vertical-align:middle"></span>${name.toUpperCase()}`;
  }
}

function openProfilePicker() {
  renderProfileList();
  openModal('profile-modal');
}

const HOUSEHOLD_COLOURS = [
  '#e8a838','#5b8dee','#4cbb8a','#e85050','#b45dee',
  '#ee8c5b','#5bdee8','#dee85b','#ee5bab','#7880a0',
];
const MAX_HOUSEHOLDS = 5;

async function renderProfileList() {
  const profiles = await getProfiles();
  const list     = document.getElementById('profile-list');
  const addSec   = document.getElementById('profile-add-section');
  if (!list) return;

  if (!profiles['default']) profiles['default'] = { name: 'Home', colour: '#e8a838', items: [], settings: {} };

  const entries = Object.entries(profiles);
  if (addSec) addSec.style.display = entries.length >= MAX_HOUSEHOLDS ? 'none' : 'block';

  list.innerHTML = entries.map(([key, p]) => {
    const isActive = key === activeProfile;
    const colour   = p.colour || '#e8a838';
    const count    = (p.items || []).length;
    const reminderCount = (p.reminders || []).length;
    const syncFile = p.driveFileName ? `<span style="font-size:10px;color:var(--muted);font-family:var(--mono)">${esc(p.driveFileName)}</span>` : '';
    return `<div style="display:flex;align-items:center;gap:10px;padding:12px 14px;background:${isActive ? 'rgba(232,168,56,0.08)' : 'var(--surface2)'};border:2px solid ${isActive ? colour : 'var(--border)'};border-radius:12px;transition:border-color 0.2s">
      <div style="width:14px;height:14px;border-radius:50%;background:${colour};flex-shrink:0;box-shadow:0 1px 4px rgba(0,0,0,0.3)"></div>
      <div style="flex:1;min-width:0">
        <div style="font-size:14px;font-weight:700;color:${isActive ? colour : 'var(--text)'}">${esc(p.name || key)}${isActive ? ' ✓' : ''}</div>
        <div style="font-size:11px;color:var(--muted);font-family:var(--mono)">${count} item${count!==1?'s':''} · ${reminderCount} reminder${reminderCount!==1?'s':''}</div>
        ${syncFile}
      </div>
      <div style="display:flex;gap:6px;flex-shrink:0">
        ${!isActive ? `<button class="btn btn-primary btn-sm" onclick="switchProfile('${key}')">Switch</button>` : '<span style="font-size:11px;color:var(--accent);font-weight:700">Active</span>'}
        <button class="btn btn-ghost btn-sm" onclick="openHouseholdEdit('${key}')" title="Edit"><svg class="icon" aria-hidden="true"><use href="#i-pencil"></use></svg></button>
        ${key !== 'default' ? `<button class="btn btn-ghost btn-sm" style="color:var(--danger)" onclick="deleteProfile('${key}')" title="Delete"><svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg></button>` : ''}
      </div>
    </div>`;
  }).join('');
}

function openHouseholdEdit(key) {
  getProfiles().then(profiles => {
    const p = profiles[key] || {};
    document.getElementById('household-edit-key').value  = key;
    document.getElementById('household-edit-name').value = p.name || '';
    const currentColour = p.colour || '#e8a838';
    const colourPicker  = document.getElementById('household-edit-colours');
    if (colourPicker) {
      colourPicker.innerHTML = HOUSEHOLD_COLOURS.map(c => `
        <div onclick="selectHouseholdColour('${c}')"
          data-colour="${c}"
          style="width:28px;height:28px;border-radius:50%;background:${c};cursor:pointer;
                 border:3px solid ${c === currentColour ? 'var(--text)' : 'transparent'};
                 transition:border-color 0.15s;box-shadow:0 2px 6px rgba(0,0,0,0.3)"></div>
      `).join('');
    }
    openModal('household-edit-modal');
  });
}

function selectHouseholdColour(colour) {
  document.querySelectorAll('#household-edit-colours [data-colour]').forEach(el => {
    el.style.borderColor = el.dataset.colour === colour ? 'var(--text)' : 'transparent';
  });
}

async function saveHouseholdEdit() {
  const key    = document.getElementById('household-edit-key').value;
  const name   = document.getElementById('household-edit-name').value.trim();
  if (!name) { toast('Enter a name'); return; }
  const selected = document.querySelector('#household-edit-colours [style*="var(--text)"]');
  const colour   = selected?.dataset.colour || '#e8a838';
  const profiles = await getProfiles();
  if (profiles[key]) {
    profiles[key].name   = name;
    profiles[key].colour = colour;
    await saveProfiles(profiles);
  }
  closeModal('household-edit-modal');
  renderProfileList();
  renderSettingsHouseholdList();
  if (key === activeProfile) updateProfileLabel();
  toast('Household updated ✓');
  _syncQueue.enqueue();
}

async function switchProfile(key) {
  await saveCurrentProfile();
  closeModal('profile-modal');
  await loadProfile(key);
  const profiles = await getProfiles();
  toast(`Switched to ${profiles[key]?.name || key}`);
}

async function addProfile() {
  const profiles = await getProfiles();
  if (Object.keys(profiles).length >= MAX_HOUSEHOLDS) {
    toast(`Maximum ${MAX_HOUSEHOLDS} households reached`);
    return;
  }
  const nameEl  = document.getElementById('new-profile-name');
  const count   = Object.keys(profiles).length + 1;
  const name    = nameEl?.value.trim() || `Home ${count}`;
  const colour  = HOUSEHOLD_COLOURS[count % HOUSEHOLD_COLOURS.length];
  const key     = 'profile_' + Date.now();
  profiles[key] = {
    name,
    colour,
    items:       [],
    settings:    { threshold: 20, country: settings.country || 'GB' },
    reminders:   [],
    groceries:   [],
    departments: DEFAULT_DEPTS.map(d => ({...d})),
  };
  await saveProfiles(profiles);
  if (nameEl) nameEl.value = '';
  renderProfileList();
  renderSettingsHouseholdList();
  toast(`"${name}" created — switch to it to set it up`);
  // Sync so new household persists across devices and reloads
  _syncQueue.enqueue();
}

async function deleteProfile(key) {
  const profiles = await getProfiles();
  const name = profiles[key]?.name || key;
  if (!confirm(`Delete "${name}" and all its items, groceries and reminders?\n\nThis cannot be undone.`)) return;
  delete profiles[key];
  await saveProfiles(profiles);
  // Record this key as deleted so the sync merge doesn't re-create it
  _addDeletedHousehold(key);
  if (activeProfile === key) await loadProfile('default');
  renderProfileList();
  renderSettingsHouseholdList();
  toast(`"${name}" deleted`);
  _syncQueue.enqueue();
}

function _getDeletedHouseholds() {
  try { return new Set(JSON.parse(localStorage.getItem('stockroom_deleted_households') || '[]')); }
  catch(e) { return new Set(); }
}
function _addDeletedHousehold(key) {
  const set = _getDeletedHouseholds();
  set.add(key);
  try { localStorage.setItem('stockroom_deleted_households', JSON.stringify([...set])); } catch(e) {}
}

// ═══════════════════════════════════════════
//  20 — EXPIRY DATES
// ═══════════════════════════════════════════
function getExpiryStatus(item) {
  if (!item.expiry) return null;
  const daysUntil = Math.floor((new Date(item.expiry + 'T12:00:00') - Date.now()) / MS_PER_DAY);
  if (daysUntil < 0)   return { label: 'Expired', color: 'var(--danger)', days: daysUntil };
  if (daysUntil <= 30) return { label: `Expires in ${daysUntil}d`, color: 'var(--warn)', days: daysUntil };
  return { label: `Expires ${fmtDate(item.expiry)}`, color: 'var(--muted)', days: daysUntil };
}

// ═══════════════════════════════════════════
//  21 — REORDER POINT OVERRIDE
// ═══════════════════════════════════════════
function getItemThreshold(item) {
  return item.thresholdOverride ?? settings.threshold ?? 20;
}

// Patch getStatus to use per-item threshold
const _origGetStatus = getStatus;
// eslint-disable-next-line no-global-assign
function getStatus(pct, threshold, item) {
  const t = item ? getItemThreshold(item) : (threshold ?? 20);
  if (pct === null || pct === undefined) return 'nodata';
  if (pct <= t / 2) return 'critical';
  if (pct <= t) return 'warn';
  return 'ok';
}

// ═══════════════════════════════════════════
//  23 — SMART REORDER SUGGESTION
// ═══════════════════════════════════════════
function getReorderSuggestion(item) {
  if (!item.logs || item.logs.length < 2) return null;

  // Average days between purchases
  const sorted = [...item.logs].sort((a, b) => new Date(a.date) - new Date(b.date));
  const gaps   = [];
  for (let i = 1; i < sorted.length; i++) {
    const gap = (new Date(sorted[i].date) - new Date(sorted[i-1].date)) / MS_PER_DAY;
    if (gap > 0) gaps.push(gap);
  }
  if (!gaps.length) return null;

  const avgGapDays = gaps.reduce((a,b) => a+b, 0) / gaps.length;
  const avgQty     = sorted.reduce((a,b) => a + (b.qty || 1), 0) / sorted.length;
  const totalDays  = getTotalDaysForUnits(item, item.qty || 1);

  // How many units to cover until next shop window?
  const shopWindowDays = Math.min(avgGapDays, 30);
  const suggestedQty   = Math.ceil((shopWindowDays / Math.max(1, totalDays)) * (item.qty || 1));

  return {
    qty: Math.max(1, suggestedQty),
    shopWindowDays: Math.round(shopWindowDays),
    avgGapDays: Math.round(avgGapDays),
  };
}

// ═══════════════════════════════════════════
//  35 — USAGE ANALYTICS
// ═══════════════════════════════════════════
function openAnalyticsModal(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;

  const titleEl   = document.getElementById('analytics-title');
  const contentEl = document.getElementById('analytics-content');
  if (!titleEl || !contentEl) return;

  titleEl.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-bar-chart-2"></use></svg> ${esc(item.name)}`;

  if (!item.logs || item.logs.length < 2) {
    contentEl.innerHTML = `<p style="color:var(--muted);font-size:13px">Not enough purchase history yet. Log at least 2 purchases to see analytics.</p>`;
    openModal('analytics-modal');
    return;
  }

  const sorted = [...item.logs].sort((a,b) => new Date(a.date) - new Date(b.date));
  const gaps   = [];
  for (let i = 1; i < sorted.length; i++) {
    const gap = (new Date(sorted[i].date) - new Date(sorted[i-1].date)) / MS_PER_DAY;
    if (gap > 0) gaps.push({ gap: Math.round(gap), date: sorted[i].date });
  }

  const avgGap  = Math.round(gaps.reduce((a,b) => a+b.gap, 0) / gaps.length);
  const minGap  = Math.min(...gaps.map(g => g.gap));
  const maxGap  = Math.max(...gaps.map(g => g.gap));
  const prices  = sorted.filter(l => l.price).map(l => ({ val: parsePriceValue(l.price), raw: l.price, date: l.date })).filter(p => p.val);
  const avgPrice = prices.length ? prices.reduce((a,b) => a + b.val, 0) / prices.length : null;
  const totalSpend = prices.reduce((a,b) => a + b.val, 0);

  const suggestion = getReorderSuggestion(item);

  // Mini gap chart
  const barW = 100 / gaps.length;
  const maxG  = Math.max(...gaps.map(g => g.gap), 1);
  const gapBars = gaps.map(g =>
    `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:2px" title="${g.date}: ${g.gap} days">
      <div style="width:100%;max-width:32px;height:${Math.round((g.gap/maxG)*60)+4}px;background:var(--accent2);border-radius:3px 3px 0 0;opacity:0.8"></div>
      <div style="font-size:9px;color:var(--muted);font-family:var(--mono)">${g.gap}d</div>
    </div>`
  ).join('');

  contentEl.innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px">
      <div style="background:var(--surface2);border-radius:10px;padding:12px">
        <div style="font-size:11px;color:var(--muted);font-family:var(--mono);margin-bottom:4px">AVG RESTOCK</div>
        <div style="font-size:22px;font-weight:700;color:var(--text)">${avgGap}<span style="font-size:13px;color:var(--muted)">d</span></div>
        <div style="font-size:11px;color:var(--muted)">range: ${minGap}–${maxGap} days</div>
      </div>
      <div style="background:var(--surface2);border-radius:10px;padding:12px">
        <div style="font-size:11px;color:var(--muted);font-family:var(--mono);margin-bottom:4px">TOTAL SPEND</div>
        <div style="font-size:22px;font-weight:700;color:var(--ok)">£${totalSpend.toFixed(2)}</div>
        <div style="font-size:11px;color:var(--muted)">${prices.length} purchase${prices.length !== 1 ? 's' : ''}${avgPrice ? ` · avg £${avgPrice.toFixed(2)}` : ''}</div>
      </div>
    </div>
    ${gaps.length > 1 ? `
    <div style="margin-bottom:16px">
      <div style="font-size:11px;color:var(--muted);font-family:var(--mono);margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px">Days between restocks</div>
      <div style="display:flex;align-items:flex-end;gap:3px;height:72px">${gapBars}</div>
    </div>` : ''}
    ${suggestion ? `
    <div style="background:rgba(232,168,56,0.08);border:1px solid rgba(232,168,56,0.2);border-radius:10px;padding:12px;margin-bottom:12px">
      <div style="font-size:12px;font-weight:700;color:var(--accent);margin-bottom:4px"><svg class="icon" aria-hidden="true"><use href="#i-lightbulb"></use></svg> Smart Reorder Suggestion</div>
      <div style="font-size:13px;color:var(--text)">Buy <strong>×${suggestion.qty}</strong> — covers your typical ${suggestion.shopWindowDays}-day shop window</div>
      <div style="font-size:11px;color:var(--muted);margin-top:3px">Based on your avg restock interval of ${suggestion.avgGapDays} days</div>
    </div>` : ''}
    <div style="font-size:11px;color:var(--muted);font-family:var(--mono)">
      First purchased: ${fmtDate(sorted[0].date)} · Total purchases: ${sorted.length}
    </div>`;

  openModal('analytics-modal');
}

// ═══════════════════════════════════════════
//  28 — CAMERA PHOTO
// ═══════════════════════════════════════════
let cameraStream = null;

function openCameraModal() {
  // Free-tier photo gate — prompt to upgrade rather than open the camera.
  try {
    if (window.stockroomBilling && stockroomBilling.isFree() && !stockroomBilling.featureAllowed('photos')) {
      if (typeof toastAction === 'function') {
        toastAction('Item photos require a paid plan', { label: 'Upgrade', onClick: () => navTo('billing') });
      } else {
        toast('Item photos require a paid plan — open Billing to upgrade');
      }
      return;
    }
  } catch (_) {}
  openModal('camera-modal');
  const video = document.getElementById('camera-video');
  navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
    .then(stream => { cameraStream = stream; video.srcObject = stream; })
    .catch(() => { toast('Could not access camera — check permissions'); closeModal('camera-modal'); });
}

function closeCameraModal() {
  if (cameraStream) { cameraStream.getTracks().forEach(t => t.stop()); cameraStream = null; }
  closeModal('camera-modal');
}

function capturePhoto() {
  const video  = document.getElementById('camera-video');
  const canvas = document.createElement('canvas');
  canvas.width  = video.videoWidth  || 640;
  canvas.height = video.videoHeight || 480;
  canvas.getContext('2d').drawImage(video, 0, 0);
  const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
  pendingImageUrl = dataUrl;
  showImagePreview(dataUrl, 'Photo captured');
  closeCameraModal();
}

// ═══════════════════════════════════════════
//  36 — SHARED HOUSEHOLD / JOIN CODE
// ═══════════════════════════════════════════
function generateJoinCode() {
  // 6-character alphanumeric code stored in localStorage
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let code = '';
  for (let i = 0; i < 6; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return code;
}

function getOrCreateJoinCode() {
  let code = localStorage.getItem('stockroom_join_code');
  if (!code) { code = generateJoinCode(); localStorage.setItem('stockroom_join_code', code); }
  return code;
}

function renderHealthDashboard() {
  // No-op: status counts are now rendered on the chips inside the
  // collapsible Filters panel (#filter-bar) via _renderStatusCounts(),
  // which buildTagFilterBar() also invokes. We keep the function so
  // existing scheduleRender('dashboard') calls don't error.
  const el = document.getElementById('health-dashboard');
  if (el) el.innerHTML = '';
  // Re-render tag filter bar so status counts stay current
  try { buildTagFilterBar(); } catch(_) {}
}

// ═══════════════════════════════════════════
//  DELETE LOG ENTRIES
// ═══════════════════════════════════════════
async function deleteLogEntry(itemId, logId) {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === itemId);
  if (!item) return;
  // Tier 6.2: destructive-action confirm. Deleting a log entry is
  // permanent (no recycle bin for individual log rows), so guard it
  // like every other destructive path in the app.
  if (!confirm('Delete this log entry? This cannot be undone.')) return;
  item.logs = (item.logs||[]).filter(l => l.id !== logId);
  touchItem(item);
  await saveData();
  // Re-render the log history in place
  renderLogHistory(item);
  scheduleRender('grid', 'dashboard');
  setTimeout(syncAll, 400);
}

function renderLogHistory(item) {
  const histWrap    = document.getElementById('log-history');
  const histEntries = document.getElementById('log-history-entries');
  if (!histWrap || !histEntries) return;
  if (!item.logs || !item.logs.length) { histWrap.style.display = 'none'; return; }

  histWrap.style.display = 'block';
  const pricedLogs = item.logs.map(l => parsePriceValue(l.price)).filter(p => p !== null);
  const minPrice   = pricedLogs.length ? Math.min(...pricedLogs) : null;
  const maxPrice   = pricedLogs.length ? Math.max(...pricedLogs) : null;

  histEntries.innerHTML = [...item.logs].reverse().slice(0,8).map((l, i, arr) => {
    const thisPrice = parsePriceValue(l.price);
    const prevLog   = arr[i + 1];
    const prevPrice = prevLog ? parsePriceValue(prevLog.price) : null;
    let priceTrendEl = '';
    if (thisPrice !== null && prevPrice !== null) {
      const diff = thisPrice - prevPrice;
      if (Math.abs(diff) >= 0.01)
        priceTrendEl = diff > 0
          ? `<span style="color:var(--danger);font-size:10px">↑</span>`
          : `<span style="color:var(--ok);font-size:10px">↓</span>`;
    }
    const isCheapest = thisPrice !== null && thisPrice === minPrice && pricedLogs.length > 1;
    const isMostExp  = thisPrice !== null && thisPrice === maxPrice && pricedLogs.length > 1 && minPrice !== maxPrice;
    return `<div class="log-entry" style="display:flex;align-items:center;gap:8px">
      <div style="flex:1;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
        <span style="color:var(--muted);font-size:12px">${esc(l.store)||'—'}</span>
        <span style="color:var(--muted);font-family:var(--mono);font-size:11px">${fmtDate(l.date)}</span>
        <span style="font-family:var(--mono);font-size:12px;display:flex;align-items:center;gap:4px">
          ×${l.qty}
          ${l.price ? `<span style="color:${isCheapest?'var(--ok)':isMostExp?'var(--danger)':'var(--text)'};font-weight:700">${esc(l.price)}</span>${priceTrendEl}${isCheapest?'<svg class="icon" aria-hidden="true"><use href="#i-tag"></use></svg>':''}` : ''}
        </span>
      </div>
      <button onclick="deleteLogEntry('${item.id}','${l.id}')" title="Delete this entry" style="background:none;border:none;cursor:pointer;font-size:14px;color:var(--muted);padding:2px 4px;border-radius:4px;flex-shrink:0" onmouseover="this.style.color='var(--danger)'" onmouseout="this.style.color='var(--muted)'"><svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg></button>
    </div>`;
  }).join('');

  if (pricedLogs.length >= 2) {
    const avg = (pricedLogs.reduce((a,b)=>a+b,0) / pricedLogs.length).toFixed(2);
    histEntries.innerHTML += `<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border);font-size:11px;color:var(--muted);font-family:var(--mono);display:flex;gap:16px">
      <span>avg £${avg}</span>
      <span style="color:var(--ok)">low £${minPrice.toFixed(2)}</span>
      <span style="color:var(--danger)">high £${maxPrice.toFixed(2)}</span>
    </div>`;
  }
}

// ═══════════════════════════════════════════
//  QUICK LOG FROM SHOPPING LIST
// ═══════════════════════════════════════════
function quickLogFromShopping(itemId) {
  // Open the log modal pre-filled, then switch back to shopping after save
  openLogModal(itemId);
  // Mark that we came from shopping so we can return after save
  sessionStorage.setItem('log_return_view', 'shopping');
}


// ═══════════════════════════════════════════
//  PWA — SERVICE WORKER + INSTALL PROMPT
// ═══════════════════════════════════════════
let deferredInstallPrompt = null;

// ── iOS detection ─────────────────────────
const isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent) ||
  (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
const isInStandaloneMode = window.matchMedia('(display-mode: standalone)').matches
  || window.navigator.standalone === true;
const isAndroid = /android/i.test(navigator.userAgent);

if ('serviceWorker' in navigator) {
  const isDeployed = location.hostname.includes('github.io') || location.hostname.includes('artbot5000');
  if (isDeployed) {
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('./sw.js').then(reg => {
        reg.update();
        if (reg.waiting) showUpdateBanner(reg.waiting);
        reg.addEventListener('updatefound', () => {
          const newWorker = reg.installing;
          newWorker.addEventListener('statechange', () => {
            if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
              showUpdateBanner(newWorker);
            }
          });
        });
        // Periodic update check (hourly) so long-running tabs eventually
        // pick up new deploys without a manual refresh. The browser
        // caches sw.js HTTP-fetches aggressively by default, but
        // reg.update() bypasses cache for the SW script specifically.
        // Hourly is a reasonable trade between freshness and traffic.
        setInterval(() => {
          reg.update().catch(_ => {});
        }, 60 * 60 * 1000);
      }).catch(e => console.warn('SW failed:', e));

      // Only reload automatically if the user explicitly triggered the update
      let _userTriggeredUpdate = false;
      window._markUserTriggeredUpdate = () => { _userTriggeredUpdate = true; };
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (_userTriggeredUpdate) { location.reload(); }
        // If not user-triggered (e.g. SW auto-activating), just show the banner
        // so the user can choose when to refresh — don't force-reload
      });
    });

    // iOS install banner is shown via maybeShowInstallBanner() called from
    // _enterStockroom(), after server settings have been pulled and verified.
    // This ensures settings._installDismissed is authoritative (not stale from
    // IDB which may have been cleared along with cookies).
  }
}

function showUpdateBanner(worker) {
  const banner = document.getElementById('update-banner');
  if (banner) { banner.style.display = 'flex'; banner._worker = worker; }
}

function applyUpdate() {
  const banner = document.getElementById('update-banner');
  if (banner) banner.style.display = 'none';
  if (window._markUserTriggeredUpdate) window._markUserTriggeredUpdate();
  // Try to wake the waiting worker if present (no-op if already
  // active, but harmless). With sw.js calling skipWaiting() on install,
  // the new SW is usually already active by the time the user clicks —
  // so the reload below is what actually matters for getting the fresh
  // app shell.
  if (banner?._worker) {
    try { banner._worker.postMessage({ type: 'SKIP_WAITING' }); } catch(_) {}
  }
  // Always reload. The new SW (active from skipWaiting + clients.claim)
  // serves the fresh /index.html, /app.js, /styles.css from its cache,
  // so the reload swaps the user from old bundle → new bundle cleanly.
  // No reinstall needed, IndexedDB credentials are preserved.
  location.reload();
}

// Android install prompt — just capture the event; banner is shown via
// maybeShowInstallBanner() called from _enterStockroom() after server settings
// are confirmed, so settings._installDismissed is always authoritative.
window.addEventListener('beforeinstallprompt', e => {
  e.preventDefault();
  deferredInstallPrompt = e;
  const row = document.getElementById('install-prompt-row');
  if (row) row.style.display = 'flex';
});

window.addEventListener('appinstalled', () => {
  deferredInstallPrompt = null;
  const banner = document.getElementById('install-banner');
  if (banner) banner.classList.remove('show');
  const iosBanner = document.getElementById('ios-install-banner');
  if (iosBanner) iosBanner.style.display = 'none';
  toast('STOCKROOM installed ✓');
});

async function installPWA() {
  if (isIOS) {
    // Can't prompt on iOS — show the iOS banner instead
    const banner = document.getElementById('ios-install-banner');
    if (banner) { banner.style.display = 'block'; banner.scrollIntoView({ behavior: 'smooth' }); }
    return;
  }
  if (!deferredInstallPrompt) {
    toast('Use "Add to Home Screen" from your browser menu');
    return;
  }
  deferredInstallPrompt.prompt();
  const { outcome } = await deferredInstallPrompt.userChoice;
  deferredInstallPrompt = null;
  const banner = document.getElementById('install-banner');
  if (banner) banner.classList.remove('show');
}

// ── Amazon Order History Import banner ───────────────────────────────────────
// Behaviour: shows ONCE per account, ever. The first time the user is
// signed in and the flag is unset, the banner appears; the flag is then
// persisted to settings (which syncs to the server) so the next sign-in
// on any device sees the flag set and skips the banner entirely.
//
// Why persist on show (not on dismiss): users often just look at the
// banner and scroll past without clicking X. They've still seen the
// nudge — re-showing it on every device login would be noise. The
// dismiss X button is kept for users who want to hide it immediately
// before the auto-persist fires.
//
// Race protection: on a fresh device, _showAmazonBanners runs BEFORE the
// initial kvSyncNow has pulled settings down. To avoid a flash, we also
// re-call this function after kvSyncNow completes (see syncSettled hook).
function _showAmazonBanners() {
  if (settings._amazonBannerDismissed) return;
  // Require a valid signed-in user blob before persisting — otherwise we'd
  // mark the banner seen against a guest/local profile and never show it
  // on the user's real account. _kvEmailHash being set means kvSyncNow can
  // push the flag to the server on next sync.
  if (!_kvEmailHash) {
    // Not signed in yet — don't render the banner at all. It'll be shown
    // after the user signs in and the post-sync hook re-evaluates.
    return;
  }
  const banner = document.getElementById('amazon-banner-mobile');
  if (banner) banner.style.display = 'block';
  // Mark seen so subsequent loads / other devices don't show it again.
  settings._amazonBannerDismissed = true;
  _saveSettings()
    .then(() => activeProfile ? saveCurrentProfile() : null)
    .then(() => { if (kvConnected) kvPush().catch(() => {}); })
    .catch(() => {});
}

// Hide the banner if a sync brought down a dismissed flag that wasn't
// present locally when _showAmazonBanners first ran. Called from kvSyncNow
// after settings are merged. Idempotent — safe to call multiple times.
function _refreshAmazonBannerVisibility() {
  const banner = document.getElementById('amazon-banner-mobile');
  if (!banner) return;
  if (settings._amazonBannerDismissed) {
    banner.style.display = 'none';
  }
}

function dismissAmazonBanner() {
  const banner = document.getElementById('amazon-banner-mobile');
  if (banner) banner.style.display = 'none';
  settings._amazonBannerDismissed = true;
  // Write to both IDB (immediate, this device) and the profile blob (which
  // is what kvPush serialises to the server). _saveSettings alone wouldn't
  // update the profile; without that, a subsequent loadProfile would
  // overwrite the local flag from the stale snapshot in IDB.
  _saveSettings()
    .then(() => activeProfile ? saveCurrentProfile() : null)
    .then(() => kvPush().catch(() => {}));
  setTimeout(() => toast('Amazon order import is available anytime in Account & Security → Data'), 400);
}

function dismissInstallBanner() {
  const banner = document.getElementById('install-banner');
  if (banner) banner.classList.remove('show');
  // Save to localStorage immediately so it survives for the rest of this session
  try { localStorage.setItem('stockroom_install_dismissed', '1'); } catch(e){}
  // Save to settings object + IDB so it persists across page loads and devices
  settings._installDismissed = true;
  _saveSettings().then(() => {
    // Push to server so the flag is in the encrypted user blob on all devices
    if (kvConnected) kvSyncNow(true).catch(() => {});
  });
  setTimeout(() => toast('You can install STOCKROOM anytime from Settings'), 400);
}

function dismissIOSBanner() {
  const banner = document.getElementById('ios-install-banner');
  if (banner) banner.style.display = 'none';
  try { localStorage.setItem('stockroom_ios_banner_dismissed', '1'); } catch(e){}
  settings._installDismissed = true;
  _saveSettings().then(() => {
    if (kvConnected) kvSyncNow(true).catch(() => {});
  });
}

// ═══════════════════════════════════════════
//  PUSH NOTIFICATIONS
// ═══════════════════════════════════════════
let notifEnabled = false;

function loadNotifSettings() {
  try {
    const saved = JSON.parse(localStorage.getItem('stockroom_notif') || '{}');
    notifEnabled = saved.enabled || false;
    const daysEl = document.getElementById('notif-days');
    if (daysEl && saved.days) daysEl.value = saved.days;
  } catch(e){}
  // Set platform-specific description
  const note = document.getElementById('notif-platform-note');
  if (note) {
    if (isIOS && !isInStandaloneMode) {
      note.innerHTML = 'Push notifications on iPhone require the app to be <strong style="color:var(--text)">installed to your home screen</strong> via Safari. Once installed, notifications work like a native app.';
      note.style.color = 'var(--warn)';
    } else if (isIOS && isInStandaloneMode) {
      note.textContent = 'Running as installed app — notifications are fully supported on your iPhone.';
      note.style.color = 'var(--ok)';
    } else {
      note.textContent = 'Get notified when items are running low — no email needed. Works best when installed to your home screen.';
    }
  }
  updateNotifUI();
}

function saveNotifSettings() {
  try {
    const days = document.getElementById('notif-days')?.value || '14';
    localStorage.setItem('stockroom_notif', JSON.stringify({ enabled: notifEnabled, days }));
  } catch(e){}
}

function updateNotifUI() {
  const btn        = document.getElementById('notif-btn');
  const statusText = document.getElementById('notif-status-text');
  const threshRow  = document.getElementById('notif-threshold-row');
  const installRow = document.getElementById('install-prompt-row');
  const installInfo = document.getElementById('install-prompt-info');
  const installBtn  = document.getElementById('install-prompt-btn');
  if (!btn || !statusText) return;

  const permission = 'Notification' in window ? Notification.permission : 'unsupported';

  // iOS not installed — notifications won't work, show install prompt instead
  if (isIOS && !isInStandaloneMode) {
    statusText.textContent = 'Requires home screen install on iPhone';
    statusText.style.color = 'var(--warn)';
    btn.style.display = 'none';
    if (installRow) installRow.style.display = 'flex';
    if (installInfo) installInfo.innerHTML = '<h4>Add to Home Screen first</h4><p>iOS only supports notifications when installed via Safari → Share → Add to Home Screen</p>';
    if (installBtn) { installBtn.textContent = 'How to install'; installBtn.onclick = () => {
      const banner = document.getElementById('ios-install-banner');
      if (banner) { banner.style.display = 'block'; banner.scrollIntoView({ behavior: 'smooth' }); }
    }; }
    if (threshRow) threshRow.style.display = 'none';
    return;
  }

  if (permission === 'unsupported') {
    statusText.textContent = 'Not supported on this browser';
    btn.style.display = 'none';
    return;
  }
  if (permission === 'denied') {
    statusText.textContent = 'Blocked — enable notifications in browser/phone settings';
    statusText.style.color = 'var(--danger)';
    btn.style.display = 'none';
    return;
  }
  if (notifEnabled && permission === 'granted') {
    statusText.textContent = isIOS
      ? 'Active — you\'ll be alerted when items run low'
      : 'Active — you\'ll be alerted when items run low';
    statusText.style.color = 'var(--ok)';
    btn.textContent = 'Disable';
    btn.className   = 'btn btn-danger btn-sm';
    btn.style.display = 'inline-flex';
    if (threshRow)  threshRow.style.display  = 'flex';
    if (installRow) installRow.style.display = (!isIOS && deferredInstallPrompt) ? 'flex' : 'none';
  } else {
    statusText.textContent = 'Not enabled';
    statusText.style.color = 'var(--muted)';
    btn.textContent   = 'Enable';
    btn.className     = 'btn btn-ghost btn-sm';
    btn.style.display = 'inline-flex';
    if (threshRow)  threshRow.style.display  = 'none';
    if (installRow) installRow.style.display = (!isIOS && deferredInstallPrompt) ? 'flex' : 'none';
  }
}

async function toggleNotifications() {
  if (notifEnabled) {
    notifEnabled = false;
    saveNotifSettings();
    updateNotifUI();
    toast('Notifications disabled');
    return;
  }
  if (!('Notification' in window)) { toast('Not supported on this browser'); return; }
  const permission = await Notification.requestPermission();
  if (permission === 'granted') {
    notifEnabled = true;
    saveNotifSettings();
    updateNotifUI();
    toast('Notifications enabled ✓');
    setTimeout(() => sendLocalNotification(
      '📦 STOCKROOM notifications active',
      'You\'ll be notified when items are running low.',
      'stockroom-test'
    ), 600);
  } else {
    toast('Notifications blocked — enable in browser settings');
    updateNotifUI();
  }
}

function sendLocalNotification(title, body, tag) {
  if (!notifEnabled || Notification.permission !== 'granted') return;
  if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
    navigator.serviceWorker.ready.then(reg => {
      reg.showNotification(title, {
        body, tag: tag || 'stockroom', renotify: true,
        icon: './icon-192.png', badge: './icon-192.png',
        data: { url: window.location.href },
      });
    });
  } else {
    new Notification(title, { body, icon: './icon-192.png', tag: tag || 'stockroom' });
  }
}

async function checkLowStockNotifications() {
  // Compute due items regardless of push notifEnabled — the in-app inbox
  // should still populate so users can see low-stock alerts in the bell.
  const days = parseInt(document.getElementById('notif-days')?.value || '14');
  const due  = items
    .map(item => { const s = calcStock(item); return s && s.daysLeft <= days ? { item, daysLeft: s.daysLeft } : null; })
    .filter(Boolean)
    .sort((a, b) => a.daysLeft - b.daysLeft);
  if (!due.length) return;

  // Populate in-app inbox first (independent of push). Dedupe is handled
  // inside addNotification by sourceRef within a 24h window — so the same
  // item won't generate 30 inbox entries across repeated checks.
  for (const d of due) {
    const isCritical = d.daysLeft <= 7;
    const title = isCritical
      ? `${d.item.name} — critically low`
      : `${d.item.name} — running low`;
    const body = d.daysLeft <= 0
      ? 'Out of stock'
      : `~${d.daysLeft} day${d.daysLeft !== 1 ? 's' : ''} left`;
    try {
      await addNotification({
        type: 'low-stock',
        title,
        body,
        sourceRef: `lowstock:${d.item.id}`,
      });
    } catch(e) { /* don't let inbox errors block push */ }
    // Also schedule an immediate Web Push to all subscribed devices.
    // sourceRef matches the in-app one so OS-level dedupe (per-type tag
    // in the SW) coalesces multiple low-stock pushes into a single
    // OS notification — exactly the per-type-tag behaviour we want.
    // Stamp the date in the sourceRef so a re-trigger tomorrow becomes
    // a fresh push (otherwise schedulePushPayload would dedupe it).
    if (typeof schedulePushNotification === 'function') {
      const todayStr = new Date().toISOString().slice(0, 10);
      schedulePushNotification({
        dueAt:     Date.now(),
        sourceRef: `lowstock:${d.item.id}:${todayStr}`,
        title,
        body,
        url:       './',
        fallbackTitle: 'A Stockroom item is low',
      }).catch(_ => {});
    }
  }

  // Below: existing push-notification path (gated on notifEnabled)
  if (!notifEnabled || Notification.permission !== 'granted') return;

  const today = new Date().toISOString().slice(0, 10);
  if (localStorage.getItem('stockroom_last_notif') === today) return;

  // Include household name so user knows which household triggered the alert
  const profiles = await getProfiles();
  const householdName = profiles[activeProfile]?.name || 'Home';
  const hLabel = Object.keys(profiles).length > 1 ? ` · ${householdName}` : '';

  const critical = due.filter(d => d.daysLeft <= 7);
  const title = (critical.length
    ? `🔴 ${critical.length} item${critical.length !== 1 ? 's' : ''} critically low!`
    : `📦 ${due.length} item${due.length !== 1 ? 's' : ''} running low`) + hLabel;
  const body = due.slice(0, 3).map(d => `• ${d.item.name} (${d.daysLeft}d left)`).join('\n')
    + (due.length > 3 ? `\n+ ${due.length - 3} more` : '');

  sendLocalNotification(title, body, 'stockroom-lowstock');
  try { localStorage.setItem('stockroom_last_notif', today); } catch(e){}
}

// ═══════════════════════════════════════════
//  SORT
// ═══════════════════════════════════════════
let activeSort = 'status';

function setSort(val) {
  activeSort = val;
  renderGrid();
}

// ═══════════════════════════════════════════
//  SWIPE TO LOG
// ═══════════════════════════════════════════
const swipeState = {};
const SWIPE_THRESHOLD  = 110; // px to trigger (was 72)
const SWIPE_LOCK_ANGLE = 30;  // degrees — swipe must be within this of horizontal

// Returns true when any per-card interaction (hover-actions, long-press,
// horizontal-swipe-to-log) should be SUPPRESSED because the user is in
// bulk-select mode. In select mode the only valid interaction with a
// card is tap-to-toggle-selection — anything else is noise that confuses
// the gesture. Hover delays, long-press timers, and swipe state are all
// gated through this so the user's bulk-select intent doesn't get
// hijacked by a stray drag or an over-long tap.
function _cardInteractionFrozen() {
  return isBulkSelectMode('stock');
}

function swipeStart(e, id) {
  if (_cardInteractionFrozen()) return;
  const t = e.touches[0];
  swipeState[id] = { startX: t.clientX, startY: t.clientY, triggered: false, locked: null };
}

function swipeMove(e, id) {
  if (_cardInteractionFrozen()) return;
  const s = swipeState[id];
  if (!s) return;
  const dx = e.touches[0].clientX - s.startX;
  const dy = e.touches[0].clientY - s.startY;
  if (dx < 0) return; // only right swipe

  // Direction lock: decide horizontal vs vertical on first meaningful movement
  if (s.locked === null && (Math.abs(dx) > 6 || Math.abs(dy) > 6)) {
    const angle = Math.abs(Math.atan2(Math.abs(dy), dx) * 180 / Math.PI);
    s.locked = angle < SWIPE_LOCK_ANGLE ? 'h' : 'v';
  }
  if (s.locked !== 'h') return; // vertical scroll — ignore

  const hint = document.getElementById('swipe-hint-' + id);
  if (hint) hint.style.opacity = Math.min(1, dx / SWIPE_THRESHOLD);
  if (dx > SWIPE_THRESHOLD && !s.triggered) {
    s.triggered = true;
    if (hint) hint.style.opacity = 1;
    navigator.vibrate && navigator.vibrate(30);
  }
}

async function swipeEnd(e, id) {
  if (_cardInteractionFrozen()) return;
  const s = swipeState[id];
  if (!s) return;
  const hint = document.getElementById('swipe-hint-' + id);
  if (hint) hint.style.opacity = 0;
  // Use changedTouches for final position — only open if user ended the swipe far enough right
  const endX = e.changedTouches[0].clientX;
  const finalDx = endX - s.startX;
  if (s.triggered && finalDx >= SWIPE_THRESHOLD) openLogModal(id);
  delete swipeState[id];
}

// ═══════════════════════════════════════════
//  ARCHIVE / UNARCHIVE ITEM
// ═══════════════════════════════════════════

let lastAutoSync = 0;
const AUTO_SYNC_COOLDOWN = 30000; // min 30s between auto-syncs

// Sync when user switches back to the tab/app
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') {
    // Re-lock all unlocked secure notes immediately
    _relockAllNotes();
  }
  if (document.visibilityState === 'visible') {
    const now = Date.now();
    if (now - lastAutoSync > AUTO_SYNC_COOLDOWN) {
      lastAutoSync = now;
      checkCloudAhead();
    }
    // Check if any reminder was marked replaced via email while app was in background
    setTimeout(pollReminderReplacements, 800);
  }
});

// Focus listener pairs with visibilitychange — covers the case where the tab
// stays visible but the window loses + regains focus (e.g. alt-tab between
// browser windows, or returning from another app on the same screen). Same
// AUTO_SYNC_COOLDOWN gate so rapid focus events don't sync-spam.
window.addEventListener('focus', () => {
  if (document.visibilityState !== 'visible') return;
  const now = Date.now();
  if (now - lastAutoSync > AUTO_SYNC_COOLDOWN) {
    lastAutoSync = now;
    checkCloudAhead();
  }
});

// ── Service Worker message handler ───────────────────────
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.addEventListener('message', event => {
    if (event.data?.type === 'REMINDER_REPLACED') {
      const { reminderId, date } = event.data;
      _applyReplacedLocally(reminderId, date);
    }
    if (event.data?.type === 'BG_SYNC') {
      console.log('BG_SYNC received from SW');
      syncAll().catch(e => console.warn('BG_SYNC syncAll failed:', e));
    }
    if (event.data?.type === 'SW_UPDATED') {
      // New service worker activated — reload to get fresh app.js
      console.log('[SW] New SW activated:', event.data.version, '— reloading for fresh files');
      window.location.reload();
    }
  });
}

// ── BroadcastChannel — cross-tab sync ────────────────────
// When any tab saves data, all other open tabs update instantly.
// Zero server cost, works natively in Chrome/Firefox/Safari.
const _bc = ('BroadcastChannel' in window) ? new BroadcastChannel('stockroom') : null;

// Message types:
//   { type: 'DATA_CHANGED' }         — items changed, reload from IDB and re-render
//   { type: 'REMINDER_REPLACED', reminderId, date } — reminder marked done in another tab
//   { type: 'GROCERY_CHANGED' }      — grocery list changed
//   { type: 'SETTINGS_CHANGED' }     — settings updated
//   { type: 'USER_CHANGED', emailHash } — sign-in / sign-out / user switch — other tabs reload

if (_bc) {
  _bc.onmessage = async event => {
    const { type } = event.data;

    if (type === 'USER_CHANGED') {
      // Another tab signed in, signed out, or switched accounts. This tab
      // still holds the previous user's credentials in memory and is
      // pointing _activeDbName at the previous user's DB — any further
      // writes would go to the wrong place. Reload to pick up the new
      // state cleanly. We do this BEFORE the other handlers so we don't
      // race against e.g. a DATA_CHANGED firing for the new user's data.
      console.log('[bc] USER_CHANGED — reloading to resync auth state');
      location.reload();
      return;
    }

    if (type === 'DATA_CHANGED') {
      // Another tab saved items — reload from IndexedDB and re-render
      const fresh = await dbGet('items', 'items');
      if (fresh && Array.isArray(fresh)) {
        items = fresh;
        scheduleRender('grid', 'dashboard', 'shopping', 'sns', 'filters');
      }
    }

    if (type === 'REMINDER_REPLACED') {
      const { reminderId, date } = event.data;
      await _applyReplacedLocally(reminderId, date);
    }

    if (type === 'GROCERY_CHANGED') {
      const fresh = await dbGet('groceries', 'items');
      if (fresh) {
        groceryItems = fresh;
        renderGrocery();
      }
    }

    if (type === 'SETTINGS_CHANGED') {
      const fresh = await dbGet('settings', 'settings');
      if (fresh) {
        settings = { ...settings, ...fresh };
        scheduleRender('settings-ui');
        // Mobile tab choice could have been changed on another device/
        // tab — re-apply so this tab's row + burger menu match the
        // persisted setting without a reload.
        try { if (typeof _applyMobileTabLayout === 'function') _applyMobileTabLayout(); } catch (_) {}
      }
    }
  };
}

function bcPost(message) {
  try { _bc?.postMessage(message); } catch(e) {}
}

// ── Register background sync after every save ─────────────
// The browser will fire the 'sync' event in the SW when connectivity
// returns, even if this tab is closed.
async function registerBackgroundSync() {
  if (!('serviceWorker' in navigator) || !('SyncManager' in window)) return;
  try {
    const reg = await navigator.serviceWorker.ready;
    await reg.sync.register('stockroom-sync');
  } catch(e) {
    // Background Sync not supported or permission denied — silent fallback
  }
}

// ── Check for pending sync flag set by SW while app was closed ─
async function checkPendingSWSync() {
  if (!('caches' in window)) return;
  try {
    const cache   = await caches.open('stockroom-flags');
    const pending = await cache.match('pending-sync');
    if (pending) {
      await cache.delete('pending-sync');
      console.log('Pending SW sync flag found — syncing now');
      setTimeout(syncAll, 800);
    }
  } catch(e) {}
}

// Adaptive polling — 30s when share state is active (either own a share or
// are a guest in one), 5min otherwise. The cheaper modified-time check makes
// 30s a fine cadence for users who aren't actively sharing; for users with
// shares, 30s gives a sensible worst-case latency for cross-account changes
// without overwhelming the server (one /share/tips call per tick, ~50 bytes
// down per share). The visibility/focus triggers below give near-instant
// updates for the common case of switching tabs/windows.
//
// TDZ note: _shareState and _shareTargets are declared with `let` MUCH later
// in this file (~line 25600). At module-load time they're in the temporal
// dead zone, so any direct reference here throws ReferenceError. The typeof
// guard below is the canonical way to probe for TDZ-bound bindings without
// triggering the access error — typeof on an uninitialised let returns the
// string 'undefined' rather than throwing.
function _sharePollIntervalMs() {
  let hasShareState = false;
  try {
    hasShareState = (typeof _shareState !== 'undefined' && !!_shareState)
                 || (typeof _shareTargets !== 'undefined' && _shareTargets?.length > 0);
  } catch(_) { /* state vars not yet initialised — treat as no share */ }
  return hasShareState ? 30 * 1000 : 5 * 60 * 1000;
}
let _sharePollTimer = null;
function _scheduleNextSharePoll() {
  clearTimeout(_sharePollTimer);
  _sharePollTimer = setTimeout(() => {
    if (document.visibilityState === 'visible') {
      lastAutoSync = Date.now();
      checkCloudAhead();
    }
    _scheduleNextSharePoll(); // re-arm with current interval (may have changed)
  }, _sharePollIntervalMs());
}
// Defer the first schedule so module evaluation completes — this avoids
// any TDZ access for `let` bindings declared later in the file, and lines
// up with the existing init() pattern of running heavy work after DOM is
// ready. If DOMContentLoaded already fired, the microtask still works.
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _scheduleNextSharePoll, { once: true });
} else {
  setTimeout(_scheduleNextSharePoll, 0);
}

// Check if cloud is ahead of local — if so, sync silently
async function checkCloudAhead() {
  if (!kvConnected && !_shareState) return;
  try {
    let remoteModified = null;

    if (_shareState) {
      remoteModified = await proxyGetModifiedTime();
    } else if (kvConnected) {
      const res = await postKV(`${WORKER_URL}/data/modified`, {emailHash: _kvEmailHash, verifier: _kvVerifier, sessionToken: _kvSessionToken, household: activeProfile});
      if (res.ok) remoteModified = (await res.json()).modifiedTime;
    }

    // Owner-side share-blob check: if we own any shares, ALSO check whether
    // a guest has written since our last absorb. Triggers a full sync even
    // when the owner's own blob hasn't moved. Without this, guest writes
    // would only be picked up on the 5-minute polling cycle.
    let shareNeedsAbsorb = false;
    if (kvConnected && !_shareState && _shareTargets?.length) {
      try {
        const codes = _shareTargets.map(t => t.code);
        const authFields = _kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier };
        const tipsRes = await postKV(`${WORKER_URL}/share/tips`, { emailHash: _kvEmailHash, ...authFields, codes });
        if (tipsRes.ok) {
          const body = await _readJsonSafe(tipsRes) || {};
          const tips = body.tips || {};
          for (const target of _shareTargets) {
            if (!target.households) continue;
            for (const hKey of Object.keys(target.households)) {
              const tip = tips[`${target.code}:${hKey}`];
              if (!tip || !tip.modified) continue;
              if (tip.writer === 'owner') continue;
              const last = _getAbsorbStamp(target.code, hKey);
              if (!last || last !== tip.modified) { shareNeedsAbsorb = true; break; }
            }
            if (shareNeedsAbsorb) break;
          }
        }
      } catch(e) { /* network blip — fall through */ }
    }

    if (shareNeedsAbsorb) {
      await syncAll();
      hideSyncBanner();
      return;
    }

    if (!remoteModified) return;

    const remoteTime = new Date(remoteModified).getTime();
    const localTime  = settings.lastSynced ? new Date(settings.lastSynced).getTime() : 0;

    if (remoteTime > localTime + 5000) {
      // Cloud is ahead — sync silently
      await syncAll();
      hideSyncBanner();
    }
  } catch(e) {
    console.warn('Auto-sync check failed:', e.message);
  }
}

function showSyncBanner() {
  const b = document.getElementById('sync-banner');
  if (b) b.style.display = 'flex';
}

function hideSyncBanner() {
  const b = document.getElementById('sync-banner');
  if (b) b.style.display = 'none';
}

async function syncNowAndDismissBanner() {
  hideSyncBanner();
  await syncAll();
}

// ═══════════════════════════════════════════
//  FILTER PANEL TOGGLE
// ═══════════════════════════════════════════
let filtersOpen = false;

function toggleFilters() {
  filtersOpen = !filtersOpen;
  const panel = document.getElementById('filter-panel');
  const icon  = document.getElementById('filter-toggle-icon');
  if (panel) panel.style.display = filtersOpen ? 'flex' : 'none';
  if (icon)  icon.textContent    = filtersOpen ? '▾' : '▸';
  // State is in-memory only — always resets to closed on page load
}

function loadFilterPanelState() {
  // Always default to closed — never restore across page loads
  filtersOpen = false;
  try { sessionStorage.removeItem('stockroom_filters_open'); } catch(e) {}
  const panel = document.getElementById('filter-panel');
  const icon  = document.getElementById('filter-toggle-icon');
  if (panel) panel.style.display = 'none';
  if (icon)  icon.textContent    = '▸';
}

function updateFilterBadge() {
  const badge = document.getElementById('filter-active-badge');
  if (!badge) return;
  const active = [
    activeFilter !== 'all',
    activeCadence !== 'all',
    activeStore !== 'all',
    activeRating !== 0,
  ].filter(Boolean).length;
  if (active > 0) {
    badge.textContent = active;
    badge.style.display = 'inline';
  } else {
    badge.style.display = 'none';
  }
}

function resetAllFilters() {
  activeFilter  = 'all';
  activeCadence = 'all';
  activeStore   = 'all';
  activeRating  = 0;
  // Reset chip visual states
  document.querySelectorAll('#filter-bar .filter-chip').forEach((c,i) => c.classList.toggle('active', i === 0));
  document.querySelectorAll('#store-filter-bar .filter-chip').forEach((c,i) => c.classList.toggle('active', i === 0));
  document.querySelectorAll('#rating-filter-bar .filter-chip').forEach((c,i) => c.classList.toggle('active', i === 0));
  updateFilterBadge();
  renderGrid();
}


function reconcileFilters() {
  const threshold = settings.threshold;
  const nonQuick  = items.filter(i => !i.quickAdded);

  // Helper: count items passing all current filters except the one being tested
  const anyMatch = (testFn) => nonQuick.some(item => {
    const s      = calcStock(item);
    const status = getStatus(s?.pct ?? null, threshold);
    return testFn(item, status);
  });

  let changed = false;

  // Status filter stale?
  if (activeFilter !== 'all') {
    const stillHas = anyMatch((item, status) => status === activeFilter);
    if (!stillHas) {
      activeFilter = 'all';
      // Reset status chip UI
      document.querySelectorAll('#filter-bar .filter-chip').forEach(c => {
        const txt = c.textContent.trim();
        if (txt === 'All' || txt.includes('All')) c.classList.add('active');
        else c.classList.remove('active');
      });
      changed = true;
    }
  }

  // Cadence filter stale?
  if (activeCadence !== 'all') {
    const stillHas = anyMatch((item) => item.cadence === activeCadence);
    if (!stillHas) {
      activeCadence = 'all';
      document.querySelectorAll('#filter-bar .filter-chip').forEach(c => {
        if (c.textContent.includes('Monthly') || c.textContent.includes('Bulk')) c.classList.remove('active');
      });
      changed = true;
    }
  }

  // Store filter stale?
  if (activeStore !== 'all') {
    const allStores = new Set();
    nonQuick.forEach(item => {
      if (item.store?.trim()) allStores.add(item.store.trim());
      (item.logs||[]).forEach(l => { if (l.store?.trim()) allStores.add(l.store.trim()); });
    });
    if (!allStores.has(activeStore)) {
      activeStore = 'all';
      changed = true;
    }
  }

  // Rating filter stale?
  if (activeRating !== 0) {
    const stillHas = activeRating === -1
      ? anyMatch(item => !item.rating)
      : anyMatch(item => item.rating === activeRating);
    if (!stillHas) {
      activeRating = 0;
      document.querySelectorAll('#rating-filter-bar .filter-chip').forEach(c => c.classList.remove('active'));
      const allRatingBtn = document.querySelector('#rating-filter-bar .filter-chip');
      if (allRatingBtn) allRatingBtn.classList.add('active');
      changed = true;
    }
  }

  // Tag filter stale?
  if (activeTagFilter !== null) {
    const stillHas = anyMatch(item => (item.tags||[]).includes(activeTagFilter));
    if (!stillHas) {
      activeTagFilter = null;
      changed = true;
    }
  }

  if (changed) updateFilterBadge();
}

// ═══════════════════════════════════════════════════════════
//  REACTIVE RENDER SCHEDULER
//  Replaces renderAll() with targeted dirty-flag rendering.
//  Multiple saves in the same frame coalesce into one render pass.
// ═══════════════════════════════════════════════════════════

const RENDER_REGIONS = ['grid','dashboard','filters','shopping','sns','settings-ui'];
const _dirty  = new Set();
let   _raf    = null;
let   _rendering = false;

function scheduleRender(...regions) {
  if (regions.length === 0) regions = RENDER_REGIONS; // full render if no args
  regions.forEach(r => _dirty.add(r));
  if (_raf) return; // already scheduled — extra dirty flags will be picked up
  _raf = requestAnimationFrame(_flushRender);
}

function _flushRender() {
  _raf = null;
  if (_rendering) {
    // Re-schedule — a previous render is still running (async)
    _raf = requestAnimationFrame(_flushRender);
    return;
  }
  _rendering = true;
  const regions = new Set(_dirty);
  _dirty.clear();

  try {
    // Always update item count (excluding soft-deleted)
    const countEl = document.getElementById('item-count');
    if (countEl) {
      const live = items.filter(i => !i._deletedAt).length;
      countEl.textContent = live + ' item' + (live!==1?'s':'');
    }

    if (regions.has('filters')) {
      buildStoreFilterBar();
      buildTagFilterBar();
      buildShoppingTagFilterBarInline();
      reconcileFilters();
    }
    if (regions.has('dashboard')) {
      renderHealthDashboard();
      renderPendingDeliveries();
      renderIncompleteSection();
    }
    if (regions.has('sns')) {
      updateSnSBanner();
    }
    if (regions.has('grid')) {
      renderGrid();
    }
    if (regions.has('shopping') && document.getElementById('shopping-panel')?.style.display !== 'none') {
      renderShoppingList();
    }
    if (regions.has('settings-ui')) {
      const t  = document.getElementById('setting-threshold');
      const c  = document.getElementById('setting-country');
      const e  = document.getElementById('setting-email');
      const iv = document.getElementById('setting-email-interval');
      const sd = document.getElementById('setting-email-start');
      const st = document.getElementById('setting-email-start-time');
      if (t)  t.value  = settings.threshold;
      // Re-populate country options if empty (e.g. first render after sign-in).
      // Skip the .options check for hidden inputs (Settings redesign moved the
      // real selector to setting-country-sec in Account & Security).
      if (c && c.tagName === 'SELECT' && c.options.length === 0) buildSettingsCountrySelect();
      if (c)  c.value  = settings.country || 'GB';
      if (e)  e.value  = settings.email || '';
      if (iv) iv.value = settings.emailInterval ?? 30;
      if (sd) sd.value = settings.emailStartDate || '';
      if (st) st.value = settings.emailStartTime || '09:00';
      updateLastSentUI();
    }
  } finally {
    _rendering = false;
    // If new dirty flags arrived during render, flush again
    if (_dirty.size > 0) _raf = requestAnimationFrame(_flushRender);
  }
}

// Legacy alias — keeps existing callers working, schedules a full render
function renderAll() { scheduleRender(...RENDER_REGIONS); }

function renderGrid() {
  const threshold   = settings.threshold;
  const grid        = document.getElementById('items-grid');
  // Stockroom's inline #stock-search input was removed when the global
  // search took over — there's nothing to read here anymore. Filters /
  // sort / cadence / rating / store / tag controls below all still apply.

  // Defensive guard — should never happen but prevents blank screens
  if (!Array.isArray(items)) {
    console.error('stockroom: items is not an array in renderGrid', items);
    items = [];
  }

  let filtered = items.filter(item => {
    // Soft-deleted items live in the recycle bin section, not the main grid
    if (item._deletedAt) return false;
    // Quick-added items live in their own section
    if (item.quickAdded) return false;
    // Archived items only shown when archive filter is active
    if (item._archived && activeFilter !== 'archived') return false;
    if (!item._archived && activeFilter === 'archived') return false;
    if (activeFilter === 'archived') {
      return true;
    }

    const s = calcStock(item);
    const status = getStatus(s?.pct ?? null, threshold);

    // Status filter
    if (activeFilter !== 'all' && status !== activeFilter) return false;

    // Cadence filter
    if (activeCadence !== 'all' && item.cadence !== activeCadence) return false;

    // Store filter — match item-level store, or any log entry
    if (activeStore !== 'all') {
      const itemStore = item.store && item.store.trim() === activeStore;
      const logStore = (item.logs||[]).some(l => l.store && l.store.trim() === activeStore);
      if (!itemStore && !logStore) return false;
    }

    // Rating filter
    if (activeRating === -1 && item.rating) return false;        // unrated only
    if (activeRating === -1 && !item.rating) return true;
    if (activeRating > 0 && item.rating !== activeRating) return false;

    // Tag filter
    if (activeTagFilter !== null) {
      if (!(item.tags || []).includes(activeTagFilter)) return false;
    }

    return true;
  });

  if (items.length === 0) {
    grid.innerHTML = `<div class="empty-state">
      <div class="empty-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M11 21.73a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73z"/><path d="M12 22V12"/><polyline points="3.29 7 12 12 20.71 7"/><path d="m7.5 4.27 9 5.15"/></svg></div>
      <h3>Your stockroom is empty</h3>
      <p>Add the household consumables you buy regularly — coffee, toilet paper, cleaning supplies, anything you don't want to run out of.</p>
      <button class="btn btn-primary" onclick="openAddModal()">+ Add Your First Item</button>
    </div>`;
    return;
  }

  if (filtered.length === 0) {
    grid.innerHTML = `<div class="empty-state">
      <div class="empty-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="m21 21-4.34-4.34"/><circle cx="11" cy="11" r="8"/></svg></div>
      <h3>No items match this filter</h3>
      <p>Try a different filter above.</p>
    </div>`;
    return;
  }

  // Sort
  filtered.sort((a, b) => {
    switch (activeSort) {
      case 'name':
        return (a.name||'').localeCompare(b.name||'');
      case 'days': {
        const da = calcStock(a)?.daysLeft ?? 9999;
        const db = calcStock(b)?.daysLeft ?? 9999;
        return da - db;
      }
      case 'lastbought': {
        const la = a.logs?.at(-1)?.date || '0000';
        const lb = b.logs?.at(-1)?.date || '0000';
        return lb.localeCompare(la); // most recent first
      }
      case 'rating':
        return (b.rating||0) - (a.rating||0);
      case 'added':
        return 0; // preserve insertion order
      case 'status':
      default: {
        const pa = calcStock(a)?.pct ?? 101;
        const pb = calcStock(b)?.pct ?? 101;
        return pa - pb;
      }
    }
  });

  // ── Free-tier item cap ──
  // When the user is on the free plan, only show the first N items
  // (after their existing sort) and surface a banner showing how many
  // are hidden. Items remain in KV — they reappear on upgrade.
  let freeTierBadge = '';
  try {
    if (window.stockroomBilling && stockroomBilling.isFree()) {
      const status = stockroomBilling.getStatus();
      const cap    = status?.limits?.itemCount ?? 5;
      // Total non-deleted, non-archived, non-quickAdded items in this household —
      // matches the filter logic for headline visibility.
      const totalReal = items.filter(i => !i._deletedAt && !i.quickAdded && !i._archived).length;
      if (filtered.length > cap) {
        const hidden = filtered.length - cap;
        filtered = filtered.slice(0, cap);
        freeTierBadge = `<div style="margin:10px 14px;padding:10px 14px;border-radius:10px;background:color-mix(in srgb, var(--accent) 8%, var(--bg));border:1px solid color-mix(in srgb, var(--accent) 25%, transparent);display:flex;align-items:center;gap:10px;flex-wrap:wrap">
          <svg class="icon icon-sm" aria-hidden="true" style="color:var(--accent)"><use href="#i-sparkles"></use></svg>
          <span style="font-size:13px;flex:1">Showing ${cap} of ${totalReal} items — ${hidden} hidden on the free plan.</span>
          <button class="btn btn-primary btn-sm" onclick="navTo('billing')">Upgrade</button>
        </div>`;
      } else if (totalReal > 0) {
        // Under cap but on free tier — show the count so users see the limit
        freeTierBadge = `<div style="margin:10px 14px;padding:8px 14px;border-radius:10px;background:color-mix(in srgb, var(--muted) 6%, transparent);display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted)">
          <svg class="icon icon-sm" aria-hidden="true"><use href="#i-info"></use></svg>
          <span>Free plan: ${totalReal} of ${cap} items used</span>
        </div>`;
      }
    }
  } catch (_) {}

  grid.innerHTML = freeTierBadge + filtered.map(item => cardHTML(item, threshold)).join('');

  // Render Recently Deleted section after the main grid
  renderItemsRecycleBin();
}

function renderItemsRecycleBin() {
  let bin = document.getElementById('items-recycle-bin');
  const grid = document.getElementById('items-grid');
  if (!grid) return;
  const trashed = items
    .filter(i => i._deletedAt && !_expiredFromBin(i))
    .sort((a, b) => new Date(b._deletedAt) - new Date(a._deletedAt));

  if (!trashed.length) {
    if (bin) bin.style.display = 'none';
    return;
  }

  if (!bin) {
    bin = document.createElement('div');
    bin.id = 'items-recycle-bin';
    bin.className = 'recycle-bin-section';
    bin.setAttribute('data-bin-key', 'items');
    grid.parentNode.insertBefore(bin, grid.nextSibling);
  }
  bin.style.display = 'block';
  bin.classList.toggle('recycle-bin-collapsed', _isBinCollapsed('items'));

  const titleHTML = `
    <div class="recycle-bin-title">
      <svg class="icon icon-md" aria-hidden="true"><use href="#i-trash-2"></use></svg>
      Recently Deleted
      <span class="recycle-bin-count">${trashed.length}</span>
    </div>`;
  const actionHTML = `<button class="btn btn-ghost btn-sm" onclick="emptyItemsBin()">Empty</button>`;
  const headerHTML = _renderBinHeader('items', titleHTML, actionHTML)
    + `<div class="recycle-bin-subtitle">Items are permanently deleted after 30 days.</div>`;
  const rowsHTML = trashed.map(item => {
    const days = _daysLeftInBin(item);
    const cat  = item.category ? esc(item.category) : '';
    return `
      <div class="recycle-bin-row" data-id="${item.id}">
        <div class="recycle-bin-row-info">
          <div class="recycle-bin-row-name">${esc(item.name)}</div>
          <div class="recycle-bin-row-meta">${cat ? cat + ' · ' : ''}${days} day${days===1?'':'s'} left</div>
        </div>
        <div class="recycle-bin-row-actions">
          <button class="btn btn-ghost btn-sm" onclick="restoreItemFromBin('${item.id}')">Restore</button>
          <button class="btn btn-ghost btn-sm recycle-bin-delete" onclick="purgeItemForever('${item.id}')" title="Delete permanently">✕</button>
        </div>
      </div>`;
  }).join('');

  bin.innerHTML = headerHTML + `<div class="recycle-bin-rows">${rowsHTML}</div>`;
}

function cardHTML(item, threshold) {
  const s = calcStock(item);
  const pct = s?.pct ?? null;
  const daysLeft = s?.daysLeft ?? null;
  const status = getStatus(pct, threshold);
  const color = STATUS_COLOR[status];
  const lastLog = item.logs?.at(-1);

  const fillColor = status === 'critical' ? '#e85050' : status === 'warn' ? '#e8a838' : '#4cbb8a';
  const cadenceBadge = item.cadence === 'bulk'
    ? `<span class="cadence-badge badge-bulk"><svg class="icon" aria-hidden="true"><use href="#i-package"></use></svg> Bulk</span>`
    : `<span class="cadence-badge badge-monthly"><svg class="icon" aria-hidden="true"><use href="#i-calendar-days"></use></svg> Monthly</span>`;
  const statusBadge = `<span class="status-badge" style="background:${color}22;color:${color}">${STATUS_LABEL[status]}</span>`;

  // ── REDESIGNED CARD: tap-to-edit, hero days remaining, slim bar, +1 button ──
  // Best price (lowest) helper — desktop meta row
  const _prices = (item.storePrices || []).filter(sp => sp.store && sp.price);
  const _parsed = _prices.map(sp => parsePriceValue(sp.price)).filter(v => v !== null);
  const bestPrice = _parsed.length ? Math.min(..._parsed) : null;
  const bestPriceStr = bestPrice !== null ? '£' + bestPrice.toFixed(2) : null;
  const lastBoughtAgo = lastLog?.date ? timeAgo(lastLog.date) : null;
  const expiry = getExpiryStatus(item);
  const stars = [1,2,3,4,5].map(n => `<span class="card-star${(item.rating||0)>=n?' on':''}" onclick="event.stopPropagation();rateItem('${item.id}',${n})" data-id="${item.id}" data-val="${n}" onmouseover="previewCardStars('${item.id}',${n})" onmouseout="resetCardStars('${item.id}')">★</span>`).join('');
  // Compact stock indicator — projected unit count if we've got a stock count,
  // else fall back to the per-purchase descriptor.
  const projectedUnits = getProjectedUnitsLeft(item);
  let qtyText, qtyClass;
  if (projectedUnits != null) {
    const projStr = formatProjectedUnits(projectedUnits);
    const projNum = Math.round(projectedUnits);
    qtyText  = `<strong>${projStr}</strong> ${unitLabel(item, projNum)} left`;
    qtyClass = '';
  } else if (daysLeft !== null) {
    qtyText  = `<strong>${item.months || 1}mo</strong> per purchase`;
    qtyClass = ' card-qty-interval'; // hidden on mobile via styles.css
  } else {
    qtyText  = '';
    qtyClass = '';
  }
  // Quick "−1" button shown only when we have a meaningful count to decrement
  const decrementBtn = (projectedUnits != null && projectedUnits >= 1)
    ? `<button class="card-plus-btn card-plus-btn-decrement" onclick="event.stopPropagation();quickAdjustStock('${item.id}',-1)" title="Used one — decrement count">−1</button>`
    : '';
  // Inline tags rendered up to TWO places: the original location below the
  // stock bar (desktop) AND in a mobile-only slot next to the days-left
  // hero (above the bar). styles.css toggles which copy is visible.
  const tagsInlineHTML = cardSelectedTagsInline(item);

  return `
  <div class="item-card${bulkSelectionHas('stock', item.id) ? ' selected' : ''}" style="border-left:3px solid ${color}" data-id="${item.id}" data-bulk-id="${item.id}" data-bulk-section="stock"
    onclick="onCardClick(event,'${item.id}')"
    onmouseenter="onCardHoverEnter('${item.id}')"
    onmouseleave="onCardHoverLeave('${item.id}')"
    ontouchstart="onCardTouchStart(event,'${item.id}')" ontouchmove="onCardTouchMove(event,'${item.id}')" ontouchend="onCardTouchEnd(event,'${item.id}')" ontouchcancel="onCardTouchEnd(event,'${item.id}')">
    <div class="swipe-hint" id="swipe-hint-${item.id}"><svg class="icon" aria-hidden="true"><use href="#i-clipboard-list"></use></svg></div>
    <div class="card-inner">
      <div class="card-top">
        <div class="card-category">${item.category||'Other'}</div>
        <div class="card-stars-row" onclick="event.stopPropagation()">${stars}</div>
        <div class="card-status" style="background:${color}22;color:${color}">${STATUS_LABEL[status]}</div>
        ${(isOwner() && item.share != null) ? (() => {
          // Per-item share override indicator (owner-only). Tells the
          // owner at a glance which items have non-default sharing. Guest
          // views never get this — their data is already filtered, so
          // the policy is moot from their side.
          const sh = item.share;
          let icon = 'i-shield', title = 'Custom sharing';
          if (sh === 'private') { icon = 'i-eye-off'; title = 'Private — owner only'; }
          else if (typeof sh === 'object') {
            if (Array.isArray(sh.allow))    title = `Visible to ${sh.allow.length} share${sh.allow.length===1?'':'s'} only`;
            else if (Array.isArray(sh.deny))title = `Hidden from ${sh.deny.length} share${sh.deny.length===1?'':'s'}`;
            if (Array.isArray(sh.readOnly) && sh.readOnly.length) title += ` · read-only for ${sh.readOnly.length}`;
          }
          return `<div class="card-share-indicator" title="${esc(title)}" style="color:var(--muted);display:flex;align-items:center" aria-label="${esc(title)}"><svg class="icon icon-sm" aria-hidden="true"><use href="#${icon}"></use></svg></div>`;
        })() : ''}
      </div>
      <div class="card-name">${esc(item.name)}</div>
      <div class="card-hero-block">
        ${(() => {
          if (daysLeft === null) return `<div class="card-nodata">No stock data yet</div>`;
          const f = formatDaysLeft(daysLeft);
          const suspectFlag = f.suspect
            ? ` <span title="Estimate looks unusually long — tap to recount stock" style="font-size:14px;cursor:help;color:var(--warn);vertical-align:middle" onclick="event.stopPropagation();openStockCountModal('${item.id}')">⚠</span>`
            : '';
          return `<div class="card-hero">
               <span class="card-days-num" style="color:${color}">${f.num}</span>
               <span class="card-days-unit">${f.unit}${suspectFlag}</span>
             </div>`;
        })()}
        ${tagsInlineHTML ? `<div class="card-tags-row card-tags-row-mobile">${tagsInlineHTML}</div>` : ''}
      </div>
      ${pct !== null
        ? `<div class="card-bar" data-card-bar><div class="card-bar-fill" style="width:${pct}%;background:${fillColor}"></div></div>`
        : ''}
      ${(lastBoughtAgo || bestPriceStr) ? `
        <div class="card-meta-desktop">
          ${lastBoughtAgo ? `<div class="card-meta-item">Last: <strong>${lastBoughtAgo}</strong></div>` : ''}
          ${bestPriceStr ? `<div class="card-meta-item">Best: <strong>${bestPriceStr}</strong></div>` : ''}
        </div>` : ''}
      ${tagsInlineHTML ? `<div class="card-tags-row card-tags-row-desktop">${tagsInlineHTML}</div>` : ''}
      <div class="card-footer">
        ${qtyText ? `<div class="card-qty${qtyClass}">${qtyText}</div>` : ''}
        ${item.ordered ? `<div class="card-ordered"><svg class="icon" aria-hidden="true"><use href="#i-truck"></use></svg> Ordered</div>` : ''}
        ${expiry ? `<div class="card-expiry" style="color:${expiry.color};border-color:${expiry.color}55" title="${fmtDate(item.expiry)}">⏰ ${expiry.label}</div>` : ''}
        ${decrementBtn ? `<div class="card-action-btns" onclick="event.stopPropagation()">${decrementBtn}</div>` : ''}
      </div>
      ${cardActionOverlayHTML(item)}
    </div>
  </div>`;
}

// Smart order button for item cards — compact pill matching the redesign mockup
function _cardOrderButton(item) {
  const hasPending          = (item.logs || []).some(l => l.pendingDelivery);
  const hasDeliveredNoStart = (item.logs || []).some(l => !l.pendingDelivery && l.deliveredDate) && !item.startedUsing;
  if (hasPending) {
    return `<button class="card-plus-btn card-plus-btn-delivered" onclick="openOrderFlow('${item.id}','delivered')" title="Mark delivered"><svg class="icon" aria-hidden="true"><use href="#i-package-check"></use></svg> Delivered</button>`;
  } else if (hasDeliveredNoStart) {
    return `<button class="card-plus-btn card-plus-btn-start" onclick="openOrderFlow('${item.id}','startusing')" title="Start using"><svg class="icon" aria-hidden="true"><use href="#i-play"></use></svg> Start using</button>`;
  } else {
    return `<button class="card-plus-btn" onclick="openOrderFlow('${item.id}','purchase')" title="Log purchase">+1</button>`;
  }
}

// ── Card action overlay ───────────────────────────────────────
// Hover (desktop) / long-press (mobile) reveals a blurred panel over the
// bottom of the card with extra actions (count stock, timeline, history,
// archive, edit). Visually anchors below the days-left bar.
function cardActionOverlayHTML(item) {
  const id = item.id;
  const isArchived = !!item._archived;
  const tiles = [
    { icon: 'i-shopping-cart', label: 'Log Order',     onclick: `openOrderFlow('${id}','purchase')` },
    { icon: 'i-hash',          label: 'Count Stock',   onclick: `openStockCountModal('${id}')` },
    { icon: 'i-bar-chart-2',   label: 'Order Timeline', onclick: `openAnalyticsModal('${id}')` },
    { icon: 'i-banknote',      label: 'Price History', onclick: `openPriceHistoryModal('${id}')` },
    { icon: 'i-archive',       label: isArchived ? 'Restore' : 'Archive',
      onclick: isArchived ? `restoreItem('${id}')` : `archiveItem('${id}')` },
    { icon: 'i-pencil',        label: 'Edit Details',  onclick: `openEditModal('${id}')` },
    { icon: 'i-tag',           label: 'Tag',           onclick: `openCardTagPicker('${id}')` },
    { icon: 'i-share-2',       label: 'Share',         onclick: `shareItemFromCard('${id}')` },
  ];
  return `<div class="card-action-overlay" data-overlay onclick="event.stopPropagation()">
    <div class="card-action-grid">
      ${tiles.map(t => `
        <button type="button" class="card-action-tile" onclick="event.stopPropagation();_dismissCardActions('${id}');${t.onclick}">
          <svg class="icon" aria-hidden="true"><use href="#${t.icon}"></use></svg>
          <span>${t.label}</span>
        </button>`).join('')}
    </div>
  </div>`;
}

// Share-from-card entry point: enters multi-select mode AND pre-selects
// the item the user clicked on. The action bar appears with "1 item
// selected" so the user can immediately tap Share — or add more items
// to the selection first. Same flow as if they'd tapped Manage then
// tapped this card.
function shareItemFromCard(id) {
  enterBulkSelectMode('stock');
  // enterBulkSelectMode clears any prior selection. Now add the one
  // the user clicked Share on.
  toggleBulkSelection('stock', id);
}

// ── Card interaction state ────────────────────────────────────
const _cardActionState = {
  // id → { hoverTimer, longPressTimer, longPressFired, suppressClick }
  by: {},
};
const CARD_HOVER_DELAY_MS    = 350;  // hover dwell before showing
const CARD_LONG_PRESS_MS     = 500;  // press duration to trigger
const CARD_LONG_PRESS_TOLERANCE = 8; // px of finger movement allowed before cancel

function _getCardEl(id) {
  return document.querySelector(`.item-card[data-id="${id}"]`);
}

// Position the overlay so it covers from just above the "X days left" text
// (.card-hero) all the way to the bottom of the card. Sets a CSS variable
// read by .card-action-overlay.
//
// Anchoring at card-hero gives a much taller hover area than the old
// "below the bar" position, which means the user has plenty of room to
// trigger hover without racing against any underlying buttons.
function _positionCardOverlay(card) {
  if (!card) return;
  // Prefer card-hero (the "X days left" line). Fall back to data-card-bar
  // for cards that don't have hero text yet (e.g. items with no stock data).
  const hero = card.querySelector('.card-hero');
  const anchor = hero || card.querySelector('[data-card-bar]');
  if (!anchor) {
    card.style.setProperty('--card-overlay-top', '50%');
    return;
  }
  const inner = card.querySelector('.card-inner');
  const innerRect  = inner.getBoundingClientRect();
  const anchorRect = anchor.getBoundingClientRect();
  // Position the overlay 6px ABOVE the anchor's top edge (rather than
  // 8px below its bottom, which is what the old code did).
  const top = Math.max(0, (anchorRect.top - innerRect.top) - 6);
  card.style.setProperty('--card-overlay-top', `${top}px`);
}

function _showCardActions(id) {
  const card = _getCardEl(id);
  if (!card) return;
  // Hide any others that might be open
  document.querySelectorAll('.item-card.actions-open').forEach(el => {
    if (el !== card) el.classList.remove('actions-open');
  });
  _positionCardOverlay(card);
  card.classList.add('actions-open');
}

// ── Item actions modal (mobile short tap) ─────────────────────
// On touch devices a short tap on the card pops this modal — full-size
// tap targets, summary stats, and a clean iOS-style secondary action list.
// Long-press goes to the heavier edit modal. The desktop equivalent is
// the in-card hover overlay (cardActionOverlayHTML).
function openItemActionsModal(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;

  // Header
  document.getElementById('ia-category').textContent = item.category || 'Other';
  document.getElementById('ia-name').textContent     = item.name || '(unnamed)';

  // Status pill — uses the same status mapping as the card
  const status = (typeof getStatus === 'function') ? getStatus(item) : 'good';
  const statusEl = document.getElementById('ia-status');
  const statusColor = (STATUS_COLOR && STATUS_COLOR[status]) || 'var(--ok)';
  const statusWord  = ({ critical:'Critical', warn:'Low', ok:'Good', nodata:'No data' })[status] || 'OK';
  statusEl.textContent = statusWord;
  statusEl.style.background = `color-mix(in srgb, ${statusColor} 13%, transparent)`;
  statusEl.style.color      = statusColor;

  // Stat strip — three concise numbers
  const s = calcStock(item);
  const projected = (typeof getProjectedUnitsLeft === 'function') ? getProjectedUnitsLeft(item) : null;
  const deliveredLogs = (item.logs || []).filter(l => !l.pendingDelivery);
  const lastLog = deliveredLogs[deliveredLogs.length - 1];

  // Stat 1: days/weeks/months left
  const stat1Num = document.getElementById('ia-stat-1-num');
  const stat1Lab = document.getElementById('ia-stat-1-label');
  if (s && s.daysLeft != null) {
    const f = formatDaysLeft(s.daysLeft);
    stat1Num.textContent = f.num;
    stat1Lab.textContent = f.unit;
    stat1Num.style.color = statusColor;
  } else {
    stat1Num.textContent = '—';
    stat1Lab.textContent = 'no data';
    stat1Num.style.color = 'var(--muted)';
  }

  // Stat 2: units in stock (projected if we have a count, else last purchase qty)
  const stat2Num = document.getElementById('ia-stat-2-num');
  const stat2Lab = document.getElementById('ia-stat-2-label');
  if (projected != null) {
    const projStr = (typeof formatProjectedUnits === 'function') ? formatProjectedUnits(projected) : String(projected);
    stat2Num.textContent = projStr;
    stat2Lab.textContent = `${unitLabel(item, Math.round(projected))} in stock`;
  } else if (lastLog) {
    stat2Num.textContent = lastLog.qty || 1;
    stat2Lab.textContent = `${unitLabel(item, lastLog.qty || 1)} bought`;
  } else {
    stat2Num.textContent = '—';
    stat2Lab.textContent = 'in stock';
  }
  stat2Num.style.color = '';

  // Stat 3: time since last order (or "ordered" badge if pending)
  const stat3Num = document.getElementById('ia-stat-3-num');
  const stat3Lab = document.getElementById('ia-stat-3-label');
  const hasPending = (item.logs || []).some(l => l.pendingDelivery);
  if (hasPending) {
    stat3Num.textContent = '⏳';
    stat3Lab.textContent = 'pending';
  } else if (lastLog) {
    const days = Math.max(0, Math.round((Date.now() - new Date(lastLog.date+'T12:00:00')) / MS_PER_DAY));
    if (days === 0)        { stat3Num.textContent = 'today'; stat3Lab.textContent = 'last order'; }
    else if (days < 14)    { stat3Num.textContent = `${days}d`; stat3Lab.textContent = 'since order'; }
    else if (days < 60)    { stat3Num.textContent = `${Math.round(days/7)}w`; stat3Lab.textContent = 'since order'; }
    else                   { stat3Num.textContent = `${Math.round(days/AVG_DAYS_PER_MONTH)}mo`; stat3Lab.textContent = 'since order'; }
  } else {
    stat3Num.textContent = '—';
    stat3Lab.textContent = 'no orders';
  }
  stat3Num.style.color = '';

  // Wire button click handlers (replace each round to avoid stacking listeners)
  const wire = (btnId, handler) => {
    const btn = document.getElementById(btnId);
    if (!btn) return;
    btn.onclick = (e) => {
      e.stopPropagation();
      closeModal('item-actions-modal');
      // Small delay so the modal close animation runs before the next opens
      setTimeout(handler, 60);
    };
  };
  wire('ia-q-order',    () => openOrderFlow(id, 'purchase'));
  wire('ia-q-count',    () => openStockCountModal(id));
  wire('ia-q-edit',     () => openEditModal(id));
  wire('ia-l-timeline', () => openAnalyticsModal(id));
  wire('ia-l-price',    () => openPriceHistoryModal(id));

  // Archive vs Restore — toggle label
  const archived = !!item._archived;
  const archLabel = document.getElementById('ia-l-archive-label');
  if (archLabel) archLabel.textContent = archived ? 'Restore' : 'Archive';
  wire('ia-l-archive', () => archived ? restoreItem(id) : archiveItem(id));

  // ── +Tag footer ──────────────────────────────────────────────
  // Shows the item's currently-applied tags as small pills, plus a
  // single +Tag button that opens the existing card-tag-picker modal
  // (same picker as the desktop hover overlay's Tag tile and the filter
  // bar's +Tag chip). Picker lets the user toggle existing tags or
  // create a new one with name + colour — anything created here is
  // applied to this item automatically by createTagFromPicker().
  // The picker uses its own .modal-overlay (z-index 500), so it layers
  // over this modal-backdrop (z-index 200) without dismissing it; the
  // user returns to the actions modal once they close the picker.
  const tagChipsHost = document.getElementById('ia-tag-chips');
  if (tagChipsHost) {
    const customTags = getCustomTags();
    const itemTags = item.tags || [];
    const chips = itemTags.map(i => {
      const tag = customTags[i];
      if (!tag || !tag.trim()) return '';
      const c = getTagColor(i);
      return `<span class="ia-tag-chip"
        style="background:${c.bg};border:1px solid ${c.border};color:${c.text}"
        >${esc(tag)}</span>`;
    }).filter(Boolean).join('');
    tagChipsHost.innerHTML = chips || `<span class="ia-tag-empty">No tags yet</span>`;
  }
  // The +Tag button keeps the actions modal open underneath; the picker
  // overlays on top and dismisses itself via its own close button.
  const tagBtn = document.getElementById('ia-q-tag');
  if (tagBtn) {
    tagBtn.onclick = (e) => {
      e.stopPropagation();
      openCardTagPicker(id);
    };
  }

  openModal('item-actions-modal');
}

function _dismissCardActions(id) {
  if (id) {
    const card = _getCardEl(id);
    if (card) card.classList.remove('actions-open');
    const st = _cardActionState.by[id];
    if (st) {
      clearTimeout(st.hoverTimer);
      clearTimeout(st.longPressTimer);
      st.hoverTimer = null; st.longPressTimer = null;
    }
  } else {
    document.querySelectorAll('.item-card.actions-open').forEach(el => el.classList.remove('actions-open'));
  }
}

// ── Click on the card body ────────────────────────────────────
// Suppress the open-edit click if a long-press just fired (touch path).
// Routing differs by device:
//   • Touch (coarse pointer, no hover) → short tap opens the quick action
//     panel; long-press opens the detailed edit modal. This puts the
//     common actions (Log Order / Count Stock / Edit / +Tag) one tap away
//     and reserves the long-press for the heavier editor.
//   • Desktop (fine pointer + hover) → click opens the edit modal as
//     before, since desktop users already get actions via hover overlay.
function onCardClick(event, id) {
  // Multi-select mode (Pass 2a generic): when active, taps toggle the
  // item's selection instead of opening the editor. Action menus + hover
  // are suppressed via the .bulk-select-mode body class (CSS).
  if (isBulkSelectMode('stock')) {
    if (event && event.stopPropagation) event.stopPropagation();
    toggleBulkSelection('stock', id);
    return;
  }
  const st = _cardActionState.by[id] || {};
  if (st.suppressClick) {
    st.suppressClick = false;
    return;
  }
  _dismissCardActions(id);
  // Touch devices: short tap → quick action panel. Desktop: click → editor.
  const isTouch = window.matchMedia
    && window.matchMedia('(hover: none) and (pointer: coarse)').matches;
  if (isTouch) {
    openItemActionsModal(id);
  } else {
    openEditModal(id);
  }
}

// ── Desktop hover ─────────────────────────────────────────────
function onCardHoverEnter(id) {
  if (_cardInteractionFrozen()) return;
  // Only on devices that can actually hover (not coarse touch)
  if (!window.matchMedia || !window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;
  const st = _cardActionState.by[id] || (_cardActionState.by[id] = {});
  clearTimeout(st.hoverTimer);
  st.hoverTimer = setTimeout(() => _showCardActions(id), CARD_HOVER_DELAY_MS);
}

function onCardHoverLeave(id) {
  if (_cardInteractionFrozen()) return;
  const st = _cardActionState.by[id];
  if (st) clearTimeout(st.hoverTimer);
  _dismissCardActions(id);
}

// ── Mobile long-press ─────────────────────────────────────────
// Coexists with the existing right-swipe to log purchase. The long-press
// is cancelled the moment swipeMove acquires a horizontal lock, so a user
// who swipes won't accidentally trigger the editor.
function onCardTouchStart(event, id) {
  if (_cardInteractionFrozen()) return;
  swipeStart(event, id);
  const st = _cardActionState.by[id] || (_cardActionState.by[id] = {});
  st.longPressFired = false;
  const t = event.touches[0];
  st.startX = t.clientX;
  st.startY = t.clientY;
  clearTimeout(st.longPressTimer);
  st.longPressTimer = setTimeout(() => {
    st.longPressFired = true;
    st.suppressClick = true;
    // Touch path: long-press opens the detailed edit modal. Short tap is
    // reserved for the quick action panel (see onCardClick). This pairing
    // surfaces the lighter actions first and gates the heavier editor
    // behind an intentional hold.
    openEditModal(id);
    if (navigator.vibrate) navigator.vibrate(20);
  }, CARD_LONG_PRESS_MS);
}

function onCardTouchMove(event, id) {
  if (_cardInteractionFrozen()) return;
  swipeMove(event, id);
  const st = _cardActionState.by[id];
  if (!st || !st.longPressTimer) return;
  // Cancel long-press if the finger moved beyond tolerance OR the swipe
  // handler has decided this gesture is horizontal.
  const t = event.touches[0];
  const dx = Math.abs(t.clientX - (st.startX || 0));
  const dy = Math.abs(t.clientY - (st.startY || 0));
  const swState = (typeof swipeState !== 'undefined') ? swipeState[id] : null;
  if (dx > CARD_LONG_PRESS_TOLERANCE || dy > CARD_LONG_PRESS_TOLERANCE || (swState && swState.locked === 'h')) {
    clearTimeout(st.longPressTimer);
    st.longPressTimer = null;
  }
}

function onCardTouchEnd(event, id) {
  if (_cardInteractionFrozen()) return;
  swipeEnd(event, id);
  const st = _cardActionState.by[id];
  if (st) {
    clearTimeout(st.longPressTimer);
    st.longPressTimer = null;
  }
}

// Dismiss any open overlay when clicking outside any card
document.addEventListener('click', (e) => {
  if (!e.target.closest || !e.target.closest('.item-card.actions-open')) {
    _dismissCardActions();
  }
}, true);

// Escape key dismisses
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') _dismissCardActions();
});

function storePricesCardHTML(item) {
  const prices = (item.storePrices || []).filter(sp => sp.store && sp.price);
  if (!prices.length) return '';
  const parsed = prices.map(sp => ({ ...sp, val: parsePriceValue(sp.price) }));
  const validPrices = parsed.filter(p => p.val !== null);
  const minVal = validPrices.length ? Math.min(...validPrices.map(p => p.val)) : null;
  const chips = parsed.map(sp => {
    const isBest = sp.val !== null && sp.val === minVal && validPrices.length > 1;
    return `<span style="font-size:11px;font-family:var(--mono);padding:2px 8px;border-radius:99px;background:${isBest?'rgba(76,187,138,0.15)':'var(--surface2)'};border:1px solid ${isBest?'rgba(76,187,138,0.4)':'var(--border)'};color:${isBest?'var(--ok)':'var(--muted)'};white-space:nowrap">
      ${esc(sp.store)}: ${esc(sp.price)}${isBest?' <svg class="icon" aria-hidden="true"><use href="#i-tag"></use></svg>':''}
    </span>`;
  }).join('');
  return `<div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px">${chips}</div>`;
}

function esc(str) {
  return String(str||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ═══════════════════════════════════════════
//  PRODUCT IMAGE FETCHING
// ═══════════════════════════════════════════
let pendingImageUrl = null; // holds fetched image URL until item is saved

const CATEGORY_EMOJI = {
  'Kitchen':'🍳', 'Bathroom':'🛁', 'Cleaning':'🧹',
  'Food & Drink':'☕', 'Health':'💊', 'Garden':'🌱',
  'Office':'📎', 'Other':'📦'
};

// ═══════════════════════════════════════════
//  CUSTOM TAGS
// ═══════════════════════════════════════════
// Default fallback tag colours (kept for back-compat with items that have
// tags but no per-tag colour assigned). Avoids red/green/orange to not clash
// with status indicator pills.
const TAG_COLORS = [
  { bg:'rgba(91,141,238,0.15)',  border:'rgba(91,141,238,0.5)',  text:'#5b8dee' },  // blue
  { bg:'rgba(193,100,232,0.15)', border:'rgba(193,100,232,0.5)', text:'#c164e8' },  // purple
  { bg:'rgba(100,180,200,0.15)', border:'rgba(100,180,200,0.5)', text:'#64b4c8' },  // teal
  { bg:'rgba(160,140,210,0.15)', border:'rgba(160,140,210,0.5)', text:'#a08cd2' },  // lavender
  { bg:'rgba(140,160,180,0.15)', border:'rgba(140,160,180,0.5)', text:'#8ca0b4' },  // slate
];

// Muted palette offered in the tag picker. Avoids red, orange, green which
// are reserved for status indicator pills. Each entry has the trio used to
// style the chip (bg / border / text).
const TAG_PICKER_PALETTE = [
  { name:'Blue',      bg:'rgba(91,141,238,0.15)',  border:'rgba(91,141,238,0.5)',  text:'#5b8dee' },
  { name:'Purple',    bg:'rgba(193,100,232,0.15)', border:'rgba(193,100,232,0.5)', text:'#c164e8' },
  { name:'Teal',      bg:'rgba(100,180,200,0.15)', border:'rgba(100,180,200,0.5)', text:'#64b4c8' },
  { name:'Lavender',  bg:'rgba(160,140,210,0.15)', border:'rgba(160,140,210,0.5)', text:'#a08cd2' },
  { name:'Slate',     bg:'rgba(140,160,180,0.15)', border:'rgba(140,160,180,0.5)', text:'#8ca0b4' },
  { name:'Rose',      bg:'rgba(220,140,180,0.15)', border:'rgba(220,140,180,0.5)', text:'#dc8cb4' },
  { name:'Pewter',    bg:'rgba(170,170,170,0.15)', border:'rgba(170,170,170,0.5)', text:'#aaaaaa' },
  { name:'Indigo',    bg:'rgba(120,130,210,0.15)', border:'rgba(120,130,210,0.5)', text:'#7882d2' },
];

// Resolve the colour trio for a given tag index. Per-tag colour comes from
// settings.tagColors[i] if set; otherwise fall back to TAG_COLORS[i].
function getTagColor(i) {
  const stored = settings.tagColors && settings.tagColors[i];
  if (stored && stored.bg && stored.border && stored.text) return stored;
  return TAG_COLORS[i % TAG_COLORS.length];
}

let activeTagFilter = null; // null = all, 0-4 = tag index

function getCustomTags() {
  return settings.customTags || ['','','','',''];
}

function cardTagsHTML(item) {
  const tags = getCustomTags();
  const itemTags = item.tags || [];
  const defined = tags.filter(t => t && t.trim());
  if (!defined.length) return '';

  const chips = tags.map((tag, i) => {
    if (!tag || !tag.trim()) return '';
    const c = getTagColor(i);
    const active = itemTags.includes(i);
    return `<span class="item-tag ${active ? 'active' : 'inactive'}"
      style="background:${active ? c.bg : 'transparent'};border-color:${c.border};color:${c.text}"
      onclick="toggleItemTag('${item.id}',${i})"
      title="${active ? 'Remove tag' : 'Add tag'}">${esc(tag)}</span>`;
  }).join('');

  return `<div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px">${chips}</div>`;
}

// Inline list of an item's selected tags (small pills) — used in the new
// card footer next to the +Tag / +1 buttons.
function cardSelectedTagsInline(item) {
  const tags = getCustomTags();
  const itemTags = item.tags || [];
  if (!itemTags.length) return '';
  const chips = itemTags.map(i => {
    const tag = tags[i];
    if (!tag || !tag.trim()) return '';
    const c = getTagColor(i);
    return `<span class="card-inline-tag" style="background:${c.bg};border:1px solid ${c.border};color:${c.text}">${esc(tag)}</span>`;
  }).filter(Boolean).join('');
  return chips;
}

async function toggleItemTag(itemId, tagIndex) {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === itemId);
  if (!item) return;
  if (!item.tags) item.tags = [];
  const idx = item.tags.indexOf(tagIndex);
  if (idx === -1) item.tags.push(tagIndex);
  else item.tags.splice(idx, 1);
  touchItem(item);
  await saveData();
  // Re-render just this card's tags without full grid re-render
  scheduleRender('grid');
  _syncQueue.enqueue();
}


// ── Card +Tag picker ────────────────────────────────────────────────
// Opens a modal over the active item card so the user can: (a) toggle
// existing tags on/off, (b) create a new tag with name + colour.
let _cardTagPickerItemId = null;

function openCardTagPicker(itemId) {
  _cardTagPickerItemId = itemId;
  _renderCardTagPicker();
  // Per-item context: original heading ("Tags") with the helper line visible.
  const title = document.getElementById('card-tag-picker-title');
  const hint  = document.getElementById('card-tag-picker-hint');
  if (title) title.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-tag"></use></svg> Tags';
  if (hint)  hint.style.display = '';
  const modal = document.getElementById('card-tag-picker-modal');
  if (modal) modal.classList.add('active');
}


// Clear both status filter and tag filter at once (the unified "All" chip).
function clearAllInlineFilters(btn) {
  activeFilter = 'all';
  activeCadence = 'all';
  activeTagFilter = null;
  // Reset checkbox UI in the collapsible filter panel too
  document.querySelectorAll('#filter-bar .filter-chip').forEach(c => c.classList.remove('active'));
  const allChip = document.querySelector('#filter-bar .filter-chip');
  if (allChip) allChip.classList.add('active');
  updateFilterBadge?.();
  reconcileFilters?.();
  buildTagFilterBar();
  scheduleRender('grid');
}

// Open the tag picker without an item context — used for the +Tag chip in the
// unified filter bar. Lets the user create a tag (with colour) without first
// selecting an item card.
function openCardTagPickerForCreate() {
  _cardTagPickerItemId = null;
  _renderCardTagPicker();
  // Create-only context: rebrand as "Tag editor" and remove both helper
  // lines (the static hint and the dynamic intro). The form below speaks
  // for itself — adding a hint here would just duplicate the section
  // heading "Create new tag".
  const title = document.getElementById('card-tag-picker-title');
  const hint  = document.getElementById('card-tag-picker-hint');
  if (title) title.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-tag"></use></svg> Tag editor';
  if (hint)  hint.style.display = 'none';
  const list = document.getElementById('card-tag-picker-list');
  if (list) list.innerHTML = '';
  // _renderCardTagPicker bails when there's no item, so the colour swatches
  // never get built on first open from this entry point. Build them here
  // so the colour picker is visible on the very first invocation.
  const swatches = document.getElementById('card-tag-picker-swatches');
  if (swatches && !swatches.dataset.built) {
    swatches.innerHTML = TAG_PICKER_PALETTE.map((p, i) => {
      const sel = i === 0 ? ' selected' : '';
      return `<button type="button" class="tag-swatch${sel}"
        data-idx="${i}"
        style="background:${p.bg};border:1.5px solid ${p.border}"
        onclick="_selectTagSwatch(${i})"
        title="${p.name}"></button>`;
    }).join('');
    swatches.dataset.built = '1';
  }
  // Also reset the "max tags reached" visibility for the no-item case
  const tags = getCustomTags();
  const defined = tags.filter(t => t && t.trim());
  const newForm = document.getElementById('card-tag-picker-new-form');
  if (newForm) newForm.style.display = (defined.length >= 5) ? 'none' : 'flex';
  const maxNote = document.getElementById('card-tag-picker-max-note');
  if (maxNote) maxNote.style.display = (defined.length >= 5) ? 'block' : 'none';
  const modal = document.getElementById('card-tag-picker-modal');
  if (modal) modal.classList.add('active');
  // Focus the name input
  setTimeout(() => document.getElementById('card-tag-picker-new-name')?.focus(), 50);
}

function closeCardTagPicker() {
  const modal = document.getElementById('card-tag-picker-modal');
  if (modal) modal.classList.remove('active');
  // If the item-actions modal is still open for the same item, refresh
  // its tag chips strip so the user sees the result of their toggle/
  // create immediately without having to reopen the modal.
  const iaModal = document.getElementById('item-actions-modal');
  if (_cardTagPickerItemId && iaModal && iaModal.classList.contains('open')) {
    const item = items.find(i => i.id === _cardTagPickerItemId);
    const host = document.getElementById('ia-tag-chips');
    if (item && host) {
      const customTags = getCustomTags();
      const itemTags = item.tags || [];
      const chips = itemTags.map(i => {
        const tag = customTags[i];
        if (!tag || !tag.trim()) return '';
        const c = getTagColor(i);
        return `<span class="ia-tag-chip"
          style="background:${c.bg};border:1px solid ${c.border};color:${c.text}"
          >${esc(tag)}</span>`;
      }).filter(Boolean).join('');
      host.innerHTML = chips || `<span class="ia-tag-empty">No tags yet</span>`;
    }
  }
  _cardTagPickerItemId = null;
  _resetTagPickerNewForm();
}

function _renderCardTagPicker() {
  const item = items.find(i => i.id === _cardTagPickerItemId);
  if (!item) return;
  const list = document.getElementById('card-tag-picker-list');
  if (!list) return;
  const tags = getCustomTags();
  const itemTags = item.tags || [];
  const defined = tags.map((t, i) => ({ t, i })).filter(({ t }) => t && t.trim());
  if (!defined.length) {
    list.innerHTML = `<p style="font-size:12px;color:var(--muted);margin:0">No tags yet — create one below.</p>`;
  } else {
    list.innerHTML = defined.map(({ t, i }) => {
      const c = getTagColor(i);
      const active = itemTags.includes(i);
      return `<button type="button" class="card-tag-toggle ${active ? 'active' : ''}"
        style="background:${active ? c.bg : 'transparent'};border:1px solid ${c.border};color:${c.text}"
        onclick="toggleItemTagFromPicker(${i})">${esc(t)}${active ? ' ✓' : ''}</button>`;
    }).join('');
  }
  // Populate colour swatches if not already
  const swatches = document.getElementById('card-tag-picker-swatches');
  if (swatches && !swatches.dataset.built) {
    swatches.innerHTML = TAG_PICKER_PALETTE.map((p, i) => {
      const sel = i === 0 ? ' selected' : '';
      return `<button type="button" class="tag-swatch${sel}"
        data-idx="${i}"
        style="background:${p.bg};border:1.5px solid ${p.border}"
        onclick="_selectTagSwatch(${i})"
        title="${p.name}"></button>`;
    }).join('');
    swatches.dataset.built = '1';
  }
  // Show "max tags reached" hint if 5 already defined
  const newForm = document.getElementById('card-tag-picker-new-form');
  if (newForm) newForm.style.display = (defined.length >= 5) ? 'none' : 'flex';
  const maxNote = document.getElementById('card-tag-picker-max-note');
  if (maxNote) maxNote.style.display = (defined.length >= 5) ? 'block' : 'none';
}

function _selectTagSwatch(idx) {
  document.querySelectorAll('#card-tag-picker-swatches .tag-swatch').forEach((el, i) => {
    el.classList.toggle('selected', i === idx);
  });
}

function _getSelectedTagSwatch() {
  const sel = document.querySelector('#card-tag-picker-swatches .tag-swatch.selected');
  return sel ? parseInt(sel.dataset.idx, 10) : 0;
}

function _resetTagPickerNewForm() {
  const inp = document.getElementById('card-tag-picker-new-name');
  if (inp) inp.value = '';
  const swatches = document.querySelectorAll('#card-tag-picker-swatches .tag-swatch');
  swatches.forEach((el, i) => el.classList.toggle('selected', i === 0));
}

async function toggleItemTagFromPicker(tagIdx) {
  if (_cardTagPickerItemId) {
    await toggleItemTag(_cardTagPickerItemId, tagIdx);
    _renderCardTagPicker();
  }
}

async function createTagFromPicker() {
  if (!canWrite('stockroom')) { showLockBanner('stockroom'); return; }
  const inp = document.getElementById('card-tag-picker-new-name');
  const name = (inp?.value || '').trim().slice(0, 20);
  if (!name) {
    if (inp) inp.focus();
    return;
  }
  const tags = getCustomTags();
  // Find first empty slot
  const slot = tags.findIndex(t => !t || !t.trim());
  if (slot === -1) {
    toast('Maximum 5 tags — delete one first');
    return;
  }
  // Also enforce duplicate prevention
  if (tags.some(t => (t || '').trim().toLowerCase() === name.toLowerCase())) {
    toast('A tag with that name already exists');
    return;
  }
  // Apply
  if (!settings.customTags) settings.customTags = ['','','','',''];
  settings.customTags[slot] = name;
  if (!settings.tagColors) settings.tagColors = [null, null, null, null, null];
  const swatchIdx = _getSelectedTagSwatch();
  settings.tagColors[slot] = TAG_PICKER_PALETTE[swatchIdx];
  settings.customTagsUpdatedAt = new Date().toISOString();
  await _saveSettings();
  _syncQueue.enqueue();
  // Auto-apply the new tag to the current item
  if (_cardTagPickerItemId) {
    await toggleItemTag(_cardTagPickerItemId, slot);
  }
  _resetTagPickerNewForm();
  _renderCardTagPicker();
  buildTagFilterBar();
  scheduleRender('grid');
  toast('Tag created ✓');
}

// Update the count text on each status chip inside the collapsible Filters
// panel. Status filtering itself lives in #filter-bar; the counts here just
// give the chips at-a-glance information without duplicating chips in the
// inline tag bar. Counts are derived from the same logic getStatus uses.
function _renderStatusCounts() {
  if (!Array.isArray(items)) return;
  const threshold = settings.threshold;
  let critical = 0, warn = 0, ok = 0, total = 0;
  items.forEach(item => {
    if (item._deletedAt) return;
    if (item._archived) return;
    total++;
    const s = calcStock(item);
    const status = getStatus(s?.pct ?? null, threshold);
    if (status === 'critical') critical++;
    else if (status === 'warn') warn++;
    else if (status === 'ok') ok++;
  });
  const setCount = (id, n) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.textContent = n > 0 ? String(n) : '';
  };
  setCount('status-count-all', total);
  setCount('status-count-critical', critical);
  setCount('status-count-warn', warn);
  setCount('status-count-ok', ok);
}

function buildTagFilterBar() {
  const bar = document.getElementById('tag-filter-bar');
  if (!bar) return;
  // Always refresh status counts in the dropdown panel — same trigger points
  // as the tag bar rebuild.
  _renderStatusCounts();
  const tags = getCustomTags();
  const defined = tags.map((t,i) => ({t,i})).filter(({t}) => t && t.trim());
  const hasRoom = defined.length < 5;

  // The "Filters:" label that used to lead this row was removed at Pete's
  // request — the chips themselves are obviously filters, and the label
  // was visually cluttering both desktop and mobile widths. The empty
  // string kept here so the concat below is structurally unchanged.
  const label = '';
  // "All" chip only makes sense when there is at least one tag chip to clear,
  // or a non-default status filter is active. Without tags AND with status
  // already on 'all', the chip is a no-op.
  const showAllChip = defined.length > 0 || (typeof activeFilter !== 'undefined' && activeFilter && activeFilter !== 'all');
  const allChip = showAllChip
    ? `<button class="tag-filter-chip${activeTagFilter===null && (activeFilter==='all' || !activeFilter)?' active':''}" onclick="clearAllInlineFilters(this)">All</button>`
    : '';
  const chips = defined.map(({t,i}) => {
    const c = getTagColor(i);
    const isActive = activeTagFilter === i;
    return `<span class="tag-filter-chip${isActive?' active':''}"
      style="${isActive?`background:${c.bg};border-color:${c.border};color:${c.text}`:`border-color:${c.border}55;color:${c.text}`}"
      onclick="setTagFilter(${i},this)">
      ${esc(t)}
      <span class="tag-x" onclick="event.stopPropagation();deleteTag(${i})" title="Remove tag">×</span>
    </span>`;
  }).join('');

  const addBtn = hasRoom
    ? `<button class="tag-filter-chip tag-filter-add" onclick="openCardTagPickerForCreate()" title="Create tag">+ Tag</button>`
    : '';

  bar.innerHTML = label + allChip + chips + addBtn;
}

function buildShoppingTagFilterBarInline() {
  const bar = document.getElementById('shopping-tag-filter-bar');
  if (!bar) return;
  const tags = getCustomTags();
  const defined = tags.map((t,i) => ({t,i})).filter(({t}) => t && t.trim());
  const hasRoom = defined.length < 5;

  const label = `<span style="font-size:11px;color:var(--muted);font-family:var(--mono);letter-spacing:0.5px;text-transform:uppercase;flex-shrink:0">Tags:</span>`;
  const allChip = defined.length
    ? `<button class="tag-filter-chip${shoppingTagFilter===null?' active':''}" onclick="setShoppingTagFilter(null,this)">All</button>`
    : '';
  const chips = defined.map(({t,i}) => {
    const c = getTagColor(i);
    const isActive = shoppingTagFilter === i;
    return `<span class="tag-filter-chip${isActive?' active':''}"
      style="${isActive?`background:${c.bg};border-color:${c.border};color:${c.text}`:''}"
      onclick="setShoppingTagFilter(${i},this)">
      ${esc(t)}
    </span>`;
  }).join('');
  const addBtn = hasRoom
    ? `<button class="btn-add-tag" onclick="showAddTagInput('shopping-tag-filter-bar')">+ Tag</button>`
    : '';
  bar.innerHTML = label + allChip + chips + addBtn;
}

function showAddTagInput(barId) {
  const bar = document.getElementById(barId);
  if (!bar) return;
  const addBtn = bar.querySelector('.btn-add-tag');
  if (!addBtn) return;
  const inp = document.createElement('input');
  inp.className = 'tag-inline-input';
  inp.placeholder = 'Tag name…';
  inp.maxLength = 20;
  addBtn.replaceWith(inp);
  inp.focus();

  let committed = false;
  const commit = () => {
    if (committed) return;
    committed = true;
    const val = inp.value.trim();
    if (val) addTag(val);
    else { buildTagFilterBar(); buildShoppingTagFilterBarInline(); }
  };
  inp.addEventListener('keydown', e => {
    if (e.key === 'Enter') { e.preventDefault(); commit(); }
    if (e.key === 'Escape') { committed = true; buildTagFilterBar(); buildShoppingTagFilterBarInline(); }
  });
  inp.addEventListener('blur', commit);
}

async function addTag(name) {
  if (!isOwner()) { toast("Settings are read-only"); return; }
  const tags = getCustomTags();
  const firstEmpty = tags.findIndex(t => !t || !t.trim());
  if (firstEmpty === -1) return;
  tags[firstEmpty] = name;
  settings.customTags = tags;
  settings.customTagsUpdatedAt = new Date().toISOString();
  await _saveSettings();
  buildTagFilterBar();
  buildShoppingTagFilterBarInline();
  renderGrid();
  _syncQueue.enqueue();
}

async function deleteTag(index) {
  if (!isOwner()) { toast("Settings are read-only"); return; }
  if (!confirm(`Remove tag "${getCustomTags()[index]}"? Items will lose this tag.`)) return;
  const tags = getCustomTags();
  tags[index] = '';
  settings.customTags = tags;
  settings.customTagsUpdatedAt = new Date().toISOString();
  items.forEach(item => {
    if (item.tags) item.tags = item.tags.filter(t => t !== index);
  });
  if (activeTagFilter === index) activeTagFilter = null;
  if (shoppingTagFilter === index) shoppingTagFilter = null;
  await _saveSettings();
  await saveData();
  buildTagFilterBar();
  buildShoppingTagFilterBarInline();
  renderGrid();
  _syncQueue.enqueue();
}

function setTagFilter(index, btn) {
  activeTagFilter = index;
  buildTagFilterBar();
  renderGrid();
}

function buildTagSettingsRows() {} // no-op — tags now managed inline



async function fetchProductImage() {
  // Free-tier photo gate
  try {
    if (window.stockroomBilling && stockroomBilling.isFree() && !stockroomBilling.featureAllowed('photos')) {
      if (typeof toastAction === 'function') {
        toastAction('Item photos require a paid plan', { label: 'Upgrade', onClick: () => navTo('billing') });
      } else {
        toast('Item photos require a paid plan');
      }
      return;
    }
  } catch (_) {}
  const name = document.getElementById('f-name').value.trim();
  const url  = document.getElementById('f-url').value.trim();
  if (!name && !url) { alert('Enter a product name first.'); return; }

  const btn    = document.getElementById('fetch-img-btn');
  const wrap   = document.getElementById('img-preview-wrap');
  const status = document.getElementById('img-preview-status');
  const preview = document.getElementById('img-preview');

  btn.textContent = '⏳ Searching…';
  btn.disabled = true;
  status.textContent = '';
  wrap.style.display = 'none';

  const imageUrl = await findProductImage(name || url);

  btn.textContent = 'Find Image';
  btn.disabled = false;

  if (imageUrl) {
    pendingImageUrl = imageUrl;
    preview.src = imageUrl;
    preview.onerror = () => {
      status.textContent = '<svg class="icon" aria-hidden="true"><use href="#i-alert-triangle"></use></svg> Image may not display cross-origin';
      status.style.color = 'var(--warn)';
    };
    status.textContent = '✓ Image found';
    status.style.color = 'var(--ok)';
    wrap.style.display = 'flex';
  } else {
    pendingImageUrl = null;
    wrap.style.display = 'none';
    toast('No image found — try a more specific product name');
  }
}

async function findProductImage(query) {
  // 1. Open Food Facts — best for food, drink, household consumables
  try {
    const offUrl = `https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(query)}&search_simple=1&action=process&json=1&page_size=5&fields=image_url,image_front_url,product_name`;
    const res = await fetch(offUrl, { signal: AbortSignal.timeout(6000) });
    if (res.ok) {
      const data = await res.json();
      const products = data.products || [];
      for (const p of products) {
        const img = p.image_front_url || p.image_url;
        if (img && img.startsWith('http')) return img;
      }
    }
  } catch(e) {}

  // 2. Open Beauty Facts — covers toiletries, cleaning products, cosmetics
  try {
    const obfUrl = `https://world.openbeautyfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(query)}&search_simple=1&action=process&json=1&page_size=5&fields=image_url,image_front_url`;
    const res = await fetch(obfUrl, { signal: AbortSignal.timeout(6000) });
    if (res.ok) {
      const data = await res.json();
      const products = data.products || [];
      for (const p of products) {
        const img = p.image_front_url || p.image_url;
        if (img && img.startsWith('http')) return img;
      }
    }
  } catch(e) {}

  // 3. DuckDuckGo image search as fallback — works for anything not in the above databases
  try {
    const ddgUrl = `https://api.allorigins.win/get?url=${encodeURIComponent(`https://duckduckgo.com/?q=${encodeURIComponent(query + ' product')}&iax=images&ia=images&format=json`)}`;
    const res = await fetch(ddgUrl, { signal: AbortSignal.timeout(8000) });
    if (res.ok) {
      const wrapper = await res.json();
      const html = wrapper.contents || '';
      // DDG embeds image data in a JSON block in the page
      const match = html.match(/"height":\d+,"image":"(https?:[^"]+)","source"/);
      if (match && match[1]) return match[1].replace(/\\\//g, '/');
    }
  } catch(e) {}

  return null;
}

function clearProductImage() {
  pendingImageUrl = null;
  hide('img-preview-wrap');
  document.getElementById('img-preview').src = '';
}

function showImagePreview(imageUrl, statusText) {
  showModalImagePreview(imageUrl);
  if (statusText) {
    const status = document.getElementById('img-preview-status');
    if (status) { status.textContent = '<svg class="icon" aria-hidden="true"><use href="#i-check"></use></svg> ' + statusText; status.style.color = 'var(--ok)'; }
  }
}

function showModalImagePreview(imageUrl) {
  if (!imageUrl) { clearProductImage(); return; }
  pendingImageUrl = imageUrl;
  const preview = document.getElementById('img-preview');
  const wrap = document.getElementById('img-preview-wrap');
  const status = document.getElementById('img-preview-status');
  preview.src = imageUrl;
  status.textContent = '✓ Saved image';
  status.style.color = 'var(--ok)';
  wrap.style.display = 'flex';
}



function parsePriceValue(priceStr) {
  if (!priceStr) return null;
  const num = parseFloat(String(priceStr).replace(/[^0-9.]/g, ''));
  return isNaN(num) ? null : num;
}

function getPriceHistory(item) {
  if (!item.logs || !item.logs.length) return [];
  return item.logs
    .map(l => ({ date: l.date, price: parsePriceValue(l.price), raw: l.price, store: l.store }))
    .filter(l => l.price !== null)
    .slice(-6); // last 6 priced purchases
}

function getPriceTrend(item) {
  const history = getPriceHistory(item);
  if (history.length < 2) return null;
  const last = history[history.length - 1].price;
  const prev = history[history.length - 2].price;
  const diff = last - prev;
  const pct  = Math.round(Math.abs(diff) / prev * 100);
  if (Math.abs(diff) < 0.01) return { dir: 'flat', diff: 0, pct: 0, last, prev };
  return { dir: diff > 0 ? 'up' : 'down', diff, pct, last, prev };
}

function priceTrendHTML(item) {
  const history = getPriceHistory(item);
  if (!history.length) return '';
  const last = history[history.length - 1];
  const trend = getPriceTrend(item);
  const lastFormatted = last.raw || `£${last.price.toFixed(2)}`;

  let trendBadge = '';
  if (trend) {
    if (trend.dir === 'up')   trendBadge = `<span style="color:var(--danger);font-size:10px;font-family:var(--mono)">↑${trend.pct}%</span>`;
    if (trend.dir === 'down') trendBadge = `<span style="color:var(--ok);font-size:10px;font-family:var(--mono)">↓${trend.pct}%</span>`;
    if (trend.dir === 'flat') trendBadge = `<span style="color:var(--muted);font-size:10px;font-family:var(--mono)">→</span>`;
  }

  // Mini sparkline dots for last 4 prices
  const sparkline = history.slice(-4).length > 1 ? (() => {
    const prices = history.slice(-4).map(h => h.price);
    const min = Math.min(...prices), max = Math.max(...prices);
    const range = max - min || 1;
    return `<span style="display:inline-flex;align-items:flex-end;gap:2px;height:14px;margin-left:4px">
      ${prices.map(p => {
        const h = Math.round(4 + ((p - min) / range) * 9);
        const c = p === prices[prices.length-1] ? 'var(--accent)' : 'var(--border)';
        return `<span style="width:3px;height:${h}px;background:${c};border-radius:1px;display:inline-block"></span>`;
      }).join('')}
    </span>`;
  })() : '';

  return `<div style="display:flex;align-items:center;gap:5px;font-size:11px;color:var(--muted);margin-bottom:6px">
    <span style="font-family:var(--mono)">💰 ${esc(lastFormatted)}</span>
    ${trendBadge}${sparkline}
    ${history.length > 1 ? `<span style="opacity:0.5">(${history.length} prices)</span>` : ''}
  </div>`;
}

function getFrequencyAnalysis(item) {
  if (!item.logs || item.logs.length < 2) return null;
  const sorted = [...item.logs].sort((a,b) => new Date(a.date) - new Date(b.date));
  const gaps = [];
  for (let i = 1; i < sorted.length; i++) {
    const days = (new Date(sorted[i].date) - new Date(sorted[i-1].date)) / MS_PER_DAY;
    if (days > 0) gaps.push(days);
  }
  if (!gaps.length) return null;
  const avgDays = gaps.reduce((a,b) => a+b, 0) / gaps.length;
  const avgMonths = avgDays / AVG_DAYS_PER_MONTH;
  const configuredMonths = item.months || 1;
  const ratio = avgMonths / configuredMonths;
  // Only suggest if meaningfully different (>25% off)
  const significant = ratio < 0.75 || ratio > 1.25;
  return { avgDays: Math.round(avgDays), avgMonths: parseFloat(avgMonths.toFixed(1)), configuredMonths, significant, purchases: sorted.length };
}

function frequencyInsightHTML(item) {
  const f = getFrequencyAnalysis(item);
  if (!f || !f.significant) return '';
  const actual = f.avgMonths < 1
    ? `~${Math.round(f.avgDays)} days`
    : `~${f.avgMonths} months`;
  const configured = f.configuredMonths === 1 ? '1 month' : `${f.configuredMonths} months`;
  const faster = f.avgMonths < f.configuredMonths;
  return `<div style="background:rgba(91,141,238,0.08);border:1px solid rgba(91,141,238,0.25);border-radius:8px;padding:8px 10px;margin-bottom:8px;font-size:11px;line-height:1.5;display:flex;align-items:flex-start;gap:8px">
    <span><svg class="icon" aria-hidden="true"><use href="#i-lightbulb"></use></svg></span>
    <span style="color:var(--muted)">
      Based on ${f.purchases} purchases, you actually restock every ${actual}
      — ${faster ? 'faster' : 'slower'} than your configured ${configured}.
      <button onclick="applyFrequencySuggestion('${item.id}',${f.avgMonths})" style="background:none;border:none;color:var(--accent2);cursor:pointer;font-size:11px;font-family:var(--sans);text-decoration:underline;padding:0;margin-left:4px">Update setting</button>
    </span>
  </div>`;
}

async function applyFrequencySuggestion(id, avgMonths) {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === id);
  if (!item) return;
  const rounded = Math.max(0.5, Math.round(avgMonths * 2) / 2); // round to nearest 0.5
  item.months = rounded;
  // Keep daysPerUnit in sync with the new months value
  item.daysPerUnit = (rounded * AVG_DAYS_PER_MONTH) / Math.max(0.0001, item.qty || 1);
  await saveData();
  scheduleRender('grid');
  toast(`Updated to ${rounded} month${rounded !== 1 ? 's' : ''} per purchase ✓`);
  _syncQueue.enqueue();
}


const DOMAIN_STORE_MAP = {
  'amazon.co.uk': 'Amazon UK', 'amazon.com': 'Amazon US', 'amazon.ca': 'Amazon CA',
  'amazon.com.au': 'Amazon AU', 'amazon.de': 'Amazon DE', 'amazon.fr': 'Amazon FR',
  'amazon.es': 'Amazon ES', 'amazon.it': 'Amazon IT', 'amazon.nl': 'Amazon NL',
  'amazon.co.jp': 'Amazon JP',
  'costco.co.uk': 'Costco UK', 'costco.com': 'Costco US', 'costco.ca': 'Costco CA',
  'costco.com.au': 'Costco AU',
  'tesco.com': 'Tesco', 'tesco.ie': 'Tesco IE',
  'sainsburys.co.uk': 'Sainsbury\'s',
  'ocado.com': 'Ocado',
  'waitrose.com': 'Waitrose',
  'asda.com': 'ASDA',
  'morrisons.com': 'Morrisons',
  'walmart.com': 'Walmart US', 'walmart.ca': 'Walmart CA',
  'target.com': 'Target',
  'woolworths.com.au': 'Woolworths',
  'coles.com.au': 'Coles',
  'rewe.de': 'REWE', 'dm.de': 'dm',
  'carrefour.fr': 'Carrefour',
  'bol.com': 'Bol.com',
  'ah.nl': 'Albert Heijn',
  'dunnesstoresgrocery.com': 'Dunnes',
  'elcorteingles.es': 'El Corte Inglés',
  'ica.se': 'ICA',
  'rakuten.co.jp': 'Rakuten',
  'iherb.com': 'iHerb',
  'hollandandbarrett.com': 'Holland & Barrett',
  'boots.com': 'Boots',
  'superdrug.com': 'Superdrug',
  'whsmith.co.uk': 'WHSmith',
  'johnlewis.com': 'John Lewis',
  'marks-and-spencer.com': 'M&S', 'marksandspencer.com': 'M&S',
};

function urlToStoreName(url) {
  if (!url || !url.trim()) return '';
  try {
    const hostname = new URL(url).hostname.replace(/^www\./, '');
    // Exact match first
    if (DOMAIN_STORE_MAP[hostname]) return DOMAIN_STORE_MAP[hostname];
    // Partial match — find any key that the hostname ends with
    const match = Object.keys(DOMAIN_STORE_MAP).find(k => hostname.endsWith(k));
    if (match) return DOMAIN_STORE_MAP[match];
    // Fallback: capitalise the second-level domain
    const parts = hostname.split('.');
    const sld = parts.length >= 2 ? parts[parts.length - 2] : parts[0];
    return sld.charAt(0).toUpperCase() + sld.slice(1);
  } catch(e) { return ''; }
}

function autoFillStore() {
  const url = document.getElementById('f-url').value.trim();
  const storeField = document.getElementById('f-store');
  // Only auto-fill if the field is empty or was previously auto-filled
  if (!storeField.dataset.manual) {
    const detected = urlToStoreName(url);
    storeField.value = detected;
    storeField.dataset.autoFilled = detected ? '1' : '';
  }
}


window._reportHousehold = '__all__';

async function setReportHousehold(key) {
  window._reportHousehold = key;
  if (key !== '__all__' && key !== activeProfile) {
    // Load that household's items temporarily for the report view
    const profiles = await getProfiles();
    const profile  = profiles[key];
    if (profile) {
      // Temporarily override items for report rendering
      const savedItems = items;
      items = profile.items || [];
      renderReport();
      items = savedItems;
      return;
    }
  }
  renderReport();
}

function renderReport() {
  const threshold = settings.threshold;
  document.getElementById('report-date').textContent = 'Generated: ' + new Date().toLocaleDateString('en-GB',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
  renderPendingDeliveries();

  // Render household tabs if multiple households exist
  getProfiles().then(profiles => {
    const keys = Object.keys(profiles);
    const tabsEl = document.getElementById('report-household-tabs');
    if (!tabsEl) return;
    if (keys.length <= 1) { tabsEl.style.display = 'none'; return; }
    tabsEl.style.display = 'flex';
    tabsEl.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px';
    tabsEl.innerHTML = [{ key: '__all__', name: 'All Households', colour: '#7880a0' },
      ...keys.map(k => ({ key: k, name: profiles[k]?.name || k, colour: profiles[k]?.colour || '#e8a838' }))
    ].map(({ key, name, colour }) => {
      const active = (window._reportHousehold || '__all__') === key;
      return `<button onclick="setReportHousehold('${key}')"
        style="padding:6px 14px;border-radius:99px;border:2px solid ${active ? colour : 'var(--border)'};
               background:${active ? colour + '22' : 'transparent'};color:${active ? colour : 'var(--muted)'};
               font-size:12px;font-weight:${active ? '700' : '400'};cursor:pointer;transition:all 0.2s">
        ${esc(name)}
      </button>`;
    }).join('');
  });

  // Determine which items to report on
  const reportItems = items; // current household items (or will be combined below)

  const groups = { critical:[], warn:[], ok:[], nodata:[] };
  reportItems.forEach(item => {
    const s = calcStock(item);
    const status = getStatus(s?.pct??null, threshold);
    groups[status].push({item, pct:s?.pct??null, daysLeft:s?.daysLeft??null});
  });

  const needBuy = [...groups.critical, ...groups.warn];
  let html = '';

  if (needBuy.length) {
    html += `<div id="need-to-buy"><h3><svg class="icon" aria-hidden="true"><use href="#i-alert-triangle"></use></svg> BUY BEFORE YOU RUN OUT</h3><div class="buy-chips">
      ${needBuy.map(({item,daysLeft}) => `<span class="buy-chip">${esc(item.name)} <span style="color:${daysLeft<7?'#e85050':'#e8a838'};font-family:var(--mono)">(${daysLeft??'?'}d)</span></span>`).join('')}
    </div></div>`;
  }

  const makeTable = entries => {
    if (!entries.length) return '<p style="color:var(--muted);font-size:13px;padding:10px 0">None</p>';
    return `<table class="report-table">
      <thead><tr><th>Item</th><th>Category</th><th>Rating</th><th>Last Price</th><th>Est. %</th><th>Days Left</th><th>Buy</th></tr></thead>
      <tbody>${entries.map(({item,pct,daysLeft}) => {
        const history = getPriceHistory(item);
        const trend = getPriceTrend(item);
        const lastPrice = history.length ? history[history.length-1].raw || `£${history[history.length-1].price.toFixed(2)}` : '—';
        const trendStr = trend ? (trend.dir==='up'?` <span style="color:#e85050">↑${trend.pct}%</span>`:trend.dir==='down'?` <span style="color:#4cbb8a">↓${trend.pct}%</span>`:'') : '';
        return `
        <tr>
          <td><strong>${esc(item.name)}</strong></td>
          <td style="color:var(--muted)">${esc(item.category||'Other')}</td>
          <td>${starsHTML(item.rating)}</td>
          <td style="font-family:var(--mono);font-size:12px">${esc(lastPrice)}${trendStr}</td>
          <td style="font-family:var(--mono);font-weight:700;color:${STATUS_COLOR[getStatus(pct,threshold)]}">${pct!==null?pct+'%':'—'}</td>
          <td style="font-family:var(--mono)">${daysLeft!==null?daysLeft+'d':'—'}</td>
          <td>${item.url?`<a href="${esc(item.url)}" target="_blank" rel="noopener" style="color:var(--accent2);font-size:12px;text-decoration:none">Buy ↗</a>`:'—'}</td>
        </tr>`;}).join('')}
      </tbody></table>`;
  };

  const section = (title, color, entries) => `
    <div class="report-section">
      <h3 style="color:${color};border-color:${color}44">${title} (${entries.length})</h3>
      ${makeTable(entries)}
    </div>`;

  html += section('<svg class="icon" aria-hidden="true"><use href="#i-circle"></use></svg> Critical — Order Now', '#e85050', groups.critical);
  html += section('<svg class="icon" aria-hidden="true"><use href="#i-circle"></use></svg> Getting Low — Order Soon', '#e8a838', groups.warn);
  html += section('<svg class="icon" aria-hidden="true"><use href="#i-circle"></use></svg> Well Stocked', '#4cbb8a', groups.ok);
  if (groups.nodata.length) html += section('<svg class="icon" aria-hidden="true"><use href="#i-circle"></use></svg> No Purchase Data', '#7880a0', groups.nodata);

  document.getElementById('report-content').innerHTML = html || '<p style="color:var(--muted);text-align:center;padding:60px">No items yet.</p>';
}

// ═══════════════════════════════════════════
//  MONTHLY SPEND TRACKER
// ═══════════════════════════════════════════
let spendVisible = false;

function toggleSpendView() {
  spendVisible = !spendVisible;
  const section = document.getElementById('spend-section');
  const btn     = document.getElementById('spend-toggle-btn');
  if (section) section.style.display = spendVisible ? 'block' : 'none';
  if (btn)     btn.style.background  = spendVisible ? 'var(--surface2)' : '';
  if (spendVisible) renderSpendChart();
}

function getMonthlySpend() {
  // Aggregate all log entries by month
  const byMonth = {};
  items.forEach(item => {
    (item.logs || []).forEach(log => {
      if (!log.date || !log.price) return;
      const val = parsePriceValue(log.price);
      if (val === null) return;
      const key = log.date.slice(0, 7); // YYYY-MM
      if (!byMonth[key]) byMonth[key] = { total: 0, entries: [] };
      byMonth[key].total += val;
      byMonth[key].entries.push({ item: item.name, price: val, raw: log.price, store: log.store });
    });
  });
  // Sort by month
  return Object.entries(byMonth)
    .sort(([a], [b]) => a.localeCompare(b))
    .slice(-12); // last 12 months
}

function calcPeriodSpend(days) {
  // Sum all logged purchases in the last N days that have prices
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
  let total = 0, priced = 0, unpriced = 0;
  const missingItems = [];
  items.forEach(item => {
    if (item._archived) return;
    let itemHadLog = false;
    (item.logs || []).forEach(log => {
      if (!log.date) return;
      const logMs = new Date(log.date).getTime();
      if (logMs < cutoff) return;
      itemHadLog = true;
      const val = parsePriceValue(log.price);
      if (val !== null) { total += val; priced++; }
      else unpriced++;
    });
    if (itemHadLog) {
      const latestLog = (item.logs || []).filter(l => {
        const ms = new Date(l.date).getTime();
        return ms >= cutoff;
      });
      const anyUnpriced = latestLog.some(l => parsePriceValue(l.price) === null);
      if (anyUnpriced && !missingItems.includes(item.name)) {
        missingItems.push(item.name);
      }
    }
  });
  return { total, priced, unpriced, missingItems };
}

function renderSpendChart() {
  const chartEl     = document.getElementById('spend-chart');
  const breakdownEl = document.getElementById('spend-breakdown');
  if (!chartEl || !breakdownEl) return;

  // ── 7 / 30 day spend summary ──
  const s7  = calcPeriodSpend(7);
  const s30 = calcPeriodSpend(30);
  const currency = '£';
  const hasAnySpend = s7.total > 0 || s30.total > 0;
  const allMissing  = [...new Set([...s7.missingItems, ...s30.missingItems])];

  let summaryHtml = '';
  if (hasAnySpend) {
    const missingNote = allMissing.length
      ? `<div style="margin-top:8px;font-size:11px;color:var(--muted);line-height:1.5">
          ⚠️ <strong>Estimate only</strong> — some purchases have no price logged:
          ${allMissing.slice(0,5).map(n=>`<em>${n}</em>`).join(', ')}${allMissing.length>5?' and more':''}.<br>
          Figures may not reflect actual spend due to missing prices and usage changes.
        </div>`
      : `<div style="margin-top:6px;font-size:11px;color:var(--muted)">Based on logged purchase prices. Actual spend may vary.</div>`;

    summaryHtml = `
      <div style="display:flex;gap:12px;margin-bottom:16px;flex-wrap:wrap">
        <div style="flex:1;min-width:120px;background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:12px 16px">
          <div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:1px;margin-bottom:4px">Last 7 days</div>
          <div style="font-size:24px;font-weight:700;font-family:var(--mono);color:var(--text)">${currency}${s7.total.toFixed(2)}</div>
          <div style="font-size:11px;color:var(--muted);margin-top:2px">${s7.priced} purchase${s7.priced!==1?'s':''} logged</div>
        </div>
        <div style="flex:1;min-width:120px;background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:12px 16px">
          <div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:1px;margin-bottom:4px">Last 30 days</div>
          <div style="font-size:24px;font-weight:700;font-family:var(--mono);color:var(--accent)">${currency}${s30.total.toFixed(2)}</div>
          <div style="font-size:11px;color:var(--muted);margin-top:2px">${s30.priced} purchase${s30.priced!==1?'s':''} logged</div>
        </div>
      </div>
      ${missingNote}
      ${allMissing.length ? '' : ''}`;
  }

  const data = getMonthlySpend();
  if (!data.length) {
    chartEl.innerHTML     = summaryHtml + `<p style="color:var(--muted);font-size:13px;margin-top:12px">No price data logged yet. Add prices when logging purchases to track spend over time.</p>`;
    breakdownEl.innerHTML = '';
    return;
  }
  chartEl.innerHTML = summaryHtml;

  const totals  = data.map(([, d]) => d.total);
  const maxVal  = Math.max(...totals);
  const W = 440, H = 180, PAD = { t: 16, r: 16, b: 40, l: 52 };
  const chartW  = W - PAD.l - PAD.r;
  const chartH  = H - PAD.t - PAD.b;
  const barW    = Math.min(36, (chartW / data.length) - 4);

  const bars = data.map(([month, d], i) => {
    const barH = maxVal > 0 ? (d.total / maxVal) * chartH : 0;
    const x    = PAD.l + (i / data.length) * chartW + (chartW / data.length - barW) / 2;
    const y    = PAD.t + chartH - barH;
    const isLatest = i === data.length - 1;
    const label = new Date(month + '-01').toLocaleDateString('en-GB', { month: 'short' });
    return `
      <rect x="${x}" y="${y}" width="${barW}" height="${barH}" rx="3" fill="${isLatest ? '#e8a838' : '#2e3350'}"/>
      <text x="${x + barW/2}" y="${y - 5}" text-anchor="middle" font-size="9" fill="${isLatest ? '#e8a838' : '#7880a0'}" font-family="monospace">${currency}${d.total.toFixed(0)}</text>
      <text x="${x + barW/2}" y="${H - PAD.b + 14}" text-anchor="middle" font-size="9" fill="#7880a0" font-family="monospace">${label}</text>`;
  }).join('');

  // avg line
  const avg  = totals.reduce((a, b) => a + b, 0) / totals.length;
  const avgY = PAD.t + chartH - (avg / maxVal) * chartH;
  const avgLine = `
    <line x1="${PAD.l}" y1="${avgY}" x2="${W - PAD.r}" y2="${avgY}" stroke="#7880a0" stroke-dasharray="4,3" stroke-width="1"/>
    <text x="${PAD.l - 4}" y="${avgY + 4}" text-anchor="end" font-size="9" fill="#7880a0" font-family="monospace">avg</text>`;

  // y-axis
  const yLabel = v => {
    const yy = PAD.t + chartH - (v / maxVal) * chartH;
    return `<text x="${PAD.l - 6}" y="${yy + 4}" text-anchor="end" font-size="9" fill="#7880a0" font-family="monospace">${currency}${v.toFixed(0)}</text>`;
  };
  const yLabels = [0, maxVal / 2, maxVal].map(yLabel).join('');

  chartEl.innerHTML += `
    <div style="font-size:13px;font-weight:700;color:var(--muted);margin-bottom:8px;margin-top:12px;font-family:var(--mono);text-transform:uppercase;letter-spacing:1px">Monthly trend</div>
    <svg viewBox="0 0 ${W} ${H}" style="width:100%;border-radius:8px;background:#1a1d27">
      ${yLabels}${avgLine}${bars}
    </svg>
    <div style="display:flex;gap:16px;margin-top:8px;font-size:11px;font-family:monospace;color:var(--muted)">
      <span>Total logged: ${currency}${totals.reduce((a,b)=>a+b,0).toFixed(2)}</span>
      <span>Monthly avg: ${currency}${avg.toFixed(2)}</span>
      <span style="color:#e8a838">This month: ${currency}${totals[totals.length-1].toFixed(2)}</span>
    </div>`;

  // Breakdown by category for latest month
  const [latestMonth, latestData] = data[data.length - 1];
  const byCat = {};
  latestData.entries.forEach(e => {
    const item = items.find(i => i.name === e.item);
    const cat  = item?.category || 'Other';
    if (!byCat[cat]) byCat[cat] = 0;
    byCat[cat] += e.price;
  });

  const catRows = Object.entries(byCat)
    .sort(([, a], [, b]) => b - a)
    .map(([cat, total]) => `
      <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid var(--border);font-size:13px">
        <span style="color:var(--muted)">${CATEGORY_EMOJI[cat]||'📦'} ${cat}</span>
        <span style="font-family:monospace;font-weight:700">${currency}${total.toFixed(2)}</span>
      </div>`).join('');

  const mLabel = new Date(latestMonth + '-01').toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
  breakdownEl.innerHTML = `
    <div style="margin-top:16px;padding-top:14px;border-top:1px solid var(--border)">
      <div style="font-size:13px;font-weight:700;margin-bottom:10px">Breakdown — ${mLabel}</div>
      ${catRows || '<p style="font-size:13px;color:var(--muted)">No data for this month.</p>'}
    </div>`;
}


function exportReport() {
  renderReport();
  const win = window.open('','_blank');
  win.document.write(`<html><head><title>Stockroom Report</title><style>body{font-family:sans-serif;padding:20px;color:#111}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #eee;text-align:left}h3{margin:24px 0 10px}</style></head><body><h1>Stockroom Report</h1><p>${new Date().toLocaleDateString()}</p>${document.getElementById('report-content').innerHTML}</body></html>`);
  win.document.close(); win.print();
}

// ═══════════════════════════════════════════
//  EMAIL REPORT (mailto: — Part A)
// ═══════════════════════════════════════════
function buildEmailBody() {
  const threshold = settings.threshold;
  const now = Date.now();
  const dateStr = new Date().toLocaleDateString('en-GB', { weekday:'long', year:'numeric', month:'long', day:'numeric' });

  // Classify items
  const within7  = [];
  const within30 = [];
  const ok       = [];

  items.forEach(item => {
    const s = calcStock(item);
    if (!s) return;
    if (s.daysLeft <= 7)  within7.push({ item, ...s });
    else if (s.daysLeft <= 30) within30.push({ item, ...s });
    else ok.push({ item, ...s });
  });

  within7.sort((a,b)  => a.daysLeft - b.daysLeft);
  within30.sort((a,b) => a.daysLeft - b.daysLeft);

  const runOutDate = daysLeft => new Date(now + daysLeft * MS_PER_DAY)
    .toLocaleDateString('en-GB', { day:'numeric', month:'short' });

  const stars = r => r ? '★'.repeat(r) + '☆'.repeat(5-r) : 'unrated';

  const formatSection = (entries, label) => {
    if (!entries.length) return `${label}\n(none)\n`;
    return `${label}\n${'─'.repeat(40)}\n` +
      entries.map(({item, daysLeft, pct}) => {
        const lines = [
          `• ${item.name}`,
          `  Runs out: ${runOutDate(daysLeft)} (${daysLeft} days, ${pct}% remaining)`,
        ];
        if (item.store) lines.push(`  Store: ${item.store}`);
        if (item.rating) lines.push(`  Rating: ${stars(item.rating)}`);
        if (item.url)   lines.push(`  Buy: ${item.url}`);
        return lines.join('\n');
      }).join('\n\n') + '\n';
  };

  const body = [
    `STOCKROOM REPORT — ${dateStr}`,
    `${'═'.repeat(50)}`,
    ``,
    `🔴 RUNNING OUT THIS WEEK (within 7 days) — ${within7.length} item${within7.length!==1?'s':''}`,
    formatSection(within7, ''),
    `🟡 RUNNING OUT THIS MONTH (8–30 days) — ${within30.length} item${within30.length!==1?'s':''}`,
    formatSection(within30, ''),
    `🟢 WELL STOCKED — ${ok.length} item${ok.length!==1?'s':''}`,
    ok.length ? ok.map(({item}) => `• ${item.name}`).join('\n') : '(none)',
    ``,
    `─────────────────────────────────────────`,
    `Total items tracked: ${items.length}`,
    `Generated by STOCKROOM`,
  ].join('\n');

  return body;
}

function emailReport() {
  const body   = buildEmailBody();
  const within7 = items.filter(i => { const s = calcStock(i); return s && s.daysLeft <= 7; }).length;
  const within30 = items.filter(i => { const s = calcStock(i); return s && s.daysLeft > 7 && s.daysLeft <= 30; }).length;
  const subject = `Stockroom Report — ${within7} urgent, ${within30} due soon`;
  const mailto  = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  window.location.href = mailto;
}



async function rateItem(id, val) {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === id);
  if (!item) return;
  item.rating = item.rating === val ? null : val;
  touchItem(item);
  await saveData();
  _syncQueue.enqueue();
  // Update stars in place — clear preview, set on
  const rating = item.rating || 0;
  document.querySelectorAll(`.card-star[data-id="${id}"]`).forEach(s => {
    s.classList.remove('preview');
    s.classList.toggle('on', parseInt(s.dataset.val) <= rating);
  });
  const label = document.getElementById('rl-' + id);
  if (label) {
    label.textContent = item.rating ? RATING_LABELS[item.rating] : 'Not rated';
    label.style.color = !item.rating ? 'var(--muted)' : item.rating <= 2 ? 'var(--danger)' : item.rating >= 4 ? 'var(--ok)' : 'var(--muted)';
  }
  currentRating = item.rating || 0;
}

function previewCardStars(id, val) {
  document.querySelectorAll(`.card-star[data-id="${id}"]`).forEach(s => {
    const n = parseInt(s.dataset.val);
    s.classList.toggle('preview', n <= val);
    s.classList.remove('on');
  });
  const item = items.find(i => i.id === id);
  const label = document.getElementById('rl-' + id);
  if (label) {
    label.textContent = RATING_LABELS[val] || '';
    label.style.color = val <= 2 ? 'var(--danger)' : val >= 4 ? 'var(--ok)' : 'var(--muted)';
  }
}

function resetCardStars(id) {
  const item = items.find(i => i.id === id);
  const rating = item?.rating || 0;
  document.querySelectorAll(`.card-star[data-id="${id}"]`).forEach(s => {
    const n = parseInt(s.dataset.val);
    s.classList.remove('preview');
    s.classList.toggle('on', n <= rating);
  });
  const label = document.getElementById('rl-' + id);
  if (label) {
    label.textContent = rating ? RATING_LABELS[rating] : 'Not rated';
    label.style.color = !rating ? 'var(--muted)' : rating <= 2 ? 'var(--danger)' : rating >= 4 ? 'var(--ok)' : 'var(--muted)';
  }
}


// ═══════════════════════════════════════════
//  PRICE HISTORY MODAL
// ═══════════════════════════════════════════
function openPriceHistoryModal(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;
  const history = getPriceHistory(item);
  if (!history.length) return;

  document.getElementById('ph-title').innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-banknote"></use></svg> ' + esc(item.name);

  const prices  = history.map(h => h.price);
  const minP    = Math.min(...prices);
  const maxP    = Math.max(...prices);
  const avgP    = prices.reduce((a,b)=>a+b,0) / prices.length;
  const trend   = getPriceTrend(item);
  const lastP   = prices[prices.length-1];
  const currency = (history.at(-1)?.raw||'').replace(/[\d.,\s]/g,'').trim() || '£';

  // Subtitle: trend summary
  let trendDesc = 'Stable price';
  if (trend) {
    if (trend.dir === 'up')   trendDesc = `↑ Up ${trend.pct}% vs last purchase`;
    if (trend.dir === 'down') trendDesc = `↓ Down ${trend.pct}% vs last purchase`;
  }
  document.getElementById('ph-subtitle').textContent = `${history.length} purchase${history.length!==1?'s':''} · ${trendDesc}`;

  // ── SVG bar chart ──
  const W = 440, H = 160, PAD = { t:16, r:16, b:36, l:48 };
  const chartW = W - PAD.l - PAD.r;
  const chartH = H - PAD.t - PAD.b;
  const range  = maxP - minP || 1;
  const barW   = Math.min(40, (chartW / history.length) - 6);

  const bars = history.map((h, i) => {
    const x    = PAD.l + (i / history.length) * chartW + (chartW / history.length - barW) / 2;
    const barH = ((h.price - minP) / range) * (chartH * 0.75) + chartH * 0.15;
    const y    = PAD.t + chartH - barH;
    const isLow  = h.price === minP && prices.length > 1;
    const isHigh = h.price === maxP && prices.length > 1 && minP !== maxP;
    const isLast = i === history.length - 1;
    const fill   = isLow ? '#4cbb8a' : isHigh ? '#e85050' : isLast ? '#e8a838' : '#2e3350';
    const label  = `${currency}${h.price.toFixed(2)}`;
    const dateLabel = new Date(h.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
    return `
      <rect x="${x}" y="${y}" width="${barW}" height="${barH}" rx="3" fill="${fill}"/>
      <text x="${x+barW/2}" y="${y-5}" text-anchor="middle" font-size="10" fill="${fill}" font-family="monospace">${label}</text>
      <text x="${x+barW/2}" y="${H-PAD.b+14}" text-anchor="middle" font-size="9" fill="#7880a0" font-family="monospace">${dateLabel}</text>`;
  }).join('');

  // avg line
  const avgY = PAD.t + chartH - (((avgP - minP) / range) * (chartH * 0.75) + chartH * 0.15);
  const avgLine = `
    <line x1="${PAD.l}" y1="${avgY}" x2="${W-PAD.r}" y2="${avgY}" stroke="#7880a0" stroke-dasharray="4,3" stroke-width="1"/>
    <text x="${PAD.l-4}" y="${avgY+4}" text-anchor="end" font-size="9" fill="#7880a0" font-family="monospace">avg</text>`;

  // y-axis labels
  const yLabels = [minP, avgP, maxP].map(p => {
    const y = PAD.t + chartH - (((p - minP) / range) * (chartH * 0.75) + chartH * 0.15);
    return `<text x="${PAD.l-6}" y="${y+4}" text-anchor="end" font-size="9" fill="#7880a0" font-family="monospace">${currency}${p.toFixed(2)}</text>`;
  }).join('');

  document.getElementById('ph-chart').innerHTML = `
    <svg viewBox="0 0 ${W} ${H}" style="width:100%;border-radius:8px;background:#1a1d27">
      ${yLabels}${avgLine}${bars}
    </svg>
    <div style="display:flex;gap:14px;margin-top:8px;font-size:11px;font-family:monospace">
      <span style="color:#4cbb8a">● Lowest: ${currency}${minP.toFixed(2)}</span>
      <span style="color:#7880a0">● Avg: ${currency}${avgP.toFixed(2)}</span>
      <span style="color:#e85050">● Highest: ${currency}${maxP.toFixed(2)}</span>
      <span style="color:#e8a838">● Latest: ${currency}${lastP.toFixed(2)}</span>
    </div>`;

  // ── Table ──
  document.getElementById('ph-table').innerHTML = `
    <div style="margin-top:16px;padding-top:14px;border-top:1px solid var(--border)">
      <table class="report-table">
        <thead><tr><th>Date</th><th>Store</th><th>Qty</th><th>Price</th><th>vs Prev</th></tr></thead>
        <tbody>${[...history].reverse().map((h,i,arr) => {
          const prev = arr[i+1];
          const prevP = prev ? prev.price : null;
          let vsEl = '—';
          if (prevP !== null) {
            const diff = h.price - prevP;
            const pct  = Math.round(Math.abs(diff)/prevP*100);
            vsEl = Math.abs(diff) < 0.01 ? '→' :
              diff > 0 ? `<span style="color:var(--danger)">↑${pct}%</span>` :
                         `<span style="color:var(--ok)">↓${pct}%</span>`;
          }
          const isLow  = h.price === minP && prices.length > 1;
          const isHigh = h.price === maxP && prices.length > 1 && minP !== maxP;
          return `<tr>
            <td style="font-family:monospace;font-size:12px">${fmtDate(h.date)}</td>
            <td style="color:var(--muted);font-size:12px">${esc(h.store||'—')}</td>
            <td style="font-family:monospace;font-size:12px">${history[history.length-1-i]?.qty||'—'}</td>
            <td style="font-family:monospace;font-weight:700;color:${isLow?'var(--ok)':isHigh?'var(--danger)':'var(--text)'}">${h.raw||currency+h.price.toFixed(2)}${isLow?' <svg class="icon" aria-hidden="true"><use href="#i-tag"></use></svg>':''}</td>
            <td style="font-size:12px">${vsEl}</td>
          </tr>`;
        }).join('')}</tbody>
      </table>
    </div>`;

  openModal('price-history-modal');
}


let stockCountId = null;

function openStockCountModal(id) {
  stockCountId = id;
  const item = items.find(i => i.id === id);
  if (!item) return;
  const last = item.logs?.at(-1);
  const totalPurchased = last?.qty || 1;

  document.getElementById('sc-subtitle').textContent = `How many ${unitLabel(item)} of "${item.name}" do you have left?`;
  document.getElementById('sc-explanation').textContent =
    `You last bought ${totalPurchased} ${unitLabel(item, totalPurchased)} on ${fmtDate(last?.date)}. ` +
    `Enter how many you have now — the app will calculate your actual consumption rate and project when you'll run out.`;
  // Mass/volume items may have fractional stock counts; countable ones are whole.
  const scRemEl = document.getElementById('sc-remaining');
  if (scRemEl) {
    if (unitTypeAllowsDecimal(item)) { scRemEl.step = '0.1'; scRemEl.min = '0'; }
    else                            { scRemEl.step = '1';   scRemEl.min = '0'; }
  }
  document.getElementById('sc-remaining').value = item.stockCount != null ? item.stockCount : '';
  document.getElementById('sc-date').value = today();
  // The "How long does 1 unit last?" field is per-unit lifetime in months.
  // Derive from the canonical daysPerUnit accessor.
  const dpu = getDaysPerUnit(item);
  const perUnitMonths = Math.max(0.25, Math.round((dpu / AVG_DAYS_PER_MONTH) * 4) / 4); // round to 0.25
  document.getElementById('sc-months').value = perUnitMonths;
  hide('sc-preview');

  const remaining = document.getElementById('sc-remaining');
  const dateEl = document.getElementById('sc-date');
  const monthsEl = document.getElementById('sc-months');
  const preview = () => updateStockCountPreview(item);
  remaining.oninput = preview;
  dateEl.onchange = preview;
  monthsEl.oninput = preview;

  if (item.stockCount != null) updateStockCountPreview(item);
  openModal('stock-count-modal');
}

function updateStockCountPreview(item) {
  const remaining = parseFloat(document.getElementById('sc-remaining').value);
  const countDate = document.getElementById('sc-date').value;
  // The field is per-unit lifetime in months → days-per-unit = months × AVG_DAYS_PER_MONTH
  const perUnitMonths = parseFloat(document.getElementById('sc-months').value);
  const dpu = (!isNaN(perUnitMonths) && perUnitMonths > 0)
    ? perUnitMonths * AVG_DAYS_PER_MONTH
    : getDaysPerUnit(item);
  const preview = document.getElementById('sc-preview');
  const previewText = document.getElementById('sc-preview-text');

  if (isNaN(remaining) || !countDate) { preview.style.display = 'none'; return; }

  const last = item.logs?.at(-1);
  const totalPurchased = last?.qty || 1;
  const daysSincePurchase = (Date.now() - new Date((last?.date||countDate)+'T12:00:00')) / MS_PER_DAY;
  const used = totalPurchased - remaining;

  let daysLeft;
  if (used <= 0 || daysSincePurchase <= 0) {
    // Configured rate: per-unit-days × units remaining
    daysLeft = Math.round(Math.max(0, dpu * remaining));
  } else {
    const ratePerDay = used / daysSincePurchase;
    daysLeft = ratePerDay > 0 ? Math.round(remaining / ratePerDay) : null;
  }

  const pct = Math.round(Math.max(0, Math.min(100, (remaining / totalPurchased) * 100)));
  const runOutDate = daysLeft != null
    ? new Date(Date.now() + daysLeft * MS_PER_DAY).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})
    : 'unknown';

  let msg;
  if (used > 0 && daysSincePurchase > 0) {
    const ratePerDay = used / daysSincePurchase;
    msg = `Used ${used.toFixed(1)} of ${totalPurchased} in ${Math.round(daysSincePurchase)} days ` +
          `(${ratePerDay.toFixed(2)}/day). ` +
          `${remaining} left → runs out ~${runOutDate} (${daysLeft ?? '?'} days, ${pct}% remaining).`;
  } else {
    const lifetimeLabel = perUnitMonths >= 1
      ? `${perUnitMonths} month${perUnitMonths !== 1 ? 's' : ''}/${unitLabel(item, 1)}`
      : `${Math.round(dpu)} days/${unitLabel(item, 1)}`;
    msg = `${remaining} of ${totalPurchased} ${unitLabel(item, remaining)} remaining (${pct}%) → estimated ${daysLeft ?? '?'} days left (${lifetimeLabel}).`;
  }

  previewText.textContent = msg;
  previewText.style.color = pct <= 15 ? 'var(--danger)' : pct <= 30 ? 'var(--warn)' : 'var(--ok)';
  preview.style.display = 'block';
}

async function saveStockCount() {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === stockCountId);
  if (!item) return;
  const val = document.getElementById('sc-remaining').value.trim();
  const countDate = document.getElementById('sc-date').value;
  const monthsVal = parseFloat(document.getElementById('sc-months').value);

  // The stock-count modal asks "How long does 1 unit last?" (months) — that
  // is per-unit lifetime, so update daysPerUnit directly and re-derive
  // `months` for back-compat with anywhere still reading the old field.
  if (!isNaN(monthsVal) && monthsVal > 0) {
    item.daysPerUnit = monthsVal * AVG_DAYS_PER_MONTH;
    // Keep `months` consistent — it now represents whole-purchase lifetime
    // (= per-unit-lifetime × pack-qty).
    item.months = monthsVal * (item.qty || 1);
  }

  if (val === '') {
    item.stockCount = null;
    item.stockCountDate = null;
  } else {
    item.stockCount = parseFloat(val);
    item.stockCountDate = countDate || today();
  }

  touchItem(item);
  await saveData();
  closeModal('stock-count-modal');
  scheduleRender('grid', 'dashboard');
  toast(val === '' ? 'Stock count cleared' : 'Stock count updated ✓');
  _syncQueue.enqueue();
}

// Quick "−1" / "+1" adjustment from the card. Decrements/increments the
// projected count and persists, but DOES NOT reset stockCountDate — that
// preserves the cumulative-consumption rate signal in calcStock (used =
// last.qty − stockCount over the full elapsed time since purchase).
async function quickAdjustStock(id, delta) {
  if (!canWrite('stockroom')) { showLockBanner('stockroom'); return; }
  const item = items.find(i => i.id === id);
  if (!item) return;

  // Start from current projected count (or fall back to last purchase qty)
  const projected = getProjectedUnitsLeft(item);
  const lastDelivered = (item.logs || []).filter(l => !l.pendingDelivery).at(-1);
  const baseline = projected != null ? projected : (lastDelivered?.qty || 1);
  const newCount = Math.max(0, Math.round((baseline + delta) * 100) / 100);

  // If there was no prior count, anchor the date now; otherwise keep the
  // original count date so the learned rate stays accurate.
  if (item.stockCount == null || !item.stockCountDate) {
    item.stockCountDate = today();
  }
  item.stockCount = newCount;
  touchItem(item);
  await saveData();
  scheduleRender('grid', 'dashboard');
  setTimeout(syncAll, 400);
  // Quick visual confirmation; no toast for routine −1 to avoid noise
  if (delta < 0 && newCount === 0) toast(`${item.name} — out of stock`);
}

// ═══════════════════════════════════════════
//  SUBSCRIBE & SAVE
// ═══════════════════════════════════════════

const SNS_DISCOUNT      = 0.05;  // 5% when 4+ items
const SNS_MIN_PURCHASES = 3;     // need at least 3 purchases
const SNS_MIN_SPAN_DAYS = 60;    // spanning at least 60 days
const SNS_MIN_ITEMS     = 4;     // need 4+ to hit 5% tier

function isAmazonStore(store) {
  return store && /amazon/i.test(store);
}

function isAmazonUrl(url) {
  return url && /amazon\./i.test(url);
}

function getSnSLink(item) {
  // Deep link to Subscribe & Save on Amazon using the product URL
  if (!item.url) return null;
  try {
    const u = new URL(item.url);
    // Extract ASIN from Amazon URL
    const asinMatch = item.url.match(/\/([A-Z0-9]{10})(?:[/?]|$)/);
    if (!asinMatch) return item.url; // fallback to product page
    const asin   = asinMatch[1];
    const domain = u.hostname; // e.g. www.amazon.co.uk
    return `https://${domain}/dp/${asin}?th=1&psc=1&subscribeSave=1`;
  } catch(e) { return item.url; }
}

function analyseSnS() {
  // Returns array of qualifying items with savings data
  const results = [];

  items.forEach(item => {
    const isAmazon = isAmazonStore(item.store) || isAmazonUrl(item.url);
    if (!isAmazon) return;

    const logs = (item.logs || []).filter(l => l.date).sort((a,b) => new Date(a.date) - new Date(b.date));
    if (logs.length < SNS_MIN_PURCHASES) {
      // Tracking — not enough purchases yet
      if (logs.length >= 1) {
        results.push({ item, status: 'tracking', logs, purchaseCount: logs.length, spanDays: 0, avgMonthlySpend: null, annualSaving: null });
      }
      return;
    }

    const firstDate = new Date(logs[0].date + 'T12:00:00');
    const lastDate  = new Date(logs[logs.length-1].date + 'T12:00:00');
    const spanDays  = (lastDate - firstDate) / MS_PER_DAY;

    if (spanDays < SNS_MIN_SPAN_DAYS) {
      results.push({ item, status: 'tracking', logs, purchaseCount: logs.length, spanDays, avgMonthlySpend: null, annualSaving: null });
      return;
    }

    // Calculate avg monthly spend from price logs
    const pricedLogs = logs.filter(l => parsePriceValue(l.price) !== null);
    let avgMonthlySpend = null;
    let annualSaving    = null;

    if (pricedLogs.length >= 1) {
      const avgPrice    = pricedLogs.reduce((s,l) => s + parsePriceValue(l.price), 0) / pricedLogs.length;
      const monthsSpan  = spanDays / AVG_DAYS_PER_MONTH;
      const buysPerMonth = logs.length / monthsSpan;
      avgMonthlySpend   = avgPrice * buysPerMonth;
      annualSaving      = avgMonthlySpend * 12 * SNS_DISCOUNT;
    }

    const status = item.subscribeAndSave ? 'active' : 'eligible';
    results.push({ item, status, logs, purchaseCount: logs.length, spanDays: Math.round(spanDays), avgMonthlySpend, annualSaving });
  });

  return results;
}

function renderSavingsView() {
  const all      = analyseSnS();
  const active   = all.filter(r => r.status === 'active');
  const eligible = all.filter(r => r.status === 'eligible');
  const tracking = all.filter(r => r.status === 'tracking');
  const qualifies = (active.length + eligible.length) >= SNS_MIN_ITEMS;

  const totalAnnualSaving = [...active, ...eligible]
    .reduce((s, r) => s + (r.annualSaving || 0), 0);
  const activeAnnualSaving = active
    .reduce((s, r) => s + (r.annualSaving || 0), 0);

  let html = '';

  if (!all.length) {
    html = `<div class="sns-empty">
      <div style="margin-bottom:16px;color:var(--accent)"><svg aria-hidden="true" style="width:48px;height:48px"><use href="#i-shopping-cart"></use></svg></div>
      <h3 style="font-size:18px;color:var(--text);margin-bottom:8px">No Amazon purchases found</h3>
      <p style="font-size:14px;line-height:1.7">Add items purchased from Amazon and log at least 3 purchases to see Subscribe &amp; Save opportunities.</p>
    </div>`;
    document.getElementById('savings-content').innerHTML = html;
    return;
  }

  // Summary card
  const qualifiesMsg = qualifies
    ? `<span style="color:var(--ok);font-weight:700">✓ You qualify for 5% off</span> — you have ${active.length + eligible.length} eligible Amazon items.`
    : `You need <strong>${SNS_MIN_ITEMS - (active.length + eligible.length)}</strong> more eligible item${(SNS_MIN_ITEMS - active.length - eligible.length) !== 1 ? 's' : ''} to reach the 5% discount tier.`;

  html += `<div class="sns-summary-card">
    ${totalAnnualSaving > 0 ? `<div class="sns-summary-stat"><div class="val">£${totalAnnualSaving.toFixed(2)}</div><div class="lbl">Est. annual saving</div></div>` : ''}
    ${activeAnnualSaving > 0 ? `<div class="sns-summary-stat"><div class="val" style="color:var(--accent2)">£${activeAnnualSaving.toFixed(2)}</div><div class="lbl">Already saving/yr</div></div>` : ''}
    <div class="sns-summary-stat"><div class="val" style="color:var(--warn)">${active.length + eligible.length}</div><div class="lbl">Eligible items</div></div>
    <div class="sns-summary-stat"><div class="val" style="color:var(--muted)">${tracking.length}</div><div class="lbl">Being tracked</div></div>
    <div style="flex:1;min-width:200px">
      <p style="font-size:13px;line-height:1.6;color:var(--muted)">${qualifiesMsg}</p>
      <p style="font-size:12px;color:var(--muted);margin-top:6px">Amazon Subscribe &amp; Save gives 5% off when you subscribe to 4+ products in a single delivery.</p>
    </div>
  </div>`;

  const makeItem = (r) => {
    const { item, status, purchaseCount, spanDays, avgMonthlySpend, annualSaving } = r;
    const snsLink  = getSnSLink(item);
    const lastPrice = (() => { const pl = (item.logs||[]).filter(l=>parsePriceValue(l.price)!==null); return pl.length ? pl[pl.length-1].price : null; })();

    const badge = status === 'active'
      ? `<span class="sns-badge sns-badge-active">✓ S&amp;S Active</span>`
      : status === 'eligible'
        ? `<span class="sns-badge sns-badge-eligible">💡 Eligible</span>`
        : `<span class="sns-badge sns-badge-tracking"><svg class="icon" aria-hidden="true"><use href="#i-timer"></use></svg> Tracking (${purchaseCount}/${SNS_MIN_PURCHASES} purchases)</span>`;

    const savingEl = annualSaving
      ? `<div class="sns-saving">£${annualSaving.toFixed(2)}/yr saving</div>`
      : lastPrice
        ? `<div style="font-size:12px;color:var(--muted)">Add prices to see £ saving</div>`
        : `<div style="font-size:12px;color:var(--muted)">Log prices to calculate saving</div>`;

    const toggleBtn = status !== 'tracking'
      ? `<button class="btn btn-sm ${status === 'active' ? 'btn-ghost' : 'btn-primary'}" onclick="toggleSnS('${item.id}')">${status === 'active' ? 'Mark as not subscribed' : '✓ Mark as subscribed'}</button>`
      : '';

    const snsBuyBtn = snsLink && status !== 'active'
      ? `<a href="${esc(snsLink)}" target="_blank" rel="noopener" class="btn btn-ghost btn-sm"><svg class="icon" aria-hidden="true"><use href="#i-link"></use></svg> Subscribe on Amazon</a>`
      : '';

    return `<div class="sns-item">
      <div class="sns-item-header">
        <div class="sns-item-name">${esc(item.name)}</div>
        ${badge}
      </div>
      <div class="sns-stats">
        <div class="sns-stat"><strong>${purchaseCount}</strong><span>purchases</span></div>
        ${spanDays ? `<div class="sns-stat"><strong>${Math.round(spanDays/AVG_DAYS_PER_MONTH * 10)/10}mo</strong><span>tracked</span></div>` : ''}
        ${lastPrice ? `<div class="sns-stat"><strong>${esc(lastPrice)}</strong><span>last price</span></div>` : ''}
        ${avgMonthlySpend ? `<div class="sns-stat"><strong>£${avgMonthlySpend.toFixed(2)}</strong><span>/month avg</span></div>` : ''}
      </div>
      ${savingEl}
      <div class="sns-actions">${toggleBtn}${snsBuyBtn}</div>
    </div>`;
  };

  if (eligible.length) {
    html += `<div class="sns-section-title">💡 Eligible — not yet subscribed (${eligible.length})</div>`;
    html += eligible.map(makeItem).join('');
  }
  if (active.length) {
    html += `<div class="sns-section-title">✓ Already subscribed (${active.length})</div>`;
    html += active.map(makeItem).join('');
  }
  if (tracking.length) {
    html += `<div class="sns-section-title"><svg class="icon" aria-hidden="true"><use href="#i-timer"></use></svg> Building history (${tracking.length})</div>`;
    html += tracking.map(makeItem).join('');
  }

  document.getElementById('savings-content').innerHTML = html;
}

async function toggleSnS(id) {
  if (!canWrite("savings")) { showLockBanner("savings"); return; }
  const item = items.find(i => i.id === id);
  if (!item) return;
  item.subscribeAndSave = !item.subscribeAndSave;
  await saveData();
  renderSavingsView();
  scheduleRender('sns');
  toast(item.subscribeAndSave ? 'Marked as subscribed ✓' : 'Marked as not subscribed');
  _syncQueue.enqueue();
}

function updateSnSBanner() {
  const banner = document.getElementById('sns-banner');
  if (!banner) return;
  // Once dismissed, the banner stays hidden forever (until user clears the
  // flag via Settings → Reset notifications, or whatever path you've wired).
  if (settings._snsBannerDismissed) { banner.style.display = 'none'; return; }
  const all      = analyseSnS();
  const eligible = all.filter(r => r.status === 'eligible');
  const active   = all.filter(r => r.status === 'active');
  const total    = eligible.length + active.length;

  if (total < 1) { banner.style.display = 'none'; return; }

  const qualifies = total >= SNS_MIN_ITEMS;
  const totalSaving = [...eligible, ...active].reduce((s,r) => s + (r.annualSaving||0), 0);
  const savingStr   = totalSaving > 0 ? ` — save <strong>£${totalSaving.toFixed(2)}/yr</strong>` : '';

  // Dismiss X — stops propagation so it doesn't trigger switchToSavings
  const dismissBtn = `<button onclick="event.stopPropagation();dismissSnsBanner()" title="Dismiss" style="flex-shrink:0;background:transparent;color:var(--muted);border:1px solid var(--border);border-radius:7px;padding:4px 6px;cursor:pointer;display:inline-flex;align-items:center"><svg class="icon" aria-hidden="true" style="width:13px;height:13px"><use href="#i-x"></use></svg></button>`;

  if (qualifies) {
    banner.innerHTML = `<div class="sns-banner" onclick="switchToSavings()">
      <div class="sns-banner-text">💰 You qualify for <strong>Amazon Subscribe &amp; Save 5%</strong> on ${total} items${savingStr}</div>
      <button class="btn btn-ghost btn-sm" style="flex-shrink:0">View savings →</button>
      ${dismissBtn}
    </div>`;
  } else if (eligible.length > 0) {
    const needed = SNS_MIN_ITEMS - total;
    banner.innerHTML = `<div class="sns-banner" onclick="switchToSavings()">
      <div class="sns-banner-text">💡 <strong>${total} Amazon item${total!==1?'s':''}</strong> could be on Subscribe &amp; Save — ${needed} more needed for 5% discount${savingStr}</div>
      <button class="btn btn-ghost btn-sm" style="flex-shrink:0">View savings →</button>
      ${dismissBtn}
    </div>`;
  } else {
    banner.style.display = 'none';
    return;
  }
  banner.style.display = 'block';
}

function dismissSnsBanner() {
  const banner = document.getElementById('sns-banner');
  if (banner) banner.style.display = 'none';
  settings._snsBannerDismissed = true;
  _saveSettings().then(() => kvPush().catch(() => {}));
  setTimeout(() => toast('Subscribe & Save tip dismissed'), 200);
}

function switchToSavings() {
  const tab = [...document.querySelectorAll('.tab')].find(t => t.textContent.includes('Savings'));
  if (tab) showView('savings', tab);
}

// ═══════════════════════════════════════════
//  SHOPPING LIST
// ═══════════════════════════════════════════
let shoppingStores = new Set(['__all__']);
let shoppingDays = 30;
let shoppingTagFilter = null; // null = all tags

function updateStockShoppingHeader(mode) {
  const stockBtn    = document.getElementById('hdr-stock-btn');
  const shoppingBtn = document.getElementById('hdr-shopping-btn');
  const toggle      = document.getElementById('days-toggle');
  const countEl     = document.getElementById('item-count');
  if (mode === 'stock') {
    if (stockBtn)    { stockBtn.style.fontWeight = '700'; stockBtn.style.color = 'var(--text)'; }
    if (shoppingBtn) { shoppingBtn.style.fontWeight = '400'; shoppingBtn.style.color = 'var(--muted)'; }
    if (toggle)      toggle.style.display = 'none';
    if (countEl)     countEl.style.display = '';
  } else {
    if (stockBtn)    { stockBtn.style.fontWeight = '400'; stockBtn.style.color = 'var(--muted)'; }
    if (shoppingBtn) { shoppingBtn.style.fontWeight = '700'; shoppingBtn.style.color = 'var(--text)'; }
    if (toggle)      toggle.style.display = '';
    if (countEl)     countEl.style.display = 'none';
  }
}

// ── View Transitions helpers ──────────────────────────────
const TAB_ORDER = ['stock', 'grocery', 'notes', 'reminders', 'savings', 'report', 'account-security', 'settings'];
let _currentView = 'stock';

function _vtSupported() { return !!document.startViewTransition; }

function _doTransition(direction, fn) {
  if (!_vtSupported() || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    fn(); return;
  }
  const content = document.getElementById('view-content');
  if (content) content.style.viewTransitionName = direction === 'back' ? 'main-view-back' : 'main-view';
  document.startViewTransition(() => { fn(); });
}

function setStockOnlyUI(visible) {
  // pending-deliveries-section and incomplete-section have their own logic that
  // hides them when there is nothing to show. We must NOT clear their inline
  // display:none here — instead, let their renderers manage it.
  const idsAlwaysToggle = ['health-dashboard', 'filter-toggle-btn', 'sort-select', 'tag-filter-bar', 'sns-banner'];
  idsAlwaysToggle.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = visible ? '' : 'none';
  });
  // For the top action sections: when leaving stock view, hide; when entering,
  // re-run the renderers so they show or hide based on actual content.
  if (!visible) {
    ['pending-deliveries-section', 'incomplete-section'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.style.display = 'none';
    });
  } else {
    // Defer to renderers — they hide the sections if nothing to show
    try { renderPendingDeliveries(); } catch(_) {}
    try { renderIncompleteSection(); } catch(_) {}
  }
  // filter-panel visibility must respect filtersOpen state, not just show/hide blindly
  const filterPanel = document.getElementById('filter-panel');
  if (filterPanel) filterPanel.style.display = visible && filtersOpen ? 'flex' : 'none';
  // Note: previously this code also toggled `#view-stock > div:nth-child(5)`,
  // but after the search/toolbar restructure that selector pointed to
  // #stock-search-toolbar — wiping its inline display:flex on view re-entry
  // and breaking the desktop layout. The elements that genuinely need
  // toggling are already in idsAlwaysToggle above; the nth-child line was
  // stale code from an older HTML structure.
}

function switchToStock() {
  _currentViewName = 'stock';
  _doTransition('back', () => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    document.getElementById('view-stock').classList.add('active');
    const stockTab = [...document.querySelectorAll('.tab')].find(t => t.textContent.includes('Stockroom'));
    if (stockTab) stockTab.classList.add('active');
    show('items-grid');
    hide('shopping-panel');
    setStockOnlyUI(true);
    updateStockShoppingHeader('stock');
    _currentView = 'stock';
    // Re-render the recycle bin (hidden when we entered Shopping subtab)
    try { renderItemsRecycleBin(); } catch(_) {}
  });
  if (_householdEnabled) pushPresence();
}

function switchToShopping() {
  _currentViewName = 'shopping';
  _doTransition('forward', () => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    document.getElementById('view-stock').classList.add('active');
    const stockTab = [...document.querySelectorAll('.tab')].find(t => t.textContent.includes('Stockroom'));
    if (stockTab) stockTab.classList.add('active');
    hide('items-grid');
    show('shopping-panel');
    // Hide the Stockroom recycle bin while in Shopping subtab — it belongs to
    // the main stock view only, and would otherwise float above the shopping list.
    const _bin = document.getElementById('items-recycle-bin');
    if (_bin) _bin.style.display = 'none';
    setStockOnlyUI(false);
    renderShoppingList();
    updateStockShoppingHeader('shopping');
  });
  if (_householdEnabled) pushPresence();
}

function showShoppingListInline() { switchToShopping(); }

// Session-only tick-off for shopping items (doesn't affect stock data)
const _shoppingTicked = new Set();
function toggleShoppingTick(id, labelEl) {
  const ticked = _shoppingTicked.has(id);
  if (ticked) {
    _shoppingTicked.delete(id);
  } else {
    _shoppingTicked.add(id);
  }
  const box     = document.getElementById(`sl-tick-${id}`);
  const name    = document.getElementById(`sl-name-${id}`);
  const bar     = document.getElementById(`sl-bar-${id}`);
  const actions = document.getElementById(`sl-actions-${id}`);
  const card    = document.getElementById(`si-${id}`);
  if (!ticked) {
    // Now ticked
    if (box)     { box.style.background = 'var(--ok)'; box.style.borderColor = 'var(--ok)'; box.innerHTML = '<svg width="12" height="12" viewBox="0 0 12 12"><polyline points="2,6 5,9 10,3" stroke="#fff" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>'; }
    if (name)    { name.style.textDecoration = 'line-through'; name.style.color = 'var(--muted)'; }
    if (bar)     { bar.style.opacity = '0.3'; }
    if (actions) { actions.style.display = 'none'; }
    if (card)    { card.style.opacity = '0.55'; }
  } else {
    // Unticked
    if (box)     { box.style.background = ''; box.style.borderColor = 'var(--border)'; box.innerHTML = ''; }
    if (name)    { name.style.textDecoration = ''; name.style.color = ''; }
    if (bar)     { bar.style.opacity = ''; }
    if (actions) { actions.style.display = ''; }
    if (card)    { card.style.opacity = ''; }
  }
}

// ═══════════════════════════════════════════════════════════
//  BILLING / SUBSCRIPTION (Phase 2)
// ═══════════════════════════════════════════════════════════
// Self-contained module managing subscription status, the Billing tab UI,
// trial banner, free-tier gating helpers, and Stripe Checkout/Portal
// redirects. Designed to be safe to call before sign-in (returns
// neutral defaults) and to fail open if the server is unreachable
// (treats user as paid so we don't block them on a network blip).
//
// Public surface:
//   stockroomBilling.refresh()           — fetch /billing/status, repaint UI
//   stockroomBilling.isPaid()            — sync read of cached status
//   stockroomBilling.featureAllowed(f)   — gate helper for client-side checks
//   stockroomBilling.handleApiError(r)   — common 402-handler for API responses
//   stockroomBilling.openCheckout(promo) — start Stripe Checkout flow
//   stockroomBilling.openPortal()        — open Stripe Customer Portal

window.stockroomBilling = (function() {
  // Cached status payload (last fetched from /billing/status). When null,
  // we treat the user as paid (fail open) so e.g. a network error during
  // /billing/status doesn't lock the UI for grandfathered users.
  let _cached = null;
  let _lastFetch = 0;
  const STATUS_TTL_MS = 60 * 1000; // 1 minute

  // Banner dismissal — per-session (resets on reload)
  let _bannerDismissed = false;

  function _isAuthed() {
    return !!(_kvEmailHash && (_kvVerifier || _kvSessionToken));
  }

  function _authBody() {
    return _kvSessionToken && !_kvVerifier
      ? { emailHash: _kvEmailHash, sessionToken: _kvSessionToken }
      : { emailHash: _kvEmailHash, verifier: _kvVerifier };
  }

  async function refresh(force) {
    if (!_isAuthed()) {
      _cached = null;
      return null;
    }
    const now = Date.now();
    if (!force && _cached && (now - _lastFetch) < STATUS_TTL_MS) return _cached;
    try {
      const r = await fetch(`${WORKER_URL}/billing/status`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(_authBody()),
      });
      if (!r.ok) {
        // 401 means session expired — let other parts of the app handle it.
        // For other errors, fail open: keep the existing cache (or null).
        return _cached;
      }
      _cached = await r.json();
      _lastFetch = now;
      _renderBanner();
      // If the Billing view is open, repaint it
      if (_currentViewName === 'billing') _renderBillingPage();
      // Piggyback the billing/account notification queue pull on the same
      // refresh heartbeat. Fire-and-forget — we don't block status refresh
      // on notification delivery. Errors are logged inside the helper.
      pullBillingNotifications();
      return _cached;
    } catch (err) {
      console.warn('[billing] /billing/status fetch failed:', err.message);
      return _cached; // fail open
    }
  }

  // Sync read of cached status. Safe to call from anywhere.
  function getStatus() { return _cached; }
  function isPaid()   { return !_cached || _cached.status !== 'free'; }
  function isTrial()  { return _cached && _cached.status === 'trial'; }
  function isFree()   { return !!_cached && _cached.status === 'free'; }

  // Server enforces the real check. This is for *UX* — show locked UI,
  // hide buttons, etc. Fail-open semantics: if status is unknown, allow.
  function featureAllowed(feature) {
    if (!_cached) return true;
    if (_cached.status !== 'free') return true;
    const m = _cached.limits || {};
    switch (feature) {
      case 'photos':  return !!m.photosAllowed;
      case 'grocery': return !!m.groceryAllowed;
      case 'notes':   return !!m.notesAllowed;
      case 'emails':  return !!m.emailsAllowed;
      case 'addItem': {
        // Allow add when below the visible cap, regardless of total existing
        // (the user may have items hidden — they can't add more on top).
        const visible = (items || []).filter(i => !i._deletedAt).length;
        return visible < (m.itemCount || 0);
      }
      default: return true;
    }
  }

  // Inspect a fetch Response for a 402 Payment Required error and surface
  // it as a toast that links to the Billing tab. Returns true if it
  // handled the response (caller should then bail out).
  async function handleApiError(response) {
    if (!response || response.status !== 402) return false;
    let reason = 'upgrade_required';
    try {
      const body = await response.clone().json();
      reason = body.reason || reason;
    } catch (_) {}
    const messages = {
      photos_require_upgrade:        'Photos require a paid plan',
      grocery_requires_upgrade:      'Grocery mode requires a paid plan',
      notes_require_upgrade:         'Notes require a paid plan',
      email_reminders_require_upgrade:'Email reminders require a paid plan',
      free_tier_size_exceeded:       'Free plan limit reached — upgrade for unlimited items',
    };
    const msg = messages[reason] || 'This feature requires a paid plan';
    if (typeof toastAction === 'function') {
      toastAction(msg, { label: 'Upgrade', onClick: () => navTo('billing') });
    } else if (typeof toast === 'function') {
      toast(msg + ' — open Billing to upgrade');
    }
    // Refresh status to make sure local cache matches reality
    refresh(true);
    return true;
  }

  // Build a human-readable trial countdown string.
  function _trialBannerText() {
    if (!_cached) return null;
    const s = _cached;
    if (s.status === 'trial' && typeof s.trialDaysLeft === 'number') {
      if (s.trialDaysLeft <= 0)  return { urgent: true,  text: 'Your free trial has ended — upgrade to keep grocery, notes and photos.' };
      if (s.trialDaysLeft === 1) return { urgent: true,  text: '1 day left of your free trial.' };
      if (s.trialDaysLeft <= 7)  return { urgent: false, text: `${s.trialDaysLeft} days left of your free trial.` };
      return null; // don't nag during early trial
    }
    if (s.rawStatus === 'past_due') {
      return { urgent: true, text: 'Payment failed — please update your card to keep your subscription active.' };
    }
    if (s.status === 'free' && s.hasStripeSubscription === false && s.trialEndsAt) {
      return { urgent: true, text: 'Your trial has ended. Upgrade to restore full access.' };
    }
    if (s.cancelAtPeriodEnd && s.currentPeriodEnd) {
      const days = Math.max(0, Math.ceil((s.currentPeriodEnd - Math.floor(Date.now()/1000)) / 86400));
      return { urgent: false, text: `Subscription cancels in ${days} day${days===1?'':'s'}.` };
    }
    return null;
  }

  function _renderBanner() {
    const bn = document.getElementById('billing-banner');
    if (!bn) return;
    if (_bannerDismissed) { bn.style.display = 'none'; return; }
    const info = _trialBannerText();
    if (!info) { bn.style.display = 'none'; return; }
    document.getElementById('billing-banner-text').textContent = info.text;
    bn.classList.toggle('urgent', !!info.urgent);
    bn.style.display = '';
  }

  function dismissBanner() {
    _bannerDismissed = true;
    const bn = document.getElementById('billing-banner');
    if (bn) bn.style.display = 'none';
  }

  // ── Billing page rendering ──
  function _renderBillingPage() {
    const card  = document.getElementById('billing-status-card');
    const acts  = document.getElementById('billing-plan-actions');
    if (!card || !acts) return;
    const s     = _cached;
    const planName = document.getElementById('billing-plan-name');
    const sub      = document.getElementById('billing-plan-subtitle');
    const features = document.getElementById('billing-features-list');
    const promoSec = document.getElementById('billing-promo-section');
    const acctSec  = document.getElementById('billing-account-section');

    if (!s) {
      planName.textContent  = 'Loading…';
      sub.textContent       = '';
      acts.innerHTML        = '';
      if (features) features.innerHTML = '';
      if (promoSec) promoSec.style.display = 'none';
      if (acctSec)  acctSec.style.display  = 'none';
      return;
    }

    // Plan name + subtitle + badge
    let badge, badgeClass, name, subtitle, ctas;
    if (s.grandfathered) {
      badgeClass = 'paid'; badge = 'Pro'; name = 'STOCKROOM Pro'; subtitle = 'Thanks for being an early supporter — your account has full access.'; ctas = [];
    } else if (s.status === 'paid' && s.rawStatus === 'active') {
      badgeClass = 'paid'; badge = 'Pro'; name = 'STOCKROOM Pro';
      subtitle = s.cancelAtPeriodEnd && s.currentPeriodEnd
        ? `Cancels on ${new Date(s.currentPeriodEnd*1000).toLocaleDateString()}`
        : (s.currentPeriodEnd ? `Renews ${new Date(s.currentPeriodEnd*1000).toLocaleDateString()}` : 'Active');
      ctas = s.cancelAtPeriodEnd
        ? [{label:'Resume subscription', primary:true, fn:'resumeSubscription'}]
        : [{label:'Manage subscription', primary:false, fn:'openBillingPortal'}];
    } else if (s.rawStatus === 'past_due') {
      badgeClass = 'past_due'; badge = 'Action needed'; name = 'Payment failed';
      subtitle = 'Update your payment method to keep your subscription active.';
      ctas = [{label:'Update payment method', primary:true, fn:'openBillingPortal'}];
    } else if (s.status === 'trial') {
      badgeClass = 'trial'; badge = 'Free trial'; name = 'STOCKROOM Pro (trial)';
      const days = s.trialDaysLeft ?? 0;
      subtitle = days > 0 ? `${days} day${days===1?'':'s'} left of your free trial. No payment required yet.` : 'Trial ending now.';
      ctas = [{label:'Upgrade now', primary:true, fn:'openBillingCheckout'}];
    } else { // free
      badgeClass = 'free'; badge = 'Free'; name = 'STOCKROOM Free';
      subtitle = 'Limited to 5 items. Upgrade to Pro for unlimited items, photos, grocery mode, notes and email reminders.';
      ctas = [{label:'Upgrade to Pro', primary:true, fn:'openBillingCheckout'}];
    }

    planName.innerHTML = `<span class="billing-plan-badge ${badgeClass}">${_escapeHtml(badge)}</span><br>${_escapeHtml(name)}`;
    sub.textContent    = subtitle;

    acts.innerHTML = '';
    ctas.forEach(c => {
      const btn = document.createElement('button');
      btn.className = c.primary ? 'btn btn-primary' : 'btn btn-ghost';
      btn.textContent = c.label;
      btn.onclick = () => window[c.fn] && window[c.fn]();
      acts.appendChild(btn);
    });

    // Features list
    if (features) {
      const isPaidNow = s.status !== 'free';
      const list = [
        { feat:'Unlimited items',          on: isPaidNow, desc: isPaidNow ? null : 'Free plan: 5 items maximum' },
        { feat:'Item photos',              on: !!s.limits.photosAllowed },
        { feat:'Grocery mode',             on: !!s.limits.groceryAllowed },
        { feat:'Notes mode',               on: !!s.limits.notesAllowed },
        { feat:'Email reminders',          on: !!s.limits.emailsAllowed },
        { feat:'Household sharing',        on: true },
      ];
      features.innerHTML = list.map(it => `
        <div class="billing-feature ${it.on ? '' : 'locked'}">
          <svg class="icon" aria-hidden="true"><use href="#${it.on ? 'i-circle-check' : 'i-lock'}"></use></svg>
          <div>${_escapeHtml(it.feat)}${it.desc ? `<small>${_escapeHtml(it.desc)}</small>` : ''}</div>
        </div>`).join('');
    }

    // Promo + account sections visibility
    if (promoSec) promoSec.style.display = (s.status === 'free' || s.status === 'trial') && s.pricing.configured ? '' : 'none';
    if (acctSec)  acctSec.style.display  = s.hasStripeCustomer && s.hasStripeSubscription ? '' : 'none';
  }

  function _escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  }

  // Human-friendly explanation of why the user can't share their code yet.
  // Mirrors the server-side ineligibleReason values from /referral/code.
  function _ineligibleReasonText(reason) {
    switch (reason) {
      case 'no_card_on_file':
        return "You're on the free trial. Add a payment method and start your subscription to begin referring friends.";
      case 'free_tier':
        return "Your subscription has lapsed. Re-subscribe to start referring friends again.";
      case 'not_active':
        return "Your subscription isn't currently active. Open the billing portal to update your card.";
      default:
        return "Referrals are available once you have an active paid plan. Trial users can't refer friends — this prevents abuse where new accounts could chain free months.";
    }
  }

  // ── Stripe Checkout / Portal flows ──
  async function openCheckout(promoCode) {
    if (!_isAuthed()) { toast && toast('Please sign in first'); return; }
    const status = _cached || await refresh(true);
    if (!status?.pricing?.configured) { toast && toast('Billing is not configured yet — please try again later'); return; }
    try {
      const body = _authBody();
      if (promoCode) body.promoCode = promoCode;
      const r = await fetch(`${WORKER_URL}/billing/checkout`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const data = await r.json();
      if (!r.ok || !data.url) {
        toast && toast(data.error || 'Could not start checkout');
        return;
      }
      window.location.href = data.url;
    } catch (err) {
      toast && toast('Network error — please try again');
    }
  }

  async function openPortal() {
    if (!_isAuthed()) return;
    try {
      const r = await fetch(`${WORKER_URL}/billing/portal`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(_authBody()),
      });
      const data = await r.json();
      if (!r.ok || !data.url) { toast && toast(data.error || 'Could not open billing portal'); return; }
      window.location.href = data.url;
    } catch (err) {
      toast && toast('Network error — please try again');
    }
  }

  async function cancelSubscription() {
    if (!_isAuthed()) return;
    if (!confirm('Cancel your subscription? You will keep access until the end of the current billing period, then drop to the free plan.')) return;
    try {
      const r = await fetch(`${WORKER_URL}/billing/cancel`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(_authBody()),
      });
      if (!r.ok) {
        const data = await r.json().catch(()=>({}));
        toast && toast(data.error || 'Could not cancel subscription');
        return;
      }
      toast && toast('Cancellation scheduled — you will keep access until period end');
      refresh(true);
    } catch (_) { toast && toast('Network error'); }
  }

  async function resumeSubscription() {
    if (!_isAuthed()) return;
    try {
      const r = await fetch(`${WORKER_URL}/billing/resume`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(_authBody()),
      });
      if (!r.ok) { toast && toast('Could not resume subscription'); return; }
      toast && toast('Subscription resumed');
      refresh(true);
    } catch (_) {}
  }

  async function validatePromo(code) {
    if (!code || !_isAuthed()) return null;
    try {
      const r = await fetch(`${WORKER_URL}/billing/apply-promo`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ..._authBody(), code: code.trim().toUpperCase() }),
      });
      return await r.json();
    } catch (_) { return null; }
  }

  // ── Return-from-Stripe handling ──
  // After checkout/portal, Stripe redirects back to our app with a query
  // param. We refresh status and show a toast.
  function _handleReturnFromStripe() {
    const params = new URLSearchParams(window.location.search);
    const billing = params.get('billing');
    if (!billing) return;
    // Strip the param so reloads don't repeat the message
    params.delete('billing');
    params.delete('session_id');
    const newQs = params.toString();
    history.replaceState({}, '', window.location.pathname + (newQs ? '?'+newQs : ''));
    // Refresh status — webhook may take a few seconds to land, so retry
    setTimeout(() => refresh(true), 500);
    setTimeout(() => refresh(true), 3000);
    setTimeout(() => refresh(true), 8000);
    if (billing === 'success') {
      toast && toast('✓ Subscription active — thanks!');
    } else if (billing === 'cancel') {
      toast && toast('Checkout cancelled');
    }
  }

  // ── Referral ──
  // Cached referral state. Refreshed on demand by fetchReferralState().
  let _referralState = null;
  let _referralLastFetch = 0;
  const REFERRAL_TTL_MS = 5 * 60 * 1000;

  async function fetchReferralState(force) {
    if (!_isAuthed()) return null;
    const now = Date.now();
    if (!force && _referralState && (now - _referralLastFetch) < REFERRAL_TTL_MS) return _referralState;
    try {
      const [codeRes, listRes] = await Promise.all([
        fetch(`${WORKER_URL}/referral/code`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(_authBody()),
        }),
        fetch(`${WORKER_URL}/referral/list`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(_authBody()),
        }),
      ]);
      if (!codeRes.ok) return null;
      const codeData = await codeRes.json();
      const listData = listRes.ok ? await listRes.json() : { referrals: [] };
      _referralState = { ...codeData, referrals: listData.referrals || [] };
      _referralLastFetch = now;
      // Repaint the billing page if it's open (referral section lives there)
      if (_currentViewName === 'billing') _renderReferralSection();
      return _referralState;
    } catch (err) {
      console.warn('[referral] fetch failed:', err.message);
      return null;
    }
  }

  function getReferralState() { return _referralState; }

  function _renderReferralSection() {
    const sec = document.getElementById('billing-referral-section');
    if (!sec) return;
    if (!_referralState) {
      sec.style.display = '';
      const dest = document.getElementById('billing-referral-card');
      if (dest) dest.innerHTML = '<div style="padding:20px;color:var(--muted);font-size:13px">Loading…</div>';
      return;
    }
    sec.style.display = '';
    const s = _referralState;
    const dest = document.getElementById('billing-referral-card');
    if (!dest) return;
    const shareUrl = `https://app.stckrm.com/?ref=${encodeURIComponent(s.code)}`;
    const capPct = Math.min(100, Math.round((s.lifetimeCreditsMonths / s.lifetimeCapMonths) * 100));
    const refList = (s.referrals || []).map(r => {
      const statusLabel = ({
        pending:   'Signed up',
        converted: '1st payment ✓',
        qualified: 'Qualified — 30 days credited',
        rejected:  `Rejected (${(r.rejectionReason || 'unknown').replace(/_/g,' ')})`,
      })[r.status] || r.status;
      const statusColor = ({
        pending: 'var(--muted)', converted: 'var(--accent)',
        qualified: 'var(--ok)',  rejected:  'var(--danger)',
      })[r.status] || 'var(--muted)';
      const date = new Date((r.signedUpAt || 0) * 1000).toLocaleDateString();
      return `<div style="padding:8px 0;border-top:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;font-size:12px">
        <div><span style="font-family:var(--mono);color:var(--muted)">${_escapeHtml(r.refereeRef)}…</span> · <span style="color:var(--muted)">${date}</span></div>
        <div style="color:${statusColor};font-weight:500">${statusLabel}</div>
      </div>`;
    }).join('');
    dest.innerHTML = `
      ${!s.eligible ? `
        <div class="acc-sec-row acc-sec-row-block" style="background:color-mix(in srgb,var(--accent) 6%,var(--bg));border-radius:8px;padding:14px;margin-bottom:10px">
          <div class="acc-sec-label" style="width:100%">
            <div class="acc-sec-h" style="display:flex;align-items:center;gap:8px">
              <svg class="icon icon-sm" aria-hidden="true" style="color:var(--accent)"><use href="#i-lock"></use></svg>
              Referrals require an active paid plan
            </div>
            <div class="acc-sec-p">${_ineligibleReasonText(s.ineligibleReason)}</div>
          </div>
          <div style="width:100%;margin-top:12px">
            <button class="btn btn-primary" onclick="openBillingCheckout()">Upgrade to start referring</button>
          </div>
        </div>` : ''}
      <div class="acc-sec-row acc-sec-row-block" style="${!s.eligible ? 'opacity:0.55;pointer-events:none;filter:grayscale(0.3)' : ''}">
        <div class="acc-sec-label" style="width:100%">
          <div class="acc-sec-h">Your code</div>
          <div class="acc-sec-p">Share this code with friends. When they sign up and complete their second paid month, you both get rewarded.</div>
        </div>
        <div style="width:100%;display:flex;gap:8px;align-items:center;margin-top:12px;flex-wrap:wrap">
          <code style="font-family:var(--mono);font-size:18px;font-weight:700;padding:8px 14px;background:var(--bg);border:1px solid var(--border);border-radius:8px;letter-spacing:1px">${_escapeHtml(s.code)}</code>
          <button class="btn btn-ghost btn-sm" ${!s.eligible ? 'disabled' : ''} onclick="copyReferralCode()">Copy code</button>
          <button class="btn btn-primary btn-sm" ${!s.eligible ? 'disabled' : ''} onclick="shareReferralLink()">Share link</button>
        </div>
        <div style="width:100%;margin-top:14px;font-size:12px;color:var(--muted)">
          You give: <strong style="color:var(--text)">${s.rewards.refereeDiscountPercent}% off ${s.rewards.refereeDiscountMonths} months</strong>
          &nbsp;•&nbsp; You get: <strong style="color:var(--text)">${s.rewards.referrerExtensionDays} days free per qualified referral</strong>
        </div>
      </div>
      <div class="acc-sec-row acc-sec-row-block" style="border-top:1px solid var(--border);margin-top:12px;padding-top:14px">
        <div class="acc-sec-label" style="width:100%">
          <div class="acc-sec-h" style="display:flex;justify-content:space-between;align-items:center">
            <span>Your stats</span>
            ${s.capReached ? '<span class="billing-plan-badge past_due" style="margin:0">Cap reached</span>' : ''}
          </div>
          <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px">
            <div style="padding:10px;background:var(--bg);border-radius:8px">
              <div style="font-size:20px;font-weight:700;color:var(--text)">${s.signupCount}</div>
              <div style="font-size:11px;color:var(--muted);margin-top:2px">Signed up</div>
            </div>
            <div style="padding:10px;background:var(--bg);border-radius:8px">
              <div style="font-size:20px;font-weight:700;color:var(--text)">${s.qualifiedCount}</div>
              <div style="font-size:11px;color:var(--muted);margin-top:2px">Qualified</div>
            </div>
            <div style="padding:10px;background:var(--bg);border-radius:8px">
              <div style="font-size:20px;font-weight:700;color:var(--ok)">${s.lifetimeCreditsMonths}<span style="font-size:13px;color:var(--muted);font-weight:400">/${s.lifetimeCapMonths}</span></div>
              <div style="font-size:11px;color:var(--muted);margin-top:2px">Months earned</div>
            </div>
          </div>
          ${s.capReached ? `
            <div style="margin-top:10px;padding:8px 12px;background:color-mix(in srgb,var(--danger) 8%,var(--bg));border-left:3px solid var(--danger);border-radius:4px;font-size:12px;color:var(--text)">
              You've reached the lifetime cap of ${s.lifetimeCapMonths} months earned. Future referrals will still count for stats but won't add more free time.
            </div>` : ''}
        </div>
      </div>
      ${refList ? `
        <div class="acc-sec-row acc-sec-row-block" style="border-top:1px solid var(--border);margin-top:12px;padding-top:14px">
          <div class="acc-sec-label" style="width:100%">
            <div class="acc-sec-h">Referrals</div>
            <div style="margin-top:6px">${refList}</div>
          </div>
        </div>` : `
        <div class="acc-sec-row acc-sec-row-block" style="border-top:1px solid var(--border);margin-top:12px;padding-top:14px">
          <div class="acc-sec-label" style="width:100%">
            <div class="acc-sec-p" style="font-style:italic">No referrals yet — share your code to get started!</div>
          </div>
        </div>`}`;
  }

  async function copyReferralCode() {
    if (!_referralState) return;
    if (!_referralState.eligible) { toast && toast('Upgrade to start referring friends'); return; }
    try { await navigator.clipboard.writeText(_referralState.code); toast && toast('Code copied'); }
    catch (_) { toast && toast('Could not copy — long-press to select'); }
  }

  async function shareReferralLink() {
    if (!_referralState) return;
    if (!_referralState.eligible) { toast && toast('Upgrade to start referring friends'); return; }
    const url   = `https://app.stckrm.com/?ref=${encodeURIComponent(_referralState.code)}`;
    const text  = `Join me on STOCKROOM — never run out of household essentials again. Use my code ${_referralState.code} for ${_referralState.rewards.refereeDiscountPercent}% off your first ${_referralState.rewards.refereeDiscountMonths} paid months: ${url}`;
    if (navigator.share) {
      try { await navigator.share({ title: 'STOCKROOM', text, url }); return; }
      catch (_) { /* user cancelled or share failed — fall through to clipboard */ }
    }
    try { await navigator.clipboard.writeText(text); toast && toast('Share link copied'); }
    catch (_) { toast && toast('Could not copy — long-press to select'); }
  }

  // Capture ?ref= from the URL on first load and stash for the signup form.
  function _captureRefFromUrl() {
    try {
      const params = new URLSearchParams(window.location.search);
      const ref = params.get('ref');
      if (ref) {
        window._pendingReferralCode = ref.toUpperCase();
        // Strip ?ref= so reloads don't keep it; preserve other params.
        params.delete('ref');
        const qs = params.toString();
        history.replaceState({}, '', window.location.pathname + (qs ? '?'+qs : ''));
        // Pre-fill the signup form's referral input if/when it appears.
        const tryFill = () => {
          const input = document.getElementById('kv-ref');
          if (input && !input.value) input.value = window._pendingReferralCode;
        };
        tryFill();
        setTimeout(tryFill, 500);
        setTimeout(tryFill, 2000);
      }
    } catch (_) {}
  }


  // Defer until DOM ready and initial sign-in completes.
  function init() {
    _captureRefFromUrl();
    _handleReturnFromStripe();
    // Initial fetch (will no-op if not signed in yet; signin flow re-calls)
    setTimeout(() => refresh(false), 1000);
    // Refresh hourly while the app is open
    setInterval(() => refresh(true), 60 * 60 * 1000);
    // Refresh when window regains focus (catches webhook updates)
    window.addEventListener('focus', () => refresh(false));
  }

  return {
    init,
    refresh,
    getStatus,
    isPaid, isTrial, isFree,
    featureAllowed,
    handleApiError,
    openCheckout,
    openPortal,
    cancelSubscription,
    resumeSubscription,
    validatePromo,
    dismissBanner,
    fetchReferralState,
    getReferralState,
    copyReferralCode,
    shareReferralLink,
    _renderBillingPage,
    _renderReferralSection,
  };
})();

// Top-level helpers exposed for inline onclick handlers
function openBillingCheckout(code) { return stockroomBilling.openCheckout(code); }
function openBillingPortal()       { return stockroomBilling.openPortal(); }
function cancelSubscription()      { return stockroomBilling.cancelSubscription(); }
function resumeSubscription()      { return stockroomBilling.resumeSubscription(); }
function dismissBillingBanner()    { return stockroomBilling.dismissBanner(); }
function copyReferralCode()        { return stockroomBilling.copyReferralCode(); }
function shareReferralLink()       { return stockroomBilling.shareReferralLink(); }

// ── Mobile menu (burger) ──
// On mobile we hide the secondary nav items (Report/Billing/Settings/
// Account & Security) from the tab bar to keep the row uncluttered, and
// surface them via this overlay menu opened from the header burger button.
// ── Mobile menu (burger dropdown) ──
// Toggles a top-right anchored dropdown rather than a centered modal —
// no full-screen backdrop, just the menu rendered on top of everything.
// Tap-outside-to-close is handled via a one-shot document listener.
function openMobileMenu() {
  const el = document.getElementById('mobile-menu-dropdown');
  if (!el) return;
  // Sync the active highlight with the current view BEFORE showing,
  // so there's no flash of the wrong state.
  _syncMobileMenuActive();
  el.classList.add('open');
  el.setAttribute('aria-hidden', 'false');
  // Defer attaching the outside-click listener by one event-loop tick
  // so the click that opened the menu doesn't immediately close it.
  setTimeout(() => {
    document.addEventListener('click', _mobileMenuOutsideClick, true);
    document.addEventListener('keydown', _mobileMenuKeyDown);
  }, 0);
}
function closeMobileMenu() {
  const el = document.getElementById('mobile-menu-dropdown');
  if (!el) return;
  el.classList.remove('open');
  el.setAttribute('aria-hidden', 'true');
  document.removeEventListener('click', _mobileMenuOutsideClick, true);
  document.removeEventListener('keydown', _mobileMenuKeyDown);
}
function _mobileMenuOutsideClick(e) {
  const el     = document.getElementById('mobile-menu-dropdown');
  const burger = document.getElementById('header-burger-btn');
  if (!el) return;
  // If the click is inside the menu OR on the burger button itself, don't close.
  if (el.contains(e.target) || (burger && burger.contains(e.target))) return;
  closeMobileMenu();
}
function _mobileMenuKeyDown(e) {
  if (e.key === 'Escape') closeMobileMenu();
}
// Sync the .active highlight on whichever menu item matches the current view.
function _syncMobileMenuActive() {
  const el = document.getElementById('mobile-menu-dropdown');
  if (!el) return;
  const cur = (typeof _currentViewName === 'string') ? _currentViewName : '';
  el.querySelectorAll('.mobile-menu-item[data-view]').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-view') === cur);
  });
}
function navFromMobileMenu(name) {
  closeMobileMenu();
  // Slight delay so the close transition doesn't fight a heavy view render.
  setTimeout(() => { try { navTo(name); } catch (_) {} }, 60);
}
// Stub kept for backwards-compat with any cached HTML/onclicks.
function closeMobileMenuOnOverlay(e) { closeMobileMenu(); }

// ═══════════════════════════════════════════
//  MOBILE TAB LAYOUT — swappable main row
// ═══════════════════════════════════════════
// At ≤600px the main tab row shows exactly three of six swappable views;
// the rest live in the top of the burger menu. The user picks which three
// via the burger's "Edit tabs" footer (openEditTabsModal). Choice is
// persisted in settings.mobileTabs as a 3-element array of view names.
//
// At the medium range (601–899px) the full 6-tab row is preferred (more
// horizontal space) so the data-mobile-tab="off" attribute is gated by
// the @media (max-width: 600px) rule in styles.css — at 601–899px every
// tab is shown except Report/Billing/Settings (those always burger-only).
//
// Three pieces work in concert:
//   1. _applyMobileTabLayout() — sets data-mobile-tab attribute + CSS
//      order on each .tab, AND rebuilds #mobile-menu-swappable with the
//      views NOT in the main row, in fixed Notes→Reminders→Savings
//      preference order.
//   2. settings.mobileTabs — array of 3 view names (default
//      ['stock','grocery','budget']). Persisted via _saveSettings.
//   3. openEditTabsModal / saveEditTabs — UI for picking 3 of 6.
//
// Called from: boot (after settings load), saveEditTabs (after persist),
// the SETTINGS_CHANGED broadcast handler (other tabs/devices), and on
// window resize (in case the user crosses the 600px threshold and we
// want the burger contents to match what's actually visible).

const _MOBILE_TAB_DEFAULTS = ['stock', 'grocery', 'budget'];
const _MOBILE_TAB_SWAPPABLE = ['stock', 'grocery', 'budget', 'notes', 'reminders', 'savings'];
// Preferred order when listing swappable views in the burger menu —
// Pete's spec: Notes → Reminders → Savings come first, then any of the
// "main three" defaults that got bumped out land after.
const _MOBILE_TAB_BURGER_ORDER = ['notes', 'reminders', 'savings', 'stock', 'grocery', 'budget'];
// Display metadata for the picker rows and the dynamically-injected
// burger-menu buttons. Mirrors the icons + labels used in #tabs / sidebar.
const _MOBILE_TAB_META = {
  stock:     { icon: 'i-package',         label: 'Stockroom'  },
  grocery:   { icon: 'i-shopping-cart',   label: 'Groceries'  },
  budget:    { icon: 'i-banknote',        label: 'Budget'     },
  notes:     { icon: 'i-notebook-pen',    label: 'Notes'      },
  reminders: { icon: 'i-bell',            label: 'Reminders'  },
  savings:   { icon: 'i-piggy-bank',      label: 'Savings'    },
};

// Return a sanitised 3-element array of swappable view names from
// settings, falling back to defaults if the stored value is malformed
// or missing. Guarantees the result is always valid for layout.
function _getMobileTabs() {
  const v = settings && settings.mobileTabs;
  if (Array.isArray(v) && v.length === 3
      && v.every(n => _MOBILE_TAB_SWAPPABLE.includes(n))
      && new Set(v).size === 3) {
    return v.slice();
  }
  return _MOBILE_TAB_DEFAULTS.slice();
}

// Map a view name back to its .tab button in #tabs. Returns null if
// the view isn't a swappable tab (e.g. report/billing/settings have
// their own tab buttons but aren't part of the swap pool).
// NOTE: must match BOTH quote styles because html-minifier-terser with
// --minify-js rewrites onclick="showView('x',this)" into
// onclick='showView("x",this)'. The source has 'x'; the minified
// production HTML has "x". Check for both.
function _getTabButtonForView(view) {
  const tabs = document.querySelectorAll('#tabs > .tab');
  const needleSingle = `'${view}'`;
  const needleDouble = `"${view}"`;
  for (const t of tabs) {
    const oc = t.getAttribute('onclick') || '';
    if (oc.includes(needleSingle) || oc.includes(needleDouble)) return t;
  }
  return null;
}

function _applyMobileTabLayout() {
  const chosen = _getMobileTabs(); // 3 view names in user's preferred order
  // 1. Mark each swappable tab on/off and set its display order to match
  //    the user's chosen sequence. Tabs not in the swap pool (report/
  //    billing/settings) are left alone — they're hidden via the static
  //    onclick selectors in the ≤899px media query.
  _MOBILE_TAB_SWAPPABLE.forEach(view => {
    const btn = _getTabButtonForView(view);
    if (!btn) return;
    const idx = chosen.indexOf(view);
    if (idx === -1) {
      btn.setAttribute('data-mobile-tab', 'off');
      btn.style.order = ''; // not relevant when hidden
    } else {
      btn.setAttribute('data-mobile-tab', 'on');
      btn.style.order = String(idx); // grid honours `order` on items
    }
  });

  // 2. Rebuild the swappable section at the top of the burger menu —
  //    contains the 3 views NOT currently in the main row, in fixed
  //    Notes → Reminders → Savings → (other defaults) order so the
  //    burger reads predictably regardless of which trio is chosen.
  const host = document.getElementById('mobile-menu-swappable');
  if (host) {
    const inBurger = _MOBILE_TAB_BURGER_ORDER.filter(v => !chosen.includes(v));
    host.innerHTML = inBurger.map(view => {
      const m = _MOBILE_TAB_META[view];
      if (!m) return '';
      return `<button class="mobile-menu-item" data-view="${view}" onclick="navFromMobileMenu('${view}')">
        <svg class="icon icon-tab" aria-hidden="true"><use href="#${m.icon}"></use></svg>
        <span>${m.label}</span>
      </button>`;
    }).join('');
  }
  // 3. The active highlight may now be on a freshly-injected button —
  //    re-run the syncer so the currently-open view is highlighted
  //    correctly in the burger menu if it lives there.
  try { _syncMobileMenuActive(); } catch (_) {}
}

// ── Edit-tabs modal ──
// Local state for the modal so we don't mutate settings.mobileTabs until
// the user taps Save. Stored as an ordered array; new picks append, so
// removing the first lets us implement a "drop oldest" FIFO rule when
// the user already has three selected and taps a fourth.
let _editTabsState = null;

function openEditTabsModal() {
  _editTabsState = _getMobileTabs(); // start from current setting
  _renderEditTabsList();
  // Closing the burger menu first feels cleaner than layering the
  // modal over the open dropdown — and the dropdown's outside-click
  // listener would fight the modal's tap targets otherwise.
  closeMobileMenu();
  openModal('edit-tabs-modal');
}
function closeEditTabsModal() {
  closeModal('edit-tabs-modal');
  _editTabsState = null;
}
function _renderEditTabsList() {
  const host = document.getElementById('edit-tabs-list');
  if (!host) return;
  // Iterate in the burger order so the rows read Notes/Reminders/Savings
  // first — consistent with where users find them in the menu.
  const rows = _MOBILE_TAB_BURGER_ORDER.map(view => {
    const m = _MOBILE_TAB_META[view];
    if (!m) return '';
    const idx = _editTabsState.indexOf(view);
    const selected = idx !== -1;
    const positionPill = selected
      ? `<span class="edit-tabs-row-position">${idx + 1}</span>`
      : '';
    return `<div class="edit-tabs-row ${selected ? 'selected' : ''}"
              data-view="${view}"
              onclick="_toggleEditTabsRow('${view}')">
      <svg class="icon icon-tab" aria-hidden="true"><use href="#${m.icon}"></use></svg>
      <span class="edit-tabs-row-label">${m.label}</span>
      ${positionPill}
      <span class="edit-tabs-checkbox">
        <svg class="icon" aria-hidden="true"><use href="#i-check"></use></svg>
      </span>
    </div>`;
  }).join('');
  host.innerHTML = rows;
  // Re-enable Save (a previous open might have left it disabled if state
  // ever drifted to <3 selections in an edge case).
  const saveBtn = document.getElementById('edit-tabs-save-btn');
  if (saveBtn) saveBtn.disabled = false;
}
function _toggleEditTabsRow(view) {
  if (!_editTabsState) return;
  const idx = _editTabsState.indexOf(view);
  if (idx !== -1) {
    // Deselecting — but only if doing so wouldn't leave fewer than 3
    // selections (otherwise the user is stuck with no valid config).
    if (_editTabsState.length <= 1) return;
    _editTabsState.splice(idx, 1);
    // We allow temporary <3 selection while picking, but in practice
    // the FIFO rule below keeps us at exactly 3 most of the time.
  } else {
    // Selecting — if already at 3, drop the oldest (FIFO).
    _editTabsState.push(view);
    if (_editTabsState.length > 3) _editTabsState.shift();
  }
  _renderEditTabsList();
}
async function saveEditTabs() {
  if (!_editTabsState || _editTabsState.length !== 3) {
    if (typeof toast === 'function') toast('Pick exactly 3 tabs');
    return;
  }
  settings.mobileTabs = _editTabsState.slice();
  settings.mobileTabsUpdatedAt = new Date().toISOString();
  try { await _saveSettings(); } catch (e) { console.warn('saveEditTabs persist failed', e); }
  try { _syncQueue && _syncQueue.enqueue && _syncQueue.enqueue(); } catch (_) {}
  _applyMobileTabLayout();
  closeEditTabsModal();
  if (typeof toast === 'function') toast('Tabs updated');
}

// Re-apply on resize so the burger menu always lists views that are
// genuinely off the main row. Cheap (DOM attribute writes), but debounce
// anyway to avoid spamming during a resize drag on desktop dev tools.
let _mobileTabResizeTimer = null;
window.addEventListener('resize', () => {
  clearTimeout(_mobileTabResizeTimer);
  _mobileTabResizeTimer = setTimeout(() => {
    try { _applyMobileTabLayout(); } catch (_) {}
  }, 150);
});

// Promo code field handlers
function onBillingPromoInput() {
  const el = document.getElementById('billing-promo-result');
  if (el) el.innerHTML = '';
}
async function validateBillingPromo() {
  const input  = document.getElementById('billing-promo-input');
  const result = document.getElementById('billing-promo-result');
  if (!input || !result) return;
  const code = (input.value || '').trim().toUpperCase();
  if (!code) { result.innerHTML = ''; return; }
  result.innerHTML = '<span style="color:var(--muted)">Checking…</span>';
  const res = await stockroomBilling.validatePromo(code);
  if (!res) { result.innerHTML = '<span class="billing-promo-result-error">Could not check code</span>'; return; }
  if (!res.valid) { result.innerHTML = '<span class="billing-promo-result-error">Code not found or expired</span>'; return; }
  let desc = '';
  if (res.percentOff)        desc = `${res.percentOff}% off`;
  else if (res.amountOff && res.currency) desc = `${(res.amountOff/100).toFixed(2)} ${res.currency.toUpperCase()} off`;
  else                        desc = 'Discount applied';
  if (res.duration === 'repeating' && res.durationInMonths) desc += ` for ${res.durationInMonths} month${res.durationInMonths===1?'':'s'}`;
  if (res.duration === 'forever') desc += ' (forever)';
  if (res.duration === 'once')    desc += ' (first invoice)';
  result.innerHTML = `<span class="billing-promo-result-ok">✓ ${desc} — code will apply at checkout</span>
    <div style="margin-top:8px"><button class="btn btn-primary btn-sm" onclick="openBillingCheckout('${code.replace(/'/g,'\\\'')}')">Apply &amp; checkout</button></div>`;
}

function _renderBillingLockscreen(which) {
  const viewId = which === 'grocery' ? 'view-grocery' : 'view-notes';
  const view   = document.getElementById(viewId);
  if (!view) return;
  // Hide all of view's existing children — we'll show our lockscreen
  // overlay instead. We keep them in the DOM so they're ready to come
  // back if/when the user upgrades.
  Array.from(view.children).forEach(c => {
    if (c.classList.contains('billing-lockscreen-overlay')) return;
    c.dataset._billingHidden = '1';
    c.style.display = 'none';
  });
  // Make / refresh the overlay
  let overlay = view.querySelector('.billing-lockscreen-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.className = 'billing-lockscreen-overlay';
    view.appendChild(overlay);
  }
  const labels = {
    grocery: { title: 'Grocery mode is part of Pro',
               body:  'Build named lists per store, share them with people in your household, and check items off as you go. Currently in your free plan.' },
    notes:   { title: 'Secure notes are part of Pro',
               body:  'End-to-end-encrypted notes for keeping rolling shopping notes, recipes, or reminders. Currently in your free plan.' },
  };
  const l = labels[which] || labels.grocery;
  overlay.innerHTML = `
    <div class="billing-lockscreen">
      <svg class="lock-icon icon" aria-hidden="true"><use href="#i-lock"></use></svg>
      <h3>${l.title}</h3>
      <p>${l.body}</p>
      <div class="billing-lockscreen-cta" style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center">
        <button class="btn btn-primary" onclick="navTo('billing')">See plans</button>
        <button class="btn btn-ghost" onclick="openBillingCheckout()">Upgrade now</button>
      </div>
    </div>`;
}

// When the user upgrades and free-tier content needs to come back, restore
// any view children we'd hidden. Called from refresh-after-checkout flows.
function _restoreFromBillingLockscreens() {
  document.querySelectorAll('[data-_billing-hidden]').forEach(el => {
    el.style.display = '';
    delete el.dataset._billingHidden;
  });
  document.querySelectorAll('.billing-lockscreen-overlay').forEach(el => el.remove());
}

function showView(name, btn) {
  // Exit any bulk-select mode when switching views — the action bar is
  // body-level so it'd otherwise persist into the new view. (Pass 2a:
  // applies to any registered section, not just stockroom.)
  if (isBulkSelectMode() && name !== _currentViewName) {
    exitBulkSelectMode();
  }
  _currentViewName = name;
  // Restore any previously-hidden view content from billing lockscreens
  // before swapping to the new view (cheap; idempotent if nothing hidden).
  try { _restoreFromBillingLockscreens(); } catch (_) {}
  const sectionMap = { grocery:'groceries', reminders:'reminders', savings:'savings', report:'report', stock:'stockroom', shopping:'stockroom', budget:'budget' };
  const section    = sectionMap[name];
  if (section && !canView(section)) { showLockBanner(section); return; }
  // Billing gate: when on free tier, render grocery/notes as locked screens
  // rather than blocking navigation entirely. The user can still SEE the
  // tab and understand what's there — they're just shown an upgrade CTA
  // instead of the live functionality.
  let billingLocked = false;
  try {
    if (window.stockroomBilling) {
      if (name === 'grocery' && !stockroomBilling.featureAllowed('grocery')) billingLocked = 'grocery';
      else if (name === 'notes' && !stockroomBilling.featureAllowed('notes')) billingLocked = 'notes';
    }
  } catch (_) {}
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
  const targetView = document.getElementById('view-'+name);
  if (targetView) targetView.classList.add('active');
  if (btn) btn.classList.add('active');
  // Tier 5.2 — keep ARIA tab state in sync. aria-selected must reflect the
  // active view no matter how it was reached (tab tap, sidebar, burger,
  // keyboard shortcut). We match each role=tab to its aria-controls target.
  const expectedPanel = 'view-' + name;
  document.querySelectorAll('#tabs [role="tab"]').forEach(tab => {
    const controls = tab.getAttribute('aria-controls');
    tab.setAttribute('aria-selected', controls === expectedPanel ? 'true' : 'false');
  });
  // Sync sidebar active state
  document.querySelectorAll('.app-nav-link').forEach(a => {
    a.classList.toggle('active', a.dataset.view === name);
  });
  if (name === 'report')    { renderReport(); if (spendVisible) renderSpendChart(); }
  if (name === 'reminders') renderReminders();
  if (name === 'shopping')  renderShoppingList();
  if (name === 'savings')   renderSavingsView();
  if (name === 'grocery')   {
    if (billingLocked === 'grocery') _renderBillingLockscreen('grocery');
    else {
      // Default landing is the list-picker overview. Clear the cached
      // active list so a fresh tab tap always shows the picker even if
      // the user was previously inside a list.
      activeGroceryListId = '';
      try { localStorage.removeItem('stockroom_active_grocery_list'); } catch(e) {}
      document.body.classList.remove('grocery-list-open');
      renderGrocery();
    }
  }
  if (name === 'budget')    renderBudget();
  if (name === 'notes')     { if (billingLocked === 'notes') _renderBillingLockscreen('notes'); else { renderNotes(); setTimeout(_maybeShowMfaPrompt, 600); } }
  if (name === 'account-security') renderAccountSecurity();
  if (name === 'accessibility') {
    // Sync the Theme and Text size segmented controls to the current
    // settings. These pickers live in the new Accessibility view but
    // are also embedded inline in omnibox search results (see
    // _renderSearchAccessibilityChip) — both share the same DOM ids,
    // so calling the same UI-update helpers keeps them in sync.
    _updateThemeUI();
    _updateTextScaleUI();
  }
  if (name === 'billing') {
    // Refresh status (force) and re-render the page. _renderBillingPage()
    // is called both immediately (with cached data) and when the fresh
    // status arrives, so the page never looks empty.
    try {
      stockroomBilling._renderBillingPage();
      stockroomBilling.refresh(true);
      // Fetch referral state in parallel — populates the section below
      // the plan card.
      stockroomBilling._renderReferralSection();
      stockroomBilling.fetchReferralState(false);
    } catch (_) {}
  }
  if (name === 'stock') {
    updateStockShoppingHeader('stock');
    setStockOnlyUI(true);
    show('items-grid');
    hide('shopping-panel');
  }
  if (name === 'settings') {
    renderSettingsForUser();
    buildSettingsCountrySelect();
    if (kvConnected) { loadTrustedDevices(); loadPasskeys(); }
    initSettingsCollapsibles();
    _refreshBudgetWeekStartRadio();
    // Lazy-refresh the Share Access section every time the user opens
    // Settings. Without this, the list reflects whatever state was loaded
    // at app init — which can be stale if (a) another device created/
    // removed a share, or (b) loadShareTargets early-returned at init
    // because credentials weren't ready yet. Cheap network call; the user
    // will be looking at the section a moment from now anyway.
    if (WORKER_URL && _kvEmailHash) loadShareTargets();
  }
  _currentView = name;
  // Notes view sits OUTSIDE #main (it's a body-level sibling, for reasons related
  // to its desktop fixed-positioning). Toggle a body class so CSS can hide the
  // empty #main when Notes is active — otherwise its empty padding leaves a
  // visual gap above the Notes header on mobile.
  document.body.classList.toggle('notes-view-active', name === 'notes');
  // Burger-menu views (Report / Billing / Settings / Account & Security) get
  // a body class so mobile CSS can hide the tab bar and show a back button
  // instead. Keeps the screen focused on the section the user navigated into
  // from the burger. _previousMainView remembers the last non-burger view so
  // the back button knows where to return.
  const BURGER_VIEWS = ['report', 'billing', 'settings', 'account-security', 'accessibility'];
  const isBurgerView = BURGER_VIEWS.includes(name);
  if (!isBurgerView) {
    // Remember every non-burger view we visit. When the user later taps a
    // burger-menu item, the back button can return them here.
    window._previousMainView = name;
  }
  document.body.classList.toggle('burger-view-active', isBurgerView);
  if (_householdEnabled) pushPresence();
  updateFab(name);
  // Clear grocery done-slide when leaving grocery view
  if (name !== 'grocery') _hideGroceryDoneSlide?.();
  // Demo mode — surface a one-time contextual nudge for relevant tabs.
  // Stockroom auto-fires from init, so we only handle the other three here.
  if (window._demoMode) {
    const nudgeMap = { grocery: 'groceries', savings: 'savings', budget: 'budget' };
    const which = nudgeMap[name];
    if (which) {
      // Small delay so the tab's content has rendered before the callout
      // tries to anchor to it
      setTimeout(() => _showDemoNudge(which), 400);
    } else {
      _hideAllDemoNudges();
    }
  }
}

// navTo — called by sidebar links (no btn element needed)
function navTo(name) {
  // Whenever we navigate (to any tab), drop the "grocery list open" body
  // class. The grocery tab handler will re-add it if the user enters a
  // specific list. Without this reset, switching from inside a list to
  // any other tab would leave the chrome-hidden state behind.
  if (name !== 'grocery') {
    document.body.classList.remove('grocery-list-open');
  }
  // Find the matching tab button if it exists (for mobile tab state)
  const tabBtn = [...document.querySelectorAll('.tab')].find(t => {
    const oc = t.getAttribute('onclick') || '';
    return oc.includes(`'${name}'`);
  });
  showView(name, tabBtn || { classList: { add: () => {}, remove: () => {} } });
}

// Back navigation from a burger-menu view (Report / Billing / Settings /
// Account & Security). Called by the mobile back button that replaces the
// tab bar on those views. Returns to whichever non-burger view the user
// last visited, falling back to Stockroom if there's no record. _previous-
// MainView is set in showView whenever the user lands on a non-burger view.
function backFromBurgerView() {
  const target = window._previousMainView || 'stock';
  navTo(target);
}

// Update sidebar profile label and sync state


function getShoppingItems() {
  return items.filter(item => {
    if (item._deletedAt) return false;
    const s = calcStock(item);
    if (!s) return false;
    if (s.daysLeft > shoppingDays) return false;
    // Store filter
    if (!shoppingStores.has('__all__')) {
      const itemStore = item.store && item.store.trim();
      if (!itemStore || !shoppingStores.has(itemStore)) return false;
    }
    // Tag filter
    if (shoppingTagFilter !== null) {
      if (!(item.tags || []).includes(shoppingTagFilter)) return false;
    }
    return true;
  }).map(item => {
    const s = calcStock(item);
    return { item, daysLeft: s.daysLeft, pct: s.pct };
  }).sort((a, b) => a.daysLeft - b.daysLeft);
}

function getAllStoresFromItems() {
  const storeSet = new Set();
  items.forEach(item => {
    if (item.store && item.store.trim()) storeSet.add(item.store.trim());
    (item.logs||[]).forEach(l => { if (l.store && l.store.trim()) storeSet.add(l.store.trim()); });
  });
  return [...storeSet].sort();
}

function openStorePickerModal() {
  const stores = getAllStoresFromItems();
  const container = document.getElementById('store-picker-options');

  // Build item counts per store
  const countPerStore = {};
  stores.forEach(s => {
    countPerStore[s] = items.filter(item => {
      if (item._deletedAt) return false;
      const st = calcStock(item);
      return st && st.daysLeft <= shoppingDays && (
        (item.store && item.store.trim() === s) ||
        (item.logs||[]).some(l => l.store && l.store.trim() === s)
      );
    }).length;
  });

  // "All stores" row
  const allChecked = shoppingStores.has('__all__');
  let html = `<div class="store-picker-row" onclick="toggleStorePick('__all__',this)">
    <input type="checkbox" id="sp-all" ${allChecked?'checked':''} onclick="event.stopPropagation();toggleStorePick('__all__',this.closest('.store-picker-row'))">
    <label for="sp-all" onclick="event.preventDefault()">🌐 All Stores</label>
  </div>`;

  if (stores.length === 0) {
    html += `<p style="font-size:13px;color:var(--muted);padding:10px 0">No stores found. Add stores when logging purchases.</p>`;
  } else {
    html += stores.map(s => {
      const checked = shoppingStores.has('__all__') || shoppingStores.has(s);
      const id = 'sp-' + s.replace(/\s+/g,'_');
      const cnt = countPerStore[s] || 0;
      return `<div class="store-picker-row" onclick="toggleStorePick('${esc(s)}',this)">
        <input type="checkbox" id="${id}" ${checked?'checked':''} onclick="event.stopPropagation();toggleStorePick('${esc(s)}',this.closest('.store-picker-row'))">
        <label for="${id}" onclick="event.preventDefault()">${esc(s)}</label>
        <span class="store-item-count">${cnt} item${cnt!==1?'s':''} due</span>
      </div>`;
    }).join('');
  }

  container.innerHTML = html;

  openModal('store-picker-modal');
}

function toggleStorePick(store, row) {
  const cb = row.querySelector('input[type=checkbox]');
  if (store === '__all__') {
    shoppingStores = new Set(['__all__']);
    // uncheck all individual store boxes
    document.querySelectorAll('#store-picker-options input[type=checkbox]').forEach(c => {
      c.checked = c.id === 'sp-all';
    });
    if (cb) cb.checked = true;
  } else {
    // Deselect "all"
    shoppingStores.delete('__all__');
    const allCb = document.getElementById('sp-all');
    if (allCb) allCb.checked = false;

    if (cb) cb.checked = !cb.checked;
    if (cb && cb.checked) shoppingStores.add(store);
    else shoppingStores.delete(store);

    // If nothing selected, revert to all
    if (shoppingStores.size === 0) {
      shoppingStores.add('__all__');
      if (allCb) allCb.checked = true;
    }
  }
}


function setShoppingTagFilter(index, btn) {
  shoppingTagFilter = index;
  buildShoppingTagFilterBarInline();
  renderShoppingList();
}


function toggleShoppingDays() {
  shoppingDays = shoppingDays === 30 ? 7 : 30;
  document.getElementById('days-opt-30').classList.toggle('active', shoppingDays === 30);
  document.getElementById('days-opt-30').classList.toggle('faded', shoppingDays !== 30);
  document.getElementById('days-opt-7').classList.toggle('active', shoppingDays === 7);
  document.getElementById('days-opt-7').classList.toggle('faded', shoppingDays !== 7);
  renderShoppingList();
}

function applyShoppingList() {
  closeModal('store-picker-modal');
  showShoppingListInline();
}

function renderShoppingList() {
  buildShoppingTagFilterBarInline();
  const shoppingItems = getShoppingItems();
  const storeLabel = shoppingStores.has('__all__') ? 'All Stores' : [...shoppingStores].join(', ');
  const threshold = settings.threshold;

  document.getElementById('shopping-subtitle').textContent =
    `Items running out within ${shoppingDays} days · ${storeLabel}`;

  const pillsEl = document.getElementById('shopping-store-pills');
  const pillStores = shoppingStores.has('__all__') ? ['All Stores'] : [...shoppingStores];
  pillsEl.innerHTML = pillStores.map(s =>
    `<span style="font-size:12px;font-weight:600;padding:4px 12px;border-radius:99px;background:var(--surface2);border:1px solid var(--border);color:var(--text)">${esc(s)}</span>`
  ).join('');

  const container = document.getElementById('shopping-content');

  if (shoppingItems.length === 0) {
    container.innerHTML = getShoppingPresenceBar() + `<div class="shopping-empty">
      <div style="font-size:48px;margin-bottom:16px"><svg class="icon icon-xl" aria-hidden="true"><use href="#i-party-popper"></use></svg></div>
      <h3 style="font-size:18px;color:var(--text);margin-bottom:8px">You're all stocked up!</h3>
      <p style="font-size:14px;line-height:1.7">No items are running out within ${shoppingDays} days for the selected stores.</p>
      <button class="btn btn-ghost" style="margin-top:16px" onclick="openStorePickerModal()">Change filters</button>
    </div>`;
    return;
  }

  // Group by store
  const byStore = {};
  shoppingItems.forEach(({ item, daysLeft, pct }) => {
    const store = item.store || 'No store set';
    if (!byStore[store]) byStore[store] = [];
    byStore[store].push({ item, daysLeft, pct });
  });

  const q = encodeURIComponent;

  container.innerHTML = getShoppingPresenceBar() + Object.entries(byStore).map(([store, entries]) => {
    const itemsHTML = entries.map(({ item, daysLeft, pct }) => {
      const s = calcStock(item);
      const status = getStatus(s?.pct ?? null, threshold);
      const color = STATUS_COLOR[status];
      const fillColor = status === 'critical' ? '#e85050' : status === 'warn' ? '#e8a838' : '#4cbb8a';
      const urgencyColor = daysLeft <= 7 ? 'var(--danger)' : daysLeft <= 14 ? 'var(--warn)' : 'var(--muted)';
      const runOutDate = new Date(Date.now() + daysLeft * MS_PER_DAY)
        .toLocaleDateString('en-GB', { day:'numeric', month:'short' });

      // Buy now link
      const buyLink = item.url
        ? `<a class="sl-btn sl-btn-buy" href="${esc(item.url)}" target="_blank" rel="noopener">🛒 Buy now</a>`
        : '';

      // Store search links (first 2 only to keep compact)
      const altLinks = getStores(settings.country).slice(0,2).map(st =>
        `<a class="sl-btn sl-btn-search" href="${st.url(q(item.name))}" target="_blank" rel="noopener">🔍 ${st.name.replace(/^[^\s]+\s/,'')}</a>`
      ).join('');

      // Ordered / Delivered buttons
      const orderedBtn = !item.ordered
        ? `<button class="sl-btn sl-btn-order" onclick="markOrdered('${item.id}')">📦 Ordered?</button>`
        : `<button class="sl-btn sl-btn-unorder" onclick="unmarkOrdered('${item.id}')">↩ Unmark</button>`;
      const deliveredBtn = `<button class="sl-btn sl-btn-delivered" onclick="openDeliveredModal('${item.id}')">✓ Delivered</button>`;

      const orderedBadge = item.ordered
        ? `<span style="font-size:10px;font-weight:700;padding:1px 6px;border-radius:99px;background:rgba(91,141,238,0.15);border:1px solid rgba(91,141,238,0.3);color:#5b8dee;font-family:var(--mono);flex-shrink:0">📦 Ordered</span>`
        : '';

      return `<div class="sl-item${item.ordered?' sl-ordered':''}" id="si-${item.id}" style="border-left:3px solid ${color}">
        <div class="sl-item-top">
          <label style="display:flex;align-items:center;gap:8px;cursor:pointer;flex:1;min-width:0" onclick="toggleShoppingTick('${item.id}',this)">
            <span class="sl-tick-box" id="sl-tick-${item.id}" style="flex-shrink:0;width:20px;height:20px;border-radius:5px;border:2px solid var(--border);display:inline-flex;align-items:center;justify-content:center;transition:all .15s"></span>
            <span class="sl-item-name" id="sl-name-${item.id}">${esc(item.name)}</span>
          </label>
          ${orderedBadge}
          <span class="sl-days" style="color:${urgencyColor}">${daysLeft}d · ${runOutDate}</span>
        </div>
        <div class="sl-bar-wrap" id="sl-bar-${item.id}">
          <div class="sl-bar"><div class="sl-bar-fill" style="width:${pct??0}%;background:${fillColor}"></div></div>
          <span class="sl-pct" style="color:${color}">${pct ?? '?'}%</span>
        </div>
        <div class="sl-actions" id="sl-actions-${item.id}">
          ${buyLink}${altLinks}${orderedBtn}${deliveredBtn}
        </div>
      </div>`;
    }).join('');

    return `<div class="shopping-store-section">
      <div class="shopping-store-header">
        <h3><svg class="icon" aria-hidden="true"><use href="#i-store"></use></svg> ${esc(store)}</h3>
        <span class="shopping-store-count">${entries.length} item${entries.length!==1?'s':''}</span>
      </div>
      ${itemsHTML}
    </div>`;
  }).join('');
}

function toggleShoppingCheck(itemId, cb) {
  const el = document.getElementById('si-' + itemId);
  if (el) el.classList.toggle('checked', cb.checked);
}

function exportShoppingList() {
  const shoppingItems = getShoppingItems();
  if (!shoppingItems.length) { toast('Nothing to export'); return; }

  const lines = ['STOCKROOM — Shopping List', `Generated: ${new Date().toLocaleDateString('en-GB')}`, `Stores: ${shoppingStores.has('__all__')?'All':[...shoppingStores].join(', ')}`, `Window: Next ${shoppingDays} days`, '', '---', ''];

  const byStore = {};
  shoppingItems.forEach(({item, daysLeft}) => {
    const store = item.store || 'No store set';
    if (!byStore[store]) byStore[store] = [];
    byStore[store].push({item, daysLeft});
  });

  Object.entries(byStore).forEach(([store, entries]) => {
    lines.push(`## ${store}`);
    entries.forEach(({item, daysLeft}) => {
      const runOut = new Date(Date.now() + daysLeft * MS_PER_DAY).toLocaleDateString('en-GB');
      lines.push(`[ ] ${item.name}`);
      lines.push(`    Runs out: ${runOut} (${daysLeft}d)`);
      if (item.url) lines.push(`    Buy: ${item.url}`);
      if (item.rating) lines.push(`    Rating: ${'★'.repeat(item.rating)}${'☆'.repeat(5-item.rating)}`);
      lines.push('');
    });
    lines.push('');
  });

  const blob = new Blob([lines.join('\n')], {type:'text/plain'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `shopping_list_${new Date().toISOString().split('T')[0]}.txt`;
  a.click();
}



// ═══════════════════════════════════════════════════════════════
//  ADD ITEM WIZARD
// ═══════════════════════════════════════════════════════════════
let _wizStep = 1;
let _wizRating = 0;
let _wizImageUrl = null;
let _wizReminders = []; // [{id, name, interval, unit}]

function openAddModal() {
  // Free-tier add-item gate — block if already at the visible cap.
  // The server can't enforce this because items live inside the encrypted
  // blob, so the client is the gatekeeper. Server's blob-size cap kicks
  // in if a determined user bypasses this somehow.
  try {
    if (window.stockroomBilling && stockroomBilling.isFree() && !stockroomBilling.featureAllowed('addItem')) {
      const status = stockroomBilling.getStatus();
      const cap = status?.limits?.itemCount ?? 5;
      if (typeof toastAction === 'function') {
        toastAction(`Free plan: ${cap}-item limit reached`, { label: 'Upgrade', onClick: () => navTo('billing') });
      } else {
        toast(`Free plan: ${cap}-item limit reached — open Billing to upgrade`);
      }
      return;
    }
  } catch (_) {}
  _wizStep = 1;
  _wizRating = 0;
  _wizImageUrl = null;
  _wizReminders = [];
  // Reset all fields
  const reset = { 'wiz-name':'', 'wiz-category':'Kitchen', 'wiz-cadence':'monthly',
    'wiz-unit-type':'item', 'wiz-qty':1, 'wiz-months':1, 'wiz-url':'', 'wiz-store':'', 'wiz-notes':'',
    'wiz-last-date':today(), 'wiz-last-qty':1, 'wiz-last-price':'', 'wiz-started-using':'',
    'wiz-price-search':'' };
  Object.entries(reset).forEach(([id, v]) => { const el = document.getElementById(id); if (el) el.value = v; });
  if (typeof applyWizUnitTypeToQtyInput === 'function') applyWizUnitTypeToQtyInput();
  const storeEl = document.getElementById('wiz-store');
  if (storeEl) { storeEl.dataset.manual = ''; storeEl.dataset.autoFilled = ''; }
  // Reset awaiting-delivery checkbox + ensure started-using row visible
  const awaitingCb = document.getElementById('wiz-awaiting-delivery');
  if (awaitingCb) awaitingCb.checked = false;
  const susField = document.getElementById('wiz-started-using-field');
  const susHint  = document.getElementById('wiz-started-using-hint');
  if (susField) susField.style.display = '';
  if (susHint)  susHint.style.display  = '';
  wizSetRating(0);
  wizClearImage();
  document.getElementById('wiz-price-links').innerHTML = '';
  document.getElementById('wiz-reminders-list').innerHTML = '';
  _wizGotoStep(1);
  openModal('add-item-wizard-modal');
}

// Toggle the "Started using" row based on awaiting-delivery checkbox.
// When awaiting delivery, we don't ask for a started-using date — the item
// hasn't arrived yet, so it's added to pending deliveries instead.
function wizToggleAwaitingDelivery() {
  const checked  = document.getElementById('wiz-awaiting-delivery').checked;
  const susField = document.getElementById('wiz-started-using-field');
  const susHint  = document.getElementById('wiz-started-using-hint');
  if (susField) susField.style.display = checked ? 'none' : '';
  if (susHint)  susHint.style.display  = checked ? 'none' : '';
  // Clear started-using value when ticking, so it can't sneak through to save
  if (checked) {
    const su = document.getElementById('wiz-started-using');
    if (su) su.value = '';
  }
}

function _wizGotoStep(n) {
  _wizStep = n;
  [1,2,3,4].forEach(i => {
    const s = document.getElementById('wiz-step-' + i);
    if (s) s.style.display = i === n ? 'block' : 'none';
    const p = document.getElementById('wprog-' + i);
    if (p) { p.classList.toggle('active', i === n); p.classList.toggle('done', i < n); }
  });
  document.getElementById('wizard-step-label').textContent = `Step ${n} of 4`;
  toggle('wiz-back-btn', n > 1, 'inline-flex');
  const nextBtn = document.getElementById('wiz-next-btn');
  const skipBtn = document.getElementById('wiz-skip-btn');
  if (n === 4) {
    nextBtn.textContent = 'Add Item ✓';
    nextBtn.onclick = wizSave;
    skipBtn.style.display = 'none';
    _wizRenderTimeline();
  } else {
    nextBtn.textContent = 'Next →';
    nextBtn.onclick = wizNext;
    skipBtn.style.display = n === 2 || n === 3 ? 'inline-flex' : 'none';
  }
}

function wizNext() {
  if (_wizStep === 1) {
    const name = document.getElementById('wiz-name').value.trim();
    if (!name) { document.getElementById('wiz-name').focus(); toast('Please enter a name for this item'); return; }
  }
  if (_wizStep < 4) _wizGotoStep(_wizStep + 1);
}
function wizBack() { if (_wizStep > 1) _wizGotoStep(_wizStep - 1); }
function wizSkip() { if (_wizStep < 4) _wizGotoStep(_wizStep + 1); }

function wizAutoFillStore() {
  const urlEl = document.getElementById('wiz-url');
  const storeEl = document.getElementById('wiz-store');
  if (!urlEl || !storeEl) return;
  if (storeEl.dataset.manual) return;
  const s = urlToStoreName(urlEl.value);
  if (s) { storeEl.value = s; storeEl.dataset.autoFilled = '1'; }
}

function wizSetRating(n) {
  _wizRating = n;
  const stars = document.querySelectorAll('#wiz-star-rating .star');
  const label = document.getElementById('wiz-rating-label');
  stars.forEach((s, i) => s.classList.toggle('active', i < n));
  if (label) label.textContent = n ? (RATING_LABELS?.[n] || `${n} star${n>1?'s':''}`) : 'Not rated';
}
function wizPreviewStars(n) { document.querySelectorAll('#wiz-star-rating .star').forEach((s,i) => s.classList.toggle('active', i < n)); }
function wizResetStars() { wizSetRating(_wizRating); }
function wizUpdatePriceLinks() {
  const q = document.getElementById('wiz-price-search').value.trim();
  const container = document.getElementById('wiz-price-links');
  if (!container) return;
  if (typeof buildPriceLinks === 'function') container.innerHTML = buildPriceLinks(q);
  else if (typeof updatePriceLinks === 'function') updatePriceLinks('wiz-price-search', 'wiz-price-links');
}
async function wizFetchProductImage() {
  const name = document.getElementById('wiz-name').value.trim() || document.getElementById('wiz-price-search').value.trim();
  if (!name) { toast('Enter an item name first'); return; }
  if (typeof fetchProductImage !== 'function') return;
  // Delegate to existing function but redirect to wiz preview
  const btn = document.querySelector('#add-item-wizard-modal button[onclick="wizFetchProductImage()"]');
  if (btn) btn.disabled = true;
  try {
    const url = await _fetchProductImageUrl(name);
    if (url) { _wizImageUrl = url; wizShowImage(url); }
    else toast('No image found');
  } catch(e) { toast('Image search failed'); }
  if (btn) btn.disabled = false;
}
function wizShowImage(url) {
  const wrap = document.getElementById('wiz-img-preview-wrap');
  const img = document.getElementById('wiz-img-preview');
  if (wrap && img) { img.src = url; wrap.style.display = 'flex'; }
}
function wizClearImage() {
  _wizImageUrl = null;
  const wrap = document.getElementById('wiz-img-preview-wrap');
  if (wrap) wrap.style.display = 'none';
}

// ── Wizard step 3: reminders ──────────────────────────────
function wizAddReminder() {
  _wizReminders.push({ id: uid(), name: '', interval: 3, unit: 'months' });
  _wizRenderReminders();
}
function _wizRenderReminders() {
  const list = document.getElementById('wiz-reminders-list');
  if (!list) return;
  list.innerHTML = _wizReminders.map((r, i) => `
    <div class="repl-reminder-row" id="wizrem-${r.id}">
      <div style="flex:1;display:flex;flex-direction:column;gap:6px">
        <input type="text" placeholder="Name (e.g. Pete, Main filter)" value="${esc(r.name)}"
          style="width:100%" oninput="_wizReminders[${i}].name=this.value">
        <div style="display:flex;gap:6px;align-items:center">
          <span style="font-size:12px;color:var(--muted);white-space:nowrap">Replace every</span>
          <input type="number" min="1" max="365" value="${r.interval}" style="width:60px"
            oninput="_wizReminders[${i}].interval=parseInt(this.value)||1">
          <select style="flex:1" onchange="_wizReminders[${i}].unit=this.value">
            <option value="days" ${r.unit==='days'?'selected':''}>days</option>
            <option value="weeks" ${r.unit==='weeks'?'selected':''}>weeks</option>
            <option value="months" ${r.unit==='months'?'selected':''}>months</option>
          </select>
        </div>
      </div>
      <button onclick="_wizReminders.splice(${i},1);_wizRenderReminders()" style="background:none;border:none;cursor:pointer;color:var(--danger);padding:4px" title="Remove">
        <svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg>
      </button>
    </div>`).join('');
}

// ── Wizard step 4: timeline ────────────────────────────────
function _wizRenderTimeline() {
  const content = document.getElementById('wiz-timeline-content');
  if (!content) return;
  const name    = document.getElementById('wiz-name').value.trim() || 'This item';
  const months  = parseFloat(document.getElementById('wiz-months').value) || 1;
  const wizQty  = parseFloat(document.getElementById('wiz-qty').value) || 1;
  const lastQty = parseFloat(document.getElementById('wiz-last-qty').value) || 1;
  const awaitingDelivery = !!document.getElementById('wiz-awaiting-delivery')?.checked;
  const refDate = document.getElementById('wiz-started-using').value
               || document.getElementById('wiz-last-date').value
               || today();
  // New model: months = lifetime of a full pack (wiz-qty units),
  // so days-per-unit = months × AVG_DAYS_PER_MONTH / wiz-qty, and total days for the most-
  // recent purchase = days-per-unit × lastQty.
  const dpu        = (months * AVG_DAYS_PER_MONTH) / Math.max(0.0001, wizQty);
  const totalDays  = Math.round(dpu * lastQty);
  const ref     = new Date(refDate + 'T12:00:00');
  const runOut  = new Date(ref.getTime() + totalDays * MS_PER_DAY);
  const threshold = settings.threshold || 20;
  const warnDays  = Math.round(totalDays * threshold / 100);
  const warnDate  = new Date(runOut.getTime() - warnDays * MS_PER_DAY);
  const fmtD = d => d.toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' });
  const daysDiff = d => Math.round((d - Date.now()) / MS_PER_DAY);
  const relLabel = d => { const diff = daysDiff(d); return diff < 0 ? `${Math.abs(diff)}d ago` : diff === 0 ? 'today' : `in ${diff}d`; };

  const events = awaitingDelivery
    ? [
        // No "started using" yet — show the order date as the anchor
        { label: 'Ordered (awaiting delivery)', date: ref, color: 'var(--accent)', icon: 'i-truck' },
      ]
    : [
        { label: 'Started using', date: ref, color: '#5b8dee', icon: 'i-play' },
        { label: `${threshold}% warning threshold (order reminder)`, date: warnDate, color: 'var(--warn)', icon: 'i-bell' },
        { label: 'Estimated run-out', date: runOut, color: 'var(--danger)', icon: 'i-alert-triangle' },
      ];

  // Add replacement reminders to timeline (only meaningful once delivered/started)
  if (!awaitingDelivery) {
    _wizReminders.forEach(r => {
      const days = r.unit==='days' ? r.interval : r.unit==='weeks' ? r.interval*7 : r.interval*AVG_DAYS_PER_MONTH;
      const replDate = new Date(ref.getTime() + Math.round(days)*MS_PER_DAY);
      events.push({ label: `Replace${r.name ? ` (${r.name})` : ''}`, date: replDate, color:'var(--ok)', icon:'i-repeat' });
    });
  }

  events.sort((a,b) => a.date - b.date);

  const statsRow = awaitingDelivery
    ? `<div style="background:rgba(232,168,56,0.1);border:1px solid rgba(232,168,56,0.25);border-radius:10px;padding:12px 14px;font-size:13px;color:var(--text);line-height:1.5">
         <strong>Will be added to Pending Deliveries.</strong><br>
         <span style="color:var(--muted);font-size:12px">When it arrives, tap <em>Delivered</em> on the card to add it to stock and set when you start using it.</span>
       </div>`
    : `<div style="display:flex;gap:16px;flex-wrap:wrap">
        <div style="flex:1;min-width:100px;background:var(--surface2);border-radius:10px;padding:12px;text-align:center">
          <div style="font-size:24px;font-weight:800;color:var(--text)">${totalDays}d</div>
          <div style="font-size:11px;color:var(--muted)">Total supply</div>
        </div>
        <div style="flex:1;min-width:100px;background:var(--surface2);border-radius:10px;padding:12px;text-align:center">
          <div style="font-size:24px;font-weight:800;color:var(--warn)">${warnDays}d</div>
          <div style="font-size:11px;color:var(--muted)">Warning at</div>
        </div>
        <div style="flex:1;min-width:100px;background:var(--surface2);border-radius:10px;padding:12px;text-align:center">
          <div style="font-size:24px;font-weight:800;color:var(--accent)">${Math.max(0,daysDiff(runOut))}d</div>
          <div style="font-size:11px;color:var(--muted)">Days left</div>
        </div>
      </div>`;

  content.innerHTML = `
    <div style="background:var(--surface2);border:1px solid var(--border);border-radius:12px;padding:16px;margin-bottom:16px">
      <div style="font-size:13px;font-weight:700;color:var(--text);margin-bottom:12px">${esc(name)}</div>
      <div style="display:flex;flex-direction:column;gap:10px">
        ${events.map(ev => `
          <div style="display:flex;align-items:center;gap:10px">
            <div style="width:32px;height:32px;border-radius:50%;background:${ev.color}22;border:1px solid ${ev.color}55;display:flex;align-items:center;justify-content:center;flex-shrink:0">
              <svg class="icon" aria-hidden="true" style="color:${ev.color};width:14px;height:14px"><use href="#${ev.icon}"></use></svg>
            </div>
            <div style="flex:1;min-width:0">
              <div style="font-size:12px;color:var(--muted)">${ev.label}</div>
              <div style="font-size:13px;font-weight:700;color:var(--text)">${fmtD(ev.date)} <span style="font-weight:400;color:var(--muted);font-size:12px">${relLabel(ev.date)}</span></div>
            </div>
          </div>`).join('')}
      </div>
    </div>
    ${statsRow}`;
}

async function wizSave() {
  if (!canWrite('stockroom')) { showLockBanner('stockroom'); return; }
  const name = document.getElementById('wiz-name').value.trim();
  if (!name) { _wizGotoStep(1); document.getElementById('wiz-name').focus(); toast('Please enter an item name'); return; }
  const storeVal = document.getElementById('wiz-store').value.trim()
    || urlToStoreName(document.getElementById('wiz-url').value.trim());
  const lastDate  = document.getElementById('wiz-last-date').value;
  const lastQty   = parseFloat(document.getElementById('wiz-last-qty').value) || 1;
  const lastPrice = document.getElementById('wiz-last-price').value.trim();
  const awaitingDelivery = !!document.getElementById('wiz-awaiting-delivery')?.checked;
  // When awaiting delivery, never set startedUsing — item hasn't arrived yet
  const startedUsing = awaitingDelivery
    ? null
    : (document.getElementById('wiz-started-using').value || null);

  // Build the log entry. If awaiting delivery, mark it pending so it shows
  // up in the Pending Deliveries section and the multifunction button starts
  // at "Delivered". Otherwise, log as a normal already-delivered purchase.
  const logEntry = lastDate
    ? (awaitingDelivery
        ? { id: uid(), date: lastDate, qty: lastQty, price: lastPrice, store: storeVal, pendingDelivery: true }
        : { id: uid(), date: lastDate, qty: lastQty, price: lastPrice, store: storeVal, pendingDelivery: false, deliveredDate: lastDate })
    : null;

  const wizQty    = parseFloat(document.getElementById('wiz-qty').value) || 1;
  const wizMonths = parseFloat(document.getElementById('wiz-months').value) || 1;
  // Compute canonical per-unit lifetime: months entered = whole-purchase supply,
  // so per-unit lifetime = months × AVG_DAYS_PER_MONTH / qty. (e.g. 24 cans, 1 month → 1.27 d/can)
  const daysPerUnit = (wizMonths * AVG_DAYS_PER_MONTH) / Math.max(0.0001, wizQty);

  const newItem = {
    id:                   uid(),
    name,
    category:             document.getElementById('wiz-category').value,
    cadence:              document.getElementById('wiz-cadence').value,
    qty:                  wizQty,
    months:               wizMonths,
    unitType:             document.getElementById('wiz-unit-type')?.value || 'item',
    daysPerUnit,
    url:                  document.getElementById('wiz-url').value.trim(),
    store:                storeVal,
    notes:                document.getElementById('wiz-notes').value.trim(),
    startedUsing,
    rating:               _wizRating || null,
    imageUrl:             _wizImageUrl || null,
    storePrices:          [],
    replacementReminders: _wizReminders.filter(r => r.interval > 0).map(r => ({ ...r, lastReplaced: startedUsing || (awaitingDelivery ? null : lastDate) || null })),
    logs:                 logEntry ? [logEntry] : [],
    updatedAt:            new Date().toISOString(),
  };
  // If awaiting delivery, mark item as ordered so it appears in pending
  // deliveries and the order button reflects the correct stage.
  if (awaitingDelivery && logEntry) {
    newItem.ordered   = true;
    newItem.orderedAt = new Date().toISOString();
  }
  // Backwards compat: copy first reminder to replacementInterval/Unit
  if (newItem.replacementReminders?.length) {
    newItem.replacementInterval = newItem.replacementReminders[0].interval;
    newItem.replacementUnit     = newItem.replacementReminders[0].unit;
  }
  items.push(newItem);
  await saveData();
  closeModal('add-item-wizard-modal');
  scheduleRender('grid', 'dashboard', 'filters', 'shopping', 'sns');
  toast(awaitingDelivery
    ? `"${name}" added — awaiting delivery ✓`
    : `"${name}" added ✓`);
  _syncQueue.enqueue('Saving item…');
}



function openEditModal(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;
  editingId = id;
  document.getElementById('item-modal-title').textContent = 'Item Details';
  document.getElementById('item-modal-subtitle').textContent = item.name;

  // Populate readonly summary
  document.getElementById('ro-category').textContent = item.category || 'Other';
  document.getElementById('ro-name').textContent = item.name;
  const metaParts = [];
  if (item.cadence === 'bulk') metaParts.push('Bulk');
  else metaParts.push('Monthly');
  if (item.qty) metaParts.push(`${item.qty} ${unitLabel(item, item.qty)} per purchase`);
  if (item.months) metaParts.push(`${item.months} month${item.months !== 1 ? 's' : ''} supply`);
  const lastLog = (item.logs || []).filter(l => !l.pendingDelivery).at(-1);
  if (lastLog?.price) metaParts.push(`Last price: ${lastLog.price}`);
  document.getElementById('ro-meta').textContent = metaParts.join(' · ');
  document.getElementById('ro-store').innerHTML = item.store
    ? `<svg class="icon" aria-hidden="true"><use href="#i-store"></use></svg> ${esc(item.store)}` : '';

  // ── Order history ──
  _renderEditOrderHistory(item);

  // ── Stock summary ──
  _renderEditStockSummary(item);

  // ── Replacement reminders ──
  _renderEditReminders(item);

  // ── Sharing (Part B Rounds 2 + 3) ──
  // Uses the generic sharing-panel module. The 'item' section was
  // registered in the _SHARING_SECTIONS literal — see near
  // openSharingPanelFor. openSharingPanelFor resets expanded state
  // and renders for the currently-edited item.
  openSharingPanelFor('item');

  // Show readonly, hide edit form
  show('item-readonly-view', 'block');
  hide('item-edit-view');

  // Pre-populate edit form fields
  tempStorePrices = JSON.parse(JSON.stringify(item.storePrices || []));
  if (typeof renderTempStorePrices === 'function') renderTempStorePrices();
  if (tempStorePrices.length) show('store-prices-section', 'block');
  document.getElementById('f-name').value = item.name;
  document.getElementById('f-category').value = item.category || 'Kitchen';
  document.getElementById('f-cadence').value = item.cadence || 'monthly';
  document.getElementById('f-qty').value = item.qty || 1;
  document.getElementById('f-months').value = item.months || 1;
  const utSel = document.getElementById('f-unit-type');
  if (utSel) utSel.value = getUnitType(item);
  if (typeof applyUnitTypeToQtyInput === 'function') applyUnitTypeToQtyInput();
  document.getElementById('f-url').value = item.url || '';
  pendingImageUrl = item.imageUrl || null;
  showModalImagePreview(item.imageUrl || null);
  const storeField = document.getElementById('f-store');
  storeField.value = item.store || urlToStoreName(item.url || '');
  storeField.dataset.manual = item.store ? '1' : '';
  storeField.dataset.autoFilled = '';
  document.getElementById('f-notes').value = item.notes || '';
  const expiryEl    = document.getElementById('f-expiry');
  const thresholdEl = document.getElementById('f-threshold');
  if (expiryEl)    expiryEl.value    = item.expiry || '';
  if (thresholdEl) thresholdEl.value = item.thresholdOverride != null ? item.thresholdOverride : '';
  // Legacy compat fields (hidden inputs)
  const last = (item.logs || []).filter(l => !l.pendingDelivery).at(-1);
  const flDate = document.getElementById('f-last-date'); if (flDate) flDate.value = last?.date || today();
  const flQty  = document.getElementById('f-last-qty');  if (flQty)  flQty.value  = last?.qty  || 1;
  const flPrice= document.getElementById('f-last-price');if (flPrice) flPrice.value= last?.price|| '';
  const flSU   = document.getElementById('f-started-using'); if (flSU) flSU.value = item.startedUsing || '';
  const flRI   = document.getElementById('f-replace-interval'); if (flRI) flRI.value = item.replacementInterval || '';
  const flRU   = document.getElementById('f-replace-unit'); if (flRU) flRU.value = item.replacementUnit || 'months';
  currentRating = item.rating || 0;
  renderStars();
  document.getElementById('price-search-input').value = item.name;
  updatePriceLinks();
  openModal('item-modal');
}

function _renderEditOrderHistory(item) {
  const logs = (item.logs || []).slice().reverse().slice(0, 5); // latest 5
  const container = document.getElementById('ro-order-history');
  if (!container) return;

  if (!logs.length) {
    container.innerHTML = `<p style="font-size:13px;color:var(--muted)">No orders yet.</p>`;
  } else {
    container.innerHTML = logs.map(l => {
      const stage = !l.pendingDelivery && l.deliveredDate && item.startedUsing ? 'using'
                  : !l.pendingDelivery && l.deliveredDate ? 'delivered'
                  : 'pending';
      const stageLabel = stage === 'using' ? 'In use' : stage === 'delivered' ? 'Delivered' : 'Ordered';
      const dateStr = l.deliveredDate || l.date;
      return `<div class="order-history-row">
        <span class="order-stage-badge ${stage}">${stageLabel}</span>
        <span style="flex:1;color:var(--muted);font-size:12px">${l.date ? fmt(l.date) : ''}${l.price ? ` · ${esc(l.price)}` : ''}${l.qty && l.qty !== 1 ? ` · ×${l.qty}` : ''}</span>
      </div>`;
    }).join('');
  }

  // Smart order button
  const btn = document.getElementById('ro-order-btn');
  if (!btn) return;
  const hasPending = (item.logs || []).some(l => l.pendingDelivery);
  const hasDelivered = (item.logs || []).some(l => !l.pendingDelivery && l.deliveredDate && !item.startedUsing);
  if (hasPending) {
    btn.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-package-check"></use></svg> Mark as Delivered';
    btn.onclick = () => { closeModal('item-modal'); openOrderFlow(item.id, 'delivered'); };
    btn.style.background = 'rgba(76,187,138,0.12)'; btn.style.color = 'var(--ok)'; btn.style.borderColor = 'rgba(76,187,138,0.3)';
  } else if (hasDelivered) {
    btn.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-play"></use></svg> Set Start Using Date';
    btn.onclick = () => { closeModal('item-modal'); openOrderFlow(item.id, 'startusing'); };
    btn.style.background = 'rgba(91,141,238,0.12)'; btn.style.color = '#5b8dee'; btn.style.borderColor = 'rgba(91,141,238,0.3)';
  } else {
    btn.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-clipboard-list"></use></svg> Log Purchase';
    btn.onclick = () => { closeModal('item-modal'); openOrderFlow(item.id, 'purchase'); };
    btn.style.background = ''; btn.style.color = ''; btn.style.borderColor = '';
  }
}

function _renderEditStockSummary(item) {
  const container = document.getElementById('ro-stock-summary');
  if (!container) return;
  const s = calcStock(item);
  const dpu = getDaysPerUnit(item);
  const projected = getProjectedUnitsLeft(item);
  const lastLog = (item.logs || []).filter(l => !l.pendingDelivery).at(-1);

  // Per-unit lifetime in human form
  let perUnitLabel;
  if (dpu < 7)        perUnitLabel = `~${dpu.toFixed(1)} days/unit`;
  else if (dpu < 60)  perUnitLabel = `~${Math.round(dpu)} days/unit`;
  else if (dpu < 365) perUnitLabel = `~${(dpu / AVG_DAYS_PER_MONTH).toFixed(1)} months/unit`;
  else                perUnitLabel = `~${(dpu / 365).toFixed(1)} years/unit`;

  let lines = [];
  if (item.stockCount != null && item.stockCountDate) {
    const projStr = formatProjectedUnits(projected);
    const exact   = item.stockCount % 1 === 0 ? item.stockCount : item.stockCount.toFixed(1);
    // Show projected count prominently; mention the underlying count + when
    const sameAsCount = projected != null && Math.abs(projected - item.stockCount) < 0.05;
    if (sameAsCount) {
      lines.push(`<strong style="color:var(--text)">${exact} unit${item.stockCount !== 1 ? 's' : ''} in stock</strong> (counted ${timeAgo(item.stockCountDate)})`);
    } else {
      lines.push(`<strong style="color:var(--text)">${projStr} units left</strong> <span style="color:var(--muted)">(projected — was ${exact} ${timeAgo(item.stockCountDate)})</span>`);
    }
    if (s) {
      const f = formatDaysLeft(s.daysLeft);
      lines.push(`Runs out: ${f.num} ${f.unit}${f.suspect ? ' — looks unusually long, recount?' : ''}`);
    }
    lines.push(perUnitLabel);
  } else if (lastLog) {
    lines.push(`Time-based estimate from last purchase (${timeAgo(lastLog.date)})`);
    if (s) {
      const f = formatDaysLeft(s.daysLeft);
      lines.push(`<strong style="color:var(--text)">${f.num} ${f.unit}</strong>${f.suspect ? ' <span style="color:var(--warn)">⚠ unusually long — recount?</span>' : ''}`);
    }
    lines.push(perUnitLabel);
    lines.push(`<em style="color:var(--muted)">Tap "Count Stock" mid-pack to switch to learned-rate projections.</em>`);
  } else {
    lines.push(`<em>No purchases logged yet.</em>`);
    lines.push(perUnitLabel);
  }
  container.innerHTML = lines.join('<br>');
}

function _renderEditReminders(item) {
  const container = document.getElementById('ro-reminders-list');
  if (!container) return;
  const reminders = _getItemReminders(item);
  if (!reminders.length) {
    container.innerHTML = `<p style="font-size:13px;color:var(--muted)">No replacement reminders set.</p>`;
  } else {
    container.innerHTML = reminders.map(r => `
      <div class="order-history-row">
        <svg class="icon" aria-hidden="true" style="color:var(--ok)"><use href="#i-bell"></use></svg>
        <span style="flex:1;font-size:12px;color:var(--text)">${r.name ? esc(r.name) + ' — ' : ''}Every ${r.interval} ${r.unit}</span>
        ${r.lastReplaced ? `<span style="font-size:11px;color:var(--muted)">Last: ${fmt(r.lastReplaced)}</span>` : ''}
      </div>`).join('');
  }
}

// Get replacement reminders from item — always returns from the array (migrating legacy first)
function _getItemReminders(item) {
  const hadLegacy = !item.replacementReminders?.length && !!item.replacementInterval;
  _ensureReplRemindersArray(item);
  if (hadLegacy && item.replacementReminders?.length) {
    // Persist the migration so IDs are stable across page loads
    saveData().catch(() => {});
  }
  return item.replacementReminders || [];
}

// ─── Per-record sharing panel (Part B, Rounds 2 + 3) ──────────────────────
// One generic panel module powers per-record sharing overrides across all
// sections: stockroom items (Round 2), grocery lists + reminders + budget
// transactions (Round 3). Each section registers its specifics in
// _SHARING_SECTIONS — record source array, DOM mount IDs, save function,
// current-record-id getter — and reuses the same picker UI + interaction
// helpers below.
//
// State is held on the record itself via `record.share`. Editing the
// picker mutates the field in place and calls the section's save +
// _rePushAllShares() for fast guest-side propagation.
//
// _sharingExpanded and _SHARING_SECTIONS are declared near the top of
// the file (near editingId) so the various registerSharingSection() calls
// scattered through this file don't trip the const TDZ. See the comment
// near those declarations for why.

// Section registry contract. Each entry tells the panel HOW to find /
// save / re-render records for that section. Keep keys short — they
// appear in onclick attribute strings throughout the picker UI.
//
//   findRecord(id)   — return the record object (or null)
//   currentId()      — return the id of the record currently being edited
//                      for this section (e.g. editingId for items)
//   save()           — async, persist the changed record (saveData,
//                      _saveGroceryLists, etc.)
//   mountSectionEl() — outer wrapper element to show/hide
//   mountContentEl() — inner element that receives the rendered HTML
//   noun             — singular noun for tooltips ("item", "list", etc.)

// Public API for sections to register themselves. Each section's editor
// code calls this to register its own spec — lets section-specific code
// live near its editor without coming back here to edit a central
// registry. Section keys must be unique.
function registerSharingSection(key, spec) {
  if (_SHARING_SECTIONS[key]) {
    console.warn('[sharing] section already registered, overwriting:', key);
  }
  _SHARING_SECTIONS[key] = spec;
}

// Register the item section here as the first user of the API. Other
// sections (groceryList, reminder, transaction) register themselves
// alongside their own editor code.
registerSharingSection('item', {
  findRecord:    (id) => items.find(i => i.id === id),
  currentId:     ()   => editingId,
  save:          ()   => saveData(),
  mountSectionEl: () => document.getElementById('ro-sharing-section'),
  mountContentEl: () => document.getElementById('ro-sharing-content'),
  noun:          'item',
});

// Called by each section's editor when it opens. Resets expanded state
// and renders the panel for the currently-edited record.
function openSharingPanelFor(sectionKey) {
  _sharingExpanded[sectionKey] = false;
  const spec = _SHARING_SECTIONS[sectionKey];
  if (!spec) return;
  const rec = spec.findRecord(spec.currentId());
  _renderSharingPanel(sectionKey, rec);
}

function _renderSharingPanel(sectionKey, record) {
  const spec = _SHARING_SECTIONS[sectionKey];
  if (!spec) return;
  const sectionEl = spec.mountSectionEl();
  const contentEl = spec.mountContentEl();
  if (!sectionEl || !contentEl) return;

  // Guests never see this panel — sharing policy is owner-only.
  if (!isOwner()) { sectionEl.style.display = 'none'; return; }

  // No record (shouldn't happen, but guard) — hide cleanly.
  if (!record) { sectionEl.style.display = 'none'; return; }

  // No shares configured anywhere → panel is useless, show a one-liner.
  if (!Array.isArray(_shareTargets) || !_shareTargets.length) {
    sectionEl.style.display = 'block';
    contentEl.innerHTML = `<p style="font-size:12px;color:var(--muted);font-style:italic">No shares configured. Set up household sharing first to use per-${esc(spec.noun)} overrides.</p>`;
    return;
  }

  sectionEl.style.display = 'block';
  if (!_sharingExpanded[sectionKey]) {
    contentEl.innerHTML = _renderSharingSummary(sectionKey, record);
  } else {
    contentEl.innerHTML = _renderSharingPicker(sectionKey, record);
  }
}

// One-line summary of the current state. Visible in the collapsed view.
function _renderSharingSummary(sectionKey, record) {
  const spec = _SHARING_SECTIONS[sectionKey];
  const defaultBehavior = spec?.defaultBehavior || 'inherit';
  const share = record.share;
  let label, icon;
  if (share == null) {
    // Section default. For most sections (items, groceries, etc.) the
    // absent-field case means "inherit section perm". For notes (and
    // potentially future sections without a section perm), it means
    // "private — owner only", since there's nothing to inherit FROM.
    if (defaultBehavior === 'private') {
      label = `Private — owner only`;
      icon  = 'i-eye-off';
    } else {
      label = `Inherits from household — visible to ${_shareTargets.length} share${_shareTargets.length===1?'':'s'} per section perms`;
      icon  = 'i-share-2';
    }
  } else if (share === 'private') {
    label = `Private — owner only`;
    icon  = 'i-eye-off';
  } else if (typeof share === 'object') {
    const parts = [];
    if (Array.isArray(share.allow))    parts.push(`${share.allow.length} allowed`);
    if (Array.isArray(share.deny))     parts.push(`${share.deny.length} denied`);
    if (Array.isArray(share.readOnly)) parts.push(`${share.readOnly.length} read-only`);
    label = `Overridden — ${parts.join(' · ') || 'no entries set'}`;
    icon  = 'i-shield';
  } else {
    label = `Malformed override (${typeof share}) — review`;
    icon  = 'i-alert-triangle';
  }

  // Reset button is meaningful only when there's a non-null share field.
  // For notes (defaultBehavior=private), Reset just clears to the same
  // private state — still valid as a "discard overrides" action.
  const action = (share != null)
    ? `<button class="btn btn-ghost btn-sm" onclick="_clearSharing('${sectionKey}')" style="margin-right:6px"><svg class="icon" aria-hidden="true"><use href="#i-rotate-ccw"></use></svg> Reset</button>
       <button class="btn btn-ghost btn-sm" onclick="_expandSharing('${sectionKey}')"><svg class="icon" aria-hidden="true"><use href="#i-pencil"></use></svg> Edit</button>`
    : `<button class="btn btn-ghost btn-sm" onclick="_expandSharing('${sectionKey}')"><svg class="icon" aria-hidden="true"><use href="#i-shield"></use></svg> ${defaultBehavior === 'private' ? 'Share with someone' : 'Override sharing'}</button>`;

  return `<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:var(--surface2);border-radius:8px">
    <svg class="icon" aria-hidden="true" style="color:var(--muted);flex-shrink:0"><use href="#${icon}"></use></svg>
    <div style="flex:1;font-size:12px;color:var(--text);line-height:1.4">${esc(label)}</div>
    <div style="flex-shrink:0;display:flex;gap:4px">${action}</div>
  </div>`;
}

// Expanded picker UI. Four radio modes + optional readOnly chip group.
function _renderSharingPicker(sectionKey, record) {
  const spec = _SHARING_SECTIONS[sectionKey];
  const defaultBehavior = spec?.defaultBehavior || 'inherit';
  const share = record.share;
  // Default mode mirrors the section's default behaviour when there's
  // no override. For most sections that's 'inherit'; for notes (and
  // any future default-private section) it's 'private'.
  let mode = defaultBehavior === 'private' ? 'private' : 'inherit';
  if (share === 'private') mode = 'private';
  else if (typeof share === 'object') {
    if (Array.isArray(share.allow)) mode = 'allow';
    else if (Array.isArray(share.deny)) mode = 'deny';
  }

  const allowSet    = new Set(Array.isArray(share?.allow)    ? share.allow    : []);
  const denySet     = new Set(Array.isArray(share?.deny)     ? share.deny     : []);
  const readOnlySet = new Set(Array.isArray(share?.readOnly) ? share.readOnly : []);

  const radio = (val, label, help) => `
    <label style="display:flex;align-items:flex-start;gap:8px;padding:8px;border-radius:8px;cursor:pointer;border:1px solid ${mode===val?'var(--accent)':'var(--border)'};background:${mode===val?'rgba(232,168,56,0.08)':'transparent'};margin-bottom:6px">
      <input type="radio" name="${sectionKey}-share-mode" value="${val}" ${mode===val?'checked':''} onchange="_setSharingMode('${sectionKey}','${val}')" style="accent-color:var(--accent);margin-top:2px;cursor:pointer">
      <div style="flex:1">
        <div style="font-size:13px;font-weight:600;color:var(--text)">${esc(label)}</div>
        <div style="font-size:11px;color:var(--muted);margin-top:2px;line-height:1.4">${esc(help)}</div>
      </div>
    </label>`;

  const shareChips = (selSet, key, disabled) => _shareTargets.map(t => {
    const checked = selSet.has(t.code);
    return `<button class="btn btn-ghost btn-sm" ${disabled?'disabled':''} onclick="_toggleSharingArr('${sectionKey}','${key}','${t.code}')"
      style="padding:5px 12px;border-radius:99px;font-size:12px;border:1px solid ${checked?'var(--accent)':'var(--border)'};background:${checked?'rgba(232,168,56,0.15)':'var(--bg)'};color:${checked?'var(--accent)':'var(--muted)'};${disabled?'opacity:0.4;cursor:not-allowed':''}">
      ${checked?'<svg class="icon icon-sm" aria-hidden="true"><use href="#i-check"></use></svg> ':''}${esc(t.name)}
    </button>`;
  }).join('');

  const noun = spec?.noun || 'record';
  const showAllowList = mode === 'allow';
  const showDenyList  = mode === 'deny';
  const showReadOnly  = mode === 'inherit' || mode === 'allow';

  return `
    <div style="padding:12px;background:var(--surface2);border-radius:8px">
      ${defaultBehavior === 'private' ? '' : radio('inherit', 'Inherit (default)', 'Use the section-level permission for every share.')}
      ${radio('private', 'Private — owner only', `Hide this ${noun} from every share. Nobody sees it.`)}
      ${radio('allow',   'Only specific shares', `Visible only to the shares you tick below.`)}
      ${defaultBehavior === 'private' ? '' : radio('deny',    'Hide from specific shares', 'Show to everyone EXCEPT the shares you tick below.')}

      ${showAllowList ? `
        <div style="margin-top:12px">
          <div style="font-size:12px;font-weight:600;color:var(--text);margin-bottom:6px">Allowed shares</div>
          <div style="display:flex;flex-wrap:wrap;gap:6px">${shareChips(allowSet, 'allow', false)}</div>
        </div>` : ''}

      ${showDenyList ? `
        <div style="margin-top:12px">
          <div style="font-size:12px;font-weight:600;color:var(--text);margin-bottom:6px">Denied shares</div>
          <div style="display:flex;flex-wrap:wrap;gap:6px">${shareChips(denySet, 'deny', false)}</div>
        </div>` : ''}

      ${showReadOnly ? `
        <div style="margin-top:14px;padding-top:12px;border-top:1px solid var(--border)">
          <div style="font-size:12px;font-weight:600;color:var(--text);margin-bottom:6px">Read-only for these shares</div>
          <div style="font-size:11px;color:var(--muted);margin-bottom:8px;line-height:1.4">Selected shares can see this ${esc(noun)} but never edit it, even if they have edit perm on the whole section.</div>
          <div style="display:flex;flex-wrap:wrap;gap:6px">${shareChips(readOnlySet, 'readOnly', mode==='deny'||mode==='private')}</div>
        </div>` : ''}

      <div style="margin-top:14px;padding-top:12px;border-top:1px solid var(--border);display:flex;justify-content:flex-end;gap:6px">
        <button class="btn btn-ghost btn-sm" onclick="_collapseSharing('${sectionKey}')">Done</button>
      </div>
    </div>`;
}

// ── Sharing panel interactions (generic, section-keyed) ─────────────────
// Each handler resolves to its section's spec, mutates the record via the
// spec's findRecord(), persists via spec.save(), and re-renders.

function _expandSharing(sectionKey) {
  _sharingExpanded[sectionKey] = true;
  const spec = _SHARING_SECTIONS[sectionKey];
  if (!spec) return;
  const rec = spec.findRecord(spec.currentId());
  if (rec) _renderSharingPanel(sectionKey, rec);
}

function _collapseSharing(sectionKey) {
  _sharingExpanded[sectionKey] = false;
  const spec = _SHARING_SECTIONS[sectionKey];
  if (!spec) return;
  const rec = spec.findRecord(spec.currentId());
  if (rec) _renderSharingPanel(sectionKey, rec);
}

async function _clearSharing(sectionKey) {
  const spec = _SHARING_SECTIONS[sectionKey];
  if (!spec) return;
  const rec = spec.findRecord(spec.currentId());
  if (!rec) return;
  delete rec.share;
  rec.updatedAt = new Date().toISOString();
  await spec.save();
  _sharingExpanded[sectionKey] = false;
  _renderSharingPanel(sectionKey, rec);
  _syncQueue.enqueue('Updating sharing…');
  _rePushAllShares();
}

function _setSharingMode(sectionKey, mode) {
  const spec = _SHARING_SECTIONS[sectionKey];
  if (!spec) return;
  const rec = spec.findRecord(spec.currentId());
  if (!rec) return;
  // Preserve readOnly across mode flips when it still makes sense.
  // Inherit and allow keep it; private and deny clear it.
  const oldReadOnly = (typeof rec.share === 'object' && Array.isArray(rec.share?.readOnly))
    ? rec.share.readOnly : [];

  if (mode === 'inherit') {
    if (oldReadOnly.length) rec.share = { readOnly: oldReadOnly };
    else                    delete rec.share;
  } else if (mode === 'private') {
    rec.share = 'private';
  } else if (mode === 'allow') {
    const oldAllow = (typeof rec.share === 'object' && Array.isArray(rec.share?.allow))
      ? rec.share.allow : [];
    rec.share = { allow: oldAllow };
    if (oldReadOnly.length) rec.share.readOnly = oldReadOnly;
  } else if (mode === 'deny') {
    const oldDeny = (typeof rec.share === 'object' && Array.isArray(rec.share?.deny))
      ? rec.share.deny : [];
    rec.share = { deny: oldDeny };
  }
  rec.updatedAt = new Date().toISOString();
  spec.save();
  _renderSharingPanel(sectionKey, rec);
  _syncQueue.enqueue('Updating sharing…');
  _rePushAllShares();
}

function _toggleSharingArr(sectionKey, key, shareCode) {
  const spec = _SHARING_SECTIONS[sectionKey];
  if (!spec) return;
  const rec = spec.findRecord(spec.currentId());
  if (!rec) return;
  if (typeof rec.share !== 'object' || rec.share === null) {
    rec.share = {};
  }
  const cur = Array.isArray(rec.share[key]) ? [...rec.share[key]] : [];
  const idx = cur.indexOf(shareCode);
  if (idx === -1) cur.push(shareCode);
  else cur.splice(idx, 1);
  if (cur.length) rec.share[key] = cur;
  else            delete rec.share[key];
  // Auto-clean: empty share object → delete entirely (= inherit)
  if (typeof rec.share === 'object' && Object.keys(rec.share).length === 0) {
    delete rec.share;
  }
  rec.updatedAt = new Date().toISOString();
  spec.save();
  _renderSharingPanel(sectionKey, rec);
  _syncQueue.enqueue('Updating sharing…');
  _rePushAllShares();
}

// Re-push every share so per-record perm changes take effect immediately
// on the guest side. Worth doing for fast feedback when the owner is
// actively configuring overrides.
async function _rePushAllShares() {
  if (!Array.isArray(_shareTargets) || !_shareTargets.length) return;
  for (const t of _shareTargets) {
    try { await pushSharedData(t.code); } catch(_) {}
  }
}



function openLogModal(id) { openOrderFlow(id, 'purchase'); } // backward compat
function openLogPurchaseModal(id) { openOrderFlow(id, 'purchase'); } // backward compat
function openLogPurchaseModalLegacy(id) {
  // Legacy fallback for when new index.html hasn't been deployed
  loggingId = id;
  const item = items.find(i => i.id === id);
  if (!item || !document.getElementById('log-modal')) return;
  document.getElementById('log-modal-title').textContent = 'Log Purchase — ' + item.name;
  document.getElementById('log-date').value  = today();
  document.getElementById('log-qty').value   = item.qty || 1;
  document.getElementById('log-price').value = '';
  document.getElementById('log-store').value = item.store || urlToStoreName(item.url||'') || '';
  renderLogHistory(item);
  openModal('log-modal');
}

// ═══════════════════════════════════════════════════════════════
//  ORDER FLOW — unified Log Purchase / Delivered / Start Using
// ═══════════════════════════════════════════════════════════════
let _ofItemId   = null;
let _ofStage    = 'purchase'; // 'purchase' | 'delivered' | 'startusing'

function openOrderFlow(id, stage) {
  const item = items.find(i => i.id === id);
  if (!item) return;

  // Create order-flow-modal dynamically if index.html doesn't have it yet
  if (!document.getElementById('order-flow-modal')) {
    const backdrop = document.createElement('div');
    backdrop.className = 'modal-backdrop';
    backdrop.id = 'order-flow-modal';
    backdrop.innerHTML = `
      <div class="modal" style="max-width:460px">
        <h2 id="order-flow-title"><svg class="icon icon-md" aria-hidden="true"><use href="#i-shopping-cart"></use></svg> Log Purchase</h2>
        <p class="subtitle" id="order-flow-subtitle"></p>
        <div id="order-stage-purchase">
          <div class="form-grid">
            <div class="field"><label>Date purchased</label><input type="date" id="of-date"></div>
            <div class="field"><label>Quantity</label><input type="number" id="of-qty" min="0.1" step="0.1" value="1"></div>
            <div class="field"><label>Price paid <span style="font-weight:400;color:var(--muted)">(optional)</span></label><input type="text" id="of-price" placeholder="e.g. £12.99"></div>
            <div class="field"><label>Store <span style="font-weight:400;color:var(--muted)">(optional)</span></label><input type="text" id="of-store" placeholder="Amazon, Tesco…"></div>
          </div>
          <div id="of-purchase-history" style="margin-top:12px"></div>
        </div>
        <div id="order-stage-delivered" style="display:none">
          <div class="form-grid">
            <div class="field"><label>Delivery date</label><input type="date" id="of-delivered-date"></div>
            <div class="field"><label>Quantity delivered</label><input type="number" id="of-delivered-qty" min="0.1" step="0.1" value="1"></div>
          </div>
          <div style="margin-top:14px;padding:14px;background:var(--surface2);border-radius:10px;border:1px solid var(--border)">
            <label style="font-size:13px;font-weight:700;display:flex;align-items:center;gap:8px;cursor:pointer">
              <input type="checkbox" id="of-started-now" onchange="ofToggleStarted()" style="width:16px;height:16px">
              I'm starting to use this straight away
            </label>
            <div id="of-started-row" style="display:none;margin-top:10px">
              <div class="field"><label>Started using date</label><input type="date" id="of-started-date"></div>
            </div>
            <p id="of-started-hint" style="font-size:12px;color:var(--muted);margin-top:8px;line-height:1.5">If not using it immediately, leave this unchecked — you'll be prompted to set the date when you open it.</p>
          </div>
        </div>
        <div id="order-stage-startusing" style="display:none">
          <p style="font-size:14px;color:var(--text);margin-bottom:16px;line-height:1.6">When did you start using this item? This anchors the stock clock so your estimates stay accurate.</p>
          <div class="field"><label>Started using date</label><input type="date" id="of-startusing-date"></div>
        </div>
        <div class="modal-footer" style="margin-top:16px">
          <button class="btn btn-ghost" onclick="closeModal('order-flow-modal')">Cancel</button>
          <button class="btn btn-primary" id="of-save-btn" onclick="ofSave()">Save</button>
        </div>
      </div>`;
    document.body.appendChild(backdrop);
  }

  _ofItemId = id;

  // Auto-detect stage if not specified
  if (!stage) {
    const hasPending = (item.logs || []).some(l => l.pendingDelivery);
    const hasDeliveredNoStart = (item.logs || []).some(l => !l.pendingDelivery && l.deliveredDate) && !item.startedUsing;
    stage = hasPending ? 'delivered' : hasDeliveredNoStart ? 'startusing' : 'purchase';
  }
  _ofStage = stage;

  const titles = { purchase:'Log Purchase', delivered:'Mark as Delivered', startusing:'Set Start Using Date' };
  const icons  = { purchase:'i-shopping-cart', delivered:'i-package-check', startusing:'i-play' };
  document.getElementById('order-flow-title').innerHTML =
    `<svg class="icon icon-md" aria-hidden="true"><use href="#${icons[stage]}"></use></svg> ${titles[stage]}`;
  document.getElementById('order-flow-subtitle').textContent = item.name;

  // Show/hide stages
  toggle('order-stage-purchase', stage === 'purchase', 'block');
  toggle('order-stage-delivered', stage === 'delivered', 'block');
  toggle('order-stage-startusing', stage === 'startusing', 'block');

  const saveBtn = document.getElementById('of-save-btn');
  if (stage === 'purchase')   { saveBtn.textContent = 'Save Purchase'; }
  if (stage === 'delivered')  { saveBtn.textContent = 'Confirm Delivery'; }
  if (stage === 'startusing') { saveBtn.textContent = 'Save Date'; }

  if (stage === 'purchase') {
    document.getElementById('of-date').value  = today();
    document.getElementById('of-qty').value   = item.qty || 1;
    document.getElementById('of-price').value = '';
    document.getElementById('of-store').value = item.store || urlToStoreName(item.url || '') || '';
    // Show recent purchase history
    _renderOfHistory(item);
  }
  if (stage === 'delivered') {
    document.getElementById('of-delivered-date').value = today();
    const pendingLog = [...(item.logs || [])].reverse().find(l => l.pendingDelivery);
    document.getElementById('of-delivered-qty').value = pendingLog?.qty || item.qty || 1;
    document.getElementById('of-started-now').checked = false;
    hide('of-started-row');
    show('of-started-hint', 'block');
    document.getElementById('of-started-date').value = today();
  }
  if (stage === 'startusing') {
    document.getElementById('of-startusing-date').value = item.startedUsing || today();
  }

  openModal('order-flow-modal');
}

function _renderOfHistory(item) {
  const hist = document.getElementById('of-purchase-history');
  if (!hist) return;
  const logs = (item.logs || []).filter(l => !l.pendingDelivery).slice(-3).reverse();
  if (!logs.length) { hist.innerHTML = ''; return; }
  hist.innerHTML = `<p style="font-size:11px;font-weight:700;color:var(--muted);font-family:var(--mono);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px">Recent purchases</p>` +
    logs.map(l => `<div style="font-size:12px;color:var(--muted);padding:4px 0">${fmt(l.date)}${l.price ? ' · ' + esc(l.price) : ''}${l.qty && l.qty !== 1 ? ' · ×' + l.qty : ''}</div>`).join('');
}

function ofToggleStarted() {
  const checked = document.getElementById('of-started-now').checked;
  toggle('of-started-row', checked, 'block');
  toggle('of-started-hint', !(checked), 'block');
}

async function ofSave() {
  if (!canWrite('stockroom')) { showLockBanner('stockroom'); return; }
  const item = items.find(i => i.id === _ofItemId);
  if (!item) return;

  if (_ofStage === 'purchase') {
    if (!item.logs) item.logs = [];
    item.logs.push({
      id:              uid(),
      date:            document.getElementById('of-date').value || today(),
      qty:             parseFloat(document.getElementById('of-qty').value) || 1,
      price:           document.getElementById('of-price').value.trim(),
      store:           document.getElementById('of-store').value.trim(),
      pendingDelivery: true,
    });
    item.logs.sort((a,b) => new Date(a.date) - new Date(b.date));
    item.ordered   = true;
    item.orderedAt = new Date().toISOString();
    touchField(item, 'logs', 'ordered', 'orderedAt');
    await saveData();
    closeModal('order-flow-modal');
    scheduleRender('grid', 'dashboard', 'shopping');
    setTimeout(syncAll, 400);
    toast('Purchase logged — tap the order button when it arrives ✓');

  } else if (_ofStage === 'delivered') {
    if (!item.logs) item.logs = [];
    const deliveryDate = document.getElementById('of-delivered-date').value || today();
    const qty          = parseFloat(document.getElementById('of-delivered-qty').value) || 1;
    const startedNow   = document.getElementById('of-started-now').checked;
    const startedDate  = startedNow ? (document.getElementById('of-started-date').value || deliveryDate) : null;
    const pendingIdx   = [...item.logs].map((l,i) => ({l,i})).reverse().find(({l}) => l.pendingDelivery)?.i;
    if (pendingIdx !== undefined) {
      item.logs[pendingIdx].pendingDelivery = false;
      item.logs[pendingIdx].deliveredDate   = deliveryDate;
      item.logs[pendingIdx].qty             = qty;
    } else {
      item.logs.push({ id: uid(), date: deliveryDate, qty, pendingDelivery: false, deliveredDate });
      item.logs.sort((a,b) => new Date(a.date) - new Date(b.date));
    }
    item.ordered = false; item.orderedAt = null;
    if (startedDate) item.startedUsing = startedDate;
    // Auto-update stock count: add delivered qty to existing projected count
    // (or use delivered qty as the new count if there wasn't one).
    const existing = getProjectedUnitsLeft(item);
    item.stockCount = (existing != null && existing > 0)
      ? Math.round((existing + qty) * 100) / 100
      : qty;
    item.stockCountDate = deliveryDate;
    touchItem(item);
    await saveData();
    closeModal('order-flow-modal');
    scheduleRender('grid', 'dashboard', 'shopping');
    setTimeout(syncAll, 400);
    toast(startedDate ? 'Delivered and marked as in use ✓' : 'Delivery confirmed ✓');

  } else if (_ofStage === 'startusing') {
    const date = document.getElementById('of-startusing-date').value || today();
    item.startedUsing = date;
    touchField(item, 'startedUsing');
    await saveData();
    closeModal('order-flow-modal');
    scheduleRender('grid', 'dashboard');
    setTimeout(syncAll, 400);
    toast('Start date saved — stock clock updated ✓');
  }
}

// Unified card button — determines correct stage automatically
function openOrderFlowFromCard(id) { openOrderFlow(id, null); }

// ═══════════════════════════════════════════════════════════════
//  REPLACEMENT REMINDERS MODAL
// ═══════════════════════════════════════════════════════════════
let _replItemId = null;

function openReplRemindersModal(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;

  // Migrate legacy single-reminder into array format before opening, and persist it
  const hadLegacy = !item.replacementReminders?.length && !!item.replacementInterval;
  _ensureReplRemindersArray(item);
  if (hadLegacy && item.replacementReminders?.length) {
    // Silently persist the migrated format so future opens use stable IDs
    saveData().then(() => _syncQueue.enqueue()).catch(() => {});
  }

  _replItemId = id;

  // Create modal dynamically if index.html doesn't have it yet
  if (!document.getElementById('repl-reminders-modal')) {
    const backdrop = document.createElement('div');
    backdrop.className = 'modal-backdrop';
    backdrop.id = 'repl-reminders-modal';
    backdrop.innerHTML = `
      <div class="modal" style="max-width:480px">
        <h2><svg class="icon icon-md" aria-hidden="true"><use href="#i-bell"></use></svg> Replacement Reminders</h2>
        <p class="subtitle" id="repl-reminders-subtitle"></p>
        <div id="repl-reminders-list" style="display:flex;flex-direction:column;gap:10px;margin-bottom:16px"></div>
        <button class="btn btn-ghost btn-sm" onclick="replAddReminder()" style="width:100%">
          <svg class="icon" aria-hidden="true"><use href="#i-plus"></use></svg> Add a reminder
        </button>
        <div class="modal-footer" style="margin-top:16px">
          <button class="btn btn-ghost" onclick="closeModal('repl-reminders-modal')">Close</button>
        </div>
      </div>`;
    document.body.appendChild(backdrop);
  }

  document.getElementById('repl-reminders-subtitle').textContent = item.name;
  _renderReplRemindersList(item);
  openModal('repl-reminders-modal');
}

function _renderReplRemindersList(item) {
  const list = document.getElementById('repl-reminders-list');
  if (!list) return;
  const reminders = _getItemReminders(item);
  if (!reminders.length) {
    list.innerHTML = `<p style="font-size:13px;color:var(--muted)">No reminders yet. Add one below.</p>`;
    return;
  }
  list.innerHTML = reminders.map((r, i) => `
    <div class="repl-reminder-row" id="replrem-${r.id}">
      <div style="flex:1;display:flex;flex-direction:column;gap:6px">
        <div style="display:flex;align-items:center;gap:8px">
          <svg class="icon" aria-hidden="true" style="color:var(--ok);flex-shrink:0"><use href="#i-bell"></use></svg>
          <input type="text" placeholder="Name (e.g. Pete, Main filter — optional)" value="${esc(r.name || '')}"
            style="flex:1" oninput="_replUpdateName('${r.id}',this.value)">
        </div>
        <div style="display:flex;gap:6px;align-items:center;padding-left:24px">
          <span style="font-size:12px;color:var(--muted);white-space:nowrap">Every</span>
          <input type="number" min="1" max="365" value="${r.interval}" style="width:60px"
            oninput="_replUpdateInterval('${r.id}',parseInt(this.value)||1)">
          <select style="flex:1" onchange="_replUpdateUnit('${r.id}',this.value)">
            <option value="days" ${r.unit==='days'?'selected':''}>days</option>
            <option value="weeks" ${r.unit==='weeks'?'selected':''}>weeks</option>
            <option value="months" ${r.unit==='months'?'selected':''}>months</option>
          </select>
        </div>
        ${r.lastReplaced ? `<div style="font-size:11px;color:var(--muted);padding-left:24px">Last replaced: ${fmt(r.lastReplaced)}</div>` : ''}
      </div>
      <button onclick="_replDeleteReminder('${r.id}')" style="background:none;border:none;cursor:pointer;color:var(--danger);padding:4px" title="Delete">
        <svg class="icon" aria-hidden="true"><use href="#i-trash-2"></use></svg>
      </button>
    </div>`).join('');
}

function _ensureReplRemindersArray(item) {
  if (!item.replacementReminders?.length) {
    if (item.replacementInterval) {
      item.replacementReminders = [{ id: uid(), name: '', interval: item.replacementInterval, unit: item.replacementUnit || 'months', lastReplaced: item.startedUsing || null }];
    } else {
      item.replacementReminders = [];
    }
  }
}

function replAddReminder() {
  const item = items.find(i => i.id === _replItemId);
  if (!item) return;
  _ensureReplRemindersArray(item);
  item.replacementReminders.push({ id: uid(), name: '', interval: 3, unit: 'months', lastReplaced: null });
  _saveReplReminders(item);
}

function _replUpdateName(rid, val) {
  const item = items.find(i => i.id === _replItemId);
  if (!item?.replacementReminders) return;
  const r = item.replacementReminders.find(r => r.id === rid);
  if (r) { r.name = val; _saveReplRemindersDebounced(item); }
}
function _replUpdateInterval(rid, val) {
  const item = items.find(i => i.id === _replItemId);
  if (!item?.replacementReminders) return;
  const r = item.replacementReminders.find(r => r.id === rid);
  if (r) { r.interval = val; _saveReplRemindersDebounced(item); }
}
function _replUpdateUnit(rid, val) {
  const item = items.find(i => i.id === _replItemId);
  if (!item?.replacementReminders) return;
  const r = item.replacementReminders.find(r => r.id === rid);
  if (r) { r.unit = val; _saveReplRemindersDebounced(item); }
}
function _replDeleteReminder(rid) {
  const item = items.find(i => i.id === _replItemId);
  if (!item?.replacementReminders) return;
  item.replacementReminders = item.replacementReminders.filter(r => r.id !== rid);
  _saveReplReminders(item);
}

let _replSaveTimer = null;
function _saveReplRemindersDebounced(item) {
  clearTimeout(_replSaveTimer);
  _replSaveTimer = setTimeout(() => _saveReplReminders(item), 600);
}
async function _saveReplReminders(item) {
  // Keep legacy fields in sync with first reminder
  if (item.replacementReminders?.length) {
    item.replacementInterval = item.replacementReminders[0].interval;
    item.replacementUnit     = item.replacementReminders[0].unit;
  } else {
    item.replacementInterval = null;
    item.replacementUnit     = null;
  }
  touchItem(item);
  await saveData();
  _renderReplRemindersList(item);
  scheduleRender('grid');
  setTimeout(syncAll, 400);
}





// ═══════════════════════════════════════════
//  SAVE / DELETE
// ═══════════════════════════════════════════
async function saveItem() {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const name = document.getElementById('f-name').value.trim();
  if (!name) { alert('Please enter a name for this item.'); return; }
  const startedUsing = document.getElementById('f-started-using').value || null;
  const storeVal = document.getElementById('f-store').value.trim()
    || urlToStoreName(document.getElementById('f-url').value.trim());

  // Snapshot before any mutation so history can capture the change.
  // For an edit: snapshot the existing item. For a create: null (the
  // new item doesn't exist yet).
  let _historyBefore = null;
  if (editingId) {
    const existing = items.find(i => i.id === editingId);
    if (existing) _historyBefore = JSON.parse(JSON.stringify(existing));
  }
  // Will be filled in below — captured here so the record() call after
  // close has both before and after.
  let _historyAfter = null;
  let _historyRecordId = null;
  let _historyRecordName = name;

  if (editingId) {
    const item = items.find(i => i.id === editingId);
    if (item) {
      item.name         = name;
      item.category     = document.getElementById('f-category').value;
      item.cadence      = document.getElementById('f-cadence').value;
      const newQty      = parseFloat(document.getElementById('f-qty').value)||1;
      const newMonths   = parseFloat(document.getElementById('f-months').value)||1;
      // Recompute daysPerUnit if months or qty changed (or if missing)
      if (newQty !== item.qty || newMonths !== item.months || typeof item.daysPerUnit !== 'number') {
        item.daysPerUnit = (newMonths * AVG_DAYS_PER_MONTH) / Math.max(0.0001, newQty);
      }
      item.qty          = newQty;
      item.months       = newMonths;
      item.unitType     = document.getElementById('f-unit-type')?.value || 'item';
      item.url          = document.getElementById('f-url').value.trim();
      item.store        = storeVal;
      // Propagate new store name to all log entries so filter bar stays clean
      if (storeVal && item.logs) {
        item.logs.forEach(l => { if (l.store && l.store !== storeVal) l.store = storeVal; });
      }
      item.notes        = document.getElementById('f-notes').value.trim();
      item.startedUsing = startedUsing;
      item.rating       = currentRating || null;
      item.imageUrl     = pendingImageUrl || item.imageUrl || null;
      item.storePrices  = tempStorePrices.filter(sp => sp.store || sp.price);
      item.expiry       = document.getElementById('f-expiry')?.value || null;
      const tOverride   = parseInt(document.getElementById('f-threshold')?.value);
      item.thresholdOverride = isNaN(tOverride) ? null : tOverride;
      const replInterval = parseInt(document.getElementById('f-replace-interval')?.value);
      item.replacementInterval = isNaN(replInterval) ? null : replInterval;
      item.replacementUnit     = document.getElementById('f-replace-unit')?.value || 'months';

      // Update the most recent log entry's date and qty
      const lastDate  = document.getElementById('f-last-date').value;
      const lastQty   = parseFloat(document.getElementById('f-last-qty').value)||1;
      const lastPrice = document.getElementById('f-last-price').value.trim();
      if (lastDate) {
        if (item.logs && item.logs.length) {
          item.logs[item.logs.length - 1].date  = lastDate;
          item.logs[item.logs.length - 1].qty   = lastQty;
          item.logs[item.logs.length - 1].price = lastPrice;
          item.logs.sort((a,b) => new Date(a.date) - new Date(b.date));
        } else {
          item.logs = [{ id: uid(), date: lastDate, qty: lastQty, price: lastPrice, store: storeVal }];
        }
      }
      touchField(item,
        'name','category','cadence','qty','months','unitType','daysPerUnit','url','store',
        'notes','startedUsing','rating','imageUrl','storePrices',
        'expiry','thresholdOverride','replacementInterval','replacementUnit'
      );
      _historyRecordId = item.id;
      _historyRecordName = item.name;
      _historyAfter = JSON.parse(JSON.stringify(item));
    }
  } else {
    const lastDate  = document.getElementById('f-last-date').value;
    const lastQty   = parseFloat(document.getElementById('f-last-qty').value)||1;
    const lastPrice = document.getElementById('f-last-price').value.trim();
    const newQty    = parseFloat(document.getElementById('f-qty').value)||1;
    const newMonths = parseFloat(document.getElementById('f-months').value)||1;
    const newItem = {
      id:                uid(),
      name,
      category:          document.getElementById('f-category').value,
      cadence:           document.getElementById('f-cadence').value,
      qty:               newQty,
      months:            newMonths,
      unitType:          document.getElementById('f-unit-type')?.value || 'item',
      daysPerUnit:       (newMonths * AVG_DAYS_PER_MONTH) / Math.max(0.0001, newQty),
      url:               document.getElementById('f-url').value.trim(),
      store:             storeVal,
      notes:             document.getElementById('f-notes').value.trim(),
      startedUsing,
      rating:            currentRating || null,
      imageUrl:          pendingImageUrl || null,
      storePrices:       tempStorePrices.filter(sp => sp.store || sp.price),
      expiry:            document.getElementById('f-expiry')?.value || null,
      thresholdOverride: (() => { const v = parseInt(document.getElementById('f-threshold')?.value); return isNaN(v) ? null : v; })(),
      logs:              lastDate ? [{ id:uid(), date:lastDate, qty:lastQty, price:lastPrice, store:storeVal }] : [],
      updatedAt:         new Date().toISOString(),
    };
    items.push(newItem);
    _historyRecordId = newItem.id;
    _historyRecordName = newItem.name;
    _historyAfter = JSON.parse(JSON.stringify(newItem));
  }
  await saveData();
  closeModal('item-modal');
  if (editingId) clearQuickAddedFlag(editingId);
  scheduleRender('grid', 'dashboard', 'filters', 'shopping', 'sns');
  // Log to history. Edit → type='edit' with before+after. Create →
  // type='create' with after only. Undo for edits restores the snapshot
  // via _applyRestoreFromSnapshot. Undo for creates soft-deletes.
  if (_historyRecordId) {
    const isCreate = !_historyBefore;
    const recId = _historyRecordId;
    historyRecord({
      type: isCreate ? 'create' : 'edit',
      domain: 'item',
      recordId: recId,
      recordName: _historyRecordName,
      before: _historyBefore,
      after:  _historyAfter,
      undo: async () => {
        if (isCreate) {
          // Undo a create: soft-delete the new item
          const it = items.find(i => i.id === recId);
          if (!it) return;
          it._deletedAt = new Date().toISOString();
          if (typeof touchField === 'function') { try { touchField(it, '_deletedAt'); } catch (_) {} }
          await saveData();
          scheduleRender('grid', 'dashboard', 'shopping');
          _syncQueue.enqueue();
        } else {
          // Undo an edit: restore the before snapshot
          const idx = items.findIndex(i => i.id === recId);
          if (idx >= 0 && _historyBefore) {
            items[idx] = { ..._historyBefore, updatedAt: new Date().toISOString() };
            if (typeof touchItem === 'function') touchItem(items[idx]);
            await saveData();
            scheduleRender('grid', 'dashboard', 'filters', 'shopping', 'sns');
            _syncQueue.enqueue();
          }
        }
      },
      redo: async () => {
        if (isCreate) {
          // Redo create: undelete the item we soft-deleted
          const it = items.find(i => i.id === recId);
          if (!it) return;
          delete it._deletedAt;
          if (typeof touchField === 'function') { try { touchField(it, '_deletedAt'); } catch (_) {} }
          await saveData();
          scheduleRender('grid', 'dashboard', 'shopping');
          _syncQueue.enqueue();
        } else {
          // Redo edit: re-apply the after snapshot
          const idx = items.findIndex(i => i.id === recId);
          if (idx >= 0 && _historyAfter) {
            items[idx] = { ..._historyAfter, updatedAt: new Date().toISOString() };
            if (typeof touchItem === 'function') touchItem(items[idx]);
            await saveData();
            scheduleRender('grid', 'dashboard', 'filters', 'shopping', 'sns');
            _syncQueue.enqueue();
          }
        }
      },
    });
  }
  toast('Item saved ✓');
  _syncQueue.enqueue('Saving item…');
}

async function saveLog() {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === loggingId);
  if (!item) return;
  if (!item.logs) item.logs = [];
  item.logs.push({
    id:             uid(),
    date:           document.getElementById('log-date').value,
    qty:            parseFloat(document.getElementById('log-qty').value)||1,
    price:          document.getElementById('log-price').value.trim(),
    store:          document.getElementById('log-store').value.trim(),
    pendingDelivery: true,
  });
  item.logs.sort((a,b) => new Date(a.date) - new Date(b.date));
  // Mark as ordered
  item.ordered   = true;
  item.orderedAt = new Date().toISOString();
  touchField(item, 'logs', 'ordered', 'orderedAt');
  await saveData();
  closeModal('log-modal');
  scheduleRender('grid', 'dashboard', 'shopping');
  setTimeout(syncAll, 400);

  // If triggered from "Delivered" button with no prior log, go straight to delivered modal
  const logThenDeliver = sessionStorage.getItem('log_then_deliver');
  if (logThenDeliver && logThenDeliver === loggingId) {
    sessionStorage.removeItem('log_then_deliver');
    setTimeout(() => openDeliveredModal(loggingId), 200);
  } else {
    toast('Purchase logged — tap Delivered when it arrives ✓');
  }
}

// ── Delivered flow ─────────────────────────────────────────
let deliveringId = null;

function openDeliveredModal(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;

  const hasPendingLog = item.logs?.some(l => l.pendingDelivery);

  // If not ordered at all and no pending log, route through log purchase first
  if (!hasPendingLog && !item.ordered) {
    sessionStorage.setItem('log_then_deliver', id);
    openLogPurchaseModal(id);
    setTimeout(() => {
      const title = document.getElementById('log-modal-title');
      if (title) title.innerHTML = '<svg class="icon icon-md" aria-hidden="true" style="color:var(--accent);vertical-align:-3px"><use href="#i-package"></use></svg> Purchase Details — ' + esc(item.name);
      const sub = document.querySelector('#log-modal .subtitle');
      if (sub) sub.textContent = 'Enter the purchase details then we\'ll confirm delivery.';
      const saveBtn = document.querySelector('#log-modal .btn-primary');
      if (saveBtn) { saveBtn.textContent = 'Next — Confirm Delivery →'; saveBtn.style.background = 'var(--ok)'; }
    }, 30);
    return;
  }

  deliveringId = id;
  document.getElementById('delivered-modal-title').innerHTML = `<svg class="icon icon-md" aria-hidden="true" style="color:var(--accent);vertical-align:-3px"><use href="#i-package-check"></use></svg> Delivered — ${esc(item.name)}`;
  document.getElementById('delivered-date').value = today();
  const pendingLog = [...(item.logs||[])].reverse().find(l => l.pendingDelivery);
  document.getElementById('delivered-qty').value = pendingLog?.qty || item.qty || 1;
  document.getElementById('delivered-started-now').checked = false;
  hide('delivered-started-row');
  show('delivered-started-hint', 'block');
  document.getElementById('delivered-started-date').value = today();
  openModal('delivered-modal');
}

function toggleDeliveredStarted() {
  const checked = document.getElementById('delivered-started-now').checked;
  toggle('delivered-started-row', checked, 'block');
  toggle('delivered-started-hint', !(checked), 'block');
}

async function saveDelivered() {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === deliveringId);
  if (!item) return;

  const deliveryDate  = document.getElementById('delivered-date').value || today();
  const qty           = parseFloat(document.getElementById('delivered-qty').value) || 1;
  const startedNow    = document.getElementById('delivered-started-now').checked;
  const startedDate   = startedNow ? (document.getElementById('delivered-started-date').value || deliveryDate) : null;

  if (!item.logs) item.logs = [];

  // Find and update the most recent pending log, or create a new delivered log
  const pendingIdx = [...item.logs].map((l,i)=>({l,i})).reverse().find(({l})=>l.pendingDelivery)?.i;
  if (pendingIdx !== undefined) {
    item.logs[pendingIdx].pendingDelivery = false;
    item.logs[pendingIdx].deliveredDate   = deliveryDate;
    item.logs[pendingIdx].qty             = qty;
  } else {
    item.logs.push({ id: uid(), date: deliveryDate, qty, pendingDelivery: false, deliveredDate });
    item.logs.sort((a,b) => new Date(a.date) - new Date(b.date));
  }

  // Clear ordered flag
  item.ordered   = false;
  item.orderedAt = null;

  // Set startedUsing if user said they're starting now
  if (startedDate) item.startedUsing = startedDate;

  // Auto-update stock count: add delivered qty to existing projected count
  // (or use delivered qty as the new count if there wasn't one). This is
  // what powers "~17 cans left" projections going forward.
  const existing = getProjectedUnitsLeft(item);
  item.stockCount = (existing != null && existing > 0)
    ? Math.round((existing + qty) * 100) / 100  // keep up to 2 decimal places
    : qty;
  item.stockCountDate = deliveryDate;

  touchItem(item);
  await saveData();
  closeModal('delivered-modal');
  scheduleRender('grid', 'dashboard', 'shopping');
  setTimeout(syncAll, 400);

  // Offer reminder setup
  openDeliveryReminderModal(deliveringId, !startedDate);
}

// ── Post-delivery reminder modal ───────────────────────────
let deliveryReminderItemId = null;
let deliveryNeedsStartDate = false;

function openDeliveryReminderModal(id, needsStartDate) {
  const item = items.find(i => i.id === id);
  if (!item) return;
  deliveryReminderItemId = id;
  deliveryNeedsStartDate = needsStartDate;

  document.getElementById('delivery-reminder-subtitle').textContent =
    needsStartDate
      ? `Come back and set a "started using" date to keep calculations accurate.`
      : `Do you want a reminder when it's time to replace this?`;

  const hasReminder = item.replacementInterval;
  const body = document.getElementById('delivery-reminder-body');
  body.innerHTML = `
    ${needsStartDate ? `
      <div style="background:rgba(232,168,56,0.1);border:1px solid rgba(232,168,56,0.25);border-radius:10px;padding:12px 14px;margin-bottom:16px;font-size:13px;color:var(--warn);line-height:1.5">
        ⏳ When you open the first pack, tap <strong>"Set date"</strong> on the card — it anchors the stock clock and any reminders to the right start point.
      </div>` : ''}
    <div style="margin-bottom:14px">
      <label class="form-label">Replace every</label>
      <div style="display:flex;gap:8px;align-items:center">
        <input class="form-input" id="dr-interval" type="number" min="1" max="365" value="${item.replacementInterval||3}" style="width:80px">
        <select class="form-input" id="dr-unit" style="flex:1">
          <option value="days"   ${(item.replacementUnit||'months')==='days'   ?'selected':''}>days</option>
          <option value="weeks"  ${(item.replacementUnit||'months')==='weeks'  ?'selected':''}>weeks</option>
          <option value="months" ${(item.replacementUnit||'months')==='months' ?'selected':''}>months</option>
        </select>
      </div>
    </div>
    ${!hasReminder ? `<p style="font-size:12px;color:var(--muted)">You can also set this later via ✏️ Edit on the item.</p>` : ''}
  `;
  openModal('delivery-reminder-modal');
}

async function saveDeliveryReminder() {
  const item = items.find(i => i.id === deliveryReminderItemId);
  if (!item) return;
  const interval = parseInt(document.getElementById('dr-interval').value) || 3;
  const unit     = document.getElementById('dr-unit').value || 'months';
  item.replacementInterval = interval;
  item.replacementUnit     = unit;
  touchItem(item);
  await saveData();
  closeModal('delivery-reminder-modal');
  scheduleRender('grid');
  setTimeout(syncAll, 400);
  toast(`🔔 Reminder set: every ${interval} ${unit}`);
}

// ── Started using modal ────────────────────────────────────
let startedUsingItemId = null;

function openStartedUsingModal(id) {
  startedUsingItemId = id;
  const item = items.find(i => i.id === id);
  if (!item) return;
  document.getElementById('started-using-title').innerHTML = `<svg class="icon icon-md" aria-hidden="true" style="color:var(--accent);vertical-align:-3px"><use href="#i-calendar"></use></svg> ${esc(item.name)} — when did you start using it?`;
  document.getElementById('started-using-date').value = today();
  openModal('started-using-modal');
}

async function saveStartedUsing() {
  if (!canWrite("stockroom")) { showLockBanner("stockroom"); return; }
  const item = items.find(i => i.id === startedUsingItemId);
  if (!item) return;
  const date = document.getElementById('started-using-date').value || today();
  item.startedUsing = date;
  touchField(item, 'startedUsing');
  await saveData();
  closeModal('started-using-modal');
  scheduleRender('grid', 'dashboard');
  setTimeout(syncAll, 400);
  toast('Start date saved — stock clock updated ✓');
}

// ─── Generic bulk-select / bulk-actions module (Pass 2a) ────────────────
// Section-parameterised multi-select infrastructure. Each section
// registers its specifics — find record, save path, archive support,
// per-section share-merge logic — via registerBulkSelectSection.
// The picker, action bar, and share-flow are shared.
//
// Spec shape:
//   findRecord(id)        — return the record object (or null)
//   save()                — async, persist the section after a bulk
//                           mutation (saveData, _saveGroceryLists, etc.)
//   rerender()            — refresh the section's view after the action
//   getVisibleIds()       — array of currently-rendered record ids; used
//                           by Select All. Should respect filters.
//   permCheck()           — boolean. Should toast+return false if the
//                           user lacks the canWrite gate for this section.
//   applyDelete(record)   — mutate record into the deleted state (set
//                           tombstone, _deletedAt, etc). Called once per
//                           record before a single save+rerender.
//   applyArchive(record)  — optional. If present, action bar shows Archive.
//                           Same shape as applyDelete.
//   sectionPermKey        — 'stockroom' | 'groceries' | 'reminders' | 'budget'
//                           Used when bulk-share creates a NEW share, to
//                           pre-set that section perm to 'r'.
//   noun                  — singular ("item", "list", "reminder", "spend")
//   pluralNoun            — plural form
//
// Public API:
//   registerBulkSelectSection(key, spec)
//   enterBulkSelectMode(sectionKey)
//   exitBulkSelectMode()
//   isBulkSelectMode(sectionKey?) — true if any/specific section in mode
//   toggleBulkSelection(sectionKey, id)
//   bulkSelectionHas(sectionKey, id)

function registerBulkSelectSection(key, spec) {
  if (_BULK_SELECT_SECTIONS[key]) {
    console.warn('[bulk-select] section already registered, overwriting:', key);
  }
  _BULK_SELECT_SECTIONS[key] = spec;
}

function isBulkSelectMode(sectionKey) {
  if (sectionKey) return _bulkSelectActiveSection === sectionKey;
  return _bulkSelectActiveSection !== null;
}

function bulkSelectionHas(sectionKey, id) {
  const set = _bulkSelections[sectionKey];
  return set ? set.has(id) : false;
}

function _getActiveSpec() {
  return _bulkSelectActiveSection ? _BULK_SELECT_SECTIONS[_bulkSelectActiveSection] : null;
}

function _getActiveSelection() {
  if (!_bulkSelectActiveSection) return null;
  if (!_bulkSelections[_bulkSelectActiveSection]) {
    _bulkSelections[_bulkSelectActiveSection] = new Set();
  }
  return _bulkSelections[_bulkSelectActiveSection];
}

function enterBulkSelectMode(sectionKey) {
  const spec = _BULK_SELECT_SECTIONS[sectionKey];
  if (!spec) { console.warn('[bulk-select] unknown section:', sectionKey); return; }
  // Permission gate — each section decides its own canWrite check.
  if (spec.permCheck && !spec.permCheck()) return;
  // If another section is already in select mode, exit it first (one
  // section at a time — keeps the action bar unambiguous).
  if (_bulkSelectActiveSection && _bulkSelectActiveSection !== sectionKey) {
    exitBulkSelectMode();
  }
  _bulkSelectActiveSection = sectionKey;
  _bulkSelections[sectionKey] = new Set();
  document.body.classList.add('bulk-select-mode');
  document.body.classList.add(`bulk-select-mode-${sectionKey}`);
  // Dismiss any card-actions overlay that might be open from a prior
  // hover/long-press — and clear any pending hover/long-press timers,
  // since onCardHoverEnter / onCardTouchStart now early-return so the
  // timers won't be cleaned up by the usual paths once frozen.
  if (typeof _dismissCardActions === 'function') {
    try { _dismissCardActions(); } catch(_) {}
  }
  if (typeof _cardActionState === 'object' && _cardActionState?.by) {
    for (const id of Object.keys(_cardActionState.by)) {
      const st = _cardActionState.by[id];
      if (st) { clearTimeout(st.hoverTimer); clearTimeout(st.longPressTimer); }
    }
  }
  _renderBulkSelectBar();
  if (spec.rerender) spec.rerender();
}

function exitBulkSelectMode() {
  if (!_bulkSelectActiveSection) return;
  const wasSection = _bulkSelectActiveSection;
  const spec = _BULK_SELECT_SECTIONS[wasSection];
  _bulkSelectActiveSection = null;
  if (_bulkSelections[wasSection]) _bulkSelections[wasSection].clear();
  document.body.classList.remove('bulk-select-mode');
  document.body.classList.remove(`bulk-select-mode-${wasSection}`);
  _renderBulkSelectBar();
  if (spec && spec.rerender) spec.rerender();
}

// Toggle a record in the active section's selection set. No-op when not
// in select mode. Called from card/row click handlers via
// `if (isBulkSelectMode(section)) { toggleBulkSelection(section, id); return; }`
function toggleBulkSelection(sectionKey, id) {
  if (_bulkSelectActiveSection !== sectionKey) return;
  const set = _getActiveSelection();
  if (set.has(id)) set.delete(id);
  else             set.add(id);
  _renderBulkSelectBar();
  // Full re-render via the spec — guarantees the visual stays in sync
  // with the selection set regardless of how the section's elements
  // are wrapped (e.g. categories have a wrapped _renderCategoryTile
  // that produced fragile querySelector targets). Cost is minor —
  // dozens of elements at most per section.
  const spec = _getActiveSpec();
  if (spec && spec.rerender) spec.rerender();
}

// "All" button — toggles every currently-visible record in the section.
// Respects the section's filter state via getVisibleIds().
function toggleBulkSelectAll() {
  const spec = _getActiveSpec();
  const set = _getActiveSelection();
  if (!spec || !set) return;
  const visibleIds = spec.getVisibleIds ? spec.getVisibleIds() : [];
  const allSelected = visibleIds.length > 0 && visibleIds.every(id => set.has(id));
  if (allSelected) visibleIds.forEach(id => set.delete(id));
  else             visibleIds.forEach(id => set.add(id));
  _renderBulkSelectBar();
  if (spec.rerender) spec.rerender();
}

// Floating bottom bar. Idempotent — creates the element on first call,
// updates innerHTML on subsequent calls. Shared across all sections;
// labels adapt via spec.pluralNoun and spec.canArchive (Archive button
// hidden when the section doesn't support archiving).
// Maps a bulk-select section key to the view container element it should
// mount into. Mounting inside the view container (rather than #main)
// means the bar's auto-margin centers it against the SECTION's
// horizontal extent — which matters because most views (grocery,
// reminders, budget) have max-width 800px and are LEFT-aligned within
// #main (1100px). Centering inside #main offset the bar right of the
// section content. Centering inside the section keeps the bar visually
// under the data.
const _BULK_SECTION_VIEW_HOST = {
  stock:    'view-stock',
  grocery:  'view-grocery',
  reminder: 'view-reminders',
  category: 'view-budget',
};

function _renderBulkSelectBar() {
  let bar = document.getElementById('bulk-select-bar');
  if (!_bulkSelectActiveSection) {
    if (bar) bar.remove();
    return;
  }
  const spec = _getActiveSpec();
  const set  = _getActiveSelection();
  if (!spec || !set) return;
  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'bulk-select-bar';
    bar.className = 'bulk-select-bar';
    // Mount inside the active section's view container so the bar
    // centers against the section content (which is left-anchored at
    // ~800px inside #main's 1100px). Falls back to #main, then body,
    // if the view container isn't mounted — defensive.
    const viewId = _BULK_SECTION_VIEW_HOST[_bulkSelectActiveSection];
    const host   = (viewId && document.getElementById(viewId))
                || document.getElementById('main')
                || document.body;
    host.appendChild(bar);
  }
  const n = set.size;
  const noun = (n === 1) ? spec.noun : spec.pluralNoun;
  const disabled = n === 0 ? 'disabled style="opacity:0.5;cursor:not-allowed"' : '';
  const archiveBtn = spec.applyArchive
    ? `<button class="btn btn-ghost btn-sm" ${disabled} onclick="bulkArchive()" title="Archive selected"><svg class="icon" aria-hidden="true"><use href="#i-archive"></use></svg> Archive</button>`
    : '';
  // Delete button is optional too — sections like categories prefer to
  // route destructive removal through Archive (with hard-delete only
  // available per-record after archive). Omitting applyDelete from the
  // spec hides the Delete button automatically.
  const deleteBtn = spec.applyDelete
    ? `<button class="btn btn-ghost btn-sm" ${disabled} onclick="bulkDelete()" title="Delete selected" style="color:var(--danger)"><svg class="icon" aria-hidden="true"><use href="#i-trash-2"></use></svg> Delete</button>`
    : '';
  bar.innerHTML = `
    <div class="bulk-select-bar-count">${n} ${noun} selected</div>
    <button class="btn btn-ghost btn-sm" onclick="toggleBulkSelectAll()" title="Toggle select all">All</button>
    <button class="btn btn-ghost btn-sm" ${disabled} onclick="bulkShare()" title="Share selected"><svg class="icon" aria-hidden="true"><use href="#i-share-2"></use></svg> Share</button>
    ${archiveBtn}
    ${deleteBtn}
    <button class="btn btn-ghost btn-sm" onclick="exitBulkSelectMode()" title="Exit selection">Cancel</button>
  `;
}

async function bulkDelete() {
  const spec = _getActiveSpec();
  const set  = _getActiveSelection();
  if (!spec || !set || !set.size) return;
  if (spec.permCheck && !spec.permCheck()) return;
  // Optional section-specific pre-flight. Lets the section refuse the
  // bulk delete with a custom message (e.g. groceries: "can't delete
  // your only list"). Returns {ok, reason}.
  if (spec.preDeleteCheck) {
    const check = spec.preDeleteCheck([...set]);
    if (!check.ok) { toast(check.reason || `Can't delete those right now`); return; }
  }
  const n = set.size;
  const noun = (n === 1) ? spec.noun : spec.pluralNoun;
  // Spec opts into a different confirm message when delete is permanent
  // (e.g. budget transactions which use tombstones — no recycle bin).
  const confirmMsg = spec.deleteIsPermanent
    ? `Delete ${n} ${noun}? This can't be undone.`
    : `Move ${n} ${noun} to the recycle bin?\n\nYou can restore them within 30 days.`;
  if (!confirm(confirmMsg)) return;
  const ids = [...set];
  for (const id of ids) {
    const rec = spec.findRecord(id);
    if (!rec) continue;
    spec.applyDelete(rec);
  }
  await spec.save();
  exitBulkSelectMode();
  if (spec.rerender) spec.rerender();
  _syncQueue?.enqueue?.('Updating…');
  const toastMsg = spec.deleteIsPermanent
    ? `Deleted ${n} ${noun}`
    : `Moved ${n} ${noun} to recycle bin`;
  toast(toastMsg);
}

async function bulkArchive() {
  const spec = _getActiveSpec();
  const set  = _getActiveSelection();
  if (!spec || !set || !set.size) return;
  if (!spec.applyArchive) return; // Should not reach here — button hidden
  if (spec.permCheck && !spec.permCheck()) return;
  const n = set.size;
  const noun = (n === 1) ? spec.noun : spec.pluralNoun;
  const ids = [...set];
  for (const id of ids) {
    const rec = spec.findRecord(id);
    if (!rec) continue;
    spec.applyArchive(rec);
  }
  await spec.save();
  exitBulkSelectMode();
  if (spec.rerender) spec.rerender();
  _syncQueue?.enqueue?.();
  toast(`Archived ${n} ${noun}`);
}

// Open the bulk-share modal. Lists existing shares (each clickable to
// append) plus a "Create new share" CTA. Modal text adapts to the
// section's noun ("Share 3 items" / "Share 3 lists" / etc).
function bulkShare() {
  const spec = _getActiveSpec();
  const set  = _getActiveSelection();
  if (!spec || !set || !set.size) return;
  if (!isOwner()) { toast('Only the owner can share'); return; }
  const n = set.size;
  const noun = (n === 1) ? spec.noun : spec.pluralNoun;
  const existing = Array.isArray(_shareTargets) ? _shareTargets.filter(t => !t._deletedAt) : [];

  document.getElementById('bulk-share-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'bulk-share-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:650;background:rgba(0,0,0,0.7);display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(4px)';
  _hideFabForCustomOverlay(overlay);

  const existingRows = existing.length ? existing.map(t => `
    <div onclick="bulkShareAppendToExisting('${t.code}')" style="display:flex;align-items:center;gap:12px;padding:12px;background:var(--surface2);border:1px solid var(--border);border-radius:10px;margin-bottom:8px;cursor:pointer" onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='var(--border)'">
      <div style="width:32px;height:32px;border-radius:50%;background:${esc(t.colour||'var(--accent)')};display:flex;align-items:center;justify-content:center;color:#111;font-weight:700;font-size:13px;flex-shrink:0">${esc((t.name||'?').charAt(0).toUpperCase())}</div>
      <div style="flex:1;min-width:0">
        <div style="font-size:14px;font-weight:600;color:var(--text)">${esc(t.name)}</div>
        <div style="font-size:11px;color:var(--muted);font-family:var(--mono)">${esc(t.guestEmail||'(no email)')}</div>
      </div>
      <svg class="icon icon-sm" aria-hidden="true" style="color:var(--muted)"><use href="#i-plus"></use></svg>
    </div>`).join('') : `<p style="font-size:13px;color:var(--muted);font-style:italic;padding:8px 4px;margin:0">No existing shares yet.</p>`;

  overlay.innerHTML = `
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:16px;width:100%;max-width:480px;max-height:80vh;display:flex;flex-direction:column;box-shadow:0 12px 48px rgba(0,0,0,0.5)">
      <div style="padding:18px 18px 12px;border-bottom:1px solid var(--border)">
        <h3 style="font-size:17px;font-weight:700;margin:0 0 4px 0"><svg class="icon icon-lg" aria-hidden="true" style="color:var(--accent);vertical-align:-3px"><use href="#i-share-2"></use></svg> Share ${n} ${esc(noun)}</h3>
        <p style="font-size:12px;color:var(--muted);margin:0">Append to an existing share, or create a new one — recipients will see ONLY ${spec.pluralNoun==='items'?'these items':'this'}.</p>
      </div>
      <div style="flex:1;overflow-y:auto;padding:14px 18px">
        ${existing.length ? `<div style="font-size:11px;color:var(--muted);font-family:var(--mono);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px">Add to existing share</div>` : ''}
        ${existingRows}
        <button onclick="bulkShareCreateNew()" style="width:100%;padding:13px;border-radius:10px;border:1px dashed var(--accent);background:transparent;color:var(--accent);font-size:13px;font-weight:600;cursor:pointer;margin-top:8px;display:flex;align-items:center;justify-content:center;gap:6px">
          <svg class="icon" aria-hidden="true"><use href="#i-plus"></use></svg> Create new share with ${spec.pluralNoun==='items'?'these items':'this selection'}
        </button>
      </div>
      <div style="padding:12px 18px;border-top:1px solid var(--border);display:flex;justify-content:flex-end">
        <button class="btn btn-ghost btn-sm" onclick="document.getElementById('bulk-share-overlay').remove()">Cancel</button>
      </div>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
}

// Merge shareCode into each selected record's share.allow. Items already
// explicitly denied to this share are skipped (count flagged in toast).
async function bulkShareAppendToExisting(shareCode) {
  document.getElementById('bulk-share-overlay')?.remove();
  const spec = _getActiveSpec();
  const set  = _getActiveSelection();
  if (!spec || !set || !set.size) return;
  const ids = [...set];
  const now = new Date().toISOString();
  let appended = 0;
  let alreadyDenied = 0;
  for (const id of ids) {
    const rec = spec.findRecord(id);
    if (!rec) continue;
    if (typeof rec.share === 'object' && Array.isArray(rec.share?.deny) && rec.share.deny.includes(shareCode)) {
      alreadyDenied++;
      continue;
    }
    if (rec.share == null) {
      rec.share = { allow: [shareCode] };
    } else if (typeof rec.share === 'object') {
      const allow = Array.isArray(rec.share.allow) ? rec.share.allow : [];
      if (!allow.includes(shareCode)) allow.push(shareCode);
      rec.share.allow = allow;
    } else if (rec.share === 'private') {
      rec.share = { allow: [shareCode] };
    }
    rec.updatedAt = now;
    appended++;
  }
  await spec.save();
  exitBulkSelectMode();
  if (spec.rerender) spec.rerender();
  _syncQueue?.enqueue?.('Updating sharing…');
  try { await pushSharedData(shareCode); } catch(_) {}
  const tgt = _shareTargets.find(t => t.code === shareCode);
  const recName = tgt?.name || 'share';
  const noun = (appended === 1) ? spec.noun : spec.pluralNoun;
  let msg = `Added ${appended} ${noun} to ${recName}`;
  if (alreadyDenied) msg += ` · ${alreadyDenied} skipped (explicitly denied)`;
  toast(msg);
}

// Pre-configures the share-target-modal for the bulk-share path: section
// perm set to 'r' so the recipient can see the selected records; other
// sections set to 'none'. Banner inserted, role/perms/mgmt rows hidden.
function bulkShareCreateNew() {
  document.getElementById('bulk-share-overlay')?.remove();
  const spec = _getActiveSpec();
  const set  = _getActiveSelection();
  if (!spec || !set || !set.size) return;
  // Capture the selection AND the active section — exitBulkSelectMode
  // clears the live state, so saveShareTarget needs both pieces.
  _bulkShareSelectionPending = {
    section: _bulkSelectActiveSection,
    ids: [...set],
  };
  openAddShareTarget();
  setTimeout(() => {
    const targetPerm = spec.sectionPermKey;
    const hhKeys = Object.keys(_shareTargetPerms || {});
    const blankPerms = { stockroom: 'none', groceries: 'none', reminders: 'none', budget: 'none' };
    if (!hhKeys.length) {
      _shareTargetPerms = { default: { ...blankPerms, [targetPerm]: 'r' } };
    } else {
      for (const k of hhKeys) {
        _shareTargetPerms[k] = { ...blankPerms, [targetPerm]: 'r' };
      }
    }
    if (typeof renderShareHouseholdPerms === 'function') renderShareHouseholdPerms();
    // Hide the sections that don't apply to "share these specific records"
    const _row1 = document.getElementById('share-target-role-row');
    const _row2 = document.getElementById('share-target-perms-row');
    const _row3 = document.getElementById('share-target-mgmt-row');
    if (_row1) _row1.style.display = 'none';
    if (_row2) _row2.style.display = 'none';
    if (_row3) _row3.style.display = 'none';
    _shareTargetMgmt = 'none';
    // Banner
    const modal = document.getElementById('share-target-modal');
    let banner = document.getElementById('bulk-share-pending-banner');
    if (modal && !banner) {
      const n = _bulkShareSelectionPending.ids.length;
      const nounLabel = (n === 1) ? spec.noun : spec.pluralNoun;
      banner = document.createElement('div');
      banner.id = 'bulk-share-pending-banner';
      banner.style.cssText = 'margin:0 0 12px 0;padding:10px 12px;background:rgba(232,168,56,0.08);border:1px solid rgba(232,168,56,0.3);border-radius:8px;font-size:12px;color:var(--text);line-height:1.4';
      banner.innerHTML = `<svg class="icon icon-sm" aria-hidden="true" style="color:var(--accent);vertical-align:-2px"><use href="#i-share-2"></use></svg> Sharing <strong>${n} selected ${nounLabel}</strong>. Section perms are pre-set; the recipient will see only ${spec.pluralNoun==='items'?'these items':'this selection'}.`;
      const modalEl = modal.querySelector('.modal');
      if (modalEl) modalEl.insertBefore(banner, modalEl.firstChild?.nextSibling || null);
    }
  }, 30);
}

// Pending bulk-share state — set by bulkShareCreateNew, consumed by
// saveShareTarget after a successful create. Cleared on cancel or save.
let _bulkShareSelectionPending = null;

// Cancel path for the share-target-modal. Clears bulk-share pending so
// the next normal share-create doesn't accidentally apply the previous
// pending allow-list.
function _cancelShareTargetModal() {
  _bulkShareSelectionPending = null;
  document.getElementById('bulk-share-pending-banner')?.remove();
  closeModal('share-target-modal');
}

// Apply pending bulk-share allow-list overrides. Called from
// saveShareTarget after a new share is created and data.code is known.
// Dispatches to the right section spec — works for stock, groceries,
// reminders, transactions, etc — because the spec carries findRecord/save.
async function _applyBulkSharePending(newShareCode) {
  if (!_bulkShareSelectionPending) return;
  const { ids, section } = _bulkShareSelectionPending;
  _bulkShareSelectionPending = null;
  if (!Array.isArray(ids) || !ids.length) return;
  const spec = _BULK_SELECT_SECTIONS[section];
  if (!spec) { console.warn('[bulk-share] unknown section for pending:', section); return; }
  const now = new Date().toISOString();
  for (const id of ids) {
    const rec = spec.findRecord(id);
    if (!rec) continue;
    if (rec.share == null) {
      rec.share = { allow: [newShareCode] };
    } else if (typeof rec.share === 'object') {
      const allow = Array.isArray(rec.share.allow) ? rec.share.allow : [];
      if (!allow.includes(newShareCode)) allow.push(newShareCode);
      rec.share.allow = allow;
    } else if (rec.share === 'private') {
      rec.share = { allow: [newShareCode] };
    }
    rec.updatedAt = now;
  }
  await spec.save();
  if (spec.rerender) spec.rerender();
  try { await pushSharedData(newShareCode); } catch(_) {}
  const noun = (ids.length === 1) ? spec.noun : spec.pluralNoun;
  toast(`✓ Shared ${ids.length} ${noun}`);
}

// Register Stockroom (Pass 1 → 2a) as the first section. Other sections
// register themselves alongside their own editor code in passes 2b/c/d.
registerBulkSelectSection('stock', {
  findRecord:    (id) => items.find(i => i.id === id),
  save:          ()   => saveData(),
  rerender:      ()   => scheduleRender('grid', 'dashboard'),
  getVisibleIds: ()   => Array.from(document.querySelectorAll('#items-grid [data-bulk-id]'))
                          .map(el => el.getAttribute('data-bulk-id'))
                          .filter(Boolean),
  permCheck:     ()   => {
    if (!canWrite('stockroom')) { showLockBanner('stockroom'); return false; }
    return true;
  },
  applyDelete:   (item) => {
    item._deletedAt = new Date().toISOString();
    if (typeof touchField === 'function') { try { touchField(item, '_deletedAt'); } catch(_) {} }
  },
  applyArchive:  (item) => {
    item._archived = true;
    item.updatedAt = new Date().toISOString();
  },
  sectionPermKey: 'stockroom',
  noun:           'item',
  pluralNoun:     'items',
});

// ─── Stockroom-specific entry-point shim (Pass 2a compat) ────────────
// The toolbar's "Select" button calls enterStockSelectMode — keep that
// name working without changing the HTML.
function enterStockSelectMode() { enterBulkSelectMode('stock'); }
// Old name kept for the onCardClick interceptor — see comment there.
function exitStockSelectMode()  { exitBulkSelectMode(); }

// Tap-to-toggle wrapper used by every section's Manage button. First tap
// puts the section into bulk-select mode; a second tap on the same button
// exits it. Without this users had no obvious way to back out short of
// hitting Cancel in the floating action bar — and several reported that
// the Manage button "didn't seem to do anything" when they tapped it a
// second time. Defers to the existing enter/exit helpers so per-section
// rerender logic and permission gating stay in one place.
function toggleBulkSelectMode(sectionKey) {
  if (isBulkSelectMode(sectionKey)) {
    exitBulkSelectMode();
  } else {
    enterBulkSelectMode(sectionKey);
  }
}

// Stockroom variant — mirrors enterStockSelectMode for the toolbar button.
function toggleStockSelectMode() { toggleBulkSelectMode('stock'); }



async function archiveItem(id) {
  if (!canWrite('stockroom')) { showLockBanner('stockroom'); return; }
  const item = items.find(i => i.id === id);
  if (!item) return;
  const before = JSON.parse(JSON.stringify(item));
  item._archived  = true;
  item.updatedAt  = new Date().toISOString();
  await saveData();
  scheduleRender('grid', 'dashboard');
  _syncQueue.enqueue();
  historyRecord({
    type: 'archive',
    domain: 'item',
    recordId: item.id,
    recordName: item.name,
    before,
    after: JSON.parse(JSON.stringify(item)),
    undo: async () => { await restoreItem(item.id); },
    redo: async () => { await archiveItem(item.id); },
  });
  toastWithUndo(`"${item.name}" archived`);
}

async function restoreItem(id) {
  if (!canWrite('stockroom')) { showLockBanner('stockroom'); return; }
  const item = items.find(i => i.id === id);
  if (!item) return;
  const before = JSON.parse(JSON.stringify(item));
  delete item._archived;
  item.updatedAt = new Date().toISOString();
  await saveData();
  scheduleRender('grid', 'dashboard');
  _syncQueue.enqueue();
  historyRecord({
    type: 'unarchive',
    domain: 'item',
    recordId: item.id,
    recordName: item.name,
    before,
    after: JSON.parse(JSON.stringify(item)),
    undo: async () => { await archiveItem(item.id); },
    redo: async () => { await restoreItem(item.id); },
  });
  toastWithUndo(`"${item.name}" restored`);
}

async function deleteItem(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;
  if (!confirm(
    `Move "${item.name}" to recycle bin?\n\n` +
    `You can restore it within 30 days from the bottom of the Stockroom view.`
  )) return;
  const before = JSON.parse(JSON.stringify(item));
  item._deletedAt = new Date().toISOString();
  if (typeof touchField === 'function') {
    try { touchField(item, '_deletedAt'); } catch(e) {}
  }
  await saveData();
  closeModal('item-modal');
  scheduleRender('grid', 'dashboard', 'shopping');
  historyRecord({
    type: 'delete',
    domain: 'item',
    recordId: item.id,
    recordName: item.name,
    before,
    after: null,
    undo: async () => { await restoreItemFromBin(item.id); },
    redo: async () => {
      // Re-soft-delete without the confirm prompt
      const it = items.find(i => i.id === item.id);
      if (!it) return;
      it._deletedAt = new Date().toISOString();
      if (typeof touchField === 'function') { try { touchField(it, '_deletedAt'); } catch(_) {} }
      await saveData();
      scheduleRender('grid', 'dashboard', 'shopping');
      _syncQueue.enqueue();
    },
  });
  toastWithUndo(`"${item.name}" moved to recycle bin`);
  _maybeShowBinHint('items');
  _syncQueue.enqueue('Updating…');
}

async function restoreItemFromBin(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;
  const before = JSON.parse(JSON.stringify(item));
  delete item._deletedAt;
  if (typeof touchField === 'function') {
    try { touchField(item, '_deletedAt'); } catch(e) {}
  }
  await saveData();
  scheduleRender('grid', 'dashboard', 'shopping');
  historyRecord({
    type: 'restore',
    domain: 'item',
    recordId: item.id,
    recordName: item.name,
    before,
    after: JSON.parse(JSON.stringify(item)),
    undo: async () => {
      // Re-delete without the confirm prompt
      const it = items.find(i => i.id === item.id);
      if (!it) return;
      it._deletedAt = new Date().toISOString();
      if (typeof touchField === 'function') { try { touchField(it, '_deletedAt'); } catch(_) {} }
      await saveData();
      scheduleRender('grid', 'dashboard', 'shopping');
      _syncQueue.enqueue();
    },
    redo: async () => { await restoreItemFromBin(item.id); },
  });
  toastWithUndo(`"${item.name}" restored from recycle bin`);
  _syncQueue.enqueue('Updating…');
}

async function purgeItemForever(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;
  if (!confirm(
    `Permanently delete "${item.name}"?\n\n` +
    `Removes the item from the recycle bin. You can still restore it from Settings → Change History within the next 50 changes.`
  )) return;
  // Snapshot the full record BEFORE we remove it so restoreFromHistory
  // has the data it needs to reconstruct the item later.
  const before = JSON.parse(JSON.stringify(item));
  items = items.filter(i => i.id !== id);
  await addTombstone(id);
  await saveData();
  scheduleRender('grid', 'dashboard', 'shopping');
  historyRecord({
    type: 'purge',
    domain: 'item',
    recordId: before.id,
    recordName: before.name,
    before,
    after: null,
    // Cmd+Z reinserts the record and removes the tombstone
    undo: async () => {
      items.push({ ...before, updatedAt: new Date().toISOString() });
      if (typeof removeTombstone === 'function') {
        try { await removeTombstone(before.id); } catch (_) {}
      }
      await saveData();
      scheduleRender('grid', 'dashboard', 'shopping');
      _syncQueue.enqueue();
    },
    // Redo re-purges without the confirm
    redo: async () => {
      items = items.filter(i => i.id !== before.id);
      await addTombstone(before.id);
      await saveData();
      scheduleRender('grid', 'dashboard', 'shopping');
      _syncQueue.enqueue();
    },
  });
  toastWithUndo(`"${item.name}" permanently deleted`);
  _syncQueue.enqueue('Updating…');
}

async function emptyItemsBin() {
  const trashed = items.filter(_isInRecycleBin);
  if (!trashed.length) return;
  if (!confirm(
    `Permanently delete ${trashed.length} item${trashed.length===1?'':'s'} from the recycle bin? This cannot be undone.`
  )) return;
  for (const it of trashed) await addTombstone(it.id);
  items = items.filter(i => !_isInRecycleBin(i));
  await saveData();
  scheduleRender('grid', 'dashboard', 'shopping');
  toast('Recycle bin emptied');
  _syncQueue.enqueue('Updating…');
}

