// Keyword map for auto-department detection
const DEPT_KEYWORDS = {
  'bakery':     ['bread','loaf','roll','baguette','bagel','pitta','crumpet','muffin','croissant','brioche','sourdough','toast','wrap','tortilla'],
  'fruit-veg':  ['apple','banana','orange','grape','strawberry','berry','lemon','lime','mango','pear','peach','plum','melon','pineapple','kiwi','avocado','tomato','potato','carrot','onion','garlic','spinach','lettuce','cucumber','pepper','courgette','broccoli','cauliflower','celery','mushroom','leek','asparagus','kale','cabbage','salad','herb','coriander','parsley','basil','mint','ginger','sweetcorn','corn','pea','bean','lentil'],
  'meat-fish':  ['chicken','beef','pork','lamb','turkey','salmon','tuna','cod','haddock','prawn','shrimp','sausage','bacon','mince','steak','fillet','ham','salami','pepperoni','chorizo','duck','venison','mackerel','sea bass','crab','lobster','fish'],
  'dairy':      ['milk','cheese','butter','yogurt','yoghurt','cream','cheddar','mozzarella','brie','camembert','feta','eggs','egg','margarine','flora','crème fraîche','soured cream','quark','ricotta'],
  'frozen':     ['frozen','ice cream','ice lolly','pizza','chips','waffles','nuggets','burger','oven ready'],
  'drinks':     ['juice','water','coffee','tea','wine','beer','lager','cider','spirit','gin','vodka','rum','whisky','cola','pepsi','coke','fanta','sprite','squash','cordial','smoothie','energy drink','oat milk','almond milk','soy milk'],
  'snacks':     ['crisp','chip','nuts','biscuit','cookie','chocolate','sweet','candy','popcorn','pretzel','cracker','rice cake','granola bar','cereal bar','flapjack'],
  'cupboard':   ['pasta','rice','flour','sugar','oil','vinegar','sauce','ketchup','mustard','mayo','mayonnaise','salt','pepper','spice','herb','stock','gravy','tin','can','soup','beans','chickpea','lentils','noodle','cereal','oat','porridge','jam','honey','syrup','spread','peanut butter','coffee','tea','cocoa','breadcrumb','stuffing'],
  'household':  ['washing','detergent','cleaner','bleach','sponge','cloth','toilet','kitchen roll','tissue','bin bag','clingfilm','foil','parchment','zip bag','mop','brush','nappy','baby wipe'],
  'toiletries': ['soap','shampoo','conditioner','deodorant','toothbrush','toothpaste','razor','shower gel','body wash','moisturiser','lotion','sunscreen','face wash','cotton','floss','mouthwash','lip balm','perfume','aftershave','nail','pad','tampon','sanitary'],
  'baby-care':  ['nappy','baby formula','baby food','dummy','baby bottle','baby wipe','baby lotion'],
};

// Parse a grocery item name like "2 Yoghurts", "Yoghurts x 2", "Apples (3)"
// into { name, qty }. Returns { name: trimmed, qty: 1 } if no quantity is
// confidently detectable. Conservative — we don't want to strip "2L Milk".
const _GROCERY_UNIT_TOKENS = ['g','kg','mg','ml','l','oz','lb','%','cl','dl','floz','tsp','tbsp','cup','cups','pack','packs','pk','ct'];
function parseGroceryQty(raw) {
  const original = (raw || '').trim();
  if (!original) return { name: '', qty: 1 };

  // Pattern A — trailing "x N" or "× N" (most explicit)
  // e.g. "Yoghurts x 2", "Apples × 3", "Bread x2"
  let m = original.match(/^(.+?)\s*[x×X]\s*(\d{1,3})\s*$/);
  if (m) {
    const n = parseInt(m[2], 10);
    if (n >= 1 && n <= 999) return { name: m[1].trim(), qty: n };
  }

  // Pattern B — trailing "(N)"
  // e.g. "Yoghurts (2)"
  m = original.match(/^(.+?)\s*\((\d{1,3})\)\s*$/);
  if (m) {
    const n = parseInt(m[2], 10);
    if (n >= 1 && n <= 999) return { name: m[1].trim(), qty: n };
  }

  // Pattern C — leading "N x Name" or "Nx Name"
  // e.g. "3 x Apples", "3x Apples"
  m = original.match(/^(\d{1,3})\s*[x×X]\s+(.+)$/);
  if (m) {
    const n = parseInt(m[1], 10);
    if (n >= 1 && n <= 999) return { name: m[2].trim(), qty: n };
  }

  // Pattern D — leading number followed by a word that ISN'T a unit
  // e.g. "2 Yoghurts" → qty 2, "500g Flour" → no extraction (g is a unit)
  // Also reject "2L Milk" (digit immediately followed by letters means a unit-like token)
  m = original.match(/^(\d{1,3})\s+([A-Za-z].*)$/);
  if (m) {
    const rest = m[2].trim();
    // Check if the first word of `rest` is a unit token — if so, don't extract
    const firstWord = (rest.split(/\s+/)[0] || '').toLowerCase().replace(/[.,;:]$/, '');
    if (!_GROCERY_UNIT_TOKENS.includes(firstWord)) {
      const n = parseInt(m[1], 10);
      if (n >= 1 && n <= 999) return { name: rest, qty: n };
    }
  }

  return { name: original, qty: 1 };
}

function detectDepartment(name) {
  const lower = name.toLowerCase();
  for (const [deptId, keywords] of Object.entries(DEPT_KEYWORDS)) {
    if (keywords.some(kw => lower.includes(kw))) return deptId;
  }
  return 'other';
}

function openGroceryImport() {
  openModal('grocery-import-info-modal');
}

async function pasteGroceryImport() {
  closeModal('grocery-import-info-modal');
  try {
    const text = await navigator.clipboard.readText();
    if (!text || !text.trim()) { toast('Clipboard is empty'); return; }
    const raw = text.split(/[\n\r,;]+/)
      .map(s => s.replace(/["']/g, '').trim())
      .filter(s => s.length > 1 && s.length < 200);
    const unique = [...new Set(raw)];
    if (!unique.length) { toast('No items found in clipboard text'); return; }
    buildGroceryImportReview(unique);
  } catch(e) {
    toast('Cannot read clipboard — try choosing a file instead');
  }
}

function handleGroceryImportFile(e) {
  const file = e.target.files[0];
  if (!file) return;
  e.target.value = '';
  const ext = file.name.split('.').pop().toLowerCase();
  const reader = new FileReader();

  reader.onerror = () => toast('Could not read file');

  reader.onload = ev => {
    let text = '';
    const result = ev.target.result;

    if (ext === 'xml') {
      // Parse XML and extract all text nodes
      try {
        const parser = new DOMParser();
        const doc    = parser.parseFromString(result, 'text/xml');
        const walker = document.createTreeWalker(doc, NodeFilter.SHOW_TEXT);
        const parts  = [];
        let node;
        while ((node = walker.nextNode())) {
          const t = node.textContent.trim();
          if (t) parts.push(t);
        }
        text = parts.join('\n');
      } catch(e) { text = result; }

    } else if (ext === 'rtf') {
      // Strip RTF control words, keep readable text
      text = result
        .replace(/\\[a-z]+\d*\s?/g, ' ')
        .replace(/[{}\\]/g, ' ')
        .replace(/\s+/g, '\n');

    } else if (ext === 'md') {
      // Extract bullet list items and headings stripped
      text = result
        .split('\n')
        .map(l => l.replace(/^[\s]*[-*+]\s+/, '').replace(/^#{1,6}\s+/, '').trim())
        .filter(Boolean)
        .join('\n');

    } else if (ext === 'docx' || ext === 'doc') {
      // docx is a zip — extract readable text via raw read
      // For binary formats, convert result bytes to string and pull any readable sequences
      const bytes = new Uint8Array(result);
      const chunks = [];
      let current = '';
      for (let i = 0; i < bytes.length; i++) {
        const b = bytes[i];
        if (b >= 32 && b < 127) {
          current += String.fromCharCode(b);
        } else if (current.length >= 3) {
          chunks.push(current.trim());
          current = '';
        } else {
          current = '';
        }
      }
      if (current.length >= 3) chunks.push(current.trim());
      // Filter out XML/binary noise, keep human-readable word-like chunks
      text = chunks
        .filter(s => /^[A-Za-z]/.test(s) && !/^(xml|http|rId|docx|rels|word|type|xmlns|Content|Relation|Target|schema|xmlns)/i.test(s))
        .join('\n');

    } else {
      // Plain text: txt, csv, tsv, text, fallback
      text = typeof result === 'string' ? result : new TextDecoder().decode(result);
    }

    // Split on newlines, tabs, or commas
    const sep = ext === 'tsv' ? /[\t\n\r]+/ : /[\n\r,;]+/;
    const raw = text.split(sep)
      .map(s => s.replace(/["']/g, '').trim())   // strip quotes
      .filter(s => s.length > 1 && s.length < 200 && !/^[<>\[\]{}&|\\\/]/.test(s));

    const unique = [...new Set(raw)]; // deduplicate
    if (!unique.length) { toast('No items found in file — try a plain text file with one item per line'); return; }
    buildGroceryImportReview(unique);
  };

  // docx/doc need binary read
  if (ext === 'docx' || ext === 'doc') {
    reader.readAsArrayBuffer(file);
  } else {
    reader.readAsText(file);
  }
}

// Holds pending import items during review
let _groceryImportDraft = [];

function buildGroceryImportReview(names) {
  _groceryImportDraft = names.map(name => ({
    name,
    department: detectDepartment(name),
    notes: '',
  }));

  renderGroceryImportList();
  const btn = document.getElementById('grocery-import-confirm-btn');
  if (btn) btn.textContent = `✓ Add ${_groceryImportDraft.length} item${_groceryImportDraft.length !== 1 ? 's' : ''}`;
  openModal('grocery-import-modal');
}

function renderGroceryImportList() {
  const container = document.getElementById('grocery-import-list');
  if (!container) return;

  const depts = groceryDepts.length ? groceryDepts : DEFAULT_DEPTS;

  container.innerHTML = _groceryImportDraft.map((item, i) => {
    const deptInfo = depts.find(d => d.id === item.department) || { emoji: '📦', name: 'Other' };
    const deptOptions = depts.map(d =>
      `<option value="${esc(d.id)}" ${d.id === item.department ? 'selected' : ''}>${d.emoji} ${esc(d.name)}</option>`
    ).join('');

    return `<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:10px 12px;display:flex;flex-direction:column;gap:6px" id="gi-row-${i}">
      <div style="display:flex;gap:8px;align-items:center">
        <input type="text" value="${esc(item.name)}"
          style="flex:1;background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:6px 8px;color:var(--text);font-size:13px;font-weight:600"
          oninput="_groceryImportDraft[${i}].name=this.value"
          placeholder="Item name">
        <button onclick="removeGroceryImportRow(${i})"
          style="background:none;border:none;cursor:pointer;color:var(--muted);font-size:18px;padding:2px 4px;flex-shrink:0"
          title="Remove this item"><svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg></button>
      </div>
      <div style="display:flex;gap:8px;align-items:center">
        <select style="flex:1;background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);font-size:12px"
          onchange="_groceryImportDraft[${i}].department=this.value">
          ${deptOptions}
        </select>
        <input type="text" value="${esc(item.notes)}"
          style="flex:1;background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--muted);font-size:12px"
          placeholder="Note (optional)"
          oninput="_groceryImportDraft[${i}].notes=this.value">
      </div>
    </div>`;
  }).join('');
}

function removeGroceryImportRow(i) {
  _groceryImportDraft.splice(i, 1);
  renderGroceryImportList();
  const btn = document.getElementById('grocery-import-confirm-btn');
  if (btn) btn.textContent = `✓ Add ${_groceryImportDraft.length} item${_groceryImportDraft.length !== 1 ? 's' : ''}`;
  if (_groceryImportDraft.length === 0) closeModal('grocery-import-modal');
}

async function confirmGroceryImport() {
  const valid = _groceryImportDraft.filter(item => item.name.trim().length > 0);
  if (!valid.length) { toast('No items to add'); return; }

  const now = new Date().toISOString();
  valid.forEach(item => {
    // Skip duplicates (same name, case-insensitive)
    const exists = groceryItems.some(g => g.name.toLowerCase() === item.name.trim().toLowerCase());
    if (!exists) {
      const newId = 'g_' + Date.now() + '_' + Math.random().toString(36).slice(2,6);
      groceryItems.push({
        id:         newId,
        name:       item.name.trim(),
        department: item.department || 'other',
        notes:      item.notes.trim(),
        recurring:  false,
        intervalDays: 0,
        checked:    false,
        addedAt:    now,
        updatedAt:  now,
      });
      appendToGroceryOrder(newId);
    }
  });

  closeModal('grocery-import-modal');
  _groceryImportDraft = [];
  await saveGrocery();
  renderGrocery();
  toast(`${valid.length} item${valid.length !== 1 ? 's' : ''} added to grocery list ✓`);
}

function renderGrocery() {
  // Previously this read from two inline search inputs (#grocery-search on
  // desktop, #grocery-fs-search-input on mobile FS). Both were removed when
  // the global search took over — searching groceries now happens via the
  // global search modal. `query` is kept as a const here so the existing
  // filter call sites (`!query || …`) stay valid without a wider sweep.
  const query = '';
  const body  = document.getElementById('grocery-list-body');
  const checkedBar = document.getElementById('grocery-checked-bar');
  if (!body) return;

  // ── Multi-list picker vs active-list view ──
  // Picker view: shown when 2+ lists exist AND no list is currently open.
  // Active view: shown when a list is open (single-list users always see
  // this — they never get a picker).
  const multiList = groceryLists.length > 1;
  const isPicker  = multiList && !activeGroceryListId;

  // Shared header chrome — the standalone subtitle row and interval-info
  // row were both removed per Pete's request. Their elements are kept in
  // the DOM (set to display:none in index.html) so any straggler writes
  // are invisible rather than throwing. Force-empty here as belt-and-
  // braces so a stale value from an older session can't peek through.
  const _sub = document.getElementById('grocery-subtitle');
  if (_sub) { _sub.textContent = ''; _sub.style.display = 'none'; }
  const _info = document.getElementById('grocery-interval-info');
  if (_info) { _info.textContent = ''; _info.style.display = 'none'; }

  // "← All lists" button slot — only visible when an active list is open
  // AND there are 2+ lists to navigate between. Single-list users have
  // nowhere to go back to. Sits at the left of the action-button cluster.
  const _allListsSlot = document.getElementById('grocery-all-lists-slot');
  if (_allListsSlot) {
    _allListsSlot.style.display = (activeGroceryListId && multiList) ? 'inline-flex' : 'none';
  }

  // Bulk-select entry slot (Pass 2b) — only visible in the multi-list
  // picker view. When a list is open, the action bar would be ambiguous
  // ("select what?") so we hide it there.
  const _selectSlot = document.getElementById('grocery-select-slot');
  if (_selectSlot) {
    _selectSlot.style.display = (isPicker) ? 'inline-flex' : 'none';
  }

  // Active list name + toolbar visibility — both shown only when a list
  // is open. In the picker the user is choosing a list; sort/edit controls
  // don't apply yet, so we hide them entirely.
  const _activeName = document.getElementById('grocery-active-list-name');
  const _toolbar    = document.querySelector('#view-grocery .grocery-toolbar');
  if (isPicker) {
    if (_activeName) { _activeName.textContent = ''; _activeName.style.display = 'none'; }
    if (_toolbar)    _toolbar.style.display = 'none';
  } else {
    // Single-list or active-list view: write the list name above the
    // toolbar. The phase bar (Stock Check / Start Shopping) renders
    // further below, between the toolbar and the list body.
    const _activeList = groceryLists.find(l => l.id === activeGroceryListId && !l._deletedAt);
    if (_activeName) {
      _activeName.textContent = _activeList?.name || 'List';
      _activeName.style.display = '';
    }
    if (_toolbar) _toolbar.style.display = '';
  }

  // Remove the standalone #grocery-active-toolbar that used to inject a
  // separate "← All lists" button row above the list body. The slot in
  // the header above replaces it.
  const _legacyActiveToolbar = document.getElementById('grocery-active-toolbar');
  if (_legacyActiveToolbar) _legacyActiveToolbar.remove();
  // Remove legacy dynamic back-button if it exists from a previous render
  const legacyBack = document.getElementById('grocery-back-to-lists');
  if (legacyBack) legacyBack.remove();

  // Show list picker if no active list (multi-list mode only)
  if (isPicker) {
    document.body.classList.add('grocery-multilist');
    // Hide single-list-only controls
    const editToggle = document.getElementById('grocery-edit-toggle');
    const addItem    = document.querySelector('#view-grocery .btn-primary[onclick*="openAddGroceryItem"]');
    if (editToggle) editToggle.style.display = 'none';
    if (addItem)    addItem.style.display    = 'none';
    renderGroceryListPicker();
    const _binEl = document.getElementById('grocery-recycle-bin');
    if (_binEl) _binEl.style.display = 'none';
    // Hide any leftover phase bar from a previous active-list render.
    const _phaseBar = document.getElementById('grocery-phase-bar');
    if (_phaseBar) _phaseBar.style.display = 'none';
    return;
  }
  // Single list mode — restore controls
  document.body.classList.remove('grocery-multilist');
  const _editToggle = document.getElementById('grocery-edit-toggle');
  const _addItem    = document.querySelector('#view-grocery .btn-primary[onclick*="openAddGroceryItem"]');
  // Hide the Edit button when the active list is empty — there's nothing to
  // edit, and offering the button leads to a fruitless "edit mode" with no
  // rows visible. The +Add Item button stays visible because that's how
  // the user populates an empty list.
  const _activeItemCount = groceryItems.filter(i => !i._deletedAt && (i.listId || 'default') === activeGroceryListId).length;
  if (_editToggle) _editToggle.style.display = (_activeItemCount === 0) ? 'none' : '';
  if (_addItem)    _addItem.style.display    = '';

  cleanGroceryOrder();
  // Hide multi-select bar whenever we re-render
  if (!groceryEditMode) {
    const sb = document.getElementById('grocery-selection-bar');
    if (sb) sb.style.display = 'none';
  }

  // Filter to active list only (exclude soft-deleted)
  let listItems = groceryItems.filter(i => !i._deletedAt && (i.listId || 'default') === activeGroceryListId);

  // ── Stock-check / shopping mode ─────────────────────────────────
  // In shop phase we DON'T filter the list — items the user didn't mark
  // as needed during stock check stay visible, but render as pre-checked
  // (greyed out, struck-through). The user can still tap them to "buy
  // anyway", which un-greys them. This avoids items disappearing without
  // explanation and gives the user an out if they change their mind.
  const _activeList = _activeGroceryList();
  const _mode  = _activeGroceryListMode();
  const _phase = _activeGroceryListPhase();

  // Populate the mobile full-screen header title with the list name. The
  // CSS only shows the FS header on mobile when body.grocery-list-open is
  // set, so this is a cheap write either way.
  const _fsTitle = document.getElementById('grocery-fs-title');
  if (_fsTitle) {
    _fsTitle.textContent = _activeList ? _activeList.name : 'List';
  }

  // Render the phase-control bar (Start Shopping / Done Shopping etc.).
  // It sits between the toolbar and the items so it's always visible.
  _renderGroceryPhaseBar(_activeList, _mode, _phase, listItems);

  // Subtitle line ("78 items · stock check — tap to mark as needed") and
  // interval-info line ("Shopping every 7 days · N items remaining") used
  // to be written here. Both removed per Pete's request — the list name
  // (set in the header switch above) plus the phase bar already convey
  // mode and intent without the extra text rows.

  // Edit mode lock button
  const editBtn = document.getElementById('grocery-edit-toggle');
  if (editBtn) {
    editBtn.innerHTML = groceryEditMode
      ? '<svg class="icon" aria-hidden="true"><use href="#i-lock"></use></svg> Done'
      : '<svg class="icon" aria-hidden="true"><use href="#i-pencil"></use></svg> Edit';
    editBtn.style.background = groceryEditMode ? 'rgba(232,168,56,0.15)' : '';
    editBtn.style.color = groceryEditMode ? 'var(--accent)' : '';
    editBtn.style.borderColor = groceryEditMode ? 'rgba(232,168,56,0.4)' : '';
  }

  let filtered = listItems.filter(i => !query || i.name.toLowerCase().includes(query) || (i.notes||'').toLowerCase().includes(query));
  // In stockcheck-shop phase, by default drop items that weren't marked as
  // needed during stock check — the user has already decided what they're
  // buying; the rest is noise. A phase-bar toggle (groceryHideUnneeded)
  // lets them unhide if they want to grab something on the fly.
  const _inShopPhaseForFilter = _mode === 'stockcheck' && _phase === 'shop';
  if (_inShopPhaseForFilter && groceryHideUnneeded && !groceryEditMode) {
    filtered = filtered.filter(i => _itemIsNeeded(i));
  }
  const unchecked = filtered.filter(i => !i.checked);
  // If hideChecked: hide checked items from main render (they can still be cleared)
  const checked   = groceryHideChecked ? [] : filtered.filter(i => i.checked);

  const checkedCount = groceryItems.filter(i => !i._deletedAt && i.checked).length;
  if (checkedBar) {
    const actualCheckedCount = listItems.filter(i => i.checked).length;
    checkedBar.style.display = !groceryEditMode && actualCheckedCount > 0 && activeGroceryListId ? 'flex' : 'none';
    const cc = document.getElementById('grocery-checked-count');
    if (cc) cc.textContent = `${actualCheckedCount} item${actualCheckedCount===1?'':'s'} checked`;
  }
  // Update hide-checked button state
  const hcBtn = document.getElementById('grocery-hide-checked-btn');
  if (hcBtn) {
    const hasChecked = listItems.some(i => i.checked);
    hcBtn.style.display = hasChecked && !groceryEditMode && activeGroceryListId ? 'inline-flex' : 'none';
    hcBtn.innerHTML = groceryHideChecked ? `<svg class="icon" aria-hidden="true"><use href="#i-eye"></use></svg> Show ticked` : `<svg class="icon" aria-hidden="true"><use href="#i-eye-off"></use></svg> Hide ticked`;
    hcBtn.style.color = groceryHideChecked ? 'var(--accent)' : '';
    hcBtn.style.borderColor = groceryHideChecked ? 'rgba(232,168,56,0.4)' : '';
    hcBtn.style.background = groceryHideChecked ? 'rgba(232,168,56,0.08)' : '';
  }

  if (listItems.length === 0) {
    body.innerHTML = `<div class="grocery-empty">
      <div class="grocery-empty-icon" style="color:var(--accent)"><svg aria-hidden="true" style="width:48px;height:48px"><use href="#i-shopping-cart"></use></svg></div>
      <div style="font-size:16px;font-weight:700;margin-bottom:8px">No items in this list yet</div>
      <div style="font-size:13px;color:var(--muted);margin-bottom:18px">Add items quickly under each department, or use Quick List to paste a comma-separated list.</div>
      <button onclick="quickAddByDepartment()" class="btn btn-primary" style="display:inline-flex;align-items:center;gap:8px">
        <svg class="icon" aria-hidden="true"><use href="#i-zap"></use></svg>
        Quick Add by Department
      </button>
    </div>`;
    return;
  }

  if (filtered.length === 0 && !groceryEditMode) {
    body.innerHTML = `<div class="grocery-empty"><div class="grocery-empty-icon" style="color:var(--muted)"><svg aria-hidden="true" style="width:48px;height:48px"><use href="#i-search"></use></svg></div><div style="font-size:15px;font-weight:600">No matches</div></div>`;
    return;
  }

  // In edit mode: show items in same structure as locked, just with drag handle + delete + inline note
  if (groceryEditMode) {
    const depts = groceryDepts.length ? groceryDepts : DEFAULT_DEPTS;
    const isDeptView = grocerySort === 'dept';
    const canDrag    = isDeptView; // drag only in dept view

    let editHtml = `<div id="grocery-drag-hint" style="font-size:12px;color:var(--muted);padding:6px 0 10px;text-align:center;position:sticky;top:0;z-index:10;background:var(--bg);margin:0 -2px;border-bottom:1px solid rgba(46,51,80,0.3);margin-bottom:8px">
      ${canDrag ? '<svg class="icon" aria-hidden="true"><use href="#i-grip-vertical"></use></svg> Hold and drag to reorder within departments' : 'A–Z view — switch to By Dept to reorder'}
    </div>`;

    const ordered = getGroceryItemsInOrder().filter(i => !i.checked && (!query || i.name.toLowerCase().includes(query) || (i.notes||'').toLowerCase().includes(query)));

    if (isDeptView) {
      // Group by department, same structure as locked view
      const deptMap = {};
      ordered.forEach(item => {
        const d = item.department || 'other';
        if (!deptMap[d]) deptMap[d] = [];
        deptMap[d].push(item);
      });
      const deptOrder = depts.map(d => d.id);
      const extraDepts = [...new Set(ordered.map(i => i.department || 'other'))].filter(d => !deptOrder.includes(d));
      [...deptOrder, ...extraDepts].forEach(deptId => {
        const deptItems = deptMap[deptId];
        if (!deptItems || !deptItems.length) return;
        const deptDef = depts.find(d => d.id === deptId) || {name: deptId, emoji:'📦'};
        editHtml += `<div class="grocery-dept-group">
          <div class="grocery-dept-header">
            <span class="grocery-dept-label">${deptDef.emoji} ${esc(deptDef.name)}</span>
            <span style="display:flex;align-items:center;gap:8px">
              <span class="grocery-dept-count">${deptItems.length}</span>
              <button onclick="event.stopPropagation();addGroceryItemToDept('${deptId}')"
                style="background:none;border:none;cursor:pointer;color:var(--accent);font-size:22px;line-height:1;padding:0 2px;font-weight:300;transition:opacity 0.15s"
                title="Add item to ${deptDef.name}">＋</button>
            </span>
          </div>
          <div class="grocery-edit-dept-group" data-dept="${deptId}">
            ${deptItems.map(item => groceryItemEditHTML(item, depts, canDrag)).join('')}
          </div>
        </div>`;
      });
    } else {
      // A-Z: sorted, no drag
      const sorted = [...ordered].sort((a,b) => a.name.localeCompare(b.name));
      editHtml += `<div class="grocery-edit-dept-group" data-dept="all">
        ${sorted.map(item => groceryItemEditHTML(item, depts, false)).join('')}
      </div>`;
    }

    body.innerHTML = editHtml;
    if (canDrag) initGroceryDragSort();
    return;
  }

  let html = '';

  if (grocerySort === 'dept') {
    // Use manual order within each department group
    const ordered = getGroceryItemsInOrder();
    let filteredOrdered = ordered.filter(i => !query || i.name.toLowerCase().includes(query) || (i.notes||'').toLowerCase().includes(query));
    // Mirror the shop-phase unneeded filter applied above to `filtered`.
    // The dept view doesn't read from `filtered` because it needs to keep
    // checked items per-dept rather than partition them.
    if (_inShopPhaseForFilter && groceryHideUnneeded && !groceryEditMode) {
      filteredOrdered = filteredOrdered.filter(i => _itemIsNeeded(i));
    }

    // Build dept map including both checked and unchecked
    const deptMap = {};
    filteredOrdered.forEach(item => {
      const dept = item.department || 'other';
      if (!deptMap[dept]) deptMap[dept] = { unchecked: [], checked: [] };
      if (item.checked) deptMap[dept].checked.push(item);
      else deptMap[dept].unchecked.push(item);
    });

    const deptOrder = (groceryDepts.length ? groceryDepts : DEFAULT_DEPTS).map(d => d.id);
    const extraDepts = [...new Set(filteredOrdered.map(i => i.department || 'other'))].filter(d => !deptOrder.includes(d));
    const activeDepts = groceryDepts.length ? groceryDepts : DEFAULT_DEPTS;

    [...deptOrder, ...extraDepts].forEach(deptId => {
      const bucket = deptMap[deptId];
      if (!bucket || (bucket.unchecked.length === 0 && bucket.checked.length === 0)) return;
      const deptDef = activeDepts.find(d => d.id === deptId) || {name: deptId, emoji:'📦'};
      const allChecked = bucket.unchecked.length === 0 && bucket.checked.length > 0;
      const totalCount = bucket.unchecked.length + bucket.checked.length;

      // Fully-checked dept: show collapsed with toggle
      if (allChecked) {
        html += `<div class="grocery-dept-group">
          <div class="grocery-dept-header" onclick="_toggleDeptCollapse('${deptId}')" style="cursor:pointer">
            <span class="grocery-dept-label" style="color:var(--muted);text-decoration:line-through">${deptDef.emoji} ${esc(deptDef.name)}</span>
            <span style="display:flex;align-items:center;gap:6px">
              <span class="grocery-dept-count">✓ all ${totalCount}</span>
              <span id="dept-chevron-${deptId}" style="color:var(--muted);font-size:11px;transition:transform 0.2s">▼</span>
            </span>
          </div>
          <div id="dept-body-${deptId}" style="display:none">
            ${bucket.checked.map(item => groceryItemHTML(item)).join('')}
          </div>
        </div>`;
        return;
      }

      // Mixed dept: unchecked first, then checked at bottom of this dept
      html += `<div class="grocery-dept-group">
        <div class="grocery-dept-header">
          <span class="grocery-dept-label">${deptDef.emoji} ${esc(deptDef.name)}</span>
          <span style="display:flex;align-items:center;gap:8px">
            <span class="grocery-dept-count">${bucket.unchecked.length}${bucket.checked.length ? ` · ${bucket.checked.length} done` : ''}</span>
            <button onclick="event.stopPropagation();addGroceryItemToDept('${deptId}')"
              style="background:none;border:none;cursor:pointer;color:var(--accent);font-size:22px;line-height:1;padding:0 2px;font-weight:300;transition:opacity 0.15s"
              title="Add item to ${deptDef.name}">＋</button>
          </span>
        </div>
        ${bucket.unchecked.map(item => groceryItemHTML(item)).join('')}
        ${bucket.checked.length ? `<div style="border-top:1px dashed rgba(46,51,80,0.4);margin-top:2px">${bucket.checked.map(item => groceryItemHTML(item)).join('')}</div>` : ''}
      </div>`;
    });
  } else {
    // Alpha view — sort alphabetically but preserve manual sub-order within same letter
    let ordered = getGroceryItemsInOrder().filter(i => !i.checked && (!query || i.name.toLowerCase().includes(query) || (i.notes||'').toLowerCase().includes(query)));
    // Mirror the shop-phase unneeded filter from the dept view above.
    if (_inShopPhaseForFilter && groceryHideUnneeded && !groceryEditMode) {
      ordered = ordered.filter(i => _itemIsNeeded(i));
    }
    const sorted  = [...ordered].sort((a,b) => a.name.localeCompare(b.name));
    html += sorted.map(item => groceryItemHTML(item)).join('');
  }

  // In alpha view: checked items at bottom (in dept view they're per-dept above)
  if (grocerySort === 'alpha' && checked.length > 0) {
    html += `<div style="margin-top:16px">
      <div class="grocery-dept-header">
        <span class="grocery-dept-label" style="color:var(--muted)">✓ Checked</span>
        <span class="grocery-dept-count">${checked.length}</span>
      </div>
      ${checked.map(item => groceryItemHTML(item)).join('')}
    </div>`;
  }

  body.innerHTML = html;

  // Render Recently Deleted section after the main grocery body
  renderGroceryRecycleBin();
}

function renderGroceryRecycleBin() {
  const body = document.getElementById('grocery-list-body');
  if (!body) return;
  let bin = document.getElementById('grocery-recycle-bin');
  // Per-item recycle bin is intentionally hidden — users find it confusing
  // to see individual ticked-off items here. The "Recently Deleted Lists"
  // section on the All lists picker handles whole-list recovery instead.
  // Soft-delete still happens behind the scenes for sync correctness, just
  // not surfaced. Auto-purge after 30 days continues to apply.
  if (bin) bin.style.display = 'none';
  return;

  if (!bin) {
    bin = document.createElement('div');
    bin.id = 'grocery-recycle-bin';
    bin.className = 'recycle-bin-section';
    bin.setAttribute('data-bin-key', 'grocery-items');
    body.parentNode.insertBefore(bin, body.nextSibling);
  }
  bin.style.display = 'block';
  bin.classList.toggle('recycle-bin-collapsed', _isBinCollapsed('grocery-items'));

  const titleHTML = `
    <div class="recycle-bin-title">
      <svg class="icon icon-md" aria-hidden="true"><use href="#i-trash-2"></use></svg>
      Recently Deleted
      <span class="recycle-bin-count">${trashed.length}</span>
    </div>`;
  const actionHTML = `<button class="btn btn-ghost btn-sm" onclick="emptyGroceryBin()">Empty</button>`;
  const headerHTML = _renderBinHeader('grocery-items', titleHTML, actionHTML)
    + `<div class="recycle-bin-subtitle">Items are permanently deleted after 30 days.</div>`;
  const rowsHTML = trashed.map(item => {
    const days = _daysLeftInBin(item);
    const dept = item.dept ? esc(item.dept) : '';
    return `
      <div class="recycle-bin-row" data-id="${item.id}">
        <div class="recycle-bin-row-info">
          <div class="recycle-bin-row-name">${esc(item.name || 'Untitled')}</div>
          <div class="recycle-bin-row-meta">${dept ? dept + ' · ' : ''}${days} day${days===1?'':'s'} left</div>
        </div>
        <div class="recycle-bin-row-actions">
          <button class="btn btn-ghost btn-sm" onclick="restoreGroceryItem('${item.id}')">Restore</button>
          <button class="btn btn-ghost btn-sm recycle-bin-delete" onclick="purgeGroceryForever('${item.id}')" title="Delete permanently">✕</button>
        </div>
      </div>`;
  }).join('');

  bin.innerHTML = headerHTML + `<div class="recycle-bin-rows">${rowsHTML}</div>`;
}

function _toggleDeptCollapse(deptId) {
  const body    = document.getElementById(`dept-body-${deptId}`);
  const chevron = document.getElementById(`dept-chevron-${deptId}`);
  if (!body) return;
  const isOpen = body.style.display !== 'none';
  body.style.display = isOpen ? 'none' : '';
  if (chevron) chevron.style.transform = isOpen ? '' : 'rotate(180deg)';
}

// Edit mode item — same visual design as locked view, just with drag handle + delete + inline edit
function groceryItemEditHTML(item, depts, canDrag) {
  const deptDef  = depts.find(d => d.id === (item.department||'other')) || {name:'Other', emoji:'📦'};
  const metaLine = grocerySort === 'alpha' ? `${deptDef.emoji} ${deptDef.name}` : '';
  const isSelected = grocerySelected.has(item.id);
  const isNew = item._isNew; // blank row being named inline
  const dragHandle = canDrag
    ? `<span class="grocery-drag-handle" title="Hold to drag and reorder" style="color:var(--muted);font-size:16px;cursor:grab;flex-shrink:0;touch-action:none;user-select:none;padding:0 4px">☰</span>`
    : `<span style="width:24px;flex-shrink:0"></span>`;
  return `<div class="grocery-item grocery-edit-row${isSelected?' edit-selected':''}" data-id="${item.id}" data-dept="${item.department||'other'}" ${canDrag ? 'draggable="true"' : ''}>
    ${dragHandle}
    <input type="checkbox" class="grocery-cb grocery-select-cb" ${isSelected?'checked':''}
      onchange="toggleGrocerySelect('${item.id}',this)"
      onclick="event.stopPropagation()"
      title="Select item">
    <div class="grocery-item-info">
      <input type="text" value="${esc(item.name)}"
        class="grocery-item-name"
        id="gi-name-${item.id}"
        style="background:transparent;border:none;border-bottom:1px solid rgba(46,51,80,0.5);width:100%;color:var(--text);padding:0 0 2px;outline:none;font-weight:600;font-size:inherit"
        placeholder="${isNew ? 'Item name…' : ''}"
        onchange="updateGroceryItemInline('${item.id}','name',this.value)"
        ${isNew ? `oninput="_groceryNewItemAutocomplete('${item.id}', this.value)" onblur="_groceryNewItemBlur('${item.id}')"` : ''}>
      <div style="display:flex;gap:6px;margin-top:3px;align-items:center">
        ${metaLine ? `<span class="grocery-item-meta" style="flex-shrink:0;font-size:inherit">${esc(metaLine)}</span>` : ''}
        <input type="text" value="${esc(item.notes||'')}" placeholder="Add note…"
          class="grocery-item-meta"
          style="background:transparent;border:none;border-bottom:1px dashed rgba(46,51,80,0.35);color:var(--muted);padding:0;flex:1;min-width:40px;outline:none;font-size:inherit"
          onchange="updateGroceryItemInline('${item.id}','notes',this.value)">
      </div>
    </div>
    ${groceryQtyStepperHTML(item)}
  </div>`;
}

async function updateGroceryItemInline(id, field, value) {
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  // For the name field, parse "2 Yoghurts", "Yoghurts x 2" etc. — promote
  // any embedded quantity to the new qty stepper rather than baking it into
  // the name.
  if (field === 'name') {
    const parsed = parseGroceryQty(value);
    item.name = parsed.name;
    if (parsed.qty > 1) item.qty = parsed.qty;
    // Keep the input visually in sync with the cleaned-up name
    if (parsed.name !== value || parsed.qty > 1) {
      const inp = document.getElementById(`gi-name-${id}`);
      if (inp && inp.value !== parsed.name) inp.value = parsed.name;
    }
  } else {
    item[field] = value;
  }
  item.updatedAt = new Date().toISOString();
  // Once the user has set a name, clear the _isNew flag
  if (field === 'name') delete item._isNew;
  await saveGrocery();
  // Re-render so the qty stepper reflects any extracted number
  if (field === 'name') renderGrocery();
}

// Increment / decrement a grocery item's quantity. Min 1, max 999.
async function _adjustGroceryQty(id, delta) {
  if (!canWrite('groceries')) { showLockBanner('groceries'); return; }
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  const current = (typeof item.qty === 'number' && item.qty > 0) ? item.qty : 1;
  const next = Math.max(1, Math.min(999, current + delta));
  if (next === current) return;
  item.qty = next;
  item.updatedAt = new Date().toISOString();
  // Update the visible number in place without a full re-render so taps feel snappy
  const numEl = document.getElementById(`gqty-${id}`);
  if (numEl) numEl.textContent = next;
  // Hide/show stepper minus button at min
  const minusEl = document.getElementById(`gqtyminus-${id}`);
  if (minusEl) minusEl.disabled = (next === 1);
  await saveGrocery();
}

// ── Autocomplete on inline new-item inputs ────────────────────────────
// Same idea as the Quick List autocomplete, but applied to the blank rows
// the user types into during edit mode. Source pool is every item the
// user has ever added to ANY grocery list (their personal "item history"),
// deduplicated by case-insensitive name. Picking a suggestion fills the
// name AND moves the row to the suggestion's department if different —
// saves a step when typing items that belong elsewhere.
function _groceryNewItemAutocomplete(itemId, raw) {
  const value = (raw || '').trim();
  if (value.length < 1) { _hideGroceryAutocompletePopover(); return; }

  // Strip any quantity prefix the user has typed so suggestions surface
  // correctly. Keep the prefix so we can re-attach it on pick.
  const parsed     = parseGroceryQty(value);
  const searchTerm = (parsed.name || value).toLowerCase();
  if (searchTerm.length < 1) { _hideGroceryAutocompletePopover(); return; }

  // Build a deduplicated suggestion pool from ALL items across every list.
  // Map: lowercase-name → { name, department } using the most recent dept.
  const seen = new Map();
  for (const i of groceryItems) {
    if (!i.name || i._deletedAt) continue;
    if (i.id === itemId) continue; // exclude the blank we're typing into
    const key = i.name.trim().toLowerCase();
    if (!key) continue;
    if (!seen.has(key)) {
      seen.set(key, { name: i.name.trim(), department: i.department || 'other', updatedAt: i.updatedAt });
    } else {
      const cur = seen.get(key);
      // Prefer the entry with the latest updatedAt — in case dept changed
      if ((i.updatedAt || '') > (cur.updatedAt || '')) {
        seen.set(key, { name: cur.name, department: i.department || cur.department, updatedAt: i.updatedAt });
      }
    }
  }
  const matches = [...seen.values()]
    .filter(s => s.name.toLowerCase().includes(searchTerm))
    .sort((a, b) => {
      // Prioritise startsWith over contains
      const aStarts = a.name.toLowerCase().startsWith(searchTerm) ? 0 : 1;
      const bStarts = b.name.toLowerCase().startsWith(searchTerm) ? 0 : 1;
      if (aStarts !== bStarts) return aStarts - bStarts;
      return a.name.localeCompare(b.name);
    })
    .slice(0, 6);
  if (!matches.length) { _hideGroceryAutocompletePopover(); return; }

  const pop = _ensureGroceryAutocompletePopover();
  const input = document.getElementById(`gi-name-${itemId}`);
  if (!input) { _hideGroceryAutocompletePopover(); return; }

  const qtyPrefix = parsed.qty > 1 ? `${parsed.qty} ` : '';
  pop.innerHTML = matches.map(m => {
    const lo  = m.name.toLowerCase();
    const idx = lo.indexOf(searchTerm);
    const before = esc(m.name.slice(0, idx));
    const matchTxt = `<strong style="color:var(--accent)">${esc(m.name.slice(idx, idx + searchTerm.length))}</strong>`;
    const after = esc(m.name.slice(idx + searchTerm.length));
    const fullName = (qtyPrefix + m.name).replace(/'/g, "\\'");
    const dept = m.department || 'other';
    return `<div
      onmousedown="event.preventDefault()"
      onclick="_groceryNewItemPickSuggestion('${itemId}','${esc(fullName)}','${esc(dept)}')"
      style="padding:9px 12px;cursor:pointer;font-size:13px;border-bottom:1px solid var(--border)"
      onmouseover="this.style.background='var(--surface2)'"
      onmouseout="this.style.background=''"
    >${before}${matchTxt}${after}<span style="color:var(--muted);font-size:11px;margin-left:8px">${esc(dept)}</span></div>`;
  }).join('');

  // Position below the input. Account for scroll so the popover tracks.
  const rect = input.getBoundingClientRect();
  pop.style.left  = `${Math.round(rect.left + window.scrollX)}px`;
  pop.style.top   = `${Math.round(rect.bottom + window.scrollY + 2)}px`;
  pop.style.width = `${Math.max(180, Math.round(rect.width))}px`;
  pop.style.display = 'block';
}

function _ensureGroceryAutocompletePopover() {
  let pop = document.getElementById('grocery-new-autocomplete');
  if (pop) return pop;
  pop = document.createElement('div');
  pop.id = 'grocery-new-autocomplete';
  pop.style.cssText = 'position:absolute;z-index:300;background:var(--surface);border:1px solid var(--border);border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,0.35);max-height:240px;overflow-y:auto;display:none';
  document.body.appendChild(pop);
  return pop;
}

function _hideGroceryAutocompletePopover() {
  const pop = document.getElementById('grocery-new-autocomplete');
  if (pop) pop.style.display = 'none';
}

// Pick a suggestion: fill the input, parse qty, move dept if different,
// keep the row in edit mode (don't blur).
async function _groceryNewItemPickSuggestion(itemId, fullName, dept) {
  const item = groceryItems.find(i => i.id === itemId);
  const input = document.getElementById(`gi-name-${itemId}`);
  if (!item || !input) { _hideGroceryAutocompletePopover(); return; }
  // Parse "2 Yoghurts" into name+qty so the qty stepper updates
  const parsed = parseGroceryQty(fullName);
  item.name = parsed.name || fullName.trim();
  if (parsed.qty > 1) item.qty = parsed.qty;
  if (dept && dept !== item.department) item.department = dept;
  // Promote out of "_isNew" — the user has explicitly chosen a name now,
  // so it's a real saved item. Subsequent edits go through normal flow.
  delete item._isNew;
  item.updatedAt = new Date().toISOString();
  _hideGroceryAutocompletePopover();
  await saveGrocery();
  // Re-render so the dept reordering and stepper update are visible
  renderGrocery();
  // Try to refocus on the next blank input (so the user can keep tab-walking)
  const nextBlank = groceryItems.find(i => i._isNew && !i.name.trim());
  if (nextBlank) {
    setTimeout(() => {
      const el = document.getElementById(`gi-name-${nextBlank.id}`);
      if (el) { el.focus(); el.select(); }
    }, 50);
  }
}

// Called when a new blank item's name field loses focus — remove if still empty
async function _groceryNewItemBlur(id) {
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  // Hide the autocomplete popover. Small delay so a click on a suggestion
  // (which fires its onclick after the blur) still has time to land before
  // the popover disappears.
  setTimeout(() => _hideGroceryAutocompletePopover(), 150);
  // Capture which other input the user just clicked into, if any — we want
  // to keep that input focused across the re-render so Quick Add feels
  // smooth when filling many depts in a row.
  const nextFocusId = (document.activeElement?.id || '').startsWith('gi-name-')
    ? document.activeElement.id
    : null;
  const restoreFocus = () => {
    if (!nextFocusId) return;
    const el = document.getElementById(nextFocusId);
    if (el) {
      el.focus();
      // Don't re-select; cursor keeps its place wherever the user typed
    }
  };
  if (item._isNew && !item.name.trim()) {
    // Never named — remove it silently, no sync needed
    groceryItems = groceryItems.filter(i => i.id !== id);
    const order = getGroceryManualOrder().filter(oid => oid !== id);
    saveGroceryManualOrder(order);
    await _saveGroceryLocal(); // local only — don't push a blank item delete
    renderGrocery();
    restoreFocus();
  } else if (item._isNew && item.name.trim()) {
    // Named successfully — parse qty out of the name if present, then save+sync
    const parsed = parseGroceryQty(item.name);
    item.name = parsed.name;
    if (parsed.qty > 1) item.qty = parsed.qty;
    delete item._isNew;
    item.updatedAt = new Date().toISOString();
    await saveGrocery(); // now safe to sync — item has a name
    renderGrocery();
    restoreFocus();
  }
}

async function deleteGroceryItem(id) {
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  const name = item.name || 'this item';
  if (!confirm(
    `Move "${name}" to recycle bin?\n\n` +
    `You can restore it within 30 days from the bottom of the Groceries view.`
  )) return;
  item._deletedAt = new Date().toISOString();
  if (typeof touchField === 'function') {
    try { touchField(item, '_deletedAt'); } catch(e) {}
  }
  grocerySelected.delete(id);
  await saveGrocery();
  renderGrocery();
  _updateGrocerySelectionBar();
  toast('Moved to recycle bin');
  _maybeShowBinHint('groceries');
}

async function restoreGroceryItem(id) {
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  delete item._deletedAt;
  // If the item's original list was deleted, move it to the currently active list
  const validListIds = new Set(groceryLists.map(l => l.id));
  validListIds.add('default');
  const lid = item.listId || 'default';
  let movedToActive = false;
  if (!validListIds.has(lid)) {
    item.listId = activeGroceryListId || groceryLists[0]?.id || 'default';
    movedToActive = true;
  }
  if (typeof touchField === 'function') {
    try {
      touchField(item, '_deletedAt');
      if (movedToActive) touchField(item, 'listId');
    } catch(e) {}
  }
  await saveGrocery();
  renderGrocery();
  toast(movedToActive ? 'Item restored to current list' : 'Item restored');
}

async function purgeGroceryForever(id) {
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  if (!confirm(`Permanently delete "${item.name||'this item'}"? This cannot be undone.`)) return;
  groceryItems = groceryItems.filter(i => i.id !== id);
  await addGroceryTombstone(id);
  await saveGrocery();
  renderGrocery();
  toast('Permanently deleted');
}

async function emptyGroceryBin() {
  const trashed = groceryItems.filter(_isInRecycleBin);
  if (!trashed.length) return;
  if (!confirm(
    `Permanently delete ${trashed.length} item${trashed.length===1?'':'s'} from the recycle bin? This cannot be undone.`
  )) return;
  for (const g of trashed) await addGroceryTombstone(g.id);
  groceryItems = groceryItems.filter(i => !_isInRecycleBin(i));
  await saveGrocery();
  renderGrocery();
  toast('Recycle bin emptied');
}

// ── Multi-select (edit mode) ─────────────────────────────────────────

function toggleGrocerySelect(id, cb) {
  if (cb.checked) grocerySelected.add(id);
  else            grocerySelected.delete(id);
  // Highlight the row
  const row = document.querySelector(`.grocery-edit-row[data-id="${id}"]`);
  if (row) row.classList.toggle('edit-selected', cb.checked);
  _updateGrocerySelectionBar();
}

function _updateGrocerySelectionBar() {
  let bar = document.getElementById('grocery-selection-bar');
  const count = grocerySelected.size;

  if (!groceryEditMode || count === 0) {
    if (bar) bar.style.display = 'none';
    return;
  }

  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'grocery-selection-bar';
    bar.style.cssText = [
      'position:fixed;bottom:0;left:0;right:0;z-index:400',
      'background:var(--surface)',
      'border-top:2px solid var(--border)',
      'padding:12px 16px 28px',
      'display:flex;gap:10px;align-items:center',
      'backdrop-filter:blur(8px)',
      'box-shadow:0 -4px 20px rgba(0,0,0,0.3)',
    ].join(';');
    document.body.appendChild(bar);
  }

  bar.style.display = 'flex';
  bar.innerHTML = `
    <span style="font-size:13px;color:var(--muted);flex-shrink:0">${count} selected</span>
    <div style="flex:1"></div>
    ${groceryLists.length > 1 ? `<button onclick="openChangeSelectedStore()"
      style="padding:10px 16px;border-radius:8px;border:1px solid rgba(91,141,238,0.4);background:rgba(91,141,238,0.07);color:#5b8dee;font-size:14px;font-weight:600;cursor:pointer">
      <svg class="icon" aria-hidden="true"><use href="#i-store"></use></svg> Move list
    </button>` : ''}
    <button onclick="_changeSelectedDept()"
      style="padding:10px 16px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text);font-size:14px;font-weight:600;cursor:pointer">
      📂 Change Dept
    </button>
    <button onclick="_deleteSelected()"
      style="padding:10px 16px;border-radius:8px;border:none;background:rgba(232,80,80,0.15);color:var(--danger);font-size:14px;font-weight:600;cursor:pointer">
      🗑️ Delete
    </button>`;
}

function _changeSelectedDept() {
  if (grocerySelected.size === 0) return;
  // Show dept picker — we use a special sentinel item id 'multi' to signal multi-mode
  _showDeptPickerForSelection();
}

function _showDeptPickerForSelection() {
  document.getElementById('grocery-dept-picker-overlay')?.remove();
  const depts = groceryDepts.length ? groceryDepts : DEFAULT_DEPTS;
  const count = grocerySelected.size;

  const overlay = document.createElement('div');
  overlay.id = 'grocery-dept-picker-overlay';
  overlay.style.cssText = [
    'position:fixed;inset:0;z-index:600',
    'background:rgba(0,0,0,0.7)',
    'display:flex;align-items:flex-end;justify-content:center',
    'backdrop-filter:blur(4px)',
  ].join(';');
  overlay.dataset.mode     = 'multi';
  overlay.dataset.selected = '';

  overlay.innerHTML = `
    <div style="background:var(--surface);border-radius:20px 20px 0 0;width:100%;max-height:75vh;display:flex;flex-direction:column;padding:20px 16px 36px;box-shadow:0 -8px 32px rgba(0,0,0,0.5)">
      <div style="width:40px;height:4px;background:var(--border);border-radius:2px;margin:0 auto 18px"></div>
      <h3 style="font-size:17px;font-weight:700;margin-bottom:4px;text-align:center">Change Department</h3>
      <p style="font-size:13px;color:var(--muted);text-align:center;margin-bottom:4px">Move ${count} item${count!==1?'s':''} to…</p>
      <div style="text-align:center;margin-bottom:14px">
        <button onclick="_cancelDeptPicker();openGroceryDepts()" style="background:none;border:none;color:var(--accent);font-size:13px;cursor:pointer;text-decoration:underline;padding:0">✏️ Edit Departments</button>
      </div>
      <div style="overflow-y:auto;flex:1;display:flex;flex-direction:column;gap:6px;margin-bottom:16px">
        ${depts.map(d => `
          <button id="dept-pick-${d.id}" onclick="_selectPickerDept('${d.id}')"
            style="display:flex;align-items:center;gap:12px;padding:12px 14px;background:var(--surface2);border:2px solid var(--border);border-radius:10px;cursor:pointer;text-align:left;width:100%;transition:all 0.15s">
            <span style="font-size:22px">${d.emoji}</span>
            <span style="font-size:16px;font-weight:600;color:var(--text)">${esc(d.name)}</span>
            <span id="dept-pick-check-${d.id}" style="margin-left:auto;display:none;color:var(--accent);font-size:18px">✓</span>
          </button>`).join('')}
      </div>
      <div style="display:flex;gap:10px">
        <button onclick="_cancelDeptPicker()" style="flex:1;padding:13px;border-radius:10px;border:1px solid var(--border);background:var(--surface2);color:var(--text);font-size:16px;font-weight:600;cursor:pointer">Cancel</button>
        <button onclick="_confirmDeptPicker()" style="flex:2;padding:13px;border-radius:10px;border:none;background:var(--accent);color:#111;font-size:16px;font-weight:700;cursor:pointer">Move here →</button>
      </div>
    </div>`;

  document.body.appendChild(overlay);
  overlay.addEventListener('click', e => { if (e.target === overlay) _cancelDeptPicker(); });
}

async function _deleteSelected() {
  const ids = [...grocerySelected];
  if (!ids.length) return;
  if (!confirm(
    `Move ${ids.length} item${ids.length!==1?'s':''} to recycle bin?\n\n` +
    `You can restore them within 30 days from the bottom of the Groceries view.`
  )) return;
  const stamp = new Date().toISOString();
  const idSet = new Set(ids);
  groceryItems.forEach(i => {
    if (idSet.has(i.id)) {
      i._deletedAt = stamp;
      if (typeof touchField === 'function') {
        try { touchField(i, '_deletedAt'); } catch(e) {}
      }
    }
  });
  grocerySelected.clear();
  await saveGrocery();
  renderGrocery();
  _updateGrocerySelectionBar();
  toast(`${ids.length} item${ids.length!==1?'s':''} moved to recycle bin`);
  _maybeShowBinHint('groceries');
}

// ── Inline add (+ button) ────────────────────────────────────────────

function toggleGroceryHideChecked() {
  groceryHideChecked = !groceryHideChecked;
  try { localStorage.setItem('stockroom_hide_checked', groceryHideChecked ? '1' : '0'); } catch(e) {}
  const btn = document.getElementById('grocery-hide-checked-btn');
  if (btn) {
    btn.innerHTML = groceryHideChecked ? `<svg class="icon" aria-hidden="true"><use href="#i-eye"></use></svg> Show ticked` : `<svg class="icon" aria-hidden="true"><use href="#i-eye-off"></use></svg> Hide ticked`;
    btn.style.color = groceryHideChecked ? 'var(--accent)' : '';
    btn.style.borderColor = groceryHideChecked ? 'rgba(232,168,56,0.4)' : '';
    btn.style.background = groceryHideChecked ? 'rgba(232,168,56,0.08)' : '';
  }
  renderGrocery();
}

async function addGroceryItemToDept(deptId) {
  // Enable edit mode if not already — don't re-render yet, do it once after item is created
  groceryEditMode = true;
  // Create a blank item and insert at the top of that dept
  const newId = 'g_' + Date.now() + '_' + Math.random().toString(36).slice(2,6);
  // Phase-aware default for `needed`:
  // - stockcheck + check phase → needed: false (user ticks during check)
  // - stockcheck + shop phase  → needed: true  (you're adding it BECAUSE you need it)
  // - shopping mode            → leave unset (irrelevant in this mode)
  const _list = groceryLists.find(l => l.id === (activeGroceryListId || 'default'));
  const _isStockcheck  = _list?.mode === 'stockcheck';
  const _isCheckPhase  = _isStockcheck && (_list.shoppingPhase || 'check') === 'check';
  const newItem = {
    id: newId, name: '', department: deptId || 'other',
    listId: activeGroceryListId || 'default',
    notes: '', recurring: false, intervalDays: 0,
    checked: false, addedAt: new Date().toISOString(), updatedAt: new Date().toISOString(),
    _isNew: true,
  };
  if (_isStockcheck) newItem.needed = !_isCheckPhase; // true in shop phase, false in check phase
  groceryItems.unshift(newItem);
  const order = getGroceryManualOrder();
  saveGroceryManualOrder([newId, ...order]);
  // Save without triggering sync yet — item is still blank
  await _saveGroceryLocal();
  // Single render with edit mode already on
  renderGrocery();
  // Focus the new item's name input
  setTimeout(() => {
    const input = document.getElementById(`gi-name-${newId}`);
    if (input) { input.focus(); input.select(); }
  }, 80);
}

// ── Settings collapsible sections ────────────────────────────────
// All sections start open by default. State persists to localStorage.

const SETTINGS_COLLAPSE_KEY = 'stockroom_settings_collapsed';

function _getSettingsCollapsed() {
  try { return JSON.parse(localStorage.getItem(SETTINGS_COLLAPSE_KEY) || '{}'); }
  catch(e) { return {}; }
}

function _saveSettingsCollapsed(state) {
  try { localStorage.setItem(SETTINGS_COLLAPSE_KEY, JSON.stringify(state)); }
  catch(e) {}
}

function toggleSettings(bodyId, headerEl) {
  // On desktop the sections are always expanded — clicking the header scrolls to it instead
  if (window.innerWidth >= 900) {
    scrollToSection(bodyId);
    return;
  }
  const body = document.getElementById(bodyId);
  if (!body) return;
  const isOpen = body.style.display !== 'none';
  const nowOpen = !isOpen;
  body.style.display = nowOpen ? '' : 'none';
  const chevron = headerEl?.querySelector('.settings-chevron');
  if (chevron) chevron.style.transform = nowOpen ? '' : 'rotate(-90deg)';
  const state = _getSettingsCollapsed();
  if (nowOpen) delete state[bodyId];
  else state[bodyId] = true;
  _saveSettingsCollapsed(state);
}

function initSettingsCollapsibles() {
  const collapsed = _getSettingsCollapsed();
  const allIds = [
    'settings-households-body', 'settings-account-body', 'settings-alerts-body',
    'settings-reminders-body',  'settings-prefs-body',   'settings-about-body',
  ];

  // On desktop: always show all sections, sidebar handles navigation
  const isDesktop = window.innerWidth >= 900;

  allIds.forEach(bodyId => {
    const body = document.getElementById(bodyId);
    if (!body) return;
    const header = body.previousElementSibling;
    const chevron = header?.querySelector?.('.settings-chevron');
    if (isDesktop) {
      // Always expanded on desktop
      body.style.display = '';
      if (chevron) chevron.style.transform = '';
    } else if (collapsed[bodyId]) {
      body.style.display = 'none';
      if (chevron) chevron.style.transform = 'rotate(-90deg)';
    } else {
      body.style.display = '';
      if (chevron) chevron.style.transform = '';
    }
  });

  if (isDesktop) _initSettingsSidebarScroll();
}

function scrollToSection(bodyId) {
  const el = document.getElementById(bodyId);
  if (!el) return;
  const offset = 56 + 61 + 20; // app-header + tabs-wrap + spacing
  const top = el.getBoundingClientRect().top + window.scrollY - offset;
  window.scrollTo({ top, behavior: 'smooth' });
  document.querySelectorAll('.settings-nav-link').forEach(a => {
    a.classList.toggle('active', (a.getAttribute('onclick') || '').includes(bodyId));
  });
}

function _initSettingsSidebarScroll() {
  // Highlight sidebar link as each section scrolls into view
  const sections = [
    'settings-households-body', 'settings-account-body', 'settings-alerts-body',
    'settings-reminders-body',  'settings-prefs-body',   'settings-about-body',
  ];
  // Remove any old observer
  if (window._settingsObserver) window._settingsObserver.disconnect();
  window._settingsObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const id = entry.target.id;
        document.querySelectorAll('.settings-nav-link').forEach(a => {
          a.classList.toggle('active', (a.getAttribute('onclick') || '').includes(id));
        });
      }
    });
  }, { rootMargin: '-10% 0px -70% 0px', threshold: 0 });
  sections.forEach(id => {
    const el = document.getElementById(id);
    if (el) window._settingsObserver.observe(el);
  });
  // Highlight first link by default
  const first = document.querySelector('.settings-nav-link');
  if (first) first.classList.add('active');
}

function toggleGroceryEditMode() {
  groceryEditMode = !groceryEditMode;
  if (!groceryEditMode) {
    grocerySelected.clear();
    // Sweep any unfinished `_isNew` blank items left behind — Quick Add
    // creates one per dept, and the user may exit edit mode without typing
    // into all of them. Without this sweep, blank rows would render in
    // locked mode.
    const before = groceryItems.length;
    groceryItems = groceryItems.filter(i => !(i._isNew && !i.name?.trim()));
    if (groceryItems.length !== before) {
      const order = getGroceryManualOrder().filter(id => groceryItems.some(i => i.id === id));
      saveGroceryManualOrder(order);
      _saveGroceryLocal().catch(() => {});
    }
  }
  // When entering edit mode, auto-show the Done editing pill beside the FAB
  if (groceryEditMode) {
    _showGroceryDoneSlide();
  } else {
    _hideGroceryDoneSlide();
  }
  renderGrocery();
  _updateGrocerySelectionBar();
}

// ── Quick Add: one blank input per department ──────────────────────────
// Surfaced from the empty-list CTA. Drops one `_isNew` blank into every
// department, switches to dept-grouped edit mode, and lets the user type
// into whichever depts they care about. Unused depts collapse out of view
// the moment the user leaves edit mode (toggleGroceryEditMode sweeps the
// blanks). Existing inline blur logic handles per-input cleanup.
async function quickAddByDepartment() {
  if (!canWrite('groceries')) { showLockBanner('groceries'); return; }
  if (!activeGroceryListId) return;
  const depts = groceryDepts.length ? groceryDepts : DEFAULT_DEPTS;
  // Force dept-grouped view so the per-dept blanks are visible in their groups
  grocerySort = 'dept';
  try { localStorage.setItem('stockroom_grocery_sort', 'dept'); } catch (e) {}
  const now = new Date().toISOString();
  // Create one blank `_isNew` item per dept — phase-aware default for `needed`
  const list = _activeGroceryList();
  const isStockcheck = list?.mode === 'stockcheck';
  const inCheckPhase = isStockcheck && (list.shoppingPhase || 'check') === 'check';
  const newIds = [];
  depts.forEach(dept => {
    const newId = 'g_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6) + '_' + dept.id;
    const newItem = {
      id: newId,
      name: '',
      department: dept.id,
      listId: activeGroceryListId,
      notes: '',
      recurring: false,
      intervalDays: 0,
      checked: false,
      addedAt: now,
      updatedAt: now,
      _isNew: true,
    };
    if (isStockcheck) newItem.needed = !inCheckPhase; // shop phase: needed=true; check phase: needed=false
    groceryItems.push(newItem);
    newIds.push(newId);
  });
  // Append all new blanks to the manual-order list so they sort sensibly
  const order = getGroceryManualOrder();
  saveGroceryManualOrder([...order, ...newIds]);
  // Enter edit mode (without going through toggleGroceryEditMode so we don't
  // double-sweep). _showGroceryDoneSlide gives the user the visible exit cue.
  groceryEditMode = true;
  _showGroceryDoneSlide();
  await _saveGroceryLocal();
  renderGrocery();
  // Focus the first dept's input so the user can start typing immediately
  setTimeout(() => {
    const firstInput = document.getElementById(`gi-name-${newIds[0]}`);
    if (firstInput) { firstInput.focus(); firstInput.select(); }
  }, 100);
}

// Show the "Done editing" amber pill sliding left from FAB — always visible in edit mode
function _showGroceryDoneSlide() {
  const btn = document.getElementById('fab-btn');
  if (!btn || btn.style.display === 'none') return;
  _hideGroceryDoneSlide();
  const slide = document.createElement('div');
  slide.id = 'grocery-done-slide';
  slide.onclick = () => { toggleGroceryEditMode(); };
  slide.style.cssText = 'position:fixed;bottom:88px;right:112px;z-index:1100;display:flex;align-items:center;gap:10px;cursor:pointer;animation:fabSlideLeft 0.22s cubic-bezier(0.34,1.56,0.64,1) both';
  slide.innerHTML = `<span style="font-size:17px;font-weight:700;color:#111;background:var(--accent);padding:10px 18px;border-radius:12px;white-space:nowrap;box-shadow:0 4px 16px rgba(232,168,56,0.45);display:flex;align-items:center;gap:8px"><svg class="icon" aria-hidden="true" style="color:#111"><use href="#i-lock"></use></svg> Done editing</span>`;
  document.body.appendChild(slide);
}

function _hideGroceryDoneSlide() {
  document.getElementById('grocery-done-slide')?.remove();
}

// ── Drag-to-reorder ─────────────────────────────────────────
let _dragSrcEl   = null;
let _dragSrcDept = null;

function _showChangeDeptZone() {
  // Fixed bar pinned to bottom of screen — appears when drag starts
  if (document.getElementById('grocery-change-dept-zone')) {
    show('grocery-change-dept-zone', 'flex');
    return;
  }
  const zone = document.createElement('div');
  zone.id = 'grocery-change-dept-zone';
  zone.style.cssText = [
    'position:fixed;bottom:0;left:0;right:0;z-index:500',
    'background:rgba(15,17,23,0.96)',
    'border-top:2px solid rgba(232,168,56,0.5)',
    'padding:14px 16px 28px',
    'display:flex;align-items:center;justify-content:center;gap:12px',
    'backdrop-filter:blur(8px)',
    'transition:transform 0.2s ease',
  ].join(';');

  // Change Dept drop target
  const deptBtn = document.createElement('div');
  deptBtn.id = 'grocery-zone-dept';
  deptBtn.style.cssText = 'flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;padding:10px;border:2px dashed rgba(232,168,56,0.4);border-radius:12px;cursor:pointer';
  deptBtn.innerHTML = `<svg aria-hidden="true" style="width:22px;height:22px;color:var(--accent)"><use href="#i-folder-open"></use></svg><div style="font-size:12px;font-weight:700;color:var(--accent);letter-spacing:1px">CHANGE DEPT</div>`;
  deptBtn.addEventListener('dragover', e => { e.preventDefault(); deptBtn.style.background='rgba(232,168,56,0.12)'; });
  deptBtn.addEventListener('dragleave', () => { deptBtn.style.background=''; });
  deptBtn.addEventListener('drop', e => { e.preventDefault(); deptBtn.style.background=''; _showDeptPickerOverlay(); });
  deptBtn.addEventListener('touchend', e => { if (_dragSrcEl) { e.preventDefault(); _showDeptPickerOverlay(); } });

  // Change List button (only if 2+ lists)
  const listBtn = document.createElement('div');
  listBtn.id = 'grocery-zone-list';
  listBtn.style.cssText = 'flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;padding:10px;border:2px dashed rgba(91,141,238,0.4);border-radius:12px;cursor:pointer';
  listBtn.innerHTML = `<svg class="icon" style="width:22px;height:22px" aria-hidden="true"><use href="#i-store"></use></svg><div style="font-size:12px;font-weight:700;color:#5b8dee;letter-spacing:1px">CHANGE LIST</div>`;
  listBtn.addEventListener('dragover', e => { e.preventDefault(); listBtn.style.background='rgba(91,141,238,0.12)'; });
  listBtn.addEventListener('dragleave', () => { listBtn.style.background=''; });
  listBtn.addEventListener('drop', e => { e.preventDefault(); listBtn.style.background=''; const id = _dragSrcEl?.dataset?.id; if (id) openChangeGroceryItemStore(id); _hideChangeDeptZone(); });
  listBtn.addEventListener('touchend', e => { if (_dragSrcEl) { e.preventDefault(); const id = _dragSrcEl.dataset.id; if (id) openChangeGroceryItemStore(id); _hideChangeDeptZone(); } });

  // Delete button
  const delBtn = document.createElement('div');
  delBtn.id = 'grocery-zone-delete';
  delBtn.style.cssText = 'flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;padding:10px;border:2px dashed rgba(232,80,80,0.4);border-radius:12px;cursor:pointer';
  delBtn.innerHTML = `<svg aria-hidden="true" style="width:22px;height:22px;color:var(--danger)"><use href="#i-trash-2"></use></svg><div style="font-size:12px;font-weight:700;color:var(--danger);letter-spacing:1px">DELETE</div>`;
  delBtn.addEventListener('dragover', e => { e.preventDefault(); delBtn.style.background='rgba(232,80,80,0.12)'; });
  delBtn.addEventListener('dragleave', () => { delBtn.style.background=''; });
  delBtn.addEventListener('drop', async e => {
    e.preventDefault(); delBtn.style.background='';
    const id = _dragSrcEl?.dataset?.id;
    if (id) await deleteGroceryItem(id);
    _hideChangeDeptZone(); _dragSrcEl = null;
  });
  delBtn.addEventListener('touchend', async e => {
    if (_dragSrcEl) {
      e.preventDefault();
      const id = _dragSrcEl.dataset.id;
      if (id) await deleteGroceryItem(id);
      _hideChangeDeptZone(); _dragSrcEl = null;
    }
  });

  zone.appendChild(deptBtn);
  if (groceryLists.length > 1) zone.appendChild(listBtn);
  zone.appendChild(delBtn);
  document.body.appendChild(zone);
}

function _hideChangeDeptZone() {
  const zone = document.getElementById('grocery-change-dept-zone');
  if (zone) { zone.style.display = 'none'; }
}

function _showDeptPickerOverlay() {
  // Remove any existing
  document.getElementById('grocery-dept-picker-overlay')?.remove();

  const depts = groceryDepts.length ? groceryDepts : DEFAULT_DEPTS;
  // Capture item ID NOW while _dragSrcEl is still live
  const itemId      = _dragSrcEl?.dataset?.id || '';
  const currentDept = _dragSrcEl?.dataset?.dept || groceryItems.find(i => i.id === itemId)?.department || 'other';

  const overlay = document.createElement('div');
  overlay.id = 'grocery-dept-picker-overlay';
  overlay.style.cssText = [
    'position:fixed;inset:0;z-index:600',
    'background:rgba(0,0,0,0.7)',
    'display:flex;align-items:flex-end;justify-content:center',
    'padding:0',
    'backdrop-filter:blur(4px)',
  ].join(';');

  // Store item ID and selection on overlay so _confirmDeptPicker doesn't need _dragSrcEl
  overlay.dataset.itemId   = itemId;
  overlay.dataset.selected = currentDept;

  overlay.innerHTML = `
    <div style="background:var(--surface);border-radius:20px 20px 0 0;width:100%;max-height:75vh;display:flex;flex-direction:column;padding:20px 16px 36px;box-shadow:0 -8px 32px rgba(0,0,0,0.5)">
      <div style="width:40px;height:4px;background:var(--border);border-radius:2px;margin:0 auto 18px"></div>
      <h3 style="font-size:17px;font-weight:700;margin-bottom:4px;text-align:center">Change Department</h3>
      <p style="font-size:13px;color:var(--muted);text-align:center;margin-bottom:4px">Choose a department for this item</p>
      <div style="text-align:center;margin-bottom:14px">
        <button onclick="_cancelDeptPicker();openGroceryDepts()" style="background:none;border:none;color:var(--accent);font-size:13px;cursor:pointer;text-decoration:underline;padding:0">✏️ Edit Departments</button>
      </div>
      <div id="dept-picker-list" style="overflow-y:auto;flex:1;display:flex;flex-direction:column;gap:6px;margin-bottom:16px">
        ${depts.map(d => `
          <button id="dept-pick-${d.id}" onclick="_selectPickerDept('${d.id}')"
            style="display:flex;align-items:center;gap:12px;padding:12px 14px;background:${d.id === currentDept ? 'rgba(232,168,56,0.12)' : 'var(--surface2)'};border:2px solid ${d.id === currentDept ? 'rgba(232,168,56,0.5)' : 'var(--border)'};border-radius:10px;cursor:pointer;text-align:left;transition:all 0.15s;width:100%">
            <span style="font-size:22px">${d.emoji}</span>
            <span style="font-size:16px;font-weight:600;color:var(--text)">${esc(d.name)}</span>
            <span id="dept-pick-check-${d.id}" style="margin-left:auto;display:${d.id === currentDept ? 'block' : 'none'};color:var(--accent);font-size:18px">✓</span>
          </button>`).join('')}
      </div>
      <div style="display:flex;gap:10px">
        <button onclick="_cancelDeptPicker()" style="flex:1;padding:13px;border-radius:10px;border:1px solid var(--border);background:var(--surface2);color:var(--text);font-size:16px;font-weight:600;cursor:pointer">Cancel</button>
        <button id="dept-picker-ok" onclick="_confirmDeptPicker()" style="flex:2;padding:13px;border-radius:10px;border:none;background:var(--accent);color:#111;font-size:16px;font-weight:700;cursor:pointer">Move here →</button>
      </div>
    </div>`;

  document.body.appendChild(overlay);

  // Tap backdrop to cancel
  overlay.addEventListener('click', e => { if (e.target === overlay) _cancelDeptPicker(); });
}

function _selectPickerDept(deptId) {
  const overlay = document.getElementById('grocery-dept-picker-overlay');
  if (!overlay) return;
  // Update highlight
  const depts = groceryDepts.length ? groceryDepts : DEFAULT_DEPTS;
  depts.forEach(d => {
    const btn   = document.getElementById(`dept-pick-${d.id}`);
    const check = document.getElementById(`dept-pick-check-${d.id}`);
    if (btn) {
      btn.style.background    = d.id === deptId ? 'rgba(232,168,56,0.12)' : 'var(--surface2)';
      btn.style.borderColor   = d.id === deptId ? 'rgba(232,168,56,0.5)' : 'var(--border)';
    }
    if (check) check.style.display = d.id === deptId ? 'block' : 'none';
    // Remove "current" label from all, it only showed pre-selection
  });
  overlay.dataset.selected = deptId;
}

async function _confirmDeptPicker() {
  const overlay   = document.getElementById('grocery-dept-picker-overlay');
  const newDeptId = overlay?.dataset?.selected;
  if (!newDeptId) { overlay?.remove(); return; }

  if (overlay?.dataset?.mode === 'multi') {
    // Multi-select mode — move all selected items
    const ids = [...grocerySelected];
    ids.forEach(id => {
      const item = groceryItems.find(i => i.id === id);
      if (item) { item.department = newDeptId; item.updatedAt = new Date().toISOString(); }
    });
    grocerySelected.clear();
    await saveGrocery();
    overlay?.remove();
    renderGrocery();
    _updateGrocerySelectionBar();
  } else {
    // Single drag-to-change-dept mode
    const itemId = overlay?.dataset?.itemId;
    if (itemId) {
      const item = groceryItems.find(i => i.id === itemId);
      if (item && item.department !== newDeptId) {
        item.department = newDeptId;
        item.updatedAt  = new Date().toISOString();
        await saveGrocery();
      }
    }
    if (_dragSrcEl) { _dragSrcEl.classList.remove('dragging'); _dragSrcEl = null; _dragSrcDept = null; }
    overlay?.remove();
    _hideChangeDeptZone();
    renderGrocery();
  }
}

function _cancelDeptPicker() {
  document.getElementById('grocery-dept-picker-overlay')?.remove();
  // Item stays in original dept — just drop drag state
  _dragSrcEl?.classList.remove('dragging');
  _dragSrcEl = null; _dragSrcDept = null;
  _hideChangeDeptZone();
  _persistDragOrder();
}

async function _changeDragItemDept(newDeptId) {
  // Kept for backwards compat — now delegates to confirm flow
  const overlay = document.getElementById('grocery-dept-picker-overlay');
  if (overlay) { overlay.dataset.selected = newDeptId; await _confirmDeptPicker(); return; }
  if (!_dragSrcEl) return;
  const id   = _dragSrcEl.dataset.id;
  const item = groceryItems.find(i => i.id === id);
  if (item && item.department !== newDeptId) {
    item.department = newDeptId;
    item.updatedAt  = new Date().toISOString();
    await saveGrocery();
  }
  _dragSrcEl.classList.remove('dragging');
  _dragSrcEl = null; _dragSrcDept = null;
  _hideChangeDeptZone();
  renderGrocery();
}

function initGroceryDragSort() {
  document.querySelectorAll('.grocery-edit-dept-group').forEach(group => {
    group.querySelectorAll('.grocery-edit-row[draggable="true"]').forEach(row => {
      row.addEventListener('dragstart', e => {
        _dragSrcEl   = row;
        _dragSrcDept = group;
        e.dataTransfer.effectAllowed = 'move';
        setTimeout(() => { row.classList.add('dragging'); _showChangeDeptZone(); }, 0);
      });
      row.addEventListener('dragend', () => {
        row.classList.remove('dragging');
        _hideChangeDeptZone();
        _dragSrcEl = null; _dragSrcDept = null;
        _persistDragOrder();
      });
      row.addEventListener('dragover', e => {
        e.preventDefault();
        if (!_dragSrcEl || _dragSrcEl === row || _dragSrcDept !== group) return;
        const rect = row.getBoundingClientRect();
        if (e.clientY < rect.top + rect.height / 2) group.insertBefore(_dragSrcEl, row);
        else group.insertBefore(_dragSrcEl, row.nextSibling);
      });
      // Touch drag — requires 400ms hold before drag activates
      let _touchHoldTimer = null;
      let _touchMoved     = false;

      row.addEventListener('touchstart', e => {
        _touchMoved = false;
        _touchHoldTimer = setTimeout(() => {
          // Hold confirmed — start drag
          _dragSrcEl   = row;
          _dragSrcDept = group;
          row.classList.add('dragging');
          _showChangeDeptZone();
          // Light haptic if supported
          if (navigator.vibrate) navigator.vibrate(30);
        }, 400);
      }, { passive: true });

      row.addEventListener('touchmove', e => {
        // If finger moves more than 8px before hold, cancel the hold timer (it's a scroll)
        if (_touchHoldTimer && !_dragSrcEl) {
          clearTimeout(_touchHoldTimer);
          _touchHoldTimer = null;
          return;
        }
        if (!_dragSrcEl) return;
        e.preventDefault(); // prevent scroll while dragging
        const t = e.touches[0];
        const target = document.elementFromPoint(t.clientX, t.clientY)?.closest('.grocery-edit-row');
        if (target && target !== _dragSrcEl && target.closest('.grocery-edit-dept-group') === group) {
          const rect = target.getBoundingClientRect();
          if (t.clientY < rect.top + rect.height / 2) group.insertBefore(_dragSrcEl, target);
          else group.insertBefore(_dragSrcEl, target.nextSibling);
        }
        // If finger lands on change-dept zone, highlight it
        const zone = document.getElementById('grocery-change-dept-zone');
        if (zone) {
          const zr = zone.getBoundingClientRect();
          const onZone = t.clientY >= zr.top;
          zone.style.borderTopColor = onZone ? 'var(--accent)' : 'rgba(232,168,56,0.5)';
          zone.style.background = onZone ? 'rgba(232,168,56,0.18)' : 'rgba(15,17,23,0.96)';
        }
      }, { passive: false });

      row.addEventListener('touchend', e => {
        clearTimeout(_touchHoldTimer);
        _touchHoldTimer = null;
        if (!_dragSrcEl) return; // was a tap, not a drag — do nothing

        // Check if finger ended on change-dept zone
        const t = e.changedTouches[0];
        const zone = document.getElementById('grocery-change-dept-zone');
        if (zone) {
          const zr = zone.getBoundingClientRect();
          if (t.clientY >= zr.top) {
            // Dropped on zone — show dept picker without clearing _dragSrcEl
            zone.style.borderTopColor = 'rgba(232,168,56,0.5)';
            zone.style.background     = 'rgba(15,17,23,0.96)';
            _showDeptPickerOverlay();
            return; // _dragSrcEl stays alive for _confirmDeptPicker
          }
        }

        _dragSrcEl.classList.remove('dragging');
        _hideChangeDeptZone();
        _dragSrcEl = null; _dragSrcDept = null;
        _persistDragOrder();
      });
    });
  });
}

function _persistDragOrder() {
  // Collect order from all dept groups in DOM order
  const newOrder = [...document.querySelectorAll('.grocery-edit-dept-group .grocery-edit-row')]
    .map(el => el.dataset.id).filter(Boolean);
  const checkedIds = groceryItems.filter(i => i.checked).map(i => i.id);
  // Append any items not currently visible (checked, filtered out) to end
  const visible = new Set(newOrder);
  const rest = groceryItems.filter(i => !visible.has(i.id)).map(i => i.id);
  saveGroceryManualOrder([...newOrder, ...rest]);
}

function groceryItemHTML(item) {
  const deptDef = groceryDepts.find(d => d.id === (item.department || 'other')) || {name:'Other', emoji:'📦'};
  const meta = [
    grocerySort === 'alpha' ? `${deptDef.emoji} ${deptDef.name}` : null,
    item.notes || null,
    item.recurring ? `↻ every ${item.intervalDays||7}d` : null,
  ].filter(Boolean).join(' · ');

  // Determine which "ticked" state to render based on the list's mode/phase.
  // - shopping mode (legacy)        → use `checked` (green, struck-through)
  // - stockcheck-check phase        → use `needed` (amber, "to buy" highlight)
  // - stockcheck-shop phase:
  //     • items marked needed       → use `checked` (struck through when bought)
  //     • items NOT marked needed   → render as pre-checked / suppressed so
  //                                   only the buy-list stands out. Tapping
  //                                   re-activates them ("buy anyway").
  const list = groceryLists.find(l => l.id === (item.listId || 'default'));
  const isStockcheck = list && list.mode === 'stockcheck';
  const inCheckPhase = isStockcheck && (list.shoppingPhase || 'check') === 'check';
  const inShopPhase  = isStockcheck && list.shoppingPhase === 'shop';

  let stateClass = '';
  if (inCheckPhase) {
    if (_itemIsNeeded(item)) stateClass = ' needed';
  } else if (inShopPhase) {
    if (!_itemIsNeeded(item)) {
      // Wasn't on the buy-list — render as suppressed/checked so the active
      // shopping items stand out. The actual `checked` field stays untouched.
      stateClass = ' checked unneeded-suppressed';
    } else if (item.checked) {
      stateClass = ' checked';
    }
  } else {
    // Legacy shopping mode
    if (item.checked) stateClass = ' checked';
  }

  // Full-row tap target: no checkbox, no menu button
  return `<div class="grocery-item${stateClass}" id="gitem-${item.id}"
    role="button" tabindex="0"
    onclick="tapGroceryItem('${item.id}')"
    onkeydown="if(event.key==='Enter'||event.key===' ')tapGroceryItem('${item.id}')"
    ontouchstart="onGroceryRowTouchStart(event,'${item.id}')"
    ontouchmove="onGroceryRowTouchMove(event,'${item.id}')"
    ontouchend="onGroceryRowTouchEnd(event,'${item.id}')"
    ontouchcancel="onGroceryRowTouchEnd(event,'${item.id}')"
    oncontextmenu="onGroceryRowContextMenu(event,'${item.id}')"
    style="cursor:pointer;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none">
    <div class="grocery-item-info">
      <div class="grocery-item-name">${esc(item.name)}</div>
      ${meta ? `<div class="grocery-item-meta">${esc(meta)}</div>` : ''}
    </div>
    ${groceryQtyStepperHTML(item)}
  </div>`;
}

// ── Qty stepper markup ────────────────────────────────────
// Used in both locked and edit-mode rows. Visible always, but quietly styled
// when qty=1 so it doesn't scream "extra info". stopPropagation on every
// click so it never collides with row tap-to-check or row drag.
function groceryQtyStepperHTML(item) {
  const qty = (typeof item.qty === 'number' && item.qty > 0) ? item.qty : 1;
  const minusDisabled = qty <= 1;
  return `<div class="grocery-qty-stepper${qty > 1 ? ' has-qty' : ''}" onclick="event.stopPropagation()">
    <div class="grocery-qty-arrows">
      <button type="button" class="grocery-qty-btn" aria-label="Decrease quantity"
        id="gqtyminus-${item.id}" ${minusDisabled ? 'disabled' : ''}
        onclick="event.stopPropagation();_adjustGroceryQty('${item.id}',-1)">−</button>
      <span class="grocery-qty-num" id="gqty-${item.id}">${qty}</span>
      <button type="button" class="grocery-qty-btn" aria-label="Increase quantity"
        onclick="event.stopPropagation();_adjustGroceryQty('${item.id}',1)">+</button>
    </div>
  </div>`;
}

// ── Grocery row long-press → open editor ─────────────────────────
// State keyed by item id. Independent of the stockroom card long-press
// state (_cardActionState) so the two systems can't collide. Stores the
// long-press timer, the start coords for tolerance checking, whether
// the long-press has already fired, and a "suppressClick" flag so the
// synthetic onclick that follows a touchend doesn't also fire
// tapGroceryItem.
const _groceryRowState = { by: {} };
const GROCERY_LONG_PRESS_MS        = 500;
const GROCERY_LONG_PRESS_TOLERANCE = 8; // px

function onGroceryRowTouchStart(event, id) {
  // Don't engage long-press inside edit mode — that view has its own
  // inline editors and the long-press behaviour would conflict.
  if (groceryEditMode) return;
  const st = _groceryRowState.by[id] || (_groceryRowState.by[id] = {});
  st.longPressFired = false;
  const t = event.touches && event.touches[0];
  if (!t) return;
  st.startX = t.clientX;
  st.startY = t.clientY;
  clearTimeout(st.longPressTimer);
  st.longPressTimer = setTimeout(() => {
    st.longPressFired = true;
    st.suppressClick  = true;
    // Blur whatever has focus so the on-screen keyboard dismisses
    // before the editor modal opens. Without this, a stale focus on
    // search input / sort dropdown can leave the keyboard up,
    // covering the bottom of the modal on mobile.
    if (document.activeElement && typeof document.activeElement.blur === 'function') {
      try { document.activeElement.blur(); } catch(_) {}
    }
    if (navigator.vibrate) { try { navigator.vibrate(20); } catch(_) {} }
    openEditGroceryItem(id);
  }, GROCERY_LONG_PRESS_MS);
}

function onGroceryRowTouchMove(event, id) {
  const st = _groceryRowState.by[id];
  if (!st || !st.longPressTimer) return;
  const t = event.touches && event.touches[0];
  if (!t) return;
  const dx = Math.abs(t.clientX - (st.startX || 0));
  const dy = Math.abs(t.clientY - (st.startY || 0));
  if (dx > GROCERY_LONG_PRESS_TOLERANCE || dy > GROCERY_LONG_PRESS_TOLERANCE) {
    clearTimeout(st.longPressTimer);
    st.longPressTimer = null;
  }
}

function onGroceryRowTouchEnd(event, id) {
  const st = _groceryRowState.by[id];
  if (!st) return;
  clearTimeout(st.longPressTimer);
  st.longPressTimer = null;
  // If the long-press fired, swallow the click that follows touchend so
  // tapGroceryItem doesn't also run. Reset the flag a moment later so
  // future taps work normally.
  if (st.longPressFired) {
    try { event.preventDefault(); } catch(_) {}
    setTimeout(() => { st.suppressClick = false; }, 50);
  }
}

// Desktop / mouse: right-click opens the editor. Cleaner than the old
// context menu (which only offered "Edit item" → editor as one of three
// choices). Touch users get the same destination via long-press above.
function onGroceryRowContextMenu(event, id) {
  if (groceryEditMode) return;
  try { event.preventDefault(); } catch(_) {}
  if (document.activeElement && typeof document.activeElement.blur === 'function') {
    try { document.activeElement.blur(); } catch(_) {}
  }
  openEditGroceryItem(id);
}

async function tapGroceryItem(id) {
  // Swallow the click if a long-press just opened the editor on this row.
  const _st = _groceryRowState.by[id];
  if (_st && _st.suppressClick) { _st.suppressClick = false; return; }
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;

  const list = groceryLists.find(l => l.id === (item.listId || 'default'));
  const isStockcheck = list && list.mode === 'stockcheck';
  const inCheckPhase = isStockcheck && (list.shoppingPhase || 'check') === 'check';
  const inShopPhase  = isStockcheck && list.shoppingPhase === 'shop';

  let kind;  // which state actually changed — feeds into the DOM update + animation
  if (inCheckPhase) {
    // Stock-check: tap toggles `needed`
    item.needed = !_itemIsNeeded(item);
    kind = 'needed';
  } else if (inShopPhase && !_itemIsNeeded(item)) {
    // Shop phase, item was rendered as suppressed (not on the buy-list).
    // Tap re-activates it: it joins the buy-list and is unchecked.
    item.needed = true;
    item.checked = false;
    item.checkedAt = null;
    kind = 'reactivate';
  } else {
    // Shopping mode (legacy) or shop phase + needed item: toggle checked
    item.checked   = !item.checked;
    item.checkedAt = item.checked ? new Date().toISOString() : null;
    kind = 'checked';
  }

  // Save locally (IDB, fast), then smart-queue server sync
  await _saveGroceryLocal();
  _smartSync.enqueueGrocery();
  bcPost({ type: 'GROCERY_CHANGED' });

  // Reactivation needs a full re-render so the suppressed visual flips
  // off. Other paths can do a fast DOM update first, then a debounced
  // re-render to slide the item to its new dept position.
  if (kind === 'reactivate') {
    renderGrocery();
  } else {
    _updateGroceryItemDOM(id, kind === 'needed' ? !!item.needed : !!item.checked, kind);
    setTimeout(() => renderGrocery(), 350);
  }
}

async function toggleGroceryCheck(id, cb) {
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  item.checked   = cb.checked;
  item.checkedAt = cb.checked ? new Date().toISOString() : null;

  // Save and smart-queue
  await _saveGroceryLocal();
  _smartSync.enqueueGrocery();
  bcPost({ type: 'GROCERY_CHANGED' });

  setTimeout(() => renderGrocery(), 350);
}

// Instantly update a single grocery item's visual state without full re-render
function _updateGroceryItemDOM(id, on, kind /* 'checked' | 'needed' */) {
  const el = document.getElementById(`gitem-${id}`);
  if (!el) return;
  // 'checked' is the green "purchased" state; 'needed' is the amber "to buy" state.
  // Strip both classes first to handle phase changes cleanly.
  el.classList.remove('checked', 'needed');
  if (on) el.classList.add(kind === 'needed' ? 'needed' : 'checked');
  const nameEl = el.querySelector('.grocery-item-name');
  if (nameEl) nameEl.style.textDecoration = (on && kind === 'checked') ? 'line-through' : '';
  // Dim only when "checked" (bought) — needed-state stays full opacity so it reads as a target
  el.style.opacity = (on && kind === 'checked') ? '0.45' : '';
}

async function clearCheckedGrocery() {
  if (!canWrite('groceries')) { showLockBanner('groceries'); return; }
  groceryItems = groceryItems.map(item => {
    if ((item.listId || 'default') !== activeGroceryListId) return item;
    if (!item.checked) return item;
    // Uncheck all checked items (recurring and non-recurring alike)
    return { ...item, checked: false, checkedAt: null };
  });
  await _saveGroceryLocal();
  _smartSync.enqueueGrocery();
  renderGrocery();
}

// ── Add / Edit ────────────────────────────────────────────

function openAddGroceryItem(prefillName) {
  document.getElementById('grocery-modal-title').textContent = 'Add Grocery Item';
  document.getElementById('grocery-edit-id').value = '';
  document.getElementById('grocery-f-name').value  = prefillName || '';
  document.getElementById('grocery-f-notes').value = '';
  document.getElementById('grocery-f-recurring').checked = false;
  document.getElementById('grocery-f-interval').value = '7';
  document.getElementById('grocery-f-interval-unit').value = '1';
  hide('grocery-recurring-opts');
  populateGroceryDeptSelect('');
  openModal('grocery-item-modal');
  setTimeout(() => document.getElementById('grocery-f-name').focus(), 100);
}

// Add item directly to a specific department — enables edit mode first
function openEditGroceryItem(id) {
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  document.getElementById('grocery-modal-title').textContent = 'Edit Item';
  document.getElementById('grocery-edit-id').value = id;
  document.getElementById('grocery-f-name').value  = item.name;
  document.getElementById('grocery-f-notes').value = item.notes || '';
  document.getElementById('grocery-f-recurring').checked = !!item.recurring;
  const days = item.intervalDays || 7;
  // pick best unit
  if (days % 30 === 0 && days >= 30) {
    document.getElementById('grocery-f-interval').value = days / 30;
    document.getElementById('grocery-f-interval-unit').value = '30';
  } else if (days % 7 === 0) {
    document.getElementById('grocery-f-interval').value = days / 7;
    document.getElementById('grocery-f-interval-unit').value = '7';
  } else {
    document.getElementById('grocery-f-interval').value = days;
    document.getElementById('grocery-f-interval-unit').value = '1';
  }
  toggle('grocery-recurring-opts', item.recurring, 'block');
  populateGroceryDeptSelect(item.department || 'other');
  openModal('grocery-item-modal');
}

function populateGroceryDeptSelect(selectedId) {
  const sel = document.getElementById('grocery-f-dept');
  sel.innerHTML = groceryDepts.map(d =>
    `<option value="${d.id}" ${d.id === selectedId ? 'selected' : ''}>${d.emoji} ${d.name}</option>`
  ).join('');
}

function toggleGroceryRecurring() {
  const checked = document.getElementById('grocery-f-recurring').checked;
  toggle('grocery-recurring-opts', checked, 'block');
}

async function saveGroceryItem() {
  if (!canWrite("groceries")) { showLockBanner("groceries"); return; }
  const rawName = document.getElementById('grocery-f-name').value.trim();
  if (!rawName) { showToast('Please enter an item name'); return; }
  // Parse "2 Yoghurts", "Apples x 3" etc. so the qty stepper gets it
  const parsed = parseGroceryQty(rawName);
  const name   = parsed.name;
  const parsedQty = parsed.qty;
  const id        = document.getElementById('grocery-edit-id').value;
  const dept      = document.getElementById('grocery-f-dept').value;
  const notes     = document.getElementById('grocery-f-notes').value.trim();
  const recurring = document.getElementById('grocery-f-recurring').checked;
  const intervalVal  = parseInt(document.getElementById('grocery-f-interval').value) || 7;
  const intervalUnit = parseInt(document.getElementById('grocery-f-interval-unit').value) || 1;
  const intervalDays = intervalVal * intervalUnit;

  if (id) {
    const item = groceryItems.find(i => i.id === id);
    if (item) {
      const patch = {name, department:dept, notes, recurring, intervalDays, updatedAt:new Date().toISOString()};
      // Only adopt the parsed qty if user actually wrote one — never silently
      // reset the qty when editing an existing item.
      if (parsedQty > 1) patch.qty = parsedQty;
      Object.assign(item, patch);
    }
  } else {
    const newId = 'g_'+Date.now()+'_'+Math.random().toString(36).slice(2,6);
    const newItem = { id: newId, name, department:dept, notes, recurring, intervalDays, checked:false, listId: activeGroceryListId, addedAt:new Date().toISOString(), updatedAt:new Date().toISOString() };
    if (parsedQty > 1) newItem.qty = parsedQty;
    // Phase-aware default for `needed` — see addGroceryItemToDept for the rule.
    const _list = groceryLists.find(l => l.id === (activeGroceryListId || 'default'));
    if (_list?.mode === 'stockcheck') {
      const _isCheckPhase = (_list.shoppingPhase || 'check') === 'check';
      newItem.needed = !_isCheckPhase;
    }
    groceryItems.push(newItem);
    appendToGroceryOrder(newId);
  }
  await saveGrocery();
  closeModal('grocery-item-modal');
  renderGrocery();
}

// ── Context menu ─────────────────────────────────────────

function openGroceryContext(e, id) {
  e.stopPropagation();
  groceryContextTarget = id;
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  const menu = document.getElementById('grocery-context-menu');
  menu.innerHTML = `
    <button class="grocery-context-item" onclick="editFromContext()"><svg class="icon" aria-hidden="true"><use href="#i-pencil"></use></svg> Edit item</button>
    <button class="grocery-context-item" onclick="convertFromContext()"><svg class="icon" aria-hidden="true"><use href="#i-package"></use></svg> Convert to stock item</button>
    <button class="grocery-context-item danger" onclick="deleteFromContext()"><svg class="icon" aria-hidden="true"><use href="#i-trash-2"></use></svg> Delete</button>
  `;
  // Position near tap
  const rect = e.currentTarget.getBoundingClientRect();
  menu.style.display = 'block';
  const menuW = 190, menuH = 140;
  let left = rect.left - menuW + rect.width;
  let top  = rect.bottom + 6;
  if (left < 8) left = 8;
  if (top + menuH > window.innerHeight) top = rect.top - menuH - 6;
  menu.style.left = left + 'px';
  menu.style.top  = top  + 'px';

  setTimeout(() => document.addEventListener('click', dismissGroceryContext, {once:true}), 10);
}

function dismissGroceryContext() {
  hide('grocery-context-menu');
  groceryContextTarget = null;
}

function editFromContext() {
  const id = groceryContextTarget;
  dismissGroceryContext();
  if (id) openEditGroceryItem(id);
}

async function deleteFromContext() {
  const id = groceryContextTarget;
  dismissGroceryContext();
  if (!id) return;
  groceryItems = groceryItems.filter(i => i.id !== id);
  await saveGrocery();
  renderGrocery();
}

function convertFromContext() {
  const id = groceryContextTarget;
  dismissGroceryContext();
  if (!id) return;
  const item = groceryItems.find(i => i.id === id);
  if (!item) return;
  groceryConvertItem = item;
  const body = document.getElementById('grocery-convert-body');
  const deptDef = groceryDepts.find(d => d.id === (item.department||'other')) || {name:'Other',emoji:'📦'};
  body.innerHTML = `
    <div style="background:var(--surface2);border-radius:8px;padding:14px;margin-bottom:16px;border:1px solid var(--border)">
      <div style="font-size:15px;font-weight:700;margin-bottom:4px">${esc(item.name)}</div>
      <div style="font-size:12px;color:var(--muted)">${deptDef.emoji} ${esc(deptDef.name)}${item.notes?' · '+esc(item.notes):''}</div>
    </div>
    <div class="form-group">
      <label class="form-label">Category in Stockroom</label>
      <select class="form-input" id="convert-category">
        <option>Food &amp; Drink</option><option>Kitchen</option><option>Bathroom</option>
        <option>Cleaning</option><option>Health</option><option>Garden</option><option>Other</option>
      </select>
    </div>
    <div class="form-group">
      <label class="form-label">Months of supply per purchase</label>
      <input class="form-input" id="convert-months" type="number" min="0.25" max="24" step="0.25" value="1">
    </div>
    <p style="font-size:12px;color:var(--muted);margin-top:4px">You can finish setting it up in the stock item form.</p>
  `;
  openModal('grocery-convert-modal');
}

function doConvertToStock() {
  if (!groceryConvertItem) return;
  const category = document.getElementById('convert-category').value;
  const months   = parseFloat(document.getElementById('convert-months').value) || 1;
  closeModal('grocery-convert-modal');
  // Pre-fill the main item modal
  openItemModal();
  setTimeout(() => {
    const nameEl = document.getElementById('f-name');
    const catEl  = document.getElementById('f-category');
    const monEl  = document.getElementById('f-months');
    if (nameEl) nameEl.value = groceryConvertItem.name;
    if (catEl)  catEl.value  = category;
    if (monEl)  monEl.value  = months;
    // Switch to the stock tab
    const stockTab = [...document.querySelectorAll('.tab')].find(t => t.textContent.includes('Stock'));
    if (stockTab) showView('stock', stockTab);
  }, 150);
  groceryConvertItem = null;
}

// ── Departments modal ──────────────────────────────────────

function openGroceryDepts() {
  renderGroceryDeptsModal();
  // populate shop interval
  const si = getGroceryShopInterval();
  document.getElementById('grocery-shop-interval').value = si.value;
  document.getElementById('grocery-shop-interval-unit').value = si.unit;
  openModal('grocery-depts-modal');
}

function renderGroceryDeptsModal() {
  const list = document.getElementById('grocery-depts-list');
  list.innerHTML = groceryDepts.map((d, idx) => `
    <div class="dept-manage-row">
      <span class="dept-manage-emoji">${d.emoji}</span>
      <span class="dept-manage-name">${esc(d.name)}</span>
      <div class="dept-manage-actions">
        ${idx > 0 ? `<button class="grocery-icon-btn" onclick="moveGroceryDept(${idx},-1)" title="Move up">↑</button>` : ''}
        ${idx < groceryDepts.length-1 ? `<button class="grocery-icon-btn" onclick="moveGroceryDept(${idx},1)" title="Move down">↓</button>` : ''}
        <button class="grocery-icon-btn" style="color:var(--danger)" onclick="deleteGroceryDept('${d.id}')" title="Delete"><svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg></button>
      </div>
    </div>
  `).join('');
}

async function moveGroceryDept(idx, dir) {
  const newIdx = idx + dir;
  if (newIdx < 0 || newIdx >= groceryDepts.length) return;
  [groceryDepts[idx], groceryDepts[newIdx]] = [groceryDepts[newIdx], groceryDepts[idx]];
  await saveGroceryDepts();
  renderGroceryDeptsModal();
}

async function deleteGroceryDept(id) {
  const inUse = groceryItems.some(i => i.department === id);
  if (inUse && !confirm('Items use this department. They\'ll move to Other. Continue?')) return;
  if (inUse) groceryItems.forEach(i => { if (i.department === id) i.department = 'other'; });
  groceryDepts = groceryDepts.filter(d => d.id !== id);
  await saveGroceryDepts();
  await saveGrocery();
  renderGroceryDeptsModal();
}

async function addGroceryDept() {
  const nameInput  = document.getElementById('grocery-new-dept-name');
  const emojiInput = document.getElementById('grocery-new-dept-emoji');
  const name  = nameInput.value.trim();
  const emoji = emojiInput.value.trim() || '📦';
  if (!name) { showToast('Please enter a department name'); return; }
  const id = 'dept_' + Date.now();
  groceryDepts.push({id, name, emoji});
  await saveGroceryDepts();
  nameInput.value  = '';
  emojiInput.value = '';
  renderGroceryDeptsModal();
  showToast('Department added');
}

// ── Auto-restore recurring items ───────────────────────────
async function checkGroceryRecurring() {
  const now = Date.now();
  let changed = false;
  groceryItems.forEach(item => {
    if (!item.recurring || !item.checked || !item.checkedAt) return;
    const intervalMs = (item.intervalDays || 7) * MS_PER_DAY;
    if (now - new Date(item.checkedAt).getTime() >= intervalMs) {
      item.checked   = false;
      item.checkedAt = null;
      changed = true;
    }
  });
  if (changed) { saveGrocery(); renderGrocery(); }
}

// ═══════════════════════════════════════════════════════════
//  HOUSEHOLD PRESENCE
// ═══════════════════════════════════════════════════════════

const PRESENCE_COLOURS = [
  '#e8a838','#5b8dee','#4cbb8a','#e85050','#b45dee',
  '#ee8c5b','#5bdee8','#dee85b','#ee5bab','#5beeaa',
];

let _householdEnabled  = false;
let _householdName     = '';
let _householdColour   = PRESENCE_COLOURS[0];
let _presenceSSE       = null;
let _presencePingTimer = null;
let _currentViewName   = 'stock';
let _otherPresence     = {}; // { userId: { name, colour, view, ts } }

// ── Persistence ───────────────────────────────────────────
function loadHouseholdSettings() {
  try {
    const raw = localStorage.getItem('stockroom_household');
    if (!raw) return;
    const d = JSON.parse(raw);
    _householdEnabled = !!d.enabled;
    _householdColour  = d.colour || PRESENCE_COLOURS[0];
  } catch(e) {}
}

function saveHouseholdSettings() {
  // Household mode auto-enables when a share target is added
  if (!_householdEnabled) return;
  try {
    localStorage.setItem('stockroom_household', JSON.stringify({
      enabled: _householdEnabled,
      colour:  _householdColour,
    }));
  } catch(e) {}
  if (_householdEnabled) connectPresence();
}

function pickHouseholdColour(colour) {
  _householdColour = colour;
  renderHouseholdColourPicker();
  saveHouseholdSettings();
  pushPresence();
}

function renderHouseholdColourPicker() {
  const el = document.getElementById('household-colour-picker');
  if (!el) return;
  el.innerHTML = PRESENCE_COLOURS.map(c => `
    <div onclick="pickHouseholdColour('${c}')"
      style="width:28px;height:28px;border-radius:50%;background:${c};cursor:pointer;
             border:3px solid ${c === _householdColour ? 'var(--text)' : 'transparent'};
             transition:border-color 0.15s;box-shadow:0 2px 6px rgba(0,0,0,0.3)"></div>
  `).join('');
}

// ── Household sharing — file proxy ───────────────────────
// ═══════════════════════════════════════════════════════════
//  SHARE PERMISSION SYSTEM
//  When a user joins via a share link, _shareState holds their
//  permission set. This drives tab locking and edit enforcement.
// ═══════════════════════════════════════════════════════════

// _shareState: null = owner (full access), or { code, name, type, ownerName, households }
let _shareState    = null;
let _sharedFileId  = null; // kept for legacy compat
let _shareKey      = null; // CryptoKey — the AES-GCM share key (travels in URL fragment)
let _pendingJoinCode  = null; // join code awaiting auth
let _pendingShareMeta = null; // share metadata awaiting auth
let _inviteCode    = null;

// Default permission sets per user type
const SHARE_TYPE_DEFAULTS = {
  family: {
    stockroom: 'rw', groceries: 'rw', reminders: 'rw', savings: 'rw', report: 'r', budget: 'rw'
  },
  cleaner: {
    stockroom: 'r', groceries: 'rw', reminders: 'none', savings: 'none', report: 'none', budget: 'none'
  },
  guest: {
    stockroom: 'r', groceries: 'r', reminders: 'none', savings: 'none', report: 'r', budget: 'none'
  },
};

const SECTION_LABELS = {
  stockroom: '📦 Stockroom', groceries: '🛒 Groceries',
  reminders: '🔔 Reminders', savings: '💰 Savings', report: '📋 Report',
  budget:    '💷 Budget',
};

// Share-management permission values per type. Always 'none' by default —
// the owner has to opt in explicitly. `shareManagement` is a global (not
// per-household) permission that controls whether a guest can see and/or
// modify the owner's Share Access section. Stored per-target on the
// `shareManagement` field of the share record so it survives sync without
// polluting per-household perms.
const SHARE_MGMT_DEFAULTS = { family: 'none', cleaner: 'none', guest: 'none' };

// Share-management permission for the *current viewer*. Owners always have
// 'edit'. Guests get whatever the owner granted them on the share record
// (`_shareState.shareManagement`), defaulting to 'none'. The view-mode
// shows the Share Access list as read-only — no add/edit/delete/sync/
// refresh buttons. Edit-mode is identical to owner access for that section.
function getShareMgmtPerm() {
  if (!_shareState) return 'edit'; // owner
  return _shareState.shareManagement || 'none';
}
function canViewShares()   { const p = getShareMgmtPerm(); return p === 'view' || p === 'edit'; }
function canManageShares() { return getShareMgmtPerm() === 'edit'; }

// Get permission for a section in the current household
// Returns 'rw', 'r', or 'none'. Returns 'rw' for owners.
function getSectionPerm(section) {
  if (!_shareState) return 'rw'; // owner
  const hKey  = activeProfile || 'default';
  const hPerms = _shareState.households?.[hKey];
  if (!hPerms) return 'none'; // no access to this household
  return hPerms[section] || 'none';
}

function canView(section)  { const p = getSectionPerm(section); return p === 'rw' || p === 'r'; }
function canWrite(section) { return getSectionPerm(section) === 'rw'; }
function isOwner()         { return !_shareState; }

// Apply permission state to the tab bar — lock inaccessible sections
function applyTabPermissions() {
  if (!_shareState) return; // owner sees everything
  const sectionToTab = {
    stockroom: 'stock', groceries: 'grocery', reminders: 'reminders',
    savings: 'savings', report: 'report', budget: 'budget',
  };
  document.querySelectorAll('.tab').forEach(tab => {
    const text = tab.textContent.trim().toLowerCase();
    let section = null;
    if (text.includes('stockroom')) section = 'stockroom';
    else if (text.includes('groceries') || text.includes('grocery')) section = 'groceries';
    else if (text.includes('reminders')) section = 'reminders';
    else if (text.includes('savings')) section = 'savings';
    else if (text.includes('budget')) section = 'budget';
    else if (text.includes('report')) section = 'report';
    if (!section) return;
    if (canView(section)) {
      tab.disabled = false;
      tab.style.opacity = '';
      tab.title = '';
    } else {
      tab.disabled = true;
      tab.style.opacity = '0.4';
      tab.title = `🔒 Ask ${_shareState.ownerName || 'the owner'} for access`;
    }
  });
}

// Show lock banner when a user tries to access a restricted section
function showLockBanner(section) {
  const label = SECTION_LABELS[section] || section;
  toast(`🔒 ${label} — ask ${_shareState?.ownerName || 'the owner'} for access`);
}

// Save/restore share state from localStorage
async function loadShareState() {
  try {
    const raw = localStorage.getItem('stockroom_share_state');
    if (!raw) {
      // No local cache — on a fresh device the user might still be a
      // member of a share on the server side. Ask the server before
      // giving up. Bails fast if auth isn't ready yet (in which case
      // _enterStockroom will retry post-login).
      await hydrateMembershipsFromServer();
      return;
    }
    const stored = JSON.parse(raw);
    // Don't load share state if this user is the owner of this share
    if (stored.ownerEmailHash && _kvEmailHash && stored.ownerEmailHash === _kvEmailHash) {
      localStorage.removeItem('stockroom_share_state');
      return;
    }
    _shareState   = stored;
    _sharedFileId = stored._sharedFileId || null;
    // Restore share key from local cache (ECDH system — key is never stored in state)
    try {
      const localKeys = await _getShareKeys();
      const keyB64    = localKeys[stored.code];
      if (keyB64) {
        const keyBytes = Uint8Array.from(atob(keyB64), c => c.charCodeAt(0));
        _shareKey = await crypto.subtle.importKey('raw', keyBytes, { name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
      }
    } catch(e) { console.warn('Could not restore share key from cache:', e.message); }
  } catch(e) {}
}

function saveShareState() {
  try {
    if (_shareState) {
      localStorage.setItem('stockroom_share_state', JSON.stringify({ ..._shareState, _sharedFileId }));
    } else {
      localStorage.removeItem('stockroom_share_state');
    }
  } catch(e) {}
}

// Ask the server which shares this user is a MEMBER of (guest-side) and
// restore _shareState if a membership exists. This is the cross-device
// continuity path: a guest who joined a share on device A logs into
// device B with no localStorage cache — without this call, their share
// would appear lost. The /share/memberships endpoint exists on the
// backend specifically for this and is keyed on emailHash, which is
// stable across devices.
//
// Safe to call multiple times: bails immediately when (a) no auth is
// present, (b) the user already has a share state hydrated, or (c) the
// server returns no memberships.
//
// Key recovery is non-blocking: we try (1) local cache, then (2) a
// single server fetch of the wrapped key, then (3) we file a rewrap
// request and return. We do NOT block on polling for up to 30s the way
// the invite-link join flow does — that would hang every fresh-device
// login. If the wrapped key isn't immediately available, _shareState
// is still set; the next kvSyncNow will see the share, log a warning
// about the missing key, and the rewrap request stays queued for the
// owner's next sync to fulfil. The user can then re-sync (or just
// reload the app) and the key arrives.
async function hydrateMembershipsFromServer() {
  if (!WORKER_URL || !_kvEmailHash) return false;
  if (!_kvVerifier && !_kvSessionToken) return false;
  if (_shareState) return false; // already restored from localStorage or invite
  try {
    const authFields = _kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier };
    const res = await postKV(`${WORKER_URL}/share/memberships`, { emailHash: _kvEmailHash, ...authFields });
    if (!res.ok) {
      console.warn('[share] /share/memberships returned', res.status);
      return false;
    }
    const data = (await _readJsonSafe(res)) || {};
    const memberships = Array.isArray(data.memberships) ? data.memberships : [];
    if (!memberships.length) return false;

    // Pick the most-recently joined membership when there are several.
    // Current client model is single-active-share; multi-membership UX
    // is a future iteration.
    memberships.sort((a, b) => {
      const ja = a.joinedAt ? Date.parse(a.joinedAt) : 0;
      const jb = b.joinedAt ? Date.parse(b.joinedAt) : 0;
      return jb - ja;
    });
    if (memberships.length > 1) {
      console.log('[share] multiple memberships found; using most recent:', memberships.map(m => m.code).join(', '));
    }
    const pick = memberships[0];

    // Build _shareState from the membership shape. The server strips
    // the members list for privacy; everything else matches /share/join.
    _shareState = { ...pick };
    saveShareState();

    // Step 1 — local cache. Populated on cases where localStorage was
    // only partially cleared (share_state evicted but share_keys survived).
    try {
      const localKeys = await _getShareKeys();
      const keyB64 = localKeys[pick.code];
      if (keyB64) {
        const keyBytes = Uint8Array.from(atob(keyB64), c => c.charCodeAt(0));
        _shareKey = await crypto.subtle.importKey('raw', keyBytes, { name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
        console.log('[share] hydrated membership', pick.code, '— key restored from local cache');
        return true;
      }
    } catch(e) { console.warn('[share] local key cache check failed:', e.message); }

    // Step 2 — single server attempt. The owner may have already wrapped
    // the share key for this guest's emailHash on a previous occasion
    // (e.g. guest used this email on another device that's since been
    // wiped). One fetch, no polling.
    try {
      const guestPrivKey = await loadEcdhPrivateKey(_kvEmailHash);
      if (guestPrivKey) {
        const ecdhRes = await postKV(`${WORKER_URL}/share/ecdh-key/get`, {
          guestEmailHash: _kvEmailHash, ...authFields, code: pick.code,
        });
        if (ecdhRes.ok) {
          const { wrappedKey, ownerPublicKeyJwk } = (await _readJsonSafe(ecdhRes)) || {};
          if (wrappedKey && ownerPublicKeyJwk) {
            try {
              const shareKey = await ecdhUnwrapShareKey(guestPrivKey, ownerPublicKeyJwk, wrappedKey);
              _shareKey = shareKey;
              const shareKeyB64 = await exportShareKey(shareKey);
              try {
                const stored = await _getShareKeys();
                stored[pick.code] = shareKeyB64;
                await _setShareKeys(stored);
              } catch(e) {}
              console.log('[share] hydrated membership', pick.code, '— key recovered from server');
              toast(`Restored access to ${pick.ownerName || 'shared'} household ✓`);
              return true;
            } catch(unwrapErr) {
              // Stale wrap (wrapped against a different pubkey we don't have anymore).
              // Falls through to step 3.
              console.warn('[share] unwrap failed on hydration, requesting rewrap:', unwrapErr?.name || unwrapErr?.message);
            }
          }
        }
      }
    } catch(e) { console.warn('[share] server key fetch during hydration failed:', e.message); }

    // Step 3 — fire-and-forget rewrap request, then return. The owner's
    // next sync (cron or interactive) fulfils it; the next time this
    // guest's app syncs, step 2 will succeed.
    try {
      await postKV(`${WORKER_URL}/share/ecdh-key/request-rewrap`, {
        guestEmailHash: _kvEmailHash, ...authFields, code: pick.code,
      });
      console.log('[share] queued rewrap request for', pick.code, '— share will activate when owner is next online');
    } catch(e) { console.warn('[share] could not queue rewrap request:', e.message); }
    toast(`Restoring shared household — waiting for ${pick.ownerName || 'owner'} to be online…`);

    // Schedule a single deferred retry. If the owner is actively using
    // STOCKROOM their app fulfils the rewrap within a few seconds; this
    // retry then picks up the wrapped key and finishes the hand-off
    // without making the user reload. If the owner is offline the retry
    // is harmless — it just times out the same way the initial fetch
    // did, and the share stays in waiting state for the next reload.
    setTimeout(async () => {
      if (_shareKey) return; // already recovered by some other path
      if (!_shareState || _shareState.code !== pick.code) return; // user moved on
      try {
        const guestPrivKey2 = await loadEcdhPrivateKey(_kvEmailHash);
        if (!guestPrivKey2) return;
        const ecdhRes2 = await postKV(`${WORKER_URL}/share/ecdh-key/get`, {
          guestEmailHash: _kvEmailHash, ...authFields, code: pick.code,
        });
        if (!ecdhRes2.ok) return;
        const { wrappedKey, ownerPublicKeyJwk } = (await _readJsonSafe(ecdhRes2)) || {};
        if (!wrappedKey || !ownerPublicKeyJwk) return;
        const shareKey = await ecdhUnwrapShareKey(guestPrivKey2, ownerPublicKeyJwk, wrappedKey);
        _shareKey = shareKey;
        const shareKeyB64 = await exportShareKey(shareKey);
        try {
          const stored = await _getShareKeys();
          stored[pick.code] = shareKeyB64;
          await _setShareKeys(stored);
        } catch(e) {}
        console.log('[share] deferred retry succeeded — share', pick.code, 'activated');
        toast(`Restored access to ${pick.ownerName || 'shared'} household ✓`);
        // Pull shared data now that we have the key
        try { await kvSyncNow(true); } catch(_) {}
        try { scheduleRender(...RENDER_REGIONS); } catch(_) {}
      } catch(_) { /* harmless — user can reload to retry */ }
    }, 10000);

    return true;
  } catch(e) {
    console.warn('[share] hydrateMembershipsFromServer failed:', e.message);
    return false;
  }
}

// Generate a new AES-GCM share key — used when creating a share link
async function generateShareKey() {
  return crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
}

// Export a share key to base64 for embedding in URL fragment
async function exportShareKey(key) {
  const raw = await crypto.subtle.exportKey('raw', key);
  return btoa(String.fromCharCode(...new Uint8Array(raw)));
}

// Encrypt data with a share key (for /share/data/push)
async function encryptWithShareKey(shareKey, plaintext) {
  const iv         = crypto.getRandomValues(new Uint8Array(12));
  const encoded    = new TextEncoder().encode(plaintext);
  const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, shareKey, encoded);
  const combined   = new Uint8Array(iv.length + ciphertext.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(ciphertext), iv.length);
  return btoa(String.fromCharCode(...combined));
}

// Decrypt data received from /share/data/pull
async function decryptWithShareKey(shareKey, ciphertext) {
  const combined = Uint8Array.from(atob(ciphertext), c => c.charCodeAt(0));
  const iv       = combined.slice(0, 12);
  const data     = combined.slice(12);
  const plain    = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, shareKey, data);
  return new TextDecoder().decode(plain);
}

// joinViaShareCode — replaced by handleShareJoinLink + completePendingJoin
async function joinViaShareCode(code) {
  // Legacy shim — load scanner.js which defines handleShareJoinLink
  await window._loadScanner().catch(() => {});
  if (typeof handleShareJoinLink === 'function') await handleShareJoinLink(code);
}

async function leaveShare() {
  if (!confirm('Leave this shared household?\n\nYou can rejoin with the same link. Your own households are unaffected.')) return;
  const code = _shareState?.code;
  _shareState   = null;
  _sharedFileId = null;
  _shareKey     = null;
  saveShareState();
  // Clear cached share key
  if (code) {
    try {
      const stored = await _getShareKeys();
      delete stored[code];
      await _setShareKeys(stored);
    } catch(e) {}
  }
  applyTabPermissions();
  toast('Left shared household');
  // Switch to own default profile and reload own data
  loadProfile('default');
  kvSyncNow().catch(() => {});
}

// ── Share state: stored share (old key, migration) ────────
function loadHouseholdShareState() {
  // Migrated to loadShareState() — kept for backwards compat
  loadShareState();
  if (!_shareState) {
    // Check old format
    try {
      const raw = localStorage.getItem('stockroom_household_share');
      if (raw) {
        const d = JSON.parse(raw);
        if (d.fileId) { _sharedFileId = d.fileId; }
      }
    } catch(e) {}
  }
  updateHouseholdShareUI();
}

function saveHouseholdShareState() { saveShareState(); }

async function createInviteCode() {
  if (!kvConnected) {
    toast('Sign in first');
    return;
  }
  const btn = document.querySelector('[onclick="createInviteCode()"]');
  if (btn) { btn.textContent = '⏳ Generating…'; btn.disabled = true; }
  try {
    // Backend uses its stored drive_file_id — no need to send it from frontend
    const res  = await fetch(`${WORKER_URL}/invite/create`, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify({}),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Failed');
    _inviteCode = data.code;
    document.getElementById('invite-code-value').textContent = data.code;
    show('invite-code-display', 'block');
    toast('Invite code created — valid for 24 hours');
  } catch(err) {
    toast('Could not create invite: ' + err.message);
  } finally {
    if (btn) { btn.innerHTML = '<svg class="icon" aria-hidden="true" style="vertical-align:-3px"><use href="#i-link"></use></svg> Generate invite code'; btn.disabled = false; }
  }
}

function copyInviteCode() {
  const code = document.getElementById('invite-code-value')?.textContent?.trim();
  if (!code) return;
  navigator.clipboard?.writeText(code).then(() => toast('Code copied ✓')).catch(() => {
    prompt('Copy this invite code:', code);
  });
}

async function joinHousehold() {
  const input = document.getElementById('invite-code-input');
  const code  = (input?.value || '').trim().toUpperCase();
  if (code.length < 4) { toast('Enter the full invite code'); return; }

  const btn = document.querySelector('[onclick="joinHousehold()"]');
  if (btn) { btn.textContent = '⏳'; btn.disabled = true; }

  try {
    const res  = await fetch(`${WORKER_URL}/invite/join`, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify({ code }),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Invalid code');

    _sharedFileId = data.fileId;
    saveHouseholdShareState();
    updateHouseholdShareUI();
    toast('Joined household ✓ — syncing now');
    // Immediately sync to pull the shared file
    await syncAll();
  } catch(err) {
    toast('Could not join: ' + err.message);
  } finally {
    if (btn) { btn.textContent = 'Join'; btn.disabled = false; }
  }
}

function leaveHousehold() { leaveShare(); }

// ── Proxy read/write used when _sharedFileId is set ──────
async function proxyReadDrive() {
  const code   = _shareState?.code || '';
  const hParam = activeProfile && activeProfile !== 'default' ? `&household=${encodeURIComponent(activeProfile)}` : '';
  const res    = await fetch(`${WORKER_URL}/sync/pull?share=${encodeURIComponent(code)}${hParam}`);
  if (res.status === 404) return null;
  if (res.status === 403) {
    const d = await res.json().catch(() => ({}));
    throw new Error('ACCESS_DENIED: ' + (d.error || 'No access'));
  }
  if (res.status === 503) throw new Error('OWNER_NOT_CONNECTED');
  if (!res.ok) throw new Error('Proxy read failed: ' + res.status);
  return res.json();
}

async function proxyWriteDrive(payload) {
  // Shared user — push via backend, permission validated server-side with share code
  const code   = _shareState?.code || '';
  const hParam = activeProfile && activeProfile !== 'default' ? `&household=${encodeURIComponent(activeProfile)}` : '';
  const res    = await fetch(`${WORKER_URL}/sync/push?share=${encodeURIComponent(code)}${hParam}`, {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    payload,
  });
  if (res.status === 403) throw new Error('READ_ONLY');
  if (!res.ok) throw new Error('Proxy write failed: ' + res.status);
}

async function proxyGetModifiedTime() {
  if (!_shareState?.code || !_kvEmailHash || (!_kvVerifier && !_kvSessionToken)) return null;
  try {
    const res = await postKV(`${WORKER_URL}/share/data/modified`, { guestEmailHash: _kvEmailHash, guestVerifier: _kvVerifier, guestSessionToken: _kvSessionToken, code: _shareState.code, household: activeProfile });
    if (!res.ok) return null;
    return (await res.json()).modifiedTime || null;
  } catch(e) { return null; }
}

// ── Share Target Management ───────────────────────────────
let _shareTargets     = []; // cached from backend
let _shareTargetType  = 'family';
let _shareTargetPerms = {}; // { householdKey: { stockroom, groceries, reminders, savings, report } }
let _shareTargetColour = HOUSEHOLD_COLOURS[0];
let _shareTargetDone   = false; // true after link is generated — btn becomes Done
let _shareTargetMgmt   = 'none'; // 'none' | 'view' | 'edit' — share-management perm for the target being edited

// Tracks which share rows are expanded to show member details. Survives
// re-renders within a session but resets on page reload.
const _expandedShareCodes = {};

function handleShareTargetBtn() {
  if (_shareTargetDone) {
    closeModal('share-target-modal');
  } else {
    saveShareTarget();
  }
}

async function loadShareTargets() {
  if (!WORKER_URL || !_kvEmailHash || (!_kvVerifier && !_kvSessionToken)) return;
  // /share/list returns shares owned by the calling user — including the case
  // where the user is also a guest in someone else's share (_shareState is
  // set but they still own shares of their own). The previous gate
  // `if (!isOwner() && !canViewShares()) return` was wrong because it
  // conflated "in guest mode" with "is a guest" — a user can be both an
  // owner and a guest simultaneously. Removing the gate makes the call
  // always run; the server returns [] for a true guest with no owned shares
  // so no harm done.
  try {
    const res  = await postKV(`${WORKER_URL}/share/list`, { ownerEmailHash: _kvEmailHash, verifier: _kvVerifier, sessionToken: _kvSessionToken });
    const data = await res.json();
    _shareTargets = data.targets || [];
    renderShareTargetsList();
  } catch(e) { console.warn('Could not load share targets:', e); }
}

// ─── Share Access Control panel UI ────────────────────────────────────────
// Renders the panel that lives at the top of Household Sharing — mode
// toggle + deny / allow list editors. See checkShareAccessControl in the
// helpers near settings/_ensureShareAccessControl for the enforcement
// check itself; this function just paints the panel and reflects state.
function renderShareAccessControl() {
  const sac = _ensureShareAccessControl();
  const summary = document.getElementById('sac-summary');
  if (summary) {
    const denyCount  = sac.deny.length;
    const allowCount = sac.allow.length;
    if (sac.mode === 'allowlist') {
      summary.textContent = `Allowlist mode · ${allowCount} allowed · ${denyCount} blocked`;
    } else {
      summary.textContent = `Open mode · ${denyCount} blocked`;
    }
  }
  // Mode radios
  const openRadio  = document.getElementById('sac-mode-open');
  const alistRadio = document.getElementById('sac-mode-allowlist');
  if (openRadio)  openRadio.checked  = (sac.mode === 'open');
  if (alistRadio) alistRadio.checked = (sac.mode === 'allowlist');
  // Mode help text
  const helpEl = document.getElementById('sac-mode-help');
  if (helpEl) {
    helpEl.textContent = sac.mode === 'allowlist'
      ? 'Only emails on the allow list can be added to a share.'
      : 'Anyone can be added except entries on the deny list.';
  }
  // Allow section visibility
  const allowSec = document.getElementById('sac-allow-section');
  if (allowSec) allowSec.style.display = (sac.mode === 'allowlist') ? '' : 'none';
  // Deny chips
  _renderShareAccessChips('deny', sac.deny);
  // Allow chips
  _renderShareAccessChips('allow', sac.allow);
  // Existing-share conflict hint — list any current share targets whose
  // email is on the deny list. Helps the owner clean up after adding
  // someone to deny *after* an existing share was created (forward-only
  // enforcement, see plan doc).
  const hintEl = document.getElementById('sac-conflict-hint');
  if (hintEl && Array.isArray(_shareTargets) && _shareTargets.length) {
    const denySet = new Set(sac.deny.map(_normEmail));
    const conflicts = _shareTargets.filter(t => t.guestEmail && denySet.has(_normEmail(t.guestEmail)));
    if (conflicts.length) {
      const names = conflicts.map(t => esc(t.name || t.guestEmail)).join(', ');
      hintEl.innerHTML = `<strong>⚠ ${conflicts.length} existing share${conflicts.length===1?'':'s'}</strong> use an email that's on your deny list (${names}). The share${conflicts.length===1?'':'s'} will keep working until you remove them manually below.`;
      hintEl.style.display = '';
    } else {
      hintEl.style.display = 'none';
    }
  } else if (hintEl) {
    hintEl.style.display = 'none';
  }
}

function _renderShareAccessChips(listKey, entries) {
  const slot = document.getElementById(`sac-${listKey}-chips`);
  if (!slot) return;
  if (!entries.length) {
    slot.innerHTML = `<div style="font-size:11px;color:var(--muted);font-style:italic">No entries yet.</div>`;
    return;
  }
  slot.innerHTML = entries.map(email => `
    <div style="display:inline-flex;align-items:center;gap:6px;background:var(--surface2);border:1px solid var(--border);border-radius:99px;padding:4px 4px 4px 10px;font-size:12px">
      <span>${esc(email)}</span>
      <button onclick="removeShareAccessEntry('${listKey}', '${esc(email).replace(/'/g, "\\'")}')"
        aria-label="Remove ${esc(email)}"
        style="background:transparent;border:none;cursor:pointer;color:var(--muted);padding:2px 6px;border-radius:99px;display:flex;align-items:center"
        onmouseover="this.style.color='var(--danger)'" onmouseout="this.style.color='var(--muted)'">
        <svg class="icon icon-sm" aria-hidden="true"><use href="#i-x"></use></svg>
      </button>
    </div>
  `).join('');
}

function toggleShareAccessControlPanel() {
  const body = document.getElementById('share-access-control-body');
  const chev = document.getElementById('sac-chevron');
  if (!body) return;
  const open = body.style.display === 'none' || !body.style.display;
  body.style.display = open ? '' : 'none';
  if (chev) chev.style.transform = open ? 'rotate(180deg)' : '';
  if (open) renderShareAccessControl();
}

async function setShareAccessControlMode(mode) {
  const sac = _ensureShareAccessControl();
  sac.mode = (mode === 'allowlist') ? 'allowlist' : 'open';
  sac.updatedAt = new Date().toISOString();
  await _saveSettings();
  renderShareAccessControl();
}

function onShareAccessInputKey(e, listKey) {
  if (e.key === 'Enter') {
    e.preventDefault();
    addShareAccessEntry(listKey);
  }
}

async function addShareAccessEntry(listKey) {
  const input = document.getElementById(`sac-${listKey}-input`);
  const errEl = document.getElementById(`sac-${listKey}-error`);
  if (!input) return;
  const raw = input.value;
  const email = _normEmail(raw);
  // Basic validation. The same regex pattern the share-create modal uses
  // implicitly via type="email" + form-validation — kept loose deliberately
  // (proper RFC 5322 validation is famously not worth doing).
  const emailLooksValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  if (!emailLooksValid) {
    if (errEl) errEl.textContent = 'Not a valid email address';
    return;
  }
  const sac = _ensureShareAccessControl();
  const list = listKey === 'allow' ? sac.allow : sac.deny;
  // Duplicate detection — case-insensitive
  if (list.map(_normEmail).includes(email)) {
    if (errEl) errEl.textContent = 'Already on this list';
    return;
  }
  // Cross-list conflict — same email can't sit on both deny AND allow.
  // Deny always wins, so if we're adding to allow but it's on deny, refuse.
  const otherKey = listKey === 'allow' ? 'deny' : 'allow';
  const otherList = listKey === 'allow' ? sac.deny : sac.allow;
  if (otherList.map(_normEmail).includes(email)) {
    if (errEl) errEl.textContent = `Already on the ${otherKey} list — remove it from there first`;
    return;
  }
  list.push(email);
  sac.updatedAt = new Date().toISOString();
  input.value = '';
  if (errEl) errEl.textContent = '';
  await _saveSettings();
  renderShareAccessControl();
}

async function removeShareAccessEntry(listKey, email) {
  const sac = _ensureShareAccessControl();
  const list = listKey === 'allow' ? sac.allow : sac.deny;
  const targetNorm = _normEmail(email);
  const before = list.length;
  if (listKey === 'allow') {
    sac.allow = list.filter(e => _normEmail(e) !== targetNorm);
  } else {
    sac.deny = list.filter(e => _normEmail(e) !== targetNorm);
  }
  if (sac.allow.length === before && sac.deny.length === before) return;
  sac.updatedAt = new Date().toISOString();
  await _saveSettings();
  renderShareAccessControl();
}

// Live access-control feedback inside the share-create / share-edit modal.
// Wired on the email input's `oninput` + `onblur`. Renders the deny/allow
// reason inline so the user sees the error before clicking Save.
function onShareTargetEmailInput() {
  const input  = document.getElementById('share-target-email');
  const errEl  = document.getElementById('share-target-email-sac-error');
  if (!input || !errEl) return;
  const val = (input.value || '').trim();
  if (!val) { errEl.textContent = ''; return; }
  // Only check once it looks like a complete email — partial typing
  // ("alice@" etc.) shouldn't flash an error before they've finished.
  const looksValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
  if (!looksValid) { errEl.textContent = ''; return; }
  const check = checkShareAccessControl(val);
  errEl.textContent = check.ok ? '' : check.reason;
}

function renderShareTargetsList() {
  const list = document.getElementById('share-targets-list');
  const btn  = document.getElementById('add-share-target-btn');
  const section = document.getElementById('share-targets-section');
  if (!list) return;

  // Visibility gate: show the section if the user has any owned shares OR
  // has view/edit shareManagement permission on a share they joined as a
  // guest. The previous check (canViewShares alone) hid the entire section
  // for users who own shares AND are also a guest in another household,
  // which is a normal multi-tenant scenario. The owned-shares list comes
  // from _shareTargets (populated by loadShareTargets — the server only
  // returns shares the caller owns), so its non-emptiness is a reliable
  // signal of ownership.
  const hasOwnedShares = Array.isArray(_shareTargets) && _shareTargets.length > 0;
  const viewable = hasOwnedShares || canViewShares();
  if (!viewable) {
    if (section) section.style.display = 'none';
    return;
  }
  if (section) section.style.display = '';

  // Treat the user as effective owner of the Share Access section if they
  // either are not in guest mode at all, OR they have at least one owned
  // share. Without this, an owner-who-also-joined-another-share would see
  // their own shares but with all action buttons hidden (canManageShares
  // returns false because canViewShares only checks guest permissions).
  const editable = hasOwnedShares || canManageShares();

  // Add-person button is hidden in view-only mode
  if (btn) btn.style.display = (editable && _shareTargets.length < 5) ? 'inline-flex' : 'none';

  const typeEmoji = { family: '👨‍👩‍👧', cleaner: '🧹', guest: '👤' };
  if (!_shareTargets.length) {
    list.innerHTML = `<p style="font-size:12px;color:var(--muted)">No one has access yet.</p>`;
  } else {
    list.innerHTML = _shareTargets.map(t => {
      const colour    = t.colour || '#e8a838';
      const members   = t.members?.length || 0;
      const expired   = t.expiresAt && Date.now() > new Date(t.expiresAt).getTime();
      const expiryStr = t.expiresAt ? (expired ? '<svg class="icon" aria-hidden="true"><use href="#i-alert-triangle"></use></svg> Link expired' : `Link valid until ${new Date(t.expiresAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}`) : '';
      const isExpanded = !!_expandedShareCodes[t.code];
      const memberDetails = t.memberDetails || {};

      // Member sub-rows — only meaningful when there are joined members.
      // Each row shows the member's email-hash prefix (we don't store the
      // raw email server-side for privacy), last-active relative time,
      // and a "Remove" button (mgmt-edit only).
      const memberRows = members ? `
        <div style="margin-top:10px;padding-top:10px;border-top:1px solid var(--border);display:${isExpanded?'block':'none'}" id="share-members-${t.code}">
          <div style="font-size:11px;color:var(--muted);margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px">Members</div>
          ${(t.members||[]).map(memberHash => {
            const md = memberDetails[memberHash] || {};
            const lastActive = md.lastActiveAt ? _relTime(md.lastActiveAt) : 'Not yet active';
            const firstSeen  = md.firstSeenAt  ? new Date(md.firstSeenAt).toLocaleDateString() : '—';
            const pulls      = md.pullCount || 0;
            return `<div style="display:flex;align-items:center;gap:8px;padding:6px 8px;background:var(--bg);border-radius:8px;margin-bottom:4px">
              <svg class="icon icon-sm" aria-hidden="true" style="color:var(--muted);flex-shrink:0"><use href="#i-user"></use></svg>
              <div style="flex:1;min-width:0">
                <div style="font-size:11px;font-family:var(--mono);color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(memberHash.slice(0,12))}…</div>
                <div style="font-size:10px;color:var(--muted);margin-top:1px">
                  <svg class="icon" aria-hidden="true" style="width:10px;height:10px;vertical-align:-1px"><use href="#i-clock"></use></svg>
                  ${esc(lastActive)} · joined ${esc(firstSeen)}${pulls>0?` · ${pulls} sync${pulls===1?'':'s'}`:''}
                </div>
              </div>
              ${editable ? `<button class="btn btn-ghost btn-sm" style="color:var(--danger);padding:4px 8px;font-size:11px" onclick="removeShareMember('${t.code}','${memberHash}')" title="Remove this member"><svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg></button>` : ''}
            </div>`;
          }).join('')}
        </div>` : '';

      // Action buttons — full set for owners/edit, none for view-only
      const actionsHtml = editable ? `
        <button class="btn btn-ghost btn-sm" onclick="openEditShareTarget('${t.code}')" title="Edit"><svg class="icon" aria-hidden="true"><use href="#i-pencil"></use></svg></button>
        ${expired
          ? `<button class="btn btn-ghost btn-sm" onclick="refreshShareLink('${t.code}')" title="Refresh link (new 24h window)"><svg class="icon" aria-hidden="true"><use href="#i-refresh-cw"></use></svg></button>`
          : `<button class="btn btn-ghost btn-sm" onclick="copyShareTargetLink('${t.code}')" title="Copy invite link">🔗</button>`
        }
        <button class="btn btn-ghost btn-sm" onclick="resyncSharedData('${t.code}')" title="Re-sync data to guest"><svg class="icon" aria-hidden="true"><use href="#i-share-2"></use></svg></button>
        <button class="btn btn-ghost btn-sm" style="color:var(--danger)" onclick="deleteShareTarget('${t.code}')" title="Remove share"><svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg></button>
      ` : '';

      // Expand/collapse chevron — always present when there are members so
      // viewers can audit who has access even in view-only mode.
      const expandBtn = members ? `<button class="btn btn-ghost btn-sm" onclick="toggleShareMembers('${t.code}')" title="${isExpanded?'Hide':'Show'} members" aria-expanded="${isExpanded}"><svg class="icon" aria-hidden="true" style="transform:rotate(${isExpanded?180:0}deg);transition:transform 0.15s"><use href="#i-chevron-down"></use></svg></button>` : '';

      return `
      <div style="display:flex;flex-direction:column;padding:10px 12px;background:var(--surface2);border:1px solid ${expired?'var(--danger)':'var(--border)'};border-radius:10px">
        <div style="display:flex;align-items:center;gap:10px">
          <div style="width:12px;height:12px;border-radius:50%;background:${colour};flex-shrink:0;box-shadow:0 1px 4px rgba(0,0,0,0.3)"></div>
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:700">${typeEmoji[t.type]||'👤'} ${esc(t.name)}</div>
            <div style="font-size:11px;color:var(--muted);font-family:var(--mono)">${t.type}${members?' · '+members+' member'+(members!==1?'s':''):''}${t.shareManagement && t.shareManagement !== 'none' ? ' · share-'+t.shareManagement : ''}</div>
            ${expiryStr?`<div style="font-size:10px;color:${expired?'var(--danger)':'var(--muted)'};margin-top:2px">${expiryStr}</div>`:''}
          </div>
          ${expandBtn}
          ${actionsHtml}
        </div>
        ${memberRows}
      </div>`;
    }).join('');
  }
  const clearBtn = document.getElementById('clear-all-shares-btn');
  if (clearBtn) clearBtn.style.display = (editable && _shareTargets.length > 0) ? 'inline-flex' : 'none';
  // Refresh the Share Access Control summary alongside — it lives in the
  // same Settings → Household Sharing section, and its conflict hint
  // depends on the share-targets list we just refreshed above.
  try { renderShareAccessControl(); } catch (_) {}
}

// Toggle expand/collapse for a share row's member list. Survives
// re-renders within a session but resets on page reload.
function toggleShareMembers(code) {
  _expandedShareCodes[code] = !_expandedShareCodes[code];
  renderShareTargetsList();
}

// Human-readable relative time ("3 mins ago", "2 hours ago", etc).
// Used for last-active timestamps in the member list.
function _relTime(iso) {
  if (!iso) return '—';
  const ms = Date.now() - new Date(iso).getTime();
  if (ms < 0) return 'just now';
  const s = Math.floor(ms/1000);
  if (s < 60)   return 'just now';
  const m = Math.floor(s/60);
  if (m < 60)   return `${m} min${m===1?'':'s'} ago`;
  const h = Math.floor(m/60);
  if (h < 24)   return `${h} hour${h===1?'':'s'} ago`;
  const d = Math.floor(h/24);
  if (d < 30)   return `${d} day${d===1?'':'s'} ago`;
  return new Date(iso).toLocaleDateString();
}

// Surgically remove a single member from a share. Calls the
// /share/member/remove endpoint which evicts them, drops their wrapped
// share key, and writes a 7-day revocation marker so their next pull
// returns 403 fast and they self-clean.
async function removeShareMember(code, memberHash) {
  const target = _shareTargets.find(t => t.code === code);
  if (!target) return;
  const memberLabel = memberHash.slice(0, 12) + '…';
  if (!confirm(`Remove this member (${memberLabel}) from "${target.name}"?\n\nThey'll lose access immediately on their next sync, and their copy of the shared data will clear from their device. Other members of this share are unaffected.`)) return;
  try {
    const authFields = _kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier };
    const res = await postKV(`${WORKER_URL}/share/member/remove`, {
      ownerEmailHash: _kvEmailHash, ...authFields, code, guestEmailHash: memberHash,
    });
    if (!res.ok) {
      const d = await _readJsonSafe(res) || {};
      throw new Error(d.error || 'Could not remove member');
    }
    toast('Member removed ✓');
    await loadShareTargets();
  } catch(err) {
    toast('Could not remove member: ' + err.message);
  }
}

// Render the three-button None / View / Edit selector for share-management.
// Lives in a dedicated region above the per-household perms grid. If the
// host HTML doesn't include a #share-mgmt-perm element, this auto-injects
// one above #share-household-perms so the picker still renders.
function renderShareMgmtPicker() {
  let el = document.getElementById('share-mgmt-perm');
  if (!el) {
    const anchor = document.getElementById('share-household-perms');
    if (!anchor || !anchor.parentNode) return;
    const wrap = document.createElement('div');
    wrap.style.cssText = 'margin-bottom:10px';
    wrap.innerHTML = `
      <div style="font-size:11px;color:var(--muted);margin-bottom:6px;text-transform:uppercase;letter-spacing:0.5px">Share-access management</div>
      <div id="share-mgmt-perm" style="display:flex;gap:6px;flex-wrap:wrap"></div>`;
    anchor.parentNode.insertBefore(wrap, anchor);
    el = document.getElementById('share-mgmt-perm');
    if (!el) return;
  }
  const opts = [
    { v: 'none', label: '🔒 None', hint: 'Cannot see share access' },
    { v: 'view', label: '👁 View', hint: 'Can see who has access (read-only)' },
    { v: 'edit', label: '✏️ Edit', hint: 'Can add, edit, remove share access' },
  ];
  el.innerHTML = opts.map(o => {
    const active = o.v === _shareTargetMgmt;
    return `<button onclick="setShareMgmt('${o.v}')" type="button"
      style="flex:1;min-width:90px;padding:8px 10px;border-radius:8px;cursor:pointer;font-size:12px;
             border:1px solid ${active?'var(--accent)':'var(--border)'};
             background:${active?'rgba(232,168,56,0.15)':'transparent'};
             color:${active?'var(--accent)':'var(--muted)'};transition:all 0.15s;
             display:flex;flex-direction:column;align-items:flex-start;gap:2px;text-align:left">
      <span style="font-weight:600">${o.label}</span>
      <span style="font-size:10px;color:var(--muted);font-weight:400">${o.hint}</span>
    </button>`;
  }).join('');
}

function setShareMgmt(v) {
  _shareTargetMgmt = v;
  renderShareMgmtPicker();
}

function renderShareTargetColourPicker(selectedColour) {
  const el = document.getElementById('share-target-colours');
  if (!el) return;
  el.innerHTML = HOUSEHOLD_COLOURS.map(c => `
    <div onclick="selectShareTargetColour('${c}')"
      data-colour="${c}"
      style="width:26px;height:26px;border-radius:50%;background:${c};cursor:pointer;
             border:3px solid ${c === selectedColour ? 'var(--text)' : 'transparent'};
             transition:border-color 0.15s;box-shadow:0 2px 5px rgba(0,0,0,0.3)"></div>
  `).join('');
}

function selectShareTargetColour(colour) {
  _shareTargetColour = colour;
  document.querySelectorAll('#share-target-colours [data-colour]').forEach(el => {
    el.style.borderColor = el.dataset.colour === colour ? 'var(--text)' : 'transparent';
  });
}

function selectShareType(type, btn) {
  _shareTargetType = type;
  document.querySelectorAll('.share-type-btn').forEach(b => {
    const isActive = b.dataset.type === type;
    b.style.borderColor = isActive ? 'var(--accent)' : 'var(--border)';
    b.style.background  = isActive ? 'rgba(232,168,56,0.1)' : 'transparent';
    b.style.color       = isActive ? 'var(--accent)' : 'var(--muted)';
  });
  // Apply defaults for this type to all households
  Object.keys(_shareTargetPerms).forEach(hKey => {
    const defaults = SHARE_TYPE_DEFAULTS[type] || SHARE_TYPE_DEFAULTS.guest;
    _shareTargetPerms[hKey] = { ...defaults };
  });
  // Reset share-management permission to type default (always 'none' today —
  // there's no per-type override yet, but keeping the indirection makes
  // future tweaks one-line).
  _shareTargetMgmt = SHARE_MGMT_DEFAULTS[type] || 'none';
  renderShareMgmtPicker();
  renderShareHouseholdPerms();
}

async function renderShareHouseholdPerms() {
  const container = document.getElementById('share-household-perms');
  if (!container) return;
  const profiles  = await getProfiles();
  const sections  = ['stockroom','groceries','reminders','savings','report','budget'];
  const defaults  = SHARE_TYPE_DEFAULTS[_shareTargetType] || SHARE_TYPE_DEFAULTS.guest;

  container.innerHTML = Object.entries(profiles).map(([key, p]) => {
    const hName  = p.name || (key === 'default' ? 'Home' : key);
    const colour = p.colour || '#e8a838';
    const perms  = _shareTargetPerms[key] || { ...defaults };
    _shareTargetPerms[key] = perms;

    return `<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:12px">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:10px">
        <div style="width:10px;height:10px;border-radius:50%;background:${colour}"></div>
        <strong style="font-size:13px">${esc(hName)}</strong>
      </div>
      <div style="display:flex;flex-direction:column;gap:6px">
        ${sections.map(s => {
          const val = perms[s] || 'none';
          return `<div style="display:flex;align-items:center;justify-content:space-between;gap:8px">
            <span style="font-size:12px;color:var(--muted)">${SECTION_LABELS[s]||s}</span>
            <div style="display:flex;gap:4px">
              ${['none','r','rw'].map(opt => `
                <button onclick="setSharePerm('${key}','${s}','${opt}')"
                  id="spm-${key}-${s}-${opt}"
                  style="padding:3px 8px;border-radius:6px;font-size:11px;cursor:pointer;
                         border:1px solid ${val===opt?'var(--accent)':'var(--border)'};
                         background:${val===opt?'rgba(232,168,56,0.15)':'transparent'};
                         color:${val===opt?'var(--accent)':'var(--muted)'};transition:all 0.15s">
                  ${opt==='none'?'🔒 None':opt==='r'?'👁 View':'✏️ Edit'}
                </button>`).join('')}
            </div>
          </div>`;
        }).join('')}
      </div>
    </div>`;
  }).join('');
}

function setSharePerm(hKey, section, value) {
  if (!_shareTargetPerms[hKey]) _shareTargetPerms[hKey] = {};
  _shareTargetPerms[hKey][section] = value;
  // Update button states
  ['none','r','rw'].forEach(opt => {
    const btn = document.getElementById(`spm-${hKey}-${section}-${opt}`);
    if (!btn) return;
    const active = opt === value;
    btn.style.borderColor = active ? 'var(--accent)' : 'var(--border)';
    btn.style.background  = active ? 'rgba(232,168,56,0.15)' : 'transparent';
    btn.style.color       = active ? 'var(--accent)' : 'var(--muted)';
  });
}

async function openAddShareTarget() {
  // Owners (not in guest mode at all) can always add. Users in guest mode
  // can add IF they have shareManagement edit permission on the share they
  // joined, OR they already own shares of their own (the typical case for a
  // returning user who's a tenant on another household and also runs their
  // own). Without the hasOwnedShares clause, an owner who happened to join
  // another share would see their own Share Access section but be unable
  // to add new entries to it.
  const hasOwnedShares = Array.isArray(_shareTargets) && _shareTargets.length > 0;
  if (!isOwner() && !canManageShares() && !hasOwnedShares) {
    toast('Only the household owner can manage share access');
    return;
  }
  if (_shareTargets.length >= 5) { toast('Maximum 5 share targets reached'); return; }
  _shareTargetType   = 'family';
  _shareTargetPerms  = {};
  _shareTargetColour = HOUSEHOLD_COLOURS[_shareTargets.length % HOUSEHOLD_COLOURS.length];
  _shareTargetMgmt   = SHARE_MGMT_DEFAULTS.family;
  const profiles     = await getProfiles();
  const defaults     = SHARE_TYPE_DEFAULTS.family;
  // Always include at least the default household
  const profileKeys  = Object.keys(profiles).length ? Object.keys(profiles) : ['default'];
  profileKeys.forEach(k => { _shareTargetPerms[k] = { ...defaults }; });

  _shareTargetDone   = false;
  document.getElementById('share-target-modal-title').innerHTML = '<svg class="icon icon-md" aria-hidden="true" style="color:var(--accent);vertical-align:-3px"><use href="#i-user"></use></svg> Add Person';
  document.getElementById('share-target-code').value = '';
  document.getElementById('share-target-name').value = '';
  document.getElementById('share-target-email').value = '';
  // Clear any lingering deny/allow inline error from a previous open
  const _sacErr = document.getElementById('share-target-email-sac-error');
  if (_sacErr) _sacErr.textContent = '';
  // Hide the "send notification" checkbox — only relevant on edit
  const sendEmailRow = document.getElementById('share-send-email-row');
  if (sendEmailRow) sendEmailRow.style.display = 'none';
  hide('share-link-section');
  document.getElementById('share-target-save-btn').textContent = 'Create & get link';
  // Restore the three sections that bulk-share mode hides (Role / Access
  // per household / Share management). When openAddShareTarget runs from
  // the normal Settings → Add Person path, these need to be visible. The
  // bulk-share flow re-hides them in bulkShareCreateNew AFTER this
  // function returns, so the order is: reset everything → hide as needed.
  const _row1 = document.getElementById('share-target-role-row');
  const _row2 = document.getElementById('share-target-perms-row');
  const _row3 = document.getElementById('share-target-mgmt-row');
  if (_row1) _row1.style.display = '';
  if (_row2) _row2.style.display = '';
  if (_row3) _row3.style.display = '';
  // Also clear any leftover bulk-share banner from a prior invocation.
  document.getElementById('bulk-share-pending-banner')?.remove();
  selectShareType('family', document.querySelector('.share-type-btn[data-type="family"]'));
  renderShareTargetColourPicker(_shareTargetColour);
  renderShareMgmtPicker();
  await renderShareHouseholdPerms();
  openModal('share-target-modal');
}

async function openEditShareTarget(code) {
  const target = _shareTargets.find(t => t.code === code);
  if (!target) return;
  _shareTargetType   = target.type || 'family';
  _shareTargetPerms  = JSON.parse(JSON.stringify(target.households || {}));
  _shareTargetColour = target.colour || HOUSEHOLD_COLOURS[0];
  _shareTargetMgmt   = target.shareManagement || 'none';
  _shareTargetDone   = false;

  document.getElementById('share-target-modal-title').innerHTML = '<svg class="icon icon-md" aria-hidden="true" style="color:var(--accent);vertical-align:-3px"><use href="#i-pencil"></use></svg> Edit Access';
  document.getElementById('share-target-code').value = code;
  document.getElementById('share-target-name').value = target.name || '';

  // Restore plain label text (same as create)
  const emailGroup = document.getElementById('share-target-email-group');
  if (emailGroup) emailGroup.style.display = 'block';
  const emailLabel = document.querySelector('#share-target-email-group label');
  if (emailLabel) emailLabel.textContent = 'Their email address';
  const emailHint = document.querySelector('#share-target-email-group p');
  if (emailHint) emailHint.textContent = 'Their email is used to encrypt the share key — it never leaves your device.';
  // Pre-fill saved email
  document.getElementById('share-target-email').value = target.guestEmail || '';

  // Show "send email notification" checkbox (hidden on create screen)
  const sendEmailRow = document.getElementById('share-send-email-row');
  if (sendEmailRow) sendEmailRow.style.display = 'block';
  const sendEmailCb = document.getElementById('share-send-email-cb');
  if (sendEmailCb) sendEmailCb.checked = false;

  hide('share-link-section');
  document.getElementById('share-target-save-btn').textContent = 'Save changes';
  selectShareType(_shareTargetType, document.querySelector(`.share-type-btn[data-type="${_shareTargetType}"]`));
  // selectShareType resets _shareTargetMgmt to type default; restore the
  // saved value AFTER so the editor shows what's actually stored.
  _shareTargetMgmt = target.shareManagement || 'none';
  renderShareTargetColourPicker(_shareTargetColour);
  renderShareMgmtPicker();
  await renderShareHouseholdPerms();
  openModal('share-target-modal');
}

async function saveShareTarget() {
  const name = document.getElementById('share-target-name').value.trim();
  if (!name) { toast('Enter a name for this person'); return; }
  const code      = document.getElementById('share-target-code').value;
  const colour    = _shareTargetColour;
  const profiles  = await getProfiles();
  const ownerName = settings.email?.split('@')[0] || profiles['default']?.name || 'Home';
  const btn = document.getElementById('share-target-save-btn');
  if (btn) { btn.textContent = '⏳'; btn.disabled = true; }

  try {
    if (code) {
      // Update existing — re-use existing share key.
      // Deny / allow check: only fires if the email is being CHANGED to a
      // newly-restricted value. Editing other fields on an existing share
      // whose email is already denied is fine — the share exists, the
      // owner is allowed to keep it (forward-only enforcement). The
      // renderShareAccessControl conflict hint already nudges them to
      // remove these shares manually if they want.
      const _currentTgt    = _shareTargets.find(t => t.code === code);
      const _existingEmail = _normEmail(_currentTgt?.guestEmail || '');
      const _editingEmail  = _normEmail(document.getElementById('share-target-email')?.value || '');
      if (_editingEmail && _editingEmail !== _existingEmail) {
        const sacCheck = checkShareAccessControl(_editingEmail);
        if (!sacCheck.ok) { if (btn) { btn.textContent = 'Save changes'; btn.disabled = false; } toast(sacCheck.reason); return; }
      }
      // Update existing — re-use existing share key
      const res = await postKV(`${WORKER_URL}/share/update`, { ownerEmailHash: _kvEmailHash, verifier: _kvVerifier, sessionToken: _kvSessionToken, code, name, type: _shareTargetType, colour, households: _shareTargetPerms, shareManagement: _shareTargetMgmt });
      if (!res.ok) { const d = await res.json().catch(()=>({})); throw new Error(d.error || 'Update failed'); }
      await pushSharedData(code);

      // Always persist the email address; only send notification if checkbox ticked
      const guestEmailEl  = document.getElementById('share-target-email');
      const guestEmailVal = guestEmailEl?.value.trim();
      const tgt = _shareTargets.find(t => t.code === code);
      if (tgt && guestEmailVal) tgt.guestEmail = guestEmailVal;
      const sendEmailCb = document.getElementById('share-send-email-cb');
      if (guestEmailVal && sendEmailCb?.checked && WORKER_URL) {
        await _sendShareEmail(guestEmailVal, { code, name, type: _shareTargetType, households: _shareTargetPerms, isUpdate: true }).catch(() => {});
      }

      await loadShareTargets();
      closeModal('share-target-modal');
      toast(`✓ ${name}'s access updated`);
    } else {
      // Create new — ECDH key wrapping flow
      const guestEmail = document.getElementById('share-target-email')?.value.trim();
      if (!guestEmail) throw new Error('Enter their email address so their share key can be encrypted for them');

      // Forward-only enforcement of the deny / allow lists. The check exists
      // only here at share-create time — existing shares are unaffected when
      // someone is added to the deny list later (renderShareAccessControl
      // shows a conflict hint instead). The check is client-side only by
      // design — the lists exist to protect the owner from themselves.
      const sacCheck = checkShareAccessControl(guestEmail);
      if (!sacCheck.ok) throw new Error(sacCheck.reason);

      // 1. Hash guest email → fetch their ECDH public key. A 404 means the
      //    recipient hasn't signed up yet — that's a supported case via
      //    pendingInvite (server stores the invite; owner's rewrap queue
      //    finishes the ECDH wrap once the recipient registers and uploads
      //    their pubkey).
      const guestEmailHash = await kvHashEmail(guestEmail);
      const pubRes         = await postKV(`${WORKER_URL}/user/ecdh-pubkey/get`, { emailHash: guestEmailHash });
      const guestExists    = pubRes.ok;
      if (!pubRes.ok && pubRes.status !== 404) throw new Error('Could not fetch their encryption key — try again');
      const guestPubKeyJwk = guestExists ? (await pubRes.json()).publicKeyJwk : null;

      // 2. Load our own ECDH private key
      const ownerPrivKey = await loadEcdhPrivateKey(_kvEmailHash);
      if (!ownerPrivKey) throw new Error('Your encryption key is missing — try signing out and back in');

      // 3. Generate the AES-GCM share key
      const shareKey    = await generateShareKey();
      const shareKeyB64 = await exportShareKey(shareKey);

      // 4. ECDH-wrap the share key for the guest — only if they exist now.
      //    If they don't exist yet, the wrap happens later (see rewrap queue).
      const wrappedKey = guestExists
        ? await ecdhWrapShareKey(ownerPrivKey, guestPubKeyJwk, shareKey)
        : null;

      // 5. Export our own public key JWK to send alongside (guest needs it to unwrap)
      const ownerPubRes = await postKV(`${WORKER_URL}/user/ecdh-pubkey/get`, { emailHash: _kvEmailHash });
      if (!ownerPubRes.ok) throw new Error('Could not fetch your encryption key — try again');
      const { publicKeyJwk: ownerPubKeyJwk } = await ownerPubRes.json();

      // 6. Create share on server. Include pendingInvite when the recipient
      //    doesn't have an account yet, so the share-join flow and owner UI
      //    can show "awaiting signup" state for this entry.
      const res = await postKV(`${WORKER_URL}/share/create`, {
          ownerEmailHash: _kvEmailHash,
          ..._kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier },
          name, type: _shareTargetType, colour, ownerName,
          households: _shareTargetPerms,
          shareManagement: _shareTargetMgmt,
          householdNames: Object.fromEntries(
            Object.entries(profiles).map(([k,p]) => [k, p.name||(k==='default'?'Home':k)])
          ),
          ...(guestExists ? {} : { pendingInvite: { guestEmailHash, guestEmail } }),
        });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed');

      // 7. Store ECDH-wrapped key on server for the guest — only if we
      //    actually wrapped one. For pending invites, the wrapped key is
      //    deferred until the guest signs up and the rewrap queue runs.
      if (wrappedKey) {
        const ecdhStoreRes = await postKV(`${WORKER_URL}/share/ecdh-key/store`, {
            ownerEmailHash: _kvEmailHash,
            ..._kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier },
            code: data.code,
            guestEmailHash,
            wrappedKey,
            ownerPublicKeyJwk: ownerPubKeyJwk,
          });
        if (!ecdhStoreRes.ok) throw new Error('Could not store encrypted share key — try again');
      }

      // 8. Cache share key locally and back it up (for owner cross-device recovery)
      try {
        const stored = await _getShareKeys();
        stored[data.code] = shareKeyB64;
        await _setShareKeys(stored);
      } catch(e) {}
      await backupShareKey(data.code, shareKey).catch(e => console.warn('Share key backup failed:', e.message));

      // 9. Push initial shared data
      await pushSharedData(data.code, shareKey);

      // 10. Share created — enable household, close modal, show link in toast
      if (!_householdEnabled) {
        _householdEnabled = true;
        try { localStorage.setItem('stockroom_household', JSON.stringify({ enabled: true, colour: _householdColour })); } catch(e) {}
        connectPresence();
      }

      // Copy link to clipboard and close modal — no "Done" step needed
      const inviteLink = data.link || `${location.origin}${location.pathname}?join=${data.code}`;
      try { await navigator.clipboard.writeText(inviteLink); } catch(e) {}

      // Send invite email if address provided
      const createEmailEl = document.getElementById('share-target-email');
      const createEmailVal = createEmailEl?.value.trim();
      if (createEmailVal && WORKER_URL) {
        await _sendShareEmail(createEmailVal, {
          code: data.code, name, type: _shareTargetType,
          households: _shareTargetPerms, isUpdate: false, inviteLink,
        }).catch(() => {});
      }

      await loadShareTargets();
      closeModal('share-target-modal');
      _shareTargetDone = false; // reset for next use

      // Bulk-share hand-off — if this share was created via the
      // selection-driven flow (bulkShareCreateNew), apply allow
      // overrides to the selected records now that we have a share code.
      // The Pending state's `section` field routes the apply to the right
      // section spec (stock, grocery, reminder, transaction).
      // Fire-and-forget — failures only toast a warn, the share itself
      // is already created and saved.
      try { await _applyBulkSharePending(data.code); } catch(e) { console.warn('_applyBulkSharePending failed:', e); }
      // Clear the pending-bulk-share banner if it was inserted.
      document.getElementById('bulk-share-pending-banner')?.remove();

      toast(`✓ Share created — link copied! Send it to ${name}`);
      if (kvConnected) setTimeout(syncAll, 600);
    }
  } catch(err) {
    console.error('saveShareTarget:', err);
    toast('Could not save: ' + err.message);
    if (btn) { btn.textContent = code ? 'Save changes' : 'Create & get link'; btn.disabled = false; }
  }
}

// Encrypt the raw share key with the owner's data key and store on server.
// This lets the owner recover the share key on any device.
async function backupShareKey(code, shareKey) {
  if (!_kvKey || !_kvEmailHash || (!_kvVerifier && !_kvSessionToken)) return;
  const raw        = await crypto.subtle.exportKey('raw', shareKey);
  const ciphertext = await kvEncrypt(_kvKey, btoa(String.fromCharCode(...new Uint8Array(raw))));
  await postKV(`${WORKER_URL}/share/key/store`, { ownerEmailHash: _kvEmailHash, verifier: _kvVerifier, sessionToken: _kvSessionToken, code, encryptedShareKey: ciphertext });
}

// Recover share key from server — decrypts with owner's data key.
// Returns a CryptoKey or null.
async function recoverShareKey(code) {
  if (!_kvKey || !_kvEmailHash || (!_kvVerifier && !_kvSessionToken)) return null;
  try {
    const res = await postKV(`${WORKER_URL}/share/key/get`, { ownerEmailHash: _kvEmailHash, verifier: _kvVerifier, sessionToken: _kvSessionToken, code });
    if (!res.ok) return null;
    const { encryptedShareKey } = await res.json();
    if (!encryptedShareKey) return null;
    const keyB64 = await kvDecrypt(_kvKey, encryptedShareKey);
    const raw    = Uint8Array.from(atob(keyB64), c => c.charCodeAt(0));
    const sk     = await crypto.subtle.importKey('raw', raw, { name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
    // Cache locally so subsequent pushes don't need a round-trip
    try {
      const stored = await _getShareKeys();
      stored[code] = keyB64;
      await _setShareKeys(stored);
    } catch(e) {}
    return sk;
  } catch(e) {
    console.warn('recoverShareKey failed:', e.message);
    return null;
  }
}

// Push owner's data re-encrypted with the share key for a specific share code
async function pushSharedData(code, shareKey) {
  if (!_kvKey) return;
  // Get or restore share key — local cache first, then server backup
  let sk = shareKey;
  if (!sk) {
    try {
      const stored = await _getShareKeys();
      const keyB64 = stored[code];
      if (keyB64) {
        const raw = Uint8Array.from(atob(keyB64), c => c.charCodeAt(0));
        sk = await crypto.subtle.importKey('raw', raw, { name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
      }
    } catch(e) {}
  }
  // If still missing, try recovering from server
  if (!sk) {
    sk = await recoverShareKey(code);
  }
  if (!sk) {
    console.warn('pushSharedData: no share key for', code, '— skipping');
    return;
  }

  // Find which households this share code covers
  const target = _shareTargets.find(t => t.code === code);
  const households = target?.households ? Object.keys(target.households) : ['default'];

  // Grocery list tombstones live at user-level (not per-household), so load
  // once outside the per-household loop and reuse for each share payload.
  const groceryListTombstones = await loadGroceryListDeletedIds();

  for (const hKey of households) {
    try {
      // Build full payload for this household (same shape as kvPush so guest merge works)
      const allProfiles = await getProfiles();
      const hProfile    = allProfiles[hKey] || allProfiles['default'];
      const hItems      = hKey === activeProfile ? items       : (hProfile?.items      || []);
      const hSettings   = hKey === activeProfile ? settings    : (hProfile?.settings   || {});
      const hGroceries  = hKey === activeProfile ? groceryItems: (hProfile?.groceries  || []);
      const hReminders  = hKey === activeProfile ? reminders   : (hProfile?.reminders  || []);
      const hDepts      = hKey === activeProfile ? groceryDepts: (hProfile?.departments|| []);

      // Respect per-section permissions — only push what the guest can view
      const perms = target?.households?.[hKey] || {};
      const canSeeStockroom  = perms.stockroom  && perms.stockroom  !== 'none';
      const canSeeGroceries  = perms.groceries  && perms.groceries  !== 'none';
      const canSeeReminders  = perms.reminders  && perms.reminders  !== 'none';
      const canSeeBudget     = perms.budget     && perms.budget     !== 'none';

      // Per-record filter pass (Part B foundation). Each section's records
      // are routed through _filterRecordsForShare, which drops anything the
      // share's per-record perm resolves to 'none' and annotates the rest
      // with their effective perm (only when it differs from section).
      //
      // Why share code, not member email hash: the share blob is encrypted
      // once with the share's key, and ALL members of that share decrypt
      // it. We can't put a per-member filtered view in the same blob.
      // The unit of access the crypto can actually enforce is the share
      // itself — so the discriminator is the share code. If a user wants
      // different perms for spouse vs. adult child, they go on separate
      // shares.
      //
      // For each section, apply the filter only when the section is
      // visible. The share `code` is already in scope from the outer
      // function signature.
      const filteredItems     = canSeeStockroom
        ? _filterRecordsForShare(hItems, code, perms.stockroom)
        : [];
      const filteredGroceries = canSeeGroceries
        ? _filterRecordsForShare(hGroceries, code, perms.groceries)
        : [];
      const filteredReminders = canSeeReminders
        ? _filterRecordsForShare(hReminders, code, perms.reminders)
        : [];
      const filteredGroceryLists = canSeeGroceries
        ? _filterRecordsForShare(groceryLists, code, perms.groceries)
        : [];
      // ── Budget filter (Pass 2e-a) ──
      // Per-category sharing: walk budgetCategories to compute the
      // allowed-cat-id set for THIS share, then filter both categories
      // and transactions by that set. Uncategorised transactions
      // (categoryId == null) are always owner-private.
      //
      // Other budget data (accounts, income, bills) stays section-level —
      // category-membership filtering doesn't apply to those. The
      // section perm 'r'/'rw' gates them as before.
      const budgetFiltered = canSeeBudget
        ? _filterBudgetForShare(budgetCategories, transactions, code, perms.budget)
        : { allowedCatIds: new Set(), categories: [], transactions: {} };

      const payload = JSON.stringify({
        items:       filteredItems,
        settings:    hSettings,
        groceries:   filteredGroceries,
        reminders:   filteredReminders,
        departments: canSeeGroceries ? hDepts     : [],
        // Grocery lists (named lists like "Tesco" / "Costco") + their
        // tombstones live at user-level, not per-household. Without these
        // a guest pulling the share blob would see grocery ITEMS but no
        // named-list structure, leaving items orphaned in the default list.
        groceryLists:            filteredGroceryLists,
        groceryListDeletedIds:   canSeeGroceries ? [...groceryListTombstones] : [],
        // Budget — Phase 1 (bills) + Phase 2 (categories, transactions) + Phase 3 (accounts, income).
        // Lives at user-level (not per-household), so the same data goes to every share with budget perm.
        bills:                       canSeeBudget ? bills           : [],
        billInstances:               canSeeBudget ? billInstances   : {},
        budgetSettings:              canSeeBudget ? budgetSettings  : {},
        // Categories + transactions filtered by per-category share state.
        // Tombstones flow unfiltered — knowing an unknown id was deleted
        // tells the guest nothing they didn't already know nothing about.
        budgetCategories:            budgetFiltered.categories,
        transactions:                budgetFiltered.transactions,
        budgetCategoryDeletedIds:    canSeeBudget ? [...budgetCategoryDeletedIds]    : [],
        budgetTransactionDeletedIds: canSeeBudget ? [...budgetTransactionDeletedIds] : [],
        budgetAccounts:              canSeeBudget ? budgetAccounts  : [],
        incomeTemplates:             canSeeBudget ? incomeTemplates : [],
        incomeEntries:               canSeeBudget ? incomeEntries   : {},
        budgetAccountDeletedIds:     canSeeBudget ? [...budgetAccountDeletedIds]   : [],
        incomeTemplateDeletedIds:    canSeeBudget ? [...incomeTemplateDeletedIds]  : [],
        incomeEntryDeletedIds:       canSeeBudget ? [...incomeEntryDeletedIds]    : [],
        // Per-note sharing. Notes don't sit under a section perm — each
        // note's `share` field is the sole gate. _filterNotesForShare
        // walks the notes array, includes any whose share resolves to
        // r/rw for THIS share code, drops locked + trashed notes, and
        // strips the owner-only `share` field. Annotates each note with
        // `_shareEffectivePerm: 'r' | 'rw'` so the recipient's UI knows
        // whether the note is read-only or editable. (Pass 3a: no rw
        // semantics enforced yet on the guest side — that lands in 3b.)
        sharedNotes: _filterNotesForShare(notes, code),
        lastSynced:  new Date().toISOString(),
      });
      const ciphertext  = await encryptWithShareKey(sk, payload);
      const authFields  = _kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier };
      await postKV(`${WORKER_URL}/share/data/push`, { ownerEmailHash: _kvEmailHash, ...authFields, code, household: hKey, ciphertext });
    } catch(e) { console.warn('pushSharedData failed for', hKey, e.message); }
  }
}

// Push shared data for ALL active share targets (called from kvPush)
//
// Race window note: there's a short window (typically <1s) between absorb
// and push during which a guest's new write could land in the share blob.
// The owner's push then overwrites that write with stale state. The next
// sync cycle catches it (the guest's write gets re-absorbed and the owner
// re-pushes). For v1 we accept this trade-off rather than adding a compare-
// and-swap on the share blob. If real users hit this, the closing move is
// to re-check /share/tips inside this loop and skip pushes for any blob
// whose modified time changed since absorb.
async function pushAllSharedData() {
  if (!_shareTargets?.length) return;
  for (const target of _shareTargets) {
    await pushSharedData(target.code).catch(e => console.warn('pushAllSharedData failed for', target.code, e.message));
    // Also fulfil any pending rewrap requests from new guests
    await _fulfilPendingRewraps(target.code).catch(e => console.warn('rewrap failed for', target.code, e.message));
  }
}

// ── Owner-side share absorb ────────────────────────────────────────────────
//
// When a guest writes via /share/data/push-guest, their changes land in the
// share blob's KV slot but DO NOT make it into the owner's own data blob.
// Without this absorb step, guest writes are invisible to the owner forever,
// and worse, the next owner push overwrites the share blob with the owner's
// stale data — silently losing the guest's changes.
//
// absorbSharedData runs BEFORE the owner pushes. It pulls each share blob via
// /share/data/pull-owner, decrypts with the share key, and merges guest writes
// into the owner's in-memory state using the standard mergeItems / mergeGroceries
// helpers (field-level LWW via _fieldTs handles conflicts). After absorption
// the owner's local state is up-to-date, and the subsequent push reflects
// both their own and the guest's changes.
//
// Per-share lastAbsorbed timestamps are kept in localStorage to skip work
// when nothing has changed since last absorb.
const _ABSORB_STAMPS_KEY = 'stockroom_share_absorbed_modified';

function _getAbsorbStamps() {
  try { return JSON.parse(localStorage.getItem(_ABSORB_STAMPS_KEY) || '{}'); }
  catch(_) { return {}; }
}
function _setAbsorbStamp(code, hKey, isoTime) {
  const all = _getAbsorbStamps();
  all[`${code}:${hKey}`] = isoTime;
  try { localStorage.setItem(_ABSORB_STAMPS_KEY, JSON.stringify(all)); } catch(_) {}
}
function _getAbsorbStamp(code, hKey) {
  return _getAbsorbStamps()[`${code}:${hKey}`] || null;
}

// Returns true if anything was absorbed (caller may want to re-render).
async function absorbAllSharedData() {
  if (!kvConnected || !_shareTargets?.length) return false;
  // Cheap multi-tip check first — avoid pulling blobs whose modified time
  // matches what we've already absorbed.
  const codes = _shareTargets.map(t => t.code);
  let tips = {};
  try {
    const authFields = _kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier };
    const tipsRes = await postKV(`${WORKER_URL}/share/tips`, { emailHash: _kvEmailHash, ...authFields, codes });
    if (tipsRes.ok) {
      const body = await _readJsonSafe(tipsRes) || {};
      tips = body.tips || {};
    }
  } catch(e) { console.warn('absorbAllSharedData: tips fetch failed', e.message); }

  let anyAbsorbed = false;
  for (const target of _shareTargets) {
    if (!target.households) continue;
    for (const hKey of Object.keys(target.households)) {
      const tipKey = `${target.code}:${hKey}`;
      const tip = tips[tipKey];
      // If tips were unavailable (network blip etc), fall through and try
      // the absorb anyway — we'd rather over-pull than miss writes.
      if (tip) {
        // Skip if last writer was us — no guest changes since our own push.
        if (tip.writer === 'owner') continue;
        // Skip if modified time matches what we already absorbed.
        const last = _getAbsorbStamp(target.code, hKey);
        if (last && tip.modified && last === tip.modified) continue;
      }
      try {
        const absorbed = await absorbSharedData(target.code, hKey);
        if (absorbed) anyAbsorbed = true;
      } catch(e) {
        console.warn('absorbSharedData failed for', target.code, hKey, e.message);
      }
    }
  }
  return anyAbsorbed;
}

// Absorb a single (code, household) share blob — pull, decrypt, merge.
async function absorbSharedData(code, hKey) {
  // Need the share key (same one used to push to this share).
  let sk = null;
  try {
    const stored = await _getShareKeys();
    const keyB64 = stored[code];
    if (keyB64) {
      const raw = Uint8Array.from(atob(keyB64), c => c.charCodeAt(0));
      sk = await crypto.subtle.importKey('raw', raw, { name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
    }
  } catch(_) {}
  if (!sk) sk = await recoverShareKey(code);
  if (!sk) { console.warn('absorbSharedData: no share key for', code); return false; }

  const authFields = _kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier };
  const res = await postKV(`${WORKER_URL}/share/data/pull-owner`, {
    ownerEmailHash: _kvEmailHash, ...authFields, code, household: hKey,
  });
  if (!res.ok) return false;
  const body = await _readJsonSafe(res) || {};
  if (!body.ciphertext) return false;
  // If the last writer was the owner (us), there's nothing to absorb — the
  // share blob is our own re-pushed data. Bail before doing crypto + merge work.
  if (body.writer?.kind === 'owner') {
    if (body.modified) _setAbsorbStamp(code, hKey, body.modified);
    return false;
  }

  let payload;
  try {
    const plain = await decryptWithShareKey(sk, body.ciphertext);
    payload = JSON.parse(plain);
  } catch(e) {
    console.warn('absorbSharedData: decrypt failed for', code, hKey, e.message);
    return false;
  }

  // Defense in depth: scrub any owner-only fields (`share`,
  // `_shareEffectivePerm`) the guest's payload might carry. The guest's
  // push path already strips these, but if a guest is on a future or
  // pre-scrub client version, we don't want their writes to overwrite
  // the owner's per-record sharing policy on absorb.
  if (Array.isArray(payload.items))         payload.items         = _scrubGuestRecords(payload.items);
  if (Array.isArray(payload.groceries))     payload.groceries     = _scrubGuestRecords(payload.groceries);
  if (Array.isArray(payload.groceryLists))  payload.groceryLists  = _scrubGuestRecords(payload.groceryLists);
  if (Array.isArray(payload.reminders))     payload.reminders     = _scrubGuestRecords(payload.reminders);
  // sharedNotes is OWNER-ONLY data — the owner pushes shared notes to
  // their guests; guests never push shared notes back. If a guest's
  // payload carries this field (buggy or malicious), drop it before
  // absorb so it can't poison the owner's local _sharedNotesIncoming
  // bucket on the next cycle or otherwise affect state.
  if ('sharedNotes' in payload) delete payload.sharedNotes;
  // Transaction scrub removed in Pass 2d-rollback (no per-tx share field
  // to scrub). Pass 2e-a will replace this with a category-membership
  // check on absorb so guests can't introduce categories the owner
  // doesn't have, and can't write transactions against unshared cats.

  // Merge into local state for this household. If hKey === activeProfile,
  // merging hits the live in-memory arrays; otherwise we merge into the
  // stored profile in IDB. v1: focus on activeProfile — non-active household
  // absorbs are a less common case and would need more wiring to do safely.
  if (hKey !== activeProfile) {
    // For now, skip non-active households — the data will be absorbed when
    // the owner next switches to that household and syncs.
    return false;
  }

  // Reuse the same merge logic kvSyncNow uses on the owner's own pull.
  const target = _shareTargets.find(t => t.code === code);
  const perms  = target?.households?.[hKey] || {};

  // ── Notification diff (owner side) ──
  // Snapshot the local items BEFORE we merge in the guest's writes so we can
  // emit "Sarah added milk" type notifications afterwards. We only diff
  // items[] for now since that's the most user-visible. Guest identity is
  // taken from body.writer (the server stamps it on every guest push).
  const _shareNotifSnapshot = (Array.isArray(payload.items) && perms.stockroom === 'rw')
    ? _snapshotItemsForDiff(items)
    : null;
  const _shareNotifWho = (() => {
    if (body.writer?.kind !== 'guest') return null;
    // Try to resolve a friendly name from memberDetails on the share target
    const eh = body.writer.emailHash;
    const md = target?.memberDetails?.[eh];
    if (md?.name) return md.name;
    if (md?.email) return md.email.split('@')[0];
    // Fall back to a generic label
    return 'a household member';
  })();
  const _shareNotifLabel = target?.name || null;

  if (Array.isArray(payload.items) && perms.stockroom === 'rw') {
    items = await mergeItems(items, payload.items, false);
    await saveData();
    // Diff and emit notifications after the merge. Wrapped in try/catch so
    // any notification failure never blocks the absorb (which is critical
    // for share data integrity).
    if (_shareNotifSnapshot) {
      try {
        const afterMap = _snapshotItemsForDiff(items);
        await _emitShareDiffNotifications(_shareNotifSnapshot, afterMap, {
          code,
          who: _shareNotifWho || _shareNotifLabel,
        });
      } catch(e) { console.warn('share diff notification failed:', e.message); }
    }
  }
  if (Array.isArray(payload.groceries) && perms.groceries === 'rw') {
    // Mirror the own-data merge in kvSyncNow: take guest's items as the base
    // (filtered by local tombstones), preserve local soft-deletes, then add
    // any local items not in the guest's set. This is a basic union with
    // local-deletes-win — proper field-level LWW would need updatedAt on
    // every grocery field, which we don't have yet. Matches existing
    // behaviour for owner own-data sync.
    const groceryTombstones = await loadGroceryDeletedIds();
    const incoming = payload.groceries.filter(i => !groceryTombstones.has(i.id));
    // Determine if remote (guest write) should win wholesale based on
    // lastSynced timestamp. If guest's payload is newer than local's last
    // save, take their version; otherwise add new-from-remote into local.
    const localLastSynced  = settings.lastSynced  ? new Date(settings.lastSynced).getTime()  : 0;
    const remoteLastSynced = payload.lastSynced   ? new Date(payload.lastSynced).getTime()   : 0;
    const remoteWins = remoteLastSynced > localLastSynced;
    if (remoteWins || groceryItems.length === 0) {
      groceryItems = _preserveLocalDeletes(incoming, groceryItems);
    } else {
      const localIds = new Set(groceryItems.map(i => i.id));
      const newFromRemote = incoming.filter(i => !localIds.has(i.id));
      if (newFromRemote.length) groceryItems = [...groceryItems, ...newFromRemote];
    }
    if (Array.isArray(payload.departments)) {
      // Merge departments (lower priority — owner-defined order wins)
      const existingIds = new Set(groceryDepts.map(d => d.id));
      for (const d of payload.departments) {
        if (!existingIds.has(d.id)) groceryDepts.push(d);
      }
    }
    // Merge grocery LISTS (named lists like "Tesco") + their tombstones.
    // Mirrors the kvSyncNow own-data merge — without it, a guest's newly-
    // created list never reaches the owner's device.
    if (Array.isArray(payload.groceryLists)) {
      const localGLTombstones = await loadGroceryListDeletedIds();
      if (Array.isArray(payload.groceryListDeletedIds)) {
        payload.groceryListDeletedIds.forEach(id => localGLTombstones.add(id));
        await dbPut('groceryLists', '_deletedIds', [...localGLTombstones]);
      }
      const remoteFiltered = payload.groceryLists.filter(l => !localGLTombstones.has(l.id));
      const localListsEmpty = groceryLists.length <= 1 && groceryLists[0]?.id === 'default';
      if (remoteWins || localListsEmpty) {
        groceryLists = remoteFiltered;
        await _saveGroceryLists();
      } else {
        const localListIds = new Set(groceryLists.map(l => l.id));
        const newLists = remoteFiltered.filter(l => !localListIds.has(l.id));
        if (newLists.length) {
          groceryLists = [...groceryLists, ...newLists];
          await _saveGroceryLists();
        }
      }
      // Prune any local lists matching a tombstone (covers the case where
      // a list was rebuilt from a remote pull before the tombstone arrived).
      const before = groceryLists.length;
      groceryLists = groceryLists.filter(l => !localGLTombstones.has(l.id));
      if (groceryLists.length !== before) await _saveGroceryLists();
    }
    await _saveGroceryLocal();
  }
  if (Array.isArray(payload.reminders) && perms.reminders === 'rw') {
    reminders = _preserveLocalDeletes(payload.reminders, reminders);
    await dbPut('reminders', 'reminders', reminders);
  }
  if (perms.budget === 'rw') {
    // Budget data is user-level (not per-household), so any household's
    // share blob with budget perms may carry the latest budget state.
    // Merge bills, categories, transactions, accounts, income.
    if (Array.isArray(payload.bills))             bills            = mergeBills(bills, payload.bills);
    if (payload.billInstances)                    billInstances    = mergeBillInstances(billInstances, payload.billInstances);

    // ── Pass 2e-a absorb enforcement ──
    // RULE A: Guests can't write categories. The owner owns category
    // metadata (name, color, budget targets, share state). Guests can
    // sync categories DOWN (to render their budget tab) but their
    // writes are dropped. If a guest somehow pushes back a modified
    // budgetCategories, we ignore it entirely.
    //
    // RULE B: Guests can only write transactions against categories
    // shared with THEIR share code. The owner's current share state is
    // authoritative — if the owner changed a category's share since
    // the guest wrote, the most-recent owner policy wins. Transactions
    // against unshared categories (or categoryId === null) are
    // dropped silently.
    //
    // Both rules ONLY apply when the writer is a guest. Owner-to-owner
    // sync (own-data pull on another device) bypasses these.
    const writerIsGuest = body.writer?.kind === 'guest';

    // RULE A: drop guest category writes entirely.
    if (Array.isArray(payload.budgetCategories) && !writerIsGuest) {
      budgetCategories = mergeBudgetCategories(budgetCategories, payload.budgetCategories);
    }
    // (no else — when writerIsGuest, the merge is simply skipped)

    // RULE B: filter guest tx writes by current owner-side allowed-cat set.
    if (payload.transactions) {
      if (writerIsGuest) {
        // Resolve which categories are currently shared with this code.
        // Reuses the same _filterBudgetForShare helper as the push side
        // — symmetric logic, single source of truth.
        const { allowedCatIds } = _filterBudgetForShare(
          budgetCategories, transactions, code, perms.budget
        );
        // Walk the incoming tx map and drop any not in the allowed set.
        const filteredTxMap = {};
        for (const [month, bucket] of Object.entries(payload.transactions)) {
          if (!bucket || typeof bucket !== 'object') continue;
          const cleanBucket = {};
          for (const [txId, tx] of Object.entries(bucket)) {
            if (!tx) continue;
            if (tx.categoryId == null) continue;          // uncategorised → reject
            if (!allowedCatIds.has(tx.categoryId)) continue; // unshared cat → reject
            cleanBucket[txId] = tx;
          }
          if (Object.keys(cleanBucket).length) filteredTxMap[month] = cleanBucket;
        }
        transactions = mergeTransactions(transactions, filteredTxMap);
      } else {
        transactions = mergeTransactions(transactions, payload.transactions);
      }
    }

    if (Array.isArray(payload.budgetAccounts))    budgetAccounts   = mergeBudgetAccounts(budgetAccounts, payload.budgetAccounts);
    if (Array.isArray(payload.incomeTemplates))   incomeTemplates  = mergeIncomeTemplates(incomeTemplates, payload.incomeTemplates);
    if (payload.incomeEntries)                    incomeEntries    = mergeIncomeEntries(incomeEntries, payload.incomeEntries);
    await saveBudgetLocal().catch(() => {});
  }

  if (body.modified) _setAbsorbStamp(code, hKey, body.modified);
  return true;
}

// ── Guest-side share push ──────────────────────────────────────────────────
//
// When a guest makes a change, the change MUST be sent to the owner's share
// blob via /share/data/push-guest. Previously the guest's _syncQueue.enqueue
// called kvSyncNow which did nothing useful for guests (no own-account push),
// so guest writes never left the device. This function fixes that.
//
// Permission-aware: only sections the guest has rw access to are included
// in the push. Pushing sections they only have ro on would either be rejected
// server-side or — worse — silently overwrite owner data with stale local
// state, which would be a permissions escape.
async function pushGuestSharedData() {
  if (!_shareState || !_shareKey) return;
  const code  = _shareState.code;
  const hKey  = activeProfile === 'default' ? 'default' : activeProfile;
  const perms = _shareState.households?.[hKey];
  if (!perms) { console.warn('pushGuestSharedData: no perms for household', hKey); return; }

  const hasAnyRw = Object.values(perms).some(p => p === 'rw');
  if (!hasAnyRw) return; // read-only guest — nothing to push

  // Build payload — only include sections the guest has rw on. Sections
  // they only have ro on get the owner's last value (which we pulled).
  const canWriteStockroom = perms.stockroom  === 'rw';
  const canWriteGroceries = perms.groceries  === 'rw';
  const canWriteReminders = perms.reminders  === 'rw';
  const canWriteBudget    = perms.budget     === 'rw';

  // For sections the guest can't write, we need to NOT include them in
  // the payload (else the server stores our possibly-stale local copy as
  // the new share state). The owner's last write to those sections stays
  // untouched by sending an empty array / object that the merger ignores.
  // mergeItems et al treat missing-on-remote as "no change", but they DO
  // overwrite when an explicit empty array is sent. So we omit entirely.
  //
  // Per-record perms (the `share` field and the `_shareEffectivePerm`
  // annotation) are an OWNER-ONLY concept. The guest must NEVER write
  // them back to the owner — that would let a guest unilaterally modify
  // the owner's sharing policy. Strip both fields from every record
  // before sending. _scrubGuestRecords does this in-place on a clone.
  const payload = {
    lastSynced: new Date().toISOString(),
  };
  if (canWriteStockroom) payload.items     = _scrubGuestRecords(items);
  if (canWriteGroceries) {
    payload.groceries   = _scrubGuestRecords(groceryItems);
    payload.departments = groceryDepts;
    // Include named-list state — without these, a guest creating a new
    // list (e.g. "Tesco") would push grocery ITEMS but the list itself
    // would never reach the owner.
    payload.groceryLists          = _scrubGuestRecords(groceryLists);
    payload.groceryListDeletedIds = [...(await loadGroceryListDeletedIds())];
  }
  if (canWriteReminders) payload.reminders = _scrubGuestRecords(reminders);
  if (canWriteBudget) {
    payload.bills             = bills;
    payload.billInstances     = billInstances;
    payload.budgetSettings    = budgetSettings;
    payload.budgetCategories  = budgetCategories;
    // Transactions pushed raw — no per-tx share field to scrub since
    // Pass 2d-rollback. Pass 2e-a's owner-side absorb will enforce
    // category-membership rules on these writes (reject categories the
    // owner doesn't have; reject tx writes against unshared cats).
    payload.transactions      = transactions;
    payload.budgetAccounts    = budgetAccounts;
    payload.incomeTemplates   = incomeTemplates;
    payload.incomeEntries     = incomeEntries;
  }
  // Always include settings — UI prefs etc travel with the user.
  payload.settings = settings;

  try {
    const ciphertext = await encryptWithShareKey(_shareKey, JSON.stringify(payload));
    const res = await postKV(`${WORKER_URL}/share/data/push-guest`, {
      guestEmailHash: _kvEmailHash,
      guestVerifier:  _kvVerifier,
      guestSessionToken: _kvSessionToken,
      code, household: hKey, ciphertext,
    });
    if (!res.ok) {
      const body = await _readJsonSafe(res) || {};
      console.warn('pushGuestSharedData failed:', res.status, body.error || '');
    }
  } catch(e) {
    console.warn('pushGuestSharedData threw:', e.message);
  }
}

// When a new guest accepts an invite before the owner had their ECDH pubkey,
// they store a rewrap request. Owner's app picks this up on next sync and wraps for them.
async function _fulfilPendingRewraps(code) {
  if (!_kvEmailHash || (!_kvVerifier && !_kvSessionToken)) return;
  const authFields = _kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier };
  try {
    const res = await postKV(`${WORKER_URL}/share/ecdh-key/pending-rewraps`, { ownerEmailHash: _kvEmailHash, ...authFields, code });
    if (!res.ok) return;
    const { requests } = await res.json();
    if (!requests?.length) return;

    const ownerPrivKey = await loadEcdhPrivateKey(_kvEmailHash);
    if (!ownerPrivKey) return;
    const ownerPubRes = await postKV(`${WORKER_URL}/user/ecdh-pubkey/get`, { emailHash: _kvEmailHash });
    if (!ownerPubRes.ok) return;
    const { publicKeyJwk: ownerPubKeyJwk } = await ownerPubRes.json();

    // Recover the share key for this code
    const sk = await (async () => {
      try {
        const stored = await _getShareKeys();
        const b64 = stored[code];
        if (b64) {
          const raw = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
          return crypto.subtle.importKey('raw', raw, { name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
        }
      } catch(e) {}
      return recoverShareKey(code);
    })();
    if (!sk) return;

    for (const req of requests) {
      if (!req.guestEmailHash || !req.guestPublicKeyJwk) continue;
      try {
        const wrappedKey = await ecdhWrapShareKey(ownerPrivKey, req.guestPublicKeyJwk, sk);
        await postKV(`${WORKER_URL}/share/ecdh-key/store`, {
            ownerEmailHash: _kvEmailHash, ...authFields, code,
            guestEmailHash: req.guestEmailHash, wrappedKey, ownerPublicKeyJwk: ownerPubKeyJwk,
          });
        console.log('[share] rewrapped key for guest:', req.guestEmailHash);
      } catch(e) { console.warn('[share] rewrap failed for', req.guestEmailHash, e.message); }
    }
  } catch(e) { /* non-critical */ }
}

async function resyncSharedData(code) {
  toast('Syncing to guest…');
  try {
    await pushSharedData(code);
    toast('Synced ✓');
  } catch(e) {
    toast('Sync failed: ' + e.message);
  }
}

// ── Share diagnostic — run window.shareDiag() on owner device ──
window.shareDiag = async function(code) {
  const out = [];
  out.push('=== SHARE DIAGNOSTIC ===');
  out.push(`_kvKey:       ${_kvKey ? 'SET' : 'NULL — owner not signed in with key'}`);
  out.push(`_kvEmailHash: ${_kvEmailHash || '(empty)'}`);
  out.push(`_kvVerifier:  ${_kvVerifier ? _kvVerifier.slice(0,8)+'…' : '(empty)'}`);
  out.push(`_shareTargets: ${JSON.stringify((_shareTargets||[]).map(t=>({code:t.code,households:Object.keys(t.households||{})})))}`);

  const localKeys = await _getShareKeys();
  out.push(`local share keys: ${Object.keys(localKeys).join(', ') || 'none'}`);

  const codes = code ? [code] : (_shareTargets||[]).map(t=>t.code);
  if (!codes.length) { out.push('No share targets found'); console.log(out.join('\n')); return out.join('\n'); }

  for (const c of codes) {
    out.push(`\n--- Code: ${c} ---`);
    out.push(`local key present: ${!!localKeys[c]}`);

    // Try server key backup
    try {
      const r = await fetch(`${WORKER_URL}/share/key/get`, {
        method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ownerEmailHash:_kvEmailHash, verifier:_kvVerifier, sessionToken:_kvSessionToken, code:c}),
      });
      out.push(`share/key/get status: ${r.status}`);
      const d = await r.json();
      out.push(`share/key/get body: ${JSON.stringify(d)}`);
    } catch(e) { out.push(`share/key/get error: ${e.message}`); }

    // Try share/data/push with a test payload to see if auth works
    // (just check whether we can get a share key at all)
    let sk = null;
    if (localKeys[c]) {
      try {
        const raw = Uint8Array.from(atob(localKeys[c]), c2=>c2.charCodeAt(0));
        sk = await crypto.subtle.importKey('raw', raw, {name:'AES-GCM',length:256}, true, ['encrypt','decrypt']);
        out.push(`local key import: OK`);
      } catch(e) { out.push(`local key import FAILED: ${e.message}`); }
    }
    if (!sk) {
      out.push(`attempting server key recovery…`);
      sk = await recoverShareKey(c).catch(e => { out.push(`recoverShareKey error: ${e.message}`); return null; });
      out.push(`server key recovery: ${sk ? 'OK' : 'FAILED — no backup stored'}`);
    }

    // Check if share_data exists on server using owner credentials
    if (_kvEmailHash && _kvVerifier) {
      try {
        // share/data/pull requires guest credentials — use owner as a proxy check via share/list
        const shareRecord = _shareTargets.find(t => t.code === c);
        out.push(`share record in _shareTargets: ${shareRecord ? 'YES' : 'NO'}`);
        out.push(`share members: ${JSON.stringify(shareRecord?.members || [])}`);
        out.push(`share households: ${JSON.stringify(Object.keys(shareRecord?.households || {}))}`);
      } catch(e) { out.push(`share record check error: ${e.message}`); }
    }
  }
  out.push('\nTo recover a share with no key: run window.rebuildShare("CODE") to delete and recreate it.');
  out.push('=== END ===');
  console.log(out.join('\n'));
  return out.join('\n');
};

// Delete a broken share target (no key) and toast instructions to recreate
window.clearBrokenShare = async function(code) {
  if (!code) { console.error('Usage: clearBrokenShare("CODE")'); return; }
  if (!confirm(`Delete share target ${code}? The guest will lose access. You'll need to send them a new link.`)) return;
  try {
    const res = await postKV(`${WORKER_URL}/share/delete`, { ownerEmailHash: _kvEmailHash, verifier: _kvVerifier, sessionToken: _kvSessionToken, code });
    if (!res.ok) { const d = await res.json(); throw new Error(d.error || 'Delete failed'); }
    // Remove from local share keys
    try {
      const stored = await _getShareKeys();
      delete stored[code];
      await _setShareKeys(stored);
    } catch(e) {}
    await loadShareTargets();
    console.log(`Share ${code} deleted. Go to Settings → Households → Add person to create a new share.`);
    toast('Share removed — create a new one from Settings → Households');
  } catch(e) {
    console.error('clearBrokenShare failed:', e.message);
  }
};

async function refreshShareLink(code) {
  const target = _shareTargets.find(t => t.code === code);
  if (!target) return;
  try {
    const res = await postKV(`${WORKER_URL}/share/refresh`, { ownerEmailHash: _kvEmailHash, verifier: _kvVerifier, sessionToken: _kvSessionToken, code });
    if (!res.ok) throw new Error('Could not refresh');
    const baseLink = `${location.origin}${location.pathname}?join=${code}`;
    await navigator.clipboard.writeText(baseLink).catch(()=>{});
    toast('New link copied ✓ (valid 24h)');
    await loadShareTargets();
  } catch(err) { toast('Could not refresh link: ' + err.message); }
}

async function deleteShareTarget(code) {
  if (!confirm('Remove this person\'s access? They will no longer be able to sync your data.')) return;
  try {
    const res = await postKV(`${WORKER_URL}/share/delete`, { ownerEmailHash: _kvEmailHash, verifier: _kvVerifier, sessionToken: _kvSessionToken, code });
    if (!res.ok) { const d = await res.json().catch(()=>({})); throw new Error(d.error || 'Could not delete'); }
    // Remove local share key
    try {
      const stored = await _getShareKeys();
      delete stored[code];
      await _setShareKeys(stored);
    } catch(e) {}
    toast('Access removed ✓');
    await loadShareTargets();
  } catch(err) { toast('Could not remove: ' + err.message); }
}

function clearAllShares() {
  if (!_shareTargets?.length) { toast('No shares to clear'); return; }
  if (!confirm(`Remove all ${_shareTargets.length} share link${_shareTargets.length !== 1 ? 's' : ''}? ` +
    'Guests will immediately lose access and their local share data will be cleared on next sync.')) return;
  requireReauth('Confirm your identity to remove all shares.', _doClearAllShares, { passkeyAllowed: true });
}

async function _doClearAllShares() {
  let failed = 0;
  for (const target of (_shareTargets || [])) {
    try {
      const res = await postKV(`${WORKER_URL}/share/delete`, { ownerEmailHash: _kvEmailHash, verifier: _kvVerifier, sessionToken: _kvSessionToken, code: target.code });
      if (!res.ok) failed++;
    } catch(e) { failed++; }
  }
  // Clear local share key cache
  try { localStorage.removeItem('stockroom_share_keys'); } catch(e) {}
  await loadShareTargets();
  toast(failed ? `Cleared with ${failed} error(s) — check console` : 'All shares removed ✓');
}

// Send share invite or update email via server
async function _sendShareEmail(guestEmail, { code, name, type, households, isUpdate = false, inviteLink = '' }) {
  if (!guestEmail || !WORKER_URL) return;
  try {
    const authFields = _kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier };
    await postKV(`${WORKER_URL}/share/send-email`, {
        ownerEmailHash: _kvEmailHash, ...authFields,
        guestEmail, code, name, type, households, isUpdate, inviteLink,
        ownerName: settings.email?.split('@')[0] || 'Your household',
      });
  } catch(e) { console.warn('share email failed:', e.message); }
}

function copyShareLink() {
  const link = document.getElementById('share-link-value')?.textContent?.trim();
  if (!link) return;
  navigator.clipboard?.writeText(link).then(() => toast('Link copied ✓')).catch(() => prompt('Copy this link:', link));
}

function copyShareTargetLink(code) {
  const link = `${location.origin}${location.pathname}?join=${code}`;
  navigator.clipboard.writeText(link).then(() => toast('Invite link copied ✓')).catch(() => prompt('Copy this link:', link));
}

function updateHouseholdShareUI() {
  const joinedSection = document.getElementById('household-joined-section');
  if (!joinedSection) return;
  if (_shareState) {
    joinedSection.style.display = 'block';
    const statusEl = document.getElementById('joined-status-text');
    if (statusEl) statusEl.textContent = `✓ Joined ${_shareState.ownerName || 'a household'}'s STOCKROOM as ${_shareState.type || 'guest'}`;
  } else {
    joinedSection.style.display = 'none';
  }
}

async function renderSettingsHouseholdList() {
  const list = document.getElementById('settings-household-list');
  if (!list) return;
  const profiles = await getProfiles();
  list.innerHTML = Object.entries(profiles).map(([key, p]) => {
    const isActive = key === activeProfile;
    const colour   = p.colour || '#e8a838';
    const count    = (p.items || []).length;
    return `<div style="display:flex;align-items:center;gap:8px;padding:10px 12px;background:${isActive?'rgba(232,168,56,0.08)':'var(--surface2)'};border:2px solid ${isActive?colour:'var(--border)'};border-radius:10px">
      <div style="width:10px;height:10px;border-radius:50%;background:${colour};flex-shrink:0"></div>
      <div style="flex:1;font-size:13px;font-weight:${isActive?'700':'400'};color:${isActive?colour:'var(--text)'}">
        ${esc(p.name || key)}${isActive?' ✓':''}
        <span style="font-size:11px;font-weight:400;color:var(--muted);margin-left:6px">${count} item${count!==1?'s':''}</span>
      </div>
      ${!isActive ? `<button class="btn btn-ghost btn-sm" onclick="switchProfileFromSettings('${key}')">Switch</button>` : ''}
      <button class="btn btn-ghost btn-sm" onclick="openHouseholdEdit('${key}')" title="Edit"><svg class="icon" aria-hidden="true"><use href="#i-pencil"></use></svg></button>
      ${key !== 'default' ? `<button class="btn btn-ghost btn-sm" style="color:var(--danger)" onclick="deleteProfile('${key}');renderSettingsHouseholdList()"><svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg></button>` : ''}
    </div>`;
  }).join('');
}

async function switchProfileFromSettings(key) {
  await switchProfile(key);
  renderSettingsHouseholdList();
}

async function addProfileFromSettings() {
  const input = document.getElementById('settings-new-household-name');
  const name  = input?.value.trim() || '';
  // Temporarily set the new-profile-name so addProfile can read it
  const nameEl = document.getElementById('new-profile-name');
  if (nameEl) nameEl.value = name;
  await addProfile();
  if (input) input.value = '';
  renderSettingsHouseholdList();
}

function initHouseholdSettingsUI() {
  loadHouseholdSettings();
  loadShareState();
  updateHouseholdShareUI();
  renderHouseholdColourPicker(); // still used by presence system internally
  if (_householdEnabled) connectPresence();
  applyTabPermissions();
  renderSettingsHouseholdList();
  if (WORKER_URL && (isOwner() || canViewShares())) loadShareTargets();
}

// ── User ID ───────────────────────────────────────────────
async function getHouseholdUserId() {
  // Use the KV email hash if signed in — stable across devices, no raw email sent
  if (_kvEmailHash) return 'u_' + _kvEmailHash.slice(0, 12);
  // Fall back to settings email hash
  const email = settings.email || '';
  if (email) {
    const msgBuffer  = new TextEncoder().encode(email.toLowerCase().trim());
    const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
    return 'u_' + Array.from(new Uint8Array(hashBuffer)).slice(0, 6).map(b => b.toString(16).padStart(2,'0')).join('');
  }
  // No email — per-device ID
  let id = localStorage.getItem('stockroom_user_id');
  if (!id) {
    id = 'u_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    localStorage.setItem('stockroom_user_id', id);
  }
  return id;
}

// ── SSE connection ────────────────────────────────────────
async function connectPresence() {
  if (!WORKER_URL || !_householdEnabled) return;
  if (!_kvEmailHash || (!_kvVerifier && !_kvSessionToken)) return;
  disconnectPresence(); // close any existing

  const userId = await getHouseholdUserId();
  // Auth via query string — EventSource cannot send POST bodies or custom
  // headers. The server scopes presence to the authenticated user.
  const params = new URLSearchParams({ emailHash: _kvEmailHash, userId });
  if (_kvSessionToken) params.set('sessionToken', _kvSessionToken);
  else if (_kvVerifier) params.set('verifier', _kvVerifier);
  const url = `${WORKER_URL}/presence-stream?${params.toString()}`;

  try {
    _presenceSSE = new EventSource(url);

    _presenceSSE.onmessage = async e => {
      try {
        const data = JSON.parse(e.data);
        if (data.type === 'presence') {
          _otherPresence = {};
          const myId = await getHouseholdUserId();
          (data.users || []).forEach(u => {
            if (u.userId !== myId) _otherPresence[u.userId] = u;
          });
          renderPresenceAvatars();
          // Update shopping list if we're on it — items may have changed
          if (_currentViewName === 'shopping' || document.getElementById('shopping-panel')?.style.display !== 'none') {
            scheduleRender('shopping');
          }
        }
      } catch(err) { console.warn('Presence parse error', err); }
    };

    _presenceSSE.onerror = () => {
      // SSE dropped — try to reconnect after 10s
      disconnectPresence();
      setTimeout(() => { if (_householdEnabled) connectPresence(); }, 10000);
    };

    // Push our own presence immediately and then every 25s
    pushPresence();
    _presencePingTimer = setInterval(pushPresence, 25000);

    const statusEl = document.getElementById('household-status');
    if (statusEl) statusEl.innerHTML = '<span style="color:var(--ok)">●</span> Connected — presence active';
  } catch(e) {
    console.warn('Presence SSE failed:', e);
  }
}

function disconnectPresence() {
  if (_presenceSSE) { _presenceSSE.close(); _presenceSSE = null; }
  clearInterval(_presencePingTimer);
  _otherPresence = {};
  renderPresenceAvatars();
  const statusEl = document.getElementById('household-status');
  if (statusEl) statusEl.textContent = '';
}

async function pushPresence() {
  if (!WORKER_URL || !_householdEnabled) return;
  if (!_kvEmailHash || (!_kvVerifier && !_kvSessionToken)) return;
  const name   = _householdName || settings.email?.split('@')[0] || 'You';
  const initials = name.slice(0,2).toUpperCase();
  try {
    await fetch(`${WORKER_URL}/presence-update`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        emailHash:    _kvEmailHash,
        verifier:     _kvVerifier,
        sessionToken: _kvSessionToken,
        userId:       await getHouseholdUserId(),
        name,
        initials,
        colour:       _householdColour,
        view:         _currentViewName,
        ts:           new Date().toISOString(),
      }),
    });
  } catch(e) { /* offline — ignore */ }
}

// ── Presence avatars ──────────────────────────────────────
function renderPresenceAvatars() {
  const bar = document.getElementById('presence-bar');
  if (!bar) return;
  const users = Object.values(_otherPresence);
  if (!users.length) { bar.style.display = 'none'; return; }
  bar.style.display = 'flex';
  bar.innerHTML = users.map(u => {
    const viewLabel = { stock:'Stockroom', grocery:'Groceries', shopping:'Shopping', reminders:'Reminders', savings:'Savings', report:'Report', settings:'Settings' }[u.view] || u.view;
    const isShopping = u.view === 'shopping';
    return `<div class="presence-avatar ${isShopping ? 'shopping' : ''}"
      style="background:${u.colour};color:#111"
      title="${u.name} — viewing ${viewLabel}">
      ${u.initials}
      <div class="presence-dot"></div>
      <div class="presence-tooltip">${esc(u.name)} · ${viewLabel}</div>
    </div>`;
  }).join('');
}

// Hook into showView and switchTo* to push presence on navigation
// Note: we patch _currentViewName directly rather than wrapping functions,
// since function re-declaration with hoisting causes infinite recursion.

// ── Shopping list: show who else is viewing ───────────────
function getShoppingPresenceBar() {
  const shoppers = Object.values(_otherPresence).filter(u => u.view === 'shopping');
  if (!shoppers.length) return '';
  return `<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:rgba(232,168,56,0.08);border:1px solid rgba(232,168,56,0.2);border-radius:10px;margin-bottom:14px;font-size:13px">
    <div style="display:flex;gap:4px">${shoppers.map(u =>
      `<div class="presence-avatar shopping" style="background:${u.colour};color:#111;width:24px;height:24px;font-size:10px">${u.initials}<div class="presence-dot"></div></div>`
    ).join('')}</div>
    <span style="color:var(--warn)">${shoppers.map(u=>esc(u.name)).join(', ')} ${shoppers.length===1?'is':'are'} also on the shopping list</span>
  </div>`;
}

async function init() {
  // ── Restore device ID from device-info IDB before anything else ─────────
  // getOrCreateDeviceId() is synchronous, so the async IDB restore in the IIFE
  // below may not have completed yet. If localStorage was cleared, a new random
  // device ID would be generated, making all IDB setup-flag lookups miss.
  // We await the IDB restore here so the correct device ID is in localStorage
  // before any setup-flag checks run. Note: this reads from the device-info
  // DB, which is shared across all users on this browser — the active per-
  // user DB hasn't been chosen yet at this point.
  if (!localStorage.getItem('stockroom_device_id')) {
    try {
      const savedId = await _deviceInfoGet('stockroom_device_id');
      if (savedId) {
        localStorage.setItem('stockroom_device_id', savedId);
        sessionStorage.setItem('stockroom_device_id_session', savedId);
      }
    } catch(e) {}
  }

  // ── Restore kv_session from device-info IDB if localStorage was cleared ─
  // stockroom_kv_session is the gating key for kvRestoreSession() AND the
  // source for the emailHash peek below. We persist it in the device-info
  // DB so a cookie/localStorage clear doesn't force a re-login.
  if (!localStorage.getItem('stockroom_kv_session')) {
    try {
      const savedSession = await _deviceInfoGet('stockroom_kv_session');
      if (savedSession) {
        localStorage.setItem('stockroom_kv_session', savedSession);
      }
    } catch(e) {}
  }

  // ── CRITICAL: set active per-user DB BEFORE loadData ─────────────────────
  // Each signed-in user has their own IDB database. If we call loadData()
  // while _activeDbName is still 'stockroom_unauth', the first read goes to
  // the wrong database — at best it returns empty data and the UI flashes
  // an empty state; at worst it would write fresh empties back over the
  // unauth DB on a sync race. Peek the kv_session here, extract emailHash,
  // and flip the active DB name now so every subsequent dbGet/dbPut lands
  // in the right place. Demo mode (set by handleURLAction before init) is
  // routed to its own DB and wiped on entry.
  if (window._demoMode) {
    await _setActiveDbForDemo();
  } else {
    try {
      const raw = localStorage.getItem('stockroom_kv_session');
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && parsed.emailHash) {
          _setActiveDbForUser(parsed.emailHash);
        }
      }
    } catch(e) { console.warn('[init] kv_session peek failed:', e && e.message); }
  }

  // ── One-time legacy `stockroom` DB cleanup ───────────────────────────────
  // Pre-per-user-IDB versions of the app wrote everything into a single
  // shared IDB named `stockroom`. That DB now holds stale data for whichever
  // user last touched it before the migration. Delete it once, gated by a
  // localStorage flag so it only runs on the first post-deploy load. We
  // don't migrate — Pete has backups and is the only real user; sync from
  // the server repopulates the per-user DB on first authed load.
  if (!localStorage.getItem('stockroom_legacy_db_deleted_v1')) {
    try {
      indexedDB.deleteDatabase('stockroom');
      localStorage.setItem('stockroom_legacy_db_deleted_v1', '1');
      console.log('[init] Deleted legacy `stockroom` IDB (one-time migration)');
    } catch(e) { console.warn('[init] legacy DB delete failed (non-fatal):', e && e.message); }
  }

  // Load all data from IndexedDB (migrates from localStorage on first run)
  await loadData();

  // ── Migration: stamp updatedAt on any item that doesn't have one ──
  const now = new Date().toISOString();
  let migrated = false;
  items.forEach(item => {
    if (!item.updatedAt) { item.updatedAt = now; migrated = true; }
  });
  if (migrated) {
    await saveData();
    console.log(`Stamped updatedAt on ${items.filter(i=>i.updatedAt===now).length} legacy items`);
  }

  // Restore KV session
  const _diagSession = localStorage.getItem('stockroom_kv_session');
  const _diagSecret  = localStorage.getItem('stockroom_device_secret');
  const _diagEmail   = localStorage.getItem('stockroom_remembered_email');
  const _diagConsent = localStorage.getItem('stockroom_cookie_consent');
  const _diagFallback= localStorage.getItem('stockroom_kv_key_fallback');
  const _diagLsKey   = localStorage.getItem('stockroom_kv_session_key');
  console.log('[DIAG] ── init ──────────────────────────────');
  console.log('[DIAG] kv_session:       ', _diagSession ? JSON.parse(_diagSession) : 'ABSENT');
  console.log('[DIAG] device_secret:    ', _diagSecret  ? 'SET' : 'ABSENT');
  console.log('[DIAG] remembered_email: ', _diagEmail   || 'ABSENT');
  console.log('[DIAG] cookie_consent:   ', _diagConsent || 'ABSENT');
  console.log('[DIAG] key_fallback:     ', _diagFallback ? JSON.parse(_diagFallback) : 'ABSENT');
  console.log('[DIAG] session_key (ls): ', _diagLsKey   ? 'SET' : 'ABSENT');
  // CRITICAL: refuse to restore the user's session while in demo mode.
  // kvRestoreSession calls _setActiveDbForUser which flips _activeDbName
  // from 'stockroom_demo' back to the user's per-user DB. If that's
  // allowed to happen, _seedDemoData's dbPut calls — which fire later
  // in the demo branch — will write the demo persona's items into the
  // real user's IDB, destroying their data.
  //
  // Demo mode and signed-in mode are mutually exclusive within a single
  // tab session. The kv_session in localStorage is left untouched, so
  // navigating away from ?action=demo (or closing the tab and returning
  // to /app) restores the user's session normally.
  const kvRestored = window._demoMode ? false : await kvRestoreSession();
  console.log('[DIAG] kvRestored:', kvRestored, '| kvConnected:', kvConnected, '| _kvKey:', !!_kvKey, '| demoMode:', !!window._demoMode);

  // ── Email-verification gate on session restore ─────────────────────────
  // Defends against the "Back-button bypass" path: user signed up, the OTP
  // email failed (or they pressed Back before entering it), and now there's
  // a session cached in localStorage/IDB for an unverified account. Without
  // this check they'd be admitted on next page load. We make a cheap call
  // to /user/email-verified to see whether the server has marked this hash
  // as verified; if not, we drop them at the verification screen instead
  // of the app. The server call is unauthenticated (just emailHash) so it
  // works even without _kvKey unlocked.
  let _blockedUnverified = false;
  if (kvRestored && _kvEmailHash) {
    try {
      const r = await fetch(`${WORKER_URL}/user/email-verified`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ emailHash: _kvEmailHash }),
      });
      const data = await r.json().catch(() => ({}));
      if (r.ok && !data.verified) {
        console.warn('[init] Session restored for unverified email — blocking entry');
        _blockedUnverified = true;
        // Show the wizard and route to the verification step. The
        // _pendingUnverifiedRestore state lets us complete the handoff
        // (drop the half-built session, return to login) once the OTP
        // is entered — they then sign in cleanly to a verified account.
        const restoreEmail = _kvEmail || '';
        _pendingUnverifiedRestore = { email: restoreEmail, emailHash: _kvEmailHash };
        // Drop the unauthenticated session bits — we don't want any
        // background sync running on this account until verification
        // completes. Setting kvConnected=false stops kvSyncNow.
        kvConnected = false;
        document.body.classList.add('wizard-active');
        const wiz = document.getElementById('wizard');
        if (wiz) wiz.style.display = 'flex';
        await showEmailVerification(
          restoreEmail,
          _kvEmailHash,
          _completePendingUnverifiedRestore
        );
      }
    } catch (e) {
      // Network error — fail open rather than locking the user out of an
      // already-verified account just because the check call failed. The
      // server-side gate on /user/verify still catches anything important.
      console.warn('[init] email-verified check failed (continuing):', e.message);
    }
  }

  if (kvRestored && !_blockedUnverified) {
    // Always ensure the data key is available before syncing.
    // If _kvKey is already set (trusted device / 4h cache), this is instant.
    // If not, kvEnsureKey will prompt cleanly BEFORE the stockroom shows.
    if (!_kvKey) {
      // Show overlay so user knows something is happening
      showDataLoadingOverlay('Unlocking your data…');
      const keyOk = await kvEnsureKey().catch(() => false);
      hideDataLoadingOverlay();
      if (keyOk) {
        setTimeout(() => kvSyncNow(true), 400);
      }
      // If keyOk is false user cancelled — leave them on current screen with sign-in option
    } else {
      setTimeout(() => kvSyncNow(true), 800);
    }
  }

  await loadShareState();

  // Check for ?join=CODE — show loading state immediately so user doesn't see normal wizard
  const _joinCode = new URLSearchParams(location.search).get('join');
  if (_joinCode) {
    const _step1b = document.getElementById('wizard-step-1b');
    if (_step1b) {
      document.querySelectorAll('.wizard-step').forEach(s => s.classList.remove('active'));
      _step1b.innerHTML = '<div style="font-size:52px;margin-bottom:16px">\uD83C\uDFE0</div><h1 style="font-size:24px;font-weight:700;margin-bottom:8px">Joining household…</h1><p style="color:var(--muted);font-size:14px">Checking your invite link</p>';
      _step1b.classList.add('active');
    }
  }

  handleURLAction(); // processes ?join= and replaces loading state with join screen

  buildCountryGrid();
  buildSettingsCountrySelect();
  buildTagSettingsRows();
  buildTagFilterBar();
  wizardCountry = settings.country || 'GB';
  selectCountry(wizardCountry);

  const seen        = kvConnected; // signed-in users skip the wizard
  const wizardStep  = localStorage.getItem('stockroom_wizard_step');

  const countrySet  = await getCountrySetForDevice();
  const protectSeen = await getProtectSeenForDevice();
  console.log('[DIAG] init branch: seen=', seen, 'kvConnected=', kvConnected, '_kvKey=', !!_kvKey, 'protectSeen=', protectSeen);

  if (window._landingAction === 'demo') {
    // Demo mode — skip wizard, skip login, skip MFA. Seed in-memory data and
    // render straight into the app. Nothing persists past this tab session
    // because the dbGet/dbPut/dbDelete shim routes to in-memory Maps.
    //
    // CRITICAL: wipe in-memory state first. Earlier init code (loadProfile,
    // loadReminders, loadNotifications, etc.) may have run a beat ago and
    // populated globals from whatever DB was active at that instant. We've
    // since flipped to the demo DB, but any global the load functions
    // didn't overwrite (notifications, _history) would otherwise survive
    // and surface inside the demo session. This is the fix for the
    // real-account-notifications-in-demo leak. _seedDemoData below then
    // re-populates the data arrays from the persona definition.
    _resetInMemoryUserState();
    // Belt-and-braces: refuse to seed if anything flipped _activeDbName
    // away from stockroom_demo between init's initial set and here. The
    // primary defence is in _setActiveDbForUser (now bails in demo mode)
    // and init's gated kvRestoreSession call, but if a future code path
    // ever introduces a third way to flip the DB, this catches it loudly
    // instead of silently writing demo data into the real user's IDB.
    if (_activeDbName !== 'stockroom_demo') {
      console.error('[demo] DB context corrupted — _activeDbName is',
        _activeDbName, '— re-flipping to stockroom_demo before seed');
      await _setActiveDbForDemo();
    }
    document.body.classList.remove('wizard-active');
    const wiz = document.getElementById('wizard');
    if (wiz) wiz.style.display = 'none';
    window.scrollTo(0, 0);
    // Mark setup flags as seen so legacy "first run" UI doesn't pop up
    settings.country = settings.country || 'GB';
    settings.threshold = settings.threshold || 20;
    settings._setupProtectSeen = true;
    settings._setupCountrySet  = true;
    await _seedDemoData();
    await _saveSettings();
    scheduleRender(...RENDER_REGIONS);
    _showDemoBanner();
    hideDataLoadingOverlay();
    // Surface the first contextual nudge once the layout settles. Items
    // grid renders synchronously but card images / stat strips finish a
    // tick later — 1.5s gives the eye time to land on the page first.
    setTimeout(() => _showDemoNudge('stockroom'), 1500);
  } else if (_joinCode) {
    // join flow handled by handleURLAction above
  } else if (kvConnected) {
    if (!_kvKey) {
      showDataLoadingOverlay('Unlocking your data…');
      const keyOk = await kvEnsureKey().catch(() => false);
      hideDataLoadingOverlay();
      if (!keyOk) { showKvLogin(); return; }
    }
    // Always go through MFA first — protect/country/stockroom routing happens inside
    document.body.classList.remove('wizard-active');
    hide('wizard');
    window.scrollTo(0, 0);
    await _mfaGate(async () => {
      // Re-read flags after _mfaGate's server pull
      const ps = await getProtectSeenForDevice();
      const cs = await getCountrySetForDevice();
      if (!ps) {
        showProtectDataScreen([]);
      } else if (!cs) {
        document.body.classList.add('wizard-active');
        show('wizard', 'flex');
        document.querySelectorAll('.wizard-step').forEach(s => s.classList.remove('active'));
        document.getElementById('wizard-step-2').classList.add('active');
        wizardCountry = settings.country || 'GB';
        requestAnimationFrame(() => { buildCountryGrid(); selectCountry(wizardCountry); });
      } else {
        showDataLoadingOverlay('Loading your Stockroom…');
        scheduleRender(...RENDER_REGIONS);
        try { await kvSyncNow(true); } catch(e) {}
        hideDataLoadingOverlay();
        // Show install banner after sync — settings._installDismissed now authoritative
        setTimeout(maybeShowInstallBanner, 2000);
      }
    });
  } else if (wizardStep === '2') {
    localStorage.removeItem('stockroom_wizard_step');
    wizardNext();
  } else if (countrySet) {
    wizardNext();
  } else if (window._landingAction === 'register') {
    // Came from landing page "Create account" — go straight to register flow.
    // If a remembered email is present (user clicked Create account anyway),
    // clear it so registration starts fresh.
    try {
      localStorage.removeItem('stockroom_remembered_email');
      localStorage.removeItem('stockroom_remembered_passkey');
    } catch(e) {}
    showKvRegister();
  } else {
    // No session, no seen flag — show login (will auto-skip to auth if remembered).
    // Includes the ?action=login path from the landing page.
    showKvLogin();
  }

  updateSyncUI();
  renderSettingsForUser();
  _showAmazonBanners();
  initPasskeyUI();
  loadCompactView();
  loadFilterPanelState();
  updateFab(_currentView || 'stock'); // init FAB for current view
  _updateSidebarProfile();            // populate sidebar household name

  // Init profiles — migrate if needed
  const existingProfiles = await getProfiles();
  const profileKeys = Object.keys(existingProfiles);
  if (!profileKeys.length) {
    // First run — wrap current items/settings into default profile
    const profiles = { default: { name: 'Home', items: JSON.parse(JSON.stringify(items)), settings: JSON.parse(JSON.stringify(settings)) } };
    await saveProfiles(profiles);
  }
  activeProfile = localStorage.getItem('stockroom_active_profile') || 'default';
  await loadProfile(activeProfile);

  scheduleRender(...RENDER_REGIONS);
  loadNotifSettings();
  initHouseholdSettingsUI();
  updateHeaderGreeting();
  await loadReminders();
  await loadNotes();
  await loadGrocery();
  await loadBudget();
  await loadBudgetSpend();
  await loadBudgetAccountsAndIncome();
  await loadNotifications();
  _renderNotificationBellBadge();
  // Sweep any expired items from the 30-day recycle bin (no-op if loadProfile already did it)
  await purgeExpiredFromBins();
  // Same for soft-deleted grocery lists older than 30 days
  await purgeExpiredGroceryLists();
  await checkGroceryRecurring();
  renderReminders(); // pre-render for badge count

  setTimeout(() => { lastAutoSync = Date.now(); checkCloudAhead(); }, 1500);
  checkPendingSWSync();
  if (migrated) setTimeout(syncAll, 1500);
  // Shared users need an explicit sync on load
  if (_shareState && !migrated) setTimeout(() => kvSyncNow(true), 800);
  setTimeout(checkExportReminder, 5000);
  setTimeout(checkScheduledEmail, 2000);
  setTimeout(checkLowStockNotifications, 3000);
  setTimeout(checkReminderNotifications, 3500);
  // Global search keyboard shortcut — Cmd+K on Mac, Ctrl+K elsewhere.
  // Attaches once at init; the handler itself no-ops when the user is
  // already inside the search input so plain "k" keystrokes don't fight.
  document.addEventListener('keydown', _globalSearchKeyShortcut);
}

// ═══════════════════════════════════════════════════════════
//  STORE PRICES (multiple stores per item)
//  Moved from scanner.js — needed as soon as the item modal opens
// ═══════════════════════════════════════════════════════════

function renderStorePricesSection(item) {
  const section = document.getElementById('store-prices-section');
  const list    = document.getElementById('store-prices-list');
  if (!section || !list) return;
  const prices = item?.storePrices || [];
  section.style.display = 'block';
  if (!prices.length) {
    list.innerHTML = `<p style="font-size:12px;color:var(--muted);padding:4px 0">No store prices added yet. Click + Add Store to compare prices across different shops.</p>`;
    return;
  }
  list.innerHTML = prices.map((sp, i) => `
    <div style="display:flex;gap:8px;align-items:center;padding:6px 0;border-bottom:1px solid var(--border)">
      <input type="text" value="${esc(sp.store)}" placeholder="Store name"
        style="flex:1;background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);font-size:12px"
        onchange="updateStorePrice(${i},'store',this.value)">
      <input type="text" value="${esc(sp.price)}" placeholder="Price"
        style="width:80px;background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);font-size:12px;font-family:var(--mono)"
        onchange="updateStorePrice(${i},'price',this.value)">
      <button onclick="removeStorePrice(${i})" style="background:none;border:none;cursor:pointer;color:var(--muted);font-size:16px;padding:2px 4px"
        onmouseover="this.style.color='var(--danger)'" onmouseout="this.style.color='var(--muted)'"><svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg></button>
    </div>`).join('');
  if (prices.length > 1) {
    const parsed = prices.map((sp,i) => ({ i, val: parsePriceValue(sp.price) })).filter(x => x.val !== null);
    if (parsed.length > 1) {
      const min = Math.min(...parsed.map(x => x.val));
      const cheapestIdx = parsed.find(x => x.val === min)?.i;
      if (cheapestIdx !== undefined) {
        const rows = list.querySelectorAll('div');
        if (rows[cheapestIdx]) rows[cheapestIdx].style.background = 'rgba(76,187,138,0.08)';
      }
    }
  }
}

function addStorePriceRow() {
  tempStorePrices.push({ store: '', price: '' });
  renderTempStorePrices();
}

function updateStorePrice(idx, field, val) {
  if (tempStorePrices[idx]) tempStorePrices[idx][field] = val;
}

function removeStorePrice(idx) {
  tempStorePrices.splice(idx, 1);
  renderTempStorePrices();
}

function renderTempStorePrices() {
  const section = document.getElementById('store-prices-section');
  const list    = document.getElementById('store-prices-list');
  if (!section || !list) return;
  section.style.display = 'block';
  if (!tempStorePrices.length) {
    list.innerHTML = `<p style="font-size:12px;color:var(--muted);padding:4px 0">No store prices added yet.</p>`;
    return;
  }
  list.innerHTML = tempStorePrices.map((sp, i) => `
    <div style="display:flex;gap:8px;align-items:center;padding:6px 0;border-bottom:1px solid var(--border)">
      <input type="text" value="${esc(sp.store)}" placeholder="Store name"
        style="flex:1;background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);font-size:12px"
        oninput="updateStorePrice(${i},'store',this.value)">
      <input type="text" value="${esc(sp.price)}" placeholder="e.g. £12.99"
        style="width:90px;background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);font-size:12px;font-family:var(--mono)"
        oninput="updateStorePrice(${i},'price',this.value)">
      <button onclick="removeStorePrice(${i})" style="background:none;border:none;cursor:pointer;color:var(--muted);font-size:16px;padding:2px 4px"
        onmouseover="this.style.color='var(--danger)'" onmouseout="this.style.color='var(--muted)'"><svg class="icon" aria-hidden="true"><use href="#i-x"></use></svg></button>
    </div>`).join('');
}

// ═══════════════════════════════════════════════════════════
//  QUICK ADD — moved from scanner.js
// ═══════════════════════════════════════════════════════════

function openQuickAdd() {
  document.getElementById('quick-add-input').value = '';
  hide('quick-add-preview');
  document.getElementById('quick-add-chips').innerHTML = '';
  openModal('quick-add-modal');
  setTimeout(() => document.getElementById('quick-add-input')?.focus(), 100);
}

function parseQuickAddNames() {
  return document.getElementById('quick-add-input').value
    .split(',').map(s => s.trim()).filter(s => s.length > 0);
}

function updateQuickAddPreview() {
  const names   = parseQuickAddNames();
  const preview = document.getElementById('quick-add-preview');
  const chips   = document.getElementById('quick-add-chips');
  const btn     = document.getElementById('quick-add-save-btn');
  if (!names.length) { preview.style.display = 'none'; return; }
  preview.style.display = 'block';
  chips.innerHTML = names.map(n =>
    `<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;background:var(--surface2);border:1px solid var(--border);border-radius:99px;font-size:12px;color:var(--text)">
      📦 ${esc(n)}
    </span>`
  ).join('');
  if (btn) btn.innerHTML = `<svg class="icon" aria-hidden="true" style="vertical-align:-3px"><use href="#i-zap"></use></svg> Add ${names.length} Item${names.length !== 1 ? 's' : ''}`;
}

async function saveQuickAdd() {
  const names = parseQuickAddNames();
  if (!names.length) { toast('Enter at least one item name'); return; }
  const now = new Date().toISOString();
  names.forEach(name => {
    items.push({
      id: uid(), name, category: 'Other', cadence: 'monthly',
      qty: 1, months: 1, url: '', store: '', notes: '',
      rating: null, imageUrl: null, logs: [], storePrices: [],
      quickAdded: true, updatedAt: now,
    });
  });
  await saveData();
  closeModal('quick-add-modal');
  scheduleRender('grid', 'dashboard', 'filters', 'shopping');
  _syncQueue.enqueue();
  toast(`${names.length} item${names.length !== 1 ? 's' : ''} added — complete their details when ready`);
}

// ═══════════════════════════════════════════════════════════
//  SCAN CHOOSER — shown after a barcode is scanned
// ═══════════════════════════════════════════════════════════

let scannedProductName  = '';
let scannedProductImage = null;
let scannedProductUnitType = 'item';

// Guess a unit type from an Open Food Facts `quantity` string, e.g.
// "500 g" → 'g', "1.5 l" → 'litre', "4 x 110 g" → 'g', "6 rolls" → 'roll',
// "330ml can" → 'can'. Returns 'item' when nothing matches. Order matters:
// explicit container words (rolls, cans, bottles) win over mass/volume so a
// "330ml can" is tracked as cans, not ml.
function detectUnitTypeFromQuantity(qStr) {
  if (!qStr || typeof qStr !== 'string') return 'item';
  const s = qStr.toLowerCase();
  if (/\broll(s)?\b/.test(s))            return 'roll';
  if (/\b(can|cans|tin|tins)\b/.test(s)) return 'can';
  if (/\bbottle(s)?\b/.test(s))          return 'bottle';
  if (/\b(pack|packs|x\s*\d)\b/.test(s)) return 'pack';
  if (/\b(kg|kilograms?)\b/.test(s))     return 'kg';
  if (/\b(l|lt|ltr|litre|litres|liter|liters)\b/.test(s)) return 'litre';
  if (/\bml\b/.test(s))                  return 'ml';
  if (/\bg(rams?)?\b/.test(s))           return 'g';
  return 'item';
}

function openScanChooser(name, imageUrl, unitType) {
  scannedProductName  = name;
  scannedProductImage = imageUrl;
  scannedProductUnitType = (unitType && UNIT_TYPES[unitType]) ? unitType : 'item';
  const nameEl = document.getElementById('scan-chooser-name');
  if (nameEl) nameEl.textContent = name;
  openModal('scan-chooser-modal');
}

function scanChooserQuickAdd() {
  closeModal('scan-chooser-modal');
  openQuickAdd();
  const ta = document.getElementById('quick-add-input');
  if (ta) { ta.value = scannedProductName; updateQuickAddPreview(); }
}

function scanChooserLogPurchase() {
  closeModal('scan-chooser-modal');
  openLogPicker();
  const search = document.getElementById('log-picker-search');
  if (search) { search.value = scannedProductName; filterLogPicker(scannedProductName); }
}

function scanChooserFullAdd() {
  closeModal('scan-chooser-modal');
  openAddModal();  // opens the WIZARD (wiz-* fields) and resets them synchronously first
  const wn = document.getElementById('wiz-name');
  if (wn) { wn.value = scannedProductName; wn.dispatchEvent(new Event('input', { bubbles: true })); }
  const wc = document.getElementById('wiz-category');
  if (wc) wc.value = 'Food & Drink';
  const wut = document.getElementById('wiz-unit-type');
  if (wut) { wut.value = scannedProductUnitType || 'item'; if (typeof applyWizUnitTypeToQtyInput === 'function') applyWizUnitTypeToQtyInput(); }
  if (scannedProductImage && typeof wizShowImage === 'function') {
    _wizImageUrl = scannedProductImage;
    wizShowImage(scannedProductImage);
  }
}

// ═══════════════════════════════════════════════════════════
//  LOG PURCHASE PICKER — moved from scanner.js
// ═══════════════════════════════════════════════════════════

function openLogPicker() {
  renderLogPickerList('');
  document.getElementById('log-picker-search').value = '';
  openModal('log-picker-modal');
  setTimeout(() => document.getElementById('log-picker-search').focus(), 100);
}

function renderLogPickerList(filter) {
  const list = document.getElementById('log-picker-list');
  if (!list) return;
  const q      = filter.toLowerCase().trim();
  const sorted = [...items]
    .filter(i => !i.quickAdded)
    .filter(i => !q || i.name.toLowerCase().includes(q))
    .sort((a, b) => {
      const la = a.logs?.at(-1)?.date || '0000';
      const lb = b.logs?.at(-1)?.date || '0000';
      return lb.localeCompare(la);
    });
  if (!sorted.length) {
    list.innerHTML = `<p style="font-size:13px;color:var(--muted);text-align:center;padding:20px">No items found</p>`;
    return;
  }
  list.innerHTML = sorted.map(item => {
    const s        = calcStock(item);
    const daysLeft = s?.daysLeft ?? null;
    const color    = STATUS_COLOR[getStatus(s?.pct ?? null, settings.threshold)];
    const lastLog  = item.logs?.at(-1);
    return `<button onclick="pickItemForLog('${item.id}')"
      style="display:flex;align-items:center;gap:12px;padding:10px 12px;background:var(--surface2);border:1px solid var(--border);border-radius:10px;cursor:pointer;text-align:left;width:100%;transition:border-color 0.15s"
      onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='var(--border)'">
      <div style="width:4px;height:36px;border-radius:2px;background:${color};flex-shrink:0"></div>
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:600;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(item.name)}</div>
        <div style="font-size:11px;color:var(--muted);font-family:var(--mono);margin-top:2px">
          ${daysLeft !== null ? `${daysLeft}d left` : 'no data'}
          ${lastLog ? ` · last bought ${fmtDate(lastLog.date)}` : ''}
          ${item.store ? ` · ${esc(item.store)}` : ''}
        </div>
      </div>
      <span style="font-size:18px;flex-shrink:0">+</span>
    </button>`;
  }).join('');
}

function filterLogPicker(val) { renderLogPickerList(val); }

function pickItemForLog(id) {
  closeModal('log-picker-modal');
  openLogModal(id);
}

// ═══════════════════════════════════════════════════════════
//  SHARE ITEM — moved from scanner.js
// ═══════════════════════════════════════════════════════════

let sharingItem = null;

function shareItem(id) {
  const item = items.find(i => i.id === id);
  if (!item) return;
  sharingItem = item;
  const subtitle = document.getElementById('share-modal-subtitle');
  if (subtitle) subtitle.textContent = item.name;
  drawShareCard(item);
  openModal('share-modal');
}

function drawShareCard(item) {
  const canvas = document.getElementById('share-canvas');
  if (!canvas) return;
  const W = 600, H = 340;
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createLinearGradient(0, 0, W, H);
  grad.addColorStop(0, '#0f1117'); grad.addColorStop(1, '#1a1d27');
  ctx.fillStyle = grad; ctx.fillRect(0, 0, W, H);
  const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 260);
  glow.addColorStop(0, 'rgba(232,168,56,0.07)'); glow.addColorStop(1, 'rgba(232,168,56,0)');
  ctx.fillStyle = glow; ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = '#2e3350'; ctx.lineWidth = 1; ctx.strokeRect(0.5, 0.5, W-1, H-1);
  const headerH = 44;
  ctx.fillStyle = '#1a1d27'; ctx.fillRect(0, 0, W, headerH);
  ctx.strokeStyle = '#2e3350'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(0, headerH); ctx.lineTo(W, headerH); ctx.stroke();
  ctx.fillStyle = '#e8a838'; ctx.font = 'bold 13px monospace'; ctx.fillText('📦 STOCKROOM', 20, 28);
  ctx.fillStyle = '#7880a0'; ctx.font = '11px monospace'; ctx.textAlign = 'right';
  ctx.fillText('Household Consumables Tracker', W - 20, 28); ctx.textAlign = 'left';
  const contentY = headerH + 24;
  ctx.fillStyle = 'rgba(120,128,160,0.2)';
  const catText = (item.category || 'Other').toUpperCase();
  ctx.font = '10px monospace';
  const catW = ctx.measureText(catText).width + 16;
  _roundRect(ctx, 20, contentY, catW, 20, 4); ctx.fill();
  ctx.fillStyle = '#7880a0'; ctx.fillText(catText, 28, contentY + 14);
  ctx.fillStyle = '#e8eaf2'; ctx.font = 'bold 28px system-ui, sans-serif';
  const nameLines = _wrapText(ctx, item.name || '', W - 48);
  nameLines.slice(0, 2).forEach((line, i) => ctx.fillText(line, 20, contentY + 46 + i * 36));
  const afterName = contentY + 46 + Math.min(nameLines.length, 2) * 36;
  const pillY = afterName + 16; let pillX = 20;
  const drawPill = (label, value, bg, textCol) => {
    if (!value) return;
    ctx.font = '11px system-ui, sans-serif';
    const fullText = label ? `${label}: ${value}` : value;
    const pw = ctx.measureText(fullText).width + 20;
    ctx.fillStyle = bg; ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(pillX, pillY, pw, 24, 12) : _roundRect(ctx, pillX, pillY, pw, 24, 12);
    ctx.fill(); ctx.fillStyle = textCol; ctx.fillText(fullText, pillX + 10, pillY + 16);
    pillX += pw + 8;
  };
  const history = getPriceHistory(item);
  const lastPrice = history.length ? (history[history.length-1].raw || `£${history[history.length-1].price.toFixed(2)}`) : null;
  if (lastPrice) drawPill('Price', lastPrice, 'rgba(76,187,138,0.15)', '#4cbb8a');
  if (item.store) drawPill('From', item.store, 'rgba(91,141,238,0.15)', '#5b8dee');
  if (item.qty && item.qty !== 1) drawPill('Qty', `×${item.qty}`, 'rgba(120,128,160,0.15)', '#7880a0');
  if (item.rating) drawPill('', '★'.repeat(item.rating) + '☆'.repeat(5 - item.rating), 'rgba(232,168,56,0.15)', '#e8a838');
  const barY = H - 30;
  ctx.fillStyle = '#0f1117'; ctx.fillRect(0, barY, W, 30);
  ctx.strokeStyle = '#2e3350'; ctx.beginPath(); ctx.moveTo(0, barY); ctx.lineTo(W, barY); ctx.stroke();
  if (item.url) {
    try {
      const domain = new URL(item.url).hostname.replace('www.', '');
      ctx.fillStyle = '#5b8dee'; ctx.font = '11px monospace'; ctx.fillText(`🛒 ${domain}`, 20, barY + 20);
    } catch(e) {}
  }
  ctx.fillStyle = '#4a5070'; ctx.font = '10px monospace'; ctx.textAlign = 'right';
  ctx.fillText('stckrm.fly.dev', W - 20, barY + 20); ctx.textAlign = 'left';
}

function _wrapText(ctx, text, maxWidth) {
  const words = text.split(' '), lines = [];
  let current = '';
  for (const word of words) {
    const test = current ? current + ' ' + word : word;
    if (ctx.measureText(test).width > maxWidth && current) { lines.push(current); current = word; }
    else { current = test; }
  }
  if (current) lines.push(current);
  return lines;
}

function _roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

async function doShareImage() {
  const canvas = document.getElementById('share-canvas');
  if (!canvas || !sharingItem) return;
  canvas.toBlob(async blob => {
    const file = new File([blob], `${sharingItem.name.replace(/\s+/g, '-')}.png`, { type: 'image/png' });
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      try { await navigator.share({ title: sharingItem.name, text: buildShareText(sharingItem), files: [file] }); closeModal('share-modal'); }
      catch(e) { if (e.name !== 'AbortError') _downloadShareImage(canvas, sharingItem); }
    } else { _downloadShareImage(canvas, sharingItem); }
  }, 'image/png');
}

function _downloadShareImage(canvas, item) {
  const a = document.createElement('a');
  a.download = `${item.name.replace(/\s+/g, '-')}.png`;
  a.href = canvas.toDataURL('image/png'); a.click();
  toast('Image saved — share from your downloads');
}

async function doShareItemLink() {
  if (!sharingItem) return;
  const link = generateItemShareLink(sharingItem);
  if (navigator.share) {
    try { await navigator.share({ title: `${sharingItem.name} — via STOCKROOM`, text: `I'm using ${sharingItem.name} in STOCKROOM:`, url: link }); closeModal('share-modal'); return; }
    catch(e) { if (e.name === 'AbortError') return; }
  }
  fallbackCopy(link);
}

async function doShareLink() {
  const url = sharingItem?.url || window.location.href;
  if (navigator.share) {
    try { await navigator.share({ title: sharingItem?.name, text: buildShareText(sharingItem), url }); closeModal('share-modal'); }
    catch(e) { if (e.name !== 'AbortError') fallbackCopy(url); }
  } else { fallbackCopy(url); }
}

async function doShareText() {
  if (!sharingItem) return;
  fallbackCopy(buildShareText(sharingItem));
}

function buildShareText(item) {
  if (!item) return '';
  const history = getPriceHistory(item);
  const lastPrice = history.length ? (history[history.length-1].raw || `£${history[history.length-1].price.toFixed(2)}`) : null;
  const storePrices = (item.storePrices || []).filter(sp => sp.store && sp.price);
  const lines = [`📦 ${item.name}`];
  if (item.category) lines.push(`Category: ${item.category}`);
  if (lastPrice)     lines.push(`Price: ${lastPrice}`);
  if (item.store)    lines.push(`Available at: ${item.store}`);
  if (storePrices.length > 1) { lines.push('Price comparison:'); storePrices.forEach(sp => lines.push(`  ${sp.store}: ${sp.price}`)); }
  if (item.qty && item.qty !== 1) lines.push(`Pack size: ×${item.qty}`);
  if (item.rating)   lines.push(`Rated: ${'★'.repeat(item.rating)}${'☆'.repeat(5 - item.rating)}`);
  if (item.notes)    lines.push(`Note: ${item.notes}`);
  if (item.url)      lines.push(`Buy here: ${item.url}`);
  lines.push(''); lines.push('Shared via STOCKROOM — stckrm.fly.dev');
  return lines.join('\n');
}

function fallbackCopy(text) {
  navigator.clipboard?.writeText(text)
    .then(() => { toast('Copied to clipboard ✓'); closeModal('share-modal'); })
    .catch(() => {
      const ta = document.createElement('textarea');
      ta.value = text; ta.style.cssText = 'position:fixed;opacity:0';
      document.body.appendChild(ta); ta.select(); document.execCommand('copy');
      document.body.removeChild(ta); toast('Copied to clipboard ✓'); closeModal('share-modal');
    });
}

// ═══════════════════════════════════════════════════════════
//  ITEM SHARE LINK — receive items shared via URL
// ═══════════════════════════════════════════════════════════

function generateItemShareLink(item) {
  const payload = {
    v: 1, name: item.name, category: item.category, cadence: item.cadence,
    qty: item.qty, months: item.months, url: item.url || '', store: item.store || '',
    notes: item.notes || '', rating: item.rating || null,
    storePrices: (item.storePrices || []).filter(sp => sp.store && sp.price),
  };
  const encoded = btoa(unescape(encodeURIComponent(JSON.stringify(payload))));
  return `${window.location.origin}/?item=${encoded}`;
}

function checkIncomingItem() {
  const params  = new URLSearchParams(location.search);
  const encoded = params.get('item');
  if (!encoded) return false;
  history.replaceState(null, '', location.pathname);
  try {
    const payload = JSON.parse(decodeURIComponent(escape(atob(encoded))));
    if (!payload?.name) return false;
    setTimeout(() => showIncomingItemPrompt(payload), 700);
    return true;
  } catch(e) { return false; }
}

function showIncomingItemPrompt(payload) {
  const priceStr = (payload.storePrices || []).map(sp => `${sp.store}: ${sp.price}`).join(' · ');
  let domainStr = '';
  try { if (payload.url) domainStr = new URL(payload.url).hostname.replace('www.', ''); } catch(e) {}
  const el = document.createElement('div');
  el.id = 'incoming-item-overlay';
  el.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:9999;display:flex;align-items:flex-end;justify-content:center;padding:20px';
  el.onclick = e => { if (e.target === el) closeIncomingItem(); };
  el.innerHTML = `
    <div style="background:var(--surface);border-radius:16px 16px 12px 12px;padding:24px;max-width:440px;width:100%;border:1px solid var(--border);box-shadow:0 -4px 32px rgba(0,0,0,0.4)">
      <div style="font-size:11px;font-weight:700;color:var(--accent);font-family:var(--mono);letter-spacing:1px;margin-bottom:8px">📦 ITEM SHARED WITH YOU</div>
      <div style="font-size:20px;font-weight:700;color:var(--text);margin-bottom:4px">${esc(payload.name)}</div>
      <div style="font-size:12px;color:var(--muted);margin-bottom:12px;line-height:1.8">
        ${payload.category ? `<span style="font-family:var(--mono)">${esc(payload.category)}</span>` : ''}
        ${payload.store    ? ` · From <strong style="color:var(--text)">${esc(payload.store)}</strong>` : ''}
        ${priceStr         ? ` · ${esc(priceStr)}` : ''}
        ${payload.months   ? ` · ${payload.months}mo supply` : ''}
      </div>
      ${payload.notes ? `<div style="font-size:12px;color:var(--muted);font-style:italic;margin-bottom:14px;padding:8px;background:var(--surface2);border-radius:6px"><svg class="icon" aria-hidden="true"><use href="#i-message-square"></use></svg> ${esc(payload.notes)}</div>` : ''}
      ${domainStr ? `<div style="margin-bottom:14px"><a href="${esc(payload.url)}" target="_blank" rel="noopener" style="font-size:12px;color:var(--accent2)">🛒 ${esc(domainStr)} ↗</a></div>` : ''}
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">
        <button class="btn btn-primary" style="flex:1" id="incoming-add-btn">+ Add to my stockroom</button>
        <button class="btn btn-ghost" id="incoming-edit-btn">✏️ Add &amp; set up</button>
        <button class="btn btn-ghost btn-sm" onclick="closeIncomingItem()">Dismiss</button>
      </div>
    </div>`;
  document.body.appendChild(el);
  document.getElementById('incoming-add-btn').onclick  = () => addIncomingItem(payload, false);
  document.getElementById('incoming-edit-btn').onclick = () => addIncomingItem(payload, true);
}

function closeIncomingItem() {
  document.getElementById('incoming-item-overlay')?.remove();
}

async function addIncomingItem(payload, openEdit) {
  closeIncomingItem();
  const newItem = {
    id: uid(), name: payload.name, category: payload.category || 'Other',
    cadence: payload.cadence || 'monthly', qty: payload.qty || 1, months: payload.months || 1,
    url: payload.url || '', store: payload.store || '', notes: payload.notes || '',
    rating: payload.rating || null, storePrices: payload.storePrices || [],
    imageUrl: null, logs: [], quickAdded: false, updatedAt: new Date().toISOString(),
  };
  items.push(newItem);
  await saveData();
  scheduleRender('grid', 'dashboard', 'shopping');
  _syncQueue.enqueue();
  if (openEdit) { setTimeout(() => { openEditModal(newItem.id); enableItemEdit(); }, 300); }
  else { toast(`"${payload.name}" added ✓`); }
}

// ═══════════════════════════════════════════════════════════
//  SHARE JOIN FLOW — moved from scanner.js
// ═══════════════════════════════════════════════════════════

async function handleShareJoinLink(code) {
  updateSyncPill('syncing');
  try {
    const probe = await postKV(`${WORKER_URL}/share/join`, { code });
    const probeData = (await _readJsonSafe(probe)) || {};
    if (probe.status === 410) { toast('This invite link has expired — ask the owner for a new one'); updateSyncPill('error'); return; }
    if (!probe.ok && !probeData.requiresAuth) throw new Error(probeData.error || `Invalid link (${probe.status})`);
    _pendingJoinCode  = code.toUpperCase();
    _pendingShareMeta = probeData;
    if (kvConnected && _kvEmailHash && (_kvVerifier || _kvSessionToken)) { await completePendingJoin(); return; }
    showShareAuthGate(probeData);
  } catch(err) { updateSyncPill('error'); toast('Invalid invite link — ' + (err.message || `network error`)); }
}

function showShareAuthGate(meta) {
  const wizard = document.getElementById('wizard');
  if (!wizard) return;
  wizard.style.display = 'flex';
  const step1 = document.getElementById('wizard-step-1');
  if (!step1) return;
  const hCount = Object.keys(meta.households || {}).length;
  const groupName = meta.name ? `the <strong>${esc(meta.name)}</strong> group` : 'this household';
  step1.innerHTML = `
    <div style="margin-bottom:12px;color:var(--accent)"><svg aria-hidden="true" style="width:44px;height:44px"><use href="#i-home"></use></svg></div>
    <h1 style="font-size:22px;font-weight:700;margin-bottom:6px">You're invited!</h1>
    <p style="color:var(--muted);font-size:13px;line-height:1.6;margin-bottom:16px">
      <strong style="color:var(--text)">${esc(meta.ownerName||'Someone')}</strong> has invited you
      to access ${hCount} household${hCount!==1?'s':''} as a member of ${groupName}.
    </p>
    <div style="text-align:left;margin-bottom:12px">
      <div class="form-group" style="margin-bottom:10px">
        <label class="form-label">Email address</label>
        <input class="form-input" id="share-gate-email" type="email" placeholder="you@example.com" autocomplete="email">
      </div>
      <div class="form-group" style="margin-bottom:8px">
        <label class="form-label">Passphrase</label>
        <input class="form-input" id="share-gate-pass" type="password" placeholder="Your passphrase" autocomplete="current-password">
      </div>
    </div>
    <button class="btn btn-primary btn-xl full" style="margin-bottom:8px" onclick="shareGateSignIn()">Sign in &amp; Accept →</button>
    <button class="btn btn-ghost btn-xl full" style="font-size:13px;margin-bottom:8px" onclick="shareGateRegister()">Create new account &amp; Accept →</button>
    <p id="share-gate-error" style="font-size:12px;color:var(--danger);margin-top:6px;display:none"></p>
  `;
  step1.classList.add('active');
}

async function shareGateSignIn() {
  const email = document.getElementById('share-gate-email')?.value.trim();
  const pass  = document.getElementById('share-gate-pass')?.value;
  const errEl = document.getElementById('share-gate-error');
  if (!email || !pass) { if(errEl){errEl.textContent='Enter email and passphrase';errEl.style.display='block';} return; }
  try {
    const emailHash = await kvHashEmail(email);
    const verifier  = await kvMakeVerifier(pass, emailHash);
    const res = await postKV(`${WORKER_URL}/user/verify`, { emailHash, verifier });
    const d = await res.json();
    if (res.status === 404) throw new Error('Account not found — use Create new account');
    if (!res.ok) throw new Error(d.error || 'Sign-in failed');
    // Fetch the passphrase envelope and unwrap to recover the data key.
    const keyRes  = await postKV(`${WORKER_URL}/key/get`, { emailHash, verifier });
    const keyData = await keyRes.json();
    if (!keyRes.ok || !keyData.envelope) throw new Error('Could not fetch key envelope');
    const key = await unwrapPassphraseDataKey(pass, emailHash, keyData);
    await kvStoreSession(email, emailHash, verifier, key);
    // Ensure ECDH keypair is ready BEFORE attempting join (required for key unwrapping)
    await ensureEcdhKeypair(emailHash).catch(e => console.warn('ensureEcdhKeypair:', e.message));
    await _trustIfRemembered(email, emailHash, verifier, key);
    await completePendingJoin();
  } catch(err) { if(errEl){errEl.textContent=err.message;errEl.style.display='block';} }
}

async function shareGateRegister() {
  const email = document.getElementById('share-gate-email')?.value.trim();
  const pass  = document.getElementById('share-gate-pass')?.value;
  const errEl = document.getElementById('share-gate-error');
  if (!email || !pass) { if(errEl){errEl.textContent='Enter email and passphrase';errEl.style.display='block';} return; }
  if (pass.length < 8) { if(errEl){errEl.textContent='Passphrase must be at least 8 characters';errEl.style.display='block';} return; }
  try {
    const emailHash = await kvHashEmail(email);
    const verifier  = await kvMakeVerifier(pass, emailHash);
    const res = await postKV(`${WORKER_URL}/user/register`, { emailHash, verifier, email });
    const d = await res.json();
    if (!res.ok) throw new Error(d.error || 'Registration failed');
    const kdfSalt = generateKdfSalt();
    const wrapKey = await derivePassphraseWrapKeyV2(pass, emailHash, kdfSalt);
    const dataKey = await generateDataKeyV2Extractable();
    const passphraseEnvelope = await wrapDataKeyV2(dataKey, wrapKey);
    const saltB64 = btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(32))));
    const recoveryCodes = generateRecoveryCodes(10);
    const recoveryEnvelopes = await buildRecoveryEnvelopesV2(recoveryCodes, dataKey, emailHash);
    const storeRes = await postKV(`${WORKER_URL}/key/store`, { emailHash, verifier, salt: saltB64, passphraseEnvelope, recoveryEnvelopes, kdfSalt });
    if (!storeRes.ok) throw new Error('Could not store key envelopes — try again');
    _kvKey = dataKey;
    await kvStoreSession(email, emailHash, verifier, dataKey);
    // Generate the ECDH keypair NOW so the rewrap-request fired from
    // completePendingJoin's 404 branch has a usable pubkey on the server.
    // Without this, the rewrap request stores `guestPublicKeyJwk: null` and
    // the owner's rewrap loop has nothing to wrap against — guest stays
    // stuck on "Your invite is being set up" forever.
    await ensureEcdhKeypair(emailHash).catch(e => console.warn('ensureEcdhKeypair:', e.message));
    // Mark as fresh registration so the verification screen shows a Cancel
    // button — share-gate users hit the same Resend-failure path as the
    // main signup wizard, and need an exit if their email won't deliver.
    _pendingUnverifiedRestore = { email, emailHash, verifier };
    await showEmailVerification(email, emailHash, async () => {
      _pendingUnverifiedRestore = null;
      await _trustIfRemembered(email, emailHash, verifier, dataKey);
      await completePendingJoin();
    });
  } catch(err) { if(errEl){errEl.textContent=err.message;errEl.style.display='block';} }
}

// Attempt to fetch + unwrap the ECDH-wrapped share key for the current code.
// Returns a CryptoKey on success, null if we exhausted retries.
//
// On the first failure (404 or unwrap OperationError) this:
//   1. Posts a rewrap-request to the server with the guest's CURRENT pubkey
//   2. Updates the UI to "Waiting for owner to refresh your invite…"
//   3. Polls /share/ecdh-key/get every 5s for up to ~30s. Each polled
//      response is unwrapped against the current local private key — once
//      we get a wrappedKey whose payload was wrapped against our current
//      pubkey, the unwrap succeeds.
//
// This automates the "ask the owner to open STOCKROOM" loop: as soon as the
// owner's app fires kvSyncNow (which now calls _fulfilPendingRewraps even
// on a pull-only sync), the new wrappedKey is stored and the guest's poll
// picks it up without any further user action.
async function _tryUnwrapWithRewrapRetry(code) {
  const guestPrivKey = await loadEcdhPrivateKey(_kvEmailHash);
  if (!guestPrivKey) throw new Error('Your encryption key is missing — sign out and back in to regenerate it');

  const fetchAndUnwrap = async () => {
    const ecdhRes = await postKV(`${WORKER_URL}/share/ecdh-key/get`, {
        guestEmailHash: _kvEmailHash,
        ...(_kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier }),
        code,
      });
    if (ecdhRes.status === 404) return { ok: false, reason: 'missing' };
    if (!ecdhRes.ok) {
      const ed = (await _readJsonSafe(ecdhRes)) || {};
      return { ok: false, reason: 'server', error: ed.error || `HTTP ${ecdhRes.status}` };
    }
    const { wrappedKey, ownerPublicKeyJwk } = (await _readJsonSafe(ecdhRes)) || {};
    if (!wrappedKey || !ownerPublicKeyJwk) return { ok: false, reason: 'incomplete' };
    try {
      const key = await ecdhUnwrapShareKey(guestPrivKey, ownerPublicKeyJwk, wrappedKey);
      return { ok: true, key };
    } catch(unwrapErr) {
      return { ok: false, reason: 'unwrap', error: unwrapErr };
    }
  };

  // First attempt — fast path. If unwrap succeeds, done.
  const first = await fetchAndUnwrap();
  if (first.ok) return first.key;

  // If the server returned a non-recoverable error (server/incomplete that
  // isn't going to be fixed by waiting), bail.
  if (first.reason === 'server') throw new Error(first.error);
  if (first.reason === 'incomplete') throw new Error('Share key response is missing — ask the owner to re-send the invite');

  // missing (404) or unwrap (stale wrap) → trigger rewrap request, then poll.
  console.warn(first.reason === 'missing'
    ? 'No wrapped key on server — requesting rewrap'
    : 'Stale wrapped key — requesting rewrap');
  if (first.reason === 'unwrap') {
    console.error('ecdhUnwrapShareKey failed:', first.error?.name, first.error?.message);
  }
  try {
    await postKV(`${WORKER_URL}/share/ecdh-key/request-rewrap`, {
      guestEmailHash: _kvEmailHash,
      ...(_kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier }),
      code,
    });
  } catch(reqErr) { console.warn('rewrap request failed:', reqErr.message); }

  // Update the joining UI to reflect the wait
  try {
    const lbl = document.querySelector('.joining-subtitle, [data-joining-subtitle]');
    if (lbl) lbl.textContent = 'Waiting for owner to refresh your invite…';
  } catch(_) {}
  toast('Refreshing invite — this can take up to 30 seconds');

  // Poll: 5s, 10s, 15s, 20s, 25s, 30s
  const POLL_INTERVALS_MS = [5000, 5000, 5000, 5000, 5000, 5000];
  for (const wait of POLL_INTERVALS_MS) {
    await new Promise(r => setTimeout(r, wait));
    const result = await fetchAndUnwrap();
    if (result.ok) {
      console.log('[share] poll succeeded — rewrap fulfilled by owner');
      return result.key;
    }
    // missing/unwrap → keep polling. server/incomplete → bail.
    if (result.reason === 'server' || result.reason === 'incomplete') {
      throw new Error(result.reason === 'server' ? result.error : 'Share key response is missing');
    }
  }
  // Exhausted retries
  return null;
}

async function completePendingJoin() {
  if (!_pendingJoinCode) return;
  const code = _pendingJoinCode;
  try {
    const res  = await postKV(`${WORKER_URL}/share/join`, {
        code,
        guestEmailHash:    _kvEmailHash,
        ...(_kvSessionToken ? { guestSessionToken: _kvSessionToken } : { guestVerifier: _kvVerifier }),
      });
    const data = (await _readJsonSafe(res)) || {};
    if (!res.ok) throw new Error(data.error || `Invalid invite link (${res.status}) — it may have expired`);
    // Server returned 200 but with ok:false — means it needs auth (shouldn't happen here but guard it)
    if (data.requiresAuth) throw new Error('Authentication required — please sign in first');

    // Attempt the unwrap. If it fails because of stale wrap, request a rewrap
    // and poll for up to ~30s for the owner's app to fulfil it. This avoids
    // forcing the user to manually click the invite link a second time.
    const shareKey = await _tryUnwrapWithRewrapRetry(code);
    if (!shareKey) {
      // Couldn't unwrap even after waiting — leave the rewrap request queued
      // and instruct the user. _tryUnwrapWithRewrapRetry already triggered
      // the request-rewrap call on the first failure.
      throw new Error('Your invite is being refreshed — ask the owner to open STOCKROOM, then tap this link again');
    }

    const shareKeyB64 = await exportShareKey(shareKey);
    try {
      const stored = await _getShareKeys();
      stored[code] = shareKeyB64;
      await _setShareKeys(stored);
    } catch(e) {}
    _shareState = { ...data, code };
    _shareKey   = shareKey;
    saveShareState();
    _pendingJoinCode  = null;
    _pendingShareMeta = null;
    localStorage.setItem('stockroom_seen', '1');
    localStorage.setItem('stockroom_country_set', '1');
    document.body.classList.remove('wizard-active');
    hide('wizard');
    applyTabPermissions();
    updateSyncPill('syncing');
    await kvSyncNow();
    scheduleRender(...RENDER_REGIONS);
    toast(`✓ Joined ${data.ownerName || 'household'}'s STOCKROOM`);
  } catch(err) {
    const msg = err.message || 'Unknown error — please try again';
    toast('Could not join: ' + msg);
    updateSyncPill('error');
  }
}

// ═══════════════════════════════════════════════════════════
//  URL ACTION HANDLER — moved from scanner.js
// ═══════════════════════════════════════════════════════════
function handleURLAction() {
  // ── Share join link: ?join=CODE ──────────────────────────
  const joinParams = new URLSearchParams(location.search);
  const joinCode   = joinParams.get('join');
  if (joinCode) {
    history.replaceState(null, '', location.pathname);
    if (typeof handleShareJoinLink === 'function') handleShareJoinLink(joinCode.toUpperCase());
    return;
  }

  // Check for incoming shared item (defined in scanner.js)
  if (typeof checkIncomingItem === 'function' && checkIncomingItem()) return;

  const params = new URLSearchParams(location.search);
  const action = params.get('action');
  if (!action) return;

  // ── Landing-page entry points: ?action=login / ?action=register ──
  // These are recorded as a flag for the init flow to honour, then
  // returned early so the rest of init can route the user appropriately.
  // We don't strip these from the URL until init has consumed them, so
  // a refresh on /app?action=register still does the right thing.
  if (action === 'login' || action === 'register') {
    window._landingAction = action;
    history.replaceState(null, '', location.pathname);
    return;
  }

  // ── Demo mode: ?action=demo ───────────────────────────────────────────
  // Sets the global demo flag (which the dbGet/dbPut/dbDelete shim picks
  // up) and signals the init flow to skip wizard/login and seed data.
  // No backend calls are made — kvConnected stays false, sync paths bail.
  if (action === 'demo') {
    window._demoMode = true;
    window._landingAction = 'demo';
    // Reset persona to 'couple' on every new demo session (per the spec —
    // the chosen persona doesn't persist across tab refreshes).
    window._demoPersona = 'couple';
    // Hide the wizard right now so it doesn't flash before init runs
    const _wiz = document.getElementById('wizard');
    if (_wiz) _wiz.style.display = 'none';
    document.body.classList.remove('wizard-active');
    history.replaceState(null, '', location.pathname);
    return;
  }

  history.replaceState(null, '', location.pathname);

  setTimeout(() => {
    if (action === 'quick-add') {
      if (typeof openQuickAdd === 'function') openQuickAdd();
    } else if (action === 'log-purchase') {
      if (typeof openLogPicker === 'function') openLogPicker();
    } else if (action === 'shopping') {
      showShoppingListInline();
    } else if (action === 'scan') {
      sessionStorage.setItem('barcode_target', 'scan-chooser');
      openBarcodeScanner();
    } else if (action === 'reminder-sync') {
      const id    = params.get('id')    || '';
      const date  = params.get('date')  || today();
      const token = params.get('token') || '';
      if (id && token && typeof applyReminderReplaced === 'function') applyReminderReplaced(id, date, token);
    } else if (action === 'unsubscribe') {
      if (typeof handleUnsubscribe === 'function') handleUnsubscribe();
    } else if (action === 'share') {
      // Share target — lazy-load scanner.js which has full handling
      window._loadScanner().then(() => handleURLAction()).catch(() => {});
    }
  }, 600);
}

init();

// (Notes section moved to notes.js — extracted 2026-05-21)

// ── 2FA prompt (MFA system) ───────────────

// ═══════════════════════════════════════════
//  BACK BUTTON / SWIPE INTERSTITIAL
// ═══════════════════════════════════════════

(function _initBackInterstitial() {
  // Push a history entry so the first back press/swipe hits us, not the previous page
  history.pushState({ stockroom: true }, '');

  let _touchStartX = 0;
  let _touchStartY = 0;
  const SWIPE_THRESHOLD = 40; // px from left edge to count as back swipe

  document.addEventListener('touchstart', e => {
    _touchStartX = e.touches[0].clientX;
    _touchStartY = e.touches[0].clientY;
  }, { passive: true });

  document.addEventListener('touchend', e => {
    const dx = e.changedTouches[0].clientX - _touchStartX;
    const dy = Math.abs(e.changedTouches[0].clientY - _touchStartY);
    // Swipe right from left edge (back gesture on iOS/Android)
    if (_touchStartX < 30 && dx > 60 && dy < 80) {
      _showBackInterstitial();
    }
  }, { passive: true });

  window.addEventListener('popstate', e => {
    if (window._allowExit) { window._allowExit = false; return; }
    if (e.state?.stockroom) return; // our own push — ignore
    history.pushState({ stockroom: true }, '');
    _showBackInterstitial();
  });
})();

function _showBackInterstitial() {
  // Don't show if wizard is active or a modal is already open
  if (document.body.classList.contains('wizard-active')) return;
  if (document.querySelector('.modal-backdrop.open')) return;
  openModal('back-interstitial-modal');
}

function backInterstitialGoTo(view) {
  closeModal('back-interstitial-modal');
  const tab = [...document.querySelectorAll('.tab, .app-nav-link')].find(t =>
    t.dataset?.view === view || t.textContent?.toLowerCase().includes(view)
  );
  if (tab) { tab.click(); } else { navTo(view); }
}

function backInterstitialExit() {
  closeModal('back-interstitial-modal');
  window._allowExit = true;
  history.back();
}

// ═══════════════════════════════════════════
//  MULTIFACTOR AUTHENTICATION (MFA)
// ═══════════════════════════════════════════
// Replaces notes-only 2FA. Works across the whole app via requireReauth hook.
// Methods: Email OTP | TOTP (authenticator app)
// ── MFA — multi-method system ─────────────────────────────────────────────
// settings.mfa shape (v2, backwards-compat with v1 single-method):
// {
//   enabled: bool,
//   methods: [
//     { type:'email', primary:bool },
//     { type:'totp',  secret:string, primary:bool }
//   ]
// }
// v1 compat: if methods absent, derive from legacy { method, totpSecret }

const _MFA_DISMISSED_KEY = 'stockroom_mfa_prompt_dismissed';
let _pendingMfaCallback = null;
let _mfaOtpSent = false;

function _mfaEnabled() {
  return !!(settings.mfa?.enabled);
}

function _mfaMethods() {
  // v2 shape: methods array is the source of truth
  if (Array.isArray(settings.mfa?.methods)) return settings.mfa.methods;
  // Disabled or not configured
  if (!settings.mfa?.enabled) return [];
  // v1 single-method compat (legacy accounts that haven't been migrated yet)
  const m = settings.mfa?.method || 'email';
  return [{ type: m, primary: true, ...(m === 'totp' ? { secret: settings.mfa.totpSecret } : {}) }];
}

function _mfaPrimaryMethod() {
  const methods = _mfaMethods();
  return methods.find(m => m.primary) || methods[0] || null;
}

// Legacy compat — old code calls _mfaMethod()
function _mfaMethod() {
  return _mfaPrimaryMethod()?.type || 'email';
}

// ── Login intercept ─────────────────────────────────────────────────────────
async function _mfaLoginIntercept(callback) {
  _pendingMfaCallback = callback;
  _mfaVerifyAltMode   = false;

  const primary     = _mfaPrimaryMethod();
  const isTotp      = primary?.type === 'totp';
  const hasBoth     = _mfaMethods().length > 1;

  // Show the correct hint panel and hide the other
  const emailHint = document.getElementById('mfa-email-hint');
  const totpHint  = document.getElementById('mfa-totp-hint');
  const altBtn    = document.getElementById('mfa-alt-method');
  const resendBtn = document.getElementById('mfa-resend-btn');
  const codeEl    = document.getElementById('mfa-verify-code');

  if (emailHint) emailHint.style.display = isTotp ? 'none' : 'block';
  if (totpHint)  totpHint.style.display  = isTotp ? 'block' : 'none';
  // Alt button only shown when user has both methods
  if (altBtn) {
    altBtn.style.display = hasBoth ? '' : 'none';
    altBtn.textContent   = isTotp ? 'Use email code instead' : 'Use authenticator app instead';
  }
  // Resend only relevant for email
  if (resendBtn) resendBtn.style.display = isTotp ? 'none' : '';
  if (codeEl) codeEl.value = '';

  openModal('mfa-verify-modal');

  if (!isTotp) {
    // Email primary — send OTP immediately
    if (emailHint) emailHint.innerHTML = '<p style="font-size:13px;color:var(--muted);margin-bottom:8px">Sending a code to your email…</p>';
    await _mfaSendEmailOtp();
    if (emailHint) emailHint.innerHTML = '<p style="font-size:13px;color:var(--muted);margin-bottom:8px">Enter the code sent to your email.</p>';
  }
}

async function _mfaIntercept(callback) {
  if (!_mfaEnabled()) { callback(); return; }
  _pendingMfaCallback = callback;
  _mfaVerifyAltMode   = false;

  const primary  = _mfaPrimaryMethod();
  const isTotp   = primary?.type === 'totp';
  const hasBoth  = _mfaMethods().length > 1;
  const emailHint = document.getElementById('mfa-email-hint');
  const totpHint  = document.getElementById('mfa-totp-hint');
  const altBtn    = document.getElementById('mfa-alt-method');
  const resendBtn = document.getElementById('mfa-resend-btn');
  const codeEl    = document.getElementById('mfa-verify-code');

  if (emailHint) emailHint.style.display = isTotp ? 'none' : 'block';
  if (totpHint)  totpHint.style.display  = isTotp ? 'block' : 'none';
  if (altBtn)    { altBtn.style.display  = hasBoth ? '' : 'none'; altBtn.textContent = isTotp ? 'Use email code instead' : 'Use authenticator app instead'; }
  if (resendBtn) resendBtn.style.display = isTotp ? 'none' : '';
  if (codeEl)    codeEl.value = '';

  openModal('mfa-verify-modal');
  if (!isTotp) await _mfaSendEmailOtp();
}

async function _mfaSendEmailOtp() {
  const errEl     = document.getElementById('mfa-otp-error');
  const sendingEl = document.getElementById('mfa-sending-status');
  if (errEl)     errEl.textContent = '';
  if (sendingEl) { sendingEl.textContent = 'Sending code…'; sendingEl.style.display = 'block'; }
  try {
    const res = await postKV(`${WORKER_URL}/mfa/otp/send`, { emailHash:_kvEmailHash, email: _kvEmail || settings.email || '', ..._kvSessionToken?{sessionToken:_kvSessionToken}:{verifier:_kvVerifier} });
    const d = await _readJsonSafe(res) || {};
    if (!res.ok) {
      if (errEl) errEl.textContent = d.error || `Could not send verification code (${res.status})`;
      if (sendingEl) sendingEl.style.display = 'none';
      return;
    }
    if (sendingEl) { sendingEl.textContent = 'Code sent ✓ — check your email'; }
    setTimeout(() => { if (sendingEl) sendingEl.style.display = 'none'; }, 3000);
    _mfaOtpSent = true;
  } catch(e) {
    if (errEl) errEl.textContent = 'Could not send code: ' + e.message;
    if (sendingEl) sendingEl.style.display = 'none';
  }
}

let _mfaVerifyAltMode = false;

async function mfaVerifySubmit() {
  const primaryMethod = _mfaMethod();
  const method = _mfaVerifyAltMode
    ? (primaryMethod === 'totp' ? 'email' : 'totp')
    : primaryMethod;
  const codeEl = document.getElementById('mfa-verify-code');
  const errEl  = document.getElementById('mfa-otp-error');
  const code   = codeEl?.value.trim().replace(/\s/g,'');
  if (!code || code.length < 6) { if(errEl) errEl.textContent='Enter your 6-digit code'; return; }

  if (method === 'email') {
    const res = await postKV(`${WORKER_URL}/mfa/otp/verify`, { emailHash:_kvEmailHash, otp:code });
    const d = await _readJsonSafe(res) || {};
    if (!res.ok) { if(errEl) errEl.textContent = d.error || `Incorrect code (${res.status})`; return; }
  } else {
    // TOTP — find secret from any stored location
    const methods    = _mfaMethods();
    const totpMethod = methods.find(m => m.type === 'totp');
    const secret     = totpMethod?.secret || settings.mfa?.totpSecret || null;
    if (!secret) {
      if(errEl) errEl.textContent = 'Authenticator app not configured on this account';
      console.error('TOTP verify: no secret found. settings.mfa =', JSON.stringify(settings.mfa));
      return;
    }
    const valid = await _totpVerify(secret, code);
    if (!valid) { if(errEl) errEl.textContent = 'Incorrect code — check your authenticator app and device clock'; return; }
  }

  _mfaVerifyAltMode = false;
  localStorage.removeItem('stockroom_mfa_was_active');
  // Mark MFA as verified for this browser session (allows trusted devices to skip on reload)
  try { sessionStorage.setItem(_MFA_SESSION_KEY, _kvEmailHash || '1'); } catch(e) {}
  closeModal('mfa-verify-modal');
  if (codeEl) codeEl.value = '';
  if (_pendingMfaCallback) { const cb = _pendingMfaCallback; _pendingMfaCallback = null; cb(); }
}

async function mfaResendCode() {
  await _mfaSendEmailOtp();
  toast('Code sent ✓');
}

async function mfaSwitchMethod() {
  _mfaVerifyAltMode = !_mfaVerifyAltMode;
  const primaryMethod   = _mfaMethod();
  const effectiveMethod = _mfaVerifyAltMode ? (primaryMethod === 'totp' ? 'email' : 'totp') : primaryMethod;
  const altBtn    = document.getElementById('mfa-alt-method');
  const totpHint  = document.getElementById('mfa-totp-hint');
  const emailHint = document.getElementById('mfa-email-hint');
  const resendBtn = document.getElementById('mfa-resend-btn');
  const codeEl    = document.getElementById('mfa-verify-code');
  if (altBtn)    altBtn.textContent        = effectiveMethod === 'totp' ? 'Use email code instead' : 'Use authenticator app instead';
  if (totpHint)  totpHint.style.display    = effectiveMethod === 'totp'  ? 'block' : 'none';
  if (emailHint) emailHint.style.display   = effectiveMethod === 'email' ? 'block' : 'none';
  if (resendBtn) resendBtn.style.display   = effectiveMethod === 'email' ? '' : 'none';
  if (codeEl)    codeEl.value = '';
  if (_mfaVerifyAltMode && effectiveMethod === 'email') await _mfaSendEmailOtp();
}

// ── Setup / Add method ──────────────────────────────────────────────────────
// _pendingMfaSetupMode: 'enable' (first time) | 'add' (adding second method)
let _pendingMfaSetupMode = 'enable';
let _mfaEmailTestSent    = false;

// ── MFA gate — single hard checkpoint for all login paths ────────────────────
// Every path into the app calls _mfaGate(callback). It:
//   1. Pulls the latest settings from the server (so MFA state is always fresh)
//   2. If MFA is enabled AND not already verified this session, shows verify modal
//   3. If disabled OR already verified this session, runs callback immediately
//
// "Stay signed in" behaviour with MFA:
//   - First load after sign-in: MFA fires, user verifies → flag set in sessionStorage
//   - Subsequent page loads in same browser session: flag present → MFA skipped
//   - Sign out or cookie/storage clear: sessionStorage wiped → MFA fires again next load
//   - Explicit sign-out always clears the flag
const _MFA_SESSION_KEY = 'stockroom_mfa_verified';

async function _mfaGate(callback) {
  // Pull fresh settings from server — MFA state must be authoritative from server.
  // Also merge setup flags so protectSeen/countrySet/installDismissed are fresh
  // when routing code runs inside the callback.
  if (kvConnected && _kvKey) {
    try {
      const remote = await kvPull();
      if (remote?.settings) {
        const remoteMfa = remote.settings.mfa;
        if (remoteMfa !== undefined) {
          settings.mfa = remoteMfa;
          localStorage.removeItem('stockroom_mfa_was_active');
        }
        // Merge one-time setup flags
        if (remote.settings._setupProtectSeen) settings._setupProtectSeen = true;
        if (remote.settings._setupCountrySet)  settings._setupCountrySet  = true;
        if (remote.settings._installDismissed) {
          settings._installDismissed = true;
          try { localStorage.setItem('stockroom_install_dismissed', '1'); } catch(e) {}
          try { localStorage.setItem('stockroom_ios_banner_dismissed', '1'); } catch(e) {}
        }
        await _saveSettings();
      }
    } catch(e) {
      console.warn('_mfaGate: pull failed, enforcing local/was-active MFA state:', e.message);
    }
  }

  const mfaActive = (kvConnected && _mfaEnabled()) ||
    (kvConnected && !!localStorage.getItem('stockroom_mfa_was_active'));

  if (!mfaActive) {
    await callback();
    return;
  }

  // MFA is enabled — check if already verified this browser session
  // sessionStorage is wiped on tab/browser close AND on cookie clear,
  // so "stay signed in" users only verify once per session.
  const alreadyVerified = sessionStorage.getItem(_MFA_SESSION_KEY) === _kvEmailHash;
  if (alreadyVerified) {
    await callback();
    return;
  }

  await _mfaLoginIntercept(callback);
}
function _totpGenerate(secret, time) {
  const b32   = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  const clean = secret.toUpperCase().replace(/[^A-Z2-7]/g,'');
  let bits = '';
  for (const c of clean) bits += b32.indexOf(c).toString(2).padStart(5,'0');
  const bytes = new Uint8Array(bits.length >> 3);
  for (let i = 0; i < bytes.length; i++) bytes[i] = parseInt(bits.slice(i*8,(i+1)*8),2);
  const counter = Math.floor((time || Date.now()/1000) / 30);
  const msg = new Uint8Array(8);
  let c = counter;
  for (let i = 7; i >= 0; i--) { msg[i] = c & 0xff; c >>>= 8; }
  async function hmacSha1(key, data) {
    const k = await crypto.subtle.importKey('raw', key, {name:'HMAC',hash:'SHA-1'}, false, ['sign']);
    return new Uint8Array(await crypto.subtle.sign('HMAC', k, data));
  }
  return hmacSha1(bytes, msg).then(hash => {
    const offset = hash[19] & 0xf;
    const code = ((hash[offset]&0x7f)<<24|(hash[offset+1]&0xff)<<16|(hash[offset+2]&0xff)<<8|(hash[offset+3]&0xff)) % 1000000;
    return code.toString().padStart(6,'0');
  });
}

async function _totpVerify(secret, code) {
  const t = Date.now()/1000;
  for (const offset of [-30, 0, 30]) {
    if (await _totpGenerate(secret, t + offset) === code) return true;
  }
  return false;
}

function _totpNewSecret() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  return Array.from(crypto.getRandomValues(new Uint8Array(20))).map(b => chars[b % 32]).join('');
}

function _totpOtpauthUrl(secret) {
  const label  = encodeURIComponent(`STOCKROOM:${settings.email || _kvEmail || 'account'}`);
  const issuer = encodeURIComponent('STOCKROOM');
  return `otpauth://totp/${label}?secret=${secret}&issuer=${issuer}&digits=6&period=30`;
}

async function _renderTotpQr(secret) {
  const canvas = document.getElementById('mfa-totp-qr-canvas');
  if (!canvas) return;
  const uri = _totpOtpauthUrl(secret);
  try {
    if (!window.QRious) {
      await new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = 'https://cdnjs.cloudflare.com/ajax/libs/qrious/4.0.2/qrious.min.js';
        s.onload = resolve; s.onerror = reject;
        document.head.appendChild(s);
      });
    }
    canvas.style.display = 'block';
    new window.QRious({ element: canvas, value: uri, size: 200, background: '#ffffff', foreground: '#000000' });
  } catch(e) {
    canvas.style.display = 'none';
    const fallback = document.getElementById('mfa-totp-qr-fallback');
    if (fallback) { fallback.style.display = 'block'; fallback.textContent = 'Could not load QR code — use the manual code below.'; }
  }
}

async function openMfaSetup() {
  _pendingMfaSetupMode = 'enable';
  _mfaEmailTestSent    = false;
  _mfaSetupReset();
  document.getElementById('mfa-setup-title').innerHTML    = '<svg class="icon icon-md" aria-hidden="true" style="color:var(--accent);vertical-align:-3px"><use href="#i-shield"></use></svg> Set Up Multifactor Authentication';
  document.getElementById('mfa-setup-subtitle').textContent = 'Choose your second factor and verify it works before enabling.';
  document.getElementById('mfa-setup-confirm-btn').textContent = 'Send code to my email →';
  // Always show both tabs — fresh enable, no existing methods
  const step = document.getElementById('mfa-setup-step-method');
  if (step) {
    step.style.display = '';
    step.querySelectorAll('.mfa-method-btn').forEach(b => b.style.display = '');
  }
  _mfaSetupSelectMethod('email');
  openModal('mfa-setup-modal');
}

function openMfaAddMethod() {
  const existing    = _mfaMethods().map(m => m.type);
  const canAddEmail = !existing.includes('email');
  const canAddTotp  = !existing.includes('totp');
  if (!canAddEmail && !canAddTotp) { toast('All available methods are already added'); return; }
  _pendingMfaSetupMode = 'add';
  _mfaEmailTestSent    = false;
  _mfaSetupReset();
  document.getElementById('mfa-setup-title').innerHTML = '<svg class="icon icon-md" aria-hidden="true"><use href="#i-plus"></use></svg> Add Authentication Method';
  document.getElementById('mfa-setup-subtitle').textContent = 'Verify the new method works before adding it.';
  document.getElementById('mfa-setup-confirm-btn').textContent = canAddEmail ? 'Send code to my email →' : 'Enable authenticator app ✓';
  const step = document.getElementById('mfa-setup-step-method');
  // Reset all tabs visible first, then hide the one that already exists
  step.querySelectorAll('.mfa-method-btn').forEach(b => b.style.display = '');
  const emailBtn = step.querySelector('[data-method="email"]');
  const totpBtn  = step.querySelector('[data-method="totp"]');
  if (emailBtn) emailBtn.style.display = canAddEmail ? '' : 'none';
  if (totpBtn)  totpBtn.style.display  = canAddTotp  ? '' : 'none';
  step.style.display = '';
  _mfaSetupSelectMethod(canAddEmail ? 'email' : 'totp');
  openModal('mfa-setup-modal');
}

function _mfaSetupReset() {
  const errEl = document.getElementById('mfa-setup-error');
  if (errEl) errEl.textContent = '';
  const codeEl = document.getElementById('mfa-setup-totp-code');
  if (codeEl) codeEl.value = '';
  const emailCodeEl = document.getElementById('mfa-setup-email-code');
  if (emailCodeEl) emailCodeEl.value = '';
  const testDiv = document.getElementById('mfa-setup-email-test');
  if (testDiv) testDiv.style.display = 'none';
  const emailDisp = document.getElementById('mfa-setup-email-display');
  if (emailDisp) emailDisp.textContent = settings.email || _kvEmail || '(your email)';
  // Pre-generate TOTP secret
  const secret = _totpNewSecret();
  window._pendingTotpSecret = secret;
  _renderTotpQr(secret).catch(() => {});
  const secretEl = document.getElementById('mfa-totp-secret-display');
  if (secretEl) secretEl.textContent = secret.match(/.{1,4}/g).join(' ');
}

function _mfaSetupSelectMethod(method) {
  toggle('mfa-setup-email-section', method === 'email', 'block');
  toggle('mfa-setup-totp-section', method === 'totp', 'block');
  // Tab styling
  document.querySelectorAll('.mfa-method-btn').forEach(b => {
    const active = b.dataset.method === method;
    b.style.background = active ? 'var(--accent)' : 'var(--surface2)';
    b.style.color      = active ? '#111' : 'var(--muted)';
  });
  window._pendingMfaSetupMethod = method;
  // Button label depends on method — email needs send step, TOTP doesn't
  const btn = document.getElementById('mfa-setup-confirm-btn');
  if (btn) btn.textContent = method === 'email' ? 'Send code to my email →' : 'Enable authenticator app ✓';
  // Reset email test state when switching tabs
  if (method === 'email') {
    _mfaEmailTestSent = false;
    const testDiv = document.getElementById('mfa-setup-email-test');
    if (testDiv) testDiv.style.display = 'none';
    const codeEl = document.getElementById('mfa-setup-email-code');
    if (codeEl) codeEl.value = '';
  }
}

async function mfaSetupConfirm() {
  const method  = window._pendingMfaSetupMethod || 'email';
  const errEl   = document.getElementById('mfa-setup-error');
  const btn     = document.getElementById('mfa-setup-confirm-btn');
  if (errEl) errEl.textContent = '';

  if (method === 'email') {
    if (!_mfaEmailTestSent) {
      // Stage 1: send the test code
      if (btn) { btn.disabled = true; btn.textContent = '⏳ Sending…'; }
      try {
        const res = await postKV(`${WORKER_URL}/mfa/otp/send`, { emailHash: _kvEmailHash, email: _kvEmail || settings.email || '',
            ..._kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier } });
        const d = await _readJsonSafe(res) || {};
        if (!res.ok) {
          if (errEl) errEl.textContent = d.error || `Could not send code — check your email address (${res.status})`;
          if (btn) { btn.disabled = false; btn.textContent = 'Send code to my email →'; }
          return;
        }
      } catch(e) {
        if (errEl) errEl.textContent = 'Error: ' + e.message;
        if (btn) { btn.disabled = false; btn.textContent = 'Send code to my email →'; }
        return;
      }
      _mfaEmailTestSent = true;
      // Reveal code input
      const testDiv = document.getElementById('mfa-setup-email-test');
      if (testDiv) testDiv.style.display = 'block';
      setTimeout(() => document.getElementById('mfa-setup-email-code')?.focus(), 100);
      if (btn) { btn.disabled = false; btn.textContent = 'Enable email MFA ✓'; }
      return; // wait for user to enter code and press again
    }

    // Stage 2: verify the code and enable
    const codeEl = document.getElementById('mfa-setup-email-code');
    const code   = codeEl?.value.trim();
    if (!code || code.length < 6) { if (errEl) errEl.textContent = 'Enter the 6-digit code from your email'; return; }
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Verifying…'; }
    try {
      const res = await postKV(`${WORKER_URL}/mfa/otp/verify`, { emailHash: _kvEmailHash, otp: code });
      const d = await _readJsonSafe(res) || {};
      if (!res.ok) {
        if (errEl) errEl.textContent = d.error || `Incorrect code — request a new one (${res.status})`;
        if (btn) { btn.disabled = false; btn.textContent = 'Enable email MFA ✓'; }
        return;
      }
    } catch(e) {
      if (errEl) errEl.textContent = 'Error: ' + e.message;
      if (btn) { btn.disabled = false; btn.textContent = 'Enable email MFA ✓'; }
      return;
    }
    const newMethod = { type: 'email', primary: true };
    _mfaFinishSetup(newMethod);

  } else {
    // TOTP — verify the code from the app
    const codeEl = document.getElementById('mfa-setup-totp-code');
    const code   = codeEl?.value.trim();
    if (!code || code.length < 6) { if (errEl) errEl.textContent = 'Enter the 6-digit code from your authenticator app'; return; }
    const valid = await _totpVerify(window._pendingTotpSecret, code);
    if (!valid) { if (errEl) errEl.textContent = 'Code incorrect — make sure your device clock is accurate'; return; }
    const newMethod = { type: 'totp', secret: window._pendingTotpSecret, primary: true };
    _mfaFinishSetup(newMethod);
  }
}

async function _mfaFinishSetup(newMethod) {
  if (_pendingMfaSetupMode === 'add') {
    const existing = _mfaMethods();
    newMethod.primary = false;
    existing.push(newMethod);
    settings.mfa = { enabled: true, methods: existing, method: null, totpSecret: null };
  } else {
    settings.mfa = { enabled: true, methods: [newMethod], method: null, totpSecret: null };
  }
  await _saveSettings();
  // Push first so the server has the new MFA state — then pull to confirm
  try {
    await kvPush();
  } catch(e) { console.warn('_mfaFinishSetup push failed:', e.message); }
  closeModal('mfa-setup-modal');
  closeModal('mfa-prompt-modal');
  localStorage.setItem(_MFA_DISMISSED_KEY, 'enabled');
  _updateMfaSettingsUI();
  toast(_pendingMfaSetupMode === 'add' ? 'Method added ✓' : 'Multifactor authentication enabled ✓');
  // Persistent account notification — security event, should be auditable
  // from the inbox even after the toast disappears.
  const _mfaAdded = _pendingMfaSetupMode === 'add';
  addNotification({
    type:      'account',
    title:     _mfaAdded ? 'New MFA method added' : 'Multifactor authentication enabled',
    body:      _mfaAdded
      ? 'A new authentication method has been added to your account.'
      : 'Your account is now protected by multifactor authentication.',
    sourceRef: _mfaAdded
      ? `account:mfa-method-added:${(newMethod && newMethod.id) || Date.now()}`
      : `account:mfa-enabled:${Date.now()}`,
  }).catch(_ => {});
}

// ── Manage methods ──────────────────────────────────────────────────────────
function openMfaManage() {
  _renderMfaManageList();
  _renderMfaManageFooter();
  openModal('mfa-manage-modal');
}

function _renderMfaManageFooter() {
  const footer  = document.getElementById('mfa-manage-footer');
  if (!footer) return;
  const methods  = _mfaMethods();
  const canAdd   = methods.length < 2;
  footer.innerHTML = `
    ${canAdd ? '<button class="btn btn-ghost" style="flex:1" onclick="closeModal(\'mfa-manage-modal\');openMfaAddMethod()">+ Add method</button>' : ''}
    <button class="btn btn-danger acc-sec-btn" onclick="closeModal(\'mfa-manage-modal\');mfaDisable()">Disable all MFA</button>
    <button class="btn btn-ghost" onclick="closeModal(\'mfa-manage-modal\')">Done</button>
  `;
}

function _renderMfaManageList() {
  const container = document.getElementById('mfa-manage-list');
  if (!container) return;
  const methods = _mfaMethods();
  if (!methods.length) { container.innerHTML = '<p style="font-size:13px;color:var(--muted)">No methods configured.</p>'; return; }
  container.innerHTML = methods.map((m, i) => {
    const label = m.type === 'totp' ? '<svg class="icon" aria-hidden="true"><use href="#i-smartphone"></use></svg> Authenticator app' : '<svg class="icon" aria-hidden="true"><use href="#i-mail"></use></svg> Email code';
    const primaryBadge = m.primary
      ? '<span style="font-size:10px;font-weight:700;color:var(--ok);background:rgba(76,187,138,0.15);padding:2px 8px;border-radius:99px;margin-left:8px">PRIMARY</span>'
      : `<button onclick="mfaSetPrimary(${i})" style="font-size:11px;background:none;border:none;color:var(--accent);cursor:pointer;margin-left:8px;text-decoration:underline">Set primary</button>`;
    const removeLabel = methods.length === 1 ? 'Remove &amp; disable MFA' : 'Remove';
    return `<div style="display:flex;align-items:center;justify-content:space-between;padding:12px;background:var(--surface2);border:1px solid var(--border);border-radius:10px;margin-bottom:8px">
      <div style="font-size:13px;font-weight:600">${label}${primaryBadge}</div>
      <button class="btn btn-ghost btn-sm" style="color:var(--danger);flex-shrink:0;white-space:nowrap" onclick="mfaRemoveMethod(${i})">${removeLabel}</button>
    </div>`;
  }).join('');
}

async function mfaSetPrimary(idx) {
  const methods = _mfaMethods();
  methods.forEach((m, i) => { m.primary = (i === idx); });
  settings.mfa = { ...settings.mfa, methods, method: null, totpSecret: null };
  await _saveSettings();
  try { await kvPush(); } catch(e) { console.warn('mfaSetPrimary push failed:', e.message); }
  _renderMfaManageList();
  _updateMfaSettingsUI();
}

async function mfaRemoveMethod(idx) {
  const methods  = _mfaMethods();
  const removing = methods[idx];
  if (!removing) return;
  const label = removing.type === 'totp' ? 'authenticator app' : 'email code';
  if (methods.length === 1) { mfaDisable(); return; }
  // Snapshot updated list now before the reauth delay changes anything
  const updatedMethods = methods.filter((_, i) => i !== idx);
  if (!updatedMethods.some(m => m.primary)) updatedMethods[0].primary = true;
  requireReauth(
    `Confirm your identity to remove the ${label} from MFA.`,
    async () => {
      settings.mfa = { enabled: true, methods: updatedMethods, method: null, totpSecret: null };
      await _saveSettings();
      try { await kvPush(); } catch(e) { console.warn('mfaRemoveMethod push failed:', e.message); }
      _renderMfaManageList();
      _updateMfaSettingsUI();
      toast('Method removed');
    },
    { passkeyAllowed: true }
  );
}

function mfaDisable() {
  requireReauth(
    'Confirm your identity to disable multifactor authentication.',
    async () => {
      settings.mfa = { enabled: false, methods: [], method: null, totpSecret: null };
      await _saveSettings();
      try { await kvPush(); } catch(e) { console.warn('mfaDisable push failed:', e.message); }
      closeModal('mfa-manage-modal');
      _updateMfaSettingsUI();
      toast('MFA disabled');
      // Security-relevant change — always notify, even when self-initiated.
      // The inbox entry serves as an audit trail; if the user later sees a
      // "MFA disabled" notification they didn't trigger, that's their cue
      // to investigate.
      addNotification({
        type:      'account',
        title:     'Multifactor authentication disabled',
        body:      'MFA is no longer required to sign in. If you didn\'t make this change, re-enable MFA immediately.',
        sourceRef: `account:mfa-disabled:${Date.now()}`,
      }).catch(_ => {});
    },
    { passkeyAllowed: true }
  );
}

function _updateMfaSettingsUI() {
  const enabledEl   = document.getElementById('mfa-settings-status');
  const toggleBtn   = document.getElementById('mfa-settings-toggle');
  const actionBtns  = document.getElementById('mfa-action-btns');
  const methodsList = document.getElementById('mfa-methods-list');
  const enabled  = _mfaEnabled() && _mfaMethods().length > 0;
  const methods  = _mfaMethods();

  if (enabledEl) {
    if (!enabled) {
      enabledEl.textContent = 'Disabled';
      enabledEl.style.color = '';
    } else {
      const primary = _mfaPrimaryMethod();
      const label   = primary?.type === 'totp' ? 'Authenticator app' : 'Email code';
      enabledEl.textContent = `Enabled — primary: ${label}${methods.length > 1 ? ` + ${methods.length - 1} backup` : ''}`;
      enabledEl.style.color = 'var(--ok)';
    }
  }

  // Swap action buttons based on state
  if (actionBtns) {
    if (!enabled) {
      actionBtns.innerHTML = '<button id="mfa-settings-toggle" class="btn btn-ghost acc-sec-btn" onclick="openMfaSetup()">Enable</button>';
    } else {
      actionBtns.innerHTML = `
        <button class="btn btn-ghost acc-sec-btn" onclick="openMfaManage()">Manage</button>
        ${methods.length < 2 ? '<button class="btn btn-ghost acc-sec-btn" onclick="openMfaAddMethod()">Add method</button>' : ''}`;
    }
  }

  // Show method list inline
  if (methodsList) {
    if (enabled && methods.length) {
      methodsList.style.display = '';
      methodsList.innerHTML = methods.map(m => {
        const icon  = m.type === 'totp'
          ? '<svg class="icon" aria-hidden="true" style="width:12px;height:12px"><use href="#i-smartphone"></use></svg>'
          : '<svg class="icon" aria-hidden="true" style="width:12px;height:12px"><use href="#i-mail"></use></svg>';
        const label = m.type === 'totp' ? 'Authenticator app' : 'Email code';
        return `<span style="display:inline-flex;align-items:center;gap:4px;font-size:12px;padding:3px 10px;border-radius:99px;background:${m.primary?'rgba(76,187,138,0.15)':'rgba(120,128,160,0.15)'};color:${m.primary?'var(--ok)':'var(--muted)'};margin-right:6px;margin-bottom:4px">${icon} ${label}${m.primary?' ★':''}</span>`;
      }).join('');
    } else {
      methodsList.style.display = 'none';
    }
  }

  // Compat — old UI button refs
  const n2faBtn = document.getElementById('notes-2fa-settings-btn');
  if (n2faBtn) n2faBtn.textContent = enabled ? 'Disable' : 'Enable';
  const n2faAcc = document.getElementById('notes-2fa-acc-btn');
  if (n2faAcc) n2faAcc.textContent = enabled ? 'Disable' : 'Enable';
}

function _maybeShowMfaPrompt() {
  if (_mfaEnabled()) return;
  if (settings._mfaPromptDismissed) return;
  if (localStorage.getItem(_MFA_DISMISSED_KEY)) return; // legacy fallback
  if (!kvConnected) return;
  openModal('mfa-prompt-modal');
}

function dismissMfaPrompt() {
  // Persist to the synced settings blob so it survives cookie/storage clears
  settings._mfaPromptDismissed = true;
  _saveSettings().then(() => { if (kvConnected) kvPush().catch(() => {}); });
  // Also set localStorage for immediate effect within this session
  try { localStorage.setItem(_MFA_DISMISSED_KEY, 'dismissed'); } catch(e) {}
  closeModal('mfa-prompt-modal');
}
function resetFirstRunPrompts() {
  // Clear all first-run/onboarding dismissed flags from the synced settings blob.
  // On next login the Protecting Your Data, Country, Amazon import and
  // Enable MFA prompts will all show again as if it were a first-time setup.
  // Use `delete` (not `= false`) for the sticky one-shot flags so the
  // OR-merge in kvSyncNow can't undo the reset by restoring the server-side
  // true. The push immediately below writes settings without these keys,
  // so the server-side flags are also cleared.
  delete settings._setupProtectSeen;
  delete settings._setupCountrySet;
  delete settings._installDismissed;
  settings._amazonBannerDismissed = false;
  settings._snsBannerDismissed    = false;
  settings._mfaPromptDismissed   = false;
  // Also clear the legacy localStorage key for MFA
  try { localStorage.removeItem(_MFA_DISMISSED_KEY); } catch(e) {}
  _saveSettings().then(() => { if (kvConnected) kvPush().catch(() => {}); });
  toast('First-run prompts reset — they will show again on next login ✓');
}

function renderAccountSecurity() {
  // Your Details
  const nameEl = document.getElementById('setting-display-name-sec');
  if (nameEl && settings.displayName) nameEl.value = settings.displayName;
  const emailEl = document.getElementById('acc-sec-email');
  if (emailEl) emailEl.textContent = settings.email || _kvEmail || '—';

  // Country
  const countryEl = document.getElementById('setting-country-sec');
  if (countryEl && COUNTRIES) {
    if (!countryEl.options.length) {
      COUNTRIES.forEach(c => {
        const opt = document.createElement('option');
        opt.value = c.code; opt.textContent = `${c.flag} ${c.name}`;
        countryEl.appendChild(opt);
      });
    }
    countryEl.value = settings.country || 'GB';
  }

  // MFA status
  _updateMfaSettingsUI();

  // Push notification toggle status
  renderPushSettingsUI().catch(_ => {});

  // Load passkeys into account security list
  if (kvConnected) {
    loadPasskeys().catch(() => {});

    loadTrustedDevices().then(() => {
      const tdListSec = document.getElementById('trusted-devices-list-sec');
      const tdListMain = document.getElementById('trusted-devices-list');
      if (tdListSec && tdListMain) tdListSec.innerHTML = tdListMain.innerHTML;
    }).catch(() => {});
  }
}

function toggleTrustedDevicesPanel() {
  const panel = document.getElementById('trusted-devices-panel-sec') || document.getElementById('trusted-devices-panel');
  if (!panel) return;
  const hidden = panel.style.display === 'none';
  panel.style.display = hidden ? 'block' : 'none';
  document.querySelectorAll('[onclick="toggleTrustedDevicesPanel()"]').forEach(btn => {
    btn.textContent = hidden ? 'Hide devices' : 'Show devices';
  });
  if (hidden) loadTrustedDevices();
}

// ── Deactivate Account ────────────────────
function openDeactivateAccount() {
  openModal('deactivate-account-modal');
}

async function confirmDeactivateAccount() {
  closeModal('deactivate-account-modal');
  try {
    const res = await postKV(`${WORKER_URL}/user/deactivate`, {
        emailHash: _kvEmailHash,
        ..._kvSessionToken ? { sessionToken: _kvSessionToken } : { verifier: _kvVerifier },
      });
    if (!res.ok) {
      const d = await res.json();
      toast('Could not deactivate: ' + (d.error || 'Unknown error'));
      return;
    }
    toast('Account deactivated. You will be signed out.');
    setTimeout(() => kvSignOut(), 2000);
  } catch(e) {
    toast('Error: ' + e.message);
  }
}

// ── Delete Account Flow ───────────────────
function openDeleteAccountFlow() {
  const inp = document.getElementById('delete-confirm-input');
  const err = document.getElementById('delete-confirm-error');
  const btn = document.getElementById('delete-confirm-btn');
  if (inp) inp.value = '';
  if (err) err.textContent = '';
  if (btn) btn.disabled = true;
  openModal('delete-account-step1-modal');
}

function deleteAccountStep2() {
  closeModal('delete-account-step1-modal');
  openModal('delete-account-step2-modal');
  setTimeout(() => document.getElementById('delete-confirm-input')?.focus(), 200);
}

function checkDeleteConfirmInput() {
  const val = document.getElementById('delete-confirm-input')?.value || '';
  const btn = document.getElementById('delete-confirm-btn');
  if (btn) btn.disabled = val !== 'Delete';
}

function deleteAccountStep3() {
  const val = document.getElementById('delete-confirm-input')?.value;
  if (val !== 'Delete') {
    const err = document.getElementById('delete-confirm-error');
    if (err) err.textContent = 'Type exactly: Delete';
    return;
  }
  closeModal('delete-account-step2-modal');
  const ppErr = document.getElementById('delete-passphrase-error');
  const ppInp = document.getElementById('delete-passphrase-input');
  if (ppErr) ppErr.textContent = '';
  if (ppInp) ppInp.value = '';
  openModal('delete-account-step3-modal');
  setTimeout(() => ppInp?.focus(), 200);
}

async function deleteAccountFinal() {
  const pass = document.getElementById('delete-passphrase-input')?.value;
  const errEl = document.getElementById('delete-passphrase-error');
  if (!pass) { if (errEl) errEl.textContent = 'Enter your passphrase'; return; }
  try {
    const verifier = await kvMakeVerifier(pass, _kvEmailHash);
    const res = await postKV(`${WORKER_URL}/user/delete-confirm-send`, { emailHash: _kvEmailHash, verifier });
    if (!res.ok) {
      const d = await res.json();
      if (errEl) errEl.textContent = d.error || 'Incorrect passphrase';
      return;
    }
    closeModal('delete-account-step3-modal');
    openModal('delete-email-sent-modal');
  } catch(e) {
    if (errEl) errEl.textContent = 'Error: ' + e.message;
  }
}

// Called when user lands on app after clicking "Delete Account" in email
async function handleDeleteAccountConfirmation(token) {
  try {
    const res = await postKV(`${WORKER_URL}/user/delete-execute`, { token });
    if (res.ok) {
      // Clear all local data
      try { localStorage.clear(); } catch(e) {}
      openModal('account-deleted-modal');
      // Hide the rest of the app
      hide('main');
    } else {
      const d = await res.json();
      toast('Could not complete deletion: ' + (d.error || 'Link may have expired'));
    }
  } catch(e) {
    toast('Error: ' + e.message);
  }
}

// Check URL for delete confirmation token on load
(function _checkDeleteToken() {
  const params = new URLSearchParams(location.search);
  const deleteToken = params.get('delete_token');
  if (deleteToken) {
    history.replaceState(null, '', location.pathname);
    // Wait for app to init before showing modal
    setTimeout(() => handleDeleteAccountConfirmation(deleteToken), 1000);
  }
  const reactivateToken = params.get('reactivate_token');
  if (reactivateToken) {
    history.replaceState(null, '', location.pathname);
    setTimeout(() => handleReactivation(reactivateToken), 1000);
  }
})();

async function handleReactivation(token) {
  try {
    const res = await postKV(`${WORKER_URL}/user/reactivate`, { token });
    if (res.ok) {
      toast('Your account has been reactivated! Please sign in.');
    } else {
      const d = await res.json();
      toast('Reactivation failed: ' + (d.error || 'Link may have expired'));
    }
  } catch(e) {
    toast('Error: ' + e.message);
  }
}

// ═══════════════════════════════════════════════════════════════════
//  OMNIBOX — Pass 1
// ═══════════════════════════════════════════════════════════════════
// The omnibox is the persistent input bar at the top of every tab.
// It replaces the modal-based global search and adds six action
// buttons (Search / Stockroom / Groceries / Reminders / Notes /
// Spend) that operate on the text in the input.
//
// The existing search engine (runGlobalSearch, _searchStockroom etc.)
// is reused unchanged — we just retarget its renderer at the omnibox's
// own results container. _navigateToSearchResult is also reused; it
// closes the omnibox via closeGlobalSearch's body-class cleanup, which
// we still trigger here for compatibility.
//
// Architecture:
//   - #omnibox in index.html has data-state="collapsed" by default.
//   - onOmniboxFocus / onOmniboxInput flip it to "expanded" and run
//     the same debounced search as the old global modal did.
//   - The action buttons (.omnibox-action) call omniboxAction(kind),
//     which routes to the existing add-flow for that destination.
//   - Pass 2 will add intent detection — for now all buttons are
//     always enabled and Search is the Enter-key default.

const _OMNIBOX = {
  active: false,
  debounceTimer: null,
  query: '',
  // Set to true once auto-grow is wired so we don't double-bind.
  autoGrowBound: false,
};

function _omniboxEl()      { return document.getElementById('omnibox'); }
function _omniboxInput()   { return document.getElementById('omnibox-input'); }
function _omniboxResults() { return document.getElementById('omnibox-results'); }

function onOmniboxFocus() {
  expandOmnibox();
}

// Expand the omnibox panel. Idempotent — safe to call from focus,
// keyboard shortcut, paste, etc.
function expandOmnibox() {
  const omni = _omniboxEl();
  if (!omni) return;
  omni.setAttribute('data-state', 'expanded');
  _OMNIBOX.active = true;
  document.body.classList.add('omnibox-expanded');
  // Scroll-lock both html and body — iOS Safari scrolls the html element
  // while everywhere else scrolls body, and we need to freeze whichever
  // is doing the scrolling while the omnibox overlay is open.
  document.documentElement.classList.add('omnibox-locked');
  // Show the collapse chevron (mobile users need a way to dismiss the
  // panel without losing what they typed). Clear-X visibility is
  // managed separately based on input value.
  const collapseBtn = document.getElementById('omnibox-collapse-btn');
  if (collapseBtn) collapseBtn.style.display = '';
  _refreshOmniboxClearButton();
}

// Collapse without clearing the input. Useful when the user is mid-typing
// and wants to see the page again — they can tap back in to resume.
function collapseOmnibox() {
  const omni = _omniboxEl();
  if (!omni) return;
  omni.setAttribute('data-state', 'collapsed');
  _OMNIBOX.active = false;
  document.body.classList.remove('omnibox-expanded');
  document.documentElement.classList.remove('omnibox-locked');
  const collapseBtn = document.getElementById('omnibox-collapse-btn');
  if (collapseBtn) collapseBtn.style.display = 'none';
  // Blur the input so the keyboard dismisses on mobile.
  try { _omniboxInput()?.blur(); } catch(_) {}
}

// Switch the action-button layout at runtime. `key` is one of
// 'chips' | 'grid' | 'list' — see styles.css for the visual treatment of
// each. Persists across reloads via localStorage so Pete can try a layout,
// keep using the app for a while, and not have to re-set it each session.
//
// From the browser console:
//   setOmniboxLayout('grid')
//   setOmniboxLayout('list')
//   setOmniboxLayout('chips')
//
// Once Pete picks one, we delete the other two CSS blocks and remove the
// data-layout attribute from the HTML.
function setOmniboxLayout(key) {
  if (!['chips', 'grid', 'list'].includes(key)) {
    console.warn('Unknown omnibox layout:', key, '— expected chips/grid/list');
    return;
  }
  const el = document.getElementById('omnibox-actions');
  if (!el) return;
  el.setAttribute('data-layout', key);
  try { localStorage.setItem('stockroom_omnibox_layout', key); } catch(_) {}
  console.log('[omnibox] layout set to', key);
}
// Restore last-chosen layout on load (no-op if nothing saved).
try {
  const _stored = localStorage.getItem('stockroom_omnibox_layout');
  if (_stored && ['chips','grid','list'].includes(_stored)) {
    // Defer until DOM is ready; the omnibox element may not exist yet
    // when this script is parsed.
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', () => setOmniboxLayout(_stored));
    } else {
      setOmniboxLayout(_stored);
    }
  }
} catch(_) {}

// Clear input + results, keep panel expanded with focus.
function clearOmnibox() {
  const inp = _omniboxInput();
  if (inp) { inp.value = ''; }
  _OMNIBOX.query = '';
  clearTimeout(_OMNIBOX.debounceTimer);
  _renderOmniboxEmpty();
  _refreshOmniboxClearButton();
  _autoGrowOmnibox();
  try { inp?.focus(); } catch(_) {}
}

// Show/hide the clear-X based on whether the input has any text.
function _refreshOmniboxClearButton() {
  const btn = document.getElementById('omnibox-clear-btn');
  const inp = _omniboxInput();
  if (!btn || !inp) return;
  btn.style.display = inp.value ? '' : 'none';
}

// Auto-grow the textarea from 1 line up to ~4 lines, then stop (CSS
// caps overflow to hidden). Without this the field stays at 1 line
// even after wrapping, which feels broken when pasting a block.
function _autoGrowOmnibox() {
  const ta = _omniboxInput();
  if (!ta) return;
  // Reset to single line first so we can measure scrollHeight cleanly.
  ta.style.height = 'auto';
  // Cap at the CSS max-height (96px) — anything taller stays scrollable
  // internally rather than pushing the panel down.
  const h = Math.min(ta.scrollHeight, 96);
  ta.style.height = h + 'px';
}

function _renderOmniboxEmpty() {
  const container = _omniboxResults();
  if (!container) return;
  container.innerHTML = '<div class="omnibox-empty">Type to search or use the buttons below to add.</div>';
}

// Fires on every keystroke. Same debounce window as the old global
// search (120ms). Routes the query through runGlobalSearch by
// temporarily aliasing the results container — see the
// _redirectSearchRender helper.
function onOmniboxInput() {
  const inp = _omniboxInput();
  if (!inp) return;
  _autoGrowOmnibox();
  _refreshOmniboxClearButton();
  const q = (inp.value || '').trim();
  _OMNIBOX.query = q;
  clearTimeout(_OMNIBOX.debounceTimer);
  if (!q) { _renderOmniboxEmpty(); return; }
  _OMNIBOX.debounceTimer = setTimeout(() => {
    try { _runOmniboxSearch(q); } catch (err) { console.error('Omnibox search failed:', err); }
  }, 120);
}

// Run the existing runGlobalSearch but route its output into the
// omnibox's #omnibox-results container instead of #global-search-
// results. We do this by temporarily swapping IDs — cheap and
// reversible. Avoids forking the searcher.
function _runOmniboxSearch(q) {
  const omniResults    = _omniboxResults();
  const oldModalResults = document.getElementById('global-search-results');
  if (!omniResults) return;

  // runGlobalSearch queries by ID 'global-search-results'. The cleanest
  // way to redirect without touching that code is to rename the modal
  // container (if it exists) and give our own container that ID for
  // the duration of the call. Restore IDs after.
  let renamed = false;
  if (oldModalResults && oldModalResults !== omniResults) {
    oldModalResults.id = 'global-search-results__shadowed';
    omniResults.id = 'global-search-results';
    renamed = true;
  } else {
    // Old modal absent (or already shadowed) — just give our container
    // the expected ID for this call.
    omniResults.id = 'global-search-results';
    renamed = true;
  }

  try {
    runGlobalSearch(q);
  } finally {
    if (renamed) {
      // Restore. The omnibox container goes back to its own ID; the
      // shadowed modal container (if any) gets its original ID back.
      omniResults.id = 'omnibox-results';
      const shadowed = document.getElementById('global-search-results__shadowed');
      if (shadowed) shadowed.id = 'global-search-results';
    }
  }
}

// Keyboard handler. Enter = run primary action (Pass 1: always Search).
// Esc = collapse.
function onOmniboxKeyDown(e) {
  if (e.key === 'Escape') {
    e.preventDefault();
    collapseOmnibox();
    return;
  }
  if (e.key === 'Enter') {
    // Pass 1: Enter is "smart" but only between Search-with-results and
    // Search-without. Pass 2 will swap in the detected destination if
    // no results exist and an intent was detected.
    if (!e.shiftKey) {
      e.preventDefault();
      _omniboxEnterSmart();
    }
    // Shift+Enter inserts a newline — useful for the eventual Reminders /
    // Notes paths that accept multi-line input. Auto-grow handles it.
  }
}

// "Smart" Enter handling. Pass 1 implementation:
//   - If there are search results, jump to the first one.
//   - Otherwise, fall back to Search action (which is a no-op visually
//     since the empty-results state is already shown).
// Pass 2 replaces the fallback with the detected destination action.
function _omniboxEnterSmart() {
  // Look for the first .global-search-row inside our results container.
  const firstRow = _omniboxResults()?.querySelector('.global-search-row');
  if (firstRow) {
    // Simulate a click — reuses the existing onclick handler which calls
    // _navigateToSearchResult with the right payload.
    firstRow.click();
    return;
  }
  // No results — Pass 1 fallback is just "do nothing useful but don't
  // submit a form either". Pass 2 swaps in the detected add action.
}

// ── Action button handler ───────────────────────────────────────────
// Routes the current input text to the right add-flow. Each branch
// re-uses existing functions so this layer stays thin.
function omniboxAction(kind) {
  const text = (_omniboxInput()?.value || '').trim();
  if (!text && kind !== 'search') {
    toast('Type something first');
    return;
  }
  switch (kind) {
    case 'search':
      // Search is mostly a no-op — typing already runs the search live.
      // We use this button as a "make sure I'm in search mode" cue and
      // a focus target on mobile when the user wants to dismiss the
      // keyboard and tap a result.
      try { _omniboxInput()?.blur(); } catch(_) {}
      return;

    case 'stockroom':
      return _omniboxAddToStockroom(text);

    case 'groceries':
      return _omniboxAddToGroceries(text);

    case 'reminders':
      return _omniboxAddToReminders(text);

    case 'notes':
      return _omniboxAddToNotes(text);

    case 'spend':
      return _omniboxAddToSpend(text);

    default:
      console.warn('Unknown omnibox action:', kind);
  }
}

// ── Stockroom ──
// Routes through the existing Quick Add path. We open the modal,
// stuff the text in, call saveQuickAdd. The modal opens briefly so
// the user can confirm/back out — Pass 3 may inline this.
function _omniboxAddToStockroom(text) {
  if (typeof openQuickAdd !== 'function' || typeof saveQuickAdd !== 'function') {
    toast('Stockroom add not available');
    return;
  }
  openQuickAdd();
  // openQuickAdd clears the input then focuses it on a setTimeout. We
  // need to set the value AFTER that runs.
  setTimeout(() => {
    const qaInput = document.getElementById('quick-add-input');
    if (!qaInput) return;
    qaInput.value = text;
    if (typeof updateQuickAddPreview === 'function') updateQuickAddPreview();
    _omniboxAfterAddCleanup();
  }, 120);
}

// ── Groceries ──
// Open the Quick List overlay with the text pre-filled. User confirms
// list name and saves.
function _omniboxAddToGroceries(text) {
  if (typeof openQuickList !== 'function') {
    toast('Quick List not available');
    return;
  }
  openQuickList();
  // Wait for the overlay's input to mount, then fill it.
  setTimeout(() => {
    const inp = document.getElementById('quick-list-input');
    if (!inp) return;
    inp.value = text;
    if (typeof _quickListAutocomplete === 'function') {
      try { _quickListAutocomplete(text); } catch(_) {}
    }
    _omniboxAfterAddCleanup();
  }, 120);
}

// ── Reminders ──
// Split text on commas AND newlines, each entry becomes a reminder
// with a default 3-month cadence. This is faster than opening the
// modal for each one. The user can edit individual reminders later.
async function _omniboxAddToReminders(text) {
  if (typeof saveReminders !== 'function') {
    toast('Reminders not available');
    return;
  }
  // Permission check — match what saveReminder does.
  if (typeof canWrite === 'function' && !canWrite('reminders')) {
    if (typeof showLockBanner === 'function') showLockBanner('reminders');
    return;
  }
  const names = text.split(/[,\n]/).map(s => s.trim()).filter(Boolean);
  if (!names.length) { toast('Type at least one reminder'); return; }
  const now = new Date().toISOString();
  for (const name of names) {
    reminders.push({
      id:           (typeof uid === 'function') ? uid() : ('r_' + Date.now() + '_' + Math.random().toString(36).slice(2,6)),
      name,
      interval:     3,
      unit:         'months',
      lastReplaced: null,
      notes:        '',
      linkedItemId: null,
      createdAt:    now,
    });
  }
  await saveReminders();
  if (typeof _syncQueue !== 'undefined' && _syncQueue?.enqueue) _syncQueue.enqueue();
  if (typeof renderReminders === 'function') renderReminders();
  toast(`${names.length} reminder${names.length === 1 ? '' : 's'} added`);
  _omniboxAfterAddCleanup(true);
}

// ── Notes ──
// Create one note with the typed text as the body. Title is the first
// line (or first 60 chars if the line is long). Sets contenteditable
// innerHTML correctly since note bodies use innerHTML, not .value.
async function _omniboxAddToNotes(text) {
  if (typeof saveNotes !== 'function' || typeof notes === 'undefined') {
    toast('Notes not available');
    return;
  }
  if (typeof canWrite === 'function' && !canWrite('notes')) {
    if (typeof showLockBanner === 'function') showLockBanner('notes');
    return;
  }
  // First line becomes the title; rest becomes the body. If only one
  // line, use it as title and leave body empty (user can expand later).
  const lines = text.split('\n');
  const firstLine = (lines[0] || '').trim();
  const rest = lines.slice(1).join('\n').trim();
  const title = firstLine.length > 60 ? firstLine.slice(0, 60) : firstLine;
  // Note bodies are stored as innerHTML — convert newlines to <br>.
  const bodyHTML = rest ? rest.replace(/\n/g, '<br>') : '';
  const now = new Date().toISOString();
  const newNote = {
    id:               (typeof _noteUid === 'function') ? _noteUid() : ('n_' + Date.now() + '_' + Math.random().toString(36).slice(2,6)),
    title,
    body:             bodyHTML,
    locked:           false,
    pinned:           false,
    archived:         false,
    colour:           null,
    tickBoxesVisible: false,
    tickBoxes:        {},
    createdAt:        now,
    updatedAt:        now,
    deletedAt:        null,
  };
  notes.push(newNote);
  await saveNotes();
  if (typeof _syncNoteIfConnected === 'function') {
    try { await _syncNoteIfConnected(); } catch(_) {}
  }
  if (typeof renderNotes === 'function') renderNotes();
  toast('Note added');
  _omniboxAfterAddCleanup(true);
}

// ── Spend ──
// Open the Spend Quick Add modal with the text pre-filled. The modal
// has its own parser/preview that's already excellent — we just
// stuff text in. Pass 3 will render the preview inline in the omnibox
// itself and bypass the modal entirely.
function _omniboxAddToSpend(text) {
  if (typeof openQuickAddSpend !== 'function') {
    toast('Spend add not available');
    return;
  }
  openQuickAddSpend();
  setTimeout(() => {
    const inp = document.getElementById('spend-quick-add-input');
    if (!inp) return;
    inp.value = text;
    if (typeof quickAddInputChanged === 'function') {
      try { quickAddInputChanged(); } catch(_) {}
    }
    _omniboxAfterAddCleanup();
  }, 120);
}

// Common cleanup after an action fires. If `fullyHandled` is true the
// action completed without opening another modal — clear input and
// collapse. Otherwise (modal opened) just keep the omnibox out of the
// way; the user will continue in the modal.
function _omniboxAfterAddCleanup(fullyHandled) {
  if (fullyHandled) {
    clearOmnibox();
    collapseOmnibox();
  } else {
    // A modal is now open — collapse omnibox so its expanded panel
    // doesn't visually stack on top of the modal backdrop.
    collapseOmnibox();
  }
}

// ── Keyboard shortcut: Cmd/Ctrl+K focuses the omnibox ──
// The old _globalSearchKeyShortcut opened the modal. Hijack the same
// shortcut to focus the omnibox instead. The OLD handler is still in
// app.js (it calls openGlobalSearch) — we don't remove it because the
// modal is still present in the DOM; instead the new handler runs
// first and stops propagation. If our handler ever fails to bind,
// the old one is a harmless fallback.
function _omniboxKeyShortcut(e) {
  // Don't trigger if the user is already typing in a text field other
  // than ours (avoids stealing Cmd+K from rich editors).
  const t = e.target;
  if (t && (t.id === 'omnibox-input')) return;
  const isMac = navigator.platform && /Mac|iPhone|iPad|iPod/.test(navigator.platform);
  const mod = isMac ? e.metaKey : e.ctrlKey;
  if (mod && e.key && e.key.toLowerCase() === 'k') {
    e.preventDefault();
    e.stopPropagation();
    const inp = _omniboxInput();
    if (!inp) return;
    expandOmnibox();
    try { inp.focus(); inp.select(); } catch(_) {}
  }
}

// ── Tier 4.1: Global keyboard shortcuts ─────────────────────────────────
// Gmail-style navigation and a couple of single-key shortcuts. Deliberately
// conservative: every shortcut bails the moment the user is typing in a
// field, so it never interferes with the omnibox, note editor, inputs,
// selects, or any contenteditable. Cmd/Ctrl+K (omnibox) is handled
// separately in _omniboxKeyShortcut and is unaffected.
//
// Shortcuts:
//   /         focus the omnibox search (when not typing)
//   ?         toggle the keyboard-shortcuts help overlay
//   Esc       close the help overlay (other Esc handlers are untouched)
//   g then …  navigate to a view (Gmail "go to" pattern):
//               g s  Stockroom        g g  Groceries
//               g b  Budget           g n  Notes
//               g r  Reminders        g v  Savings (a"v"ings)
//               g p  Report           g a  Accessibility
//               g c  Account & Security (se"c"urity)
//               g t  Settings (se"t"tings)
//
// The g-prefix uses a short timeout window: press g, then the second key
// within ~1.2s. Pressing g alone does nothing; an unrecognised second key
// silently cancels.
const _GKEY = { armed: false, timer: null };
const _GKEY_MAP = {
  s: 'stock',
  g: 'grocery',
  b: 'budget',
  n: 'notes',
  r: 'reminders',
  v: 'savings',
  p: 'report',
  a: 'accessibility',
  c: 'account-security',
  t: 'settings',
};

// True when focus is in a field where typing should suppress shortcuts.
function _isTypingContext(e) {
  const t = e.target;
  if (!t) return false;
  const tag = (t.tagName || '').toLowerCase();
  if (tag === 'input' || tag === 'textarea' || tag === 'select') return true;
  if (t.isContentEditable) return true;
  // Some wrappers carry contenteditable on an ancestor (e.g. note body).
  if (t.closest && t.closest('[contenteditable="true"], [contenteditable=""]')) return true;
  return false;
}

function _disarmGKey() {
  _GKEY.armed = false;
  if (_GKEY.timer) { clearTimeout(_GKEY.timer); _GKEY.timer = null; }
}

function _globalKeyShortcuts(e) {
  // Never hijack typing, never fire alongside a modifier (those belong to
  // the browser or to Cmd/Ctrl+K).
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (_isTypingContext(e)) { _disarmGKey(); return; }

  const key = (e.key || '').toLowerCase();

  // Second key of a g-sequence?
  if (_GKEY.armed) {
    _disarmGKey();
    const view = _GKEY_MAP[key];
    if (view) {
      e.preventDefault();
      try { navTo(view); } catch (_) {}
    }
    return; // whether matched or not, the sequence is consumed
  }

  // First key of a g-sequence.
  if (key === 'g') {
    _GKEY.armed = true;
    _GKEY.timer = setTimeout(_disarmGKey, 1200);
    return;
  }

  // "/" focuses the omnibox search. Some keyboard layouts put "/" behind
  // shift; accept both as long as the resulting character is "/".
  if (e.key === '/') {
    e.preventDefault();
    try {
      const inp = _omniboxInput();
      if (inp) { expandOmnibox(); inp.focus(); inp.select(); }
    } catch (_) {}
    return;
  }

  // "?" toggles the shortcuts help overlay.
  if (e.key === '?') {
    e.preventDefault();
    toggleShortcutsHelp();
    return;
  }

  // Esc closes the help overlay if it's open. We DON'T preventDefault or
  // stop propagation unless the overlay was actually open, so existing
  // per-component Esc handlers (modals, omnibox, menus) keep working.
  if (e.key === 'Escape') {
    const overlay = document.getElementById('shortcuts-help-overlay');
    if (overlay && overlay.classList.contains('show')) {
      e.preventDefault();
      closeShortcutsHelp();
    }
  }
}

// ── Shortcuts help overlay ──────────────────────────────────────────────
// Built lazily on first open so it adds nothing to initial DOM/paint.
function toggleShortcutsHelp() {
  const existing = document.getElementById('shortcuts-help-overlay');
  if (existing && existing.classList.contains('show')) {
    closeShortcutsHelp();
  } else {
    openShortcutsHelp();
  }
}

function openShortcutsHelp() {
  let overlay = document.getElementById('shortcuts-help-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'shortcuts-help-overlay';
    overlay.className = 'shortcuts-help-overlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', 'Keyboard shortcuts');
    overlay.addEventListener('click', (ev) => {
      // Click on the backdrop (not the card) closes.
      if (ev.target === overlay) closeShortcutsHelp();
    });
    const rows = [
      ['/', 'Focus search'],
      ['?', 'Show this help'],
      ['Esc', 'Close this help'],
      ['Ctrl / ⌘ + K', 'Open search'],
      ['g then s', 'Go to Stockroom'],
      ['g then g', 'Go to Groceries'],
      ['g then b', 'Go to Budget'],
      ['g then n', 'Go to Notes'],
      ['g then r', 'Go to Reminders'],
      ['g then v', 'Go to Savings'],
      ['g then p', 'Go to Report'],
      ['g then a', 'Go to Accessibility'],
      ['g then c', 'Go to Account & Security'],
      ['g then t', 'Go to Settings'],
    ];
    const rowsHtml = rows.map(([keys, desc]) => {
      const keyHtml = keys.split(' then ')
        .map(k => `<kbd class="shortcut-kbd">${esc(k)}</kbd>`)
        .join('<span class="shortcut-then">then</span>');
      return `<div class="shortcut-row">
        <div class="shortcut-keys">${keyHtml}</div>
        <div class="shortcut-desc">${esc(desc)}</div>
      </div>`;
    }).join('');
    overlay.innerHTML = `
      <div class="shortcuts-help-card" role="document">
        <div class="shortcuts-help-header">
          <h2 style="font-size:16px;font-weight:700;margin:0"><svg class="icon icon-md" aria-hidden="true"><use href="#i-help-circle"></use></svg> Keyboard shortcuts</h2>
          <button class="shortcuts-help-close" type="button" aria-label="Close" onclick="closeShortcutsHelp()">
            <svg class="icon icon-sm" aria-hidden="true"><use href="#i-x"></use></svg>
          </button>
        </div>
        <div class="shortcuts-help-body">${rowsHtml}</div>
      </div>`;
    document.body.appendChild(overlay);
  }
  // Force reflow then add .show for the transition.
  void overlay.offsetWidth;
  overlay.classList.add('show');
  // Move focus to the close button for keyboard users.
  const closeBtn = overlay.querySelector('.shortcuts-help-close');
  if (closeBtn) { try { closeBtn.focus(); } catch (_) {} }
}

function closeShortcutsHelp() {
  const overlay = document.getElementById('shortcuts-help-overlay');
  if (!overlay) return;
  overlay.classList.remove('show');
}

// ── Outside-click handler: collapse when the user taps away ──
// Without this, the expanded panel stays open until the user explicitly
// dismisses it, which is annoying when they tap a tab or a card behind.
function _omniboxOutsideClick(e) {
  if (!_OMNIBOX.active) return;
  const omni = _omniboxEl();
  if (!omni) return;
  // Use composedPath (captured at event dispatch time) rather than just
  // e.target. Some handlers — workflow-panel buttons, in particular —
  // replace innerHTML synchronously, which detaches the original target
  // before the click finishes bubbling. omni.contains(e.target) then
  // returns false for what was clearly an inside-click. composedPath
  // preserves the original ancestor chain so this case is handled
  // correctly. Older browsers without composedPath fall back to the
  // simple contains() check.
  const path = (typeof e.composedPath === 'function') ? e.composedPath() : null;
  if (path && path.length) {
    if (path.includes(omni)) return;
  } else {
    if (omni.contains(e.target)) return;
  }
  // Don't collapse if the click landed inside any modal — search
  // results lead to modals (note editor, item card, etc.) opening,
  // and those clicks shouldn't trigger a collapse race.
  const modalOpen = document.querySelector('.modal-backdrop.show, .modal-backdrop[style*="display: flex"], .modal-backdrop[style*="display:flex"]');
  if (modalOpen) {
    if (path && path.length) {
      if (path.includes(modalOpen)) return;
    } else if (modalOpen.contains(e.target)) {
      return;
    }
  }
  collapseOmnibox();
}

// ── Init ──
// Wires the global keydown shortcut + outside-click handler. Idempotent.
function initOmnibox() {
  // Auto-grow on resize too (orientation change on mobile).
  if (!_OMNIBOX.autoGrowBound) {
    window.addEventListener('resize', _autoGrowOmnibox);
    _OMNIBOX.autoGrowBound = true;
  }
  document.addEventListener('keydown', _omniboxKeyShortcut, true); // capture phase
  document.addEventListener('click', _omniboxOutsideClick);
  // Tier 4.1 — global keyboard shortcuts (g-prefix navigation, / search, ? help).
  document.addEventListener('keydown', _globalKeyShortcuts);
  // Render initial empty state so the panel isn't blank if focused
  // before any input.
  _renderOmniboxEmpty();
}

// Call init once on DOM ready. The rest of the app's init runs from
// the `init()` function further down — we tag onto DOMContentLoaded
// directly here so the omnibox is wired even if init() bails on an
// error elsewhere.
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initOmnibox);
} else {
  initOmnibox();
}
// ═══════════════════════════════════════════════════════════════════
//  OMNIBOX — Pass 2: Intent detection
// ═══════════════════════════════════════════════════════════════════
// Reads the omnibox input and decides which action buttons make sense.
// Each detected destination produces a state in {disabled, normal,
// primary}. Search is always 'normal' (never disabled, never primary).
//
// Strategy: keyword override wins. If no keyword matches, shape rules
// pick a primary and a set of enabled siblings.
//
// Called from onOmniboxInput after each keystroke (existing handler is
// patched at the bottom of this section). Output goes to button state
// + an intent-hint line above the action row.

const _OMNIBOX_INTENT = {
  // Last computed state, useful for the smart-Enter fallback.
  state: null,
};

// Regex helpers — defined once at module scope to avoid re-compiling.

// Decimal amount: "47.50", "£12", "12.00". Strong Spend signal.
// Whole numbers alone (e.g. "3") are NOT counted because they could be
// quantities. The Spend parser itself accepts whole numbers, but for
// intent detection we want a stronger signal to avoid false positives.
const _RE_DECIMAL_AMOUNT = /(?:£\s*\d+(?:\.\d+)?)|(?:\b\d+\.\d{1,2}\b)/;

// Keyword prefixes — case-insensitive. Match at start of input, followed
// by colon or whitespace. The `\s*` after `:` allows "note:something".
const _KEYWORD_RULES = [
  { re: /^(?:note|n)\s*[:\-]\s*/i,            kind: 'notes' },
  { re: /^(?:remind|reminder|r)\s*[:\-]\s*/i, kind: 'reminders' },
  { re: /^(?:spend|s)\s*[:\-]\s*/i,           kind: 'spend' },
  { re: /^(?:add|stock|stockroom)\s*[:\-]\s*/i, kind: 'stockroom' },
  { re: /^(?:list|grocery|groceries|g)\s*[:\-]\s*/i, kind: 'groceries' },
  { re: /^(?:find|search)\s*[:\-]\s*/i,       kind: 'search-only' },
];

// Returns { primary: kind|null, enabled: Set<kind>, hint: string,
//           strippedText: string }
// `strippedText` is the input with any keyword prefix removed —
// callers that fire the detected action should use this, so
// "note: pick up keys" becomes "pick up keys" in the new note.
function _omniboxDetectIntent(text) {
  const result = {
    primary: null,
    enabled: new Set(['search']), // search is always enabled
    hint: '',
    strippedText: text,
  };
  const trimmed = (text || '').trim();
  if (!trimmed) {
    // Empty input — all enabled, no primary, no hint.
    result.enabled = new Set(['search', 'stockroom', 'groceries', 'reminders', 'notes', 'spend']);
    return result;
  }

  // ── 1. Keyword override ──
  for (const rule of _KEYWORD_RULES) {
    const m = trimmed.match(rule.re);
    if (!m) continue;
    result.strippedText = trimmed.slice(m[0].length);
    if (rule.kind === 'search-only') {
      // 'find:' or 'search:' — only Search makes sense. Everything else greys.
      result.primary = null;
      result.enabled = new Set(['search']);
      result.hint = 'Searching…';
      return result;
    }
    // Add destination as primary; only that + search enabled.
    result.primary = rule.kind;
    result.enabled = new Set(['search', rule.kind]);
    result.hint = _intentHintLabel(rule.kind, true);
    return result;
  }

  // ── 2. Shape detection ──
  const commaCount = (trimmed.match(/,/g) || []).length;
  const newlineCount = (trimmed.match(/\n/g) || []).length;
  const hasDecimalAmount = _RE_DECIMAL_AMOUNT.test(trimmed);
  const wordCount = trimmed.split(/\s+/).filter(Boolean).length;
  const charCount = trimmed.length;

  // 2a. Decimal amount → Spend is primary.
  // Stockroom and Groceries get disabled (amounts don't belong in their
  // input). Notes and Reminders stay disabled too — if the user wanted
  // a note about a price, they'd use the 'note:' keyword.
  if (hasDecimalAmount) {
    result.primary = 'spend';
    result.enabled = new Set(['search', 'spend']);
    result.hint = _intentHintLabel('spend', false);
    return result;
  }

  // 2a-bis. Whole-number amount WITH category/merchant context → Spend.
  // The bare-integer case ("tesco 40 carla", "40 petrol") is ambiguous on
  // shape alone (could be a quantity), so we ask the parser: does it
  // resolve to a known category (via alias) or a remembered merchant?
  // Only if yes do we promote to spend — keeps "buy 3 eggs" out of the
  // spend bucket. Cheap pre-check first: bail if there's no integer at
  // all so we don't run parseQuickAddInput on every keystroke.
  if (commaCount === 0 && newlineCount === 0 && /\b\d+\b/.test(trimmed)) {
    try {
      if (typeof parseQuickAddInput === 'function') {
        const probe = parseQuickAddInput(trimmed);
        const first = probe && probe[0];
        if (first && first.ok && first.categoryId != null) {
          result.primary = 'spend';
          result.enabled = new Set(['search', 'spend']);
          result.hint = _intentHintLabel('spend', false);
          return result;
        }
      }
    } catch (_) { /* parser failure shouldn't break intent detection */ }
  }

  // 2b. Long prose with no commas → Notes (primary) + Reminders enabled.
  // Threshold: more than ~6 words OR more than ~40 chars, AND zero commas.
  // Newlines (multi-line paste) also push toward Notes.
  if (commaCount === 0 && (wordCount > 6 || charCount > 40 || newlineCount > 0)) {
    result.primary = 'notes';
    result.enabled = new Set(['search', 'notes', 'reminders']);
    result.hint = 'Looks like a note';
    return result;
  }

  // 2c. Multiple comma-separated short items → Stockroom (primary),
  // Groceries + Reminders also enabled. This is the "milk, eggs, bread"
  // case — could be any of the three list-like destinations.
  if (commaCount >= 1 || newlineCount >= 1) {
    result.primary = 'stockroom';
    result.enabled = new Set(['search', 'stockroom', 'groceries', 'reminders']);
    result.hint = `${Math.max(commaCount, newlineCount) + 1} items`;
    return result;
  }

  // 2d. Single short word/phrase → all enabled, lean Search (no primary
  // highlighted; user picks). This is the "I just typed yoghurt and want
  // to find it OR add it" state.
  result.enabled = new Set(['search', 'stockroom', 'groceries', 'reminders', 'notes', 'spend']);
  result.hint = '';
  return result;
}

function _intentHintLabel(kind, fromKeyword) {
  const fromKW = fromKeyword ? ' (keyword)' : '';
  switch (kind) {
    case 'stockroom':  return 'Add to Stockroom' + fromKW;
    case 'groceries':  return 'Add to a grocery list' + fromKW;
    case 'reminders':  return 'Add reminders' + fromKW;
    case 'notes':      return 'Create a note' + fromKW;
    case 'spend':      return 'Log spend' + fromKW;
    default:           return '';
  }
}

// Apply a computed intent to the DOM — update button data-primary /
// data-disabled attrs, set the hint line, and persist to _OMNIBOX_INTENT
// for the Enter handler.
function _applyOmniboxIntent(intent) {
  _OMNIBOX_INTENT.state = intent;
  const actions = document.querySelectorAll('#omnibox-actions .omnibox-action');
  actions.forEach(btn => {
    const kind = btn.getAttribute('data-action');
    const enabled = intent.enabled.has(kind);
    const primary = intent.primary === kind;
    btn.toggleAttribute('disabled', !enabled);
    if (!enabled) {
      btn.setAttribute('data-disabled', 'true');
    } else {
      btn.removeAttribute('data-disabled');
    }
    if (primary) {
      btn.setAttribute('data-primary', 'true');
    } else {
      btn.removeAttribute('data-primary');
    }
  });

  // Update hint line (lazy-create if missing — hint container is added
  // by the index.html patch, but be defensive in case of partial deploy).
  let hint = document.getElementById('omnibox-intent-hint');
  if (!hint) {
    const actionsEl = document.getElementById('omnibox-actions');
    if (actionsEl && actionsEl.parentNode) {
      hint = document.createElement('div');
      hint.id = 'omnibox-intent-hint';
      hint.className = 'omnibox-intent-hint';
      actionsEl.parentNode.insertBefore(hint, actionsEl);
    }
  }
  if (hint) {
    if (intent.hint) {
      hint.textContent = intent.hint;
      hint.style.display = '';
    } else {
      hint.textContent = '';
      hint.style.display = 'none';
    }
  }
}

// ── Patch onOmniboxInput to run intent detection ──
// We don't redefine the function — we wrap it. The original (Pass 1) is
// captured, then a new handler runs detection alongside the search call.
// Wrapping avoids touching Pass 1 code, which keeps the rollback story
// simple if Pass 2 needs to be reverted.
const _ORIG_onOmniboxInput = (typeof onOmniboxInput === 'function') ? onOmniboxInput : null;

function onOmniboxInput() {
  // Call the original Pass 1 handler (auto-grow, clear-button refresh,
  // debounced search). If it was somehow missing, gracefully degrade —
  // intent detection still runs.
  if (_ORIG_onOmniboxInput) {
    try { _ORIG_onOmniboxInput.call(this); } catch (err) {
      console.error('Original onOmniboxInput failed:', err);
    }
  }
  // Then run intent detection. Synchronous — cheap regex work, no
  // debounce needed. Updates buttons immediately so the user gets
  // instant feedback as they type.
  try {
    const text = (_omniboxInput()?.value || '');
    const intent = _omniboxDetectIntent(text);
    _applyOmniboxIntent(intent);
  } catch (err) {
    console.error('Omnibox intent detection failed:', err);
  }
}

// ── Patch _omniboxEnterSmart for intent fallback ──
// Pass 1 just jumped to the first result and did nothing on no-results.
// Pass 2: if no results AND an intent was detected, run that action.
const _ORIG_omniboxEnterSmart = (typeof _omniboxEnterSmart === 'function') ? _omniboxEnterSmart : null;

function _omniboxEnterSmart() {
  // If there's a search result, jump to it — same as Pass 1.
  const firstRow = _omniboxResults()?.querySelector('.global-search-row');
  if (firstRow) {
    firstRow.click();
    return;
  }
  // No results — try the detected primary action.
  const state = _OMNIBOX_INTENT.state;
  if (state && state.primary) {
    omniboxAction(state.primary);
    return;
  }
  // No results, no intent — Pass 1 fallback (do nothing).
  // Could toast a hint here but that gets noisy.
}

// ── Patch omniboxAction to use stripped text when keyword present ──
// "note: buy milk" should create a note titled "buy milk", not
// "note: buy milk". The detection function already strips the prefix
// in result.strippedText — we use that when an intent is active.
const _ORIG_omniboxAction = (typeof omniboxAction === 'function') ? omniboxAction : null;

function omniboxAction(kind) {
  // Search always uses raw text (no stripping — user might genuinely
  // be searching for "note:").
  if (kind === 'search') {
    return _ORIG_omniboxAction ? _ORIG_omniboxAction.call(this, kind) : undefined;
  }
  // For add actions: if intent state has a primary matching this kind
  // AND the strippedText differs from raw, use stripped. This handles
  // "note: pick up keys" → action with "pick up keys".
  const state = _OMNIBOX_INTENT.state;
  if (state && state.primary === kind && state.strippedText !== undefined) {
    const raw = _omniboxInput()?.value || '';
    if (state.strippedText !== raw.trim() && state.strippedText !== '') {
      // Temporarily swap input value to the stripped form, fire the
      // original handler, then restore. The handler reads the input's
      // value, so the cleanest swap point is right here.
      const inp = _omniboxInput();
      const original = inp ? inp.value : '';
      if (inp) inp.value = state.strippedText;
      try {
        return _ORIG_omniboxAction ? _ORIG_omniboxAction.call(this, kind) : undefined;
      } finally {
        // Restore. If the action cleared the input (full-handled case),
        // the cleanup already happened — but restoring a stale value
        // would be bad. So we ONLY restore if the input still has our
        // stripped value (i.e. action opened a modal and didn't clear).
        if (inp && inp.value === state.strippedText) {
          inp.value = original;
        }
      }
    }
  }
  // No intent / no stripping needed — straight passthrough.
  return _ORIG_omniboxAction ? _ORIG_omniboxAction.call(this, kind) : undefined;
}

// ── Initial state: run detection once on init so an empty omnibox
// shows the right "all enabled, no primary" state from the start ──
// initOmnibox in Pass 1 already calls _renderOmniboxEmpty. We tag on
// here to apply initial intent (which is just "all enabled").
(function _omniboxPass2InitialState() {
  // Defer to next tick so initOmnibox has run and buttons exist.
  setTimeout(() => {
    try {
      const intent = _omniboxDetectIntent('');
      _applyOmniboxIntent(intent);
    } catch (_) { /* harmless on init */ }
  }, 50);
})();
// ═══════════════════════════════════════════════════════════════════
//  OMNIBOX — Pass 2 FIX
// ═══════════════════════════════════════════════════════════════════
// The previous Pass 2 used a "wrap the original function" pattern which
// fell apart because BOTH function declarations live in the same global
// scope — the second `function onOmniboxInput()` declaration shadows
// the first at parse time, and the `_ORIG_*` captures point at the
// wrapper itself, causing infinite recursion and silent failure.
//
// Fix: replace the broken wrappers with single, merged function
// definitions that combine Pass 1 and Pass 2 behaviour. We assign to
// the names directly (no wrapping) so the bug can't recur.
//
// Also includes the override change: greyed-out action buttons remain
// clickable. The greying is visual guidance only — the user can always
// force an action against the suggestion.

// ── Make all action buttons always clickable ──
// Pass 1's _applyOmniboxIntent set the `disabled` attribute when a
// destination wasn't in the enabled set. Remove that — we keep the
// visual cue (lower opacity via [data-disabled]) but allow clicks.
// We override _applyOmniboxIntent fully here (re-assignment, not wrap).
_applyOmniboxIntent = function _applyOmniboxIntent(intent) {
  _OMNIBOX_INTENT.state = intent;
  const actions = document.querySelectorAll('#omnibox-actions .omnibox-action');
  actions.forEach(btn => {
    const kind = btn.getAttribute('data-action');
    const enabled = intent.enabled.has(kind);
    const primary = intent.primary === kind;
    // KEY CHANGE vs Pass 2 original: never set the `disabled` attribute.
    // The button stays clickable. We use [data-disabled="true"] only as
    // a CSS hook for the dimmed appearance.
    if (!enabled) {
      btn.setAttribute('data-disabled', 'true');
    } else {
      btn.removeAttribute('data-disabled');
    }
    if (primary) {
      btn.setAttribute('data-primary', 'true');
    } else {
      btn.removeAttribute('data-primary');
    }
  });

  // Hint line — same as Pass 2.
  let hint = document.getElementById('omnibox-intent-hint');
  if (!hint) {
    const actionsEl = document.getElementById('omnibox-actions');
    if (actionsEl && actionsEl.parentNode) {
      hint = document.createElement('div');
      hint.id = 'omnibox-intent-hint';
      hint.className = 'omnibox-intent-hint';
      actionsEl.parentNode.insertBefore(hint, actionsEl);
    }
  }
  if (hint) {
    if (intent.hint) {
      hint.textContent = intent.hint;
      hint.style.display = '';
    } else {
      hint.textContent = '';
      hint.style.display = 'none';
    }
  }
};

// ── Replace onOmniboxInput with the merged version ──
// This is the single source of truth for typing handling. Combines
// Pass 1 (auto-grow, clear-btn refresh, debounced search) and Pass 2
// (intent detection).
onOmniboxInput = function onOmniboxInput() {
  const inp = _omniboxInput();
  if (!inp) return;
  // Pass 1 behaviour
  _autoGrowOmnibox();
  _refreshOmniboxClearButton();
  const q = (inp.value || '').trim();
  _OMNIBOX.query = q;
  clearTimeout(_OMNIBOX.debounceTimer);

  // Pass 2 behaviour: run intent detection synchronously (cheap).
  try {
    const intent = _omniboxDetectIntent(inp.value || '');
    _applyOmniboxIntent(intent);
  } catch (err) {
    console.error('Omnibox intent detection failed:', err);
  }

  // Pass 1 behaviour: debounced search.
  if (!q) { _renderOmniboxEmpty(); return; }
  _OMNIBOX.debounceTimer = setTimeout(() => {
    try { _runOmniboxSearch(q); } catch (err) { console.error('Omnibox search failed:', err); }
  }, 120);
};

// ── Replace _omniboxEnterSmart with the merged version ──
// Pass 1: jump to first result; do nothing if no results.
// Pass 2: jump to first result; run detected action if no results.
_omniboxEnterSmart = function _omniboxEnterSmart() {
  const firstRow = _omniboxResults()?.querySelector('.global-search-row');
  if (firstRow) {
    firstRow.click();
    return;
  }
  const state = _OMNIBOX_INTENT.state;
  if (state && state.primary) {
    omniboxAction(state.primary);
    return;
  }
  // No results, no intent — silent no-op (Pass 1 behaviour preserved).
};

// ── Replace omniboxAction with the merged version ──
// Pass 1: route text through add-flow for the chosen destination.
// Pass 2: strip keyword prefix from text when intent matches.
// Plus: this is now the SINGLE definition so no recursion can happen.
omniboxAction = function omniboxAction(kind) {
  const inp = _omniboxInput();
  const rawText = (inp?.value || '').trim();

  // Search always uses raw text — user might literally be searching
  // for "note:" or similar.
  if (kind === 'search') {
    try { inp?.blur(); } catch(_) {}
    return;
  }

  // Empty input check — only for non-search actions.
  if (!rawText) {
    if (typeof toast === 'function') toast('Type something first');
    return;
  }

  // Decide what text to send to the action.
  // If detected intent matches this action AND there's a stripped
  // version (keyword was present), use that. Otherwise use raw.
  let textForAction = rawText;
  const state = _OMNIBOX_INTENT.state;
  if (state && state.primary === kind && typeof state.strippedText === 'string') {
    const stripped = state.strippedText.trim();
    if (stripped) textForAction = stripped;
  }

  switch (kind) {
    case 'stockroom':  return _omniboxAddToStockroom(textForAction);
    case 'groceries':  return _omniboxAddToGroceries(textForAction);
    case 'reminders':  return _omniboxAddToReminders(textForAction);
    case 'notes':      return _omniboxAddToNotes(textForAction);
    case 'spend':      return _omniboxAddToSpend(textForAction);
    default:
      console.warn('Unknown omnibox action:', kind);
  }
};

// ── Recompute initial state ──
// Buttons may have been left in a stale state from the broken Pass 2
// wrappers (e.g. with `disabled` attribute set). Force a fresh
// computation now that the fixed handlers are in place.
(function _omniboxPass2FixInitialState() {
  setTimeout(() => {
    try {
      // Strip any stale `disabled` attributes left over from the
      // broken Pass 2 wrappers.
      document.querySelectorAll('#omnibox-actions .omnibox-action[disabled]').forEach(btn => {
        btn.removeAttribute('disabled');
      });
      const inp = _omniboxInput();
      const intent = _omniboxDetectIntent(inp?.value || '');
      _applyOmniboxIntent(intent);
    } catch (_) { /* harmless on init */ }
  }, 50);
})();
// ═══════════════════════════════════════════════════════════════════
//  OMNIBOX — Pass 3: Inline Spend preview + direct commit
// ═══════════════════════════════════════════════════════════════════
// When intent detection picks `spend` as the primary action, this
// pass renders the parsed transaction chips directly inside the
// omnibox panel (above the action buttons), and rewires the Spend
// button to commit them directly without opening the Spend Quick Add
// modal.
//
// Reuses _renderQuickAddChip (for the chip markup), parseQuickAddInput
// (for parsing) and commitQuickAdd (for actual persistence). All three
// are already factored cleanly in the existing Spend code path — no
// changes needed there.
//
// Layout when spend is primary:
//   [results pane]
//   [omnibox-spend-preview — chips: today, parsed entries]
//   [omnibox-intent-hint — "Log spend"]
//   [action buttons]

// ── Inline preview container management ──
// Lazy-create the preview block inside the omnibox panel. Sits between
// the results pane and the intent hint. Hidden by default; shown only
// when intent === spend.
function _ensureOmniboxSpendPreviewEl() {
  let el = document.getElementById('omnibox-spend-preview');
  if (el) return el;
  const panel = document.getElementById('omnibox-panel');
  if (!panel) return null;
  // Insert before the intent hint if it exists, otherwise before actions.
  const intentHint = document.getElementById('omnibox-intent-hint');
  const actionsEl  = document.getElementById('omnibox-actions');
  const anchor     = intentHint || actionsEl;
  if (!anchor) return null;
  el = document.createElement('div');
  el.id = 'omnibox-spend-preview';
  el.className = 'omnibox-spend-preview';
  el.style.display = 'none';
  panel.insertBefore(el, anchor);
  return el;
}

// Render the spend preview from current input. Called from the merged
// onOmniboxInput handler after intent is computed. If intent is not
// spend, the preview is hidden (and the button reverts to the modal-
// opening behaviour from Pass 1).
function _renderOmniboxSpendPreview() {
  const el = _ensureOmniboxSpendPreviewEl();
  if (!el) return { validCount: 0, totalCount: 0 };

  const state = _OMNIBOX_INTENT.state;
  const isSpendIntent = state && state.primary === 'spend';
  if (!isSpendIntent) {
    el.style.display = 'none';
    el.innerHTML = '';
    return { validCount: 0, totalCount: 0 };
  }

  // Use the stripped text if the user typed "spend: …" — strippedText
  // already trims the keyword. Otherwise raw input.
  const rawInput  = _omniboxInput()?.value || '';
  const sourceTxt = (typeof state.strippedText === 'string' && state.strippedText.trim())
    ? state.strippedText
    : rawInput;

  // Parser handles newlines by treating them as comma separators (same
  // behaviour as confirmQuickAdd). parseQuickAddInput exists in the
  // budget/spend code and is already used by the modal preview.
  if (typeof parseQuickAddInput !== 'function' || typeof _renderQuickAddChip !== 'function') {
    // Spend code not loaded yet — bail quietly. Will retry on next keystroke.
    el.style.display = 'none';
    return { validCount: 0, totalCount: 0 };
  }
  const normalised = sourceTxt.replace(/\n/g, ',');
  const parsed = parseQuickAddInput(normalised);
  const validCount = parsed.filter(p => p.ok && p.amount > 0).length;
  const totalCount = parsed.length;

  if (totalCount === 0) {
    el.style.display = 'none';
    el.innerHTML = '';
    return { validCount, totalCount };
  }

  // Today's date (used at commit time). Shown for transparency — users
  // who want to log spend for a different day should still open the
  // full Spend modal where the date picker lives.
  const today = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });

  // Header + chips + footer summary. The footer count uses validCount
  // so users see "Add 2 of 3" if one entry is unparseable.
  const headerHTML = `<div class="omnibox-spend-preview-header">
    <span class="omnibox-spend-preview-label">Will log on ${_escapeHtml(today)}</span>
  </div>`;
  const chipsHTML  = `<div class="omnibox-spend-preview-chips">${parsed.map(_renderQuickAddChip).join('')}</div>`;
  el.innerHTML = headerHTML + chipsHTML;
  el.style.display = '';
  return { validCount, totalCount };
}

// ── Commit handler: turn parsed entries into transactions, no modal ──
// Mirrors confirmQuickAdd but reads from the omnibox input and uses
// today's date implicitly.
async function _omniboxCommitSpend() {
  if (typeof parseQuickAddInput !== 'function' || typeof commitQuickAdd !== 'function') {
    if (typeof toast === 'function') toast('Spend code not loaded');
    return;
  }
  // Bail out if there are no budget categories yet — same gate the
  // modal-opening flow uses. Drop the user into the setup flow instead.
  if (typeof getActiveBudgetCategories === 'function' && getActiveBudgetCategories().length === 0) {
    if (typeof openBudgetSetupModal === 'function') {
      openBudgetSetupModal();
    } else if (typeof toast === 'function') {
      toast('Set up budget categories first');
    }
    return;
  }

  const state = _OMNIBOX_INTENT.state;
  const rawInput = _omniboxInput()?.value || '';
  const sourceTxt = (state && state.primary === 'spend' &&
                    typeof state.strippedText === 'string' && state.strippedText.trim())
    ? state.strippedText
    : rawInput;
  const normalised = sourceTxt.replace(/\n/g, ',');
  const parsed = parseQuickAddInput(normalised).filter(p => p.ok && p.amount > 0);
  if (parsed.length === 0) {
    if (typeof toast === 'function') toast('Nothing to add — needs an amount');
    return;
  }
  try {
    const created = await commitQuickAdd(parsed, { date: null }); // null → today
    if (typeof toast === 'function') {
      toast(`Added ${created.length} transaction${created.length === 1 ? '' : 's'}`);
    }
    // Refresh budget views if currently visible — matches what
    // confirmQuickAdd does at the end of its handler.
    if (typeof _currentView !== 'undefined' && _currentView === 'budget') {
      if (typeof _budgetActivePanel !== 'undefined') {
        if (_budgetActivePanel === 'spend' && typeof renderBudgetSpend === 'function') {
          renderBudgetSpend();
        } else if (_budgetActivePanel === 'dashboard' && typeof renderBudgetDashboard === 'function') {
          renderBudgetDashboard();
        }
      }
    }
    // Clear and collapse — full handled, no follow-up modal needed.
    if (typeof clearOmnibox === 'function') clearOmnibox();
    if (typeof collapseOmnibox === 'function') collapseOmnibox();
  } catch (err) {
    console.error('_omniboxCommitSpend failed:', err);
    if (typeof toast === 'function') toast('Could not add — please try again');
  }
}

// ── Override the Spend branch in omniboxAction ──
// Pass 2-fix already redefined omniboxAction as a single direct function.
// We redefine it again here to insert inline-commit behaviour for spend,
// keeping all other branches unchanged. No wrapping pattern this time —
// just a full reassignment with the spend case substituted.
omniboxAction = function omniboxAction(kind) {
  const inp = _omniboxInput();
  const rawText = (inp?.value || '').trim();

  // Search: blur to dismiss keyboard, leave state alone.
  if (kind === 'search') {
    try { inp?.blur(); } catch (_) {}
    return;
  }

  // Empty input check for non-search actions.
  if (!rawText) {
    if (typeof toast === 'function') toast('Type something first');
    return;
  }

  // Keyword-stripped text for the matching action (Pass 2 behaviour).
  let textForAction = rawText;
  const state = _OMNIBOX_INTENT.state;
  if (state && state.primary === kind && typeof state.strippedText === 'string') {
    const stripped = state.strippedText.trim();
    if (stripped) textForAction = stripped;
  }

  switch (kind) {
    case 'stockroom':  return _omniboxAddToStockroom(textForAction);
    case 'groceries':  return _omniboxAddToGroceries(textForAction);
    case 'reminders':  return _omniboxAddToReminders(textForAction);
    case 'notes':      return _omniboxAddToNotes(textForAction);

    case 'spend': {
      // Pass 3 change: if intent has been computed and there are valid
      // parsed entries, commit inline. Otherwise fall back to opening
      // the modal — handles the case where the user clicked Spend on
      // input that wasn't detected as spend (e.g. force-clicked the
      // dimmed Spend button on "milk, eggs" — opening the modal lets
      // them recover by editing in the full Spend UI).
      const haveValid = state && state.primary === 'spend';
      if (haveValid && typeof _omniboxCommitSpend === 'function') {
        return _omniboxCommitSpend();
      }
      // Fallback: pre-fill modal (Pass 1 behaviour for non-spend intent).
      return _omniboxAddToSpend(textForAction);
    }

    default:
      console.warn('Unknown omnibox action:', kind);
  }
};

// ── Hook the preview into onOmniboxInput ──
// Pass 2-fix already wrote onOmniboxInput as a direct assignment. We
// redefine it here to add the preview render call after intent
// detection, before the debounced search.
onOmniboxInput = function onOmniboxInput() {
  const inp = _omniboxInput();
  if (!inp) return;
  _autoGrowOmnibox();
  _refreshOmniboxClearButton();
  const q = (inp.value || '').trim();
  _OMNIBOX.query = q;
  clearTimeout(_OMNIBOX.debounceTimer);

  // Intent detection — synchronous.
  try {
    const intent = _omniboxDetectIntent(inp.value || '');
    _applyOmniboxIntent(intent);
  } catch (err) {
    console.error('Omnibox intent detection failed:', err);
  }

  // Pass 3 addition: render inline spend preview if intent is spend.
  // This is cheap (just re-runs the parser + DOM update). Done synchronously
  // so the preview updates as the user types each digit of an amount.
  try { _renderOmniboxSpendPreview(); } catch (err) {
    console.error('Omnibox spend preview failed:', err);
  }

  // Debounced search.
  if (!q) { _renderOmniboxEmpty(); return; }
  _OMNIBOX.debounceTimer = setTimeout(() => {
    try { _runOmniboxSearch(q); } catch (err) { console.error('Omnibox search failed:', err); }
  }, 120);
};

// ── Clear the preview when the omnibox collapses or clears ──
// The preview is rendered into a static container; if we don't clear
// it on collapse, the next time the user opens the omnibox they see
// stale chips from a previous session.
//
// We replace clearOmnibox with a merged version (no wrapping —
// avoids the hoisting/recursion trap that bit Pass 2). The Pass 1
// behaviour is reproduced inline, then the preview cleanup added.
clearOmnibox = function clearOmnibox() {
  const inp = _omniboxInput();
  if (inp) { inp.value = ''; }
  _OMNIBOX.query = '';
  clearTimeout(_OMNIBOX.debounceTimer);
  _renderOmniboxEmpty();
  _refreshOmniboxClearButton();
  _autoGrowOmnibox();
  // Pass 3 addition: clear stale spend preview chips.
  const el = document.getElementById('omnibox-spend-preview');
  if (el) { el.innerHTML = ''; el.style.display = 'none'; }
  try { inp?.focus(); } catch (_) {}
};

// ── Initial render so the preview block is set up correctly ──
// Defer to next tick so the panel DOM is in place.
(function _omniboxPass3InitialState() {
  setTimeout(() => {
    try {
      _ensureOmniboxSpendPreviewEl();
      // Recompute preview against current input (likely empty on init).
      _renderOmniboxSpendPreview();
    } catch (_) { /* harmless on init */ }
  }, 60);
})();
// ═══════════════════════════════════════════════════════════════════
//  OMNIBOX — Pass 3 FIX
// ═══════════════════════════════════════════════════════════════════
// Bug: clicking the clear-X cleared the input and preview, but left
// the action buttons in whatever state intent detection had set —
// so Spend stayed gold-highlighted even though the input was empty.
//
// Fix: include a fresh intent detection pass inside clearOmnibox so
// the button states return to the "empty input = all enabled, no
// primary" baseline.
//
// Replaces clearOmnibox via direct assignment (not function-decl
// wrapping — the Pass 2 bug taught us why).

clearOmnibox = function clearOmnibox() {
  const inp = _omniboxInput();
  if (inp) { inp.value = ''; }
  _OMNIBOX.query = '';
  clearTimeout(_OMNIBOX.debounceTimer);
  _renderOmniboxEmpty();
  _refreshOmniboxClearButton();
  _autoGrowOmnibox();
  // Clear stale spend preview chips (Pass 3 behaviour).
  const previewEl = document.getElementById('omnibox-spend-preview');
  if (previewEl) { previewEl.innerHTML = ''; previewEl.style.display = 'none'; }
  // Pass 3 FIX: re-run intent detection against the empty input so
  // button states reset to the baseline (all enabled, no primary,
  // no hint). Without this the buttons keep their last detected
  // state from before the clear.
  try {
    const intent = _omniboxDetectIntent('');
    _applyOmniboxIntent(intent);
  } catch (_) { /* harmless */ }
  try { inp?.focus(); } catch (_) {}
};
// ═══════════════════════════════════════════════════════════════════
//  OMNIBOX — Pass 4: Mobile 3×2 button grid + darkened backdrop
// ═══════════════════════════════════════════════════════════════════
// Two related mobile-only enhancements:
//
//   1. Action button row becomes a 3×2 grid mirroring the tab bar
//      (icon above label, equal cells). Source order in HTML stays
//      put — visual order is controlled by CSS `order` on each button.
//      Desktop layout (horizontal pill row) is unchanged.
//
//   2. When the omnibox is expanded on mobile, a dark backdrop appears
//      over the content beneath the panel. Tapping the backdrop
//      collapses the panel but preserves the typed text (so the user
//      can resume by tapping the input again).
//
// All CSS lives in styles.css; this JS handles only:
//   - Inserting the backdrop element into the DOM on init
//   - Wiring its tap handler to collapseOmnibox()
//   - Toggling its visibility from expand/collapse functions

// ── Backdrop element management ──
// Single backdrop element appended once on init. Hidden by default;
// shown when omnibox is expanded on mobile (CSS handles the media-query
// gating so desktop never sees it). z-index sits below the omnibox
// panel (which is z:95) but above the rest of the app (typical content
// z is 0–80).
function _ensureOmniboxBackdrop() {
  let el = document.getElementById('omnibox-backdrop');
  if (el) return el;
  el = document.createElement('div');
  el.id = 'omnibox-backdrop';
  el.className = 'omnibox-backdrop';
  el.setAttribute('aria-hidden', 'true');
  // Tap collapses but keeps the input text — exactly the "I want to see
  // the page again but not lose my typing" affordance the user asked
  // for. collapseOmnibox already preserves input value (it just hides
  // the panel and blurs the input).
  el.addEventListener('click', () => {
    if (typeof collapseOmnibox === 'function') collapseOmnibox();
  });
  // Append at body level (NOT inside #omnibox) so it can cover all
  // page content regardless of stacking context.
  document.body.appendChild(el);
  return el;
}

// Show/hide the backdrop. Called from expand/collapse handlers below.
// The visible state is driven by a CSS class so we can transition
// opacity smoothly via the stylesheet.
function _setOmniboxBackdropVisible(visible) {
  const el = _ensureOmniboxBackdrop();
  if (!el) return;
  if (visible) {
    el.classList.add('visible');
  } else {
    el.classList.remove('visible');
  }
}

// ── Reassign expandOmnibox / collapseOmnibox to manage the backdrop ──
// Same pattern as previous passes: direct reassignment (no wrapping
// function-declared names) to dodge the hoisting trap from Pass 2.
// We reproduce the Pass 1 body of each function and add backdrop calls.

expandOmnibox = function expandOmnibox() {
  const omni = _omniboxEl();
  if (!omni) return;
  omni.setAttribute('data-state', 'expanded');
  _OMNIBOX.active = true;
  document.body.classList.add('omnibox-expanded');
  const collapseBtn = document.getElementById('omnibox-collapse-btn');
  if (collapseBtn) collapseBtn.style.display = '';
  _refreshOmniboxClearButton();
  // Pass 4 addition: show the dark backdrop on mobile.
  _setOmniboxBackdropVisible(true);
};

collapseOmnibox = function collapseOmnibox() {
  const omni = _omniboxEl();
  if (!omni) return;
  omni.setAttribute('data-state', 'collapsed');
  _OMNIBOX.active = false;
  document.body.classList.remove('omnibox-expanded');
  const collapseBtn = document.getElementById('omnibox-collapse-btn');
  if (collapseBtn) collapseBtn.style.display = 'none';
  try { _omniboxInput()?.blur(); } catch (_) {}
  // Pass 4 addition: hide the dark backdrop.
  _setOmniboxBackdropVisible(false);
  // Reset search filter flags so the next expand starts with deleted /
  // archived hidden again. User has to explicitly opt in each session.
  if (typeof _GLOBAL_SEARCH !== 'undefined' && _GLOBAL_SEARCH) {
    _GLOBAL_SEARCH.includeArchived = false;
    _GLOBAL_SEARCH.includeDeleted  = false;
  }
  // Reset the order-workflow panel state so the next "order" type-in
  // starts fresh at the chooser stage.
  if (typeof _OMNIBOX_ORDER !== 'undefined' && _OMNIBOX_ORDER) {
    _OMNIBOX_ORDER.filter = null;
    if (_OMNIBOX_ORDER.rows) _OMNIBOX_ORDER.rows.clear();
  }
};

// ── Init: insert backdrop element so it's ready before first expand ──
// Deferred to next tick to keep init order safe against partial DOM.
(function _omniboxPass4Init() {
  setTimeout(() => {
    try { _ensureOmniboxBackdrop(); } catch (_) {}
  }, 60);
})();
